INSERT INTO "public"."labo" ("id", "titre", "year", "is_universal", "notoriete", "description", "type", "region", "status", "image_prompt", "created_at", "processed_at", "error_log", "validation_notes", "illustration_url") VALUES
	(233, 'Assassinat de Jean-Paul Marat par Charlotte Corday', 1793, false, NULL, 'Le 13 juillet 1793, Charlotte Corday poignarde le journaliste révolutionnaire Jean-Paul Marat dans sa baignoire médicinale à Paris.', NULL, NULL, 'pending', NULL, '2026-03-04 07:23:29.975576+00', NULL, NULL, NULL, ''),
	(234, 'Adoption de la Constitution de l''An I', 1793, false, NULL, 'Le 24 juin 1793, la Convention nationale adopte la Constitution montagnarde, la plus démocratique de l''histoire française, bien qu''elle ne soit jamais appliquée en raison de la guerre.', NULL, NULL, 'pending', NULL, '2026-03-04 07:23:29.993574+00', NULL, NULL, NULL, ''),
	(235, 'Instauration de la Terreur par décret', 1793, false, NULL, 'Le 5 septembre 1793, la Convention nationale décrète que ''la terreur est à l''ordre du jour'', légitimant les exécutions massives d''opposants à la République.', NULL, NULL, 'pending', NULL, '2026-03-04 07:23:30.003352+00', NULL, NULL, NULL, 'http://127.0.0.1:54321/storage/v1/object/public/evenements-image/evt_235_instauration_de_la_terreur_par_decret_1772270380007.webp'),
	(236, 'Victoire de Marengo', 1800, false, NULL, 'Le 14 juin 1800, Bonaparte remporte une victoire décisive contre les Autrichiens en Italie du Nord. Cette bataille renforce considérablement sa légitimité politique en France.', NULL, NULL, 'pending', NULL, '2026-03-04 07:23:30.013846+00', NULL, NULL, NULL, 'http://127.0.0.1:54321/storage/v1/object/public/evenements-image/chambre_noire_victoire_de_marengo_1772265698552.webp'),
	(237, 'Prise de la Bastille par les Parisiens', 1789, false, NULL, 'Le 14 juillet 1789, des émeutiers parisiens s''emparent de la forteresse royale de la Bastille, symbole de l''absolutisme royal. Cet événement marque le début de la Révolution française.', NULL, NULL, 'pending', NULL, '2026-03-04 07:23:30.022465+00', NULL, NULL, NULL, 'http://127.0.0.1:54321/storage/v1/object/public/evenements-image/evt_237_prise_de_la_bastille_par_les_parisiens_1772270404327.webp'),
	(238, 'Déclaration des Droits de l''Homme et du Citoyen', 1789, false, NULL, 'Le 26 août 1789, l''Assemblée nationale constituante adopte la Déclaration des Droits de l''Homme et du Citoyen. Ce texte fondamental proclame liberté, égalité et souveraineté nationale.', NULL, NULL, 'pending', NULL, '2026-03-04 07:23:30.033373+00', NULL, NULL, NULL, 'http://127.0.0.1:54321/storage/v1/object/public/evenements-image/evt_238_declaration_des_droits_de_l_homme_et_du__1772268991860.webp'),
	(239, 'Fondation de l''Estado da India par le Portugal', 1505, false, NULL, 'Le Portugal établit officiellement l''Estado da India le 27 mars 1505, un empire commercial maritime administrant ses comptoirs en Afrique orientale et en Asie. Francisco de Almeida en devient le premier vice-roi.', NULL, NULL, 'pending', NULL, '2026-03-04 07:23:30.042255+00', NULL, NULL, NULL, 'http://127.0.0.1:54321/storage/v1/object/public/evenements-image/evt_239_fondation_de_l_estado_da_india_par_le_po_1772268994377.webp'),
	(240, 'Conquête de Goa par Afonso de Albuquerque', 1510, false, NULL, 'Le 25 novembre 1510, Afonso de Albuquerque s''empare de Goa sur la côte ouest de l''Inde, en faisant la capitale de l''empire portugais en Orient. Cette ville restera possession portugaise jusqu''en 1961.', NULL, NULL, 'pending', NULL, '2026-03-04 07:23:30.050838+00', NULL, NULL, NULL, 'http://127.0.0.1:54321/storage/v1/object/public/evenements-image/evt_240_conquete_de_goa_par_afonso_de_albuquerqu_1772268981458.webp'),
	(241, 'Prise de Malacca par les Portugais', 1511, false, NULL, 'Le 24 juillet 1511, Afonso de Albuquerque conquiert Malacca, verrou stratégique du commerce des épices en Asie du Sud-Est. Cette victoire donne au Portugal le contrôle du passage vers les îles aux épices.', NULL, NULL, 'pending', NULL, '2026-03-04 07:23:30.061076+00', NULL, NULL, NULL, 'http://127.0.0.1:54321/storage/v1/object/public/evenements-image/evt_241_prise_de_malacca_par_les_portugais_1772270416211.webp'),
	(242, 'Mort de Vasco de Gama à Cochin', 1524, false, NULL, 'Le 24 décembre 1524, Vasco de Gama meurt à Cochin (Inde) lors de son troisième voyage, alors qu''il venait d''être nommé vice-roi des Indes. Il est enterré en Inde avant que sa dépouille ne soit rapatriée au Portugal.', NULL, NULL, 'pending', NULL, '2026-03-04 07:23:30.07015+00', NULL, NULL, NULL, 'http://127.0.0.1:54321/storage/v1/object/public/evenements-image/evt_242_mort_de_vasco_de_gama_a_cochin_1772270392967.webp'),
	(283, 'Assemblage du module Unity de l''ISS par la navette Endeavour', 1998, false, NULL, 'Le 6 décembre 1998, la navette Endeavour emporte le module américain Unity et l''assemble à Zarya, formant le premier nœud habitable de l''ISS.', 'L''Ère Spatiale et la Conquête de l''Espace', '', 'READY_FOR_IMAGE', 'A breathtaking scene depicting the Space Shuttle Endeavour docked in low Earth orbit, with the American Unity module being carefully attached to the Zarya module of the International Space Station. Astronauts in bright orange spacesuits are visible outside the shuttle, focused on their task, while the vastness of space serves as a backdrop, dotted with distant stars. The Earth is partially illuminated below, casting a soft blue glow that highlights the intricate details of the modules. The shuttle’s metallic surface reflects sunlight, creating a shimmering effect. The atmosphere is tense yet exhilarating, capturing the monumental moment of assembly in the history of space exploration. Photorealistic, cinematic lighting, highly detailed, 8k resolution.', '2026-03-04 07:23:47.114109+00', NULL, NULL, NULL, ''),
	(284, 'Arrivée du premier équipage permanent à bord de l''ISS', 2000, false, NULL, 'Le 2 novembre 2000, l''équipage Expedition 1 composé de Bill Shepherd et des cosmonautes Gidzenko et Krikalev s''installe à bord de l''ISS, inaugurant une présence humaine continue en orbite.', 'L''Ère Spatiale et la Conquête de l''Espace', '', 'READY_FOR_IMAGE', 'Inside the International Space Station, three astronauts – Commander Bill Shepherd, Russian cosmonaut Sergei Krikalev, and flight engineer Yuri Gidzenko – are seen in their vibrant, bulky space suits, adorned with patches representing their missions. The interior is filled with various scientific equipment and panels, illuminated by soft, ambient lighting that enhances the metallic surfaces. The crew members are engaged in conversation, with expressions of excitement and determination, as they initiate the first permanent human presence in orbit. The view through the large windows showcases the stunning curvature of the Earth below, bathed in the blue glow of the atmosphere. The scene captures a moment of historical significance, reflecting the spirit of exploration and cooperation in space. photorealistic documentary photo, cinematic lighting, highly detailed, 8k resolution.', '2026-03-04 07:23:47.114109+00', NULL, NULL, NULL, ''),
	(302, 'Départ de la 8e croisade depuis Aigues-Mortes', 1270, false, NULL, 'Le 1er juillet 1270, Louis IX appareille une nouvelle fois d''Aigues-Mortes, lançant la huitième croisade avec pour destination la Tunisie.', 'Les Croisades en Terre Sainte', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.114109+00', NULL, NULL, NULL, ''),
	(285, 'Désorbitage et chute de la station Mir', 2001, false, NULL, 'Le 23 mars 2001, la station spatiale russe Mir est volontairement désorbité après 15 ans de service, ses débris se dispersant dans l''océan Pacifique Sud.', 'L''Ère Spatiale et la Conquête de l''Espace', '', 'READY_FOR_IMAGE', 'A dramatic scene capturing the re-entry of the Russian space station Mir into the Earth''s atmosphere, with fiery debris breaking apart in the sky. The background features a stunning view of the South Pacific Ocean, with sunlight glinting off the waves below. The atmosphere is tense and dramatic, showcasing the moment of destruction with vibrant orange and red flames contrasting against the deep blue of the ocean. The image includes silhouettes of amazed onlookers on a distant beach, dressed in early 2000s casual clothing, gazing up in awe at the spectacle. The composition emphasizes the vastness of the ocean and sky, highlighting the scale of the event. Photorealistic documentary photo, cinematic lighting, highly detailed, 8k resolution.', '2026-03-04 07:23:47.114109+00', NULL, NULL, NULL, ''),
	(286, 'Lancement de Sergei Krikalev pour son premier séjour sur Mir', 1991, false, NULL, 'Le 18 mai 1991, Sergei Krikalev part pour Mir et se retrouvera bloqué en orbite lors de la dissolution de l''URSS, passant 311 jours dans l''espace, symbole de la transition spatiale post-soviétique.', 'L''Ère Spatiale et la Conquête de l''Espace', '', 'READY_FOR_IMAGE', 'Launch of Sergei Krikalev on his first stay aboard Mir, set on May 18, 1991. The scene captures a dramatic moment at the launch site, with Krikalev in a classic Soviet-era space suit, featuring intricate details and a reflective visor. The background showcases the towering launch pad with the Soyuz rocket, surrounded by technicians and engineers in 1990s Soviet uniforms, anxiously monitoring the countdown. The atmosphere is tense, filled with a mix of hope and uncertainty, as sunlight breaks through scattered clouds, illuminating the scene with a golden hue. The image conveys a sense of historical significance, capturing the transition of space exploration during the dissolution of the USSR. Photorealistic documentary photo, cinematic lighting, highly detailed, 8k resolution.', '2026-03-04 07:23:47.114109+00', NULL, NULL, NULL, ''),
	(287, 'Première sortie extravéhiculaire conjointe américano-russe', 1992, false, NULL, 'Le 9 juillet 1992, des astronautes américains et russes effectuent ensemble une sortie extravéhiculaire lors de la mission STS-49, préfigurant la coopération future sur l''ISS.', 'L''Ère Spatiale et la Conquête de l''Espace', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.114109+00', NULL, NULL, NULL, ''),
	(288, 'Prise de Jérusalem par Saladin', 1187, false, NULL, 'Le 2 octobre 1187, Saladin, sultan ayyoubide, reprend Jérusalem aux croisés après 88 ans de domination chrétienne. La ville tombe après un siège de deux semaines, bouleversant l''Occident chrétien.', 'Les Croisades en Terre Sainte', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.114109+00', NULL, NULL, NULL, ''),
	(289, 'Bataille de Hattin', 1187, false, NULL, 'Le 4 juillet 1187, Saladin écrase l''armée des croisés près du lac de Tibériade. Cette défaite décisive ouvre la voie à la reconquête musulmane de la Terre Sainte.', 'Les Croisades en Terre Sainte', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.114109+00', NULL, NULL, NULL, ''),
	(291, 'Noyade de Frédéric Barberousse', 1190, false, NULL, 'Le 10 juin 1190, l''empereur germanique Frédéric Ier Barberousse se noie dans le fleuve Saleph en Anatolie. Sa mort provoque la désintégration de la puissante armée allemande de la croisade.', 'Les Croisades en Terre Sainte', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.114109+00', NULL, NULL, NULL, ''),
	(292, 'Massacre des prisonniers musulmans d''Acre par Richard Cœur de Lion', 1191, false, NULL, 'Le 20 août 1191, Richard Ier d''Angleterre fait exécuter environ 2 700 prisonniers musulmans devant Acre. Cet acte brutal est justifié par l''échec des négociations avec Saladin.', 'Les Croisades en Terre Sainte', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.114109+00', NULL, NULL, NULL, ''),
	(293, 'Capture de Richard Cœur de Lion par le duc d''Autriche', 1192, false, NULL, 'Le 21 décembre 1192, Richard Ier d''Angleterre est capturé près de Vienne par le duc Léopold V d''Autriche lors de son retour de croisade. Il sera emprisonné et libéré contre une rançon colossale.', 'Les Croisades en Terre Sainte', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.114109+00', NULL, NULL, NULL, ''),
	(294, 'Mort de Saladin à Damas', 1193, false, NULL, 'Le 4 mars 1193, Saladin, sultan d''Égypte et de Syrie, meurt à Damas d''une fièvre typhoïde à l''âge de 55 ans. Sa mort fragilise l''empire ayyoubide qu''il avait unifié.', 'Les Croisades en Terre Sainte', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.114109+00', NULL, NULL, NULL, ''),
	(295, 'Lancement officiel de la Quatrième Croisade par le pape Innocent III', 1202, false, NULL, 'En août 1202, les croisés se rassemblent à Venise pour embarquer vers la Terre Sainte, marquant le début de la Quatrième Croisade.', 'Les Croisades en Terre Sainte', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.114109+00', NULL, NULL, NULL, ''),
	(296, 'Signature du traité entre les croisés et Venise pour le transport maritime', 1201, false, NULL, 'En avril 1201, les envoyés des croisés signent avec le doge Enrico Dandolo un accord prévoyant le transport de 33 500 hommes vers l''Égypte.', 'Les Croisades en Terre Sainte', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.114109+00', NULL, NULL, NULL, ''),
	(297, 'Prise de Zara par les croisés au profit de Venise', 1202, false, NULL, 'Le 24 novembre 1202, les croisés s''emparent de la ville chrétienne de Zara (Dalmatie) pour rembourser leur dette envers Venise, provoquant leur excommunication.', 'Les Croisades en Terre Sainte', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.114109+00', NULL, NULL, NULL, ''),
	(298, 'Fuite de l''empereur byzantin Alexis III d''Ange de Constantinople', 1203, false, NULL, 'Le 17 juillet 1203, l''empereur Alexis III abandonne le trône et fuit Constantinople face à la pression des croisés, laissant la ville sans défense.', 'Les Croisades en Terre Sainte', '', 'READY_FOR_IMAGE', 'A dramatic scene capturing the moment Byzantine Emperor Alexios III flees Constantinople on July 17, 1203. The emperor, dressed in lavish, richly embroidered robes of deep purple and gold, is shown hastily departing from the grand palace. His expression is one of panic and regret as he looks back at the city. Surrounding him are frightened noblemen and soldiers in traditional Byzantine armor, their ornate helmets glinting in the fading light. The backdrop features the magnificent architecture of Constantinople, with its towering domes and intricate mosaics, bathed in the warm hues of a setting sun. The atmosphere is tense and chaotic, with shadows stretching across the cobblestone streets. The scene conveys a sense of urgency and despair, emphasizing the historical significance of the moment. photorealistic, cinematic lighting, highly detailed, 8k resolution, historical painting.', '2026-03-04 07:23:47.114109+00', NULL, NULL, NULL, ''),
	(299, 'Couronnement d''Alexis IV comme co-empereur de Byzance', 1203, false, NULL, 'Le 1er août 1203, Alexis IV est couronné co-empereur byzantin aux côtés de son père Isaac II, grâce au soutien militaire des croisés.', 'Les Croisades en Terre Sainte', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.114109+00', NULL, NULL, NULL, ''),
	(300, 'Assassinat d''Alexis IV par Alexis Doukas Murzuphle', 1204, false, NULL, 'Le 8 février 1204, Alexis IV est étranglé par Alexis Doukas, dit Murzuphle, qui s''empare du trône byzantin et rompt les accords avec les croisés.', 'Les Croisades en Terre Sainte', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.114109+00', NULL, NULL, NULL, ''),
	(301, 'Défaite des croisés à la bataille de La Mansourah', 1250, false, NULL, 'Le 8 février 1250, l''armée de Louis IX subit une lourde défaite à La Mansourah ; le frère du roi, Robert d''Artois, y trouve la mort.', 'Les Croisades en Terre Sainte', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.114109+00', NULL, NULL, NULL, ''),
	(303, 'Débarquement des croisés devant Carthage', 1270, false, NULL, 'Le 18 juillet 1270, l''armée de Louis IX débarque sur les ruines de Carthage, près de Tunis, pour tenter de convertir ou soumettre le sultan hafside.', 'Les Croisades en Terre Sainte', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.114109+00', NULL, NULL, NULL, ''),
	(304, 'Premier service postal aérien régulier aux États-Unis', 1918, false, NULL, 'Le 15 mai 1918, les États-Unis inaugurent leur premier service de courrier aérien régulier entre Washington et New York. Ce service préfigure le développement de l''aviation commerciale.', 'L''Aube de l''Aviation et la Conquête des Airs', '', 'READY_FOR_IMAGE', 'A busy airfield in 1918 during the early morning light, showcasing a vintage biplane taking off with a trail of smoke behind it. In the foreground, a group of excited postal workers in period-appropriate uniforms, complete with caps and leather jackets, are gathered around a wooden crate labeled "MAIL". One worker is tossing a package into the plane while others cheer on. In the background, the silhouette of Washington D.C. can be seen, with the Capitol building peeking through the soft morning mist. The atmosphere is filled with anticipation and the spirit of innovation. The scene captures the hustle and bustle of this historic moment, emphasizing the groundbreaking nature of airmail service. Photorealistic documentary photo, cinematic lighting, highly detailed, 8k resolution.', '2026-03-04 07:23:47.114109+00', NULL, NULL, NULL, ''),
	(305, 'Première traversée de l''Atlantique Nord sans escale', 1919, false, NULL, 'Le 14 juin 1919, John Alcock et Arthur Brown relient Terre-Neuve à l''Irlande en 16 heures à bord d''un Vickers Vimy. Cet exploit ouvre la voie aux liaisons transatlantiques aériennes.', 'L''Aube de l''Aviation et la Conquête des Airs', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.114109+00', NULL, NULL, NULL, ''),
	(306, 'Premier vol solo sans escale de New York à Paris (Lindbergh)', 1927, false, NULL, 'Le 21 mai 1927, Charles Lindbergh atterrit au Bourget après 33 heures de vol à bord du Spirit of St. Louis. Il devient le premier pilote à relier seul New York à Paris sans escale.', 'L''Aube de l''Aviation et la Conquête des Airs', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.114109+00', NULL, NULL, NULL, ''),
	(307, 'Inauguration de la première ligne commerciale transatlantique par dirigeable (Hindenburg)', 1936, false, NULL, 'Le 31 mars 1936, le dirigeable Hindenburg effectue son premier vol officiel, inaugurant une liaison régulière entre l''Allemagne et les États-Unis. Il symbolise l''apogée de l''ère des zeppelins.', 'L''Aube de l''Aviation et la Conquête des Airs', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.114109+00', NULL, NULL, NULL, ''),
	(308, 'Premier vol d''un avion à réaction (Heinkel He 178)', 1939, false, NULL, 'Le 27 août 1939, le Heinkel He 178 effectue le premier vol propulsé uniquement par un moteur à réaction. Cet essai en Allemagne marque le début de l''ère des avions à réaction.', 'L''Aube de l''Aviation et la Conquête des Airs', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.114109+00', NULL, NULL, NULL, ''),
	(309, 'Franchissement du mur du son par Chuck Yeager', 1947, false, NULL, 'Le 14 octobre 1947, le pilote américain Chuck Yeager dépasse la vitesse du son à bord du Bell X-1 au-dessus du désert de Mojave. Cet exploit ouvre l''ère de l''aviation supersonique.', 'L''Aube de l''Aviation et la Conquête des Airs', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.114109+00', NULL, NULL, NULL, ''),
	(310, 'Premier vol commercial du Comet, premier avion de ligne à réaction', 1952, false, NULL, 'Le 2 mai 1952, le De Havilland Comet effectue son premier vol commercial entre Londres et Johannesburg. Il devient le premier avion de ligne à réaction en service régulier dans le monde.', 'L''Aube de l''Aviation et la Conquête des Airs', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.114109+00', NULL, NULL, NULL, ''),
	(311, 'Premier vol du Boeing 747, premier avion gros porteur', 1969, false, NULL, 'Le 9 février 1969, le Boeing 747 effectue son vol inaugural depuis Everett, dans l''État de Washington. Surnommé ''Jumbo Jet'', il révolutionne le transport aérien de masse.', 'L''Aube de l''Aviation et la Conquête des Airs', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.114109+00', NULL, NULL, NULL, ''),
	(312, 'Premier bombardement aérien de l''histoire en temps de guerre', 1911, false, NULL, 'Le 1er novembre 1911, le lieutenant italien Giulio Gavotti lâche à la main quatre grenades depuis son avion sur des troupes ottomanes en Libye. C''est le premier bombardement aérien militaire de l''histoire.', 'L''Aube de l''Aviation et la Conquête des Airs', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.114109+00', NULL, NULL, NULL, ''),
	(313, 'Premier engagement de chars blindés au combat (Somme)', 1916, false, NULL, 'Le 15 septembre 1916, les Britanniques déploient pour la première fois des chars Mark I lors de la bataille de la Somme. Cette innovation tactique annonce la fin de la guerre de tranchées statique.', 'L''Aube de l''Aviation et la Conquête des Airs', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.114109+00', NULL, NULL, NULL, ''),
	(314, 'Premier tir de la fusée V2, première arme balistique', 1942, false, NULL, 'Le 3 octobre 1942, l''Allemagne nazie réussit le premier tir opérationnel de la fusée V2 à Peenemünde. Conçue par Wernher von Braun, elle est le premier engin à atteindre l''espace et préfigure les fusées spatiales.', 'L''Aube de l''Aviation et la Conquête des Airs', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.114109+00', NULL, NULL, NULL, ''),
	(315, 'Lancement du premier sous-marin militaire diesel-électrique allemand (U-1)', 1906, false, NULL, 'Le 14 décembre 1906, l''Allemagne met en service l''U-1, son premier sous-marin à propulsion diesel-électrique. Ce type de bâtiment deviendra une arme redoutable lors de la guerre sous-marine de 1914-1918.', 'L''Aube de l''Aviation et la Conquête des Airs', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.114109+00', NULL, NULL, NULL, ''),
	(316, 'Première utilisation opérationnelle du sonar anti-sous-marin', 1918, false, NULL, 'En avril 1918, la Marine britannique déploie pour la première fois l''ASDIC (sonar) pour détecter les sous-marins allemands. Cette technologie, née de l''urgence du conflit, restera fondamentale tout au long du XXe siècle.', 'L''Aube de l''Aviation et la Conquête des Airs', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.114109+00', NULL, NULL, NULL, ''),
	(317, 'Premier bombardement stratégique d''une capitale européenne (Londres)', 1915, false, NULL, 'Le 19 janvier 1915, des zeppelins allemands larguent des bombes sur la côte anglaise, puis sur Londres le 31 mai. C''est la première fois qu''une capitale est bombardée depuis les airs, inaugurant la guerre aérienne totale.', 'L''Aube de l''Aviation et la Conquête des Airs', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.114109+00', NULL, NULL, NULL, ''),
	(318, 'Première transfusion sanguine conservée avec anticoagulant', 1914, false, NULL, 'Le 27 novembre 1914, le médecin canadien Lawrence Bruce Robertson réalise la première transfusion utilisant du sang conservé avec du citrate de sodium. Cette avancée, née des besoins du front, sauvera des millions de vies.', 'L''Aube de l''Aviation et la Conquête des Airs', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.114109+00', NULL, NULL, NULL, ''),
	(336, 'Record de vitesse absolu en avion établi par le Lockheed SR-71 Blackbird', 1976, false, NULL, 'Le 28 juillet 1976, le SR-71 Blackbird établit un record mondial de vitesse à 3 529,6 km/h, soit plus de Mach 3, un record pour un avion à réaction habité qui tient encore aujourd''hui.', 'L''Aube de l''Aviation et la Conquête des Airs', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.142815+00', NULL, NULL, NULL, ''),
	(337, 'Premier vol du Caravelle, premier avion de ligne à réaction européen', 1955, false, NULL, 'Le 27 mai 1955, la Caravelle de Sud Aviation effectue son vol inaugural à Toulouse. Premier avion de ligne à réaction conçu en Europe, il sera adopté par de nombreuses compagnies mondiales.', 'L''Aube de l''Aviation et la Conquête des Airs', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.142815+00', NULL, NULL, NULL, ''),
	(319, 'Mise au point du procédé Haber-Bosch pour la synthèse de l''ammoniac', 1913, false, NULL, 'Le 9 septembre 1913, la première usine industrielle utilisant le procédé Haber-Bosch entre en production à Oppau en Allemagne. Ce procédé permettra à l''Allemagne de fabriquer des explosifs malgré le blocus allié.', 'L''Aube de l''Aviation et la Conquête des Airs', '', 'READY_FOR_IMAGE', 'A bustling industrial scene at the Oppau ammonia plant in Germany, September 9, 1913. Workers in period-appropriate clothing, including flat caps and work overalls, are engaged in various tasks around large, complex machinery. The atmosphere is filled with steam and the glow of gas lamps, casting dramatic shadows. In the background, a large sign on the factory building indicates its significance, while clouds of smoke rise into a twilight sky. The composition captures the energy of the moment, with expressions of determination and focus on the workers'' faces. Photorealistic documentary photo, cinematic lighting, highly detailed, 8k resolution, historical atmosphere.', '2026-03-04 07:23:47.114109+00', NULL, NULL, NULL, ''),
	(320, 'Premier vol d''un avion de chasse équipé d''un tir synchronisé à travers l''hélice', 1915, false, NULL, 'En juillet 1915, le Fokker Eindecker allemand entre en service avec un dispositif synchronisant le tir de la mitrailleuse avec la rotation de l''hélice. Cette invention d''Anthony Fokker révolutionne le combat aérien.', 'L''Aube de l''Aviation et la Conquête des Airs', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.114109+00', NULL, NULL, NULL, ''),
	(321, 'Premier lancement d''une torpille aérienne depuis un avion', 1915, false, NULL, 'Le 12 août 1915, un hydravion britannique Short Type 184 lance avec succès la première torpille aérienne contre un navire ottoman dans les Dardanelles. Cette innovation redéfinit la guerre navale pour les décennies suivantes.', 'L''Aube de l''Aviation et la Conquête des Airs', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.114109+00', NULL, NULL, NULL, ''),
	(322, 'Premier vol du chasseur à réaction britannique Gloster E.28/39', 1941, false, NULL, 'Le 15 mai 1941, le Gloster E.28/39 décolle pour la première fois à Cranwell, propulsé par le turboréacteur W.1 de Frank Whittle. Il marque l''entrée de la Grande-Bretagne dans l''ère des avions à réaction.', 'L''Aube de l''Aviation et la Conquête des Airs', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.114109+00', NULL, NULL, NULL, ''),
	(323, 'Mise en service opérationnel du Messerschmitt Me 262, premier chasseur à réaction en combat', 1944, false, NULL, 'En juillet 1944, la Luftwaffe déploie le Messerschmitt Me 262 dans des missions de combat, faisant de lui le premier avion à réaction utilisé militairement. Sa vitesse de 870 km/h surpassait tous les chasseurs alliés.', 'L''Aube de l''Aviation et la Conquête des Airs', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.114109+00', NULL, NULL, NULL, ''),
	(324, 'Premier vol du bombardier à réaction Arado Ar 234', 1943, false, NULL, 'Le 15 juin 1943, l''Arado Ar 234 effectue son premier vol en Allemagne, devenant le premier bombardier à réaction de l''histoire. Il sera utilisé pour des missions de reconnaissance et de bombardement à haute altitude.', 'L''Aube de l''Aviation et la Conquête des Airs', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.114109+00', NULL, NULL, NULL, ''),
	(325, 'Premier vol du Gloster Meteor, premier chasseur à réaction allié opérationnel', 1943, false, NULL, 'Le 5 mars 1943, le Gloster Meteor prend l''air pour la première fois en Grande-Bretagne. Il entre en service actif en 1944 et devient le seul avion à réaction allié à participer aux combats de la Seconde Guerre mondiale.', 'L''Aube de l''Aviation et la Conquête des Airs', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.114109+00', NULL, NULL, NULL, ''),
	(326, 'Premier vol du Lockheed P-80 Shooting Star, premier chasseur à réaction américain', 1944, false, NULL, 'Le 8 janvier 1944, le Lockheed P-80 Shooting Star effectue son premier vol aux États-Unis. Conçu en seulement 143 jours par l''équipe Skunk Works, il devient le premier chasseur à réaction opérationnel de l''US Air Force.', 'L''Aube de l''Aviation et la Conquête des Airs', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.114109+00', NULL, NULL, NULL, ''),
	(327, 'Premier vol du De Havilland Vampire, chasseur à réaction monoréacteur britannique', 1943, false, NULL, 'Le 20 septembre 1943, le De Havilland Vampire effectue son premier vol en Grande-Bretagne. Avec sa conception innovante à double poutre, il devient l''un des premiers chasseurs à réaction produits en série après la guerre.', 'L''Aube de l''Aviation et la Conquête des Airs', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.114109+00', NULL, NULL, NULL, ''),
	(328, 'Premier vol du Boeing B-47 Stratojet, bombardier stratégique à réaction', 1947, false, NULL, 'Le 17 décembre 1947, le Boeing B-47 Stratojet effectue son premier vol aux États-Unis. Avec ses ailes en flèche et ses six turboréacteurs, il révolutionne la conception des bombardiers stratégiques de l''après-guerre.', 'L''Aube de l''Aviation et la Conquête des Airs', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.114109+00', NULL, NULL, NULL, ''),
	(329, 'Premier vol du North American F-86 Sabre, chasseur à réaction américain de la guerre de Corée', 1947, false, NULL, 'Le 1er octobre 1947, le North American F-86 Sabre effectue son premier vol. Doté d''ailes en flèche, il s''illustre pendant la guerre de Corée face aux MiG-15 soviétiques dans les premiers combats aériens entre jets.', 'L''Aube de l''Aviation et la Conquête des Airs', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.114109+00', NULL, NULL, NULL, ''),
	(330, 'Premier vol du Mikoyan-Gourevitch MiG-15, chasseur à réaction soviétique', 1947, false, NULL, 'Le 30 décembre 1947, le MiG-15 soviétique effectue son premier vol. Propulsé par une copie du réacteur britannique Rolls-Royce Nene, il surprend les Alliés par ses performances lors de la guerre de Corée en 1950.', 'L''Aube de l''Aviation et la Conquête des Airs', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.114109+00', NULL, NULL, NULL, ''),
	(331, 'Premier vol du Heinkel He 176, premier avion à propulsion fusée', 1939, false, NULL, 'Le 20 juin 1939, le Heinkel He 176 effectue son premier vol en Allemagne, propulsé uniquement par un moteur-fusée à carburant liquide. C''est le premier avion de l''histoire à voler exclusivement grâce à la propulsion par réaction.', 'L''Aube de l''Aviation et la Conquête des Airs', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.114109+00', NULL, NULL, NULL, ''),
	(332, 'Premier vol commercial transatlantique sans escale (Pan Am)', 1958, false, NULL, 'Le 26 octobre 1958, Pan American World Airways inaugure le premier service commercial régulier transatlantique sans escale entre New York et Paris, à bord d''un Boeing 707.', 'L''Aube de l''Aviation et la Conquête des Airs', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.114109+00', NULL, NULL, NULL, ''),
	(333, 'Inauguration de l''aéroport international d''Orly', 1961, false, NULL, 'Le 24 février 1961, l''aéroport d''Orly ouvre officiellement ses portes au trafic commercial, devenant le principal hub aérien de France et symbole de la modernité aéronautique.', 'L''Aube de l''Aviation et la Conquête des Airs', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.114109+00', NULL, NULL, NULL, ''),
	(334, 'Premier vol du Tupolev Tu-104, premier jet soviétique commercial', 1956, false, NULL, 'Le 15 septembre 1956, l''URSS met en service le Tupolev Tu-104 sur la ligne Moscou-Irkoutsk, faisant de l''Union soviétique la seule nation opérant des avions de ligne à réaction après les accidents du Comet.', 'L''Aube de l''Aviation et la Conquête des Airs', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.142815+00', NULL, NULL, NULL, ''),
	(335, 'Ouverture de la première ligne commerciale régulière transcontinentale américaine à réaction', 1959, false, NULL, 'Le 25 janvier 1959, American Airlines inaugure le premier vol commercial à réaction transcontinental aux États-Unis entre New York et Los Angeles, à bord d''un Boeing 707.', 'L''Aube de l''Aviation et la Conquête des Airs', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.142815+00', NULL, NULL, NULL, ''),
	(338, 'Soulèvement ouvrier de Berlin-Est', 1953, false, NULL, 'Le 17 juin 1953, des ouvriers est-allemands se révoltent contre les normes de travail imposées par le régime communiste. L''insurrection est écrasée par les chars soviétiques, faisant plusieurs dizaines de morts.', 'La Guerre Froide : Crises, Conflits et Chute des Blocs', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.142815+00', NULL, NULL, NULL, ''),
	(339, 'Massacre de Tlatelolco au Mexique', 1968, false, NULL, 'Le 2 octobre 1968, l''armée mexicaine ouvre le feu sur des étudiants manifestant place des Trois-Cultures à Mexico, dix jours avant les Jeux olympiques. Le nombre de victimes reste controversé, estimé entre des dizaines et plusieurs centaines de morts.', 'La Guerre Froide : Crises, Conflits et Chute des Blocs', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.142815+00', NULL, NULL, NULL, ''),
	(340, 'Fondation du syndicat Solidarność en Pologne', 1980, false, NULL, 'Le 31 août 1980, les accords de Gdańsk sont signés, permettant la création du syndicat indépendant Solidarność dirigé par Lech Wałęsa. C''est la première organisation syndicale autonome dans un pays du bloc soviétique.', 'La Guerre Froide : Crises, Conflits et Chute des Blocs', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.142815+00', NULL, NULL, NULL, ''),
	(341, 'Assassinat d''Aldo Moro par les Brigades Rouges', 1978, false, NULL, 'Le 9 mai 1978, le corps de l''ancien Premier ministre italien Aldo Moro est retrouvé à Rome après 55 jours de séquestration par les Brigades Rouges. Cet assassinat marque le point culminant des années de plomb en Italie.', 'La Guerre Froide : Crises, Conflits et Chute des Blocs', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.142815+00', NULL, NULL, NULL, ''),
	(342, 'Répression du Mouvement du 5 avril en Chine', 1976, false, NULL, 'Le 5 avril 1976, des milliers de Chinois se rassemblent place Tiananmen pour rendre hommage à Zhou Enlai et contester la Bande des Quatre. Le mouvement est violemment réprimé par les autorités maoïstes.', 'La Guerre Froide : Crises, Conflits et Chute des Blocs', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.142815+00', NULL, NULL, NULL, ''),
	(343, 'Proclamation de la loi martiale en Pologne', 1981, false, NULL, 'Le 13 décembre 1981, le général Wojciech Jaruzelski proclame la loi martiale en Pologne pour briser le mouvement Solidarność. Des milliers de militants syndicaux et d''opposants sont internés.', 'La Guerre Froide : Crises, Conflits et Chute des Blocs', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.142815+00', NULL, NULL, NULL, ''),
	(344, 'Révolte du ghetto de Varsovie', 1943, false, NULL, 'Le 19 avril 1943, les Juifs du ghetto de Varsovie se soulèvent contre les nazis lors de la dernière grande déportation vers Treblinka. Cette insurrection héroïque dure près d''un mois avant d''être écrasée.', 'La Guerre Froide : Crises, Conflits et Chute des Blocs', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.142815+00', NULL, NULL, NULL, ''),
	(345, 'Arrivée au pouvoir de Mikhaïl Gorbatchev', 1985, false, NULL, 'Le 11 mars 1985, Mikhaïl Gorbatchev devient Secrétaire général du Parti communiste soviétique. Il lancera les réformes de la glasnost et de la perestroïka, amorçant la fin de l''URSS.', 'La Guerre Froide : Crises, Conflits et Chute des Blocs', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.142815+00', NULL, NULL, NULL, ''),
	(346, 'Premier sommet Reagan-Gorbatchev à Genève', 1985, false, NULL, 'Le 19 novembre 1985, Ronald Reagan et Mikhaïl Gorbatchev se rencontrent pour la première fois à Genève. Ce sommet marque le début d''un dialogue inédit entre les deux superpuissances.', 'La Guerre Froide : Crises, Conflits et Chute des Blocs', '', 'READY_FOR_IMAGE', 'A historic meeting scene set in Geneva on November 19, 1985, featuring Ronald Reagan and Mikhail Gorbachev shaking hands at a round table. Reagan is dressed in a dark navy suit with a light blue tie, showcasing his characteristic confident smile, while Gorbachev wears a grey suit with a subtle pattern, looking serious yet hopeful. The room is filled with natural light streaming through large windows, casting soft shadows on the faces of the two leaders. The atmosphere is tense yet optimistic, surrounded by advisors and dignitaries in the background, all dressed in 1980s formal attire. The setting includes flags of the United States and the Soviet Union, emphasizing the significance of this diplomatic moment. Photorealistic documentary photo, cinematic lighting, highly detailed, 8k resolution.', '2026-03-04 07:23:47.142815+00', NULL, NULL, NULL, ''),
	(347, 'Signature du traité sur les forces nucléaires à portée intermédiaire (FNI)', 1987, false, NULL, 'Le 8 décembre 1987, Reagan et Gorbatchev signent à Washington le traité FNI, éliminant toute une catégorie de missiles nucléaires. C''est un tournant majeur dans le désarmement de la Guerre Froide.', 'La Guerre Froide : Crises, Conflits et Chute des Blocs', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.142815+00', NULL, NULL, NULL, ''),
	(348, 'Discours de Gorbatchev à l''ONU annonçant des réductions militaires', 1988, false, NULL, 'Le 7 décembre 1988, Gorbatchev annonce devant l''Assemblée générale de l''ONU le retrait unilatéral de 500 000 soldats soviétiques d''Europe de l''Est. Ce discours signale la fin de la doctrine Brejnev.', 'La Guerre Froide : Crises, Conflits et Chute des Blocs', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.142815+00', NULL, NULL, NULL, ''),
	(349, 'Début du retrait soviétique d''Afghanistan', 1989, false, NULL, 'Le 15 février 1989, le dernier soldat soviétique quitte l''Afghanistan, mettant fin à neuf ans d''occupation. Ce retrait est perçu comme un aveu de faiblesse de l''URSS sur la scène internationale.', 'La Guerre Froide : Crises, Conflits et Chute des Blocs', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.142815+00', NULL, NULL, NULL, ''),
	(350, 'Premières élections libres en Pologne depuis 1945', 1989, false, NULL, 'Le 4 juin 1989, la Pologne organise des élections semi-libres remportées massivement par le syndicat Solidarność. C''est la première brèche électorale dans le bloc de l''Est.', 'La Guerre Froide : Crises, Conflits et Chute des Blocs', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.142815+00', NULL, NULL, NULL, ''),
	(351, 'Ouverture de la frontière entre la Hongrie et l''Autriche', 1989, false, NULL, 'Le 2 mai 1989, la Hongrie commence à démanteler ses barbelés à la frontière autrichienne, ouvrant un passage vers l''Ouest. Des milliers de citoyens est-allemands fuient par cette brèche dans le Rideau de fer.', 'La Guerre Froide : Crises, Conflits et Chute des Blocs', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.142815+00', NULL, NULL, NULL, ''),
	(352, 'Exécution de Nicolae Ceaușescu en Roumanie', 1989, false, NULL, 'Le 25 décembre 1989, le dictateur roumain Nicolae Ceaușescu et son épouse Elena sont fusillés après un procès expéditif. C''est la seule révolution violente du bloc de l''Est en 1989.', 'La Guerre Froide : Crises, Conflits et Chute des Blocs', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.142815+00', NULL, NULL, NULL, ''),
	(353, 'Déclaration d''indépendance de la Lituanie', 1990, false, NULL, 'Le 11 mars 1990, la Lituanie devient la première république soviétique à déclarer son indépendance. Cet acte ouvre une crise majeure entre Vilnius et Moscou.', 'La Guerre Froide : Crises, Conflits et Chute des Blocs', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.142815+00', NULL, NULL, NULL, ''),
	(354, 'Élection de Boris Eltsine à la présidence de la Russie', 1991, false, NULL, 'Le 12 juin 1991, Boris Eltsine est élu au suffrage universel direct président de la République de Russie. Sa victoire affaiblit l''autorité de Gorbatchev et de l''Union soviétique.', 'La Guerre Froide : Crises, Conflits et Chute des Blocs', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.142815+00', NULL, NULL, NULL, ''),
	(355, 'Tentative de coup d''État contre Gorbatchev à Moscou', 1991, false, NULL, 'Le 19 août 1991, des membres conservateurs du gouvernement soviétique tentent de renverser Gorbatchev. Le putsch échoue en trois jours, mais il précipite la dissolution de l''URSS.', 'La Guerre Froide : Crises, Conflits et Chute des Blocs', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.142815+00', NULL, NULL, NULL, ''),
	(356, 'Publication de la traduction allemande du Nouveau Testament par Luther', 1522, false, NULL, 'En septembre 1522, Luther publie sa traduction du Nouveau Testament en allemand, rendant la Bible accessible au peuple et unifiant la langue allemande écrite.', 'La Réforme Protestante et les Guerres de Religion', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.142815+00', NULL, NULL, NULL, ''),
	(357, 'Mariage de Martin Luther avec Katharina von Bora', 1525, false, NULL, 'Le 13 juin 1525, Martin Luther épouse Katharina von Bora, une ancienne religieuse, rompant symboliquement avec le célibat ecclésiastique et fondant le modèle du pasteur marié.', 'La Réforme Protestante et les Guerres de Religion', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.142815+00', NULL, NULL, NULL, ''),
	(358, 'Première Diète de Spire : suspension de l''Édit de Worms', 1526, false, NULL, 'Le 27 août 1526, la Diète de Spire suspend l''Édit de Worms, permettant à chaque prince allemand de choisir librement entre catholicisme et luthéranisme dans ses territoires.', 'La Réforme Protestante et les Guerres de Religion', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.142815+00', NULL, NULL, NULL, ''),
	(359, 'Présentation de la Confession d''Augsbourg', 1530, false, NULL, 'Le 25 juin 1530, Melanchthon présente la Confession d''Augsbourg à l''empereur Charles Quint, définissant officiellement les fondements doctrinaux du luthéranisme.', 'La Réforme Protestante et les Guerres de Religion', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.142815+00', NULL, NULL, NULL, ''),
	(360, 'Publication de l''Institution de la religion chrétienne par Calvin', 1536, false, NULL, 'En mars 1536, Jean Calvin publie à Bâle l''Institution de la religion chrétienne, ouvrage fondateur qui systématise la théologie réformée calviniste.', 'La Réforme Protestante et les Guerres de Religion', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.142815+00', NULL, NULL, NULL, ''),
	(361, 'Première installation de Calvin à Genève', 1536, false, NULL, 'En juillet 1536, Jean Calvin s''installe pour la première fois à Genève, invité par Guillaume Farel à y organiser la Réforme protestante.', 'La Réforme Protestante et les Guerres de Religion', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.142815+00', NULL, NULL, NULL, ''),
	(362, 'Exécution de Michel Servet à Genève', 1553, false, NULL, 'Le 27 octobre 1553, Michel Servet, théologien antitrinitaire, est brûlé vif à Genève sur décision du Conseil, avec l''approbation de Calvin, pour hérésie.', 'La Réforme Protestante et les Guerres de Religion', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.142815+00', NULL, NULL, NULL, ''),
	(363, 'Fondation de l''Académie de Genève par Calvin', 1559, false, NULL, 'Le 5 juin 1559, Jean Calvin fonde l''Académie de Genève, institution destinée à former les futurs pasteurs réformés et à diffuser le calvinisme en Europe.', 'La Réforme Protestante et les Guerres de Religion', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.142815+00', NULL, NULL, NULL, ''),
	(364, 'Mort de Jean Calvin à Genève', 1564, false, NULL, 'Le 27 mai 1564, Jean Calvin meurt à Genève à l''âge de 54 ans, laissant derrière lui une Église réformée structurée et influente dans toute l''Europe.', 'La Réforme Protestante et les Guerres de Religion', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.142815+00', NULL, NULL, NULL, ''),
	(365, 'Tenue du Synode de Dordrecht', 1618, false, NULL, 'Du 13 novembre 1618 au 9 mai 1619, le Synode de Dordrecht réunit les Églises réformées pour condamner l''arminianisme et fixer les cinq points du calvinisme orthodoxe.', 'La Réforme Protestante et les Guerres de Religion', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.142815+00', NULL, NULL, NULL, ''),
	(366, 'Mort d''Ignace de Loyola, fondateur des Jésuites', 1556, false, NULL, 'Le 31 juillet 1556, Ignace de Loyola meurt à Rome. Fondateur de la Compagnie de Jésus, il avait fait de cet ordre un instrument majeur de la Contre-Réforme catholique.', 'La Réforme Protestante et les Guerres de Religion', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.142815+00', NULL, NULL, NULL, ''),
	(367, 'Clôture du Concile de Trente', 1563, false, NULL, 'Le 4 décembre 1563, le Concile de Trente se clôt après 18 ans de travaux, définissant les dogmes catholiques, réformant la discipline ecclésiastique et rejetant les thèses protestantes.', 'La Réforme Protestante et les Guerres de Religion', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.142815+00', NULL, NULL, NULL, ''),
	(368, 'Publication de l''Index librorum prohibitorum tridentine', 1564, false, NULL, 'Le 24 mars 1564, le pape Pie IV publie l''Index des livres interdits issu du Concile de Trente, établissant une liste officielle des ouvrages jugés hérétiques ou dangereux pour la foi catholique.', 'La Réforme Protestante et les Guerres de Religion', '', 'READY_FOR_IMAGE', 'A grand hall filled with scholars and clergy, all dressed in elaborate 16th-century robes, deep crimson and gold accents highlighting their status. In the center, Pope Pius IV stands authoritatively, holding a scroll, illuminated by soft, warm candlelight that casts gentle shadows across the stone walls. The expressions of the attendees range from solemnity to curiosity as they gaze upon the Pope. The atmosphere is thick with tension and reverence, with richly decorated tapestries hanging in the background, depicting religious scenes. The composition captures the moment of declaration, with a focus on the Pope''s commanding presence and the attentive crowd. Photorealistic, cinematic lighting, highly detailed, 8k resolution, historical painting.', '2026-03-04 07:23:47.142815+00', NULL, NULL, NULL, ''),
	(369, 'Premier vol opérationnel du Supermarine Spitfire', 1938, false, NULL, 'Le 4 août 1938, le Spitfire entre en service opérationnel au sein du No. 19 Squadron de la RAF. Cet avion de chasse britannique deviendra l''un des symboles de la résistance aérienne britannique durant la Seconde Guerre mondiale.', 'La Seconde Guerre Mondiale : Les Moments Clés du Conflit Mondial', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.142815+00', NULL, NULL, NULL, ''),
	(370, 'Mise en service du radar Chain Home', 1937, false, NULL, 'En 1937, le réseau de détection radar Chain Home est mis en service opérationnel sur les côtes britanniques. Ce système permettra à la RAF de détecter les attaques aériennes allemandes à distance, jouant un rôle crucial durant la bataille d''Angleterre.', 'La Seconde Guerre Mondiale : Les Moments Clés du Conflit Mondial', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.142815+00', NULL, NULL, NULL, ''),
	(371, 'Discours de Churchill sur ''les quelques''', 1940, false, NULL, 'Le 20 août 1940, Winston Churchill prononce son célèbre discours au Parlement rendant hommage aux pilotes de la RAF : ''Jamais dans l''histoire des conflits humains, autant de gens n''ont dû autant à si peu.'' Ce discours immortalise les pilotes de la bataille d''Angleterre.', 'La Seconde Guerre Mondiale : Les Moments Clés du Conflit Mondial', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.142815+00', NULL, NULL, NULL, ''),
	(372, 'Annulation de l''opération Otarie (invasion de la Grande-Bretagne)', 1940, false, NULL, 'Le 17 septembre 1940, Hitler reporte indéfiniment l''opération Seelöwe (Otarie), le plan d''invasion de la Grande-Bretagne. L''échec de la Luftwaffe à obtenir la supériorité aérienne face à la RAF rend l''opération impossible.', 'La Seconde Guerre Mondiale : Les Moments Clés du Conflit Mondial', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.142815+00', NULL, NULL, NULL, ''),
	(373, 'Entrée en service du Hawker Hurricane dans la RAF', 1937, false, NULL, 'Le 25 décembre 1937, le Hawker Hurricane entre officiellement en service dans la RAF. Cet avion de chasse robuste constituera la majorité des forces de chasse britanniques durant la bataille d''Angleterre, abattant plus d''appareils ennemis que le Spitfire.', 'La Seconde Guerre Mondiale : Les Moments Clés du Conflit Mondial', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.142815+00', NULL, NULL, NULL, ''),
	(467, 'Reprise de Rouen par les Français', 1449, false, NULL, 'Le 10 novembre 1449, Charles VII entre triomphalement dans Rouen, capitale de la Normandie, mettant fin à 30 ans d''occupation anglaise dans la région.', 'La Guerre de Cent Ans : Batailles, Héroïnes et Monarchies', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.172377+00', NULL, NULL, NULL, ''),
	(374, 'Création du Fighter Command de la RAF', 1936, false, NULL, 'Le 14 juillet 1936, le Fighter Command est créé au sein de la Royal Air Force sous le commandement du Air Chief Marshal Hugh Dowding. Cette structure de commandement centralisée sera déterminante dans l''organisation de la défense aérienne britannique.', 'La Seconde Guerre Mondiale : Les Moments Clés du Conflit Mondial', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.142815+00', NULL, NULL, NULL, ''),
	(375, 'Premier raid de la RAF sur Berlin', 1940, false, NULL, 'Dans la nuit du 25 au 26 août 1940, la RAF effectue son premier bombardement sur Berlin en représailles aux bombes allemandes tombées sur Londres. Ce raid pousse Hitler à ordonner le bombardement massif des villes britanniques, soulageant indirectement les aérodromes de la RAF.', 'La Seconde Guerre Mondiale : Les Moments Clés du Conflit Mondial', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.142815+00', NULL, NULL, NULL, ''),
	(376, 'Lancement de l''opération Barbarossa par l''Allemagne nazie', 1941, false, NULL, 'Le 22 juin 1941, Hitler lance l''invasion de l''Union soviétique avec plus de 3 millions de soldats. C''est la plus grande offensive militaire terrestre de l''histoire.', 'La Seconde Guerre Mondiale : Les Moments Clés du Conflit Mondial', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.142815+00', NULL, NULL, NULL, ''),
	(377, 'Début de la bataille de Moscou sur le front de l''Est', 1941, false, NULL, 'Le 2 octobre 1941, l''Allemagne lance l''opération Typhon visant à capturer Moscou. Les forces soviétiques résistent et repoussent l''offensive en décembre 1941.', 'La Seconde Guerre Mondiale : Les Moments Clés du Conflit Mondial', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.142815+00', NULL, NULL, NULL, ''),
	(378, 'Déclaration de guerre de l''Allemagne et de l''Italie aux États-Unis', 1941, false, NULL, 'Le 11 décembre 1941, Hitler et Mussolini déclarent la guerre aux États-Unis, quatre jours après Pearl Harbor. Cette décision élargit considérablement le conflit mondial.', 'La Seconde Guerre Mondiale : Les Moments Clés du Conflit Mondial', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.142815+00', NULL, NULL, NULL, ''),
	(379, 'Première contre-offensive soviétique devant Moscou', 1941, false, NULL, 'Le 5 décembre 1941, l''Armée rouge lance une contre-offensive massive sur le front de Moscou. C''est le premier recul significatif de la Wehrmacht depuis le début de la guerre.', 'La Seconde Guerre Mondiale : Les Moments Clés du Conflit Mondial', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.142815+00', NULL, NULL, NULL, ''),
	(380, 'Lancement de l''opération Uranus', 1942, false, NULL, 'Le 19 novembre 1942, l''Armée rouge lance une contre-offensive massive visant à encercler la 6e armée allemande du général Paulus autour de Stalingrad. L''étau soviétique se referme en quelques jours.', 'La Seconde Guerre Mondiale : Les Moments Clés du Conflit Mondial', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.142815+00', NULL, NULL, NULL, ''),
	(381, 'Libération de Kharkov par l''Armée rouge', 1943, false, NULL, 'Le 23 août 1943, les forces soviétiques reprennent définitivement Kharkov, grande ville industrielle d''Ukraine. Cette victoire confirme le renversement du rapport de force sur le front de l''Est.', 'La Seconde Guerre Mondiale : Les Moments Clés du Conflit Mondial', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.142815+00', NULL, NULL, NULL, ''),
	(382, 'Signature de l''armistice franco-allemand à Rethondes', 1940, false, NULL, 'Le 22 juin 1940, la France signe l''armistice avec l''Allemagne nazie dans la forêt de Compiègne, dans le même wagon que celui de 1918. La France est divisée en zone occupée et zone libre.', 'La Seconde Guerre Mondiale : Les Moments Clés du Conflit Mondial', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.142815+00', NULL, NULL, NULL, ''),
	(383, 'Conférence de Téhéran entre Churchill, Roosevelt et Staline', 1943, false, NULL, 'Du 28 novembre au 1er décembre 1943, les trois grands alliés se réunissent à Téhéran pour coordonner leur stratégie. L''ouverture d''un second front en Europe occidentale y est officiellement décidée.', 'La Seconde Guerre Mondiale : Les Moments Clés du Conflit Mondial', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.142815+00', NULL, NULL, NULL, ''),
	(384, 'Débarquement allié en Sicile (Opération Husky)', 1943, false, NULL, 'Le 9 juillet 1943, les forces alliées débarquent en Sicile, amorçant la remontée de la péninsule italienne. Cette opération préfigure les grandes opérations amphibies qui culmineront en Normandie.', 'La Seconde Guerre Mondiale : Les Moments Clés du Conflit Mondial', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.158516+00', NULL, NULL, NULL, ''),
	(385, 'Nomination d''Eisenhower comme commandant suprême des forces alliées', 1943, false, NULL, 'Le 24 décembre 1943, le général américain Dwight D. Eisenhower est nommé commandant suprême des forces expéditionnaires alliées (SHAEF). Il sera chargé de planifier et diriger le débarquement en Normandie.', 'La Seconde Guerre Mondiale : Les Moments Clés du Conflit Mondial', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.158516+00', NULL, NULL, NULL, ''),
	(386, 'Prise de Cherbourg par les forces américaines', 1944, false, NULL, 'Le 26 juin 1944, les troupes américaines s''emparent du port stratégique de Cherbourg après plusieurs semaines de combats acharnés. Ce port devient un point d''approvisionnement crucial pour les Alliés.', 'La Seconde Guerre Mondiale : Les Moments Clés du Conflit Mondial', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.158516+00', NULL, NULL, NULL, ''),
	(387, 'Lancement de l''Opération Cobra par les forces américaines', 1944, false, NULL, 'Le 25 juillet 1944, les Américains lancent l''opération Cobra pour percer le front allemand en Normandie près de Saint-Lô. Cette percée permet la libération rapide de la Bretagne et du nord de la France.', 'La Seconde Guerre Mondiale : Les Moments Clés du Conflit Mondial', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.158516+00', NULL, NULL, NULL, ''),
	(388, 'Débarquement allié en Provence (Opération Dragoon)', 1944, false, NULL, 'Le 15 août 1944, les forces alliées débarquent sur les côtes de Provence entre Toulon et Cannes. Cette opération complémentaire du débarquement en Normandie accélère la libération du sud de la France.', 'La Seconde Guerre Mondiale : Les Moments Clés du Conflit Mondial', '', 'READY_FOR_IMAGE', 'Allied forces landing on the beaches of Provence on August 15, 1944, amidst a dramatic sky filled with clouds, beams of sunlight breaking through. Soldiers in WWII uniforms, including American GIs and Free French forces, rush to the shoreline from landing crafts, their expressions determined and focused. The sand is kicked up around them, and the ocean waves crash in the background. Military vehicles, such as jeeps and half-tracks, are visible on the beach, with supplies being unloaded. The scene is vibrant with the colors of the uniforms contrasting against the blue sea and golden sand. The atmosphere is tense yet hopeful, capturing the essence of liberation. Photorealistic documentary photo, cinematic lighting, highly detailed, 8k resolution.', '2026-03-04 07:23:47.158516+00', NULL, NULL, NULL, ''),
	(389, 'Franchissement du Rhin par les forces alliées à Remagen', 1945, false, NULL, 'Le 7 mars 1945, les soldats américains s''emparent intact du pont de Remagen sur le Rhin, permettant une traversée rapide vers l''Allemagne. Cet événement ouvre la voie à l''invasion du cœur du Reich.', 'La Seconde Guerre Mondiale : Les Moments Clés du Conflit Mondial', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.158516+00', NULL, NULL, NULL, ''),
	(390, 'Débarquement de la Grande Armée païenne en Angleterre', 865, false, NULL, 'Une immense armée viking, dirigée par Ivar le Désossé et Halfdan Ragnarsson, débarque en East Anglia. Contrairement aux raids précédents, elle vient conquérir et s''installer durablement.', 'L''Épopée Viking : Raids, Conquêtes et Explorations', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.158516+00', NULL, NULL, NULL, ''),
	(392, 'Prise de York par les Vikings', 866, false, NULL, 'En novembre 866, la Grande Armée viking s''empare de York (Jorvik), capitale du royaume de Northumbrie. La ville devient un centre majeur de la puissance scandinave en Angleterre.', 'L''Épopée Viking : Raids, Conquêtes et Explorations', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.158516+00', NULL, NULL, NULL, ''),
	(393, 'Victoire d''Alfred le Grand à la bataille d''Ashdown', 871, false, NULL, 'En janvier 871, le prince Alfred de Wessex remporte une victoire décisive contre les Vikings à la bataille d''Ashdown. C''est l''une des rares victoires saxonnes face à la Grande Armée pendant cette période.', 'L''Épopée Viking : Raids, Conquêtes et Explorations', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.158516+00', NULL, NULL, NULL, ''),
	(394, 'Colonisation viking de la Mercie orientale', 877, false, NULL, 'En 877, les Vikings partagent et colonisent une grande partie de la Mercie, s''y installant comme agriculteurs et colons. Cet événement marque une étape clé dans l''établissement du Danelaw.', 'L''Épopée Viking : Raids, Conquêtes et Explorations', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.158516+00', NULL, NULL, NULL, ''),
	(395, 'Surprise d''Alfred le Grand à Chippenham par les Vikings', 878, false, NULL, 'En janvier 878, le roi viking Guthrum lance une attaque surprise sur la résidence royale de Chippenham, forçant Alfred le Grand à fuir dans les marais du Somerset. C''est le point le plus bas du règne d''Alfred.', 'L''Épopée Viking : Raids, Conquêtes et Explorations', '', 'READY_FOR_IMAGE', 'A dramatic scene depicting the surprise attack by Viking King Guthrum on the royal residence in Chippenham, January 878. In the foreground, a fierce Viking warrior in chainmail and a fur cloak brandishes a sword, his face fierce and determined. In contrast, King Alfred the Great, wearing a simple yet regal tunic and a heavy cloak, looks alarmed as he prepares to flee, glancing back towards the approaching Vikings. The background is filled with dark, ominous clouds, suggesting an impending storm, while flickering torches cast a warm glow on the characters. The atmosphere is tense, with a sense of urgency and danger. The setting includes a wooden fortification and a glimpse of the marshy landscape beyond, shrouded in mist. The composition captures the chaos of battle, with Viking ships visible in the distance, ready for the assault. Photorealistic, cinematic lighting, highly detailed, 8k resolution, historical painting.', '2026-03-04 07:23:47.158516+00', NULL, NULL, NULL, ''),
	(396, 'Victoire d''Alfred le Grand à la bataille d''Edington', 878, false, NULL, 'En mai 878, Alfred le Grand écrase l''armée viking de Guthrum à la bataille d''Edington. Cette victoire décisive ouvre la voie à la négociation du traité délimitant le Danelaw.', 'L''Épopée Viking : Raids, Conquêtes et Explorations', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.158516+00', NULL, NULL, NULL, ''),
	(397, 'Signature du traité d''Alfred et Guthrum', 878, false, NULL, 'En 878, Alfred le Grand et le chef viking Guthrum signent un traité fixant la frontière entre le Wessex et les territoires vikings. Ce traité officialise l''existence du Danelaw en Angleterre.', 'L''Épopée Viking : Raids, Conquêtes et Explorations', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.158516+00', NULL, NULL, NULL, ''),
	(398, 'Baptême du chef viking Guthrum', 878, false, NULL, 'Après sa défaite à Edington, le chef viking Guthrum accepte le baptême chrétien, prenant le nom d''Æthelstan. Alfred le Grand est son parrain, scellant symboliquement la paix entre les deux peuples.', 'L''Épopée Viking : Raids, Conquêtes et Explorations', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.158516+00', NULL, NULL, NULL, ''),
	(399, 'Établissement de l''Althing, premier parlement islandais', 930, false, NULL, 'Les colons islandais fondent l''Althing à Þingvellir, l''une des plus anciennes assemblées parlementaires du monde. Cette institution régit les affaires politiques et juridiques de la colonie viking.', 'L''Épopée Viking : Raids, Conquêtes et Explorations', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.158516+00', NULL, NULL, NULL, ''),
	(400, 'Exil d''Eirik le Rouge d''Islande', 982, false, NULL, 'Eirik le Rouge est banni d''Islande pour trois ans après avoir commis plusieurs meurtres. Il profite de cet exil pour explorer les terres à l''ouest, découvrant ce qu''il nommera le Groenland.', 'L''Épopée Viking : Raids, Conquêtes et Explorations', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.158516+00', NULL, NULL, NULL, ''),
	(401, 'Adoption du christianisme en Islande par l''Althing', 1000, false, NULL, 'L''Althing islandais vote officiellement l''adoption du christianisme comme religion de l''île, sous pression du roi de Norvège Olaf Tryggvason. Les pratiques païennes sont toutefois tolérées en privé.', 'L''Épopée Viking : Raids, Conquêtes et Explorations', '', 'IMAGE_DONE', 'A grand assembly at the Althing in Iceland, depicting a diverse group of Viking leaders and chieftains gathered around a large stone altar. The scene is set in a lush green valley, with rugged mountains in the background under a dramatic sky. The leaders, dressed in traditional Viking attire with fur cloaks, intricate leather armor, and ornate jewelry, are engaged in a heated discussion. At the center, a charismatic figure representing King Olaf Tryggvason stands with a commanding presence, gesturing passionately as he advocates for the adoption of Christianity. In the foreground, a few individuals display expressions of concern, while others seem contemplative, reflecting the tension between pagan traditions and the new faith. The warm light of the setting sun casts long shadows, creating a solemn yet hopeful atmosphere. The scene captures the cultural shift, with elements of both Christian and pagan symbols subtly integrated. Photorealistic, cinematic lighting, highly detailed, 8k resolution, historical painting.', '2026-03-04 07:23:47.158516+00', NULL, NULL, NULL, 'http://127.0.0.1:54321/storage/v1/object/public/evenements-image/chambre_noire_adoption_du_christianisme_en_i_1772265700706.webp'),
	(402, 'Première tentative d''exploration du Vinland par Bjarne Herjolfsson', 986, false, NULL, 'Le navigateur viking Bjarne Herjolfsson aperçoit des terres inconnues à l''ouest du Groenland sans y débarquer. Son récit inspirera Leif Erikson à organiser une expédition.', 'L''Épopée Viking : Raids, Conquêtes et Explorations', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.158516+00', NULL, NULL, NULL, ''),
	(403, 'Tentative de colonisation du Vinland par Thorfinn Karlsefni', 1010, false, NULL, 'Le marchand islandais Thorfinn Karlsefni tente d''établir une colonie permanente au Vinland avec environ 160 personnes. Les conflits répétés avec les Skrælings forcent l''abandon du projet.', 'L''Épopée Viking : Raids, Conquêtes et Explorations', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.158516+00', NULL, NULL, NULL, ''),
	(405, 'Bataille de Stamford Bridge, fin de l''ère viking en Angleterre', 1066, false, NULL, 'Le roi Harald III de Norvège est vaincu et tué par Harold II d''Angleterre à Stamford Bridge. Cette bataille marque la fin des grandes invasions vikings en Angleterre.', 'L''Épopée Viking : Raids, Conquêtes et Explorations', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.158516+00', NULL, NULL, NULL, ''),
	(406, 'Siège et sac de Paris par les Vikings', 885, false, NULL, 'En novembre 885, une flotte viking d''environ 700 navires remonte la Seine et assiège Paris pendant près d''un an. Le comte Eudes défend la ville jusqu''à l''intervention du roi Charles le Gros.', 'L''Épopée Viking : Raids, Conquêtes et Explorations', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.158516+00', NULL, NULL, NULL, ''),
	(407, 'Fondation de la Normandie par Rollon', 911, false, NULL, 'Le traité de Saint-Clair-sur-Epte est signé en 911 entre le roi franc Charles III et le chef viking Rollon. Ce dernier reçoit un territoire qui deviendra la Normandie en échange de sa conversion au christianisme.', 'L''Épopée Viking : Raids, Conquêtes et Explorations', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.158516+00', NULL, NULL, NULL, ''),
	(408, 'Mort de Knut le Grand, fin de l''empire nordique', 1035, false, NULL, 'Le 12 novembre 1035, Knut le Grand meurt à Shaftesbury, en Angleterre. Son empire nordique se disloque rapidement, marquant le déclin de la puissance viking en Europe occidentale.', 'L''Épopée Viking : Raids, Conquêtes et Explorations', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.158516+00', NULL, NULL, NULL, ''),
	(409, 'Déclaration de guerre de l''Autriche-Hongrie à la Serbie', 1914, false, NULL, 'Le 28 juillet 1914, l''Autriche-Hongrie déclare officiellement la guerre à la Serbie, un mois après l''assassinat de François-Ferdinand. C''est le premier acte de guerre formel du conflit mondial.', 'La Première Guerre Mondiale : Les Moments Clés du Conflit Mondial', '', 'READY_FOR_IMAGE', 'A dramatic scene set in a grand, ornate hall filled with tension and anticipation. Austrian-Hungarian military officials in early 20th-century uniforms, complete with medals and insignias, gather around a large wooden table. One officer, a stern-looking man with a prominent mustache, stands at the forefront, raising a document with a determined expression. The room is adorned with heavy drapes and flickering candlelight, casting shadows that enhance the gravity of the moment. Outside the tall windows, hints of a bustling city can be seen, representing the world on the brink of war. The atmosphere is charged, with a mix of anxiety and resolve among the officers. The composition captures the historical significance of the moment, with intricate details of the uniforms and the opulent decor. Photorealistic documentary photo, cinematic lighting, highly detailed, 8k resolution.', '2026-03-04 07:23:47.158516+00', NULL, NULL, NULL, ''),
	(410, 'Déclaration de guerre de l''Allemagne à la Russie', 1914, false, NULL, 'Le 1er août 1914, l''Allemagne déclare la guerre à la Russie après que celle-ci a refusé de stopper sa mobilisation. L''engrenage des alliances entraîne désormais toute l''Europe dans le conflit.', 'La Première Guerre Mondiale : Les Moments Clés du Conflit Mondial', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.158516+00', NULL, NULL, NULL, ''),
	(411, 'Déclaration de guerre de l''Allemagne à la France', 1914, false, NULL, 'Le 3 août 1914, l''Allemagne déclare la guerre à la France, alliée de la Russie. Le plan Schlieffen prévoit une attaque rapide à l''ouest avant de se retourner contre l''est.', 'La Première Guerre Mondiale : Les Moments Clés du Conflit Mondial', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.158516+00', NULL, NULL, NULL, ''),
	(412, 'Proclamation de l''Union sacrée en France', 1914, false, NULL, 'Le 4 août 1914, le président Raymond Poincaré proclame l''Union sacrée, appelant tous les partis politiques français à suspendre leurs divisions pour défendre la patrie. Socialistes et conservateurs s''unissent.', 'La Première Guerre Mondiale : Les Moments Clés du Conflit Mondial', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.158516+00', NULL, NULL, NULL, ''),
	(413, 'Déclaration de guerre de l''Autriche-Hongrie à la Russie', 1914, false, NULL, 'Le 6 août 1914, l''Autriche-Hongrie déclare la guerre à la Russie, élargissant officiellement le conflit au front oriental. L''alliance des puissances centrales se consolide face à la Triple-Entente.', 'La Première Guerre Mondiale : Les Moments Clés du Conflit Mondial', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.158516+00', NULL, NULL, NULL, ''),
	(414, 'Entrée en guerre du Japon aux côtés des Alliés', 1914, false, NULL, 'Le 23 août 1914, le Japon déclare la guerre à l''Allemagne, invoquant son alliance avec le Royaume-Uni. Tokyo vise notamment les possessions coloniales allemandes en Asie et dans le Pacifique.', 'La Première Guerre Mondiale : Les Moments Clés du Conflit Mondial', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.158516+00', NULL, NULL, NULL, ''),
	(415, 'Début de la course à la mer sur le front occidental', 1914, false, NULL, 'À partir de septembre 1914, Français et Allemands tentent mutuellement de déborder le flanc adverse vers le nord. Cette série de manœuvres s''achève en novembre avec la stabilisation du front jusqu''à la mer du Nord.', 'La Première Guerre Mondiale : Les Moments Clés du Conflit Mondial', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.158516+00', NULL, NULL, NULL, ''),
	(416, 'Bataille de Liège', 1914, false, NULL, 'Du 5 au 16 août 1914, les forts belges de Liège résistent aux assauts allemands, retardant l''avance ennemie de plusieurs jours.', 'La Première Guerre Mondiale : Les Moments Clés du Conflit Mondial', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.158516+00', NULL, NULL, NULL, ''),
	(417, 'Bataille des Frontières', 1914, false, NULL, 'Du 14 au 24 août 1914, les armées françaises subissent de lourdes défaites en Alsace-Lorraine et dans les Ardennes face à l''offensive allemande.', 'La Première Guerre Mondiale : Les Moments Clés du Conflit Mondial', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.158516+00', NULL, NULL, NULL, ''),
	(418, 'Retraite de Mons des troupes britanniques', 1914, false, NULL, 'Le 24 août 1914, le Corps expéditionnaire britannique amorce sa retraite depuis Mons sous la pression des forces allemandes supérieures en nombre.', 'La Première Guerre Mondiale : Les Moments Clés du Conflit Mondial', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.158516+00', NULL, NULL, NULL, ''),
	(419, 'Chute de Namur', 1914, false, NULL, 'Le 25 août 1914, la ville fortifiée de Namur tombe aux mains des Allemands après un bombardement intense, ouvrant la route vers la France.', 'La Première Guerre Mondiale : Les Moments Clés du Conflit Mondial', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.158516+00', NULL, NULL, NULL, ''),
	(420, 'Massacre de Leuven par les troupes allemandes', 1914, false, NULL, 'Du 25 au 30 août 1914, les soldats allemands incendient la ville belge de Leuven et massacrent des civils, suscitant une indignation internationale.', 'La Première Guerre Mondiale : Les Moments Clés du Conflit Mondial', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.158516+00', NULL, NULL, NULL, ''),
	(421, 'Les taxis de la Marne transportent des renforts', 1914, false, NULL, 'Dans la nuit du 6 au 7 septembre 1914, environ 600 taxis parisiens acheminent des soldats français vers le front de la Marne, épisode emblématique de la bataille.', 'La Première Guerre Mondiale : Les Moments Clés du Conflit Mondial', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.158516+00', NULL, NULL, NULL, ''),
	(422, 'Retraite allemande vers l''Aisne', 1914, false, NULL, 'Le 9 septembre 1914, le général von Moltke ordonne le repli des armées allemandes vers la rivière Aisne, marquant l''échec du plan Schlieffen.', 'La Première Guerre Mondiale : Les Moments Clés du Conflit Mondial', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.158516+00', NULL, NULL, NULL, ''),
	(423, 'Début de la bataille de l''Aisne', 1914, false, NULL, 'Le 13 septembre 1914, les Alliés tentent de percer les lignes allemandes retranchées sur l''Aisne, inaugurant les premières tranchées du front occidental.', 'La Première Guerre Mondiale : Les Moments Clés du Conflit Mondial', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.158516+00', NULL, NULL, NULL, ''),
	(424, 'Chute d''Anvers', 1914, false, NULL, 'Le 10 octobre 1914, la ville fortifiée d''Anvers capitule devant les forces allemandes après un siège, libérant des troupes pour le front principal.', 'La Première Guerre Mondiale : Les Moments Clés du Conflit Mondial', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.158516+00', NULL, NULL, NULL, ''),
	(425, 'Première bataille d''Ypres', 1914, false, NULL, 'Du 19 octobre au 22 novembre 1914, Alliés et Allemands se battent pour le contrôle d''Ypres en Belgique, soldant la Course à la mer par un front stabilisé.', 'La Première Guerre Mondiale : Les Moments Clés du Conflit Mondial', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.158516+00', NULL, NULL, NULL, ''),
	(426, 'Massacre des Innocents à Langemarck', 1914, false, NULL, 'Le 22 octobre 1914, de jeunes volontaires allemands lancent des assauts frontaux près de Langemarck et subissent des pertes catastrophiques face aux Britanniques.', 'La Première Guerre Mondiale : Les Moments Clés du Conflit Mondial', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.158516+00', NULL, NULL, NULL, ''),
	(427, 'Trêve de Noël sur le front occidental', 1914, false, NULL, 'Le 25 décembre 1914, des soldats allemands et britanniques fraternisent spontanément dans le no man''s land, certains jouant même au football entre les tranchées.', 'La Première Guerre Mondiale : Les Moments Clés du Conflit Mondial', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.158516+00', NULL, NULL, NULL, ''),
	(428, 'Première utilisation de gaz lacrymogène par l''Allemagne', 1914, false, NULL, 'Le 27 octobre 1914, l''armée allemande utilise pour la première fois des obus chargés de xylylbromure contre les troupes russes à Neuve-Chapelle, amorçant la guerre chimique.', 'La Première Guerre Mondiale : Les Moments Clés du Conflit Mondial', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.158516+00', NULL, NULL, NULL, ''),
	(429, 'Prise du fort de Douaumont par les Allemands', 1916, false, NULL, 'Le 25 février 1916, les troupes allemandes s''emparent du fort de Douaumont, ouvrage clé du dispositif défensif français à Verdun. Sa chute provoque un choc immense en France.', 'La Première Guerre Mondiale : Les Moments Clés du Conflit Mondial', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.158516+00', NULL, NULL, NULL, ''),
	(430, 'Nomination de Pétain à la tête de la défense de Verdun', 1916, false, NULL, 'Le 26 février 1916, le général Philippe Pétain est nommé commandant de la IIe armée chargée de défendre Verdun. Il organise la résistance et la fameuse ''Voie Sacrée'' pour ravitailler le front.', 'La Première Guerre Mondiale : Les Moments Clés du Conflit Mondial', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.158516+00', NULL, NULL, NULL, ''),
	(431, 'Ouverture de la Voie Sacrée pour ravitailler Verdun', 1916, false, NULL, 'Le 27 février 1916, la route reliant Bar-le-Duc à Verdun est organisée en flux continu de camions militaires. Surnommée ''Voie Sacrée'', elle permettra d''acheminer hommes et matériel tout au long de la bataille.', 'La Première Guerre Mondiale : Les Moments Clés du Conflit Mondial', '', 'READY_FOR_IMAGE', 'A bustling scene on the Sacred Way, February 27, 1916, depicting a continuous stream of military trucks transporting supplies and soldiers from Bar-le-Duc to Verdun. The foreground features a convoy of vintage military vehicles, with uniformed soldiers in early 20th-century French army attire, including woolen greatcoats and steel helmets. Dust rises from the road, illuminated by soft, golden sunlight filtering through the trees lining the route. The atmosphere is tense yet determined, showcasing the urgency of the war effort. In the background, blurred figures of additional soldiers and equipment can be seen, creating a sense of depth and movement. The composition captures the historical significance of this vital supply line. Photorealistic documentary photo, cinematic lighting, highly detailed, 8k resolution.', '2026-03-04 07:23:47.158516+00', NULL, NULL, NULL, ''),
	(432, 'Reprise du fort de Douaumont par les Français', 1916, false, NULL, 'Le 24 octobre 1916, les troupes françaises reprennent le fort de Douaumont aux Allemands lors d''une contre-offensive menée sous le commandement du général Mangin. C''est un tournant symbolique majeur à Verdun.', 'La Première Guerre Mondiale : Les Moments Clés du Conflit Mondial', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.158516+00', NULL, NULL, NULL, ''),
	(433, 'Mort du maréchal Kitchener en mer du Nord', 1916, false, NULL, 'Le 5 juin 1916, le secrétaire d''État britannique à la Guerre Lord Kitchener périt lorsque le croiseur HMS Hampshire heurte une mine allemande. Sa mort prive l''Angleterre de l''un de ses principaux organisateurs militaires.', 'La Première Guerre Mondiale : Les Moments Clés du Conflit Mondial', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.158516+00', NULL, NULL, NULL, ''),
	(434, 'Début de l''offensive Broussilov sur le front de l''Est', 1916, false, NULL, 'Le 4 juin 1916, le général russe Alexeï Broussilov lance une vaste offensive contre les armées austro-hongroises en Galicie. Considérée comme l''offensive la plus réussie de la guerre, elle inflige plus d''un million de pertes à l''ennemi.', 'La Première Guerre Mondiale : Les Moments Clés du Conflit Mondial', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.158516+00', NULL, NULL, NULL, ''),
	(436, 'Mort de l''empereur François-Joseph d''Autriche', 1916, false, NULL, 'Le 21 novembre 1916, l''empereur François-Joseph Ier d''Autriche-Hongrie décède à Vienne à l''âge de 86 ans après 68 ans de règne. Son successeur Charles Ier hérite d''un empire épuisé par deux ans de guerre.', 'La Première Guerre Mondiale : Les Moments Clés du Conflit Mondial', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.158516+00', NULL, NULL, NULL, ''),
	(437, 'Abdication du tsar Nicolas II de Russie', 1917, false, NULL, 'Le 15 mars 1917, sous la pression de la révolution de Février, Nicolas II abdique, ouvrant la voie au retrait progressif de la Russie du conflit.', 'La Première Guerre Mondiale : Les Moments Clés du Conflit Mondial', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.172377+00', NULL, NULL, NULL, ''),
	(438, 'Discours des Quatorze Points du président Wilson', 1918, false, NULL, 'Le 8 janvier 1918, Woodrow Wilson présente au Congrès son programme de paix en quatorze points, définissant les objectifs de guerre américains et un nouvel ordre mondial.', 'La Première Guerre Mondiale : Les Moments Clés du Conflit Mondial', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.172377+00', NULL, NULL, NULL, ''),
	(439, 'Reprise de la guerre sous-marine à outrance par l''Allemagne', 1917, false, NULL, 'Le 1er février 1917, l''Allemagne annonce la reprise de la guerre sous-marine totale, coulant tout navire approchant les côtes alliées, acte déclencheur de l''entrée en guerre américaine.', 'La Première Guerre Mondiale : Les Moments Clés du Conflit Mondial', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.172377+00', NULL, NULL, NULL, ''),
	(440, 'Publication du télégramme Zimmermann', 1917, false, NULL, 'Le 1er mars 1917, le gouvernement américain rend public le télégramme secret du ministre allemand Zimmermann proposant une alliance militaire au Mexique contre les États-Unis.', 'La Première Guerre Mondiale : Les Moments Clés du Conflit Mondial', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.172377+00', NULL, NULL, NULL, ''),
	(441, 'Abdication du Kaiser Guillaume II d''Allemagne', 1918, false, NULL, 'Le 9 novembre 1918, deux jours avant l''armistice, le Kaiser Guillaume II abdique sous la pression des révolutions internes et des défaites militaires. Il s''exile aux Pays-Bas.', 'La Première Guerre Mondiale : Les Moments Clés du Conflit Mondial', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.172377+00', NULL, NULL, NULL, ''),
	(442, 'Proclamation de la République de Weimar en Allemagne', 1918, false, NULL, 'Le 9 novembre 1918, Philipp Scheidemann proclame la République depuis une fenêtre du Reichstag à Berlin, mettant fin à l''Empire allemand né en 1871.', 'La Première Guerre Mondiale : Les Moments Clés du Conflit Mondial', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.172377+00', NULL, NULL, NULL, ''),
	(443, 'Retour triomphal du maréchal Foch à Paris après l''armistice', 1918, false, NULL, 'Le 11 novembre 1918, Ferdinand Foch, commandant suprême des forces alliées, est acclamé à Paris après avoir conduit les négociations de l''armistice dans son wagon à Compiègne.', 'La Première Guerre Mondiale : Les Moments Clés du Conflit Mondial', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.172377+00', NULL, NULL, NULL, ''),
	(444, 'Entrée des troupes françaises à Strasbourg après l''armistice', 1918, false, NULL, 'Le 22 novembre 1918, le général Gouraud entre à Strasbourg, marquant le retour de l''Alsace à la France après 47 ans d''occupation allemande depuis 1871.', 'La Première Guerre Mondiale : Les Moments Clés du Conflit Mondial', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.172377+00', NULL, NULL, NULL, ''),
	(445, 'Débarquement anglais en Normandie', 1346, false, NULL, 'Le 12 juillet 1346, Édouard III débarque à Saint-Vaast-la-Hougue avec son armée, lançant une chevauchée dévastatrice à travers la Normandie vers le nord de la France.', 'La Guerre de Cent Ans : Batailles, Héroïnes et Monarchies', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.172377+00', NULL, NULL, NULL, ''),
	(446, 'Prise de Calais par Édouard III', 1347, false, NULL, 'Le 4 août 1347, après onze mois de siège, Calais capitule devant les Anglais. La ville devient une tête de pont anglaise sur le continent pour plus de deux siècles.', 'La Guerre de Cent Ans : Batailles, Héroïnes et Monarchies', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.172377+00', NULL, NULL, NULL, ''),
	(447, 'Trêve de Calais entre la France et l''Angleterre', 1347, false, NULL, 'Le 28 septembre 1347, une trêve est signée à Calais entre Édouard III et Philippe VI, suspendant temporairement les hostilités de la Guerre de Cent Ans.', 'La Guerre de Cent Ans : Batailles, Héroïnes et Monarchies', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.172377+00', NULL, NULL, NULL, ''),
	(448, 'Signature du traité de Brétigny', 1360, false, NULL, 'Le 8 mai 1360, le traité de Brétigny est signé entre la France et l''Angleterre. Jean II est libéré contre une rançon colossale et la cession de vastes territoires français à Édouard III.', 'La Guerre de Cent Ans : Batailles, Héroïnes et Monarchies', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.172377+00', NULL, NULL, NULL, ''),
	(449, 'Reprise de Pontvalain par Du Guesclin', 1370, false, NULL, 'Le 4 décembre 1370, Bertrand Du Guesclin écrase les forces anglaises à Pontvalain, ouvrant la reconquête du Maine et de l''Anjou pour Charles V.', 'La Guerre de Cent Ans : Batailles, Héroïnes et Monarchies', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.172377+00', NULL, NULL, NULL, ''),
	(451, 'Reprise de Limoges par Charles V', 1370, false, NULL, 'En 1370, après le sac brutal de Limoges par le Prince Noir, Charles V reprend progressivement le contrôle de la ville et de la région.', 'La Guerre de Cent Ans : Batailles, Héroïnes et Monarchies', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.172377+00', NULL, NULL, NULL, ''),
	(452, 'Traité d''alliance franco-castillan de Tolède', 1368, false, NULL, 'Le 18 mars 1368, Charles V signe un traité avec Henri de Trastamare, roi de Castille, assurant un soutien naval castillan contre l''Angleterre.', 'La Guerre de Cent Ans : Batailles, Héroïnes et Monarchies', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.172377+00', NULL, NULL, NULL, ''),
	(453, 'Victoire navale franco-castillane à La Rochelle', 1372, false, NULL, 'Le 22 juin 1372, la flotte franco-castillane détruit la flotte anglaise au large de La Rochelle, coupant l''Angleterre de ses possessions françaises.', 'La Guerre de Cent Ans : Batailles, Héroïnes et Monarchies', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.172377+00', NULL, NULL, NULL, ''),
	(454, 'Reprise de Poitiers par les Français', 1372, false, NULL, 'En août 1372, Du Guesclin reprend Poitiers aux Anglais, marquant la reconquête quasi totale du Poitou par Charles V.', 'La Guerre de Cent Ans : Batailles, Héroïnes et Monarchies', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.172377+00', NULL, NULL, NULL, ''),
	(455, 'Mort de Bertrand Du Guesclin au siège de Châteauneuf-de-Randon', 1380, false, NULL, 'Le 13 juillet 1380, Bertrand Du Guesclin meurt devant Châteauneuf-de-Randon, mettant fin à la carrière du principal artisan de la reconquête française.', 'La Guerre de Cent Ans : Batailles, Héroïnes et Monarchies', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.172377+00', NULL, NULL, NULL, ''),
	(456, 'Mort de Charles V le Sage', 1380, false, NULL, 'Le 16 septembre 1380, Charles V meurt à Beauté-sur-Marne, laissant un royaume largement reconquis sur les Anglais après une décennie de succès militaires.', 'La Guerre de Cent Ans : Batailles, Héroïnes et Monarchies', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.172377+00', NULL, NULL, NULL, ''),
	(457, 'Reprise de Bergerac par Du Guesclin', 1377, false, NULL, 'En 1377, Du Guesclin reprend Bergerac en Périgord, poursuivant la reconquête systématique des territoires aquitains tenus par les Anglais.', 'La Guerre de Cent Ans : Batailles, Héroïnes et Monarchies', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.172377+00', NULL, NULL, NULL, ''),
	(458, 'Débarquement de Henri V en Normandie', 1415, false, NULL, 'Le 14 août 1415, Henri V débarque à l''embouchure de la Seine avec une armée d''environ 12 000 hommes. Il entame ainsi sa campagne de conquête du royaume de France.', 'La Guerre de Cent Ans : Batailles, Héroïnes et Monarchies', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.172377+00', NULL, NULL, NULL, ''),
	(459, 'Prise de Harfleur par les Anglais', 1415, false, NULL, 'Le 22 septembre 1415, Henri V s''empare de la ville portuaire de Harfleur en Normandie après un siège de cinq semaines. Cette conquête lui offre une tête de pont stratégique sur le continent.', 'La Guerre de Cent Ans : Batailles, Héroïnes et Monarchies', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.172377+00', NULL, NULL, NULL, ''),
	(460, 'Assassinat de Jean sans Peur à Montereau', 1419, false, NULL, 'Le 10 septembre 1419, Jean sans Peur, duc de Bourgogne, est assassiné sur le pont de Montereau lors d''une entrevue avec le dauphin Charles. Cet événement pousse les Bourguignons à s''allier avec les Anglais.', 'La Guerre de Cent Ans : Batailles, Héroïnes et Monarchies', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.172377+00', NULL, NULL, NULL, ''),
	(461, 'Mariage de Henri V et Catherine de Valois', 1420, false, NULL, 'Le 2 juin 1420, Henri V d''Angleterre épouse Catherine de Valois, fille de Charles VI, à Troyes. Cette union scelle l''alliance franco-anglaise prévue par le traité de Troyes.', 'La Guerre de Cent Ans : Batailles, Héroïnes et Monarchies', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.172377+00', NULL, NULL, NULL, ''),
	(462, 'Entrée triomphale de Henri V dans Paris', 1420, false, NULL, 'Le 1er décembre 1420, Henri V entre solennellement dans Paris aux côtés de Charles VI. Il est acclamé comme futur roi de France en vertu du traité de Troyes.', 'La Guerre de Cent Ans : Batailles, Héroïnes et Monarchies', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.172377+00', NULL, NULL, NULL, ''),
	(463, 'Prise de Rouen par Henri V', 1419, false, NULL, 'Le 19 janvier 1419, Henri V s''empare de Rouen, capitale de la Normandie, après un siège de six mois. Cette conquête majeure consolide la domination anglaise sur la Normandie.', 'La Guerre de Cent Ans : Batailles, Héroïnes et Monarchies', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.172377+00', NULL, NULL, NULL, ''),
	(464, 'Début du siège d''Orléans par les Anglais', 1428, false, NULL, 'Le 12 octobre 1428, les forces anglaises commencent le siège d''Orléans, ville stratégique dont la chute aurait scellé la défaite française dans la guerre de Cent Ans.', 'La Guerre de Cent Ans : Batailles, Héroïnes et Monarchies', '', 'IMAGE_DONE', 'Main subject: A group of English soldiers laying siege to the city of Orléans.  
Action/Context: The soldiers are setting up their siege equipment and preparing for an assault on the fortified city walls.  
Specific historical details: The soldiers are clad in chainmail and leather armor, with woolen tunics and cloaks. The siege equipment includes wooden catapults and battering rams, made of sturdy timber and iron fittings. The city walls are constructed of large stone blocks, showing signs of wear from previous conflicts.  
Visual style: Historical oil painting in a classical museum style.  
Composition/Light: The scene is illuminated by the natural light of the setting sun, casting long shadows and creating a dramatic atmosphere, with flickering torches providing additional light in the foreground.', '2026-03-04 07:23:47.172377+00', NULL, NULL, NULL, 'http://127.0.0.1:54321/storage/v1/object/public/evenements-image/evt_464_debut_du_siege_d_orleans_par_les_anglais_1772268677378.webp'),
	(465, 'Première rencontre de Jeanne d''Arc avec le dauphin Charles', 1429, false, NULL, 'Le 9 mars 1429, Jeanne d''Arc rencontre le dauphin Charles VII à Chinon, le convainquant de lui confier une armée pour lever le siège d''Orléans.', 'La Guerre de Cent Ans : Batailles, Héroïnes et Monarchies', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.172377+00', NULL, NULL, NULL, ''),
	(466, 'Victoire française à la bataille de Patay', 1429, false, NULL, 'Le 18 juin 1429, les Français écrasent l''armée anglaise à Patay, capturant le général Talbot et ouvrant la route vers Reims pour le sacre du dauphin.', 'La Guerre de Cent Ans : Batailles, Héroïnes et Monarchies', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.172377+00', NULL, NULL, NULL, ''),
	(468, 'Bataille de Formigny : victoire décisive française', 1450, false, NULL, 'Le 15 avril 1450, l''armée française écrase les forces anglaises à Formigny, en Normandie, scellant définitivement la reconquête de la province.', 'La Guerre de Cent Ans : Batailles, Héroïnes et Monarchies', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.172377+00', NULL, NULL, NULL, ''),
	(469, 'Reddition de Caen aux troupes de Charles VII', 1450, false, NULL, 'Le 24 juin 1450, la ville de Caen capitule devant les armées françaises, achevant la libération totale de la Normandie après des décennies d''occupation.', 'La Guerre de Cent Ans : Batailles, Héroïnes et Monarchies', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.172377+00', NULL, NULL, NULL, ''),
	(470, 'Capitulation de Cherbourg, dernier bastion anglais en Normandie', 1450, false, NULL, 'Le 12 août 1450, Cherbourg tombe aux mains des Français, marquant la fin complète de la présence anglaise en Normandie.', 'La Guerre de Cent Ans : Batailles, Héroïnes et Monarchies', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.172377+00', NULL, NULL, NULL, ''),
	(471, 'Création des préfectures départementales', 1800, false, NULL, 'Le 17 février 1800, la loi du 28 pluviôse An VIII institue les préfets à la tête de chaque département. Cette réforme centralise l''administration territoriale française sous l''autorité de l''État.', 'Les Guerres Napoléoniennes : De l''Ascension à la Chute de l''Empire', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.172377+00', NULL, NULL, NULL, ''),
	(472, 'Création de la Légion d''honneur', 1802, false, NULL, 'Le 19 mai 1802, Napoléon Bonaparte institue la Légion d''honneur pour récompenser les mérites civils et militaires. Cet ordre national existe toujours et demeure la plus haute distinction française.', 'Les Guerres Napoléoniennes : De l''Ascension à la Chute de l''Empire', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.172377+00', NULL, NULL, NULL, ''),
	(473, 'Création des lycées napoléoniens', 1802, false, NULL, 'Le 1er mai 1802, la loi Fourcroy crée les lycées en France, remplaçant les écoles centrales révolutionnaires. Ces établissements d''enseignement secondaire forment les futures élites administratives et militaires.', 'Les Guerres Napoléoniennes : De l''Ascension à la Chute de l''Empire', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.172377+00', NULL, NULL, NULL, ''),
	(474, 'Signature du traité de Presbourg', 1805, false, NULL, 'Le 26 décembre 1805, l''Autriche signe ce traité humiliant après Austerlitz. Elle cède la Vénétie au royaume d''Italie et le Tyrol à la Bavière, alliée de Napoléon.', 'Les Guerres Napoléoniennes : De l''Ascension à la Chute de l''Empire', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.172377+00', NULL, NULL, NULL, ''),
	(475, 'Proclamation du blocus continental', 1806, false, NULL, 'Le 21 novembre 1806, depuis Berlin, Napoléon décrète le blocus continental interdisant tout commerce entre l''Europe et la Grande-Bretagne. Cette mesure vise à asphyxier économiquement l''ennemi britannique.', 'Les Guerres Napoléoniennes : De l''Ascension à la Chute de l''Empire', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.172377+00', NULL, NULL, NULL, ''),
	(476, 'Victoire française à la bataille d''Iéna', 1806, false, NULL, 'Le 14 octobre 1806, Napoléon écrase l''armée prussienne à Iéna tandis que Davout triomphe à Auerstedt le même jour. La Prusse s''effondre en quelques semaines.', 'Les Guerres Napoléoniennes : De l''Ascension à la Chute de l''Empire', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.172377+00', NULL, NULL, NULL, ''),
	(477, 'Création de la Confédération du Rhin', 1806, false, NULL, 'Le 12 juillet 1806, seize États allemands signent l''acte fondateur de la Confédération du Rhin sous protectorat français. Cela entraîne la dissolution du Saint-Empire romain germanique.', 'Les Guerres Napoléoniennes : De l''Ascension à la Chute de l''Empire', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.172377+00', NULL, NULL, NULL, ''),
	(478, 'Dissolution du Saint-Empire romain germanique', 1806, false, NULL, 'Le 6 août 1806, l''empereur François II abdique et renonce au titre d''empereur romain germanique. Une institution millénaire prend fin sous la pression de la domination napoléonienne.', 'Les Guerres Napoléoniennes : De l''Ascension à la Chute de l''Empire', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.172377+00', NULL, NULL, NULL, ''),
	(479, 'Victoire française à la bataille d''Eylau', 1807, false, NULL, 'Le 8 février 1807, Napoléon affronte les Russes et Prussiens en Prusse-Orientale dans une bataille sanglante et indécise. Ce combat difficile révèle la résistance de l''armée russe.', 'Les Guerres Napoléoniennes : De l''Ascension à la Chute de l''Empire', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.172377+00', NULL, NULL, NULL, ''),
	(480, 'Victoire décisive française à la bataille de Friedland', 1807, false, NULL, 'Le 14 juin 1807, Napoléon écrase l''armée russe du général Bennigsen en Prusse-Orientale. Cette victoire contraint le tsar Alexandre Ier à négocier la paix.', 'Les Guerres Napoléoniennes : De l''Ascension à la Chute de l''Empire', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.172377+00', NULL, NULL, NULL, ''),
	(481, 'Signature des traités de Tilsit', 1807, false, NULL, 'Les 7 et 9 juillet 1807, Napoléon signe des traités avec la Russie puis la Prusse sur un radeau au milieu du Niémen. L''Europe est redessinée : création du grand-duché de Varsovie et du royaume de Westphalie.', 'Les Guerres Napoléoniennes : De l''Ascension à la Chute de l''Empire', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.172377+00', NULL, NULL, NULL, ''),
	(482, 'Couronnement de Joseph Bonaparte roi de Naples', 1806, false, NULL, 'Le 30 mars 1806, Napoléon place son frère Joseph sur le trône du royaume de Naples. Cette décision illustre la politique napoléonienne de contrôle de l''Europe par des souverains familiaux.', 'Les Guerres Napoléoniennes : De l''Ascension à la Chute de l''Empire', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.172377+00', NULL, NULL, NULL, ''),
	(483, 'Adoption de la Constitution française de 1791', 1791, false, NULL, 'Le 3 septembre 1791, l''Assemblée constituante adopte la première constitution écrite de France, instaurant une monarchie constitutionnelle et limitant officiellement les pouvoirs du roi.', 'La Révolution Française : De la Bastille à la Chute de Robespierre', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.172377+00', NULL, NULL, NULL, ''),
	(484, 'Acceptation de la Constitution par Louis XVI', 1791, false, NULL, 'Le 14 septembre 1791, Louis XVI prête serment devant l''Assemblée nationale et accepte formellement la Constitution, devenant roi des Français sous un régime constitutionnel.', 'La Révolution Française : De la Bastille à la Chute de Robespierre', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.172377+00', NULL, NULL, NULL, ''),
	(485, 'Première réunion de l''Assemblée législative', 1791, false, NULL, 'Le 1er octobre 1791, l''Assemblée législative tient sa première séance, succédant à l''Assemblée constituante pour gouverner la France sous le nouveau régime constitutionnel.', 'La Révolution Française : De la Bastille à la Chute de Robespierre', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.172377+00', NULL, NULL, NULL, ''),
	(486, 'Déclaration de guerre à l''Autriche', 1792, false, NULL, 'Le 20 avril 1792, la France révolutionnaire déclare la guerre au roi de Bohême et de Hongrie, lançant les guerres de la Révolution française qui vont bouleverser l''Europe.', 'La Révolution Française : De la Bastille à la Chute de Robespierre', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.172377+00', NULL, NULL, NULL, ''),
	(487, 'Première utilisation de la guillotine en France', 1792, false, NULL, 'Le 25 avril 1792, la guillotine est utilisée pour la première fois pour exécuter le brigand Nicolas Jacques Pelletier, devenant bientôt le symbole de la Terreur révolutionnaire.', 'La Révolution Française : De la Bastille à la Chute de Robespierre', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.172377+00', NULL, NULL, NULL, ''),
	(895, 'Naissance de Maria Teresa Agnesi Pinottini', 1720, false, NULL, 'Compositrice, claveciniste et chanteuse italienne. Elle composa des opéras, des œuvres pour clavier et de la musique vocale.', 'L''Âge d''Or de la Piraterie', '', 'PENDING', '', '2026-03-04 07:23:47.283022+00', NULL, NULL, NULL, ''),
	(488, 'Création du Tribunal révolutionnaire', 1793, false, NULL, 'Le 10 mars 1793, la Convention nationale institue le Tribunal révolutionnaire chargé de juger les ennemis de la République. Il deviendra l''instrument principal de la Terreur.', 'La Révolution Française : De la Bastille à la Chute de Robespierre', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.187938+00', NULL, NULL, NULL, ''),
	(489, 'Proclamation de la loi des suspects', 1793, false, NULL, 'Le 17 septembre 1793, la Convention vote la loi des suspects permettant l''arrestation de toute personne jugée hostile à la Révolution. Elle ouvre officiellement la période de la Grande Terreur.', 'La Révolution Française : De la Bastille à la Chute de Robespierre', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.187938+00', NULL, NULL, NULL, ''),
	(490, 'Exécution de Georges Danton', 1794, false, NULL, 'Le 5 avril 1794, Georges Danton et ses partisans indulgents sont guillotinés sur ordre de Robespierre. La mort de cet ancien pilier de la Révolution illustre la radicalisation extrême du régime.', 'La Révolution Française : De la Bastille à la Chute de Robespierre', '', 'READY_FOR_IMAGE', 'A tense scene set on April 5, 1794, depicting the execution of Georges Danton at the guillotine. Danton, a robust man in his forties, is shown in a somber, tattered coat typical of the revolutionary fervor, with his hair styled in the fashion of the late 18th century. His expression is one of defiance and resignation as he stands before the imposing guillotine, surrounded by a crowd of indifferent onlookers wearing period-appropriate attire, including women in simple dresses and men in tricorne hats. The atmosphere is heavy with tension, illuminated by a dim, overcast sky casting a gray light over the grim scene, emphasizing the somber mood of the event. The crowd''s expressions range from curiosity to grim satisfaction, reflecting the radicalization of the time. The composition captures the moment just before the blade falls, highlighting the historical significance of this execution. Photorealistic, cinematic lighting, highly detailed, 8k resolution, historical painting.', '2026-03-04 07:23:47.187938+00', NULL, NULL, NULL, ''),
	(491, 'Adoption de la loi du 22 prairial', 1794, false, NULL, 'Le 10 juin 1794, la loi du 22 prairial an II supprime les droits de la défense devant le Tribunal révolutionnaire. Elle déclenche la Grande Terreur, période d''exécutions massives en quelques semaines.', 'La Révolution Française : De la Bastille à la Chute de Robespierre', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.187938+00', NULL, NULL, NULL, ''),
	(492, 'Premier survol de la Lune par une sonde spatiale (Luna 1)', 1959, false, NULL, 'Le 2 janvier 1959, la sonde soviétique Luna 1 devient le premier engin à s''échapper de l''attraction terrestre et à survoler la Lune.', 'L''Aventure Spatiale : Des Premiers Satellites à l''Exploration Interplanétaire', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.187938+00', NULL, NULL, NULL, ''),
	(493, 'Première photographie de la face cachée de la Lune (Luna 3)', 1959, false, NULL, 'Le 7 octobre 1959, la sonde soviétique Luna 3 transmet les premières images de la face cachée de la Lune, jusque-là totalement inconnue.', 'L''Aventure Spatiale : Des Premiers Satellites à l''Exploration Interplanétaire', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.187938+00', NULL, NULL, NULL, ''),
	(494, 'Catastrophe de la mission Apollo 1', 1967, false, NULL, 'Le 27 janvier 1967, un incendie éclate dans la capsule Apollo 1 lors d''un test au sol, tuant les trois astronautes Gus Grissom, Ed White et Roger Chaffee.', 'L''Aventure Spatiale : Des Premiers Satellites à l''Exploration Interplanétaire', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.187938+00', NULL, NULL, NULL, ''),
	(495, 'Lancement de l''observatoire spatial Compton', 1991, false, NULL, 'Le 5 avril 1991, la NASA met en orbite le Compton Gamma Ray Observatory depuis la navette Atlantis. Il permettra d''étudier les sources de rayons gamma les plus énergétiques de l''univers.', 'L''Aventure Spatiale : Des Premiers Satellites à l''Exploration Interplanétaire', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.187938+00', NULL, NULL, NULL, ''),
	(496, 'Lancement de l''observatoire infrarouge ISO', 1995, false, NULL, 'Le 17 novembre 1995, l''Agence Spatiale Européenne lance l''Infrared Space Observatory (ISO). Cet observatoire spatial étudiera l''univers dans le domaine infrarouge jusqu''en 1998.', 'L''Aventure Spatiale : Des Premiers Satellites à l''Exploration Interplanétaire', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.187938+00', NULL, NULL, NULL, ''),
	(497, 'Lancement de l''observatoire spatial Chandra', 1999, false, NULL, 'Le 23 juillet 1999, la NASA lance l''observatoire à rayons X Chandra depuis la navette Columbia. Il devient l''un des quatre grands observatoires spatiaux de la NASA, scrutant les phénomènes les plus violents de l''univers.', 'L''Aventure Spatiale : Des Premiers Satellites à l''Exploration Interplanétaire', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.187938+00', NULL, NULL, NULL, ''),
	(498, 'Lancement du télescope spatial Hipparcos', 1989, false, NULL, 'Le 8 août 1989, l''ESA lance le satellite Hipparcos depuis Kourou. Premier observatoire spatial dédié à l''astrométrie, il mesurera avec précision la position et la distance de plus de 100 000 étoiles.', 'L''Aventure Spatiale : Des Premiers Satellites à l''Exploration Interplanétaire', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.187938+00', NULL, NULL, NULL, ''),
	(499, 'Lancement de la sonde Mars Climate Orbiter', 1998, false, NULL, 'La NASA lance Mars Climate Orbiter le 11 décembre 1998 pour étudier le climat martien. La sonde sera perdue en septembre 1999 à cause d''une erreur de conversion d''unités métriques/impériales.', 'L''Aventure Spatiale : Des Premiers Satellites à l''Exploration Interplanétaire', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.187938+00', NULL, NULL, NULL, ''),
	(500, 'Perte de Mars Climate Orbiter lors de son insertion orbitale', 1999, false, NULL, 'Le 23 septembre 1999, Mars Climate Orbiter est détruite en entrant dans l''atmosphère martienne à cause d''une confusion entre unités métriques et impériales, causant une perte de 327 millions de dollars.', 'L''Aventure Spatiale : Des Premiers Satellites à l''Exploration Interplanétaire', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.187938+00', NULL, NULL, NULL, ''),
	(501, 'Lancement de Mars Polar Lander', 1999, false, NULL, 'La NASA lance Mars Polar Lander le 3 janvier 1999, destiné à se poser près du pôle sud de Mars. La sonde disparaît sans laisser de traces lors de sa tentative d''atterrissage en décembre 1999.', 'L''Aventure Spatiale : Des Premiers Satellites à l''Exploration Interplanétaire', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.187938+00', NULL, NULL, NULL, ''),
	(502, 'Lancement de la sonde Mars Odyssey', 2001, false, NULL, 'La NASA lance Mars Odyssey le 7 avril 2001. La sonde entre en orbite martienne en octobre 2001 et détecte des indices de glace d''eau sous la surface, révolutionnant notre compréhension de Mars.', 'L''Aventure Spatiale : Des Premiers Satellites à l''Exploration Interplanétaire', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.187938+00', NULL, NULL, NULL, ''),
	(503, 'Détection de glace d''eau sous la surface de Mars par Mars Odyssey', 2002, false, NULL, 'Le 28 mai 2002, la NASA annonce que la sonde Mars Odyssey a détecté d''importantes quantités de glace d''eau sous la surface martienne, notamment dans les régions polaires.', 'L''Aventure Spatiale : Des Premiers Satellites à l''Exploration Interplanétaire', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.187938+00', NULL, NULL, NULL, ''),
	(504, 'Lancement de la sonde Mars Express de l''ESA', 2003, false, NULL, 'L''Agence Spatiale Européenne lance Mars Express le 2 juin 2003, première mission européenne vers Mars. Elle emporte le petit atterrisseur Beagle 2 et entre en orbite martienne en décembre 2003.', 'L''Aventure Spatiale : Des Premiers Satellites à l''Exploration Interplanétaire', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.187938+00', NULL, NULL, NULL, ''),
	(896, 'Début du règne de Jean V du Portugal', 1706, false, NULL, 'Jean V accède au trône portugais. Son règne est marqué par le faste et le mécénat artistique, grâce aux richesses provenant du Brésil.', 'L''Âge d''Or de la Piraterie', '', 'PENDING', '', '2026-03-04 07:23:47.283022+00', NULL, NULL, NULL, ''),
	(505, 'Lancement du rover Spirit vers Mars', 2003, false, NULL, 'La NASA lance le rover Spirit le 10 juin 2003 dans le cadre du programme Mars Exploration Rover. Spirit atterrira sur Mars le 4 janvier 2004 et explorera le cratère Gusev.', 'L''Aventure Spatiale : Des Premiers Satellites à l''Exploration Interplanétaire', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.187938+00', NULL, NULL, NULL, ''),
	(506, 'Lancement du rover Opportunity vers Mars', 2003, false, NULL, 'La NASA lance le rover Opportunity le 7 juillet 2003, jumeau de Spirit. Il atterrit le 25 janvier 2004 dans Meridiani Planum et découvrira des preuves d''eau liquide ancienne sur Mars.', 'L''Aventure Spatiale : Des Premiers Satellites à l''Exploration Interplanétaire', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.187938+00', NULL, NULL, NULL, ''),
	(507, 'Atterrissage du rover Spirit sur Mars', 2004, false, NULL, 'Le 4 janvier 2004, le rover Spirit de la NASA atterrit avec succès dans le cratère Gusev sur Mars, commençant une mission d''exploration géologique qui durera bien au-delà de sa durée prévue de 90 jours.', 'L''Aventure Spatiale : Des Premiers Satellites à l''Exploration Interplanétaire', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.187938+00', NULL, NULL, NULL, ''),
	(508, 'Atterrissage du rover Opportunity sur Mars', 2004, false, NULL, 'Le 25 janvier 2004, le rover Opportunity atterrit dans Meridiani Planum sur Mars. Il découvre rapidement des sphérules d''hématite surnommées ''myrtilles'', preuve d''une présence passée d''eau liquide.', 'L''Aventure Spatiale : Des Premiers Satellites à l''Exploration Interplanétaire', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.187938+00', NULL, NULL, NULL, ''),
	(509, 'Annonce de la découverte de méthane dans l''atmosphère de Mars', 2004, false, NULL, 'Le 30 mars 2004, des scientifiques annoncent la détection de méthane dans l''atmosphère martienne grâce à Mars Express et des télescopes terrestres, soulevant des questions sur une possible activité biologique ou géologique.', 'L''Aventure Spatiale : Des Premiers Satellites à l''Exploration Interplanétaire', '', 'READY_FOR_IMAGE', 'A group of scientists in a modern research facility, intently examining screens displaying data from Mars Express and ground-based telescopes. The room is illuminated by bright overhead lights and the glow of computer monitors, creating a focused atmosphere. The scientists, dressed in lab coats and casual attire, exhibit a mix of excitement and concentration. In the background, large windows reveal a view of a starry night sky visible through the facility''s glass walls. A digital representation of Mars and its atmosphere, with swirling clouds and a hint of methane, is projected on a screen. The overall ambiance is one of discovery and anticipation, capturing the moment of a groundbreaking announcement. photorealistic, cinematic lighting, highly detailed, 8k resolution, documentary style.', '2026-03-04 07:23:47.187938+00', NULL, NULL, NULL, ''),
	(510, 'Première sortie extravéhiculaire depuis l''ISS sans navette amarrée', 2004, false, NULL, 'Le 26 février 2004, les astronautes de l''ISS effectuent une sortie extravéhiculaire sans navette spatiale amarrée, une première dans l''histoire de la station, dans le contexte post-Columbia.', 'L''Aventure Spatiale : Des Premiers Satellites à l''Exploration Interplanétaire', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.187938+00', NULL, NULL, NULL, ''),
	(511, 'Lancement de la sonde Mars Reconnaissance Orbiter', 2005, false, NULL, 'La NASA lance Mars Reconnaissance Orbiter le 12 août 2005. Équipée de la caméra HiRISE la plus puissante jamais envoyée vers Mars, elle entre en orbite en mars 2006 pour cartographier la planète en haute résolution.', 'L''Aventure Spatiale : Des Premiers Satellites à l''Exploration Interplanétaire', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.187938+00', NULL, NULL, NULL, ''),
	(512, 'Mise en service du télescope spatial COROT dédié aux exoplanètes', 2006, false, NULL, 'Le 27 décembre 2006, le CNES lance le satellite COROT, premier télescope spatial conçu pour détecter des exoplanètes par la méthode des transits.', 'L''Aventure Spatiale : Des Premiers Satellites à l''Exploration Interplanétaire', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.187938+00', NULL, NULL, NULL, ''),
	(513, 'Lancement du télescope spatial Kepler pour la chasse aux exoplanètes', 2009, false, NULL, 'Le 6 mars 2009, la NASA lance le télescope Kepler, dédié à la recherche de planètes de type terrestre autour d''autres étoiles grâce à la méthode des transits.', 'L''Aventure Spatiale : Des Premiers Satellites à l''Exploration Interplanétaire', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.187938+00', NULL, NULL, NULL, ''),
	(514, 'Publication des premiers résultats scientifiques du télescope Kepler', 2010, false, NULL, 'En janvier 2010, la NASA publie les premières données de Kepler révélant des centaines de candidats exoplanètes, marquant un tournant dans la recherche de mondes extrasolaires.', 'L''Aventure Spatiale : Des Premiers Satellites à l''Exploration Interplanétaire', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.187938+00', NULL, NULL, NULL, ''),
	(516, 'Fondation de Macao comme comptoir portugais en Chine', 1557, false, NULL, 'En 1557, le Portugal obtient l''autorisation d''établir un comptoir permanent à Macao, sur la côte sud de la Chine. Ce port devient la porte d''entrée du commerce européen avec la Chine et le Japon.', 'L''Âge des Grandes Découvertes : Explorations, Conquêtes et Nouvelles Routes', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.187938+00', NULL, NULL, NULL, ''),
	(517, 'Fondation de Batavia par la VOC en Indonésie', 1619, false, NULL, 'Le 30 mai 1619, Jan Pieterszoon Coen fonde Batavia (actuelle Jakarta) sur l''île de Java. La ville devient le quartier général de la VOC en Asie et le centre névralgique du commerce des épices.', 'L''Âge des Grandes Découvertes : Explorations, Conquêtes et Nouvelles Routes', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.187938+00', NULL, NULL, NULL, ''),
	(518, 'Fondation du comptoir français de Pondichéry en Inde', 1674, false, NULL, 'Le 4 février 1674, François Martin fonde le comptoir de Pondichéry sur la côte de Coromandel en Inde. Il deviendra la capitale des établissements français en Inde et un centre commercial majeur.', 'L''Âge des Grandes Découvertes : Explorations, Conquêtes et Nouvelles Routes', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.187938+00', NULL, NULL, NULL, ''),
	(519, 'Charte royale accordée à la Compagnie anglaise des Indes pour Bombay', 1668, false, NULL, 'En 1668, Charles II cède Bombay à la East India Company pour une location symbolique. La ville devient rapidement le principal port anglais en Inde, supplantant Surat dans le commerce asiatique.', 'L''Âge des Grandes Découvertes : Explorations, Conquêtes et Nouvelles Routes', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.187938+00', NULL, NULL, NULL, ''),
	(520, 'Fondation de la Compagnie danoise des Indes orientales', 1616, false, NULL, 'Le 17 mars 1616, le roi Christian IV du Danemark fonde la Dansk Ostindisk Kompagni. Elle établit des comptoirs en Inde, notamment à Tranquebar en 1620, participant à la course aux routes commerciales asiatiques.', 'L''Âge des Grandes Découvertes : Explorations, Conquêtes et Nouvelles Routes', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.187938+00', NULL, NULL, NULL, ''),
	(521, 'Massacre d''Amboine : éviction des Anglais des Moluques par la VOC', 1623, false, NULL, 'Le 27 février 1623, la VOC exécute dix marchands anglais de la East India Company à Amboine (Moluques). Cet événement force les Anglais à se concentrer sur l''Inde, redéfinissant les zones d''influence commerciales en Asie.', 'L''Âge des Grandes Découvertes : Explorations, Conquêtes et Nouvelles Routes', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.187938+00', NULL, NULL, NULL, ''),
	(522, 'Départ de la Croisade des Pauvres menée par Pierre l''Ermite', 1096, false, NULL, 'En avril 1096, des milliers de pèlerins non armés, conduits par Pierre l''Ermite, quittent la France vers Constantinople avant l''armée officielle. Cette croisade populaire se solde par un désastre face aux Turcs en Anatolie.', 'Les Croisades : Conflits, Pèlerinages et États Latins d''Orient', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.187938+00', NULL, NULL, NULL, ''),
	(523, 'Massacre des Juifs de Mayence par des croisés', 1096, false, NULL, 'Le 27 mai 1096, des bandes de croisés rhénans massacrent la communauté juive de Mayence, l''une des plus importantes d''Europe. Cet épisode marque le début de violentes persécutions antijuives liées aux croisades.', 'Les Croisades : Conflits, Pèlerinages et États Latins d''Orient', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.187938+00', NULL, NULL, NULL, ''),
	(524, 'Prise d''Antioche par les croisés', 1098, false, NULL, 'Le 3 juin 1098, après un siège de huit mois, les armées de la Première Croisade s''emparent d''Antioche en Syrie. La ville devient un enjeu stratégique majeur sur la route vers Jérusalem.', 'Les Croisades : Conflits, Pèlerinages et États Latins d''Orient', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.187938+00', NULL, NULL, NULL, ''),
	(525, 'Fondation de l''ordre des Hospitaliers de Saint-Jean', 1113, false, NULL, 'Le 15 février 1113, le pape Pascal II reconnaît officiellement l''ordre des Hospitaliers de Saint-Jean de Jérusalem par une bulle pontificale. Cet ordre militaire et hospitalier jouera un rôle central dans les croisades.', 'Les Croisades : Conflits, Pèlerinages et États Latins d''Orient', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.187938+00', NULL, NULL, NULL, ''),
	(526, 'Départ de la Croisade des Enfants', 1212, false, NULL, 'En 1212, des milliers d''enfants et de jeunes gens, menés par Étienne de Cloyes en France et Nicolas de Cologne en Allemagne, partent en croisade vers Jérusalem. La plupart ne reviendront jamais, vendus comme esclaves ou morts en chemin.', 'Les Croisades : Conflits, Pèlerinages et États Latins d''Orient', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.187938+00', NULL, NULL, NULL, ''),
	(527, 'Création du Comté d''Édesse', 1098, false, NULL, 'Le 10 mars 1098, Baudouin de Boulogne prend le contrôle d''Édesse et fonde le Comté d''Édesse, premier État croisé établi en Terre sainte.', 'Les Croisades : Conflits, Pèlerinages et États Latins d''Orient', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.187938+00', NULL, NULL, NULL, ''),
	(528, 'Couronnement de Baudouin Ier comme roi de Jérusalem', 1100, false, NULL, 'Le 25 décembre 1100, Baudouin Ier est couronné roi de Jérusalem en la basilique de Bethléem, premier à porter officiellement le titre royal du Royaume latin.', 'Les Croisades : Conflits, Pèlerinages et États Latins d''Orient', '', 'IMAGE_DONE', 'A grand scene depicting the crowning of Baudouin I as king of Jerusalem, taking place in a large stone hall adorned with tapestries and banners. The hall is filled with nobles and clergy, all dressed in rich, flowing garments made of wool and linen, with intricate embroidery. Baudouin, wearing a regal crown of gold and a long, ornate robe, kneels before a priest who holds a gilded cross. Candles flicker on wrought iron sconces, casting warm light across the faces of the attendees. The atmosphere is solemn and reverent, evoking a sense of historical significance. The scene is captured in an authentic historical oil painting in a classical museum style, emphasizing the grandeur of the moment and the rich textures of the fabrics and stone architecture.', '2026-03-04 07:23:47.187938+00', NULL, NULL, NULL, 'http://127.0.0.1:54321/storage/v1/object/public/evenements-image/evt_528_couronnement_de_baudouin_ier_comme_roi_d_1772268688124.webp'),
	(529, 'Fondation du Comté de Tripoli', 1109, false, NULL, 'Le 12 juillet 1109, Bertrand de Saint-Gilles s''empare de Tripoli et fonde le Comté de Tripoli, dernier des quatre grands États latins d''Orient à être établi.', 'Les Croisades : Conflits, Pèlerinages et États Latins d''Orient', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.187938+00', NULL, NULL, NULL, ''),
	(530, 'Victoire croisée à la bataille d''Ascalon', 1099, false, NULL, 'Le 12 août 1099, les croisés remportent la bataille d''Ascalon face aux Fatimides égyptiens, consolidant leur emprise sur la région de Jérusalem nouvellement conquise.', 'Les Croisades : Conflits, Pèlerinages et États Latins d''Orient', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.187938+00', NULL, NULL, NULL, ''),
	(531, 'Prise de Haïfa par les croisés', 1100, false, NULL, 'En juillet 1100, les croisés s''emparent de la ville portuaire de Haïfa, étendant le contrôle du Royaume de Jérusalem sur la côte méditerranéenne.', 'Les Croisades : Conflits, Pèlerinages et États Latins d''Orient', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.187938+00', NULL, NULL, NULL, ''),
	(532, 'Signature du Traité de Bruxelles fondant l''Union occidentale', 1948, false, NULL, 'Le 17 mars 1948, la France, le Royaume-Uni et les pays du Benelux signent le Traité de Bruxelles, créant une alliance militaire collective. Ce pacte préfigure directement la création de l''OTAN.', 'Les Temps Forts de la Guerre Froide : Crises, Tensions et Dégel', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.187938+00', NULL, NULL, NULL, ''),
	(533, 'Proclamation de la République fédérale d''Allemagne (RFA)', 1949, false, NULL, 'Le 23 mai 1949, la Loi fondamentale entre en vigueur et la RFA est officiellement créée dans les zones d''occupation occidentales. Konrad Adenauer en devient le premier chancelier en septembre.', 'Les Temps Forts de la Guerre Froide : Crises, Tensions et Dégel', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.187938+00', NULL, NULL, NULL, ''),
	(534, 'Proclamation de la République démocratique allemande (RDA)', 1949, false, NULL, 'Le 7 octobre 1949, l''URSS proclame la création de la République démocratique allemande dans sa zone d''occupation. L''Allemagne se retrouve officiellement divisée en deux États antagonistes.', 'Les Temps Forts de la Guerre Froide : Crises, Tensions et Dégel', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.187938+00', NULL, NULL, NULL, ''),
	(535, 'Début de la construction du mur de Berlin', 1961, false, NULL, 'Dans la nuit du 12 au 13 août 1961, la RDA commence à ériger des barbelés puis un mur de béton divisant Berlin en deux. Cette barrière symbolise le rideau de fer séparant l''Est et l''Ouest.', 'Les Temps Forts de la Guerre Froide : Crises, Tensions et Dégel', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.187938+00', NULL, NULL, NULL, ''),
	(536, 'Mort du premier fugitif au mur de Berlin (Peter Fechter)', 1962, false, NULL, 'Le 17 août 1962, Peter Fechter, 18 ans, est abattu par des gardes-frontières est-allemands en tentant de franchir le mur. Il agonise pendant une heure sous les yeux des passants, devenant un symbole tragique de la division.', 'Les Temps Forts de la Guerre Froide : Crises, Tensions et Dégel', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.187938+00', NULL, NULL, NULL, ''),
	(537, 'Installation du téléphone rouge entre Washington et Moscou', 1963, false, NULL, 'Le 30 août 1963, une ligne de communication directe est établie entre la Maison-Blanche et le Kremlin, suite à la crise des missiles de Cuba. Ce ''téléphone rouge'' vise à prévenir tout malentendu pouvant déclencher un conflit nucléaire.', 'Les Temps Forts de la Guerre Froide : Crises, Tensions et Dégel', '', 'IMAGE_DONE', 'A historical representation of the installation of the red telephone between Washington and Moscow in 1963, featuring dignitaries from both nations engaged in serious discussion. The setting is a formal room adorned with wooden furniture and thick drapes, reflecting the tension and significance of the moment. The officials are dressed in tailored suits made of wool and linen, with vintage accessories typical of the early 1960s, such as ties and hats, avoiding modern fastenings. The scene is captured in vintage color film still style, with warm, soft lighting coming from a large window, illuminating the room and casting gentle shadows, emphasizing the gravity of this historic event.', '2026-03-04 07:23:47.187938+00', NULL, NULL, NULL, 'http://127.0.0.1:54321/storage/v1/object/public/evenements-image/evt_537_installation_du_telephone_rouge_entre_wa_1772268685203.webp'),
	(538, 'Discours ''Ich bin ein Berliner'' de Kennedy', 1963, false, NULL, 'Le 26 juin 1963, le président américain John F. Kennedy prononce son célèbre discours devant 450 000 Berlinois de l''Ouest, affirmant sa solidarité avec la ville divisée face à la menace soviétique.', 'Les Temps Forts de la Guerre Froide : Crises, Tensions et Dégel', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.187938+00', NULL, NULL, NULL, ''),
	(539, 'Première traversée du mur de Berlin par un tunnel (Tunnel 57)', 1964, false, NULL, 'En octobre 1964, 57 personnes s''évadent de Berlin-Est via un tunnel de 145 mètres creusé sous le mur, baptisé ''Tunnel 57''. C''est l''une des évasions collectives les plus importantes de l''histoire du mur.', 'Les Temps Forts de la Guerre Froide : Crises, Tensions et Dégel', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.202153+00', NULL, NULL, NULL, ''),
	(540, 'Ouverture de la Conférence sur la Sécurité et la Coopération en Europe (CSCE)', 1973, false, NULL, 'Le 3 juillet 1973, 35 nations se réunissent à Helsinki pour ouvrir la CSCE, processus diplomatique visant à réduire les tensions entre l''Est et l''Ouest en Europe.', 'Les Temps Forts de la Guerre Froide : Crises, Tensions et Dégel', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.202153+00', NULL, NULL, NULL, ''),
	(541, 'Signature du traité SALT II entre Carter et Brejnev', 1979, false, NULL, 'Le 18 juin 1979 à Vienne, Jimmy Carter et Léonid Brejnev signent SALT II, limitant à 2 400 le nombre de vecteurs nucléaires stratégiques de chaque superpuissance.', 'Les Temps Forts de la Guerre Froide : Crises, Tensions et Dégel', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.202153+00', NULL, NULL, NULL, ''),
	(542, 'Retrait du traité SALT II par le Sénat américain', 1980, false, NULL, 'En janvier 1980, Carter retire le traité SALT II du Sénat américain après l''invasion soviétique de l''Afghanistan en décembre 1979, mettant fin à la ratification du texte.', 'Les Temps Forts de la Guerre Froide : Crises, Tensions et Dégel', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.202153+00', NULL, NULL, NULL, ''),
	(543, 'Première réunion de suivi des Accords d''Helsinki à Belgrade', 1977, false, NULL, 'Le 4 octobre 1977, s''ouvre à Belgrade la première conférence de suivi des Accords d''Helsinki, où les pays occidentaux dénoncent les violations soviétiques des droits de l''homme.', 'Les Temps Forts de la Guerre Froide : Crises, Tensions et Dégel', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.202153+00', NULL, NULL, NULL, ''),
	(544, 'Création du Groupe Helsinki de Moscou pour les droits de l''homme', 1976, false, NULL, 'Le 12 mai 1976, Youri Orlov fonde à Moscou le Groupe Helsinki, première organisation soviétique de surveillance du respect des droits de l''homme issus des Accords d''Helsinki.', 'Les Temps Forts de la Guerre Froide : Crises, Tensions et Dégel', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.202153+00', NULL, NULL, NULL, ''),
	(545, 'Invasion soviétique de l''Afghanistan', 1979, false, NULL, 'Le 24 décembre 1979, l''armée soviétique envahit l''Afghanistan, déclenchant une guerre qui durera dix ans. Cette intervention marque un tournant majeur de la Guerre froide.', 'Les Temps Forts de la Guerre Froide : Crises, Tensions et Dégel', '', 'IMAGE_DONE', 'Soviet soldiers in military uniforms of the late 1970s, engaged in combat with Afghan resistance fighters in traditional attire made of wool and linen. The scene captures the tense atmosphere of the invasion, with soldiers maneuvering through rugged mountainous terrain, surrounded by rocky outcrops and sparse vegetation. The historical context is emphasized by the presence of Soviet military vehicles, such as armored personnel carriers, and the use of traditional Afghan tools and weapons. The visual style is reminiscent of vintage color film stills from the late 20th century. Natural sunlight illuminates the scene, casting dramatic shadows and highlighting the expressions on the faces of both the Soviet and Afghan fighters.', '2026-03-04 07:23:47.202153+00', NULL, NULL, NULL, 'http://127.0.0.1:54321/storage/v1/object/public/evenements-image/chambre_noire_invasion_sovi_tique_de_l_afgha_1772267178485.webp'),
	(546, 'Assassinat du président afghan Hafizullah Amin', 1979, false, NULL, 'Le 27 décembre 1979, les forces spéciales soviétiques prennent d''assaut le palais de Tajbeg à Kaboul et tuent le président Amin, le remplaçant par Babrak Karmal.', 'Les Temps Forts de la Guerre Froide : Crises, Tensions et Dégel', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.202153+00', NULL, NULL, NULL, ''),
	(547, 'Boycott américain des Jeux olympiques de Moscou', 1980, false, NULL, 'Le 20 janvier 1980, le président Carter annonce le boycott des Jeux olympiques de Moscou en réponse à l''invasion soviétique de l''Afghanistan. 65 pays suivront cet appel.', 'Les Temps Forts de la Guerre Froide : Crises, Tensions et Dégel', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.202153+00', NULL, NULL, NULL, ''),
	(548, 'Début du financement américain des moudjahidines afghans', 1980, false, NULL, 'En janvier 1980, la CIA lance l''opération Cyclone, fournissant armes et financement aux résistants afghans combattant l''occupation soviétique, avec le soutien du Pakistan et de l''Arabie Saoudite.', 'Les Temps Forts de la Guerre Froide : Crises, Tensions et Dégel', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.202153+00', NULL, NULL, NULL, ''),
	(549, 'Élection de Ronald Reagan à la présidence américaine', 1980, false, NULL, 'Le 4 novembre 1980, Ronald Reagan remporte l''élection présidentielle américaine face à Jimmy Carter, inaugurant une politique étrangère nettement plus agressive envers l''URSS.', 'Les Temps Forts de la Guerre Froide : Crises, Tensions et Dégel', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.202153+00', NULL, NULL, NULL, ''),
	(551, 'Discours de Reagan qualifiant l''URSS d''Empire du Mal', 1983, false, NULL, 'Le 8 mars 1983, Ronald Reagan prononce devant l''Association nationale des évangéliques son célèbre discours qualifiant l''Union soviétique d''« Empire du Mal », radicalisant le discours de la Guerre froide.', 'Les Temps Forts de la Guerre Froide : Crises, Tensions et Dégel', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.202153+00', NULL, NULL, NULL, ''),
	(552, 'Annonce de l''Initiative de Défense Stratégique (IDS)', 1983, false, NULL, 'Le 23 mars 1983, le président Reagan annonce l''Initiative de Défense Stratégique, surnommée « Guerre des étoiles », un programme visant à développer un bouclier antimissile spatial pour protéger les États-Unis.', 'Les Temps Forts de la Guerre Froide : Crises, Tensions et Dégel', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.202153+00', NULL, NULL, NULL, ''),
	(553, 'Destruction du vol Korean Air Lines 007 par l''URSS', 1983, false, NULL, 'Le 1er septembre 1983, un chasseur soviétique abat le Boeing 747 de la Korean Air Lines au-dessus de la mer du Japon, tuant 269 personnes, aggravant gravement les tensions entre les superpuissances.', 'Les Temps Forts de la Guerre Froide : Crises, Tensions et Dégel', '', 'IMAGE_DONE', 'A Korean Air Lines passenger aircraft from the early 1980s, depicted in the moments just before its destruction over the sea, surrounded by Soviet military jets. The scene captures the tension of the Cold War era, with the aircraft featuring a fuselage made of metal and windows that are round and small, typical of the time. The Soviet jets are shown in aggressive formation, with their sleek designs highlighted against a dramatic sky. The setting is filled with a sense of impending doom, as dark clouds loom overhead. The visual style is vintage color film still, evoking the period''s aesthetic. Natural light filters through the clouds, casting a somber glow on the scene, emphasizing the gravity of the event.', '2026-03-04 07:23:47.202153+00', NULL, NULL, NULL, 'http://127.0.0.1:54321/storage/v1/object/public/evenements-image/evt_553_destruction_du_vol_korean_air_lines_007__1772268690552.webp'),
	(554, 'Déploiement des missiles Pershing II en Europe occidentale', 1983, false, NULL, 'En novembre 1983, les États-Unis commencent le déploiement de missiles balistiques Pershing II en Allemagne de l''Ouest, en réponse aux SS-20 soviétiques, provoquant de vives protestations en Europe.', 'Les Temps Forts de la Guerre Froide : Crises, Tensions et Dégel', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.202153+00', NULL, NULL, NULL, ''),
	(555, 'Retrait soviétique des négociations de Genève', 1983, false, NULL, 'Le 23 novembre 1983, l''URSS suspend les négociations sur le contrôle des armements à Genève en réponse au déploiement des missiles Pershing II par l''OTAN en Europe occidentale.', 'Les Temps Forts de la Guerre Froide : Crises, Tensions et Dégel', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.202153+00', NULL, NULL, NULL, ''),
	(556, 'Fondation de l''Église réformée de Zurich par Zwingli', 1525, false, NULL, 'Le 13 avril 1525, Ulrich Zwingli célèbre la première Cène réformée à Zurich, marquant la fondation officielle de l''Église réformée suisse. Une branche distincte du luthéranisme naît.', 'La Réforme Protestante et les Guerres de Religion', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.202153+00', NULL, NULL, NULL, ''),
	(557, 'Publication de la Bible de Genève en anglais', 1560, false, NULL, 'En avril 1560, la Bible de Genève est publiée en anglais, devenant la première Bible protestante largement diffusée en Angleterre et influençant profondément la Réforme anglaise.', 'La Réforme Protestante et les Guerres de Religion', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.202153+00', NULL, NULL, NULL, ''),
	(558, 'Excommunication d''Élisabeth I par le pape', 1570, false, NULL, 'Le 25 février 1570, le pape Pie V excommunie la reine Élisabeth I par la bulle Regnans in Excelsis, déclarant ses sujets catholiques déliés de toute obéissance envers elle.', 'La Réforme Protestante et les Guerres de Religion', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.202153+00', NULL, NULL, NULL, ''),
	(559, 'Publication de la Bible en allemand par Luther', 1534, false, NULL, 'En septembre 1534, Martin Luther achève la traduction complète de la Bible en allemand. Cette œuvre unifie la langue allemande et diffuse massivement les idées protestantes.', 'La Réforme Protestante et les Guerres de Religion', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.202153+00', NULL, NULL, NULL, ''),
	(560, 'Bataille de la Montagne Blanche', 1620, false, NULL, 'Le 8 novembre 1620, les forces catholiques de la Ligue battent les protestants bohémiens près de Prague, mettant fin à la révolte bohémienne et renforçant la domination des Habsbourg.', 'La Réforme Protestante et les Guerres de Religion', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.202153+00', NULL, NULL, NULL, ''),
	(561, 'Édit de Restitution de Ferdinand II', 1629, false, NULL, 'Le 6 mars 1629, l''empereur Ferdinand II promulgue l''Édit de Restitution, ordonnant la restitution aux catholiques des biens ecclésiastiques sécularisés depuis 1552, exacerbant les tensions religieuses.', 'La Réforme Protestante et les Guerres de Religion', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.202153+00', NULL, NULL, NULL, ''),
	(562, 'Entrée en guerre de la Suède dans la guerre de Trente Ans', 1630, false, NULL, 'En juillet 1630, le roi Gustave II Adolphe de Suède débarque en Poméranie avec son armée, changeant le cours de la guerre de Trente Ans en faveur des protestants.', 'La Réforme Protestante et les Guerres de Religion', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.202153+00', NULL, NULL, NULL, ''),
	(563, 'Paix de Prague mettant fin à la phase allemande', 1635, false, NULL, 'Le 30 mai 1635, la paix de Prague est signée entre l''empereur Ferdinand II et la plupart des princes protestants allemands, tentant de mettre fin aux conflits internes de l''Empire.', 'La Réforme Protestante et les Guerres de Religion', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.202153+00', NULL, NULL, NULL, ''),
	(564, 'Ouverture des négociations de paix à Münster et Osnabrück', 1644, false, NULL, 'En décembre 1644, s''ouvrent officiellement les congrès de paix dans les villes westphaliennes de Münster et Osnabrück, réunissant pour la première fois une grande conférence diplomatique européenne.', 'La Réforme Protestante et les Guerres de Religion', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.202153+00', NULL, NULL, NULL, ''),
	(565, 'Première démonstration publique du télégraphe électrique (Morse)', 1844, false, NULL, 'Le 24 mai 1844, Samuel Morse envoie le premier message télégraphique officiel ''What hath God wrought'' entre Washington et Baltimore, inaugurant l''ère des communications électriques.', 'L''Ère de la Communication de Masse : Du Télégraphe à l''Avènement d''Internet', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.202153+00', NULL, NULL, NULL, ''),
	(566, 'Mise en service du câble télégraphique transatlantique permanent', 1866, false, NULL, 'Le 27 juillet 1866, le Great Eastern pose avec succès un câble télégraphique durable entre l''Irlande et Terre-Neuve, établissant une liaison permanente entre les deux continents.', 'L''Ère de la Communication de Masse : Du Télégraphe à l''Avènement d''Internet', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.202153+00', NULL, NULL, NULL, ''),
	(567, 'Première liaison téléphonique entre Paris et Bruxelles', 1887, false, NULL, 'En mars 1887, une ligne téléphonique internationale est établie entre Paris et Bruxelles, marquant le début des communications téléphoniques transfrontalières en Europe.', 'L''Ère de la Communication de Masse : Du Télégraphe à l''Avènement d''Internet', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.202153+00', NULL, NULL, NULL, ''),
	(568, 'Inauguration du réseau téléphonique de Paris', 1879, false, NULL, 'En 1879, la Société Générale des Téléphones installe le premier réseau téléphonique parisien, connectant les premiers abonnés français à ce nouveau moyen de communication.', 'L''Ère de la Communication de Masse : Du Télégraphe à l''Avènement d''Internet', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.202153+00', NULL, NULL, NULL, ''),
	(569, 'Première liaison télégraphique entre l''Europe et l''Inde', 1865, false, NULL, 'En 1865, le câble télégraphique reliant l''Europe à l''Inde via la Perse est achevé, réduisant le délai de transmission des messages de plusieurs semaines à quelques heures.', 'L''Ère de la Communication de Masse : Du Télégraphe à l''Avènement d''Internet', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.202153+00', NULL, NULL, NULL, ''),
	(570, 'Première émission de voix humaine par radio', 1906, false, NULL, 'Le 24 décembre 1906, Reginald Fessenden diffuse depuis Brant Rock (Massachusetts) la première émission radiophonique incluant de la voix et de la musique. Des opérateurs radio en mer captent ce signal historique.', 'L''Ère de la Communication de Masse : Du Télégraphe à l''Avènement d''Internet', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.202153+00', NULL, NULL, NULL, ''),
	(571, 'Création de la BBC Radio', 1927, false, NULL, 'Le 1er janvier 1927, la British Broadcasting Corporation (BBC) reçoit sa charte royale et devient une société publique indépendante. Elle s''impose rapidement comme un modèle mondial de radiodiffusion de service public.', 'L''Ère de la Communication de Masse : Du Télégraphe à l''Avènement d''Internet', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.202153+00', NULL, NULL, NULL, ''),
	(572, 'Diffusion radiophonique de ''La Guerre des Mondes'' (Orson Welles)', 1938, false, NULL, 'Le 30 octobre 1938, Orson Welles diffuse sur CBS une adaptation radiophonique de ''La Guerre des Mondes'' présentée comme un bulletin d''information réel. L''émission provoque une panique collective aux États-Unis.', 'L''Ère de la Communication de Masse : Du Télégraphe à l''Avènement d''Internet', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.202153+00', NULL, NULL, NULL, ''),
	(588, 'Création du langage de programmation C++ par Bjarne Stroustrup', 1983, false, NULL, 'En 1983, Bjarne Stroustrup finalise et nomme officiellement le langage C++, une évolution orientée objet du langage C. Ce langage deviendra l''un des plus utilisés dans le développement de logiciels professionnels.', 'L''Ère de la Communication de Masse : Du Télégraphe à l''Avènement d''Internet', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.202153+00', NULL, NULL, NULL, ''),
	(589, 'Lancement du premier navigateur commercial Netscape Navigator', 1994, false, NULL, 'Le 13 octobre 1994, Netscape Communications lance Netscape Navigator, qui devient rapidement le navigateur web dominant avec plus de 90% de parts de marché. Il popularise massivement l''usage d''Internet auprès du grand public.', 'L''Ère de la Communication de Masse : Du Télégraphe à l''Avènement d''Internet', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.202153+00', NULL, NULL, NULL, ''),
	(897, 'Naissance de Carl Philipp Emanuel Bach', 1714, false, NULL, 'Compositeur et claveciniste allemand, fils de Johann Sebastian Bach. Il fut une figure importante de la période de transition entre le baroque et le classicisme.', 'L''Âge d''Or de la Piraterie', '', 'PENDING', '', '2026-03-04 07:23:47.283022+00', NULL, NULL, NULL, ''),
	(573, 'Première émission de télévision aux États-Unis lors de l''Exposition universelle', 1939, false, NULL, 'Le 30 avril 1939, le président Franklin D. Roosevelt est le premier chef d''État américain filmé à la télévision lors de l''ouverture de l''Exposition universelle de New York. NBC inaugure ainsi son service télévisé régulier.', 'L''Ère de la Communication de Masse : Du Télégraphe à l''Avènement d''Internet', '', 'IMAGE_DONE', '[Main Subject]: A group of early television pioneers, including engineers and broadcasters, gathered in a dimly lit studio, adjusting heavy bakelite switches and tiny rounded screens while discussing the groundbreaking live broadcast.  
[Historical Tech & Materials]: The room is filled with vacuum tubes, large wooden cabinets, and vintage microphones, all made of heavy metals and solid wood. The backdrop features a classic wooden desk adorned with linen and thick wool materials.  
[Clothing & Style]: The men wear tailored suits with high-waisted trousers and wide lapels, while the women don knee-length dresses with fitted bodices and flared skirts, all styled with vintage hairstyles featuring soft waves and pinned curls. No visible zippers.  
[Visual Aesthetic]: Authentic black and white grainy photography of the era, capturing the essence of the moment in a nostalgic manner.  
[Atmosphere]: The lighting is a mix of gas lamps and early filament bulbs, creating a warm, inviting glow that enhances the historic ambiance of the scene.', '2026-03-04 07:23:47.202153+00', NULL, NULL, NULL, 'http://127.0.0.1:54321/storage/v1/object/public/evenements-image/evt_573_premiere_emission_de_television_aux_etat_1772268693298.webp'),
	(574, 'Reprise des émissions télévisées de la BBC après la guerre', 1946, false, NULL, 'Le 7 juin 1946, la BBC reprend ses émissions télévisées interrompues depuis 1939, avec la rediffusion symbolique du programme exact qui avait été coupé. C''est le signal de la renaissance de la télévision en Europe.', 'L''Ère de la Communication de Masse : Du Télégraphe à l''Avènement d''Internet', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.202153+00', NULL, NULL, NULL, ''),
	(575, 'Première retransmission télévisée d''un match de football en France', 1948, false, NULL, 'Le 19 décembre 1948, la RTF retransmet en direct le premier match de football télévisé en France depuis le Parc des Princes. Cet événement annonce l''avènement du sport spectacle à la télévision.', 'L''Ère de la Communication de Masse : Du Télégraphe à l''Avènement d''Internet', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.202153+00', NULL, NULL, NULL, ''),
	(576, 'Première émission de télévision en couleur expérimentale (CBS)', 1950, false, NULL, 'Le 25 juin 1950, CBS diffuse la première émission de télévision en couleur aux États-Unis, approuvée par la FCC. Ce système mécanique sera rapidement supplanté par la technologie électronique RCA.', 'L''Ère de la Communication de Masse : Du Télégraphe à l''Avènement d''Internet', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.202153+00', NULL, NULL, NULL, ''),
	(577, 'Lancement du premier ordinateur personnel grand public (IBM PC)', 1981, false, NULL, 'Le 12 août 1981, IBM lance son Personal Computer (PC), propulsant l''informatique personnelle dans les foyers et les entreprises du monde entier. Ce modèle devient rapidement la référence mondiale du secteur.', 'L''Ère de la Communication de Masse : Du Télégraphe à l''Avènement d''Internet', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.202153+00', NULL, NULL, NULL, ''),
	(578, 'Commercialisation du premier Macintosh d''Apple', 1984, false, NULL, 'Le 24 janvier 1984, Apple présente et commercialise le Macintosh, premier ordinateur grand public doté d''une interface graphique et d''une souris. Il révolutionne l''expérience utilisateur en informatique.', 'L''Ère de la Communication de Masse : Du Télégraphe à l''Avènement d''Internet', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.202153+00', NULL, NULL, NULL, ''),
	(579, 'Lancement du premier navigateur web grand public (Mosaic)', 1993, false, NULL, 'En avril 1993, le navigateur Mosaic est rendu disponible gratuitement, permettant pour la première fois de naviguer sur le web avec des images intégrées au texte. Il démocratise massivement l''accès à Internet.', 'L''Ère de la Communication de Masse : Du Télégraphe à l''Avènement d''Internet', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.202153+00', NULL, NULL, NULL, ''),
	(580, 'Création du système d''exploitation MS-DOS par Microsoft', 1981, false, NULL, 'En août 1981, Microsoft fournit le système d''exploitation MS-DOS à IBM pour équiper ses PC, s''imposant comme le logiciel de référence de l''informatique personnelle. Cette décision propulse Microsoft au sommet de l''industrie.', 'L''Ère de la Communication de Masse : Du Télégraphe à l''Avènement d''Internet', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.202153+00', NULL, NULL, NULL, ''),
	(581, 'Lancement du premier moteur de recherche web (WebCrawler)', 1994, false, NULL, 'Le 20 avril 1994, WebCrawler est lancé, devenant le premier moteur de recherche capable d''indexer le contenu complet des pages web. Il ouvre la voie à une nouvelle façon de trouver l''information en ligne.', 'L''Ère de la Communication de Masse : Du Télégraphe à l''Avènement d''Internet', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.202153+00', NULL, NULL, NULL, ''),
	(582, 'Mise en service du réseau ARPANET, ancêtre d''Internet', 1983, false, NULL, 'Le 1er janvier 1983, ARPANET adopte officiellement le protocole TCP/IP, acte fondateur de l''Internet moderne. Cette transition unifie les réseaux informatiques et pose les bases de la communication numérique mondiale.', 'L''Ère de la Communication de Masse : Du Télégraphe à l''Avènement d''Internet', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.202153+00', NULL, NULL, NULL, ''),
	(583, 'Lancement du premier assistant personnel numérique grand public (Apple Newton)', 1993, false, NULL, 'Le 3 août 1993, Apple commercialise le Newton MessagePad, premier assistant numérique personnel (PDA) grand public. Bien qu''imparfait, il préfigure l''ère des appareils mobiles intelligents.', 'L''Ère de la Communication de Masse : Du Télégraphe à l''Avènement d''Internet', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.202153+00', NULL, NULL, NULL, ''),
	(584, 'Publication du premier virus informatique mondial (Brain)', 1986, false, NULL, 'En janvier 1986, le virus Brain est créé au Pakistan et se propage via des disquettes, devenant le premier virus informatique à toucher les PC à grande échelle. Il marque le début de la cybersécurité comme enjeu mondial.', 'L''Ère de la Communication de Masse : Du Télégraphe à l''Avènement d''Internet', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.202153+00', NULL, NULL, NULL, ''),
	(585, 'Lancement du premier service commercial d''accès à Internet (CompuServe)', 1989, false, NULL, 'En 1989, CompuServe ouvre son service d''accès en ligne au grand public américain, permettant pour la première fois à des particuliers de se connecter à des réseaux informatiques. Il préfigure les fournisseurs d''accès à Internet modernes.', 'L''Ère de la Communication de Masse : Du Télégraphe à l''Avènement d''Internet', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.202153+00', NULL, NULL, NULL, ''),
	(586, 'Sortie du système d''exploitation Windows 1.0 de Microsoft', 1985, false, NULL, 'Le 20 novembre 1985, Microsoft lance Windows 1.0, sa première interface graphique pour PC compatible IBM. Bien que rudimentaire, il pose les fondations de l''écosystème Windows qui dominera l''informatique mondiale.', 'L''Ère de la Communication de Masse : Du Télégraphe à l''Avènement d''Internet', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.202153+00', NULL, NULL, NULL, ''),
	(587, 'Lancement du premier CD-ROM grand public', 1985, false, NULL, 'En 1985, les premiers lecteurs et disques CD-ROM sont commercialisés pour le grand public, révolutionnant le stockage et la distribution de données numériques. Ce support remplacera progressivement la disquette dans l''informatique personnelle.', 'L''Ère de la Communication de Masse : Du Télégraphe à l''Avènement d''Internet', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.202153+00', NULL, NULL, NULL, ''),
	(590, 'Lancement de la première encyclopédie collaborative en ligne (Wikipédia)', 2001, false, NULL, 'Wikipédia est lancée officiellement le 15 janvier 2001 par Jimmy Wales et Larry Sanger. Ce projet collaboratif ouvert à tous transforme la diffusion du savoir.', 'L''Ère de la Communication de Masse : Du Télégraphe à l''Avènement d''Internet', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.213501+00', NULL, NULL, NULL, ''),
	(591, 'Ouverture du premier réseau social grand public (MySpace)', 2003, false, NULL, 'MySpace est lancé en août 2003 par Tom Anderson et Chris DeWolfe. Il devient le premier réseau social à atteindre une audience mondiale massive.', 'L''Ère de la Communication de Masse : Du Télégraphe à l''Avènement d''Internet', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.213501+00', NULL, NULL, NULL, ''),
	(592, 'Mise en ligne de la première plateforme de partage de vidéos (YouTube)', 2005, false, NULL, 'YouTube est fondé le 14 février 2005 par Chad Hurley, Steve Chen et Jawed Karim. La première vidéo y est mise en ligne le 23 avril 2005, marquant une révolution du contenu en ligne.', 'L''Ère de la Communication de Masse : Du Télégraphe à l''Avènement d''Internet', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.213501+00', NULL, NULL, NULL, ''),
	(593, 'Lancement du premier réseau social à identité réelle (Facebook)', 2004, false, NULL, 'Mark Zuckerberg lance TheFacebook.com le 4 février 2004 depuis l''université Harvard. La plateforme s''ouvre progressivement au grand public, redéfinissant les interactions sociales numériques.', 'L''Ère de la Communication de Masse : Du Télégraphe à l''Avènement d''Internet', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.213501+00', NULL, NULL, NULL, ''),
	(594, 'Commercialisation du premier smartphone grand public (iPhone)', 2007, false, NULL, 'Apple commercialise son premier téléphone tactile le 29 juin 2007 aux États-Unis. Cet appareil fusionne téléphone, iPod et navigateur web, inaugurant l''ère des smartphones modernes.', 'L''Ère de la Communication de Masse : Du Télégraphe à l''Avènement d''Internet', '', 'IMAGE_DONE', 'A group of diverse people gathered in a lively urban setting, eagerly unboxing the first iPhone, a sleek black device with a glass front and a metallic back. The scene is filled with excitement and curiosity as onlookers share their reactions to the groundbreaking technology. The year is 2007, with individuals dressed in casual clothing made of cotton and denim, reflecting the style of the early 2000s, while some wear accessories like canvas bags and sneakers. The visual style is reminiscent of vintage color film stills, capturing the vibrant atmosphere of the moment. Natural sunlight illuminates the scene, casting soft shadows and enhancing the sense of wonder and anticipation among the crowd.', '2026-03-04 07:23:47.213501+00', NULL, NULL, NULL, 'http://127.0.0.1:54321/storage/v1/object/public/evenements-image/evt_594_commercialisation_du_premier_smartphone__1772268669028.webp'),
	(595, 'Lancement de la première boutique d''applications mobiles (App Store)', 2008, false, NULL, 'Apple ouvre l''App Store le 10 juillet 2008, permettant aux développeurs de distribuer leurs applications directement aux utilisateurs. Ce modèle transforme l''économie numérique mobile.', 'L''Ère de la Communication de Masse : Du Télégraphe à l''Avènement d''Internet', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.213501+00', NULL, NULL, NULL, ''),
	(596, 'Création du premier service de microblogging mondial (Twitter)', 2006, false, NULL, 'Twitter est lancé publiquement le 15 juillet 2006 par Jack Dorsey, Biz Stone et Evan Williams. Le format des messages de 140 caractères crée un nouveau mode de communication instantanée.', 'L''Ère de la Communication de Masse : Du Télégraphe à l''Avènement d''Internet', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.213501+00', NULL, NULL, NULL, ''),
	(597, 'Lancement du premier service de stockage en nuage grand public (Dropbox)', 2008, false, NULL, 'Dropbox est lancé publiquement en septembre 2008 par Drew Houston et Arash Ferdowsi. Ce service inaugure l''ère du stockage et du partage de fichiers dans le cloud pour le grand public.', 'L''Ère de la Communication de Masse : Du Télégraphe à l''Avènement d''Internet', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.213501+00', NULL, NULL, NULL, ''),
	(598, 'Ouverture de la première plateforme de vente aux enchères en ligne (eBay)', 1995, false, NULL, 'Pierre Omidyar lance AuctionWeb, futur eBay, le 3 septembre 1995. La première vente est une imprimante laser défectueuse, marquant le début du commerce entre particuliers sur Internet.', 'L''Ère de la Communication de Masse : Du Télégraphe à l''Avènement d''Internet', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.213501+00', NULL, NULL, NULL, ''),
	(599, 'Lancement du premier service de streaming musical légal (Spotify)', 2008, false, NULL, 'Spotify est lancé en Europe le 7 octobre 2008 par Daniel Ek et Martin Lorentzon. Ce service de streaming musical légal propose un accès illimité à des millions de titres.', 'L''Ère de la Communication de Masse : Du Télégraphe à l''Avènement d''Internet', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.213501+00', NULL, NULL, NULL, ''),
	(600, 'Création du premier système d''exploitation mobile open source (Android)', 2008, false, NULL, 'Le premier téléphone sous Android, le HTC Dream, est commercialisé le 22 octobre 2008. Ce système d''exploitation open source de Google démocratise les smartphones à l''échelle mondiale.', 'L''Ère de la Communication de Masse : Du Télégraphe à l''Avènement d''Internet', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.213501+00', NULL, NULL, NULL, ''),
	(601, 'Lancement du premier service de vente en ligne à grande échelle (Amazon)', 1995, false, NULL, 'Amazon.com ouvre ses portes au public le 16 juillet 1995, fondé par Jeff Bezos. Initialement libraire en ligne, il pose les bases du commerce électronique moderne.', 'L''Ère de la Communication de Masse : Du Télégraphe à l''Avènement d''Internet', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.213501+00', NULL, NULL, NULL, ''),
	(603, 'Naissance de Tycho Brahe', 1546, false, NULL, 'L''astronome danois Tycho Brahe naît le 14 décembre 1546 à Knudstrup. Il deviendra le plus grand observateur du ciel à l''œil nu de l''histoire.', 'La Révolution Scientifique : Des Observations Célestes aux Lois de la Physique', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.213501+00', NULL, NULL, NULL, ''),
	(604, 'Construction de l''observatoire d''Uraniborg', 1576, false, NULL, 'Le roi Frédéric II de Danemark finance la construction d''Uraniborg sur l''île de Hven pour Tycho Brahe. Cet observatoire devient le plus avancé d''Europe avant l''invention du télescope.', 'La Révolution Scientifique : Des Observations Célestes aux Lois de la Physique', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.213501+00', NULL, NULL, NULL, ''),
	(605, 'Observation de la comète de 1577 par Tycho Brahe', 1577, false, NULL, 'Tycho Brahe observe minutieusement la grande comète de 1577 et démontre qu''elle se déplace au-delà de la Lune. Cela contredit la théorie des sphères cristallines d''Aristote.', 'La Révolution Scientifique : Des Observations Célestes aux Lois de la Physique', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.213501+00', NULL, NULL, NULL, ''),
	(606, 'Publication du catalogue stellaire de Tycho Brahe', 1598, false, NULL, 'Tycho Brahe achève son catalogue de 1 000 étoiles avec une précision sans précédent. Ce travail servira de base aux calculs de Kepler sur les orbites planétaires.', 'La Révolution Scientifique : Des Observations Célestes aux Lois de la Physique', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.213501+00', NULL, NULL, NULL, ''),
	(607, 'Mort de Tycho Brahe', 1601, false, NULL, 'Tycho Brahe meurt le 24 octobre 1601 à Prague, laissant ses précieuses données à Johannes Kepler. Ces observations permettront à Kepler de formuler ses lois du mouvement planétaire.', 'La Révolution Scientifique : Des Observations Célestes aux Lois de la Physique', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.213501+00', NULL, NULL, NULL, ''),
	(608, 'Retrait de l''œuvre de Copernic de l''Index des livres interdits', 1758, false, NULL, 'L''Église catholique retire ''De revolutionibus'' de Copernic de l''Index des livres interdits en 1758. Cette décision marque une reconnaissance progressive du modèle héliocentrique par les autorités religieuses.', 'La Révolution Scientifique : Des Observations Célestes aux Lois de la Physique', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.213501+00', NULL, NULL, NULL, ''),
	(609, 'Publication de l''Harmonices Mundi par Kepler', 1619, false, NULL, 'Kepler publie l''Harmonices Mundi, où il énonce sa troisième loi reliant la période orbitale d''une planète au cube de sa distance au Soleil. Cette loi complète le système des trois lois du mouvement planétaire.', 'La Révolution Scientifique : Des Observations Célestes aux Lois de la Physique', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.213501+00', NULL, NULL, NULL, ''),
	(610, 'Naissance de Johannes Kepler', 1571, false, NULL, 'Johannes Kepler naît le 27 décembre 1571 à Weil der Stadt, dans le Saint-Empire romain germanique. Il deviendra l''un des plus grands astronomes de l''histoire, fondateur de l''astronomie moderne.', 'La Révolution Scientifique : Des Observations Célestes aux Lois de la Physique', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.213501+00', NULL, NULL, NULL, ''),
	(611, 'Kepler nommé mathématicien impérial de Rodolphe II', 1601, false, NULL, 'Après la mort de Tycho Brahe, Johannes Kepler est nommé mathématicien impérial à la cour de l''empereur Rodolphe II à Prague. Ce poste lui offre les ressources nécessaires pour poursuivre ses recherches astronomiques.', 'La Révolution Scientifique : Des Observations Célestes aux Lois de la Physique', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.213501+00', NULL, NULL, NULL, ''),
	(612, 'Publication du Mysterium Cosmographicum par Kepler', 1596, false, NULL, 'Kepler publie son premier grand ouvrage astronomique, le Mysterium Cosmographicum, le 9 juillet 1596. Il y propose un modèle géométrique du système solaire basé sur les cinq solides platoniciens.', 'La Révolution Scientifique : Des Observations Célestes aux Lois de la Physique', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.213501+00', NULL, NULL, NULL, ''),
	(613, 'Mort de Johannes Kepler', 1630, false, NULL, 'Johannes Kepler meurt le 15 novembre 1630 à Ratisbonne, en Bavière. Il laisse derrière lui une œuvre fondamentale qui révolutionna la compréhension du mouvement des planètes et prépara le terrain pour Newton.', 'La Révolution Scientifique : Des Observations Célestes aux Lois de la Physique', '', 'IMAGE_DONE', 'A somber scene depicting the death of Johannes Kepler, surrounded by his books and celestial charts, as he lies on a wooden bed covered with a woolen blanket. The room is filled with shelves of aged leather-bound volumes and scrolls scattered on a stone table. Kepler, dressed in a simple linen shirt and a dark wool robe, is illuminated by the soft glow of flickering candlelight, casting gentle shadows on the rough stone walls. The atmosphere is heavy with the weight of his discoveries and the passage of time, captured in a historical oil painting in a classical museum style.', '2026-03-04 07:23:47.213501+00', NULL, NULL, NULL, 'http://127.0.0.1:54321/storage/v1/object/public/evenements-image/evt_613_mort_de_johannes_kepler_1772268671531.webp'),
	(614, 'Publication des Tables Rudolphines par Kepler', 1627, false, NULL, 'Kepler publie les Tables Rudolphines le 23 septembre 1627, des tables astronomiques d''une précision inégalée basées sur ses lois et les observations de Tycho Brahe. Elles permettent de prédire les positions planétaires avec une grande exactitude.', 'La Révolution Scientifique : Des Observations Célestes aux Lois de la Physique', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.213501+00', NULL, NULL, NULL, ''),
	(615, 'Publication des ''Lettres sur les taches solaires'' de Galilée', 1613, false, NULL, 'En 1613, Galilée publie ses observations sur les taches solaires, affirmant publiquement que le Soleil tourne sur lui-même et soutenant implicitement le modèle héliocentrique.', 'La Révolution Scientifique : Des Observations Célestes aux Lois de la Physique', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.213501+00', NULL, NULL, NULL, ''),
	(616, 'Première lettre copernicienne de Galilée à Benedetto Castelli', 1613, false, NULL, 'En décembre 1613, Galilée rédige une lettre défendant la compatibilité entre le modèle de Copernic et les Écritures, document qui sera utilisé contre lui par l''Inquisition.', 'La Révolution Scientifique : Des Observations Célestes aux Lois de la Physique', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.213501+00', NULL, NULL, NULL, ''),
	(617, 'Avertissement de l''Inquisition à Galilée', 1616, false, NULL, 'En février 1616, le cardinal Bellarmin avertit officiellement Galilée de ne plus défendre le système héliocentrique de Copernic, sous peine de poursuites ecclésiastiques.', 'La Révolution Scientifique : Des Observations Célestes aux Lois de la Physique', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.213501+00', NULL, NULL, NULL, ''),
	(618, 'Mise à l''Index de l''œuvre de Copernic par l''Église', 1616, false, NULL, 'En mars 1616, le ''De Revolutionibus'' de Copernic est placé à l''Index des livres interdits, marquant la condamnation officielle de l''héliocentrisme par l''Église catholique.', 'La Révolution Scientifique : Des Observations Célestes aux Lois de la Physique', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.213501+00', NULL, NULL, NULL, ''),
	(619, 'Publication de ''L''Essayeur'' de Galilée', 1623, false, NULL, 'En octobre 1623, Galilée publie ''Il Saggiatore'', manifeste de la méthode expérimentale affirmant que la nature est écrite en langage mathématique.', 'La Révolution Scientifique : Des Observations Célestes aux Lois de la Physique', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.213501+00', NULL, NULL, NULL, ''),
	(620, 'Naissance d''Isaac Newton', 1643, false, NULL, 'Isaac Newton naît le 4 janvier 1643 à Woolsthorpe, en Angleterre. Il deviendra l''un des plus grands scientifiques de l''histoire.', 'La Révolution Scientifique : Des Observations Célestes aux Lois de la Physique', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.213501+00', NULL, NULL, NULL, ''),
	(621, 'Observation de la comète de Halley par Edmond Halley', 1682, false, NULL, 'Edmond Halley observe la comète qui portera son nom et utilise plus tard les lois de Newton pour prédire son retour. Cette découverte valide la théorie gravitationnelle newtonienne.', 'La Révolution Scientifique : Des Observations Célestes aux Lois de la Physique', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.213501+00', NULL, NULL, NULL, ''),
	(622, 'Mort de Galilée', 1642, false, NULL, 'Galilée meurt le 8 janvier 1642 à Arcetri, en Italie. Ses travaux sur le mouvement des corps paveront la voie aux recherches de Newton sur la gravitation.', 'La Révolution Scientifique : Des Observations Célestes aux Lois de la Physique', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.213501+00', NULL, NULL, NULL, ''),
	(623, 'Mort de René Descartes', 1650, false, NULL, 'René Descartes meurt le 11 février 1650 à Stockholm. Sa philosophie mécaniste du cosmos influencera profondément les débats scientifiques auxquels Newton répondra avec sa gravitation.', 'La Révolution Scientifique : Des Observations Célestes aux Lois de la Physique', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.213501+00', NULL, NULL, NULL, ''),
	(624, 'Élection de Newton à la Royal Society', 1672, false, NULL, 'Isaac Newton est élu membre de la Royal Society le 11 janvier 1672, après avoir présenté son télescope à réflexion. Cette reconnaissance marque le début de sa carrière scientifique publique.', 'La Révolution Scientifique : Des Observations Célestes aux Lois de la Physique', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.213501+00', NULL, NULL, NULL, ''),
	(625, 'Mort d''Isaac Newton', 1727, false, NULL, 'Isaac Newton meurt le 31 mars 1727 à Kensington, en Angleterre. Il laisse un héritage scientifique immense, notamment sa loi de la gravitation universelle.', 'La Révolution Scientifique : Des Observations Célestes aux Lois de la Physique', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.213501+00', NULL, NULL, NULL, ''),
	(626, 'Naissance de Gottfried Wilhelm Leibniz', 1646, false, NULL, 'Gottfried Wilhelm Leibniz naît le 1er juillet 1646 à Leipzig. Il développera indépendamment le calcul infinitésimal, outil mathématique fondamental pour la mécanique newtonienne.', 'La Révolution Scientifique : Des Observations Célestes aux Lois de la Physique', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.213501+00', NULL, NULL, NULL, ''),
	(627, 'Publication de ''l''Opticks'' de Newton', 1704, false, NULL, 'Newton publie ''Opticks'' en 1704, exposant ses théories sur la lumière et les couleurs. Cet ouvrage complète son œuvre scientifique majeure initiée avec les Principia.', 'La Révolution Scientifique : Des Observations Célestes aux Lois de la Physique', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.213501+00', NULL, NULL, NULL, ''),
	(628, 'Naissance d''Edmond Halley', 1656, false, NULL, 'Edmond Halley naît le 8 novembre 1656 à Haggerston, en Angleterre. Il sera l''ami et le mécène de Newton, finançant la publication des Principia Mathematica.', 'La Révolution Scientifique : Des Observations Célestes aux Lois de la Physique', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.213501+00', NULL, NULL, NULL, ''),
	(629, 'Mobilisation générale de la Russie', 1914, false, NULL, 'Le 30 juillet 1914, le tsar Nicolas II ordonne la mobilisation générale de l''armée russe en soutien à la Serbie. Cette décision précipite l''entrée en guerre des grandes puissances européennes.', 'La Première Guerre Mondiale : Des Tensions Européennes à la Fin des Empires', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.213501+00', NULL, NULL, NULL, ''),
	(630, 'Signature de l''armistice de Compiègne', 1918, false, NULL, 'Le 11 novembre 1918 à 11h, l''armistice est signé dans un wagon à Compiègne, mettant fin aux combats de la Première Guerre mondiale. Après plus de quatre ans de guerre, le silence s''installe sur les fronts européens.', 'La Première Guerre Mondiale : Des Tensions Européennes à la Fin des Empires', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.213501+00', NULL, NULL, NULL, ''),
	(631, 'Assassinat de Raspoutine à Petrograd', 1916, false, NULL, 'Dans la nuit du 29 au 30 décembre 1916, le moine Grigori Raspoutine, figure controversée influençant la tsarine Alexandra, est assassiné par des nobles russes.', 'La Première Guerre Mondiale : Des Tensions Européennes à la Fin des Empires', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.213501+00', NULL, NULL, NULL, ''),
	(632, 'Début de la Révolution de Février à Petrograd', 1917, false, NULL, 'Le 23 février 1917 (calendrier julien), des grèves massives et des manifestations populaires éclatent à Petrograd, marquant le début de la révolution qui renversera le tsar.', 'La Première Guerre Mondiale : Des Tensions Européennes à la Fin des Empires', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.213501+00', NULL, NULL, NULL, ''),
	(633, 'Création du gouvernement provisoire russe', 1917, false, NULL, 'Le 2 mars 1917, un gouvernement provisoire dirigé par le prince Lvov est formé après l''abdication du tsar, tentant de maintenir l''ordre et de poursuivre la guerre.', 'La Première Guerre Mondiale : Des Tensions Européennes à la Fin des Empires', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.213501+00', NULL, NULL, NULL, ''),
	(634, 'Retour de Lénine en Russie via le train plombé', 1917, false, NULL, 'Le 3 avril 1917, Vladimir Lénine arrive à la gare de Finlande à Petrograd après un voyage en train traversant l''Allemagne, financé par Berlin pour déstabiliser la Russie.', 'La Première Guerre Mondiale : Des Tensions Européennes à la Fin des Empires', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.213501+00', NULL, NULL, NULL, ''),
	(635, 'Publication des Thèses d''Avril par Lénine', 1917, false, NULL, 'Le 4 avril 1917, Lénine publie ses Thèses d''Avril, appelant à la fin de la guerre et au transfert du pouvoir aux soviets, radicalisant le programme bolchevique.', 'La Première Guerre Mondiale : Des Tensions Européennes à la Fin des Empires', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.213501+00', NULL, NULL, NULL, ''),
	(636, 'Dissolution de l''Assemblée constituante russe par les bolcheviques', 1918, false, NULL, 'Le 6 janvier 1918, les bolcheviques dissolvent l''Assemblée constituante après une seule journée de session, car les socialistes-révolutionnaires y étaient majoritaires.', 'La Première Guerre Mondiale : Des Tensions Européennes à la Fin des Empires', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.213501+00', NULL, NULL, NULL, ''),
	(637, 'Transfert de la capitale russe de Petrograd à Moscou', 1918, false, NULL, 'Le 12 mars 1918, le gouvernement bolchevique déplace la capitale de Petrograd à Moscou, jugée plus sûre face à la menace allemande et aux armées blanches.', 'La Première Guerre Mondiale : Des Tensions Européennes à la Fin des Empires', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.213501+00', NULL, NULL, NULL, ''),
	(638, 'Attentat contre Lénine par Fanny Kaplan', 1918, false, NULL, 'Le 30 août 1918, la socialiste-révolutionnaire Fanny Kaplan tire sur Lénine à Moscou, le blessant grièvement et déclenchant la Terreur rouge bolchevique.', 'La Première Guerre Mondiale : Des Tensions Européennes à la Fin des Empires', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.213501+00', NULL, NULL, NULL, ''),
	(639, 'Proclamation de la Terreur rouge par le gouvernement soviétique', 1918, false, NULL, 'Le 5 septembre 1918, le Sovnarkom officialise la Terreur rouge, autorisant la Tchéka à exécuter massivement les opposants au régime bolchevique.', 'La Première Guerre Mondiale : Des Tensions Européennes à la Fin des Empires', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.213501+00', NULL, NULL, NULL, ''),
	(640, 'Fondation de l''Internationale communiste (Komintern) à Moscou', 1919, false, NULL, 'Le 2 mars 1919, Lénine fonde le Komintern à Moscou, une organisation internationale visant à coordonner les partis communistes du monde entier pour propager la révolution.', 'La Première Guerre Mondiale : Des Tensions Européennes à la Fin des Empires', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.213501+00', NULL, NULL, NULL, ''),
	(641, 'Raid viking sur le monastère de Jarrow', 794, false, NULL, 'Un an après Lindisfarne, les Vikings pillent le monastère de Jarrow en Northumbrie, célèbre pour avoir abrité le Vénérable Bède. Ce second raid confirme la menace nordique sur les côtes britanniques.', 'L''Épopée Viking : Des Raids en Mer du Nord aux Royaumes Scandes', '', 'IMAGE_DONE', 'Viking raiders storming the monastery of Jarrow, fierce expressions on their faces, clad in fur and chainmail, wielding axes and shields. The scene is set in the early morning light, casting dramatic shadows across the ancient stone buildings. In the background, the iconic structure of the monastery looms, with intricate stonework and a thatched roof. Smoke rises from the chaos, and frightened monks in simple robes flee in the foreground, their faces filled with terror. The atmosphere is tense and chaotic, capturing the brutality of the raid. Lush green fields surround the monastery, contrasting with the violence of the scene. Cinematic lighting, highly detailed, photorealistic, 8k resolution, historical painting.', '2026-03-04 07:23:47.22465+00', NULL, NULL, NULL, 'http://127.0.0.1:54321/storage/v1/object/public/evenements-image/chambre_noire_raid_viking_sur_le_monast_re_d_1772265694051.webp'),
	(642, 'Fondation de la ville de Hedeby par les Danois', 808, false, NULL, 'Le roi danois Gudfred fonde Hedeby (actuelle Allemagne du Nord), qui devient l''un des plus importants centres commerciaux vikings de la mer Baltique.', 'L''Épopée Viking : Des Raids en Mer du Nord aux Royaumes Scandes', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.22465+00', NULL, NULL, NULL, ''),
	(643, 'Baptême du roi danois Harald Klak', 826, false, NULL, 'Le roi danois Harald Klak est baptisé à Ingelheim am Rhein en présence de Louis le Pieux, premier baptême d''un souverain scandinave, ouvrant la christianisation du Nord.', 'L''Épopée Viking : Des Raids en Mer du Nord aux Royaumes Scandes', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.22465+00', NULL, NULL, NULL, ''),
	(644, 'Mort du roi Olaf II de Norvège à la bataille de Stiklestad', 1030, false, NULL, 'Le 29 juillet 1030, le roi Olaf II est tué à la bataille de Stiklestad en tentant de reconquérir son trône. Canonisé peu après, il devient le saint patron de la Norvège.', 'L''Épopée Viking : Des Raids en Mer du Nord aux Royaumes Scandes', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.22465+00', NULL, NULL, NULL, ''),
	(646, 'Rédaction du Livre de la Colonisation (Landnámabók)', 1100, false, NULL, 'Le Landnámabók, manuscrit islandais recensant les premiers colons de l''île, est rédigé vers cette date. Il constitue une source historique majeure sur la colonisation de l''Islande.', 'L''Épopée Viking : Des Raids en Mer du Nord aux Royaumes Scandes', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.22465+00', NULL, NULL, NULL, ''),
	(647, 'Découverte de l''Islande par le Viking Naddoðr', 861, false, NULL, 'Le Viking norvégien Naddoðr est l''un des premiers explorateurs scandinaves à atteindre l''Islande par accident, la nommant ''Snæland'' (Pays des neiges).', 'L''Épopée Viking : Des Raids en Mer du Nord aux Royaumes Scandes', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.22465+00', NULL, NULL, NULL, ''),
	(648, 'Exploration de l''Islande par le Viking Flóki Vilgerðarson', 868, false, NULL, 'Flóki Vilgerðarson est le premier Viking à naviguer délibérément vers l''Islande. Il lui donne son nom actuel ''Ísland'' (Pays des glaces) après un hiver particulièrement rigoureux.', 'L''Épopée Viking : Des Raids en Mer du Nord aux Royaumes Scandes', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.22465+00', NULL, NULL, NULL, ''),
	(649, 'Baptême du roi Harald à la Dent Bleue', 960, false, NULL, 'Le roi danois Harald Ier, dit ''Bluetooth'', est baptisé par le moine Poppo, marquant la conversion officielle du Danemark au christianisme. Cet événement est commémoré sur la pierre runique de Jelling.', 'L''Épopée Viking : Des Raids en Mer du Nord aux Royaumes Scandes', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.22465+00', NULL, NULL, NULL, ''),
	(650, 'Érection de la grande pierre runique de Jelling', 965, false, NULL, 'Harald à la Dent Bleue fait ériger la grande pierre runique de Jelling en l''honneur de ses parents et pour célébrer la christianisation du Danemark. Elle est surnommée le ''certificat de baptême du Danemark''.', 'L''Épopée Viking : Des Raids en Mer du Nord aux Royaumes Scandes', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.22465+00', NULL, NULL, NULL, ''),
	(651, 'Fondation de l''évêché de Schleswig', 948, false, NULL, 'L''évêché de Schleswig est fondé sous l''impulsion du roi Gorm l''Ancien et de l''Église franque, posant les premières bases institutionnelles du christianisme en territoire danois.', 'L''Épopée Viking : Des Raids en Mer du Nord aux Royaumes Scandes', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.22465+00', NULL, NULL, NULL, ''),
	(652, 'Mort du roi Harald à la Dent Bleue', 987, false, NULL, 'Harald Ier du Danemark, dit ''Bluetooth'', est tué lors d''une révolte menée par son propre fils Sven à la Barbe Fourchue. Il meurt en exil en Poméranie, mettant fin à son règne christianisateur.', 'L''Épopée Viking : Des Raids en Mer du Nord aux Royaumes Scandes', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.22465+00', NULL, NULL, NULL, ''),
	(653, 'Fondation de l''archevêché de Hambourg-Brême', 831, false, NULL, 'L''archevêché de Hambourg-Brême est fondé par Louis le Pieux pour évangéliser les peuples du Nord. Il devient le principal centre missionnaire vers la Scandinavie pendant deux siècles.', 'L''Épopée Viking : Des Raids en Mer du Nord aux Royaumes Scandes', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.22465+00', NULL, NULL, NULL, ''),
	(654, 'Première mission d''Ansgar en Scandinavie', 829, false, NULL, 'Le moine franc Ansgar, futur ''Apôtre du Nord'', effectue sa première mission en Suède à Birka. Il tente d''implanter le christianisme en Scandinavie avec un succès limité mais durable.', 'L''Épopée Viking : Des Raids en Mer du Nord aux Royaumes Scandes', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.22465+00', NULL, NULL, NULL, ''),
	(655, 'Conversion du roi Håkon le Bon de Norvège', 934, false, NULL, 'Håkon Ier de Norvège, élevé à la cour chrétienne d''Angleterre, tente d''introduire le christianisme en Norvège après son accession au trône. Sa tentative échoue face à la résistance des chefs vikings.', 'L''Épopée Viking : Des Raids en Mer du Nord aux Royaumes Scandes', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.22465+00', NULL, NULL, NULL, ''),
	(656, 'Début de la campagne d''Italie de Bonaparte', 1796, false, NULL, 'Le 27 mars 1796, Napoléon Bonaparte prend le commandement de l''armée d''Italie et lance une offensive fulgurante contre les forces austro-sardes.', 'L''Ère Napoléonienne : Des Campagnes d''Italie à Waterloo', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.22465+00', NULL, NULL, NULL, ''),
	(657, 'Victoire française à la bataille de Montenotte', 1796, false, NULL, 'Le 12 avril 1796, Bonaparte remporte sa première grande victoire en Italie à Montenotte, séparant les armées autrichienne et piémontaise.', 'L''Ère Napoléonienne : Des Campagnes d''Italie à Waterloo', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.22465+00', NULL, NULL, NULL, ''),
	(658, 'Signature de l''armistice de Cherasco', 1796, false, NULL, 'Le 28 avril 1796, le roi de Sardaigne signe l''armistice de Cherasco avec Bonaparte, cédant Nice et la Savoie à la France.', 'L''Ère Napoléonienne : Des Campagnes d''Italie à Waterloo', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.22465+00', NULL, NULL, NULL, ''),
	(659, 'Victoire française à la bataille de Lodi', 1796, false, NULL, 'Le 10 mai 1796, Bonaparte franchit le pont de Lodi sous un feu nourri autrichien, consolidant la conquête de la Lombardie et forgeant sa légende.', 'L''Ère Napoléonienne : Des Campagnes d''Italie à Waterloo', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.22465+00', NULL, NULL, NULL, ''),
	(660, 'Entrée de Bonaparte à Milan', 1796, false, NULL, 'Le 15 mai 1796, les troupes françaises entrent triomphalement à Milan, capitale de la Lombardie, ouvrant la voie à la domination française en Italie du Nord.', 'L''Ère Napoléonienne : Des Campagnes d''Italie à Waterloo', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.22465+00', NULL, NULL, NULL, ''),
	(661, 'Création de la République Transpadane', 1796, false, NULL, 'Le 15 octobre 1796, Bonaparte proclame la République Transpadane à Milan, première république sœur fondée par la France révolutionnaire en Italie.', 'L''Ère Napoléonienne : Des Campagnes d''Italie à Waterloo', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.22465+00', NULL, NULL, NULL, ''),
	(662, 'Victoire française à la bataille d''Arcole', 1796, false, NULL, 'Le 17 novembre 1796, après trois jours de combats acharnés sur le pont d''Arcole, Bonaparte repousse définitivement l''armée autrichienne de Davidovich.', 'L''Ère Napoléonienne : Des Campagnes d''Italie à Waterloo', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.22465+00', NULL, NULL, NULL, ''),
	(663, 'Victoire décisive à la bataille de Rivoli', 1797, false, NULL, 'Le 14 janvier 1797, Bonaparte écrase l''armée autrichienne d''Alvinczy à Rivoli, mettant fin aux tentatives autrichiennes de secourir Mantoue.', 'L''Ère Napoléonienne : Des Campagnes d''Italie à Waterloo', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.22465+00', NULL, NULL, NULL, ''),
	(664, 'Capitulation de Mantoue', 1797, false, NULL, 'Le 2 février 1797, la garnison autrichienne de Mantoue capitule après un long siège, ouvrant la route de Vienne aux armées françaises.', 'L''Ère Napoléonienne : Des Campagnes d''Italie à Waterloo', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.22465+00', NULL, NULL, NULL, ''),
	(681, 'Débarquement allié à Anzio (Opération Shingle)', 1944, false, NULL, 'Le 22 janvier 1944, les Alliés débarquent à Anzio et Nettuno, au sud de Rome, pour contourner la ligne Gustav. L''opération tourne rapidement à l''enlisement face à la résistance allemande.', 'La Seconde Guerre Mondiale : Des Invasions Initiales aux Capitulations Finales', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.22465+00', NULL, NULL, NULL, ''),
	(665, 'Signature du traité de Tolentino avec le pape', 1797, false, NULL, 'Le 19 février 1797, le pape Pie VI signe le traité de Tolentino, cédant Avignon, Bologne et la Romagne à la France sous la pression de Bonaparte.', 'L''Ère Napoléonienne : Des Campagnes d''Italie à Waterloo', '', 'IMAGE_DONE', 'Main subject: A solemn and dignified gathering of officials and clergy.  
Action/Context: The signing of the Treaty of Tolentino with the Pope, capturing the moment of agreement with pens in hand and parchment laid out on a wooden table.  
Specific historical details: Participants are dressed in 18th-century attire made from fine wool and linen, featuring long coats, waistcoats, and breeches, adorned with intricate embroidery, while the Pope is in traditional papal robes, emphasizing the ceremonial nature. The setting is a grand room with stone walls and wooden beams, decorated with tapestries depicting historical events.  
Visual style: Historical oil painting in a classical museum style.  
Composition/Light: Natural lighting from large windows illuminating the room, with soft shadows cast by flickering candlelight on the table and faces of the attendees.', '2026-03-04 07:23:47.22465+00', NULL, NULL, NULL, 'http://127.0.0.1:54321/storage/v1/object/public/evenements-image/evt_665_signature_du_traite_de_tolentino_avec_le_1772268679944.webp'),
	(666, 'Signature des préliminaires de paix de Leoben', 1797, false, NULL, 'Le 18 avril 1797, Bonaparte signe avec l''Autriche les préliminaires de paix de Leoben, première étape vers la fin de la guerre en Italie.', 'L''Ère Napoléonienne : Des Campagnes d''Italie à Waterloo', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.22465+00', NULL, NULL, NULL, ''),
	(667, 'Proclamation de la République Cisalpine', 1797, false, NULL, 'Le 29 juin 1797, Bonaparte fusionne les républiques Cispadane et Transpadane pour créer la République Cisalpine, État satellite français en Italie du Nord.', 'L''Ère Napoléonienne : Des Campagnes d''Italie à Waterloo', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.22465+00', NULL, NULL, NULL, ''),
	(668, 'Signature du traité de Campoformio', 1797, false, NULL, 'Le 17 octobre 1797, Bonaparte signe le traité de Campoformio avec l''Autriche, mettant fin à la première coalition et cédant Venise à l''Autriche en échange de la Belgique.', 'L''Ère Napoléonienne : Des Campagnes d''Italie à Waterloo', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.22465+00', NULL, NULL, NULL, ''),
	(669, 'Fin de la République de Venise', 1797, false, NULL, 'Le 12 mai 1797, le Grand Conseil de Venise vote sa propre dissolution sous la pression de Bonaparte, mettant fin à plus de mille ans d''indépendance de la Sérénissime.', 'L''Ère Napoléonienne : Des Campagnes d''Italie à Waterloo', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.22465+00', NULL, NULL, NULL, ''),
	(670, 'Retour triomphal de Bonaparte à Paris', 1797, false, NULL, 'Le 5 décembre 1797, Bonaparte rentre à Paris acclamé en héros après la campagne d''Italie, auréolé d''une gloire qui lui ouvre la voie vers le pouvoir.', 'L''Ère Napoléonienne : Des Campagnes d''Italie à Waterloo', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.22465+00', NULL, NULL, NULL, ''),
	(671, 'Couronnement de Napoléon roi d''Italie', 1805, false, NULL, 'Le 26 mai 1805, Napoléon se couronne roi d''Italie à Milan avec la couronne de fer des Lombards. Il prononce la célèbre formule : ''Dieu me l''a donnée, gare à qui la touche.''', 'L''Ère Napoléonienne : Des Campagnes d''Italie à Waterloo', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.22465+00', NULL, NULL, NULL, ''),
	(672, 'Déclaration de guerre de la France et du Royaume-Uni à l''Allemagne', 1939, false, NULL, 'Le 3 septembre 1939, la France et le Royaume-Uni déclarent la guerre à l''Allemagne en réponse à l''invasion de la Pologne. C''est le début officiel du conflit européen.', 'La Seconde Guerre Mondiale : Des Invasions Initiales aux Capitulations Finales', '', 'IMAGE_DONE', 'French and British leaders standing resolutely at a grand wooden table in a dimly lit war room, as they formally declare war on Germany in 1939. The atmosphere is tense, with maps of Europe spread out on the table, and a large, ornate globe in the background. The leaders are dressed in formal military uniforms made of wool, featuring high collars and brass insignias, without any modern buttons or zippers. The room is adorned with heavy wooden furniture and stone walls, and the only light sources are flickering oil lamps casting warm shadows. This scene is captured in authentic historical black and white photography, evoking the gravity of the moment.', '2026-03-04 07:23:47.22465+00', NULL, NULL, NULL, 'http://127.0.0.1:54321/storage/v1/object/public/evenements-image/evt_672_declaration_de_guerre_de_la_france_et_du_1772268674780.webp'),
	(673, 'Offensive allemande à l''ouest (opération Fall Gelb)', 1940, false, NULL, 'Le 10 mai 1940, l''Allemagne lance une offensive massive contre la France, la Belgique, les Pays-Bas et le Luxembourg. Les Ardennes sont traversées par les blindés allemands.', 'La Seconde Guerre Mondiale : Des Invasions Initiales aux Capitulations Finales', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.22465+00', NULL, NULL, NULL, ''),
	(674, 'Évacuation de Dunkerque (opération Dynamo)', 1940, false, NULL, 'Du 26 mai au 4 juin 1940, plus de 338 000 soldats alliés sont évacués depuis les plages de Dunkerque vers l''Angleterre. Cette opération sauve le gros des forces britanniques.', 'La Seconde Guerre Mondiale : Des Invasions Initiales aux Capitulations Finales', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.22465+00', NULL, NULL, NULL, ''),
	(675, 'Invasion de la Yougoslavie et de la Grèce par l''Allemagne', 1941, false, NULL, 'Le 6 avril 1941, l''Allemagne lance l''opération Marita et envahit simultanément la Yougoslavie et la Grèce. Les deux pays sont rapidement submergés par les forces de l''Axe.', 'La Seconde Guerre Mondiale : Des Invasions Initiales aux Capitulations Finales', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.22465+00', NULL, NULL, NULL, ''),
	(676, 'Capitulation des forces britanniques à Singapour', 1942, false, NULL, 'Le 15 février 1942, le général britannique Arthur Percival se rend aux forces japonaises à Singapour. Environ 80 000 soldats alliés sont faits prisonniers dans ce que Churchill appelle ''la pire catastrophe de l''histoire militaire britannique''.', 'La Seconde Guerre Mondiale : Des Invasions Initiales aux Capitulations Finales', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.22465+00', NULL, NULL, NULL, ''),
	(677, 'Bataille de la mer de Corail', 1942, false, NULL, 'Du 4 au 8 mai 1942, la première bataille navale de l''histoire menée exclusivement par des porte-avions oppose les États-Unis au Japon dans le Pacifique. Elle stoppe l''avancée japonaise vers l''Australie.', 'La Seconde Guerre Mondiale : Des Invasions Initiales aux Capitulations Finales', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.22465+00', NULL, NULL, NULL, ''),
	(678, 'Conférence de Casablanca entre Roosevelt et Churchill', 1943, false, NULL, 'Du 14 au 24 janvier 1943, Franklin D. Roosevelt et Winston Churchill se réunissent à Casablanca pour planifier la stratégie alliée. Ils y proclament l''exigence d''une reddition inconditionnelle des puissances de l''Axe.', 'La Seconde Guerre Mondiale : Des Invasions Initiales aux Capitulations Finales', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.22465+00', NULL, NULL, NULL, ''),
	(679, 'Arrestation et destitution de Benito Mussolini', 1943, false, NULL, 'Le 25 juillet 1943, le Grand Conseil du fascisme vote la destitution de Benito Mussolini, qui est arrêté sur ordre du roi Victor-Emmanuel III. La chute du Duce marque le début de la fin du régime fasciste en Italie.', 'La Seconde Guerre Mondiale : Des Invasions Initiales aux Capitulations Finales', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.22465+00', NULL, NULL, NULL, ''),
	(680, 'Capitulation de l''Italie face aux Alliés', 1943, false, NULL, 'Le 8 septembre 1943, l''armistice entre l''Italie et les Alliés est rendu public. L''Allemagne nazie réagit immédiatement en occupant militairement la péninsule italienne.', 'La Seconde Guerre Mondiale : Des Invasions Initiales aux Capitulations Finales', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.22465+00', NULL, NULL, NULL, ''),
	(682, 'Libération de Rome par les forces alliées', 1944, false, NULL, 'Le 4 juin 1944, les troupes américaines du général Clark entrent dans Rome, première capitale de l''Axe libérée. L''événement est éclipsé deux jours plus tard par le débarquement en Normandie.', 'La Seconde Guerre Mondiale : Des Invasions Initiales aux Capitulations Finales', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.22465+00', NULL, NULL, NULL, ''),
	(683, 'Attentat manqué contre Hitler (opération Walkyrie)', 1944, false, NULL, 'Le 20 juillet 1944, le colonel Claus von Stauffenberg place une bombe dans le quartier général d''Hitler à Rastenburg. L''attentat échoue, Hitler survit et les conjurés sont exécutés.', 'La Seconde Guerre Mondiale : Des Invasions Initiales aux Capitulations Finales', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.22465+00', NULL, NULL, NULL, ''),
	(684, 'Chute de Berlin aux mains de l''Armée rouge', 1945, false, NULL, 'Le 2 mai 1945, la garnison allemande de Berlin se rend aux forces soviétiques après des combats acharnés. La prise de la capitale du Reich symbolise l''effondrement définitif du régime nazi.', 'La Seconde Guerre Mondiale : Des Invasions Initiales aux Capitulations Finales', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.22465+00', NULL, NULL, NULL, ''),
	(685, 'Bombardement atomique de Nagasaki', 1945, false, NULL, 'Le 9 août 1945, une seconde bombe atomique ''Fat Man'' est larguée sur Nagasaki, causant la mort de 40 000 à 80 000 personnes et dévastant la ville.', 'La Seconde Guerre Mondiale : Des Invasions Initiales aux Capitulations Finales', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.22465+00', NULL, NULL, NULL, ''),
	(686, 'Déclaration de guerre soviétique au Japon', 1945, false, NULL, 'Le 8 août 1945, l''URSS déclare la guerre au Japon et envahit la Mandchourie, respectant l''accord de Yalta et précipitant la capitulation japonaise.', 'La Seconde Guerre Mondiale : Des Invasions Initiales aux Capitulations Finales', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.22465+00', NULL, NULL, NULL, ''),
	(687, 'Annonce de la capitulation du Japon par l''Empereur Hirohito', 1945, false, NULL, 'Le 15 août 1945, l''Empereur Hirohito annonce à la radio la capitulation inconditionnelle du Japon, mettant fin aux combats dans le Pacifique.', 'La Seconde Guerre Mondiale : Des Invasions Initiales aux Capitulations Finales', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.22465+00', NULL, NULL, NULL, ''),
	(688, 'Mort du président Franklin D. Roosevelt', 1945, false, NULL, 'Le 12 avril 1945, le président américain Franklin D. Roosevelt décède d''une hémorragie cérébrale à Warm Springs, en Géorgie, laissant Harry Truman lui succéder.', 'La Seconde Guerre Mondiale : Des Invasions Initiales aux Capitulations Finales', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.22465+00', NULL, NULL, NULL, ''),
	(689, 'Coulage du cuirassé Yamato par l''aviation américaine', 1945, false, NULL, 'Le 7 avril 1945, le cuirassé japonais Yamato, le plus grand du monde, est coulé par des avions américains lors d''une mission suicide vers Okinawa.', 'La Seconde Guerre Mondiale : Des Invasions Initiales aux Capitulations Finales', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.22465+00', NULL, NULL, NULL, ''),
	(690, 'Première réunion du Comité intérimaire sur la bombe atomique', 1945, false, NULL, 'Le 9 mai 1945, le Comité intérimaire américain se réunit pour la première fois afin de décider de l''utilisation de la bombe atomique contre le Japon.', 'La Seconde Guerre Mondiale : Des Invasions Initiales aux Capitulations Finales', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.22465+00', NULL, NULL, NULL, ''),
	(691, 'Première diffusion de La Marseillaise', 1792, false, NULL, 'Le 25 avril 1792, Rouget de Lisle chante pour la première fois son Chant de guerre pour l''armée du Rhin à Strasbourg. Ce chant deviendra l''hymne national français sous le nom de La Marseillaise.', 'La Révolution Française : De la Monarchie à la République, Crises et Transformations', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.22465+00', NULL, NULL, NULL, ''),
	(692, 'Massacre des prisonniers dans les prisons parisiennes', 1792, false, NULL, 'Du 2 au 6 septembre 1792, des foules révolutionnaires envahissent les prisons parisiennes et massacrent plus de 1 000 détenus, craignant une trahison intérieure face à l''avancée des armées étrangères. Ces événements sont connus sous le nom de Massacres de Septembre.', 'La Révolution Française : De la Monarchie à la République, Crises et Transformations', '', 'IMAGE_DONE', 'Prisoners in Parisian prisons: A brutal massacre unfolds as guards violently attack unarmed inmates. The scene is set in 1792, with stone walls and iron bars surrounding the chaos. The prisoners wear ragged linen shirts and woolen trousers, while the guards are clad in coarse wool uniforms, all devoid of modern buttons or zippers. The atmosphere is captured in a historical oil painting in a classical museum style, illuminated by flickering candlelight casting eerie shadows on the grim faces and bloodstained floor, heightening the sense of despair and brutality.', '2026-03-04 07:23:47.236422+00', NULL, NULL, NULL, 'http://127.0.0.1:54321/storage/v1/object/public/evenements-image/evt_692_massacre_des_prisonniers_dans_les_prison_1772268682804.webp'),
	(693, 'Fermeture du Club des Jacobins par la Convention', 1794, false, NULL, 'Le 12 novembre 1794, la Convention thermidorienne ordonne la fermeture du Club des Jacobins à Paris. Ce haut lieu du radicalisme révolutionnaire est définitivement dissous.', 'La Révolution Française : De la Monarchie à la République, Crises et Transformations', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.236422+00', NULL, NULL, NULL, ''),
	(694, 'Entrée en fonction du Directoire', 1795, false, NULL, 'Le 2 novembre 1795 (11 Brumaire an IV), le Directoire entre officiellement en fonction, remplaçant la Convention nationale. Les cinq directeurs prennent le pouvoir exécutif de la République française.', 'La Révolution Française : De la Monarchie à la République, Crises et Transformations', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.236422+00', NULL, NULL, NULL, ''),
	(695, 'Répression de l''insurrection royaliste du 13 Vendémiaire', 1795, false, NULL, 'Le 5 octobre 1795, le général Bonaparte réprime une insurrection royaliste à Paris avec une célèbre ''mitraillade''. Cet épisode propulse Bonaparte sur le devant de la scène politique.', 'La Révolution Française : De la Monarchie à la République, Crises et Transformations', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.236422+00', NULL, NULL, NULL, ''),
	(696, 'Soulèvement populaire du 1er Prairial an III', 1795, false, NULL, 'Le 20 mai 1795, des sans-culottes affamés envahissent la Convention en réclamant du pain et la Constitution de 1793. La révolte est écrasée et marque la fin de l''influence populaire sur la Révolution.', 'La Révolution Française : De la Monarchie à la République, Crises et Transformations', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.236422+00', NULL, NULL, NULL, ''),
	(697, 'Premier survol réussi de la Lune par une sonde américaine (Ranger 7)', 1964, false, NULL, 'Le 31 juillet 1964, la sonde Ranger 7 transmet 4 308 photos de la surface lunaire avant de s''y écraser. C''est la première mission américaine à fournir des images rapprochées de la Lune.', 'La Conquête Spatiale : Des Premiers Satellites aux Missions Lunaires', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.236422+00', NULL, NULL, NULL, ''),
	(698, 'Premier atterrissage en douceur d''une sonde soviétique sur la Lune (Luna 9)', 1966, false, NULL, 'Le 3 février 1966, la sonde soviétique Luna 9 se pose sans se détruire sur la Lune et transmet les premières photos depuis la surface. Elle prouve que le sol lunaire peut supporter le poids d''un engin.', 'La Conquête Spatiale : Des Premiers Satellites aux Missions Lunaires', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.236422+00', NULL, NULL, NULL, ''),
	(722, 'Abandon de Tortose par les Templiers', 1291, false, NULL, 'Le 3 août 1291, les Templiers quittent définitivement Tortose, leur dernière place forte sur le continent syrien, se repliant sur l''île de Ruad au large des côtes.', 'Les Croisades : De la Terre Sainte à la Reconquista', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.236422+00', NULL, NULL, NULL, ''),
	(699, 'Première mise en orbite lunaire d''une sonde américaine (Lunar Orbiter 1)', 1966, false, NULL, 'Le 14 août 1966, Lunar Orbiter 1 entre en orbite autour de la Lune pour cartographier sa surface. La mission prépare le choix des sites d''atterrissage pour le programme Apollo.', 'La Conquête Spatiale : Des Premiers Satellites aux Missions Lunaires', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.236422+00', NULL, NULL, NULL, ''),
	(700, 'Lancement de la première sonde soviétique en orbite lunaire habitée (Zond 5)', 1968, false, NULL, 'Le 15 septembre 1968, la sonde soviétique Zond 5 contourne la Lune et revient sur Terre, transportant des tortues et des organismes vivants. C''est la première mission à ramener des êtres vivants depuis la Lune.', 'La Conquête Spatiale : Des Premiers Satellites aux Missions Lunaires', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.236422+00', NULL, NULL, NULL, ''),
	(701, 'Premier rendez-vous orbital entre deux vaisseaux soviétiques habités (Soyouz 4 et 5)', 1969, false, NULL, 'Le 16 janvier 1969, Soyouz 4 et Soyouz 5 s''arrimèrent en orbite et deux cosmonautes effectuèrent un transfert par sortie extravéhiculaire. L''URSS présente cette manœuvre comme une répétition pour un futur vol lunaire habité.', 'La Conquête Spatiale : Des Premiers Satellites aux Missions Lunaires', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.236422+00', NULL, NULL, NULL, ''),
	(702, 'Lancement de la station soviétique Saliout 4', 1974, false, NULL, 'Le 26 décembre 1974, l''URSS lance Saliout 4, une station spatiale dédiée à la recherche astrophysique. Elle accueillera deux équipages en 1975.', 'La Conquête Spatiale : Des Premiers Satellites aux Missions Lunaires', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.236422+00', NULL, NULL, NULL, ''),
	(703, 'Mort des cosmonautes de Soyouz 11 lors du retour sur Terre', 1971, false, NULL, 'Le 30 juin 1971, les trois cosmonautes de Soyouz 11 (Dobrovolski, Volkov, Patsaïev) sont retrouvés morts dans leur capsule, victimes d''une dépressurisation lors de la séparation des modules.', 'La Conquête Spatiale : Des Premiers Satellites aux Missions Lunaires', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.236422+00', NULL, NULL, NULL, ''),
	(704, 'Prise de Nicée par les croisés', 1097, false, NULL, 'Le 19 juin 1097, les croisés s''emparent de Nicée, capitale du sultanat seldjoukide de Roum, avec l''aide de l''armée byzantine de l''empereur Alexis Ier Comnène.', 'Les Croisades : De la Terre Sainte à la Reconquista', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.236422+00', NULL, NULL, NULL, ''),
	(705, 'Victoire des croisés à la bataille de Dorylée', 1097, false, NULL, 'Le 1er juillet 1097, les armées croisées écrasent les forces du sultan Kilij Arslan à Dorylée en Anatolie, ouvrant la route vers la Syrie et la Palestine.', 'Les Croisades : De la Terre Sainte à la Reconquista', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.236422+00', NULL, NULL, NULL, ''),
	(706, 'Fondation de l''Empire de Nicée par les Byzantins en exil', 1204, false, NULL, 'En 1204, Théodore Ier Lascaris fonde l''Empire de Nicée, principal État successeur byzantin en Asie Mineure, depuis lequel les empereurs grecs en exil prépareront la reconquête de Constantinople.', 'Les Croisades : De la Terre Sainte à la Reconquista', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.236422+00', NULL, NULL, NULL, ''),
	(707, 'Reconquête de Constantinople par Michel VIII Paléologue', 1261, false, NULL, 'Le 25 juillet 1261, les troupes de Michel VIII Paléologue reprennent Constantinople aux Latins sans combat majeur. L''Empire latin s''effondre et l''Empire byzantin est restauré, bien qu''affaibli.', 'Les Croisades : De la Terre Sainte à la Reconquista', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.236422+00', NULL, NULL, NULL, ''),
	(708, 'Chute de Césarée aux mains des Mamelouks', 1265, false, NULL, 'Le sultan Baybars s''empare de Césarée le 27 février 1265, rasant la ville et ses fortifications, privant les Francs d''un port stratégique en Terre Sainte.', 'Les Croisades : De la Terre Sainte à la Reconquista', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.236422+00', NULL, NULL, NULL, ''),
	(709, 'Prise d''Arsuf par Baybars', 1265, false, NULL, 'Le sultan mamelouk Baybars capture la forteresse d''Arsuf le 29 avril 1265 après un siège de quarante jours, réduisant encore les possessions franques.', 'Les Croisades : De la Terre Sainte à la Reconquista', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.236422+00', NULL, NULL, NULL, ''),
	(710, 'Chute de Safed aux mains des Mamelouks', 1266, false, NULL, 'Baybars s''empare du château de Safed le 23 juillet 1266, massacrant la garnison des Templiers et consolidant le contrôle mamelouk sur la Galilée.', 'Les Croisades : De la Terre Sainte à la Reconquista', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.236422+00', NULL, NULL, NULL, ''),
	(711, 'Prise de Jaffa par les Mamelouks', 1268, false, NULL, 'Le sultan Baybars s''empare de Jaffa le 7 mars 1268, éliminant l''un des derniers ports francs au sud de la côte palestinienne.', 'Les Croisades : De la Terre Sainte à la Reconquista', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.236422+00', NULL, NULL, NULL, ''),
	(712, 'Chute d''Antioche aux mains de Baybars', 1268, false, NULL, 'Le 18 mai 1268, Baybars prend et détruit Antioche, mettant fin à la principauté franque d''Antioche fondée lors de la première croisade en 1098.', 'Les Croisades : De la Terre Sainte à la Reconquista', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.236422+00', NULL, NULL, NULL, ''),
	(713, 'Chute du Krak des Chevaliers', 1271, false, NULL, 'Le sultan Baybars s''empare du Krak des Chevaliers le 8 avril 1271 après un siège, privant les Hospitaliers de leur forteresse la plus puissante en Syrie.', 'Les Croisades : De la Terre Sainte à la Reconquista', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.236422+00', NULL, NULL, NULL, ''),
	(714, 'Prise du château de Montfort par Baybars', 1271, false, NULL, 'Baybars capture le château de Montfort, siège des Chevaliers Teutoniques, le 12 juin 1271, après un bref siège en Galilée occidentale.', 'Les Croisades : De la Terre Sainte à la Reconquista', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.236422+00', NULL, NULL, NULL, ''),
	(715, 'Signature de la trêve de Césarée entre Francs et Mamelouks', 1272, false, NULL, 'Le 22 mai 1272, une trêve de dix ans est conclue entre les Francs d''Acre et le sultan Baybars, offrant un répit temporaire aux dernières possessions latines.', 'Les Croisades : De la Terre Sainte à la Reconquista', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.236422+00', NULL, NULL, NULL, ''),
	(716, 'Mort du sultan Baybars', 1277, false, NULL, 'Le sultan mamelouk Baybars meurt le 1er juillet 1277, laissant un empire consolidé et les Francs réduits à quelques villes côtières en Terre Sainte.', 'Les Croisades : De la Terre Sainte à la Reconquista', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.236422+00', NULL, NULL, NULL, ''),
	(717, 'Chute de Lattaquié aux mains des Mamelouks', 1287, false, NULL, 'Le sultan Qalawun s''empare de Lattaquié en avril 1287, éliminant l''un des derniers avant-postes francs sur la côte syrienne.', 'Les Croisades : De la Terre Sainte à la Reconquista', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.236422+00', NULL, NULL, NULL, ''),
	(719, 'Début du siège d''Acre par les Mamelouks', 1291, false, NULL, 'Le sultan Al-Ashraf Khalil lance le siège d''Acre le 5 avril 1291 avec une armée considérable, engageant l''assaut final contre la dernière grande cité franque.', 'Les Croisades : De la Terre Sainte à la Reconquista', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.236422+00', NULL, NULL, NULL, ''),
	(720, 'Abandon de Sidon par les Templiers', 1291, false, NULL, 'Le 14 juillet 1291, les Templiers évacuent et abandonnent Sidon sans combattre, l''une des dernières villes franques encore tenues après la chute d''Acre.', 'Les Croisades : De la Terre Sainte à la Reconquista', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.236422+00', NULL, NULL, NULL, ''),
	(721, 'Évacuation de Beyrouth par les Francs', 1291, false, NULL, 'En juillet 1291, les derniers défenseurs francs abandonnent Beyrouth, qui tombe sans résistance aux mains des Mamelouks, parachevant la reconquête musulmane du littoral.', 'Les Croisades : De la Terre Sainte à la Reconquista', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.236422+00', NULL, NULL, NULL, ''),
	(723, 'Évacuation du château Pèlerin par les Templiers', 1291, false, NULL, 'Le 14 août 1291, les Templiers abandonnent le château Pèlerin (Atlit), la dernière forteresse franque sur le continent, mettant un terme définitif à la présence latine en Terre Sainte.', 'Les Croisades : De la Terre Sainte à la Reconquista', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.236422+00', NULL, NULL, NULL, ''),
	(724, 'Victoire chrétienne à la bataille de Las Navas de Tolosa', 1212, false, NULL, 'Le 16 juillet 1212, les rois de Castille, d''Aragon et de Navarre écrasent les Almohades en Andalousie. Cette bataille marque un tournant décisif dans la Reconquista ibérique.', 'Les Croisades : De la Terre Sainte à la Reconquista', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.236422+00', NULL, NULL, NULL, ''),
	(725, 'Conquête de Cordoue par Ferdinand III de Castille', 1236, false, NULL, 'Le 29 juin 1236, Ferdinand III de Castille s''empare de Cordoue, ancienne capitale du califat omeyyade. La Grande Mosquée est convertie en cathédrale catholique.', 'Les Croisades : De la Terre Sainte à la Reconquista', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.236422+00', NULL, NULL, NULL, ''),
	(726, 'Prise de Séville par Ferdinand III de Castille', 1248, false, NULL, 'Le 23 novembre 1248, Ferdinand III conquiert Séville après un long siège. La ville devient la capitale du royaume de Castille et León.', 'Les Croisades : De la Terre Sainte à la Reconquista', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.236422+00', NULL, NULL, NULL, ''),
	(727, 'Signature du traité d''Alcañices entre Castille et Portugal', 1297, false, NULL, 'Le 12 septembre 1297, le traité d''Alcañices fixe définitivement la frontière entre le Portugal et la Castille. Il consolide les acquis territoriaux de la Reconquista portugaise.', 'Les Croisades : De la Terre Sainte à la Reconquista', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.236422+00', NULL, NULL, NULL, ''),
	(728, 'Victoire chrétienne à la bataille du Río Salado', 1340, false, NULL, 'Le 30 octobre 1340, Alphonse XI de Castille et Alphonse IV du Portugal repoussent une invasion mérinide au bord du Río Salado. C''est la dernière grande tentative d''invasion musulmane depuis l''Afrique.', 'Les Croisades : De la Terre Sainte à la Reconquista', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.236422+00', NULL, NULL, NULL, ''),
	(729, 'Prise d''Algésiras par Alphonse XI de Castille', 1344, false, NULL, 'Le 26 mars 1344, Alphonse XI s''empare d''Algésiras après un siège de deux ans. Cette victoire coupe les liaisons entre le Maroc et le royaume de Grenade.', 'Les Croisades : De la Terre Sainte à la Reconquista', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.236422+00', NULL, NULL, NULL, ''),
	(730, 'Début de la construction de l''Alhambra de Grenade', 1238, false, NULL, 'En 1238, Muhammad I ibn Nasr, fondateur de la dynastie nasride, pose les premières pierres de l''Alhambra à Grenade. Ce palais-forteresse deviendra le symbole du dernier royaume musulman d''Espagne.', 'Les Croisades : De la Terre Sainte à la Reconquista', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.236422+00', NULL, NULL, NULL, ''),
	(731, 'Bataille de la Higueruela contre le royaume de Grenade', 1431, false, NULL, 'Le 1er juillet 1431, Jean II de Castille remporte une victoire éclatante sur les Nasrides près de Grenade. Cet événement est immortalisé dans une fresque commandée plus tard par Philippe II à l''Escurial.', 'Les Croisades : De la Terre Sainte à la Reconquista', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.236422+00', NULL, NULL, NULL, ''),
	(732, 'Début de la guerre de Grenade par les Rois Catholiques', 1482, false, NULL, 'En février 1482, Isabelle et Ferdinand lancent la campagne militaire finale contre le royaume nasride de Grenade. Cette guerre durera dix ans et aboutira à la chute du dernier État musulman d''Ibérie.', 'Les Croisades : De la Terre Sainte à la Reconquista', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.236422+00', NULL, NULL, NULL, ''),
	(733, 'Capitulation de Málaga devant les Rois Catholiques', 1487, false, NULL, 'Le 18 août 1487, Málaga tombe aux mains des Rois Catholiques après un siège de plusieurs mois. Sa population musulmane est réduite en esclavage ou contrainte à l''exil.', 'Les Croisades : De la Terre Sainte à la Reconquista', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.236422+00', NULL, NULL, NULL, ''),
	(734, 'Lancement du programme militaire soviétique SS-20', 1980, false, NULL, 'En 1980, l''URSS achève le déploiement massif de ses missiles balistiques SS-20 en Europe, capables de frapper l''ensemble du continent en quelques minutes, relançant la course aux armements nucléaires.', 'La Guerre Froide : Des Blocs à la Chute du Mur', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.236422+00', NULL, NULL, NULL, ''),
	(735, 'Boycott des Jeux olympiques de Los Angeles par le bloc soviétique', 1984, false, NULL, 'Le 8 mai 1984, l''URSS annonce son boycott des Jeux olympiques d''été de Los Angeles, entraînant 14 pays du bloc de l''Est dans sa décision, en représailles au boycott américain de Moscou en 1980.', 'La Guerre Froide : Des Blocs à la Chute du Mur', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.236422+00', NULL, NULL, NULL, ''),
	(736, 'Réélection de Ronald Reagan avec une majorité écrasante', 1984, false, NULL, 'Le 6 novembre 1984, Ronald Reagan est réélu président des États-Unis avec 49 États sur 50, confirmant la poursuite de sa politique de fermeté face à l''Union soviétique.', 'La Guerre Froide : Des Blocs à la Chute du Mur', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.236422+00', NULL, NULL, NULL, ''),
	(737, 'Sommet de Reykjavik entre Reagan et Gorbatchev', 1986, false, NULL, 'Les 11 et 12 octobre 1986, Reagan et Gorbatchev se retrouvent en Islande pour négocier une réduction radicale des armements nucléaires ; les discussions échouent sur la question de l''IDS mais ouvrent la voie à de futurs accords.', 'La Guerre Froide : Des Blocs à la Chute du Mur', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.236422+00', NULL, NULL, NULL, ''),
	(738, 'Révolution de Velours en Tchécoslovaquie', 1989, false, NULL, 'Le 17 novembre 1989, une manifestation étudiante à Prague est violemment réprimée, déclenchant une révolution pacifique qui aboutit à la chute du régime communiste tchécoslovaque.', 'La Guerre Froide : Des Blocs à la Chute du Mur', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.236422+00', NULL, NULL, NULL, ''),
	(739, 'Dissolution du Pacte de Varsovie', 1991, false, NULL, 'Le 1er juillet 1991, le Pacte de Varsovie, alliance militaire des pays communistes créée en 1955 en réponse à l''OTAN, est officiellement dissous à Prague.', 'La Guerre Froide : Des Blocs à la Chute du Mur', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.236422+00', NULL, NULL, NULL, ''),
	(740, 'Proclamation de la doctrine Truman', 1947, false, NULL, 'Le 12 mars 1947, le président américain Harry Truman demande au Congrès une aide pour la Grèce et la Turquie, posant la doctrine d''endiguement du communisme qui structurera la Guerre Froide.', 'La Guerre Froide : Des Blocs à la Chute du Mur', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.236422+00', NULL, NULL, NULL, ''),
	(741, 'Premier voyage d''Amerigo Vespucci vers le Nouveau Monde', 1501, false, NULL, 'Amerigo Vespucci part explorer les côtes de l''Amérique du Sud pour le compte du Portugal. Ses observations confirment qu''il s''agit d''un continent inconnu, distinct de l''Asie.', 'Les Grandes Découvertes Maritimes : De Colomb à Magellan, l''Exploration du Monde', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.236422+00', NULL, NULL, NULL, ''),
	(742, 'Publication de la lettre ''Mundus Novus'' d''Amerigo Vespucci', 1503, false, NULL, 'Vespucci publie sa lettre décrivant les terres découvertes comme un ''Nouveau Monde''. Ce texte diffusé en Europe bouleverse la conception géographique du globe.', 'Les Grandes Découvertes Maritimes : De Colomb à Magellan, l''Exploration du Monde', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.236422+00', NULL, NULL, NULL, ''),
	(743, 'Christophe Colomb effectue son quatrième et dernier voyage', 1502, false, NULL, 'Colomb part le 11 mai 1502 pour son ultime expédition, explorant les côtes de l''Amérique centrale. Il meurt en 1506 sans jamais reconnaître avoir atteint un nouveau continent.', 'Les Grandes Découvertes Maritimes : De Colomb à Magellan, l''Exploration du Monde', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.247406+00', NULL, NULL, NULL, ''),
	(744, 'Fondation de la première ville européenne permanente en Amérique continentale', 1510, false, NULL, 'Santa María la Antigua del Darién est fondée le 1er janvier 1510 sur les côtes de l''actuel Panama, devenant le premier établissement européen permanent sur le continent américain.', 'Les Grandes Découvertes Maritimes : De Colomb à Magellan, l''Exploration du Monde', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.247406+00', NULL, NULL, NULL, ''),
	(745, 'Ouverture de la première route commerciale régulière entre l''Espagne et les Philippines', 1565, false, NULL, 'En 1565, Andrés de Urdaneta découvre le courant du Pacifique Nord permettant le retour vers l''Amérique. Cette route, dite du ''galion de Manille'', relie l''Asie à l''Amérique pendant 250 ans.', 'Les Grandes Découvertes Maritimes : De Colomb à Magellan, l''Exploration du Monde', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.247406+00', NULL, NULL, NULL, ''),
	(746, 'Fondation de la ville de Manille aux Philippines', 1571, false, NULL, 'Le 24 juin 1571, Miguel López de Legazpi fonde officiellement Manille, qui devient le principal port espagnol en Asie. La ville devient le nœud central du commerce transpacifique.', 'Les Grandes Découvertes Maritimes : De Colomb à Magellan, l''Exploration du Monde', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.247406+00', NULL, NULL, NULL, ''),
	(747, 'Ouverture de la première route commerciale directe entre l''Europe et la Chine par les Portugais', 1513, false, NULL, 'En 1513, Jorge Álvares devient le premier Européen à atteindre la côte de Chine continentale par voie maritime. Cet événement ouvre la voie aux échanges commerciaux directs entre l''Europe et l''Empire du Milieu.', 'Les Grandes Découvertes Maritimes : De Colomb à Magellan, l''Exploration du Monde', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.247406+00', NULL, NULL, NULL, ''),
	(748, 'Adoption des Townshend Acts par le Parlement britannique', 1767, false, NULL, 'Le 29 juin 1767, le Parlement britannique adopte les Townshend Acts, imposant de nouvelles taxes sur le verre, le papier, la peinture et le thé importés dans les colonies. Ces lois relancent la résistance coloniale.', 'La Révolution Américaine et la Naissance des États-Unis', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.247406+00', NULL, NULL, NULL, ''),
	(749, 'Abrogation partielle des Townshend Acts', 1770, false, NULL, 'Le 12 avril 1770, le Parlement britannique abroge la plupart des taxes Townshend, mais maintient celle sur le thé pour affirmer son droit de taxation. Cette décision partielle ne satisfait pas les colons les plus radicaux.', 'La Révolution Américaine et la Naissance des États-Unis', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.247406+00', NULL, NULL, NULL, ''),
	(750, 'Incendie du navire britannique Gaspée par des colons', 1772, false, NULL, 'Le 9 juin 1772, des colons de Rhode Island attaquent et incendient le Gaspée, un navire de la marine royale britannique chargé de faire respecter les lois douanières. C''est l''un des premiers actes de violence ouverte contre la Couronne.', 'La Révolution Américaine et la Naissance des États-Unis', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.247406+00', NULL, NULL, NULL, ''),
	(751, 'Création des Comités de correspondance par Samuel Adams', 1772, false, NULL, 'Le 2 novembre 1772, Samuel Adams fonde le premier Comité de correspondance à Boston pour coordonner la résistance entre les colonies. Ce réseau devient un outil politique majeur dans l''organisation de la rébellion.', 'La Révolution Américaine et la Naissance des États-Unis', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.247406+00', NULL, NULL, NULL, ''),
	(752, 'Adoption du Tea Act par le Parlement britannique', 1773, false, NULL, 'Le 10 mai 1773, le Parlement britannique adopte le Tea Act, accordant à la Compagnie des Indes orientales le monopole de la vente du thé dans les colonies. Cette loi provoque une vive indignation chez les marchands coloniaux.', 'La Révolution Américaine et la Naissance des États-Unis', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.247406+00', NULL, NULL, NULL, ''),
	(753, 'Adoption des Coercive Acts (Lois intolérables) par le Parlement britannique', 1774, false, NULL, 'Entre mars et juin 1774, le Parlement britannique adopte les Coercive Acts pour punir Boston après la Tea Party. Ces lois ferment le port de Boston et restreignent l''autonomie du Massachusetts, unissant les colonies dans leur opposition.', 'La Révolution Américaine et la Naissance des États-Unis', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.247406+00', NULL, NULL, NULL, ''),
	(754, 'Réunion du Premier Congrès continental à Philadelphie', 1774, false, NULL, 'Le 5 septembre 1774, des délégués de douze colonies se réunissent à Philadelphie pour coordonner leur réponse aux Coercive Acts. Le Congrès adopte une déclaration des droits et organise un boycott des marchandises britanniques.', 'La Révolution Américaine et la Naissance des États-Unis', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.247406+00', NULL, NULL, NULL, ''),
	(755, 'Prise du fort Ticonderoga par Ethan Allen et les Green Mountain Boys', 1775, false, NULL, 'Le 10 mai 1775, Ethan Allen et ses Green Mountain Boys s''emparent du fort Ticonderoga, tenu par les Britanniques, sans tirer un seul coup de feu. Cette victoire fournit aux colons une précieuse artillerie pour le siège de Boston.', 'La Révolution Américaine et la Naissance des États-Unis', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.247406+00', NULL, NULL, NULL, ''),
	(756, 'Ouverture du Deuxième Congrès continental à Philadelphie', 1775, false, NULL, 'Le 10 mai 1775, le Deuxième Congrès continental se réunit à Philadelphie et assume le rôle de gouvernement de facto des colonies en rébellion. Il nomme George Washington commandant en chef de l''armée continentale le 15 juin.', 'La Révolution Américaine et la Naissance des États-Unis', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.247406+00', NULL, NULL, NULL, ''),
	(757, 'Publication de ''Common Sense'' par Thomas Paine', 1776, false, NULL, 'Le 10 janvier 1776, Thomas Paine publie son pamphlet ''Common Sense'', plaidant avec force pour l''indépendance des colonies américaines. Ce texte, vendu à des centaines de milliers d''exemplaires, galvanise l''opinion publique en faveur de la rupture avec la Grande-Bretagne.', 'La Révolution Américaine et la Naissance des États-Unis', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.247406+00', NULL, NULL, NULL, ''),
	(758, 'Traversée du Delaware par Washington', 1776, false, NULL, 'Dans la nuit du 25 au 26 décembre 1776, George Washington traverse le fleuve Delaware avec ses troupes pour surprendre les forces hessoise à Trenton. Cette opération audacieuse redonne un élan décisif à la cause américaine après plusieurs défaites.', 'La Révolution Américaine et la Naissance des États-Unis', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.247406+00', NULL, NULL, NULL, ''),
	(759, 'Adoption des Articles de la Confédération', 1777, false, NULL, 'Le 15 novembre 1777, le Congrès continental adopte les Articles de la Confédération, premier texte constitutionnel des États-Unis. Ce document établit un gouvernement fédéral provisoire pour les treize États nouvellement indépendants.', 'La Révolution Américaine et la Naissance des États-Unis', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.247406+00', NULL, NULL, NULL, ''),
	(760, 'Bataille navale d''Ouessant', 1778, false, NULL, 'Le 27 juillet 1778, la flotte française de l''amiral d''Orvilliers affronte la flotte britannique au large d''Ouessant, première grande bataille navale de la guerre d''indépendance américaine.', 'La Révolution Américaine et la Naissance des États-Unis', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.247406+00', NULL, NULL, NULL, ''),
	(761, 'Déclaration de guerre de l''Espagne à la Grande-Bretagne', 1779, false, NULL, 'Le 21 juin 1779, l''Espagne entre en guerre contre la Grande-Bretagne via la Convention d''Aranjuez, renforçant considérablement la coalition contre les Britanniques.', 'La Révolution Américaine et la Naissance des États-Unis', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.247406+00', NULL, NULL, NULL, ''),
	(762, 'Victoire américaine à la bataille de Cowpens', 1781, false, NULL, 'Le 17 janvier 1781, le général Daniel Morgan écrase les forces britanniques du lieutenant-colonel Tarleton en Caroline du Sud, tournant décisif de la campagne du Sud.', 'La Révolution Américaine et la Naissance des États-Unis', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.247406+00', NULL, NULL, NULL, ''),
	(763, 'Arrivée de l''escadre de de Grasse aux Antilles', 1781, false, NULL, 'Le 28 avril 1781, l''amiral de Grasse quitte Brest avec une puissante escadre de 26 vaisseaux, dont la mission sera décisive pour le dénouement de la guerre en Amérique.', 'La Révolution Américaine et la Naissance des États-Unis', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.247406+00', NULL, NULL, NULL, ''),
	(764, 'Adoption des Articles de la Confédération comme première constitution américaine', 1781, false, NULL, 'Le 1er mars 1781, les Articles de la Confédération entrent officiellement en vigueur, créant un gouvernement central faible pour les treize États. Ce texte révèle rapidement ses limites face aux défis économiques et politiques.', 'La Révolution Américaine et la Naissance des États-Unis', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.247406+00', NULL, NULL, NULL, ''),
	(765, 'Adoption de l''Ordonnance du Nord-Ouest organisant les territoires américains', 1787, false, NULL, 'Le 13 juillet 1787, le Congrès de la Confédération adopte l''Ordonnance du Nord-Ouest, réglementant la colonisation des territoires au nord de l''Ohio. Elle interdit l''esclavage dans ces nouveaux territoires.', 'La Révolution Américaine et la Naissance des États-Unis', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.247406+00', NULL, NULL, NULL, ''),
	(766, 'Début de la rébellion de Shays dans le Massachusetts', 1786, false, NULL, 'Le 29 août 1786, Daniel Shays mène une insurrection d''agriculteurs endettés dans le Massachusetts contre les saisies judiciaires. Cette révolte révèle la faiblesse du gouvernement confédéral et accélère la réforme constitutionnelle.', 'La Révolution Américaine et la Naissance des États-Unis', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.247406+00', NULL, NULL, NULL, ''),
	(767, 'Adoption de l''Ordonnance de 1785 sur le cadastre des terres fédérales', 1785, false, NULL, 'Le 20 mai 1785, le Congrès de la Confédération adopte une ordonnance établissant un système de découpage en townships pour les terres de l''Ouest. Ce système cadastral quadrillé structure encore aujourd''hui le paysage américain.', 'La Révolution Américaine et la Naissance des États-Unis', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.247406+00', NULL, NULL, NULL, ''),
	(768, 'Publication des Federalist Papers par Hamilton, Madison et Jay', 1787, false, NULL, 'À partir du 27 octobre 1787, Alexander Hamilton, James Madison et John Jay publient une série de 85 articles sous le pseudonyme Publius. Ces textes défendent la ratification de la Constitution et restent une référence du droit constitutionnel.', 'La Révolution Américaine et la Naissance des États-Unis', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.247406+00', NULL, NULL, NULL, ''),
	(769, 'Ouverture de la Convention de Philadelphie', 1787, false, NULL, 'Le 25 mai 1787, 55 délégués des États américains se réunissent à Philadelphie pour réviser les Articles de la Confédération. La convention aboutira à la rédaction d''une toute nouvelle Constitution fédérale.', 'La Révolution Américaine et la Naissance des États-Unis', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.247406+00', NULL, NULL, NULL, ''),
	(770, 'Élection de George Washington comme premier président', 1789, false, NULL, 'Le 4 février 1789, les grands électeurs américains votent à l''unanimité pour George Washington comme premier président des États-Unis. C''est la seule élection présidentielle américaine remportée à l''unanimité du collège électoral.', 'La Révolution Américaine et la Naissance des États-Unis', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.247406+00', NULL, NULL, NULL, ''),
	(771, 'Création du Département d''État américain', 1789, false, NULL, 'Le 27 juillet 1789, le Congrès américain crée le Département des Affaires étrangères, rebaptisé Département d''État peu après. Thomas Jefferson en sera le premier secrétaire d''État.', 'La Révolution Américaine et la Naissance des États-Unis', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.247406+00', NULL, NULL, NULL, ''),
	(772, 'Adoption du Bill of Rights par le Congrès américain', 1789, false, NULL, 'Le 25 septembre 1789, le Congrès américain adopte les dix premiers amendements à la Constitution, connus sous le nom de Bill of Rights. Ces textes garantissent les libertés fondamentales des citoyens américains.', 'La Révolution Américaine et la Naissance des États-Unis', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.247406+00', NULL, NULL, NULL, ''),
	(773, 'Création de la Cour suprême des États-Unis', 1789, false, NULL, 'Le 24 septembre 1789, le Judiciary Act est signé par Washington, établissant officiellement la Cour suprême des États-Unis. John Jay en devient le premier président, ou Chief Justice.', 'La Révolution Américaine et la Naissance des États-Unis', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.247406+00', NULL, NULL, NULL, ''),
	(774, 'Première course automobile de l''histoire (Paris-Rouen)', 1894, false, NULL, 'Le 22 juillet 1894, la course Paris-Rouen est organisée, considérée comme la première compétition automobile officielle. Elle couvre 126 km et voit la victoire d''une voiture à vapeur De Dion-Bouton.', 'L''Ère des Transports et des Communications : De l''Automobile à l''Internet', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.247406+00', NULL, NULL, NULL, ''),
	(775, 'Inauguration du premier salon de l''automobile à Paris', 1898, false, NULL, 'Le 15 juin 1898, le premier Salon du cycle et de l''automobile ouvre ses portes au Jardin des Tuileries à Paris. Cet événement fondateur deviendra le plus ancien salon automobile du monde.', 'L''Ère des Transports et des Communications : De l''Automobile à l''Internet', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.247406+00', NULL, NULL, NULL, ''),
	(776, 'Lancement de la première voiture entièrement électrique commercialisée (Columbia Electric)', 1897, false, NULL, 'En 1897, la Pope Manufacturing Company commercialise la Columbia Electric, l''une des premières automobiles électriques vendues au grand public aux États-Unis. Elle préfigure un débat énergétique qui durera plus d''un siècle.', 'L''Ère des Transports et des Communications : De l''Automobile à l''Internet', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.247406+00', NULL, NULL, NULL, ''),
	(778, 'Lancement de la Ford Model T, première voiture de masse', 1908, false, NULL, 'Le 1er octobre 1908, Ford présente la Model T, conçue pour être abordable et fiable. Elle deviendra le symbole de la démocratisation de l''automobile grâce à sa production à grande échelle.', 'L''Ère des Transports et des Communications : De l''Automobile à l''Internet', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.247406+00', NULL, NULL, NULL, ''),
	(811, 'Tentative de colonisation du Vinland par Thorfinn Karlsefni', 1004, false, NULL, 'Le marchand islandais Thorfinn Karlsefni tente d''établir une colonie permanente au Vinland avec environ 160 personnes. Les conflits avec les populations locales (Skrælings) forcent l''abandon du projet.', 'L''Ère Viking : Des Raids aux Royaumes', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.259306+00', NULL, NULL, NULL, ''),
	(812, 'Bataille de Hafrsfjord et unification de la Norvège', 872, false, NULL, 'Harald à la Belle Chevelure remporte la bataille de Hafrsfjord contre une coalition de rois régionaux. Cette victoire lui permet de s''imposer comme premier roi unifié de Norvège.', 'L''Ère Viking : Des Raids aux Royaumes', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.259306+00', NULL, NULL, NULL, ''),
	(813, 'Mort du roi Harald à la Belle Chevelure', 933, false, NULL, 'Harald Ier de Norvège, unificateur du royaume, meurt après un règne de plus de soixante ans. Son décès ouvre une longue période de luttes dynastiques entre ses nombreux fils.', 'L''Ère Viking : Des Raids aux Royaumes', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.259306+00', NULL, NULL, NULL, ''),
	(779, 'Inauguration de la première autoroute du monde (AVUS, Berlin)', 1921, false, NULL, 'Le 24 septembre 1921, l''AVUS (Automobil-Verkehrs- und Übungsstraße) est inaugurée à Berlin, première route réservée aux automobiles. Longue de 9,8 km, elle servira aussi de circuit de course.', 'L''Ère des Transports et des Communications : De l''Automobile à l''Internet', '', 'IMAGE_DONE', 'A bustling scene of the inauguration of the AVUS in Berlin on September 24, 1921. A diverse crowd of elegantly dressed men and women from the 1920s, wearing hats and coats, gather along the sides of the newly constructed highway. Vintage automobiles, showcasing the era''s design, are parked and some are driving on the smooth asphalt. The sun casts a warm, golden light, creating a lively atmosphere filled with excitement and celebration. Flags and banners adorn the area, while a few officials in formal attire prepare to cut the ribbon. The background features the lush greenery of the surrounding landscape, contrasting with the modern highway. A dynamic perspective captures both the cars and the crowd, evoking a sense of motion and history. photorealistic documentary photo, cinematic lighting, highly detailed, 8k resolution.', '2026-03-04 07:23:47.247406+00', NULL, NULL, NULL, 'http://127.0.0.1:54321/storage/v1/object/public/evenements-image/chambre_noire_inauguration_de_la_premi_re_au_1772265695725.webp'),
	(780, 'Fondation de General Motors par William Durant', 1908, false, NULL, 'Le 16 septembre 1908, William C. Durant fonde General Motors à Flint, Michigan. Le groupe absorbera rapidement plusieurs marques automobiles pour devenir le plus grand constructeur mondial pendant des décennies.', 'L''Ère des Transports et des Communications : De l''Automobile à l''Internet', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.247406+00', NULL, NULL, NULL, ''),
	(781, 'Première traversée des États-Unis en automobile', 1903, false, NULL, 'Le 1er août 1903, Horatio Nelson Jackson achève la première traversée des États-Unis en automobile, parti de San Francisco le 23 mai. Ce périple de 63 jours démontre les capacités de l''automobile sur de longues distances.', 'L''Ère des Transports et des Communications : De l''Automobile à l''Internet', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.247406+00', NULL, NULL, NULL, ''),
	(782, 'Lancement de la Citroën Type A, première voiture européenne de grande série', 1919, false, NULL, 'Le 4 juin 1919, André Citroën lance la Type A, première automobile européenne produite en grande série selon les méthodes tayloristes. Elle marque l''entrée de l''Europe dans l''ère de la production automobile de masse.', 'L''Ère des Transports et des Communications : De l''Automobile à l''Internet', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.247406+00', NULL, NULL, NULL, ''),
	(783, 'Inauguration de l''autoroute Milan-Varèse, première autoroute moderne', 1924, false, NULL, 'Le 21 septembre 1924, l''autoroute Milan-Varèse est inaugurée en Italie, première infrastructure routière moderne dédiée exclusivement aux automobiles. Elle est considérée comme le modèle fondateur du réseau autoroutier mondial.', 'L''Ère des Transports et des Communications : De l''Automobile à l''Internet', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.247406+00', NULL, NULL, NULL, ''),
	(784, 'Production de la 15 millionième Ford Model T', 1927, false, NULL, 'Le 26 mai 1927, Ford produit sa 15 millionième Model T avant d''arrêter sa fabrication. Ce chiffre record illustre l''ampleur de la révolution industrielle accomplie par Henry Ford en moins de 20 ans.', 'L''Ère des Transports et des Communications : De l''Automobile à l''Internet', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.247406+00', NULL, NULL, NULL, ''),
	(785, 'Lancement de la Volkswagen Beetle, voiture du peuple commandée par Hitler', 1938, false, NULL, 'Le 26 mai 1938, Adolf Hitler pose la première pierre de l''usine Volkswagen à Wolfsburg, destinée à produire une voiture accessible à tous les Allemands. La Coccinelle deviendra l''une des voitures les plus vendues de l''histoire.', 'L''Ère des Transports et des Communications : De l''Automobile à l''Internet', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.247406+00', NULL, NULL, NULL, ''),
	(786, 'Première liaison téléphonique transatlantique sans fil', 1915, false, NULL, 'Le 25 octobre 1915, la première communication téléphonique sans fil entre New York et Paris est établie, franchissant l''Atlantique grâce aux ondes radio.', 'L''Ère des Transports et des Communications : De l''Automobile à l''Internet', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.247406+00', NULL, NULL, NULL, ''),
	(787, 'Inauguration du service téléphonique transatlantique commercial', 1927, false, NULL, 'Le 7 janvier 1927, le premier service téléphonique commercial transatlantique est ouvert entre New York et Londres, à raison de 75 dollars pour trois minutes de communication.', 'L''Ère des Transports et des Communications : De l''Automobile à l''Internet', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.247406+00', NULL, NULL, NULL, ''),
	(788, 'Premier câble téléphonique transatlantique sous-marin', 1956, false, NULL, 'Le 25 septembre 1956, le câble TAT-1 est mis en service entre l''Écosse et Terre-Neuve, permettant 36 communications téléphoniques simultanées entre l''Europe et l''Amérique du Nord.', 'L''Ère des Transports et des Communications : De l''Automobile à l''Internet', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.247406+00', NULL, NULL, NULL, ''),
	(789, 'Lancement du premier satellite de télécommunications actif (Telstar 1)', 1962, false, NULL, 'Le 10 juillet 1962, la NASA lance Telstar 1, premier satellite capable de relayer en temps réel des signaux téléphoniques et télévisés entre l''Europe et les États-Unis. La première image télévisée transatlantique est transmise quelques heures après le lancement.', 'L''Ère des Transports et des Communications : De l''Automobile à l''Internet', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.247406+00', NULL, NULL, NULL, ''),
	(790, 'Première émission de télévision en couleur en France', 1967, false, NULL, 'Le 1er octobre 1967, l''ORTF inaugure les émissions régulières en couleur sur la deuxième chaîne française. La France adopte le standard SECAM, développé par Henri de France, en opposition au PAL allemand.', 'L''Ère des Transports et des Communications : De l''Automobile à l''Internet', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.247406+00', NULL, NULL, NULL, ''),
	(791, 'Mise en orbite du premier satellite géostationnaire de télécommunications (Early Bird)', 1965, false, NULL, 'Le 6 avril 1965, Intelsat I, surnommé Early Bird, est placé en orbite géostationnaire. Il devient le premier satellite commercial à assurer une liaison permanente de télécommunications entre l''Europe et l''Amérique du Nord.', 'L''Ère des Transports et des Communications : De l''Automobile à l''Internet', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.247406+00', NULL, NULL, NULL, ''),
	(792, 'Lancement de la première chaîne de télévision par câble d''information continue (CNN)', 1980, false, NULL, 'Le 1er juin 1980, Ted Turner lance CNN (Cable News Network), première chaîne américaine diffusant des informations 24 heures sur 24. Ce modèle révolutionne la façon dont le monde consomme l''actualité télévisée.', 'L''Ère des Transports et des Communications : De l''Automobile à l''Internet', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.247406+00', NULL, NULL, NULL, ''),
	(814, 'Mort d''Éric à la Hache Sanglante, roi de Norvège', 954, false, NULL, 'Éric Ier, fils de Harald à la Belle Chevelure et ancien roi de Norvège puis de Northumbrie, est tué à la bataille de Stainmore en Angleterre. Sa mort met fin aux ambitions scandinaves sur la Northumbrie.', 'L''Ère Viking : Des Raids aux Royaumes', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.259306+00', NULL, NULL, NULL, ''),
	(815, 'Bataille de Fitjar et mort du roi Haakon le Bon', 961, false, NULL, 'Haakon Ier de Norvège, premier roi chrétien du pays, est mortellement blessé lors de la bataille de Fitjar face aux fils d''Éric. Sa mort marque la fin d''une période de relative stabilité en Norvège.', 'L''Ère Viking : Des Raids aux Royaumes', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.259306+00', NULL, NULL, NULL, ''),
	(793, 'Lancement du premier satellite météorologique (TIROS-1)', 1960, false, NULL, 'Le 1er avril 1960, la NASA lance TIROS-1, premier satellite météorologique opérationnel. Il transmet les premières photographies de la couverture nuageuse terrestre, révolutionnant la prévision météorologique mondiale.', 'L''Ère des Transports et des Communications : De l''Automobile à l''Internet', '', 'IMAGE_DONE', 'A bustling NASA launch site on April 1, 1960, under a clear blue sky. Engineers and scientists in 1960s attire, wearing white lab coats, hard hats, and sunglasses, eagerly observe the countdown. The sleek, silver TIROS-1 satellite stands prominently on the launch pad, surrounded by large machinery and towering support structures. The atmosphere is charged with excitement, with a crowd of onlookers in the background, some holding cameras. Rays of sunlight illuminate the scene, casting dramatic shadows. The focus is on the satellite, symbolizing technological advancement, while the anticipation of its historic launch fills the air. Photorealistic documentary photo, cinematic lighting, highly detailed, 8k resolution.', '2026-03-04 07:23:47.247406+00', NULL, NULL, NULL, 'http://127.0.0.1:54321/storage/v1/object/public/evenements-image/chambre_noire_lancement_du_premier_satellite_1772265697204.webp'),
	(794, 'Première émission de télévision en direct par satellite entre continents', 1967, false, NULL, 'Le 25 juin 1967, l''émission ''Our World'' est diffusée simultanément dans 31 pays via satellite, réunissant 400 millions de téléspectateurs. Les Beatles y interprètent ''All You Need Is Love'' en direct depuis Londres.', 'L''Ère des Transports et des Communications : De l''Automobile à l''Internet', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.259306+00', NULL, NULL, NULL, ''),
	(795, 'Commercialisation du premier magnétoscope grand public (Betamax)', 1975, false, NULL, 'En mai 1975, Sony commercialise le Betamax, premier magnétoscope destiné au grand public. Cet appareil permet pour la première fois aux téléspectateurs d''enregistrer et de visionner des émissions à leur convenance.', 'L''Ère des Transports et des Communications : De l''Automobile à l''Internet', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.259306+00', NULL, NULL, NULL, ''),
	(796, 'Lancement du système de navigation par satellite GPS', 1978, false, NULL, 'Le 22 février 1978, le premier satellite du système GPS (Global Positioning System) est mis en orbite par l''armée américaine. Ce réseau de satellites permettra à terme une localisation précise à l''échelle mondiale.', 'L''Ère des Transports et des Communications : De l''Automobile à l''Internet', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.259306+00', NULL, NULL, NULL, ''),
	(797, 'Publication du premier langage de programmation FORTRAN', 1957, false, NULL, 'IBM publie le langage FORTRAN (Formula Translation) en avril 1957. C''est le premier langage de programmation de haut niveau largement adopté, destiné aux calculs scientifiques.', 'L''Ère des Transports et des Communications : De l''Automobile à l''Internet', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.259306+00', NULL, NULL, NULL, ''),
	(798, 'Commercialisation du premier ordinateur personnel grand public (Altair 8800)', 1975, false, NULL, 'L''Altair 8800 est mis en vente en janvier 1975 par MITS pour 439 dollars en kit. Il déclenche la révolution des micro-ordinateurs et inspire les fondateurs de Microsoft.', 'L''Ère des Transports et des Communications : De l''Automobile à l''Internet', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.259306+00', NULL, NULL, NULL, ''),
	(799, 'Création du premier réseau social grand public (SixDegrees)', 1997, false, NULL, 'SixDegrees.com est lancé en 1997 par Andrew Weinreich. Considéré comme le premier réseau social moderne, il permet aux utilisateurs de créer un profil et de se connecter entre eux.', 'L''Ère des Transports et des Communications : De l''Automobile à l''Internet', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.259306+00', NULL, NULL, NULL, ''),
	(800, 'Mise en service du premier disque dur commercial (IBM 350)', 1956, false, NULL, 'IBM commercialise le disque dur 350 RAMAC le 13 septembre 1956. Pesant une tonne et stockant 5 mégaoctets, il est le premier système de stockage magnétique à accès aléatoire de l''histoire.', 'L''Ère des Transports et des Communications : De l''Automobile à l''Internet', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.259306+00', NULL, NULL, NULL, ''),
	(801, 'Mise à l''abri de Luther au château de la Wartburg', 1521, false, NULL, 'Le 4 mai 1521, Frédéric III de Saxe fait enlever secrètement Martin Luther pour le protéger et le cache au château de la Wartburg, où Luther traduit le Nouveau Testament en allemand.', 'La Réforme Protestante et les Guerres de Religion en Europe', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.259306+00', NULL, NULL, NULL, ''),
	(802, 'Publication du Livre de la Concorde luthérien', 1580, false, NULL, 'Le 25 juin 1580, cinquante ans après la Confession d''Augsbourg, le Livre de la Concorde est publié, rassemblant les textes fondateurs de la doctrine luthérienne orthodoxe.', 'La Réforme Protestante et les Guerres de Religion en Europe', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.259306+00', NULL, NULL, NULL, ''),
	(803, 'Signature de la Trêve de Douze Ans', 1609, false, NULL, 'Le 9 avril 1609, l''Espagne et les Provinces-Unies signent une trêve de douze ans, reconnaissant de facto l''indépendance néerlandaise et suspendant la guerre de Quatre-Vingts Ans.', 'La Réforme Protestante et les Guerres de Religion en Europe', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.259306+00', NULL, NULL, NULL, ''),
	(804, 'Bataille de Nördlingen et victoire des Habsbourg', 1634, false, NULL, 'Le 6 septembre 1634, les armées impériales et espagnoles écrasent les forces suédo-protestantes à Nördlingen, renversant temporairement l''équilibre de la guerre de Trente Ans.', 'La Réforme Protestante et les Guerres de Religion en Europe', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.259306+00', NULL, NULL, NULL, ''),
	(805, 'Entrée en guerre de la France contre l''Espagne', 1635, false, NULL, 'Le 19 mai 1635, le cardinal de Richelieu déclare officiellement la guerre à l''Espagne, engageant la France catholique aux côtés des protestants contre les Habsbourg pour des raisons géopolitiques.', 'La Réforme Protestante et les Guerres de Religion en Europe', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.259306+00', NULL, NULL, NULL, ''),
	(806, 'Raid viking sur l''abbaye de Noirmoutier', 799, false, NULL, 'Des navires nordiques attaquent l''abbaye de Noirmoutier, sur la côte atlantique franque. C''est l''une des premières incursions vikings documentées sur le territoire de l''empire carolingien.', 'L''Ère Viking : Des Raids aux Royaumes', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.259306+00', NULL, NULL, NULL, ''),
	(807, 'Premier raid viking sur l''Irlande', 795, false, NULL, 'Des Vikings attaquent l''île de Rathlin et les monastères côtiers irlandais, dont celui d''Iona. Ces raids inaugurent des décennies de pillages et d''implantations nordiques en Irlande.', 'L''Ère Viking : Des Raids aux Royaumes', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.259306+00', NULL, NULL, NULL, ''),
	(808, 'Fondation de la ville de Dublin par les Vikings', 841, false, NULL, 'Les Vikings établissent un campement fortifié permanent à l''embouchure de la Liffey, donnant naissance à Dubh Linn (Dublin). Ce comptoir devient rapidement un centre commercial et militaire majeur.', 'L''Ère Viking : Des Raids aux Royaumes', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.259306+00', NULL, NULL, NULL, ''),
	(809, 'Expulsion des Vikings de Dublin', 902, false, NULL, 'Les rois irlandais d''alliance chassent les Vikings de Dublin, mettant fin temporairement à leur domination sur la ville. Les Norsemen ne retrouveront leur emprise sur Dublin qu''en 917.', 'L''Ère Viking : Des Raids aux Royaumes', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.259306+00', NULL, NULL, NULL, ''),
	(810, 'Retour des Vikings et refondation de Dublin', 917, false, NULL, 'Les Vikings, menés par Sitric Cáech, reprennent le contrôle de Dublin après quinze ans d''absence. La ville est refondée et se développe en un royaume viking prospère.', 'L''Ère Viking : Des Raids aux Royaumes', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.259306+00', NULL, NULL, NULL, ''),
	(816, 'Baptême du roi Harald Ier de Danemark (Harald à la Dent Bleue)', 965, false, NULL, 'Harald Bluetooth, roi du Danemark, se convertit officiellement au christianisme, probablement sous l''influence du moine Poppon. Cet événement marque le début de la christianisation officielle du Danemark.', 'L''Ère Viking : Des Raids aux Royaumes', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.259306+00', NULL, NULL, NULL, ''),
	(817, 'Bataille de Hjörungavágr contre les Jomsvikings', 986, false, NULL, 'Le jarl Haakon Sigurdsson de Norvège remporte une victoire décisive contre la confrérie de guerriers vikings des Jomsvikings au large des côtes norvégiennes. Cette bataille consolide son pouvoir sur la Norvège.', 'L''Ère Viking : Des Raids aux Royaumes', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.259306+00', NULL, NULL, NULL, ''),
	(818, 'Assassinat du jarl Haakon Sigurdsson de Norvège', 995, false, NULL, 'Le jarl Haakon, maître de facto de la Norvège, est assassiné par son propre serf Kark alors qu''il se cachait. Olaf Tryggvason profite de l''événement pour s''emparer du trône de Norvège.', 'L''Ère Viking : Des Raids aux Royaumes', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.259306+00', NULL, NULL, NULL, ''),
	(819, 'Mort du roi Sweyn à la Barbe Fourchue, conquérant de l''Angleterre', 1014, false, NULL, 'Sweyn Forkbeard, roi du Danemark et premier roi viking d''Angleterre, meurt subitement à Gainsborough le 3 février 1014. Sa mort précipite le retour d''Æthelred II sur le trône anglais.', 'L''Ère Viking : Des Raids aux Royaumes', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.259306+00', NULL, NULL, NULL, ''),
	(820, 'Bataille de Nesjar et prise de pouvoir d''Olaf Haraldsson en Norvège', 1016, false, NULL, 'Olaf Haraldsson remporte la bataille navale de Nesjar contre le jarl Sweyn Haakonsson, dernier rival pour le contrôle de la Norvège. Il s''impose dès lors comme roi unique de Norvège sous le nom d''Olaf II.', 'L''Ère Viking : Des Raids aux Royaumes', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.259306+00', NULL, NULL, NULL, ''),
	(821, 'Fondation de l''abbaye du Mont-Saint-Michel', 966, false, NULL, 'Le duc de Normandie Richard Ier installe des moines bénédictins au Mont-Saint-Michel, transformant ce site en l''un des grands centres religieux de la chrétienté occidentale.', 'L''Ère Viking : Des Raids aux Royaumes', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.259306+00', NULL, NULL, NULL, ''),
	(822, 'Réhabilitation officielle de Galilée par le pape Jean-Paul II', 1992, false, NULL, 'Le 31 octobre 1992, le Vatican reconnaît officiellement l''erreur de la condamnation de Galilée en 1633, clôturant 359 ans de controverse autour de l''héliocentrisme.', 'La Révolution Scientifique et les Lumières : De la Renaissance à l''Encyclopédie', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.259306+00', NULL, NULL, NULL, ''),
	(823, 'Mort de Michel-Ange à Rome', 1564, false, NULL, 'Le peintre, sculpteur et architecte Michel-Ange s''éteint le 18 février 1564 à Rome, à l''âge de 88 ans. Il laisse derrière lui des œuvres majeures comme la chapelle Sixtine et la Pietà.', 'La Révolution Scientifique et les Lumières : De la Renaissance à l''Encyclopédie', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.259306+00', NULL, NULL, NULL, ''),
	(824, 'Publication des ''Essais'' de Montaigne', 1580, false, NULL, 'Michel de Montaigne publie les deux premiers livres de ses Essais le 1er mars 1580. Cette œuvre introspective fonde un nouveau genre littéraire et philosophique centré sur l''examen de soi.', 'La Révolution Scientifique et les Lumières : De la Renaissance à l''Encyclopédie', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.259306+00', NULL, NULL, NULL, ''),
	(825, 'Signature du traité de Lunéville', 1801, false, NULL, 'Le 9 février 1801, la France et l''Autriche signent le traité de Lunéville, confirmant la domination française sur l''Italie et la rive gauche du Rhin. Ce traité consolide les conquêtes révolutionnaires et renforce le prestige de Bonaparte.', 'L''Épopée Napoléonienne : Des Guerres de la Révolution à l''Empire et sa Chute', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.259306+00', NULL, NULL, NULL, ''),
	(826, 'Signature du traité d''Amiens avec la Grande-Bretagne', 1802, false, NULL, 'Le 25 mars 1802, la France et la Grande-Bretagne signent le traité d''Amiens, instaurant une paix générale en Europe. C''est la seule période de paix entre les deux nations durant toute l''ère napoléonienne.', 'L''Épopée Napoléonienne : Des Guerres de la Révolution à l''Empire et sa Chute', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.259306+00', NULL, NULL, NULL, ''),
	(827, 'Promulgation de la Constitution de l''an X', 1802, false, NULL, 'Le 4 août 1802, une nouvelle Constitution renforce encore les pouvoirs de Napoléon Bonaparte, désormais Consul à vie. Elle lui accorde notamment le droit de désigner son successeur et de dissoudre les assemblées.', 'L''Épopée Napoléonienne : Des Guerres de la Révolution à l''Empire et sa Chute', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.259306+00', NULL, NULL, NULL, ''),
	(828, 'Armistice de Pläswitz', 1813, false, NULL, 'Le 4 juin 1813, Napoléon et les coalisés signent l''armistice de Pläswitz, suspendant les combats. Cette trêve permettra à l''Autriche de rejoindre la coalition contre la France.', 'L''Épopée Napoléonienne : Des Guerres de la Révolution à l''Empire et sa Chute', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.259306+00', NULL, NULL, NULL, ''),
	(829, 'Prise de Paris par les coalisés', 1814, false, NULL, 'Le 31 mars 1814, les armées de la Sixième Coalition entrent dans Paris après la capitulation de la ville. C''est la première fois depuis 1418 que la capitale française tombe aux mains d''un ennemi étranger.', 'L''Épopée Napoléonienne : Des Guerres de la Révolution à l''Empire et sa Chute', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.259306+00', NULL, NULL, NULL, ''),
	(830, 'Signature du premier traité de Paris', 1814, false, NULL, 'Le 30 mai 1814, la France et les puissances de la Sixième Coalition signent le premier traité de Paris. La France retrouve ses frontières de 1792 et la monarchie des Bourbons est restaurée avec Louis XVIII.', 'L''Épopée Napoléonienne : Des Guerres de la Révolution à l''Empire et sa Chute', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.259306+00', NULL, NULL, NULL, ''),
	(831, 'Traité de La Haye avec les Provinces-Unies', 1795, false, NULL, 'Le 16 mai 1795, la France impose le traité de La Haye aux Provinces-Unies, transformant les Pays-Bas en République batave, État satellite de la France révolutionnaire.', 'La Révolution Française : De la Bastille au Consulat', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.259306+00', NULL, NULL, NULL, ''),
	(832, 'Coup d''État du 18 Fructidor An V', 1797, false, NULL, 'Le 4 septembre 1797, trois directeurs républicains, appuyés par l''armée de Bonaparte, annulent les élections favorables aux royalistes et déportent leurs adversaires politiques en Guyane.', 'La Révolution Française : De la Bastille au Consulat', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.259306+00', NULL, NULL, NULL, ''),
	(833, 'Rencontre Hitler-Franco à Hendaye', 1940, false, NULL, 'Le 23 octobre 1940, Adolf Hitler rencontre Francisco Franco à Hendaye pour tenter de convaincre l''Espagne d''entrer en guerre. Franco refuse de s''engager, maintenant l''Espagne dans une neutralité bienveillante.', 'Les Guerres Mondiales : De Sarajevo à la Victoire des Alliés', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.259306+00', NULL, NULL, NULL, ''),
	(834, 'Débarquement allié en Italie continentale (Opération Baytown)', 1943, false, NULL, 'Le 3 septembre 1943, les forces britanniques traversent le détroit de Messine et débarquent en Calabre, amorçant la campagne sur le continent italien.', 'Les Guerres Mondiales : De Sarajevo à la Victoire des Alliés', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.259306+00', NULL, NULL, NULL, ''),
	(835, 'Premier satellite de navigation militaire opérationnel (Transit 1B)', 1960, false, NULL, 'Le 13 avril 1960, les États-Unis lancent Transit 1B, premier satellite de navigation fonctionnel, ancêtre direct du GPS moderne.', 'La Conquête Spatiale : De Spoutnik aux Premiers Pas sur la Lune', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.259306+00', NULL, NULL, NULL, ''),
	(836, 'Lancement du premier satellite chinois (Dong Fang Hong 1)', 1970, false, NULL, 'Le 24 avril 1970, la Chine place en orbite son premier satellite, diffusant depuis l''espace la chanson révolutionnaire ''L''Orient est rouge''.', 'La Conquête Spatiale : De Spoutnik aux Premiers Pas sur la Lune', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.259306+00', NULL, NULL, NULL, ''),
	(837, 'Lancement du premier satellite britannique (Prospero)', 1971, false, NULL, 'Le 28 octobre 1971, le Royaume-Uni lance Prospero depuis l''Australie, devenant la sixième nation à placer un satellite en orbite avec son propre lanceur.', 'La Conquête Spatiale : De Spoutnik aux Premiers Pas sur la Lune', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.259306+00', NULL, NULL, NULL, ''),
	(838, 'Premier vol en tandem de vaisseaux soviétiques (Vostok 3 et 4)', 1962, false, NULL, 'Les 11 et 12 août 1962, les cosmonautes Andreï Nikolaïev et Pavel Popovitch sont lancés à bord de Vostok 3 et 4, réalisant le premier vol spatial en tandem de l''histoire.', 'La Conquête Spatiale : De Spoutnik aux Premiers Pas sur la Lune', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.259306+00', NULL, NULL, NULL, ''),
	(839, 'Premier amarrage spatial de l''histoire (Gemini 8)', 1966, false, NULL, 'Le 16 mars 1966, Neil Armstrong et David Scott réalisent le premier amarrage entre deux engins spatiaux, Gemini 8 s''arrimant à une fusée-cible Agena.', 'La Conquête Spatiale : De Spoutnik aux Premiers Pas sur la Lune', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.259306+00', NULL, NULL, NULL, ''),
	(840, 'Première utilisation d''un scaphandre autonome dans l''espace (Gemini 11)', 1966, false, NULL, 'Le 13 septembre 1966, Richard Gordon effectue une sortie extravéhiculaire depuis Gemini 11 et attache un câble de remorquage à la fusée Agena, testant de nouvelles techniques de travail spatial.', 'La Conquête Spatiale : De Spoutnik aux Premiers Pas sur la Lune', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.259306+00', NULL, NULL, NULL, ''),
	(841, 'Premier vol sans équipage de la fusée Saturn V', 1967, false, NULL, 'Le 9 novembre 1967, la fusée Saturn V effectue son premier vol d''essai non habité (mission Apollo 4). Ce test valide la puissance du lanceur destiné à envoyer des hommes vers la Lune.', 'La Conquête Spatiale : De Spoutnik aux Premiers Pas sur la Lune', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.259306+00', NULL, NULL, NULL, ''),
	(842, 'Deuxième vol d''essai non habité de Saturn V (Apollo 6)', 1968, false, NULL, 'Le 4 avril 1968, la fusée Saturn V effectue son second vol sans équipage (Apollo 6). Malgré des anomalies moteur, le vol fournit des données cruciales pour la qualification du lanceur.', 'La Conquête Spatiale : De Spoutnik aux Premiers Pas sur la Lune', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.259306+00', NULL, NULL, NULL, ''),
	(843, 'Création du Centre de contrôle de mission de Houston pour Apollo', 1965, false, NULL, 'Le 1er juin 1965, le Mission Control Center de Houston (Texas) devient officiellement opérationnel pour les missions spatiales habitées. Il prendra en charge toutes les missions Apollo depuis le décollage.', 'La Conquête Spatiale : De Spoutnik aux Premiers Pas sur la Lune', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.259306+00', NULL, NULL, NULL, ''),
	(844, 'Sélection du site d''alunissage pour Apollo par la NASA', 1968, false, NULL, 'En juillet 1968, la NASA sélectionne officiellement la mer de la Tranquillité comme site d''alunissage prioritaire pour la mission Apollo 11. Ce choix repose sur les données des sondes Surveyor et Lunar Orbiter.', 'La Conquête Spatiale : De Spoutnik aux Premiers Pas sur la Lune', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.271676+00', NULL, NULL, NULL, ''),
	(845, 'Fondation du comté de Tripoli', 1102, false, NULL, 'Raymond IV de Saint-Gilles entreprend la conquête de Tripoli en 1102 et pose les bases du comté de Tripoli. Ce dernier État latin d''Orient est officiellement constitué après la prise de la ville en 1109.', 'Les Croisades : De la Reconquête à la Défense de la Terre Sainte', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.271676+00', NULL, NULL, NULL, ''),
	(846, 'Bataille de Harran, défaite croisée', 1104, false, NULL, 'Le 7 mai 1104, les forces croisées de Bohémond d''Antioche et de Baudouin du Bourg sont écrasées à Harran par les Seldjoukides. Cette défaite stoppe l''expansion des États latins vers l''est et marque un tournant défensif.', 'Les Croisades : De la Reconquête à la Défense de la Terre Sainte', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.271676+00', NULL, NULL, NULL, ''),
	(847, 'Mort de Godefroy de Bouillon', 1100, false, NULL, 'Godefroy de Bouillon, premier souverain du royaume de Jérusalem, meurt le 18 juillet 1100. Son frère Baudouin Ier lui succède et prend officiellement le titre de roi de Jérusalem.', 'Les Croisades : De la Reconquête à la Défense de la Terre Sainte', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.271676+00', NULL, NULL, NULL, ''),
	(848, 'Prise de Tripoli par les croisés', 1109, false, NULL, 'Les croisés s''emparent de la ville de Tripoli le 12 juillet 1109, achevant la fondation du comté de Tripoli. Cette conquête complète le dispositif des quatre États latins d''Orient en Terre sainte.', 'Les Croisades : De la Reconquête à la Défense de la Terre Sainte', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.271676+00', NULL, NULL, NULL, ''),
	(849, 'Bataille de Sarmada, mort de Roger d''Antioche', 1119, false, NULL, 'Le 28 juin 1119, l''armée d''Antioche est anéantie par l''Ortoqide Ilghazi à la bataille de Sarmada, dite ''Champ de Sang''. Le prince Roger d''Antioche périt dans la bataille, laissant la principauté sans défense.', 'Les Croisades : De la Reconquête à la Défense de la Terre Sainte', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.271676+00', NULL, NULL, NULL, ''),
	(850, 'Mort de Baudouin II de Jérusalem', 1131, false, NULL, 'Baudouin II, roi de Jérusalem, meurt le 21 août 1131 après un règne marqué par la consolidation des États latins. Sa fille Mélisende lui succède, régnant conjointement avec son époux Foulques d''Anjou.', 'Les Croisades : De la Reconquête à la Défense de la Terre Sainte', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.271676+00', NULL, NULL, NULL, ''),
	(851, 'Prise d''Édesse par Zengui', 1144, false, NULL, 'Le 24 décembre 1144, l''atabeg de Mossoul Imad ad-Din Zengui s''empare d''Édesse, capitale du premier comté latin d''Orient. Cette chute provoque un choc en Occident et déclenche la deuxième croisade.', 'Les Croisades : De la Reconquête à la Défense de la Terre Sainte', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.271676+00', NULL, NULL, NULL, ''),
	(852, 'Mort du doge Enrico Dandolo à Constantinople', 1205, false, NULL, 'En juin 1205, Enrico Dandolo, architecte vénitien de la déviation de la quatrième croisade, meurt à Constantinople à plus de 90 ans. Il est enterré dans la basilique Sainte-Sophie.', 'Les Croisades : De la Reconquête à la Défense de la Terre Sainte', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.271676+00', NULL, NULL, NULL, ''),
	(853, 'Débarquement des croisés de la cinquième croisade en Égypte', 1218, false, NULL, 'En mai 1218, les croisés de la cinquième croisade débarquent près de Damiette en Égypte. Leur objectif est de s''emparer de l''Égypte pour l''échanger contre Jérusalem.', 'Les Croisades : De la Reconquête à la Défense de la Terre Sainte', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.271676+00', NULL, NULL, NULL, ''),
	(854, 'Prise de Damiette par les croisés', 1219, false, NULL, 'Le 5 novembre 1219, les croisés s''emparent de la ville de Damiette en Égypte après un long siège. Cette victoire ouvre la voie vers Le Caire mais sera mal exploitée.', 'Les Croisades : De la Reconquête à la Défense de la Terre Sainte', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.271676+00', NULL, NULL, NULL, ''),
	(855, 'Rencontre de François d''Assise et du sultan al-Kamil', 1219, false, NULL, 'En septembre 1219, François d''Assise traverse les lignes ennemies pour rencontrer le sultan ayyoubide al-Kamil d''Égypte. Cet épisode pacifiste unique reste célèbre dans l''histoire des croisades.', 'Les Croisades : De la Reconquête à la Défense de la Terre Sainte', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.271676+00', NULL, NULL, NULL, ''),
	(856, 'Défaite des croisés à la bataille de Mansourah', 1221, false, NULL, 'Le 26 août 1221, l''armée croisée est encerclée et écrasée par les forces ayyoubides à Mansourah. Les croisés doivent rendre Damiette et quitter l''Égypte, mettant fin à la cinquième croisade.', 'Les Croisades : De la Reconquête à la Défense de la Terre Sainte', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.271676+00', NULL, NULL, NULL, ''),
	(857, 'Abel Tasman découvre la Nouvelle-Zélande', 1642, false, NULL, 'Le 13 décembre 1642, le navigateur néerlandais Abel Tasman aperçoit pour la première fois les côtes de la Nouvelle-Zélande, qu''il nomme Staaten Landt, étendant la connaissance européenne du Pacifique.', 'L''Ère des Grandes Découvertes et l''Établissement des Empires Coloniaux', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.271676+00', NULL, NULL, NULL, ''),
	(858, 'Première expédition française en Antarctique (Bouvet de Lozier)', 1738, false, NULL, 'Le 1er janvier 1739, Jean-Baptiste Charles Bouvet de Lozier découvre l''île qui portera son nom dans l''Atlantique Sud, lors d''une expédition française cherchant un continent austral.', 'L''Ère des Grandes Découvertes et l''Établissement des Empires Coloniaux', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.271676+00', NULL, NULL, NULL, ''),
	(859, 'Débarquement de la première flotte britannique en Australie', 1788, false, NULL, 'Le 26 janvier 1788, la First Fleet commandée par Arthur Phillip accoste à Sydney Cove, fondant la première colonie pénitentiaire britannique en Australie, date célébrée comme fête nationale australienne.', 'L''Ère des Grandes Découvertes et l''Établissement des Empires Coloniaux', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.271676+00', NULL, NULL, NULL, ''),
	(860, 'Première expédition négrière portugaise vers les Amériques', 1526, false, NULL, 'Le premier navire négrier documenté transporte des esclaves africains directement vers le Brésil, inaugurant la traite transatlantique organisée. Ce voyage marque le début d''un commerce qui durera trois siècles.', 'L''Ère des Grandes Découvertes et l''Établissement des Empires Coloniaux', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.271676+00', NULL, NULL, NULL, ''),
	(861, 'Fondation de la première plantation sucrière de la Barbade', 1627, false, NULL, 'Les colons anglais établissent les premières plantations à la Barbade, île qui deviendra le modèle du système de plantation esclavagiste dans les Caraïbes britanniques.', 'L''Ère des Grandes Découvertes et l''Établissement des Empires Coloniaux', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.271676+00', NULL, NULL, NULL, ''),
	(862, 'Révolte des esclaves de la Barbade', 1649, false, NULL, 'Une rébellion d''esclaves éclate à la Barbade, l''une des premières révoltes organisées dans les colonies anglaises des Caraïbes. Elle est violemment réprimée par les planteurs.', 'L''Ère des Grandes Découvertes et l''Établissement des Empires Coloniaux', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.271676+00', NULL, NULL, NULL, ''),
	(863, 'Fondation de la Royal African Company', 1672, false, NULL, 'Charles II d''Angleterre accorde une charte royale à la Royal African Company, lui conférant le monopole du commerce des esclaves africains vers les colonies anglaises d''Amérique.', 'L''Ère des Grandes Découvertes et l''Établissement des Empires Coloniaux', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.271676+00', NULL, NULL, NULL, ''),
	(864, 'Révolte de Stono en Caroline du Sud', 1739, false, NULL, 'Le 9 septembre 1739, une centaine d''esclaves menés par Jemmy se soulèvent près de Charleston, tuant une vingtaine de colons avant d''être écrasés. C''est la plus grande révolte d''esclaves dans les colonies britanniques d''Amérique.', 'L''Ère des Grandes Découvertes et l''Établissement des Empires Coloniaux', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.271676+00', NULL, NULL, NULL, ''),
	(865, 'Publication de ''Description de la Nigritie'' par Labat', 1728, false, NULL, 'Le père Jean-Baptiste Labat publie un ouvrage décrivant les pratiques esclavagistes en Afrique de l''Ouest et dans les Caraïbes, contribuant à la documentation du commerce triangulaire.', 'L''Ère des Grandes Découvertes et l''Établissement des Empires Coloniaux', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.271676+00', NULL, NULL, NULL, ''),
	(866, 'Ouverture du port de Nantes au commerce négrier', 1642, false, NULL, 'Richelieu autorise officiellement les armateurs français, notamment nantais, à participer à la traite négrière transatlantique. Nantes deviendra le premier port négrier français.', 'L''Ère des Grandes Découvertes et l''Établissement des Empires Coloniaux', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.271676+00', NULL, NULL, NULL, ''),
	(867, 'Abolition du monopole de la Royal African Company', 1698, false, NULL, 'Le Parlement britannique met fin au monopole de la Royal African Company sur la traite négrière, ouvrant le commerce des esclaves à tous les marchands anglais. Le trafic s''intensifie immédiatement.', 'L''Ère des Grandes Découvertes et l''Établissement des Empires Coloniaux', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.271676+00', NULL, NULL, NULL, ''),
	(868, 'Première loi anti-esclavagiste du Parlement britannique', 1788, false, NULL, 'Le Parlement britannique adopte le Slave Trade Act (loi Dolben) le 11 juillet 1788, limitant le nombre d''esclaves transportés par navire selon son tonnage. C''est la première restriction légale de la traite en Grande-Bretagne.', 'L''Ère des Grandes Découvertes et l''Établissement des Empires Coloniaux', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.271676+00', NULL, NULL, NULL, ''),
	(869, 'Début de la révolution haïtienne', 1791, false, NULL, 'Dans la nuit du 22 au 23 août 1791, des milliers d''esclaves de Saint-Domingue se soulèvent lors de la cérémonie du Bois Caïman. Cette révolte marque le début de la révolution qui aboutira à l''indépendance d''Haïti.', 'L''Ère des Grandes Découvertes et l''Établissement des Empires Coloniaux', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.271676+00', NULL, NULL, NULL, ''),
	(870, 'Fondation de la Compagnie française des Indes occidentales', 1664, false, NULL, 'Colbert fonde la Compagnie des Indes occidentales le 28 mai 1664, lui accordant le monopole du commerce avec les Antilles françaises, incluant la traite des esclaves africains.', 'L''Ère des Grandes Découvertes et l''Établissement des Empires Coloniaux', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.271676+00', NULL, NULL, NULL, ''),
	(871, 'Publication de ''The Interesting Narrative'' d''Olaudah Equiano', 1789, false, NULL, 'L''ancien esclave Olaudah Equiano publie le 1er mars 1789 à Londres son autobiographie, témoignage poignant de la traite négrière. L''ouvrage devient un outil majeur du mouvement abolitionniste britannique.', 'L''Ère des Grandes Découvertes et l''Établissement des Empires Coloniaux', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.271676+00', NULL, NULL, NULL, ''),
	(872, 'Fondation de la Society for Effecting the Abolition of the Slave Trade', 1787, false, NULL, 'Le 22 mai 1787 à Londres, douze militants dont Thomas Clarkson et Granville Sharp fondent la première société abolitionniste britannique organisée, lançant une campagne publique sans précédent contre la traite.', 'L''Ère des Grandes Découvertes et l''Établissement des Empires Coloniaux', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.271676+00', NULL, NULL, NULL, ''),
	(873, 'Fondation de la colonie du Cap par la VOC', 1652, false, NULL, 'Le 6 avril 1652, Jan van Riebeeck débarque à la pointe sud de l''Afrique au nom de la Compagnie néerlandaise des Indes orientales (VOC). Il y établit un comptoir de ravitaillement, fondant ce qui deviendra la colonie du Cap.', 'L''Ère des Grandes Découvertes et l''Établissement des Empires Coloniaux', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.271676+00', NULL, NULL, NULL, ''),
	(874, 'Fondation de la Nouvelle-Orléans', 1718, false, NULL, 'Le 7 mai 1718, Jean-Baptiste Le Moyne de Bienville fonde la ville de La Nouvelle-Orléans en Louisiane française. La ville devient rapidement la capitale de la colonie et un carrefour commercial majeur.', 'L''Ère des Grandes Découvertes et l''Établissement des Empires Coloniaux', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.271676+00', NULL, NULL, NULL, ''),
	(875, 'Prise de Louisbourg par les Britanniques', 1745, false, NULL, 'Le 17 juin 1745, la forteresse française de Louisbourg, sur l''île du Cap-Breton, capitule face aux forces britanniques et coloniales américaines. Cette victoire ouvre la voie au contrôle britannique du golfe du Saint-Laurent.', 'L''Ère des Grandes Découvertes et l''Établissement des Empires Coloniaux', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.271676+00', NULL, NULL, NULL, ''),
	(876, 'Signature du Traité de Rio (Pacte interaméricain d''assistance mutuelle)', 1947, false, NULL, 'Le 2 septembre 1947, les États américains signent à Rio de Janeiro le premier traité de défense collective de l''après-guerre. Il pose les bases d''un dialogue régional pour la sécurité collective.', 'La Guerre Froide : De la Division de l''Europe à la Chute du Mur de Berlin', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.271676+00', NULL, NULL, NULL, ''),
	(877, 'Création de la Commission de désarmement de l''ONU', 1952, false, NULL, 'Le 11 janvier 1952, l''Assemblée générale de l''ONU établit une commission unique chargée de superviser les négociations mondiales sur le désarmement. Elle remplace les organes précédents issus de 1945.', 'La Guerre Froide : De la Division de l''Europe à la Chute du Mur de Berlin', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.271676+00', NULL, NULL, NULL, ''),
	(878, 'Ouverture de la première conférence de Genève au sommet (Eisenhower-Khrouchtchev)', 1955, false, NULL, 'Le 18 juillet 1955, les dirigeants des quatre grandes puissances se réunissent à Genève pour la première fois depuis 1945. Cette rencontre marque un dégel symbolique de la Guerre froide.', 'La Guerre Froide : De la Division de l''Europe à la Chute du Mur de Berlin', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.271676+00', NULL, NULL, NULL, ''),
	(879, 'Signature du Traité sur l''Antarctique', 1959, false, NULL, 'Le 1er décembre 1959, douze nations signent à Washington un traité faisant de l''Antarctique une zone démilitarisée et dédiée à la science. C''est l''un des premiers accords de désarmement territorial de la Guerre froide.', 'La Guerre Froide : De la Division de l''Europe à la Chute du Mur de Berlin', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.271676+00', NULL, NULL, NULL, ''),
	(880, 'Ouverture des négociations START à Genève', 1982, false, NULL, 'Le 29 juin 1982, les États-Unis et l''URSS entament à Genève les négociations sur la réduction des armements stratégiques (START). Elles visent pour la première fois une réduction réelle, et non une simple limitation.', 'La Guerre Froide : De la Division de l''Europe à la Chute du Mur de Berlin', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.271676+00', NULL, NULL, NULL, ''),
	(881, 'Signature du Traité sur les forces armées conventionnelles en Europe (FCE)', 1990, false, NULL, 'Le 19 novembre 1990, 22 nations de l''OTAN et du Pacte de Varsovie signent à Paris le Traité FCE. Il fixe des plafonds stricts sur les armements conventionnels de l''Atlantique à l''Oural.', 'La Guerre Froide : De la Division de l''Europe à la Chute du Mur de Berlin', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.271676+00', NULL, NULL, NULL, ''),
	(882, 'Signature du Traité START I entre les États-Unis et l''URSS', 1991, false, NULL, 'Le 31 juillet 1991, Bush et Gorbatchev signent à Moscou le premier traité de réduction effective des armements stratégiques. Il prévoit une diminution d''environ 30 % des ogives nucléaires de chaque côté.', 'La Guerre Froide : De la Division de l''Europe à la Chute du Mur de Berlin', '', 'VALIDATED_HISTORY', '', '2026-03-04 07:23:47.271676+00', NULL, NULL, NULL, ''),
	(883, 'Capture de la Jamaïque par les Anglais', 1655, false, NULL, 'L''Angleterre prend le contrôle de la Jamaïque, ouvrant la voie à l''établissement de Port Royal comme base navale et plaque tournante du commerce, y compris pour les activités de flibuste et de piraterie. Cette prise marque un tournant dans l''histoire de la région.', 'L''Âge d''Or de la Piraterie', '', 'PENDING', '', '2026-03-04 07:23:47.271676+00', NULL, NULL, NULL, ''),
	(884, 'Henry Morgan devient lieutenant-gouverneur de Jamaïque', 1674, false, NULL, 'L''ancien flibustier Henry Morgan, connu pour ses raids audacieux, est nommé lieutenant-gouverneur de la Jamaïque. Cette nomination symbolise l''intégration progressive des pirates dans le système colonial anglais.', 'L''Âge d''Or de la Piraterie', '', 'PENDING', '', '2026-03-04 07:23:47.271676+00', NULL, NULL, NULL, ''),
	(885, 'Tremblement de terre de Jamaïque', 1692, false, NULL, 'Un puissant tremblement de terre frappe Port Royal, détruisant une grande partie de la ville et entraînant un tsunami. Cet événement marque le déclin de Port Royal comme principal centre de piraterie.', 'L''Âge d''Or de la Piraterie', '', 'PENDING', '', '2026-03-04 07:23:47.271676+00', NULL, NULL, NULL, ''),
	(886, 'Fondation de Kingston', 1693, false, NULL, 'Kingston est fondée après le tremblement de terre qui a détruit Port Royal. Elle devient rapidement le nouveau centre économique et administratif de la Jamaïque, éclipsant Port Royal.', 'L''Âge d''Or de la Piraterie', '', 'PENDING', '', '2026-03-04 07:23:47.271676+00', NULL, NULL, NULL, ''),
	(887, 'Exécution de Calico Jack et de son équipage', 1720, false, NULL, 'Le pirate John Rackham, plus connu sous le nom de Calico Jack, et plusieurs membres de son équipage, dont les femmes pirates Anne Bonny et Mary Read, sont exécutés à Port Royal. Cet événement marque une étape dans la répression de la piraterie dans les Caraïbes.', 'L''Âge d''Or de la Piraterie', '', 'PENDING', '', '2026-03-04 07:23:47.271676+00', NULL, NULL, NULL, ''),
	(888, 'Henry Every capture le navire Mughal Ganj-i-Sawai', 1695, false, NULL, 'Le pirate anglais Henry Every et son équipage capturent le Ganj-i-Sawai, un navire de la flotte Mughal, provoquant une crise diplomatique entre l''Angleterre et l''Inde. Cet événement illustre l''audace croissante des pirates dans l''océan Indien après la Guerre de la Ligue d''Augsbourg.', 'L''Âge d''Or de la Piraterie', '', 'PENDING', '', '2026-03-04 07:23:47.271676+00', NULL, NULL, NULL, ''),
	(889, 'William Kidd reçoit une lettre de marque', 1696, false, NULL, 'Le capitaine William Kidd reçoit une lettre de marque du roi Guillaume III d''Angleterre pour chasser les pirates et les navires ennemis. Ironiquement, Kidd deviendra lui-même l''un des pirates les plus recherchés quelques années plus tard.', 'L''Âge d''Or de la Piraterie', '', 'PENDING', '', '2026-03-04 07:23:47.271676+00', NULL, NULL, NULL, ''),
	(890, 'Le Parlement anglais adopte l''Acte contre la piraterie (Act for the More Effectual Suppression of Piracy)', 1700, false, NULL, 'L''Acte contre la piraterie renforce les lois existantes et permet de juger les pirates devant des cours d''amirauté spéciales, sans jury. Cette loi visait à réprimer la piraterie croissante dans les colonies.', 'L''Âge d''Or de la Piraterie', '', 'PENDING', '', '2026-03-04 07:23:47.271676+00', NULL, NULL, NULL, ''),
	(891, 'Blackbeard (Edward Teach) capture le navire français La Concorde', 1717, false, NULL, 'Le pirate anglais Edward Teach, plus connu sous le nom de Barbe Noire, capture le navire négrier français La Concorde et le renomme Queen Anne''s Revenge. Il l''arme de 40 canons et en fait son navire amiral.', 'L''Âge d''Or de la Piraterie', '', 'PENDING', '', '2026-03-04 07:23:47.271676+00', NULL, NULL, NULL, ''),
	(892, 'Blocus de Charleston par Barbe Noire', 1718, false, NULL, 'Barbe Noire bloque le port de Charleston, en Caroline du Sud, pillant des navires et rançonnant la ville pour obtenir des médicaments.', 'L''Âge d''Or de la Piraterie', '', 'PENDING', '', '2026-03-04 07:23:47.271676+00', NULL, NULL, NULL, ''),
	(893, 'Bataille d''Ocracoke Island', 1718, false, NULL, 'Le lieutenant Robert Maynard attaque Barbe Noire et son équipage à Ocracoke Island. Barbe Noire est tué au cours de la bataille.', 'L''Âge d''Or de la Piraterie', '', 'PENDING', '', '2026-03-04 07:23:47.271676+00', NULL, NULL, NULL, ''),
	(894, 'Exécution de Stede Bonnet', 1718, false, NULL, 'Stede Bonnet, surnommé le « gentleman pirate », est pendu à White Point, Charleston, pour piraterie.', 'L''Âge d''Or de la Piraterie', '', 'PENDING', '', '2026-03-04 07:23:47.283022+00', NULL, NULL, NULL, ''),
	(898, 'Début du règne de Louis XV', 1715, false, NULL, 'Louis XV devient roi de France à l''âge de cinq ans, après la mort de Louis XIV. Une régence est mise en place jusqu''à sa majorité.', 'L''Âge d''Or de la Piraterie', '', 'PENDING', '', '2026-03-04 07:23:47.283022+00', NULL, NULL, NULL, ''),
	(899, 'Exécution de 26 pirates à Newport, Rhode Island', 1723, false, NULL, 'Vingt-six membres de l''équipage du pirate John Brown sont pendus à Newport, Rhode Island. Il s''agit d''une des plus grandes exécutions massives de pirates en Amérique du Nord.', 'L''Âge d''Or de la Piraterie', '', 'PENDING', '', '2026-03-04 07:23:47.283022+00', NULL, NULL, NULL, ''),
	(900, 'Début du procès de Charles Vane', 1721, false, NULL, 'Le pirate Charles Vane, capturé en février, est jugé à Spanish Town, Jamaïque. Il est reconnu coupable de piraterie et condamné à mort.', 'L''Âge d''Or de la Piraterie', '', 'PENDING', '', '2026-03-04 07:23:47.283022+00', NULL, NULL, NULL, ''),
	(901, 'Exécution de William Fly', 1726, false, NULL, 'Le pirate William Fly est pendu à Boston. Son corps est exposé en public comme avertissement aux autres marins tentés par la piraterie.', 'L''Âge d''Or de la Piraterie', '', 'PENDING', '', '2026-03-04 07:23:47.283022+00', NULL, NULL, NULL, ''),
	(902, 'Construction du Fort Navidad', 1492, false, NULL, 'Le Fort Navidad est construit sur l''île d''Hispaniola (actuelle Haïti et République dominicaine) à partir des restes de la Santa Maria, qui a fait naufrage. Il devient le premier établissement européen dans le Nouveau Monde.', 'Les Grandes Découvertes : Exploration du Monde et Colonisation Européenne', '', 'PENDING', '', '2026-03-04 07:23:47.283022+00', NULL, NULL, NULL, ''),
	(903, 'Amerigo Vespucci aperçoit la baie de Rio de Janeiro', 1502, false, NULL, 'L''explorateur Amerigo Vespucci, lors d''une expédition portugaise, aperçoit la baie de Rio de Janeiro, qu''il nomme ainsi car il pense l''avoir découverte en janvier. Ses voyages contribuent à la cartographie et à la compréhension du continent américain.', 'Les Grandes Découvertes : Exploration du Monde et Colonisation Européenne', '', 'PENDING', '', '2026-03-04 07:23:47.283022+00', NULL, NULL, NULL, ''),
	(904, 'Fondation de la ville de Panama', 1519, false, NULL, 'La ville de Panama est fondée par les conquistadors espagnols sur la côte Pacifique de l''isthme de Panama. Elle devient rapidement un point de transit crucial pour l''or et l''argent pillés aux Incas.', 'Les Grandes Découvertes : Exploration du Monde et Colonisation Européenne', '', 'PENDING', '', '2026-03-04 07:23:47.283022+00', NULL, NULL, NULL, ''),
	(905, 'Début du règne de Charles III d''Espagne', 1759, false, NULL, 'Charles III accède au trône d''Espagne. Son règne est marqué par des réformes importantes visant à moderniser l''empire espagnol, y compris ses colonies en Amérique.', 'Les Grandes Découvertes : Exploration du Monde et Colonisation Européenne', '', 'PENDING', '', '2026-03-04 07:23:47.283022+00', NULL, NULL, NULL, ''),
	(906, 'Arrivée des premiers navires de la Compagnie anglaise des Indes orientales à Surat', 1608, false, NULL, 'Les premiers navires de la Compagnie anglaise des Indes orientales arrivent à Surat, en Inde, marquant le début de ses opérations commerciales sur le sous-continent indien. William Hawkins, capitaine du navire ''Hector'', cherche à obtenir des droits commerciaux auprès de l''empereur moghol Jahangir.', 'Les Grandes Découvertes : Exploration du Monde et Colonisation Européenne', '', 'PENDING', '', '2026-03-04 07:23:47.283022+00', NULL, NULL, NULL, ''),
	(907, 'Adoption du Regulating Act', 1773, false, NULL, 'Le Parlement britannique adopte le Regulating Act de 1773, la première tentative significative du gouvernement britannique de contrôler les affaires de la Compagnie anglaise des Indes orientales. Il établit un gouverneur général du Bengale et une Cour suprême à Calcutta.', 'Les Grandes Découvertes : Exploration du Monde et Colonisation Européenne', '', 'PENDING', '', '2026-03-04 07:23:47.283022+00', NULL, NULL, NULL, ''),
	(908, 'Adoption du Pitt''s India Act', 1784, false, NULL, 'Le Parlement britannique adopte le Pitt''s India Act, qui établit un double système de contrôle de la Compagnie anglaise des Indes orientales, partageant le pouvoir entre la Compagnie et un Board of Control nommé par le gouvernement britannique. Ceci renforce le contrôle de l''État britannique sur les affaires de la Compagnie.', 'Les Grandes Découvertes : Exploration du Monde et Colonisation Européenne', '', 'PENDING', '', '2026-03-04 07:23:47.283022+00', NULL, NULL, NULL, ''),
	(909, 'Premier vol public des frères Wright en France', 1908, false, NULL, 'Wilbur Wright effectue une série de démonstrations de vol au Mans, en France. Ces vols impressionnent le public européen et stimulent l''intérêt pour l''aviation.', 'La Conquête de l''Air : Des premiers vols aux Jets Commerciaux', '', 'PENDING', '', '2026-03-04 07:23:47.283022+00', NULL, NULL, NULL, ''),
	(910, 'Création de la Wright Company', 1909, false, NULL, 'Les frères Wright fondent la Wright Company pour produire et commercialiser leurs avions. C''est l''une des premières entreprises aéronautiques au monde.', 'La Conquête de l''Air : Des premiers vols aux Jets Commerciaux', '', 'PENDING', '', '2026-03-04 07:23:47.283022+00', NULL, NULL, NULL, ''),
	(911, 'Décès d''Orville Wright', 1948, false, NULL, 'Orville Wright, le cadet des frères Wright, décède à Dayton, Ohio. Son décès marque la fin d''une époque pour l''aviation.', 'La Conquête de l''Air : Des premiers vols aux Jets Commerciaux', '', 'PENDING', '', '2026-03-04 07:23:47.283022+00', NULL, NULL, NULL, ''),
	(912, 'Création de la Royal Air Force (RAF)', 1918, false, NULL, 'Le 1er avril, le Royal Flying Corps et le Royal Naval Air Service sont fusionnés pour former la Royal Air Force, la première force aérienne indépendante au monde.', 'La Conquête de l''Air : Des premiers vols aux Jets Commerciaux', '', 'IMAGE_DONE', 'Main subject: A group of early Royal Air Force pilots in their distinctive uniforms.  
Action/Context: They are gathered around a vintage biplane, discussing their upcoming flight mission, with some inspecting the aircraft while others engage in conversation.  
Specific historical details: The pilots are wearing woolen flight suits, leather helmets, and goggles, with no modern buttons or zippers visible. The biplane is made of wood and fabric, showcasing the craftsmanship of the era.  
Visual style: Vintage color film still from the early 20th century.  
Composition/Light: The scene is illuminated by natural sunlight, casting soft shadows on the ground, with a clear blue sky in the background.', '2026-03-04 07:23:47.283022+00', NULL, NULL, NULL, 'http://127.0.0.1:54321/storage/v1/object/public/evenements-image/chambre_noire_cr_ation_de_la_royal_air_force_1772267175837.webp'),
	(913, 'Fondation de la compagnie aérienne KLM (Koninklijke Luchtvaart Maatschappij)', 1919, false, NULL, 'La KLM, la plus ancienne compagnie aérienne encore en activité sous son nom d''origine, est fondée aux Pays-Bas. Elle joue un rôle majeur dans le développement du transport aérien commercial.', 'La Conquête de l''Air : Des premiers vols aux Jets Commerciaux', '', 'PENDING', '', '2026-03-04 07:23:47.283022+00', NULL, NULL, NULL, ''),
	(914, 'Premier vol commercial régulier aux États-Unis', 1914, false, NULL, 'La St. Petersburg-Tampa Airboat Line effectue le premier vol commercial régulier aux États-Unis, reliant St. Petersburg et Tampa en Floride avec un hydravion Benoist XIV.', 'La Conquête de l''Air : Des premiers vols aux Jets Commerciaux', '', 'PENDING', '', '2026-03-04 07:23:47.283022+00', NULL, NULL, NULL, ''),
	(915, 'Premier vol transcontinental de nuit aux États-Unis (US Air Mail)', 1921, false, NULL, 'Le service postal aérien américain (US Air Mail) réalise le premier vol transcontinental de nuit, reliant New York à San Francisco, marquant une étape importante pour le transport aérien.', 'La Conquête de l''Air : Des premiers vols aux Jets Commerciaux', '', 'PENDING', '', '2026-03-04 07:23:47.283022+00', NULL, NULL, NULL, ''),
	(916, 'Premier vol de l''avion de ligne Ford Trimotor', 1926, false, NULL, 'Le Ford Trimotor, un avion de ligne trimoteur en métal, effectue son premier vol. Il devient un symbole de l''aviation commerciale des années 1920 et 1930.', 'La Conquête de l''Air : Des premiers vols aux Jets Commerciaux', '', 'PENDING', '', '2026-03-04 07:23:47.283022+00', NULL, NULL, NULL, ''),
	(917, 'Premier vol du Lockheed P-38 Lightning', 1939, false, NULL, 'Le Lockheed P-38 Lightning, un avion de chasse américain distinctif à double fuselage, effectue son premier vol. Il deviendra un avion polyvalent important pendant la guerre.', 'La Conquête de l''Air : Des premiers vols aux Jets Commerciaux', '', 'PENDING', '', '2026-03-04 07:23:47.283022+00', NULL, NULL, NULL, ''),
	(918, 'Début de la production du bombardier Avro Lancaster', 1941, false, NULL, 'Lancement de la production du bombardier lourd Avro Lancaster, un avion britannique qui jouera un rôle crucial dans les bombardements stratégiques alliés contre l''Allemagne.', 'La Conquête de l''Air : Des premiers vols aux Jets Commerciaux', '', 'PENDING', '', '2026-03-04 07:23:47.283022+00', NULL, NULL, NULL, ''),
	(919, 'Début de la production du Boeing B-29 Superfortress', 1943, false, NULL, 'Début de la production du Boeing B-29 Superfortress, un bombardier lourd américain à long rayon d''action utilisé pour bombarder le Japon pendant la Seconde Guerre mondiale.', 'La Conquête de l''Air : Des premiers vols aux Jets Commerciaux', '', 'PENDING', '', '2026-03-04 07:23:47.283022+00', NULL, NULL, NULL, ''),
	(920, 'Premier vol du Boeing 707', 1957, false, NULL, 'Le Boeing 707, un avion de ligne à réaction américain, effectue son premier vol. Il devient rapidement un symbole de l''aviation commerciale moderne.', 'La Conquête de l''Air : Des premiers vols aux Jets Commerciaux', '', 'PENDING', '', '2026-03-04 07:23:47.283022+00', NULL, NULL, NULL, ''),
	(921, 'Premier vol commercial du Boeing 707', 1958, false, NULL, 'Pan American World Airways (Pan Am) effectue le premier vol commercial du Boeing 707. Il relie New York à Paris.', 'La Conquête de l''Air : Des premiers vols aux Jets Commerciaux', '', 'PENDING', '', '2026-03-04 07:23:47.283022+00', NULL, NULL, NULL, ''),
	(922, 'Saccage de Noirmoutier (raid viking)', 848, false, NULL, 'Les Vikings pillent l''île de Noirmoutier, un important centre monastique et commercial sur la côte atlantique de la France. Cet événement marque le début des raids vikings réguliers en France.', 'L''essor et le déclin des Vikings : pillages, explorations et christianisation', '', 'PENDING', '', '2026-03-04 07:23:47.283022+00', NULL, NULL, NULL, ''),
	(923, 'Raid sur Hambourg', 845, false, NULL, 'Une flotte viking remonte l''Elbe et pille Hambourg. La ville est incendiée et une grande partie de sa population est tuée ou capturée.', 'L''essor et le déclin des Vikings : pillages, explorations et christianisation', '', 'PENDING', '', '2026-03-04 07:23:47.283022+00', NULL, NULL, NULL, ''),
	(924, 'Bataille de Brunanburh', 937, false, NULL, 'Le roi anglais Æthelstan défait une coalition de Vikings et d''Écossais à Brunanburh. Cette victoire consolide le pouvoir anglais et marque un coup d''arrêt à l''expansion viking en Angleterre.', 'L''essor et le déclin des Vikings : pillages, explorations et christianisation', '', 'PENDING', '', '2026-03-04 07:23:47.283022+00', NULL, NULL, NULL, ''),
	(925, 'Première messe de Noël au Vinland', 1000, false, NULL, 'Selon les sagas nordiques, Leif Erikson et son équipage passent l''hiver au Vinland et y célèbrent la messe de Noël, marquant potentiellement la première célébration chrétienne en Amérique du Nord.', 'L''essor et le déclin des Vikings : pillages, explorations et christianisation', '', 'PENDING', '', '2026-03-04 07:23:47.283022+00', NULL, NULL, NULL, ''),
	(926, 'Fondation de l''évêché de Skara', 1014, false, NULL, 'L''évêché de Skara est fondé en Suède, marquant une étape importante dans l''organisation de l''Église en Scandinavie.', 'L''essor et le déclin des Vikings : pillages, explorations et christianisation', '', 'PENDING', '', '2026-03-04 07:23:47.283022+00', NULL, NULL, NULL, ''),
	(927, 'Destruction du temple d''Uppsala (présumée)', 1087, false, NULL, 'Selon Adam de Brême, le temple païen d''Uppsala est détruit par le roi Inge l''Ancien. Cet événement symbolise la victoire du christianisme sur les anciennes croyances en Suède.', 'L''essor et le déclin des Vikings : pillages, explorations et christianisation', '', 'PENDING', '', '2026-03-04 07:23:47.283022+00', NULL, NULL, NULL, ''),
	(928, 'Bataille de Helgeå', 1026, false, NULL, 'Le roi Canut le Grand d''Angleterre et de Danemark, avec l''aide de troupes anglaises, affronte une armée suédoise et norvégienne à Helgeå (la localisation exacte est incertaine). Canut remporte une victoire décisive.', 'L''essor et le déclin des Vikings : pillages, explorations et christianisation', '', 'PENDING', '', '2026-03-04 07:23:47.283022+00', NULL, NULL, NULL, ''),
	(929, 'Traité de Madrid', 1670, false, NULL, 'L''Angleterre et l''Espagne signent le Traité de Madrid, visant à établir la paix et à définir les possessions coloniales dans les Caraïbes. Ce traité a indirectement affecté la piraterie en modifiant les relations entre les puissances européennes.', 'L''Âge d''Or de la Piraterie : Des Caraïbes aux Océans du Monde', '', 'PENDING', '', '2026-03-04 07:23:47.283022+00', NULL, NULL, NULL, ''),
	(930, 'Mort d''Henry Morgan', 1688, false, NULL, 'Henry Morgan, ancien pirate et lieutenant-gouverneur de Jamaïque, décède. Sa mort marque la fin d''une époque où la piraterie était tolérée, voire encouragée, par les autorités anglaises.', 'L''Âge d''Or de la Piraterie : Des Caraïbes aux Océans du Monde', '', 'PENDING', '', '2026-03-04 07:23:47.283022+00', NULL, NULL, NULL, ''),
	(931, 'Bataille de l''île de Crabe', 1703, false, NULL, 'Une force combinée espagnole et française attaque et détruit un campement de pirates anglais et hollandais sur l''île de Crabe (Vieques), marquant une tentative de répression de la piraterie dans les Caraïbes.', 'L''Âge d''Or de la Piraterie : Des Caraïbes aux Océans du Monde', '', 'PENDING', '', '2026-03-04 07:23:47.283022+00', NULL, NULL, NULL, ''),
	(932, 'Adoption de l''Acte contre la piraterie (Piracy Act 1717)', 1717, false, NULL, 'Le Parlement britannique adopte une loi renforçant les mesures contre la piraterie, offrant des récompenses pour la capture des pirates et établissant des tribunaux spéciaux pour les juger.', 'L''Âge d''Or de la Piraterie : Des Caraïbes aux Océans du Monde', '', 'PENDING', '', '2026-03-04 07:23:47.283022+00', NULL, NULL, NULL, ''),
	(933, 'Début du règne de George Ier de Grande-Bretagne', 1714, false, NULL, 'George Ier monte sur le trône de Grande-Bretagne après la mort de la reine Anne. Cet événement marque un changement dynastique important et une nouvelle ère politique.', 'L''Âge d''Or de la Piraterie : Des Caraïbes aux Océans du Monde', '', 'PENDING', '', '2026-03-04 07:23:47.283022+00', NULL, NULL, NULL, ''),
	(934, 'Bataille de l''île de la Providence', 1722, false, NULL, 'Le 17 avril, les forces espagnoles attaquent et reprennent l''île de la Providence, mettant fin à la tentative de colonie pirate et marquant un tournant dans la répression de la piraterie dans les Caraïbes.', 'L''Âge d''Or de la Piraterie : Des Caraïbes aux Océans du Monde', '', 'PENDING', '', '2026-03-04 07:23:47.283022+00', NULL, NULL, NULL, ''),
	(936, 'Fondation de la Compagnie d''Ostende', 1723, false, NULL, 'Le 19 décembre, l''empereur Charles VI fonde officiellement la Compagnie d''Ostende, une compagnie commerciale visant à concurrencer les puissances maritimes européennes en Asie.', 'L''Âge d''Or de la Piraterie : Des Caraïbes aux Océans du Monde', '', 'PENDING', '', '2026-03-04 07:23:47.283022+00', NULL, NULL, NULL, ''),
	(937, 'Lancement du HMS Royal George (1730)', 1730, false, NULL, 'Le 20 février, lancement du HMS Royal George, un navire de ligne de premier rang de 100 canons de la Royal Navy, reflétant l''évolution et le renforcement des marines royales européennes.', 'L''Âge d''Or de la Piraterie : Des Caraïbes aux Océans du Monde', '', 'PENDING', '', '2026-03-04 07:23:47.283022+00', NULL, NULL, NULL, ''),
	(938, 'Installation du module Columbus de l''ESA sur la Station Spatiale Internationale', 2008, false, NULL, 'La navette spatiale Atlantis livre et installe le module Columbus, le principal laboratoire de recherche européen de l''ISS. Il permet de mener des expériences scientifiques dans un environnement en microgravité.', 'La Conquête Spatiale : De Spoutnik à la Station Spatiale Internationale', '', 'PENDING', '', '2026-03-04 07:23:47.283022+00', NULL, NULL, NULL, ''),
	(939, 'Couronnement de Kanishka Ier, empereur Kushan', 127, false, NULL, 'Kanishka Ier monte sur le trône, marquant le début d''une période d''expansion et d''influence majeure de l''Empire Kushan sur la Route de la Soie. Son règne est crucial pour le contrôle commercial et culturel de la région.', 'La Route de la Soie : Échanges Commerciaux, Culturels et Militaires entre l''Orient et l''Occident', '', 'PENDING', '', '2026-03-04 07:23:47.283022+00', NULL, NULL, NULL, ''),
	(940, 'Construction du monastère de Hadda sous le règne de Kanishka Ier', 130, false, NULL, 'Début de la construction du monastère bouddhiste de Hadda, près de Jalalabad (Afghanistan actuel). Il devient un centre important de diffusion du bouddhisme et un point clé sur la Route de la Soie.', 'La Route de la Soie : Échanges Commerciaux, Culturels et Militaires entre l''Orient et l''Occident', '', 'PENDING', '', '2026-03-04 07:23:47.283022+00', NULL, NULL, NULL, ''),
	(941, 'Début du règne d''Huvishka, empereur Kushan', 155, false, NULL, 'Huvishka succède à Kanishka Ier, poursuivant l''expansion et la consolidation de l''Empire Kushan. Son règne est marqué par une prospérité économique et un soutien continu au bouddhisme.', 'La Route de la Soie : Échanges Commerciaux, Culturels et Militaires entre l''Orient et l''Occident', '', 'PENDING', '', '2026-03-04 07:23:47.283022+00', NULL, NULL, NULL, ''),
	(942, 'Début du règne de Vasudeva Ier, empereur Kushan', 225, false, NULL, 'Vasudeva Ier monte sur le trône, marquant le début d''une période de déclin progressif de l''Empire Kushan. Son règne est le dernier dont on ait des preuves substantielles de la puissance Kushan.', 'La Route de la Soie : Échanges Commerciaux, Culturels et Militaires entre l''Orient et l''Occident', '', 'PENDING', '', '2026-03-04 07:23:47.283022+00', NULL, NULL, NULL, ''),
	(943, 'Invasion de Shapur Ier et défaite de l''Empire Kushan', 241, false, NULL, 'Shapur Ier, empereur sassanide, envahit les territoires Kushans et inflige une défaite significative à l''empire. Cet événement marque le début du démembrement de l''Empire Kushan et la perte de son contrôle sur certaines portions de la Route de la Soie.', 'La Route de la Soie : Échanges Commerciaux, Culturels et Militaires entre l''Orient et l''Occident', '', 'PENDING', '', '2026-03-04 07:23:47.283022+00', NULL, NULL, NULL, ''),
	(944, 'Introduction de la sériciculture à Byzance par des moines (soie)', 552, false, NULL, 'Des moines rapportent clandestinement des œufs de vers à soie de Chine à Constantinople, marquant le début de la production byzantine de soie. Cet événement met fin au monopole perse sur la soie en Occident.', 'La Route de la Soie : Échanges Commerciaux, Culturels et Militaires entre l''Orient et l''Occident', '', 'PENDING', '', '2026-03-04 07:23:47.283022+00', NULL, NULL, NULL, ''),
	(945, 'Traité de Venise accordant des privilèges commerciaux à Venise (Byzance)', 1082, false, NULL, 'L''empereur Alexis Ier Comnène accorde d''importants privilèges commerciaux à Venise en échange d''une aide navale contre les Normands. Cela renforce la présence vénitienne dans le commerce byzantin, y compris celui de la soie.', 'La Route de la Soie : Échanges Commerciaux, Culturels et Militaires entre l''Orient et l''Occident', '', 'PENDING', '', '2026-03-04 07:23:47.294816+00', NULL, NULL, NULL, ''),
	(946, 'Interdiction de l''exportation de soie brute de Byzance (soie)', 1368, false, NULL, 'Une loi est promulguée interdisant l''exportation de soie brute de Byzance, dans le but de protéger l''industrie locale de transformation de la soie et de maintenir la qualité des produits finis.', 'La Route de la Soie : Échanges Commerciaux, Culturels et Militaires entre l''Orient et l''Occident', '', 'PENDING', '', '2026-03-04 07:23:47.294816+00', NULL, NULL, NULL, ''),
	(947, 'Traduction du Sūtra des Quarante-deux chapitres en chinois par Kasyapa Matanga et Dharmaratna à Luoyang', 67, false, NULL, 'Première traduction connue d''un texte bouddhiste en chinois, marquant un point de départ significatif pour la diffusion du bouddhisme en Chine. L''événement s''est produit au Temple du Cheval Blanc à Luoyang.', 'La Route de la Soie : Échanges Commerciaux, Culturels et Militaires entre l''Orient et l''Occident', '', 'PENDING', '', '2026-03-04 07:23:47.294816+00', NULL, NULL, NULL, ''),
	(948, 'Construction du Temple du Cheval Blanc (Baima Si) à Luoyang', 68, false, NULL, 'Fondation du premier temple bouddhiste en Chine, commandée par l''empereur Ming des Han en l''honneur des moines Kasyapa Matanga et Dharmaratna. Le temple devient un centre important pour la traduction et la propagation des écritures bouddhistes.', 'La Route de la Soie : Échanges Commerciaux, Culturels et Militaires entre l''Orient et l''Occident', '', 'PENDING', '', '2026-03-04 07:23:47.294816+00', NULL, NULL, NULL, ''),
	(949, 'Révolte des Turbans Rouges', 1351, false, NULL, 'Début de la Révolte des Turbans Rouges en Chine contre la dynastie Yuan mongole. Cette rébellion contribue à l''affaiblissement de la domination mongole et à la restauration de la dynastie Ming.', 'La Route de la Soie : Échanges Commerciaux, Culturels et Militaires entre l''Orient et l''Occident', '', 'PENDING', '', '2026-03-04 07:23:47.294816+00', NULL, NULL, NULL, ''),
	(950, 'Marco Polo est envoyé en mission diplomatique à Yangzhou', 1282, false, NULL, 'Kubilai Khan envoie Marco Polo en mission à Yangzhou, une ville importante de l''empire. Cette mission témoigne de la confiance accordée par le Khan au jeune Vénitien et lui permet d''approfondir sa connaissance de la Chine.', 'La Route de la Soie : Échanges Commerciaux, Culturels et Militaires entre l''Orient et l''Occident', '', 'PENDING', '', '2026-03-04 07:23:47.294816+00', NULL, NULL, NULL, ''),
	(951, 'Grève des ouvrières de Lowell (Lowell Mill Girls) contre les baisses de salaires', 1834, false, NULL, 'Cette grève est une des premières actions collectives des femmes dans l''industrie aux États-Unis. Elle témoigne de la résistance ouvrière face à la dégradation des conditions de travail.', 'La Révolution Industrielle : Innovations, Transformations sociales et Impérialisme (1760-1914)', '', 'PENDING', '', '2026-03-04 07:23:47.294816+00', NULL, NULL, NULL, ''),
	(952, 'Adoption du "Railway Regulation Act"', 1844, false, NULL, 'Le Parlement britannique adopte le "Railway Regulation Act", obligeant les compagnies ferroviaires à fournir des services de transport abordables pour les classes populaires. Cette loi a démocratisé l''accès au voyage en train et a favorisé la mobilité sociale.', 'La Révolution Industrielle : Innovations, Transformations sociales et Impérialisme (1760-1914)', '', 'PENDING', '', '2026-03-04 07:23:47.294816+00', NULL, NULL, NULL, ''),
	(953, 'Incorporation de Paramount Pictures (Famous Players-Lasky Corporation)', 1916, false, NULL, 'La Famous Players-Lasky Corporation, fondée par Adolph Zukor, fusionne avec la Jesse L. Lasky Feature Play Company pour former Paramount Pictures, consolidant ainsi sa position dans l''industrie cinématographique. Cet événement marque une étape clé dans la structuration des studios hollywoodiens.', 'L''Âge d''or d''Hollywood : Naissance et Apogée du Cinéma Américain', '', 'PENDING', '', '2026-03-04 07:23:47.294816+00', NULL, NULL, NULL, ''),
	(954, 'Première projection en couleurs par procédé Technicolor trichrome du film ''La Cucaracha''', 1934, false, NULL, 'Ce court métrage est le premier film utilisant le procédé Technicolor trichrome, une avancée significative dans la technologie de la couleur au cinéma. Il a ouvert la voie à l''utilisation plus répandue de la couleur dans les films.', 'L''Âge d''or d''Hollywood : Naissance et Apogée du Cinéma Américain', '', 'PENDING', '', '2026-03-04 07:23:47.294816+00', NULL, NULL, NULL, ''),
	(955, 'Sortie du film Le Roman de Renard', 1930, false, NULL, 'Premier long métrage d''animation français et l''un des premiers d''Europe. Réalisé par Władysław Starewicz, il est une adaptation du conte médiéval.', 'L''Âge d''or d''Hollywood : Naissance et Apogée du Cinéma Américain', '', 'PENDING', '', '2026-03-04 07:23:47.294816+00', NULL, NULL, NULL, ''),
	(956, 'Première du film ''Les Lumières de la ville'' (City Lights) de Charlie Chaplin', 1931, false, NULL, 'Sortie du film muet de Charlie Chaplin, bien après l''avènement du parlant, mais contenant une bande sonore synchronisée. Il démontre la persistance et l''attrait du cinéma muet malgré la popularité croissante du cinéma sonore.', 'L''Âge d''or d''Hollywood : Naissance et Apogée du Cinéma Américain', '', 'PENDING', '', '2026-03-04 07:23:47.294816+00', NULL, NULL, NULL, ''),
	(957, 'Première diffusion du film ''Citizen Kane'' à New York', 1941, false, NULL, 'La première diffusion de ''Citizen Kane'' d''Orson Welles marque une étape importante dans l''histoire du cinéma. Le film explore les thèmes du pouvoir, de la richesse et de la solitude, et remet en question l''image idéalisée des personnalités publiques.', 'L''Âge d''or d''Hollywood : Naissance et Apogée du Cinéma Américain', '', 'PENDING', '', '2026-03-04 07:23:47.294816+00', NULL, NULL, NULL, ''),
	(958, 'Création du Bureau de l''information de guerre (Office of War Information - OWI)', 1942, false, NULL, 'Fondation de l''OWI par le gouvernement américain pour contrôler l''information et coordonner la propagande pendant la Seconde Guerre mondiale. L''OWI a joué un rôle crucial dans la production de films de guerre et de messages patriotiques à Hollywood.', 'L''Âge d''or d''Hollywood : Naissance et Apogée du Cinéma Américain', '', 'PENDING', '', '2026-03-04 07:23:47.294816+00', NULL, NULL, NULL, ''),
	(959, 'Paramount cède la majorité de son stock de films d''avant 1948 à MCA pour 50 millions de dollars', 1958, false, NULL, 'Cette vente massive de droits marque une étape importante dans le déclin du contrôle des studios sur leurs anciens films et ouvre la voie à la télévision et au marché de la vidéo. MCA (plus tard Universal) acquiert ainsi un catalogue précieux.', 'L''Âge d''or d''Hollywood : Naissance et Apogée du Cinéma Américain', '', 'PENDING', '', '2026-03-04 07:23:47.294816+00', NULL, NULL, NULL, ''),
	(960, 'Début du règne d''Itzcóatl, quatrième tlatoani de Tenochtitlan', 1428, false, NULL, 'Itzcóatl devient le quatrième tlatoani (roi) de Tenochtitlan. Son règne marque un tournant avec la destruction des registres historiques et la réécriture de l''histoire aztèque pour légitimer leur pouvoir.', 'L''Ascension et la Chute de l''Empire Aztèque : De la fondation de Tenochtitlan à la conquête espagnole', '', 'PENDING', '', '2026-03-04 07:23:47.294816+00', NULL, NULL, NULL, ''),
	(961, 'Formation de la Triple Alliance entre Tenochtitlan, Texcoco et Tlacopan', 1428, false, NULL, 'Tenochtitlan, Texcoco et Tlacopan s''unissent pour former la Triple Alliance, consolidant leur pouvoir militaire et politique dans la vallée de Mexico. Cette alliance marque le début de l''expansion impériale aztèque.', 'L''Ascension et la Chute de l''Empire Aztèque : De la fondation de Tenochtitlan à la conquête espagnole', '', 'PENDING', '', '2026-03-04 07:23:47.294816+00', NULL, NULL, NULL, ''),
	(962, 'Début du règne de Moctezuma I, cinquième tlatoani de Tenochtitlan', 1440, false, NULL, 'Moctezuma I (aussi appelé Moctezuma Ilhuicamina) accède au trône de Tenochtitlan. Son règne est marqué par d''importantes conquêtes militaires et des travaux d''infrastructure majeurs, comme la construction de digues.', 'L''Ascension et la Chute de l''Empire Aztèque : De la fondation de Tenochtitlan à la conquête espagnole', '', 'PENDING', '', '2026-03-04 07:23:47.294816+00', NULL, NULL, NULL, ''),
	(963, 'Conquête de Chalco par les Aztèques', 1465, false, NULL, 'Après des décennies de conflits, les forces aztèques sous Moctezuma Ier conquièrent finalement la cité-état de Chalco. Cette victoire consolide le contrôle aztèque sur la vallée de Mexico et ouvre de nouvelles routes commerciales.', 'L''Ascension et la Chute de l''Empire Aztèque : De la fondation de Tenochtitlan à la conquête espagnole', '', 'PENDING', '', '2026-03-04 07:23:47.294816+00', NULL, NULL, NULL, ''),
	(964, 'Début du règne d''Ahuitzotl en tant que huitième tlatoani de Tenochtitlan', 1486, false, NULL, 'Ahuitzotl succède à Tizoc et lance une période d''expansion militaire significative pour l''Empire Aztèque. Son règne marque l''apogée de la puissance aztèque.', 'L''Ascension et la Chute de l''Empire Aztèque : De la fondation de Tenochtitlan à la conquête espagnole', '', 'PENDING', '', '2026-03-04 07:23:47.294816+00', NULL, NULL, NULL, ''),
	(965, 'Couronnement de Moctezuma II à Tenochtitlan', 1502, false, NULL, 'Moctezuma Xocoyotzin, est intronisé empereur (Tlatoani) des Aztèques à Tenochtitlan, marquant le début de son règne caractérisé par des présages et des défis croissants.', 'L''Ascension et la Chute de l''Empire Aztèque : De la fondation de Tenochtitlan à la conquête espagnole', '', 'PENDING', '', '2026-03-04 07:23:47.294816+00', NULL, NULL, NULL, ''),
	(984, 'Présentation du prototype de la machine différentielle de Babbage à la Royal Astronomical Society', 1822, false, NULL, 'Charles Babbage présente un petit prototype fonctionnel de sa machine différentielle à la Royal Astronomical Society le 14 juin 1822. Cet événement marque la première démonstration publique du concept.', 'L''Histoire de l''Informatique : Des premiers calculateurs mécaniques à l''ère du smartphone', '', 'PENDING', '', '2026-03-04 07:23:47.294816+00', NULL, NULL, NULL, ''),
	(985, 'Publication du mémoire de Luigi Federico Menabrea sur la machine analytique de Babbage', 1842, false, NULL, 'Luigi Federico Menabrea publie en français un mémoire décrivant la machine analytique de Charles Babbage. Ada Lovelace traduit et annote ce mémoire, ajoutant des notes qui sont maintenant reconnues comme le premier algorithme destiné à être traité par une machine.', 'L''Histoire de l''Informatique : Des premiers calculateurs mécaniques à l''ère du smartphone', '', 'PENDING', '', '2026-03-04 07:23:47.294816+00', NULL, NULL, NULL, ''),
	(986, 'Achèvement de l''imprimante pour la machine différentielle n°2 de Babbage', 2000, false, NULL, 'Le Science Museum de Londres termine la construction de l''imprimante conçue par Babbage pour accompagner sa machine différentielle n°2. L''ensemble complet (machine et imprimante) fonctionne avec succès, produisant des tables mathématiques imprimées.', 'L''Histoire de l''Informatique : Des premiers calculateurs mécaniques à l''ère du smartphone', '', 'PENDING', '', '2026-03-04 07:23:47.294816+00', NULL, NULL, NULL, ''),
	(987, 'Publication de l''article de William Shockley sur la modulation d''amplitude ("A Theory of Amplitude Modulation Based on Square-Law Detection")', 1948, false, NULL, 'En 1948, William Shockley publie un article important jetant les bases théoriques du transistor à jonction, une amélioration significative par rapport au transistor à point de contact. Cet article a permis de mieux comprendre le fonctionnement des transistors.', 'L''Histoire de l''Informatique : Des premiers calculateurs mécaniques à l''ère du smartphone', '', 'PENDING', '', '2026-03-04 07:23:47.294816+00', NULL, NULL, NULL, ''),
	(988, 'Prix Nobel de physique décerné à John Bardeen, Walter Brattain et William Shockley pour l''invention du transistor', 1956, false, NULL, 'En 1956, John Bardeen, Walter Brattain et William Shockley reçoivent le prix Nobel de physique en reconnaissance de leur invention du transistor. Cette récompense souligne l''importance fondamentale de leur découverte pour la physique et l''électronique.', 'L''Histoire de l''Informatique : Des premiers calculateurs mécaniques à l''ère du smartphone', '', 'PENDING', '', '2026-03-04 07:23:47.294816+00', NULL, NULL, NULL, ''),
	(989, 'Lancement du tableur VisiCalc', 1979, false, NULL, 'Software Arts commercialise VisiCalc, le premier tableur largement diffusé. Il est considéré comme une application phare qui a contribué à la popularisation de l''ordinateur personnel dans les entreprises.', 'L''Histoire de l''Informatique : Des premiers calculateurs mécaniques à l''ère du smartphone', '', 'PENDING', '', '2026-03-04 07:23:47.294816+00', NULL, NULL, NULL, ''),
	(1436, 'Premier concert de Judas Priest', 1971, false, NULL, 'Judas Priest donne son premier concert, marquant le début de leur carrière et leur contribution significative au développement du heavy metal.', 'L''Histoire du Rock ''n'' Roll : Des origines au phénomène mondial (1950-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.406143+00', NULL, NULL, NULL, ''),
	(990, 'Assassinat du calife Uthman ibn Affan à Médine', 656, false, NULL, 'Le 17 juin 656, le calife Uthman ibn Affan est assassiné par des rebelles à Médine. Cet événement déclenche la première Fitna, une guerre civile majeure au sein du califat.', 'L''Expansion Arabe : Du Califat Omeyyade à l''Âge d''Or Islamique', '', 'PENDING', '', '2026-03-04 07:23:47.294816+00', NULL, NULL, NULL, ''),
	(991, 'Début du règne du calife Abd al-Malik', 685, false, NULL, 'Abd al-Malik accède au califat omeyyade, marquant le début d''une période de consolidation et d''expansion territoriale accrue. Il met en place des réformes administratives et monétaires importantes.', 'L''Expansion Arabe : Du Califat Omeyyade à l''Âge d''Or Islamique', '', 'PENDING', '', '2026-03-04 07:23:47.294816+00', NULL, NULL, NULL, ''),
	(992, 'Conquête de Carthage par les Omeyyades', 698, false, NULL, 'Les forces omeyyades, sous le commandement d''Hassan ibn al-Nu''man, prennent Carthage, mettant fin à la présence byzantine en Afrique du Nord. Cette conquête ouvre la voie à l''expansion musulmane en Afrique du Nord.', 'L''Expansion Arabe : Du Califat Omeyyade à l''Âge d''Or Islamique', '', 'PENDING', '', '2026-03-04 07:23:47.294816+00', NULL, NULL, NULL, ''),
	(994, 'Mort du dernier sultan Khwarazmien Jalal ad-Din', 1231, false, NULL, 'Jalal ad-Din, dernier sultan de l''empire Khwarazmien, meurt, marquant la fin de la résistance organisée contre l''expansion mongole en Perse. Son décès ouvre la voie à une plus grande influence mongole.', 'L''Expansion Arabe : Du Califat Omeyyade à l''Âge d''Or Islamique', '', 'PENDING', '', '2026-03-04 07:23:47.294816+00', NULL, NULL, NULL, ''),
	(995, 'Début du règne de Möngke Khan', 1251, false, NULL, 'Möngke Khan devient le quatrième Grand Khan de l''Empire mongol. Son règne est caractérisé par une expansion continue et une administration centralisée, préparant le terrain pour l''invasion de Bagdad.', 'L''Expansion Arabe : Du Califat Omeyyade à l''Âge d''Or Islamique', '', 'PENDING', '', '2026-03-04 07:23:47.294816+00', NULL, NULL, NULL, ''),
	(1005, 'Révolte des Turbans Jaunes menée par Zhang Jiao', 184, false, NULL, 'La révolte des Turbans Jaunes, menée par Zhang Jiao, éclate en Chine. Bien que n''étant pas directement liée à la Route de la Soie, cette instabilité politique perturbe temporairement le commerce et les échanges le long de la route, affectant la sécurité des caravanes et des marchands.', 'La Route de la Soie : Échanges, Découvertes et Guerres (IIe siècle AEC - XIVe siècle)', '', 'PENDING', '', '2026-03-04 07:23:47.294816+00', NULL, NULL, NULL, ''),
	(1006, 'Première traduction du Sutra des Guirlandes (Buddhavatamsaka Sutra) en chinois par Lokaksema', 179, false, NULL, 'Lokaksema, un moine bouddhiste kushan, commence la traduction de textes bouddhistes importants, dont le Sutra des Guirlandes, marquant une étape cruciale dans la diffusion du bouddhisme Mahayana en Chine. Cette traduction a lieu à Luoyang.', 'La Route de la Soie : Échanges, Découvertes et Guerres (IIe siècle AEC - XIVe siècle)', '', 'PENDING', '', '2026-03-04 07:23:47.294816+00', NULL, NULL, NULL, ''),
	(1007, 'Voyage de Faxian vers l''Inde à la recherche d''écritures bouddhistes', 399, false, NULL, 'Le moine bouddhiste chinois Faxian entreprend un pèlerinage vers l''Inde à la recherche de textes bouddhistes. Son voyage et ses écrits contribuent à une meilleure compréhension du bouddhisme et des cultures indiennes en Chine.', 'La Route de la Soie : Échanges, Découvertes et Guerres (IIe siècle AEC - XIVe siècle)', '', 'PENDING', '', '2026-03-04 07:23:47.294816+00', NULL, NULL, NULL, ''),
	(1008, 'Construction du temple de Nalanda sous le règne de Kumaragupta I', 427, false, NULL, 'Kumaragupta I fonde le monastère de Nalanda, qui deviendra un centre majeur d''apprentissage bouddhiste et de philosophie en Inde. Il attire des érudits et des étudiants de toute l''Asie.', 'La Route de la Soie : Échanges, Découvertes et Guerres (IIe siècle AEC - XIVe siècle)', '', 'PENDING', '', '2026-03-04 07:23:47.294816+00', NULL, NULL, NULL, ''),
	(1009, 'Révolte d''An Lushan, affaiblissant le contrôle Tang sur la Route de la Soie', 755, false, NULL, 'La rébellion d''An Lushan, un général d''origine sogdienne, déstabilise la dynastie Tang et réduit son influence sur les régions occidentales. Cela perturbe temporairement le commerce sur la Route de la Soie.', 'La Route de la Soie : Échanges, Découvertes et Guerres (IIe siècle AEC - XIVe siècle)', '', 'PENDING', '', '2026-03-04 07:23:47.294816+00', NULL, NULL, NULL, ''),
	(1010, 'Construction de la Grande Mosquée de Xi''an, témoignant de la présence musulmane et du commerce sur la Route de la Soie', 742, false, NULL, 'La construction de la Grande Mosquée de Xi''an commence, reflétant l''influence croissante de l''islam en Chine et la présence de marchands musulmans le long de la Route de la Soie. Elle symbolise l''échange culturel et religieux.', 'La Route de la Soie : Échanges, Découvertes et Guerres (IIe siècle AEC - XIVe siècle)', '', 'PENDING', '', '2026-03-04 07:23:47.294816+00', NULL, NULL, NULL, ''),
	(1011, 'Début du règne de Haroun al-Rachid, calife abbasside, favorisant le commerce et les échanges culturels avec la Chine via la Route de la Soie', 786, false, NULL, 'Le règne de Haroun al-Rachid est marqué par une prospérité économique et un essor culturel. Il encourage les relations commerciales et diplomatiques avec la dynastie Tang, stimulant les échanges sur la Route de la Soie.', 'La Route de la Soie : Échanges, Découvertes et Guerres (IIe siècle AEC - XIVe siècle)', '', 'PENDING', '', '2026-03-04 07:23:47.294816+00', NULL, NULL, NULL, ''),
	(1012, 'Bataille d''Aïn Djalout : les Mamelouks d''Égypte stoppent l''avancée mongole', 1260, false, NULL, 'Le 3 septembre 1260, la bataille d''Aïn Djalout voit la victoire des Mamelouks d''Égypte sur les forces mongoles. Cette bataille est cruciale car elle marque la première défaite significative des Mongols et stoppe leur expansion en Afrique du Nord et au Moyen-Orient.', 'La Route de la Soie : Échanges, Découvertes et Guerres (IIe siècle AEC - XIVe siècle)', '', 'PENDING', '', '2026-03-04 07:23:47.294816+00', NULL, NULL, NULL, ''),
	(1013, 'Marco Polo arrive à la cour de Kubilai Khan à Khanbaliq (Pékin)', 1275, false, NULL, 'En 1275, Marco Polo, accompagné de son père et de son oncle, arrive à la cour de Kubilai Khan à Khanbaliq (Pékin). Son séjour de 17 ans en Chine contribue à ouvrir la voie au commerce et aux échanges culturels entre l''Europe et l''Asie.', 'La Route de la Soie : Échanges, Découvertes et Guerres (IIe siècle AEC - XIVe siècle)', '', 'PENDING', '', '2026-03-04 07:23:47.294816+00', NULL, NULL, NULL, ''),
	(1014, 'Début du règne de Ghazan : réformes économiques et culturelles dans l''Ilkhanat', 1295, false, NULL, 'En 1295, Ghazan monte sur le trône de l''Ilkhanat et initie une série de réformes économiques et culturelles importantes. Sa conversion à l''islam et ses efforts pour stabiliser l''économie contribuent à la prospérité de la région et à la promotion des arts et des sciences.', 'La Route de la Soie : Échanges, Découvertes et Guerres (IIe siècle AEC - XIVe siècle)', '', 'PENDING', '', '2026-03-04 07:23:47.294816+00', NULL, NULL, NULL, ''),
	(1015, 'Mort d''Ibn Battuta', 1368, false, NULL, 'Le décès d''Ibn Battuta, célèbre explorateur et voyageur musulman qui a documenté ses voyages le long de la Route de la Soie, symbolise la fin d''une ère de connaissance directe et de témoignages sur cette route.', 'La Route de la Soie : Échanges, Découvertes et Guerres (IIe siècle AEC - XIVe siècle)', '', 'PENDING', '', '2026-03-04 07:23:47.294816+00', NULL, NULL, NULL, ''),
	(1016, 'Première réunion de l''Assemblée générale de Virginie à Jamestown', 1619, false, NULL, 'Cette assemblée est la première législature élue des colonies anglaises en Amérique du Nord. Elle marque un pas important vers l''autonomie gouvernementale.', 'La Colonisation Européenne des Amériques : De la découverte à l''Indépendance', '', 'PENDING', '', '2026-03-04 07:23:47.294816+00', NULL, NULL, NULL, ''),
	(1017, 'Première diffusion de l''émission "American Bandstand" à l''échelle nationale sur ABC', 1957, false, NULL, 'L''émission "American Bandstand", animée par Dick Clark, commence sa diffusion nationale sur ABC le 5 août. Elle devient une plateforme majeure pour la musique pop et rock ''n'' roll, influençant les tendances musicales et vestimentaires de la jeunesse américaine.', 'L''Âge d''Or du Rock ''n'' Roll : Naissance d''une culture mondiale (1954-1969)', '', 'PENDING', '', '2026-03-04 07:23:47.294816+00', NULL, NULL, NULL, ''),
	(1018, 'Inauguration du Disneyland Park à Anaheim, Californie', 1955, false, NULL, 'Le Disneyland Park ouvre ses portes le 17 juillet à Anaheim, Californie. Il devient rapidement une attraction emblématique et contribue à l''essor du tourisme et de la culture de divertissement en Californie.', 'L''Âge d''Or du Rock ''n'' Roll : Naissance d''une culture mondiale (1954-1969)', '', 'PENDING', '', '2026-03-04 07:23:47.294816+00', NULL, NULL, NULL, ''),
	(1019, 'Sortie du film "Gidget"', 1959, false, NULL, 'Le film "Gidget", mettant en vedette Sandra Dee, sort en salle. Il popularise la culture surf auprès d''un public plus large et contribue à l''image de la Californie comme un paradis pour les surfeurs.', 'L''Âge d''Or du Rock ''n'' Roll : Naissance d''une culture mondiale (1954-1969)', '', 'PENDING', '', '2026-03-04 07:23:47.294816+00', NULL, NULL, NULL, ''),
	(1020, 'Création du label Del-Fi Records par Bob Keane', 1958, false, NULL, 'Bob Keane fonde le label Del-Fi Records à Los Angeles. Le label joue un rôle important dans la promotion de la musique surf et des artistes rock ''n'' roll émergents de la Californie.', 'L''Âge d''Or du Rock ''n'' Roll : Naissance d''une culture mondiale (1954-1969)', '', 'PENDING', '', '2026-03-04 07:23:47.294816+00', NULL, NULL, NULL, ''),
	(1021, 'Ouverture du club de musique folk « Gerde''s Folk City » à New York', 1960, false, NULL, 'Le club devient un lieu central pour la scène folk revival, accueillant des artistes tels que Bob Dylan et Joan Baez. Il contribue à populariser la musique folk et les messages contestataires.', 'L''Âge d''Or du Rock ''n'' Roll : Naissance d''une culture mondiale (1954-1969)', '', 'PENDING', '', '2026-03-04 07:23:47.294816+00', NULL, NULL, NULL, ''),
	(1022, 'Acquisition de Motown Records par MCA Inc.', 1988, false, NULL, 'Le 28 juin 1988, Berry Gordy vend Motown Records à MCA Inc. pour 61 millions de dollars. Cette acquisition marque la fin d''une ère pour le label.', 'L''Âge d''Or du Rock ''n'' Roll : Naissance d''une culture mondiale (1954-1969)', '', 'PENDING', '', '2026-03-04 07:23:47.294816+00', NULL, NULL, NULL, ''),
	(1023, 'Inauguration du Motown Museum (Hitsville U.S.A.) à Détroit', 1985, false, NULL, 'Le Motown Museum, également connu sous le nom de Hitsville U.S.A., ouvre ses portes au public le 1er août 1985 à Détroit. Il préserve l''histoire et l''héritage de Motown Records.', 'L''Âge d''Or du Rock ''n'' Roll : Naissance d''une culture mondiale (1954-1969)', '', 'PENDING', '', '2026-03-04 07:23:47.307048+00', NULL, NULL, NULL, ''),
	(1024, 'Désignation de Bertrand d''Ogeron comme gouverneur de l''île de la Tortue', 1665, false, NULL, 'Bertrand d''Ogeron est nommé gouverneur de l''île de la Tortue par le roi Louis XIV, marquant une étape importante dans la colonisation française et l''organisation de la flibuste.', 'L''Âge d''Or de la Piraterie Caribéenne : Flibuste, Corsaires et Pirates (1650-1730)', '', 'PENDING', '', '2026-03-04 07:23:47.307048+00', NULL, NULL, NULL, ''),
	(1025, 'Début du mandat de Jean-Baptiste du Casse comme gouverneur de Saint-Domingue', 1691, false, NULL, 'Jean-Baptiste du Casse est nommé gouverneur de Saint-Domingue, jouant un rôle clé dans le développement de la colonie et la lutte contre les puissances européennes rivales.', 'L''Âge d''Or de la Piraterie Caribéenne : Flibuste, Corsaires et Pirates (1650-1730)', '', 'PENDING', '', '2026-03-04 07:23:47.307048+00', NULL, NULL, NULL, ''),
	(1026, 'Raid de Dieppe par la marine anglaise', 1694, false, NULL, 'La marine anglaise bombarde Dieppe, un port français important, dans le but de détruire les navires corsaires et les infrastructures navales. Cette action visait à perturber la guerre de course française.', 'L''Âge d''Or de la Piraterie Caribéenne : Flibuste, Corsaires et Pirates (1650-1730)', '', 'PENDING', '', '2026-03-04 07:23:47.307048+00', NULL, NULL, NULL, ''),
	(1027, 'Fondation de l''American Institute of Mining Engineers (AIME)', 1871, false, NULL, 'L''American Institute of Mining Engineers (AIME), ancêtre de l''actuel American Institute of Mining, Metallurgical, and Petroleum Engineers (AIME), est fondé. Il joue un rôle crucial dans la diffusion des connaissances et des meilleures pratiques en sidérurgie.', 'La Révolution Industrielle et ses Impacts Mondiaux : Innovations, Migrations et Transformations Sociales (1850-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.307048+00', NULL, NULL, NULL, ''),
	(1028, 'Première production d''acier Bessemer en Australie (Lithgow)', 1875, false, NULL, 'La première coulée d''acier Bessemer en Australie a lieu à Lithgow, en Nouvelle-Galles du Sud. Cet événement marque le début de la production d''acier à grande échelle dans le pays.', 'La Révolution Industrielle et ses Impacts Mondiaux : Innovations, Migrations et Transformations Sociales (1850-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.307048+00', NULL, NULL, NULL, ''),
	(1029, 'Publication de l''étude Packages of Practices (Norman Borlaug, Mexique)', 1960, false, NULL, 'L''équipe de Norman Borlaug publie un guide des pratiques agricoles optimisées, marquant une étape clé dans la diffusion des techniques de la Révolution verte. Ces pratiques incluent l''utilisation de variétés de blé à haut rendement, d''engrais et de techniques d''irrigation.', 'La Révolution Industrielle et ses Impacts Mondiaux : Innovations, Migrations et Transformations Sociales (1850-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.307048+00', NULL, NULL, NULL, ''),
	(1030, 'Création de l''Institut International de Recherche sur le Riz (IRRI) aux Philippines', 1960, false, NULL, 'L''IRRI est fondé pour développer des variétés de riz à haut rendement et des techniques agricoles améliorées. Son travail a été crucial pour augmenter la production de riz en Asie et ailleurs.', 'La Révolution Industrielle et ses Impacts Mondiaux : Innovations, Migrations et Transformations Sociales (1850-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.307048+00', NULL, NULL, NULL, ''),
	(1031, 'Lancement du Programme National de Démonstration (National Demonstration Programme) en Inde', 1965, false, NULL, 'Le gouvernement indien lance un programme national pour démontrer l''efficacité des nouvelles variétés de blé et de riz à haut rendement. Ce programme a joué un rôle important dans l''adoption de ces variétés par les agriculteurs indiens.', 'La Révolution Industrielle et ses Impacts Mondiaux : Innovations, Migrations et Transformations Sociales (1850-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.307048+00', NULL, NULL, NULL, ''),
	(1032, 'Introduction de la variété de blé ''Sonora 64'' en Inde', 1963, false, NULL, 'La variété de blé ''Sonora 64'', développée au Mexique par Norman Borlaug, est introduite en Inde. Elle s''avère bien adaptée aux conditions locales et contribue à augmenter considérablement la production de blé.', 'La Révolution Industrielle et ses Impacts Mondiaux : Innovations, Migrations et Transformations Sociales (1850-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.307048+00', NULL, NULL, NULL, ''),
	(1033, 'Démonstration publique de TCP/IP entre l''University College London et l''USC/ISI', 1973, false, NULL, 'Première démonstration publique réussie de la communication via TCP/IP entre deux réseaux distincts : l''University College London (Royaume-Uni) et l''USC/ISI (États-Unis). Un moment clé pour la validation du protocole.', 'L''essor d''Internet et des réseaux sociaux : De la Guerre Froide à la révolution numérique (1969-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.307048+00', NULL, NULL, NULL, ''),
	(1160, 'Oda Nobunaga entre à Kyoto', 1568, false, NULL, 'Oda Nobunaga entre à Kyoto pour soutenir Ashikaga Yoshiaki et le placer comme shogun. Cet événement marque le début de l''ascension de Nobunaga et son rôle central dans la fin de l''époque Muromachi.', 'L''Époque des Samouraïs : Ascensions, Guerres et Déclin du Bushido', '', 'PENDING', '', '2026-03-04 07:23:47.332093+00', NULL, NULL, NULL, ''),
	(1034, 'Création d''Usenet par Tom Truscott et Jim Ellis', 1979, false, NULL, 'Tom Truscott et Jim Ellis, étudiants à l''Université Duke et à l''Université de Caroline du Nord à Chapel Hill, créent Usenet, un système de forums de discussion distribué sur le réseau UUCP. Il permet aux utilisateurs d''échanger des messages et des informations sur divers sujets.', 'L''essor d''Internet et des réseaux sociaux : De la Guerre Froide à la révolution numérique (1969-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.307048+00', NULL, NULL, NULL, ''),
	(1035, 'Création du groupe de discussion ''net.unix-wizards''', 1982, false, NULL, 'Le groupe de discussion ''net.unix-wizards'' est créé sur Usenet. Il devient un forum influent pour les discussions techniques approfondies sur les systèmes Unix et les sujets connexes.', 'L''essor d''Internet et des réseaux sociaux : De la Guerre Froide à la révolution numérique (1969-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.307048+00', NULL, NULL, NULL, ''),
	(1036, 'Publication de l''historique du logiciel Usenet (Usenet Software: History and Sources)', 1986, false, NULL, 'La publication du document ''Usenet Software: History and Sources'' par Geoff Collyer et Henry Spencer offre un aperçu détaillé de l''histoire et des sources des logiciels utilisés pour faire fonctionner Usenet.', 'L''essor d''Internet et des réseaux sociaux : De la Guerre Froide à la révolution numérique (1969-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.307048+00', NULL, NULL, NULL, ''),
	(1037, 'Annonce de la fin du support d''Usenet par Google Groupes', 2010, false, NULL, 'Google Groupes annonce la fin du support pour la publication de nouveaux messages sur Usenet via son interface web. Cela marque un déclin significatif de l''utilisation d''Usenet via cette plateforme populaire.', 'L''essor d''Internet et des réseaux sociaux : De la Guerre Froide à la révolution numérique (1969-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.307048+00', NULL, NULL, NULL, ''),
	(1038, 'Publication du rapport RAND sur les réseaux informatiques distribués', 1964, false, NULL, 'Paul Baran publie le rapport "On Distributed Communications Networks" chez RAND Corporation. Il y décrit un réseau de communication décentralisé, résistant aux attaques, qui influencera la conception d''Internet.', 'L''essor d''Internet et des réseaux sociaux : De la Guerre Froide à la révolution numérique (1969-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.307048+00', NULL, NULL, NULL, ''),
	(1039, 'Gil Eanes dépasse le Cap Bojador', 1434, false, NULL, 'Le navigateur portugais Gil Eanes réussit à franchir le Cap Bojador, longtemps considéré comme une limite infranchissable pour la navigation européenne. Cet événement ouvre la voie à l''exploration de la côte africaine plus au sud.', 'Les Grandes Découvertes Maritimes (1415-1763)', '', 'PENDING', '', '2026-03-04 07:23:47.307048+00', NULL, NULL, NULL, ''),
	(1040, 'Fin du règne de Moctezuma I', 1469, false, NULL, 'Moctezuma I décède, mettant fin à un règne de près de trente ans marqué par l''expansion militaire, la consolidation du pouvoir et d''importantes constructions à Tenochtitlan. Axayacatl lui succède.', 'L''Ascension et la Chute de l''Empire Aztèque : De Tenochtitlan à la Conquête Espagnole', '', 'PENDING', '', '2026-03-04 07:23:47.307048+00', NULL, NULL, NULL, ''),
	(1041, 'Apparition d''une comète visible dans le ciel de Tenochtitlan', 1509, false, NULL, 'Une comète brillante est observée dans le ciel nocturne. Les prêtres aztèques la considèrent comme un signe annonciateur de calamités à venir.', 'L''Ascension et la Chute de l''Empire Aztèque : De Tenochtitlan à la Conquête Espagnole', '', 'PENDING', '', '2026-03-04 07:23:47.307048+00', NULL, NULL, NULL, ''),
	(1042, 'Inauguration de la Maison de la Sagesse (Bayt al-Hikma) à Bagdad', 813, false, NULL, 'Le calife Al-Ma’mūn fonde officiellement la Maison de la Sagesse, une académie dédiée à la traduction, à la recherche et à la diffusion des connaissances scientifiques et philosophiques. Elle attire des érudits de diverses origines.', 'L''expansion de l''Islam : Conquêtes, Dynasties et Échanges Culturels (622 - 1258)', '', 'PENDING', '', '2026-03-04 07:23:47.307048+00', NULL, NULL, NULL, ''),
	(1043, 'Début du règne du calife Al-Mutawakkil', 847, false, NULL, 'Al-Mutawakkil accède au califat abbasside. Son règne est marqué par un virage conservateur et le début du déclin de l''influence des érudits et scientifiques.', 'L''expansion de l''Islam : Conquêtes, Dynasties et Échanges Culturels (622 - 1258)', '', 'PENDING', '', '2026-03-04 07:23:47.307048+00', NULL, NULL, NULL, ''),
	(1044, 'Proclamation du califat fatimide par Abdallah al-Mahdi Billah à Raqqada', 909, false, NULL, 'Abdallah al-Mahdi Billah prend le titre de calife, marquant la fondation du califat fatimide en Ifriqiya (actuelle Tunisie). Cet événement marque une rupture avec le califat abbasside de Bagdad.', 'L''expansion de l''Islam : Conquêtes, Dynasties et Échanges Culturels (622 - 1258)', '', 'PENDING', '', '2026-03-04 07:23:47.307048+00', NULL, NULL, NULL, ''),
	(1045, 'Assassinat du calife fatimide al-Amir Bi-Ahkamillah', 1130, false, NULL, 'Le calife fatimide al-Amir Bi-Ahkamillah est assassiné, plongeant le califat dans une crise de succession. Cet événement contribue au déclin du pouvoir fatimide en Égypte.', 'L''expansion de l''Islam : Conquêtes, Dynasties et Échanges Culturels (622 - 1258)', '', 'PENDING', '', '2026-03-04 07:23:47.307048+00', NULL, NULL, NULL, ''),
	(1046, 'Lancement des travaux de la section orientale du premier chemin de fer transcontinental (Union Pacific Railroad à Omaha)', 1865, false, NULL, 'L''Union Pacific Railroad débute la construction de la section orientale du chemin de fer transcontinental à Omaha, Nebraska. Cet événement marque le début de la course contre la Central Pacific pour achever la plus grande portion du chemin de fer.', 'L''Épopée du Far West Américain : De la Ruée vers l''Or aux Guerres Indiennes (1848-1890)', '', 'PENDING', '', '2026-03-04 07:23:47.307048+00', NULL, NULL, NULL, ''),
	(1048, 'Ban Chao, général Han, rétablit le contrôle chinois sur les Régions de l''Ouest après une période de troubles', 97, false, NULL, 'Ban Chao, un général de la dynastie Han, envoie son émissaire Gan Ying vers Rome. Bien que Gan Ying n''ait pas atteint Rome, son voyage témoigne de l''ambition d''étendre l''influence chinoise vers l''ouest.', 'La Route de la Soie : Échanges Commerciaux, Culturels et Militaires (Ier siècle - XIVe siècle)', '', 'PENDING', '', '2026-03-04 07:23:47.307048+00', NULL, NULL, NULL, ''),
	(1050, 'Première mention écrite du clou de girofle en Chine', 200, false, NULL, 'Le clou de girofle, originaire des Moluques (Indonésie), apparaît dans des écrits chinois, témoignant de son commerce croissant vers l''Asie de l''Est via les routes maritimes et terrestres.', 'La Route de la Soie : Échanges Commerciaux, Culturels et Militaires (Ier siècle - XIVe siècle)', '', 'PENDING', '', '2026-03-04 07:23:47.307048+00', NULL, NULL, NULL, ''),
	(1051, 'Traduction du Sūtra du Lotus en chinois par Kumārajīva', 406, false, NULL, 'Kumārajīva, un moine bouddhiste érudit, achève la traduction du Sūtra du Lotus, un texte Mahayana influent, en chinois classique. Cette traduction devient la version la plus largement diffusée et étudiée en Asie de l''Est.', 'La Route de la Soie : Échanges Commerciaux, Culturels et Militaires (Ier siècle - XIVe siècle)', '', 'PENDING', '', '2026-03-04 07:23:47.307048+00', NULL, NULL, NULL, ''),
	(1052, 'Fondation du monastère de Shaolin', 495, false, NULL, 'L''empereur Xiaowen de la dynastie Wei du Nord ordonne la construction du monastère de Shaolin au mont Song, en Chine. Ce monastère deviendra un centre important du bouddhisme Chan et des arts martiaux.', 'La Route de la Soie : Échanges Commerciaux, Culturels et Militaires (Ier siècle - XIVe siècle)', '', 'PENDING', '', '2026-03-04 07:23:47.307048+00', NULL, NULL, NULL, ''),
	(1053, 'Introduction du bouddhisme au Japon (date traditionnelle)', 552, false, NULL, 'Selon la tradition, le bouddhisme est officiellement introduit au Japon depuis le royaume de Baekje (Corée). Des statues et des textes bouddhistes sont offerts à la cour impériale.', 'La Route de la Soie : Échanges Commerciaux, Culturels et Militaires (Ier siècle - XIVe siècle)', '', 'PENDING', '', '2026-03-04 07:23:47.307048+00', NULL, NULL, NULL, ''),
	(1054, 'Construction du Hōryū-ji au Japon', 607, false, NULL, 'Le prince Shōtoku entreprend la construction du Hōryū-ji, un temple bouddhiste à Ikaruga, au Japon. Il est considéré comme l''un des plus anciens bâtiments en bois existants au monde et un exemple important de l''architecture bouddhiste.', 'La Route de la Soie : Échanges Commerciaux, Culturels et Militaires (Ier siècle - XIVe siècle)', '', 'PENDING', '', '2026-03-04 07:23:47.307048+00', NULL, NULL, NULL, ''),
	(1055, 'Abolition du système de domaines féodaux (han) et établissement des préfectures (ken)', 1871, false, NULL, 'Le gouvernement Meiji abolit officiellement le système de domaines féodaux (han) et les remplace par des préfectures (ken). Cet événement centralise le pouvoir et élimine les structures féodales.', 'L''Ère Meiji au Japon : Modernisation, Industrialisation et Impérialisme', '', 'PENDING', '', '2026-03-04 07:23:47.307048+00', NULL, NULL, NULL, ''),
	(1056, 'Fondation de la Banque Nationale du Japon (Dai-ichi Kokuritsu Ginkō)', 1873, false, NULL, 'La première banque nationale du Japon, la Dai-ichi Kokuritsu Ginkō, est fondée par Shibusawa Eiichi. Elle joue un rôle crucial dans le développement économique et financier du pays.', 'L''Ère Meiji au Japon : Modernisation, Industrialisation et Impérialisme', '', 'PENDING', '', '2026-03-04 07:23:47.307048+00', NULL, NULL, NULL, ''),
	(1057, 'Pétrarque découvre les lettres de Cicéron à Atticus à Vérone', 1345, false, NULL, 'Cette découverte a ravivé l''intérêt pour la littérature classique et a influencé la pensée humaniste de Pétrarque. Elle a contribué à la redécouverte des valeurs et des idées de l''Antiquité.', 'La Renaissance Italienne : Art, Science et Politique (1300-1600)', '', 'PENDING', '', '2026-03-04 07:23:47.307048+00', NULL, NULL, NULL, ''),
	(1058, 'Ouverture du Studio de Florence par le chancelier Coluccio Salutati', 1397, false, NULL, 'Salutati, chancelier de Florence, a fondé ce centre d''études humanistes. Il a attiré des érudits et a promu l''étude des textes classiques, contribuant à l''essor de l''humanisme à Florence.', 'La Renaissance Italienne : Art, Science et Politique (1300-1600)', '', 'PENDING', '', '2026-03-04 07:23:47.307048+00', NULL, NULL, NULL, ''),
	(1059, 'Traduction du grec au latin du traité ''De la nature des choses'' de Lucrèce par Poggio Bracciolini', 1417, false, NULL, 'Poggio Bracciolini redécouvre et traduit ce texte épicurien majeur. Sa diffusion a eu un impact significatif sur la pensée philosophique et scientifique de la Renaissance.', 'La Renaissance Italienne : Art, Science et Politique (1300-1600)', '', 'PENDING', '', '2026-03-04 07:23:47.307048+00', NULL, NULL, NULL, ''),
	(1060, 'Première édition imprimée complète des œuvres de Platon en grec (Opera Omnia)', 1513, false, NULL, 'Publiée à Venise par Alde Manuce, cette édition a rendu les œuvres de Platon plus accessibles aux érudits. Elle a favorisé l''étude directe des textes originaux et a contribué à la diffusion de la pensée platonicienne.', 'La Renaissance Italienne : Art, Science et Politique (1300-1600)', '', 'PENDING', '', '2026-03-04 07:23:47.307048+00', NULL, NULL, NULL, ''),
	(1061, 'Inauguration du Baptistère de Florence avec la porte nord de Ghiberti', 1424, false, NULL, 'La porte nord en bronze du Baptistère de Florence, réalisée par Lorenzo Ghiberti, est installée et inaugurée. Elle représente des scènes du Nouveau Testament.', 'La Renaissance Italienne : Art, Science et Politique (1300-1600)', '', 'PENDING', '', '2026-03-04 07:23:47.307048+00', NULL, NULL, NULL, ''),
	(1062, 'Cosme l''Ancien devient Grand Maître de la Loge de Florence', 1440, false, NULL, 'Cosme de Médicis consolide son influence politique et culturelle à Florence en prenant la tête de cette importante loge, favorisant ainsi le mécénat artistique et philosophique.', 'La Renaissance Italienne : Art, Science et Politique (1300-1600)', '', 'PENDING', '', '2026-03-04 07:23:47.307048+00', NULL, NULL, NULL, ''),
	(1063, 'Publication des « Don''ts and Be Carefuls » par Martin Quigley', 1927, false, NULL, 'Martin Quigley, éditeur de magazine catholique, publie une liste de règles de censure morale pour le cinéma, qui serviront de base au Code Hays. Cette liste marque le début de la formalisation de la censure dans l''industrie cinématographique américaine.', 'L''Âge d''or d''Hollywood : De l''avènement du parlant à la fin du Code Hays (1927-1968)', '', 'PENDING', '', '2026-03-04 07:23:47.307048+00', NULL, NULL, NULL, ''),
	(1064, 'Sortie du film « Qui a peur de Virginia Woolf ? » sans le sceau d''approbation du Code Hays', 1966, false, NULL, 'Warner Bros. sort « Qui a peur de Virginia Woolf ? » sans l''approbation de la Production Code Administration (PCA), défiant ouvertement le Code Hays en raison de son langage et de ses thèmes adultes.', 'L''Âge d''or d''Hollywood : De l''avènement du parlant à la fin du Code Hays (1927-1968)', '', 'PENDING', '', '2026-03-04 07:23:47.307048+00', NULL, NULL, NULL, ''),
	(1065, 'Lancement du Commodore PET 2001', 1977, false, NULL, 'Commodore International introduit le PET 2001 (Personal Electronic Transactor), un ordinateur personnel tout-en-un. Il est l''un des premiers ordinateurs personnels complets disponibles sur le marché.', 'La Révolution Informatique : Des premiers ordinateurs personnels à l''ère d''internet mobile (1970-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.307048+00', NULL, NULL, NULL, ''),
	(1066, 'Publication des spécifications du bus ISA par IBM', 1981, false, NULL, 'IBM publie les spécifications techniques du bus ISA (Industry Standard Architecture) utilisé dans l''IBM PC. Cette ouverture favorise le développement de cartes d''extension par des tiers et contribue à l''essor de l''écosystème PC.', 'La Révolution Informatique : Des premiers ordinateurs personnels à l''ère d''internet mobile (1970-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.307048+00', NULL, NULL, NULL, ''),
	(1067, 'Lancement du tableur Lotus 1-2-3', 1983, false, NULL, 'Lotus Development Corporation lance Lotus 1-2-3, un tableur qui devient rapidement un standard sur l''IBM PC. Son interface conviviale et ses fonctionnalités avancées contribuent à populariser l''informatique personnelle auprès des entreprises.', 'La Révolution Informatique : Des premiers ordinateurs personnels à l''ère d''internet mobile (1970-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.307048+00', NULL, NULL, NULL, ''),
	(1068, 'Introduction du processeur Intel 80386', 1985, false, NULL, 'Intel lance le processeur 80386 (ou 386), un microprocesseur 32 bits qui améliore considérablement les performances des ordinateurs personnels. Il permet l''exécution de systèmes d''exploitation plus complexes et d''applications plus gourmandes en ressources.', 'La Révolution Informatique : Des premiers ordinateurs personnels à l''ère d''internet mobile (1970-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.307048+00', NULL, NULL, NULL, ''),
	(1069, 'Mise à disposition du code source du World Wide Web par le CERN', 1993, false, NULL, 'En avril 1993, le CERN annonce que le code source du World Wide Web sera mis à disposition gratuitement pour tous. Cette décision contribue à la diffusion rapide et à l''adoption massive du Web.', 'La Révolution Informatique : Des premiers ordinateurs personnels à l''ère d''internet mobile (1970-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.307048+00', NULL, NULL, NULL, ''),
	(1070, 'Publication de la RFC 1945, spécifiant HTTP/1.0', 1996, false, NULL, 'En mai 1996, la RFC 1945 est publiée, définissant officiellement le protocole HTTP/1.0. Cette spécification normalise le fonctionnement du protocole et favorise son interopérabilité.', 'La Révolution Informatique : Des premiers ordinateurs personnels à l''ère d''internet mobile (1970-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.307048+00', NULL, NULL, NULL, ''),
	(1071, 'Lancement du premier téléphone portable 1G (Motorola DynaTAC 8000x)', 1983, false, NULL, 'Motorola commercialise le DynaTAC 8000x, considéré comme le premier téléphone portable commercial. Il marque le début de l''ère de la téléphonie mobile.', 'La Révolution Informatique : Des premiers ordinateurs personnels à l''ère d''internet mobile (1970-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.307048+00', NULL, NULL, NULL, ''),
	(1072, 'Début de la construction de la ville de Salvador (Bahia)', 1549, false, NULL, 'Tomé de Sousa ordonne le début de la construction de Salvador, qui devient la première capitale du Brésil colonial. La ville est conçue comme un centre administratif et militaire pour consolider le pouvoir portugais.', 'L''Exploration du Nouveau Monde : Voyages, Conquêtes et Colonisation (1492-1700)', '', 'PENDING', '', '2026-03-04 07:23:47.307048+00', NULL, NULL, NULL, ''),
	(1073, 'Fondation de la Compagnie anglaise de Guinée (Company of Royal Adventurers into Africa)', 1660, false, NULL, 'Création de la Compagnie anglaise de Guinée, une société commerciale chargée de la traite négrière et du commerce avec l''Afrique de l''Ouest. Elle marque l''implication croissante de l''Angleterre dans le commerce triangulaire.', 'La traite négrière transatlantique : Du commerce triangulaire à l''abolition', '', 'PENDING', '', '2026-03-04 07:23:47.307048+00', NULL, NULL, NULL, ''),
	(1074, 'Adoption du Code Noir en Louisiane', 1724, false, NULL, 'Extension du Code Noir français à la Louisiane, réglementant l''esclavage et les relations entre maîtres et esclaves. Il institutionnalise l''esclavage dans cette colonie française.', 'La traite négrière transatlantique : Du commerce triangulaire à l''abolition', '', 'PENDING', '', '2026-03-04 07:23:47.307048+00', NULL, NULL, NULL, ''),
	(1075, 'Publication de l''essai de Thomas Jefferson Notes on the State of Virginia', 1785, false, NULL, 'Thomas Jefferson publie ''Notes on the State of Virginia'', qui contient des observations sur l''esclavage et la société de plantation. Il y expose ses vues sur l''infériorité raciale et la nécessité de la colonisation.', 'La traite négrière transatlantique : Du commerce triangulaire à l''abolition', '', 'PENDING', '', '2026-03-04 07:23:47.320013+00', NULL, NULL, NULL, ''),
	(1076, 'Sortie de "Johnny B. Goode" par Chuck Berry', 1958, false, NULL, 'Chuck Berry sort "Johnny B. Goode", un des morceaux les plus emblématiques du rock ''n'' roll. La chanson raconte l''histoire d''un jeune guitariste talentueux et ambitieux.', 'L''Histoire du Rock ''n'' Roll : De ses origines à la Britpop', '', 'PENDING', '', '2026-03-04 07:23:47.320013+00', NULL, NULL, NULL, ''),
	(1077, 'Sortie de l''album "The Shape of Jazz to Come" d''Ornette Coleman', 1959, false, NULL, 'Ornette Coleman sort "The Shape of Jazz to Come", un album de free jazz révolutionnaire. Bien que jazz, il influence l''expérimentation et l''improvisation dans le rock.', 'L''Histoire du Rock ''n'' Roll : De ses origines à la Britpop', '', 'PENDING', '', '2026-03-04 07:23:47.320013+00', NULL, NULL, NULL, ''),
	(1078, 'Arrestation de Chuck Berry pour violation du Mann Act', 1959, false, NULL, 'Chuck Berry est arrêté le 28 décembre 1959 pour avoir transporté une mineure à travers les frontières de l''État, en violation du Mann Act. Cet événement marque une interruption significative dans sa carrière.', 'L''Histoire du Rock ''n'' Roll : De ses origines à la Britpop', '', 'PENDING', '', '2026-03-04 07:23:47.320013+00', NULL, NULL, NULL, ''),
	(1079, 'Sortie de l''album "Surfin'' Safari" des Beach Boys', 1962, false, NULL, 'Les Beach Boys sortent leur premier album, "Surfin'' Safari", en octobre 1962. Cet album marque le début de leur succès et contribue à populariser la musique surf rock, une branche du rock ''n'' roll.', 'L''Histoire du Rock ''n'' Roll : De ses origines à la Britpop', '', 'PENDING', '', '2026-03-04 07:23:47.320013+00', NULL, NULL, NULL, ''),
	(1080, 'Sortie de l''album ''Led Zeppelin IV''', 1971, false, NULL, 'Le quatrième album de Led Zeppelin, souvent appelé ''Led Zeppelin IV'', sort le 8 novembre 1971. Il contient le titre emblématique ''Stairway to Heaven''.', 'L''Histoire du Rock ''n'' Roll : De ses origines à la Britpop', '', 'PENDING', '', '2026-03-04 07:23:47.320013+00', NULL, NULL, NULL, ''),
	(1081, 'Première diffusion de l''émission de télévision "MTV" aux États-Unis', 1981, false, NULL, 'MTV (Music Television) est lancée, marquant un tournant dans la promotion de la musique et l''essor des clips vidéo. Son impact est majeur sur la New Wave et les genres musicaux suivants.', 'L''Histoire du Rock ''n'' Roll : De ses origines à la Britpop', '', 'PENDING', '', '2026-03-04 07:23:47.320013+00', NULL, NULL, NULL, ''),
	(1082, 'Sortie de l''album "Thriller" de Michael Jackson', 1982, false, NULL, 'L''album "Thriller" de Michael Jackson est lancé, devenant l''album le plus vendu de tous les temps. Il influence profondément la musique pop et la culture visuelle des années 1980.', 'L''Histoire du Rock ''n'' Roll : De ses origines à la Britpop', '', 'PENDING', '', '2026-03-04 07:23:47.320013+00', NULL, NULL, NULL, ''),
	(1083, 'Inauguration du Théâtre Optique d''Émile Reynaud au Musée Grévin', 1892, false, NULL, 'Le 28 octobre, Émile Reynaud présente ses Pantomimes Lumineuses, des dessins animés projetés sur grand écran, au Musée Grévin à Paris. Bien qu''antérieur au cinématographe, cet événement est une étape importante dans l''histoire du cinéma d''animation.', 'L''Histoire du Cinéma : Des Frères Lumière aux Blockbusters Numériques (1895-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.320013+00', NULL, NULL, NULL, ''),
	(1084, 'Sortie du film "Les Quatre Cents Coups" de François Truffaut', 1959, false, NULL, 'Le film marque un tournant dans le cinéma français et lance officiellement la Nouvelle Vague. Il est présenté au Festival de Cannes et remporte le Prix de la mise en scène.', 'L''Histoire du Cinéma : Des Frères Lumière aux Blockbusters Numériques (1895-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.320013+00', NULL, NULL, NULL, ''),
	(1085, 'Sortie du film "Persona" d''Ingmar Bergman en Suède', 1966, false, NULL, 'Ce film, considéré comme l''un des chefs-d''œuvre de Bergman, explore les thèmes de l''identité et de la communication. Il marque une étape importante dans le cinéma d''auteur européen.', 'L''Histoire du Cinéma : Des Frères Lumière aux Blockbusters Numériques (1895-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.320013+00', NULL, NULL, NULL, ''),
	(1086, 'Sortie du film "Aguirre, la colère de Dieu" de Werner Herzog en Allemagne de l''Ouest', 1972, false, NULL, 'Ce film, avec Klaus Kinski dans le rôle principal, est un exemple marquant du Nouveau Cinéma Allemand. Il raconte l''expédition d''un conquistador fou à la recherche de l''Eldorado.', 'L''Histoire du Cinéma : Des Frères Lumière aux Blockbusters Numériques (1895-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.320013+00', NULL, NULL, NULL, ''),
	(1087, 'Sortie du film Toy Story', 1995, false, NULL, 'Premier long métrage d''animation entièrement réalisé en images de synthèse, Toy Story révolutionne l''industrie de l''animation. Il ouvre la voie à une nouvelle ère de films d''animation.', 'L''Histoire du Cinéma : Des Frères Lumière aux Blockbusters Numériques (1895-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.320013+00', NULL, NULL, NULL, ''),
	(1088, 'Établissement de la Compagnie de Saint-Domingue', 1698, false, NULL, 'Création de la Compagnie de Saint-Domingue, une compagnie commerciale française chargée de développer et d''exploiter les ressources de la colonie, notamment le sucre.', 'L''Ère des Pirates des Caraïbes : Du Flibuste à l''Âge d''Or (1650-1730)', '', 'PENDING', '', '2026-03-04 07:23:47.320013+00', NULL, NULL, NULL, ''),
	(1090, 'Construction du temple de Faxian à Dunhuang', 366, false, NULL, 'Le moine Yue Zun initie la construction du temple de Faxian près des grottes de Mogao à Dunhuang, qui devient un important centre bouddhiste et une étape clé pour les caravanes voyageant le long de la Route de la Soie. Cela facilite les échanges culturels et religieux.', 'La Route de la Soie : Du Commerce Caravanier aux Empires Commerciaux (100-1750)', '', 'PENDING', '', '2026-03-04 07:23:47.320013+00', NULL, NULL, NULL, ''),
	(1091, 'Début du règne de l''empereur Taizong, initiateur de l''âge d''or des Tang', 626, false, NULL, 'Li Shimin accède au trône sous le nom d''empereur Taizong, inaugurant une période de stabilité politique, d''expansion territoriale et de prospérité économique qui favorise le commerce et les échanges culturels le long de la Route de la Soie.', 'La Route de la Soie : Du Commerce Caravanier aux Empires Commerciaux (100-1750)', '', 'PENDING', '', '2026-03-04 07:23:47.320013+00', NULL, NULL, NULL, ''),
	(1092, 'Construction de la Grande Pagode de l''Oie Sauvage à Xi''an', 704, false, NULL, 'Achèvement de la Grande Pagode de l''Oie Sauvage à Chang''an (Xi''an), initialement construite en 652, pour abriter les écritures bouddhistes rapportées d''Inde par le moine Xuanzang, symbolisant les échanges religieux et culturels facilités par la Route de la Soie.', 'La Route de la Soie : Du Commerce Caravanier aux Empires Commerciaux (100-1750)', '', 'PENDING', '', '2026-03-04 07:23:47.320013+00', NULL, NULL, NULL, ''),
	(1093, 'Ouverture du comptoir commercial britannique à Surat', 1613, false, NULL, 'La Compagnie anglaise des Indes orientales obtient l''autorisation d''établir un comptoir commercial permanent à Surat, en Inde, en 1613. Cet événement marque une étape importante dans l''expansion de l''influence britannique en Inde.', 'La Route de la Soie : Du Commerce Caravanier aux Empires Commerciaux (100-1750)', '', 'PENDING', '', '2026-03-04 07:23:47.320013+00', NULL, NULL, NULL, ''),
	(1094, 'Brevet américain n° 1,773,980 accordé à Philo Farnsworth pour son tube dissecteur d''image', 1930, false, NULL, 'Philo Farnsworth reçoit le brevet américain n° 1,773,980 pour son tube dissecteur d''image, un composant clé de son système de télévision électronique. Ce brevet consolide sa position en tant qu''inventeur majeur dans le domaine.', 'L''Histoire de la télévision : Des premières émissions expérimentales à l''ère du streaming', '', 'PENDING', '', '2026-03-04 07:23:47.320013+00', NULL, NULL, NULL, ''),
	(1095, 'Première diffusion du "Texaco Star Theater" avec Milton Berle sur NBC', 1948, false, NULL, 'Le "Texaco Star Theater", animé par Milton Berle, est diffusé pour la première fois sur NBC. Le spectacle devient rapidement un phénomène et contribue à populariser la télévision auprès du grand public.', 'L''Histoire de la télévision : Des premières émissions expérimentales à l''ère du streaming', '', 'PENDING', '', '2026-03-04 07:23:47.320013+00', NULL, NULL, NULL, ''),
	(1096, 'Première diffusion de "The Twilight Zone" sur CBS', 1959, false, NULL, '"The Twilight Zone", créé par Rod Serling, est diffusé pour la première fois sur CBS. La série d''anthologie de science-fiction et de fantastique devient un succès critique et commercial, explorant des thèmes sociaux et moraux complexes.', 'L''Histoire de la télévision : Des premières émissions expérimentales à l''ère du streaming', '', 'PENDING', '', '2026-03-04 07:23:47.320013+00', NULL, NULL, NULL, ''),
	(1097, 'Première diffusion de ''Snack Bar'' sur TVEC', 1976, false, NULL, 'Première diffusion de l''émission ''Snack Bar'' sur TVEC (Télévision éducative et communautaire) le 27 septembre 1976. Cette émission jeunesse marque les débuts de la production télévisuelle locale au Québec.', 'L''Histoire de la télévision : Des premières émissions expérimentales à l''ère du streaming', '', 'PENDING', '', '2026-03-04 07:23:47.320013+00', NULL, NULL, NULL, ''),
	(1098, 'Première démonstration du protocole TCP/IP', 1977, false, NULL, 'Une démonstration impliquant trois réseaux différents (ARPANET, Packet Radio Net, et Atlantic Packet Satellite Net) a lieu. C''est une étape cruciale vers l''internet moderne.', 'La Révolution Numérique : De l''Ordinateur Personnel à Internet (1971-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.320013+00', NULL, NULL, NULL, ''),
	(1099, 'Lancement du projet GNU', 1983, false, NULL, 'Richard Stallman annonce le projet GNU (GNU''s Not Unix) dans le but de créer un système d''exploitation entièrement libre. C''est un événement fondateur du mouvement du logiciel libre.', 'La Révolution Numérique : De l''Ordinateur Personnel à Internet (1971-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.320013+00', NULL, NULL, NULL, ''),
	(1100, 'Invention de la Spinning Jenny par James Hargreaves', 1764, false, NULL, 'James Hargreaves invente la Spinning Jenny, une machine à filer qui permet de produire plusieurs fils simultanément. Cette invention marque une étape importante dans la mécanisation de l''industrie textile.', 'La Révolution Industrielle : Innovations, Inventions et Impact Social (1760-1914)', '', 'PENDING', '', '2026-03-04 07:23:47.320013+00', NULL, NULL, NULL, ''),
	(1101, 'Invention de la Spinning Mule par Samuel Crompton', 1779, false, NULL, 'Samuel Crompton invente la Spinning Mule, combinant les principes de la Spinning Jenny et de la Water Frame. Cette machine produit un fil plus fin et plus résistant, améliorant la qualité des textiles.', 'La Révolution Industrielle : Innovations, Inventions et Impact Social (1760-1914)', '', 'PENDING', '', '2026-03-04 07:23:47.320013+00', NULL, NULL, NULL, ''),
	(1102, 'Brevet du métier à tisser mécanique par Edmund Cartwright', 1785, false, NULL, 'Edmund Cartwright brevète le métier à tisser mécanique, une machine automatisant le processus de tissage. Cette invention accélère la production de tissus et réduit la dépendance à la main-d''œuvre.', 'La Révolution Industrielle : Innovations, Inventions et Impact Social (1760-1914)', '', 'PENDING', '', '2026-03-04 07:23:47.320013+00', NULL, NULL, NULL, ''),
	(1103, 'Établissement de la première usine textile à énergie hydraulique aux États-Unis (Slater Mill)', 1793, false, NULL, 'Samuel Slater établit la Slater Mill à Pawtucket, Rhode Island, la première usine textile américaine utilisant l''énergie hydraulique. Cet événement marque le début de l''industrialisation textile aux États-Unis.', 'La Révolution Industrielle : Innovations, Inventions et Impact Social (1760-1914)', '', 'PENDING', '', '2026-03-04 07:23:47.320013+00', NULL, NULL, NULL, ''),
	(1104, 'Construction du premier pont en fonte au monde (Iron Bridge)', 1779, false, NULL, 'L''Iron Bridge, construit sur la rivière Severn en Angleterre, est le premier pont de ce type. Il marque une étape importante dans l''utilisation du fer dans la construction.', 'La Révolution Industrielle : Innovations, Inventions et Impact Social (1760-1914)', '', 'PENDING', '', '2026-03-04 07:23:47.320013+00', NULL, NULL, NULL, ''),
	(1105, 'Invention du procédé de puddlage par Henry Cort', 1784, false, NULL, 'Henry Cort brevète le procédé de puddlage, une technique permettant de produire du fer de meilleure qualité en éliminant les impuretés. Cette invention révolutionne la production de fer.', 'La Révolution Industrielle : Innovations, Inventions et Impact Social (1760-1914)', '', 'IMAGE_DONE', 'A blacksmith (Henry Cort) working at a forge, demonstrating the puddling process for iron production in a workshop filled with tools and materials. The scene captures him stirring molten iron in a large hearth, surrounded by wooden benches and barrels. The atmosphere is bustling with assistants clad in period-appropriate clothing made of wool and linen, wearing hats and aprons, without modern fastenings. The workshop is dimly lit by flickering oil lamps and the warm glow of the forge fire, creating shadows that enhance the historical setting. This is depicted in a historical oil painting in a classical museum style.', '2026-03-04 07:23:47.320013+00', NULL, NULL, NULL, 'http://127.0.0.1:54321/storage/v1/object/public/evenements-image/chambre_noire_invention_du_proc_d__de_puddla_1772267181217.webp'),
	(1106, 'Première démonstration publique de la locomotive à vapeur de Richard Trevithick à Camborne, Cornouailles', 1801, false, NULL, 'Richard Trevithick démontre publiquement sa locomotive à vapeur, surnommée "Puffing Devil", à Camborne, marquant une étape importante dans le développement du transport ferroviaire. Bien que ce ne soit pas sur des rails, cela a prouvé le concept.', 'La Révolution Industrielle : Innovations, Inventions et Impact Social (1760-1914)', '', 'PENDING', '', '2026-03-04 07:23:47.320013+00', NULL, NULL, NULL, ''),
	(1107, 'Première ascension réussie du pilier ouest du Salathé Wall par Tom Frost, Royal Robbins et Chuck Pratt', 1961, false, NULL, 'L''ascension du Salathé Wall, dans le Yosemite, marque une étape importante dans l''escalade de big wall. Elle a duré cinq jours.', 'La Conquête de l''Everest : Des Premières Tentatives à l''Ère des Ascensions Commerciales', '', 'PENDING', '', '2026-03-04 07:23:47.320013+00', NULL, NULL, NULL, ''),
	(1108, 'Ouverture du premier magasin North Face à San Francisco', 1966, false, NULL, 'Douglas Tompkins ouvre le premier magasin North Face à San Francisco, marquant le début de l''ascension de cette marque dans le monde de l''équipement d''expédition et d''alpinisme. Ce magasin devient rapidement un point de rencontre pour les passionnés d''aventure.', 'La Conquête de l''Everest : Des Premières Tentatives à l''Ère des Ascensions Commerciales', '', 'PENDING', '', '2026-03-04 07:23:47.320013+00', NULL, NULL, NULL, ''),
	(1109, 'Fondation de São Jorge da Mina (Elmina) par les Portugais', 1482, false, NULL, 'Construction du premier comptoir commercial européen permanent en Afrique subsaharienne, initialement pour le commerce de l''or, puis impliqué dans la traite des esclaves. Ce comptoir deviendra un point central de la traite atlantique.', 'La Colonisation de l''Afrique : Explorations, Rivalités et Indépendances (1500-1975)', '', 'PENDING', '', '2026-03-04 07:23:47.320013+00', NULL, NULL, NULL, ''),
	(1110, 'Adoption du "Slave Trade Act" par le Parlement britannique', 1807, false, NULL, 'Loi interdisant la traite des esclaves dans l''Empire britannique. Bien que l''esclavage lui-même ne soit pas aboli immédiatement, cette loi marque un tournant majeur dans la lutte contre la traite atlantique.', 'La Colonisation de l''Afrique : Explorations, Rivalités et Indépendances (1500-1975)', '', 'PENDING', '', '2026-03-04 07:23:47.320013+00', NULL, NULL, NULL, ''),
	(1111, 'Première ascension du Kilimandjaro par Hans Meyer et Ludwig Purtscheller', 1889, false, NULL, 'Le géographe allemand Hans Meyer et le grimpeur autrichien Ludwig Purtscheller réussissent la première ascension documentée du Kilimandjaro, le plus haut sommet d''Afrique. Cet exploit marque un tournant dans l''exploration de l''Afrique de l''Est.', 'La Colonisation de l''Afrique : Explorations, Rivalités et Indépendances (1500-1975)', '', 'PENDING', '', '2026-03-04 07:23:47.320013+00', NULL, NULL, NULL, ''),
	(1112, 'Publication de la carte de l''Afrique de l''Ouest par Jean-Baptiste Bourguignon d''Anville', 1749, false, NULL, 'Le cartographe français Jean-Baptiste Bourguignon d''Anville publie une carte détaillée de l''Afrique de l''Ouest, basée sur les informations disponibles à l''époque. Cette carte représente une avancée significative dans la cartographie du continent.', 'La Colonisation de l''Afrique : Explorations, Rivalités et Indépendances (1500-1975)', '', 'PENDING', '', '2026-03-04 07:23:47.320013+00', NULL, NULL, NULL, ''),
	(1113, 'Début du règne de Béhanzin au Dahomey', 1889, false, NULL, 'Béhanzin accède au trône du Dahomey (actuel Bénin) le 1er janvier. Il résiste à l''expansion coloniale française jusqu''en 1894.', 'La Colonisation de l''Afrique : Explorations, Rivalités et Indépendances (1500-1975)', '', 'PENDING', '', '2026-03-04 07:23:47.320013+00', NULL, NULL, NULL, ''),
	(1114, 'Indépendance de l''Angola', 1975, false, NULL, 'L''Angola proclame son indépendance du Portugal le 11 novembre 1975, après une longue guerre de libération. L''indépendance est immédiatement suivie d''une guerre civile.', 'La Colonisation de l''Afrique : Explorations, Rivalités et Indépendances (1500-1975)', '', 'PENDING', '', '2026-03-04 07:23:47.320013+00', NULL, NULL, NULL, ''),
	(1115, 'Sortie du film À nous la liberté de René Clair', 1931, false, NULL, 'Ce film français, une comédie musicale satirique, influence le cinéma parlant et inspire des œuvres comme Les Temps modernes de Charlie Chaplin.', 'L''Âge d''Or d''Hollywood : Des Studios aux Blockbusters (1915-1969)', '', 'PENDING', '', '2026-03-04 07:23:47.320013+00', NULL, NULL, NULL, ''),
	(1116, 'Ouverture du "Hollywood Canteen" pour soutenir les soldats en permission', 1942, false, NULL, 'Inauguration du Hollywood Canteen, un club géré par des stars de cinéma et destiné à offrir gratuitement divertissement et nourriture aux soldats américains en permission pendant la Seconde Guerre mondiale. Il symbolise l''engagement d''Hollywood envers les troupes.', 'L''Âge d''Or d''Hollywood : Des Studios aux Blockbusters (1915-1969)', '', 'PENDING', '', '2026-03-04 07:23:47.320013+00', NULL, NULL, NULL, ''),
	(1117, 'Première projection du Cinerama au Broadway Theatre de New York', 1952, false, NULL, 'Le Cinerama, avec son écran incurvé et ses trois projecteurs synchronisés, offre une expérience immersive. Le premier film projeté est "This is Cinerama".', 'L''Âge d''Or d''Hollywood : Des Studios aux Blockbusters (1915-1969)', '', 'PENDING', '', '2026-03-04 07:23:47.320013+00', NULL, NULL, NULL, ''),
	(1118, 'Ouverture du Sunset Cafe à Chicago', 1921, false, NULL, 'Ce club devient un lieu emblématique du jazz à Chicago, accueillant des artistes tels que Louis Armstrong et Earl Hines. Il contribue à l''essor du jazz dans la ville.', 'L''histoire de la Musique Populaire : Des Années Folles à l''Ère du Streaming (1920-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.320013+00', NULL, NULL, NULL, ''),
	(1119, 'Premier enregistrement des "Louis Armstrong and His Hot Five"', 1925, false, NULL, 'Cette série d''enregistrements marque un tournant dans l''histoire du jazz, mettant en valeur le talent d''improvisation de Louis Armstrong. Ils influencent de nombreux musiciens.', 'L''histoire de la Musique Populaire : Des Années Folles à l''Ère du Streaming (1920-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.320013+00', NULL, NULL, NULL, ''),
	(1120, 'Inauguration du Savoy Ballroom à Harlem, New York', 1926, false, NULL, 'Le Savoy devient un lieu de danse et de musique jazz de renommée mondiale, connu pour ses compétitions de danse et ses performances musicales. Il contribue à populariser le jazz et la culture afro-américaine.', 'L''histoire de la Musique Populaire : Des Années Folles à l''Ère du Streaming (1920-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.320013+00', NULL, NULL, NULL, ''),
	(1121, 'Première du film ''Sun Valley Serenade'' avec Glenn Miller et son orchestre', 1941, false, NULL, 'Le 29 août 1941, le film ''Sun Valley Serenade'', mettant en vedette Glenn Miller et son orchestre, sort en salles. Le film contribue à populariser davantage le swing et la musique de Miller auprès d''un large public.', 'L''histoire de la Musique Populaire : Des Années Folles à l''Ère du Streaming (1920-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.320013+00', NULL, NULL, NULL, ''),
	(1122, 'Sortie de l''album "Here''s Little Richard" de Little Richard', 1957, false, NULL, 'Specialty Records sort l''album "Here''s Little Richard", qui comprend des succès comme "Long Tall Sally" et "Tutti Frutti". L''album consolide la position de Little Richard comme l''une des figures les plus importantes du rock and roll.', 'L''histoire de la Musique Populaire : Des Années Folles à l''Ère du Streaming (1920-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.320013+00', NULL, NULL, NULL, ''),
	(1123, 'Première du film ''A Hard Day''s Night'' des Beatles', 1964, false, NULL, 'Première du film ''A Hard Day''s Night'' des Beatles à Londres. Le film, une comédie musicale, reçoit un accueil critique et commercial très favorable.', 'L''histoire de la Musique Populaire : Des Années Folles à l''Ère du Streaming (1920-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.320013+00', NULL, NULL, NULL, ''),
	(1124, 'Invention du sampler Fairlight CMI', 1979, false, NULL, 'La société australienne Fairlight lance le Fairlight CMI (Computer Musical Instrument), l''un des premiers échantillonneurs numériques. Il révolutionne la production musicale en permettant aux musiciens d''enregistrer et de manipuler des sons.', 'L''histoire de la Musique Populaire : Des Années Folles à l''Ère du Streaming (1920-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.320013+00', NULL, NULL, NULL, ''),
	(1125, 'Première édition du festival Detroit Electronic Music Festival (DEMF)', 2000, false, NULL, 'La première édition du Detroit Electronic Music Festival (DEMF), plus tard connu sous le nom de Movement, a lieu à Detroit. Il célèbre la musique techno et la culture électronique de la ville.', 'L''histoire de la Musique Populaire : Des Années Folles à l''Ère du Streaming (1920-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.320013+00', NULL, NULL, NULL, ''),
	(1126, 'João Gonçalves Zarco et Tristão Vaz Teixeira découvrent l''île de Madère', 1419, false, NULL, 'Les navigateurs portugais João Gonçalves Zarco et Tristão Vaz Teixeira découvrent l''île de Madère. Cette découverte ouvre la voie à la colonisation et à l''exploitation de l''île.', 'Les Grandes Découvertes Maritimes : Explorations et Cartographie du Monde', '', 'PENDING', '', '2026-03-04 07:23:47.332093+00', NULL, NULL, NULL, ''),
	(1127, 'Diogo Cão atteint l''embouchure du fleuve Congo', 1482, false, NULL, 'L''explorateur portugais Diogo Cão atteint l''embouchure du fleuve Congo. Cet événement marque une avancée significative dans l''exploration de la côte ouest de l''Afrique.', 'Les Grandes Découvertes Maritimes : Explorations et Cartographie du Monde', '', 'PENDING', '', '2026-03-04 07:23:47.332093+00', NULL, NULL, NULL, ''),
	(1128, 'Début du siège de Nassau par les forces franco-espagnoles', 1703, false, NULL, 'Les forces franco-espagnoles attaquent Nassau, marquant une période d''instabilité croissante dans la région. Cet événement contribue à l''émergence de la piraterie comme moyen de survie et de résistance.', 'Le Siècle d''or de la Piraterie (1650-1730)', '', 'PENDING', '', '2026-03-04 07:23:47.332093+00', NULL, NULL, NULL, ''),
	(1129, 'Audience de Macartney avec l''empereur Qianlong à Jehol', 1793, false, NULL, 'George Macartney rencontre l''empereur Qianlong à Jehol (actuelle Chengde), résidence d''été impériale. Le refus de Macartney de pratiquer le kowtow complet est perçu comme un affront, entravant les négociations.', 'L''Expansion du Commerce Mondial : Routes Maritimes et Échanges Culturels (1500-1850)', '', 'PENDING', '', '2026-03-04 07:23:47.332093+00', NULL, NULL, NULL, ''),
	(1130, 'Publication du livre ''Half Mile Down'' de William Beebe relatant ses expériences bathysphériques', 1934, false, NULL, 'En novembre 1934, William Beebe publie ''Half Mile Down'', un récit détaillé de ses aventures et observations lors des plongées bathysphériques avec Otis Barton. Le livre popularise l''exploration des profondeurs marines auprès du grand public.', 'L''exploration du fond des océans : Du bathyscaphe Trieste à la découverte des sources hydrothermales', '', 'PENDING', '', '2026-03-04 07:23:47.332093+00', NULL, NULL, NULL, ''),
	(1131, 'Début du Projet FAMOUS avec la première plongée du bathyscaphe Archimède dans le rift médio-atlantique', 1973, false, NULL, 'Le bathyscaphe Archimède effectue sa première plongée dans le rift médio-atlantique, marquant le début officiel du Projet FAMOUS. Cette plongée initiale permet une reconnaissance visuelle du terrain sous-marin et la collecte de données préliminaires.', 'L''exploration du fond des océans : Du bathyscaphe Trieste à la découverte des sources hydrothermales', '', 'PENDING', '', '2026-03-04 07:23:47.332093+00', NULL, NULL, NULL, ''),
	(1132, 'Première observation directe de cheminées hydrothermales actives lors du Projet FAMOUS', 1974, false, NULL, 'Des scientifiques du Projet FAMOUS observent pour la première fois des cheminées hydrothermales actives sur la dorsale médio-atlantique. Cette découverte confirme l''existence de processus hydrothermaux et de communautés biologiques uniques associées.', 'L''exploration du fond des océans : Du bathyscaphe Trieste à la découverte des sources hydrothermales', '', 'PENDING', '', '2026-03-04 07:23:47.332093+00', NULL, NULL, NULL, ''),
	(1133, 'Publication des premiers résultats majeurs du Projet FAMOUS dans la revue Nature', 1977, false, NULL, 'Les premiers résultats significatifs du Projet FAMOUS sont publiés dans la revue scientifique Nature. Ces publications présentent les découvertes clés concernant la géologie, l''hydrothermalisme et la biologie des dorsales médio-océaniques.', 'L''exploration du fond des océans : Du bathyscaphe Trieste à la découverte des sources hydrothermales', '', 'PENDING', '', '2026-03-04 07:23:47.332093+00', NULL, NULL, NULL, ''),
	(1134, 'Publication de l''article scientifique initial sur la découverte des sources hydrothermales des Galapagos Rift dans la revue Science', 1979, false, NULL, 'L''article détaille les observations et analyses des communautés biologiques uniques et des processus chimiques associés aux évents. Il marque une étape cruciale dans la reconnaissance de ces écosystèmes.', 'L''exploration du fond des océans : Du bathyscaphe Trieste à la découverte des sources hydrothermales', '', 'PENDING', '', '2026-03-04 07:23:47.332093+00', NULL, NULL, NULL, ''),
	(1135, 'Premier déploiement du ROV Jason lors d''une expédition de l''Institut océanographique Woods Hole dans le golfe du Mexique', 1988, false, NULL, 'Marque le début de l''utilisation opérationnelle du ROV Jason pour l''exploration scientifique des fonds marins. L''expédition a permis de tester les capacités du ROV et de collecter des données importantes sur l''environnement marin profond.', 'L''exploration du fond des océans : Du bathyscaphe Trieste à la découverte des sources hydrothermales', '', 'PENDING', '', '2026-03-04 07:23:47.332093+00', NULL, NULL, NULL, ''),
	(1136, 'Participation du ROV Jason à l''étude des sources hydrothermales de la dorsale de Juan de Fuca', 1996, false, NULL, 'Le ROV Jason a été déployé pour étudier l''activité volcanique et les communautés biologiques associées aux sources hydrothermales. Cette étude a permis de mieux comprendre les processus géochimiques et biologiques qui se produisent dans ces environnements.', 'L''exploration du fond des océans : Du bathyscaphe Trieste à la découverte des sources hydrothermales', '', 'PENDING', '', '2026-03-04 07:23:47.332093+00', NULL, NULL, NULL, ''),
	(1137, 'Utilisation du ROV Jason pour l''étude des cheminées hydrothermales ''Lost City'' dans l''océan Atlantique', 2003, false, NULL, 'Le ROV Jason a exploré les cheminées hydrothermales de Lost City, un site unique caractérisé par des fluides alcalins et des communautés microbiennes particulières. Cette exploration a révélé des informations importantes sur l''origine de la vie et les processus géochimiques dans les environnements hydrothermaux.', 'L''exploration du fond des océans : Du bathyscaphe Trieste à la découverte des sources hydrothermales', '', 'PENDING', '', '2026-03-04 07:23:47.332093+00', NULL, NULL, NULL, ''),
	(1138, 'Destruction du dirigeable L 59 lors d''une mission de ravitaillement en Afrique orientale', 1917, false, NULL, 'Le dirigeable allemand L 59, en mission pour ravitailler les troupes allemandes en Afrique orientale, est détruit en vol au-dessus du détroit d''Otrante. La cause exacte de la destruction reste incertaine.', 'La Conquête de l''Air : Des Ballons aux Réacteurs', '', 'PENDING', '', '2026-03-04 07:23:47.332093+00', NULL, NULL, NULL, ''),
	(1139, 'Sortie de Space Invaders au Japon', 1978, false, NULL, 'Taito lance Space Invaders, un jeu de tir fixe qui devient un phénomène culturel au Japon et marque le début de l''âge d''or des jeux d''arcade. Son succès commercial massif contribue à populariser les salles d''arcade.', 'L''Âge d''Or des Jeux Vidéo : Des bornes d''arcade à la réalité virtuelle (1972-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.332093+00', NULL, NULL, NULL, ''),
	(1140, 'Commercialisation de Ms. Pac-Man aux États-Unis', 1982, false, NULL, 'Midway Games sort Ms. Pac-Man, une version améliorée de Pac-Man avec un personnage féminin. Il devient l''un des jeux d''arcade les plus populaires et les plus vendus de tous les temps.', 'L''Âge d''Or des Jeux Vidéo : Des bornes d''arcade à la réalité virtuelle (1972-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.332093+00', NULL, NULL, NULL, ''),
	(1141, 'Sortie de Dragon''s Lair en Amérique du Nord', 1983, false, NULL, 'Advanced Microcomputer Systems (sous le nom Cinematronics) lance Dragon''s Lair, un jeu d''arcade utilisant la technologie laserdisc pour offrir des graphismes animés de haute qualité. Il marque une avancée visuelle significative dans les jeux d''arcade.', 'L''Âge d''Or des Jeux Vidéo : Des bornes d''arcade à la réalité virtuelle (1972-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.332093+00', NULL, NULL, NULL, ''),
	(1142, 'Lancement de la Nintendo Family Computer (Famicom) au Japon', 1983, false, NULL, 'Nintendo lance sa console Famicom au Japon, marquant le début de son ascension dans l''industrie du jeu vidéo. Elle deviendra plus tard la Nintendo Entertainment System (NES) à l''international.', 'L''Âge d''Or des Jeux Vidéo : Des bornes d''arcade à la réalité virtuelle (1972-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.332093+00', NULL, NULL, NULL, ''),
	(1143, 'Sortie de *Super Mario Bros.* sur Famicom au Japon', 1985, false, NULL, 'Nintendo lance *Super Mario Bros.*, un jeu de plateforme révolutionnaire qui définit les standards du genre. Il contribue grandement au succès de la Famicom.', 'L''Âge d''Or des Jeux Vidéo : Des bornes d''arcade à la réalité virtuelle (1972-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.332093+00', NULL, NULL, NULL, ''),
	(1144, 'Lancement de la Sega Mega Drive (Genesis) au Japon', 1988, false, NULL, 'Sega lance la Mega Drive (connue sous le nom de Genesis en Amérique du Nord) au Japon. Cette console 16-bit marque une nouvelle étape dans la guerre des consoles avec Nintendo.', 'L''Âge d''Or des Jeux Vidéo : Des bornes d''arcade à la réalité virtuelle (1972-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.332093+00', NULL, NULL, NULL, ''),
	(1145, 'Sortie de *Wolfenstein 3D*', 1992, false, NULL, 'Le jeu de tir à la première personne *Wolfenstein 3D*, développé par id Software, est commercialisé le 5 mai 1992. Il est considéré comme l''un des pionniers du genre et popularise l''utilisation de graphismes 3D polygonaux dans les jeux vidéo.', 'L''Âge d''Or des Jeux Vidéo : Des bornes d''arcade à la réalité virtuelle (1972-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.332093+00', NULL, NULL, NULL, ''),
	(1146, 'Ouverture du col du Khunjerab, facilitant le commerce direct entre la Chine et le nord de l''Inde', 75, false, NULL, 'L''ouverture du col du Khunjerab permet un passage plus direct et sûr pour les caravanes commerciales. Ce passage réduit les délais et les coûts liés au commerce entre l''Empire Kushan et la Chine.', 'L''Ascension et la Chute de la Route de la Soie : Du commerce antique à l''âge d''or mongol (Ier siècle - XIVe siècle)', '', 'PENDING', '', '2026-03-04 07:23:47.332093+00', NULL, NULL, NULL, ''),
	(1147, 'Construction du monastère de Taxila, un centre majeur d''apprentissage bouddhiste sur la Route de la Soie', 50, false, NULL, 'Le monastère de Taxila devient un point de convergence pour les érudits et les moines voyageant le long de la Route de la Soie. Il facilite l''échange d''idées et de connaissances entre l''Orient et l''Occident.', 'L''Ascension et la Chute de la Route de la Soie : Du commerce antique à l''âge d''or mongol (Ier siècle - XIVe siècle)', '', 'PENDING', '', '2026-03-04 07:23:47.332093+00', NULL, NULL, NULL, ''),
	(1148, 'Construction du Monastère de Nālandā sous le règne de Kumâragupta Ier', 415, false, NULL, 'Le monastère de Nālandā, qui deviendra un centre majeur d''apprentissage bouddhiste, est fondé en Inde sous le règne de Kumâragupta Ier de la dynastie Gupta. Il attire des érudits et des moines de toute l''Asie.', 'L''Ascension et la Chute de la Route de la Soie : Du commerce antique à l''âge d''or mongol (Ier siècle - XIVe siècle)', '', 'PENDING', '', '2026-03-04 07:23:47.332093+00', NULL, NULL, NULL, ''),
	(1149, 'Introduction du bouddhisme au royaume de Baekje (Corée)', 384, false, NULL, 'Le moine indien Marananta arrive au royaume de Baekje, l''un des trois royaumes de Corée, et introduit officiellement le bouddhisme. Cela marque le début de l''influence bouddhiste sur la culture coréenne.', 'L''Ascension et la Chute de la Route de la Soie : Du commerce antique à l''âge d''or mongol (Ier siècle - XIVe siècle)', '', 'PENDING', '', '2026-03-04 07:23:47.332093+00', NULL, NULL, NULL, ''),
	(1150, 'Sac de Chang''an par les rebelles tibétains', 763, false, NULL, 'Les forces tibétaines envahissent et pillent Chang''an, la capitale des Tang, forçant l''empereur à fuir. Cet événement souligne la vulnérabilité de la dynastie et l''instabilité politique de l''époque.', 'L''Ascension et la Chute de la Route de la Soie : Du commerce antique à l''âge d''or mongol (Ier siècle - XIVe siècle)', '', 'PENDING', '', '2026-03-04 07:23:47.332093+00', NULL, NULL, NULL, ''),
	(1152, 'Érection de la stèle de Bugut, témoignant de l''influence sogdienne dans l''Empire turc', 581, false, NULL, 'La stèle de Bugut, découverte en Mongolie, est un monument funéraire bilingue (sogdien et turc) érigé en l''honneur d''un chef turc. Elle atteste de l''importance des Sogdiens dans l''administration et la culture des Göktürks.', 'L''Ascension et la Chute de la Route de la Soie : Du commerce antique à l''âge d''or mongol (Ier siècle - XIVe siècle)', '', 'PENDING', '', '2026-03-04 07:23:47.332093+00', NULL, NULL, NULL, ''),
	(1153, 'Révolte sogdienne contre le califat abbasside en Transoxiane', 806, false, NULL, 'Une révolte éclate en Transoxiane, menée par des Sogdiens et d''autres populations locales, contre la domination du califat abbasside. Cette révolte reflète le mécontentement face à la pression fiscale et à l''islamisation forcée.', 'L''Ascension et la Chute de la Route de la Soie : Du commerce antique à l''âge d''or mongol (Ier siècle - XIVe siècle)', '', 'PENDING', '', '2026-03-04 07:23:47.332093+00', NULL, NULL, NULL, ''),
	(1154, 'Mention de la présence de marchands sogdiens à Guangzhou (Canton) par des sources chinoises', 790, false, NULL, 'Des documents chinois font état de la présence active de marchands sogdiens à Guangzhou, un important port commercial du sud de la Chine. Ils y échangeaient des produits de luxe et jouaient un rôle clé dans le commerce international.', 'L''Ascension et la Chute de la Route de la Soie : Du commerce antique à l''âge d''or mongol (Ier siècle - XIVe siècle)', '', 'PENDING', '', '2026-03-04 07:23:47.332093+00', NULL, NULL, NULL, ''),
	(1155, 'Adoption des Fundamental Orders of Connecticut (texte fondateur du Connecticut)', 1639, false, NULL, 'La colonie du Connecticut adopte les "Fundamental Orders of Connecticut", considérées comme l''une des premières constitutions écrites d''Amérique du Nord. Elles établissent un gouvernement représentatif et des droits pour les citoyens.', 'La Colonisation de l''Amérique du Nord : Conflits, Traités et Fondations (1534-1776)', '', 'PENDING', '', '2026-03-04 07:23:47.332093+00', NULL, NULL, NULL, ''),
	(1156, 'Promulgation du *Goseibai Shikimoku*', 1232, false, NULL, 'Le shogunat de Kamakura promulgue le *Goseibai Shikimoku*, également connu sous le nom de *Jōei Shikimoku*, un code de lois régissant la conduite des samouraïs et l''administration de la justice. Ce code marque une étape importante dans le développement du droit féodal au Japon.', 'L''Époque des Samouraïs : Ascensions, Guerres et Déclin du Bushido', '', 'PENDING', '', '2026-03-04 07:23:47.332093+00', NULL, NULL, NULL, ''),
	(1157, 'Destruction du clan Hōjō par Ashikaga Takauji', 1333, false, NULL, 'Ashikaga Takauji, initialement allié à l''empereur Go-Daigo, se retourne contre le clan Hōjō, qui contrôle le shogunat de Kamakura, et le détruit. Cet événement marque la fin du shogunat de Kamakura et le début de la période Muromachi.', 'L''Époque des Samouraïs : Ascensions, Guerres et Déclin du Bushido', '', 'PENDING', '', '2026-03-04 07:23:47.332093+00', NULL, NULL, NULL, ''),
	(1158, 'Ashikaga Takauji est nommé Sei-i Taishōgun', 1338, false, NULL, 'Ashikaga Takauji est officiellement nommé Sei-i Taishōgun, établissant le shogunat d''Ashikaga et consolidant son pouvoir. Cet événement marque le début de l''époque Muromachi.', 'L''Époque des Samouraïs : Ascensions, Guerres et Déclin du Bushido', '', 'PENDING', '', '2026-03-04 07:23:47.332093+00', NULL, NULL, NULL, ''),
	(1159, 'Construction du Pavillon d''argent (Ginkaku-ji) commence', 1482, false, NULL, 'Ashikaga Yoshimasa commence la construction du Pavillon d''argent (Ginkaku-ji) à Kyoto. Initialement prévu comme un lieu de retraite et un reflet du Pavillon d''or, il devient un symbole de l''esthétique et de la culture de l''époque Muromachi.', 'L''Époque des Samouraïs : Ascensions, Guerres et Déclin du Bushido', '', 'PENDING', '', '2026-03-04 07:23:47.332093+00', NULL, NULL, NULL, ''),
	(1161, 'Incendie de Meireki à Edo', 1657, false, NULL, 'Un grand incendie ravage Edo (Tokyo), détruisant une grande partie de la ville. La reconstruction qui suit contribue à la consolidation du pouvoir du shogunat et à l''affirmation de son autorité.', 'L''Époque des Samouraïs : Ascensions, Guerres et Déclin du Bushido', '', 'PENDING', '', '2026-03-04 07:23:47.332093+00', NULL, NULL, NULL, ''),
	(1162, 'Début du règne d''Acamapichtli, premier tlatoani de Tenochtitlan', 1376, false, NULL, 'Acamapichtli, d''ascendance tolteca, est choisi comme premier tlatoani (roi) de Tenochtitlan. Son règne marque le début de la dynastie royale aztèque et une période de consolidation du pouvoir.', 'L''essor et le déclin de l''Empire Aztèque : Conquête, Croyances et Chute de Tenochtitlan', '', 'PENDING', '', '2026-03-04 07:23:47.332093+00', NULL, NULL, NULL, ''),
	(1163, 'Alliance entre Tenochtitlan et Azcapotzalco', 1378, false, NULL, 'Tenochtitlan s''allie avec la puissante cité-état de Azcapotzalco, sous le règne de Tezozómoc. Cette alliance permet à Tenochtitlan de gagner en puissance et en influence dans la vallée de Mexico.', 'L''essor et le déclin de l''Empire Aztèque : Conquête, Croyances et Chute de Tenochtitlan', '', 'PENDING', '', '2026-03-04 07:23:47.332093+00', NULL, NULL, NULL, ''),
	(1164, 'Inondation majeure de Tenochtitlan', 1449, false, NULL, 'Une inondation dévastatrice frappe Tenochtitlan, causant des dommages importants à la ville et à son infrastructure. Cet événement conduit à des améliorations des systèmes de contrôle des eaux.', 'L''essor et le déclin de l''Empire Aztèque : Conquête, Croyances et Chute de Tenochtitlan', '', 'PENDING', '', '2026-03-04 07:23:47.332093+00', NULL, NULL, NULL, ''),
	(1165, 'Conquête de Tlatelolco par Tenochtitlan', 1473, false, NULL, 'Axayacatl mène les forces de Tenochtitlan à la conquête de Tlatelolco, une cité-état voisine et un important centre commercial. Cette conquête renforce le contrôle de Tenochtitlan sur la vallée de Mexico.', 'L''essor et le déclin de l''Empire Aztèque : Conquête, Croyances et Chute de Tenochtitlan', '', 'PENDING', '', '2026-03-04 07:23:47.332093+00', NULL, NULL, NULL, ''),
	(1166, 'Début du règne de Tizoc, septième tlatoani de Tenochtitlan', 1481, false, NULL, 'Tizoc succède à son frère Axayacatl. Son règne est marqué par des travaux de construction et d''expansion, bien que bref.', 'L''essor et le déclin de l''Empire Aztèque : Conquête, Croyances et Chute de Tenochtitlan', '', 'PENDING', '', '2026-03-04 07:23:47.332093+00', NULL, NULL, NULL, ''),
	(1167, 'Présentation du Xerox Alto au personnel de Xerox PARC', 1973, false, NULL, 'Xerox PARC présente le Xerox Alto, un ordinateur doté d''une interface utilisateur graphique (GUI) et d''une souris. Bien que non commercialisé, il influence fortement le développement des interfaces graphiques futures.', 'L''Ère de l''Informatique Personnelle : De l''Apple II à la Révolution Mobile (1977-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.332093+00', NULL, NULL, NULL, ''),
	(1168, 'Publication de ''De Americaensche Zee-Roovers'' relatant les exploits de Morgan', 1678, false, NULL, 'Alexandre Exquemelin publie ''De Americaensche Zee-Roovers'' en 1678, un récit détaillé des aventures des flibustiers, incluant les exploits d''Henry Morgan. Ce livre contribue à la légende de Morgan.', 'L''Âge d''Or de la Piraterie Caribéenne : De l''essor des flibustiers au déclin des pirates (1625-1730)', '', 'PENDING', '', '2026-03-04 07:23:47.332093+00', NULL, NULL, NULL, ''),
	(1169, 'Début du règne de Frédéric-Guillaume Ier en Prusse', 1713, false, NULL, 'Frédéric-Guillaume Ier accède au trône de Prusse le 25 février. Son règne est marqué par la militarisation de l''État et la centralisation du pouvoir.', 'L''Âge d''Or de la Piraterie Caribéenne : De l''essor des flibustiers au déclin des pirates (1625-1730)', '', 'PENDING', '', '2026-03-04 07:23:47.332093+00', NULL, NULL, NULL, ''),
	(1170, 'Fondation de la Bibliothèque nationale d''Espagne (Biblioteca Nacional de España)', 1712, false, NULL, 'La Bibliothèque royale (future Bibliothèque nationale d''Espagne) est fondée par Philippe V. Elle a pour but de rassembler tous les écrits publiés en Espagne.', 'L''Âge d''Or de la Piraterie Caribéenne : De l''essor des flibustiers au déclin des pirates (1625-1730)', '', 'PENDING', '', '2026-03-04 07:23:47.332093+00', NULL, NULL, NULL, ''),
	(1171, 'Publication du "A General History of the Pirates" de Charles Johnson', 1724, false, NULL, 'Ce recueil de biographies romancées de pirates contribue à la légende de l''Âge d''Or de la Piraterie. Il popularise les figures de Barbe Noire, Calico Jack et Anne Bonny.', 'L''Âge d''Or de la Piraterie Caribéenne : De l''essor des flibustiers au déclin des pirates (1625-1730)', '', 'PENDING', '', '2026-03-04 07:23:47.332093+00', NULL, NULL, NULL, ''),
	(1172, 'Sortie de l''album « Pet Sounds » des Beach Boys', 1966, false, NULL, 'Sortie de l''album « Pet Sounds » des Beach Boys, considéré comme l''un des albums les plus influents de l''histoire du rock. Il marque une évolution vers des compositions plus complexes et une production sophistiquée.', 'L''Histoire du Rock''n''Roll : De la naissance au Grunge (1954-1994)', '', 'PENDING', '', '2026-03-04 07:23:47.332093+00', NULL, NULL, NULL, ''),
	(1173, 'Sortie de l''album ''The Yes Album'' de Yes', 1971, false, NULL, 'L''album est sorti le 19 février 1971. Il marque un tournant dans le style du groupe, avec des compositions plus complexes et virtuoses.', 'L''Histoire du Rock''n''Roll : De la naissance au Grunge (1954-1994)', '', 'PENDING', '', '2026-03-04 07:23:47.332093+00', NULL, NULL, NULL, ''),
	(1174, 'Sortie de l''album "Zen Arcade" de Hüsker Dü', 1984, false, NULL, 'L''album double "Zen Arcade" de Hüsker Dü sort et marque une étape importante dans le développement du rock alternatif, influençant de nombreux groupes à venir. Il mélange punk hardcore et mélodies pop.', 'L''Histoire du Rock''n''Roll : De la naissance au Grunge (1954-1994)', '', 'PENDING', '', '2026-03-04 07:23:47.332093+00', NULL, NULL, NULL, ''),
	(1175, 'Sortie de l''album "Ten" de Pearl Jam', 1991, false, NULL, 'L''album "Ten" de Pearl Jam est lancé et devient un succès commercial majeur, contribuant à populariser le son grunge auprès d''un public plus large. Il est certifié 13 fois disque de platine aux États-Unis.', 'L''Histoire du Rock''n''Roll : De la naissance au Grunge (1954-1994)', '', 'PENDING', '', '2026-03-04 07:23:47.332093+00', NULL, NULL, NULL, ''),
	(1176, 'Début du règne de Sinchi Roca, deuxième Sapa Inca de Cuzco', 1230, false, NULL, 'Sinchi Roca succède à Manco Capac et continue le développement initial de Cuzco. Son règne est marqué par l''organisation sociale et militaire de la jeune civilisation Inca.', 'L''essor et le déclin de l''Empire Inca : Des origines mythiques à la conquête espagnole (XIIe siècle - 1572)', '', 'PENDING', '', '2026-03-04 07:23:47.332093+00', NULL, NULL, NULL, ''),
	(1177, 'Début du règne de Lloque Yupanqui, troisième Sapa Inca de Cuzco', 1260, false, NULL, 'Lloque Yupanqui consolide le pouvoir Inca à Cuzco et entreprend des expéditions militaires pour étendre l''influence de la ville sur les territoires environnants.', 'L''essor et le déclin de l''Empire Inca : Des origines mythiques à la conquête espagnole (XIIe siècle - 1572)', '', 'PENDING', '', '2026-03-04 07:23:47.343937+00', NULL, NULL, NULL, ''),
	(1178, 'Début du règne de Mayta Capac, quatrième Sapa Inca de Cuzco', 1290, false, NULL, 'Mayta Capac est connu pour sa force militaire et son ambition. Il mène des campagnes pour soumettre des tribus rivales et renforcer la position de Cuzco dans la région.', 'L''essor et le déclin de l''Empire Inca : Des origines mythiques à la conquête espagnole (XIIe siècle - 1572)', '', 'PENDING', '', '2026-03-04 07:23:47.343937+00', NULL, NULL, NULL, ''),
	(1179, 'Début du règne de Capac Yupanqui, cinquième Sapa Inca de Cuzco', 1320, false, NULL, 'Capac Yupanqui continue l''expansion militaire et politique de Cuzco. Son règne est marqué par des alliances et des conflits avec les peuples voisins, contribuant à l''établissement de l''influence Inca.', 'L''essor et le déclin de l''Empire Inca : Des origines mythiques à la conquête espagnole (XIIe siècle - 1572)', '', 'PENDING', '', '2026-03-04 07:23:47.343937+00', NULL, NULL, NULL, ''),
	(1180, 'Couronnement de Pachacútec Inca Yupanqui comme Sapa Inca', 1438, false, NULL, 'Pachacútec est couronné Sapa Inca après sa victoire à Yawarpampa, consolidant son pouvoir et lançant une série de réformes administratives, militaires et urbanistiques à Cuzco. Son règne marque une période de transformation et d''expansion sans précédent pour l''empire Inca.', 'L''essor et le déclin de l''Empire Inca : Des origines mythiques à la conquête espagnole (XIIe siècle - 1572)', '', 'PENDING', '', '2026-03-04 07:23:47.343937+00', NULL, NULL, NULL, ''),
	(1181, 'Campagne de consolidation du Chinchaysuyu lancée par Tupac Inca Yupanqui', 1470, false, NULL, 'Tupac Inca Yupanqui, fils de Pachacútec, lance une campagne militaire pour consolider le contrôle inca sur la région du Chinchaysuyu, étendant l''influence impériale vers le nord. Cette campagne renforce le pouvoir inca sur les territoires conquis et assure le contrôle des routes commerciales.', 'L''essor et le déclin de l''Empire Inca : Des origines mythiques à la conquête espagnole (XIIe siècle - 1572)', '', 'PENDING', '', '2026-03-04 07:23:47.343937+00', NULL, NULL, NULL, ''),
	(1182, 'Accession de Huayna Capac au pouvoir à la mort de son père Tupac Yupanqui', 1493, false, NULL, 'Huayna Capac devient le nouvel empereur Inca, marquant le début d''une période d''expansion et de consolidation de l''empire. Son règne est caractérisé par une administration complexe et des projets de construction ambitieux.', 'L''essor et le déclin de l''Empire Inca : Des origines mythiques à la conquête espagnole (XIIe siècle - 1572)', '', 'PENDING', '', '2026-03-04 07:23:47.343937+00', NULL, NULL, NULL, ''),
	(1183, 'Exécution de Túpac Amaru I à Cuzco', 1572, false, NULL, 'Túpac Amaru I, le dernier empereur Inca de Vilcabamba, est capturé et exécuté publiquement à Cuzco sur ordre du vice-roi Francisco de Toledo. Cet événement marque la fin de la résistance inca organisée.', 'L''essor et le déclin de l''Empire Inca : Des origines mythiques à la conquête espagnole (XIIe siècle - 1572)', '', 'PENDING', '', '2026-03-04 07:23:47.343937+00', NULL, NULL, NULL, ''),
	(1184, 'Première diffusion de la publicité télévisée aux États-Unis par Bulova', 1941, false, NULL, 'La marque horlogère Bulova diffuse la première publicité télévisée aux États-Unis, marquant le début de la publicité commerciale à la télévision. La publicité est diffusée avant un match de baseball.', 'L''Histoire de la Télévision : De la création du tube cathodique à l''ère du streaming', '', 'PENDING', '', '2026-03-04 07:23:47.343937+00', NULL, NULL, NULL, ''),
	(1185, 'Première diffusion de l''émission "Les Enfants du Rock"', 1981, false, NULL, 'Lancement de l''émission "Les Enfants du Rock" sur Antenne 2. L''émission contribue à populariser la culture rock et les nouvelles tendances musicales auprès d''un large public.', 'L''Histoire de la Télévision : De la création du tube cathodique à l''ère du streaming', '', 'PENDING', '', '2026-03-04 07:23:47.343937+00', NULL, NULL, NULL, ''),
	(1186, 'Lancement du service de streaming audio ''RealAudio'' par Progressive Networks', 1995, false, NULL, 'RealAudio a été l''un des premiers services à permettre la diffusion audio en continu sur Internet. Il a ouvert la voie au streaming musical et à la radio en ligne.', 'L''Histoire de la Télévision : De la création du tube cathodique à l''ère du streaming', '', 'PENDING', '', '2026-03-04 07:23:47.343937+00', NULL, NULL, NULL, ''),
	(1187, 'Fondation de l''Interstate Commerce Commission (ICC) aux États-Unis', 1887, false, NULL, 'L''ICC a été créée pour réglementer les chemins de fer et assurer des tarifs équitables. Elle a été la première agence de réglementation indépendante du gouvernement fédéral américain.', 'L''Épopée du Far West Américain : De la Ruée vers l''Or à la Fermeture de la Frontière', '', 'PENDING', '', '2026-03-04 07:23:47.343937+00', NULL, NULL, NULL, ''),
	(1188, 'Kubilai Khan transfère sa capitale à Khanbaliq (Pékin)', 1264, false, NULL, 'En 1264, Kubilai Khan transfère sa capitale de Karakorum à Khanbaliq (l''actuelle Pékin). Ce transfert symbolise l''orientation chinoise de son khanat.', 'L''Ascension et la Chute de l''Empire Mongol : De Gengis Khan à la Dynastie Yuan (1206-1368)', '', 'PENDING', '', '2026-03-04 07:23:47.343937+00', NULL, NULL, NULL, ''),
	(1189, 'Destruction de la flotte Yuan par un typhon lors de la seconde invasion du Japon (Kamakaze)', 1281, false, NULL, 'Une tempête massive détruit une grande partie de la flotte Yuan lors de la seconde tentative d''invasion du Japon, mettant fin aux ambitions expansionnistes de Kubilai Khan dans cette direction. Cet événement est connu sous le nom de ''Kamikaze'', ou ''vent divin''.', 'L''Ascension et la Chute de l''Empire Mongol : De Gengis Khan à la Dynastie Yuan (1206-1368)', '', 'PENDING', '', '2026-03-04 07:23:47.343937+00', NULL, NULL, NULL, ''),
	(1190, 'Proclamation de Han Lin''er comme empereur de Song', 1355, false, NULL, 'Liu Futong proclame Han Lin''er, fils de Han Shantong (mort en 1351), empereur de la dynastie Song, cherchant à restaurer la dynastie Song et à légitimer la rébellion contre les Yuan.', 'L''Ascension et la Chute de l''Empire Mongol : De Gengis Khan à la Dynastie Yuan (1206-1368)', '', 'PENDING', '', '2026-03-04 07:23:47.343937+00', NULL, NULL, NULL, ''),
	(1191, 'Bataille du lac Poyang', 1363, false, NULL, 'Zhu Yuanzhang remporte une victoire décisive contre Chen Youliang à la bataille du lac Poyang, éliminant un rival majeur dans la lutte pour le pouvoir et consolidant sa position.', 'L''Ascension et la Chute de l''Empire Mongol : De Gengis Khan à la Dynastie Yuan (1206-1368)', '', 'PENDING', '', '2026-03-04 07:23:47.343937+00', NULL, NULL, NULL, ''),
	(1192, 'Première démonstration d''un circuit intégré fonctionnel (Robert Noyce, Fairchild)', 1959, false, NULL, 'Robert Noyce de Fairchild Semiconductor démontre un circuit intégré fonctionnel en 1959, peu de temps après le dépôt de brevet de Kilby, contribuant à la course à la miniaturisation.', 'L''histoire du développement informatique : De l''ENIAC à l''Internet des Objets (1946-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.343937+00', NULL, NULL, NULL, ''),
	(1193, 'Publication de l''étude sur la conception logique d''un ordinateur électronique (Burks, Goldstine, von Neumann)', 1946, false, NULL, 'Ce rapport décrit l''architecture de von Neumann, un modèle pour les ordinateurs à programme enregistré. Il influence la conception des ordinateurs pendant des décennies.', 'L''histoire du développement informatique : De l''ENIAC à l''Internet des Objets (1946-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.343937+00', NULL, NULL, NULL, ''),
	(1194, 'Création du système de noms de domaine (DNS)', 1983, false, NULL, 'Introduction d''une méthode hiérarchique et distribuée pour traduire les noms de domaine en adresses IP. Cela simplifie l''accès aux ressources en ligne.', 'L''histoire du développement informatique : De l''ENIAC à l''Internet des Objets (1946-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.343937+00', NULL, NULL, NULL, ''),
	(1195, 'Lancement du premier téléphone mobile avec navigateur WAP (Nokia 7110)', 1999, false, NULL, 'Nokia lance le 7110, le premier téléphone mobile doté d''un navigateur WAP (Wireless Application Protocol). Il permet d''accéder à des versions allégées de sites web sur mobile.', 'L''histoire du développement informatique : De l''ENIAC à l''Internet des Objets (1946-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.343937+00', NULL, NULL, NULL, ''),
	(1197, 'Première mention écrite de la soie romaine par Pline l''Ancien', 70, false, NULL, 'Pline l''Ancien décrit la soie provenant de Seres (Chine) dans son ''Histoire naturelle'', témoignant de la présence de la soie romaine et de son importance croissante dans le commerce entre l''Orient et l''Occident. Il déplore son coût élevé.', 'L''Histoire de la Route de la Soie : De l''Antiquité à son Déclin', '', 'PENDING', '', '2026-03-04 07:23:47.343937+00', NULL, NULL, NULL, ''),
	(1253, 'Publication du ''Shōbōgenzō'' par Dōgen, texte fondateur de l''école Sōtō du bouddhisme Zen', 1231, false, NULL, 'Dōgen, fondateur de l''école Sōtō, commence à écrire le ''Shōbōgenzō'', une œuvre philosophique majeure qui expose les principes fondamentaux du Zen Sōtō.', 'L''expansion du bouddhisme : De la vie de Siddhartha Gautama à sa diffusion mondiale', '', 'PENDING', '', '2026-03-04 07:23:47.356346+00', NULL, NULL, NULL, ''),
	(1198, 'Ban Chao, général Han, rétablit le contrôle chinois sur Kashgar', 91, false, NULL, 'Le général Ban Chao de la dynastie Han rétablit le contrôle chinois sur Kashgar, une ville clé de la Route de la Soie, après une période de troubles. Cette action renforce la présence chinoise en Asie centrale et sécurise les routes commerciales.', 'L''Histoire de la Route de la Soie : De l''Antiquité à son Déclin', '', 'PENDING', '', '2026-03-04 07:23:47.343937+00', NULL, NULL, NULL, ''),
	(1199, 'Traité de Changyuan (29 janvier 1005)', 1005, false, NULL, 'Signature du traité de Changyuan entre la dynastie Song et la dynastie Liao, stabilisant la frontière nord de la Chine et permettant une reprise du commerce via la Route de la Soie, bien que sous contrôle Liao au nord.', 'L''Histoire de la Route de la Soie : De l''Antiquité à son Déclin', '', 'PENDING', '', '2026-03-04 07:23:47.343937+00', NULL, NULL, NULL, ''),
	(1200, 'Prise de Samarcande par les Qarakhanides (1041)', 1041, false, NULL, 'La prise de Samarcande par les Qarakhanides marque un changement de pouvoir en Asie centrale, affectant le contrôle et la sécurité des routes commerciales de la Route de la Soie.', 'L''Histoire de la Route de la Soie : De l''Antiquité à son Déclin', '', 'PENDING', '', '2026-03-04 07:23:47.343937+00', NULL, NULL, NULL, ''),
	(1201, 'Début du règne de Mehmet II, le Conquérant', 1444, false, NULL, 'Le début du règne de Mehmet II, qui reprendra en 1451, marque une période d''expansion ottomane agressive. Sa politique aura un impact direct sur le contrôle des routes commerciales reliant l''Europe et l''Asie.', 'L''Histoire de la Route de la Soie : De l''Antiquité à son Déclin', '', 'PENDING', '', '2026-03-04 07:23:47.343937+00', NULL, NULL, NULL, ''),
	(1202, 'Première démonstration publique du scaphandre autonome Rouquayrol-Denayrouze à Espalion', 1865, false, NULL, 'Auguste Denayrouze présente le scaphandre de son invention, fruit de sa collaboration avec Benoît Rouquayrol. L''appareil marque une avancée significative dans la plongée autonome.', 'L''histoire de l''exploration du fond des océans : Des scaphandriers aux bathyscaphes (1860-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.343937+00', NULL, NULL, NULL, ''),
	(1203, 'Invention du détendeur à la demande par Yves Le Prieur', 1926, false, NULL, 'Yves Le Prieur met au point un détendeur permettant de réguler l''arrivée d''air comprimé dans le masque du plongeur. Cette invention améliore considérablement la sécurité et le confort sous l''eau.', 'L''histoire de l''exploration du fond des océans : Des scaphandriers aux bathyscaphes (1860-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.343937+00', NULL, NULL, NULL, ''),
	(1204, 'Présentation du bathysphère de Beebe et Barton à la New York Zoological Society', 1930, false, NULL, 'Le bathysphère, conçu par Otis Barton, est présenté au public pour la première fois. Il permet d''observer directement les profondeurs marines.', 'L''histoire de l''exploration du fond des océans : Des scaphandriers aux bathyscaphes (1860-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.343937+00', NULL, NULL, NULL, ''),
	(1205, 'Lancement du sous-marin de recherche Alvin', 1964, false, NULL, 'Le sous-marin Alvin, conçu pour la recherche océanographique en eaux profondes, est lancé par la Woods Hole Oceanographic Institution. Il deviendra un outil essentiel pour l''exploration des fonds marins.', 'L''histoire de l''exploration du fond des océans : Des scaphandriers aux bathyscaphes (1860-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.343937+00', NULL, NULL, NULL, ''),
	(1206, 'Lancement du projet NEPTUNE (North East Pacific Time-series Underwater Networked Experiments)', 2009, false, NULL, 'Début du déploiement du réseau NEPTUNE Canada, un observatoire sous-marin câblé fournissant une surveillance en temps réel et à long terme des fonds marins au large de la côte ouest du Canada.', 'L''histoire de l''exploration du fond des océans : Des scaphandriers aux bathyscaphes (1860-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.343937+00', NULL, NULL, NULL, ''),
	(1207, 'Première observation directe d''un poisson vivant à plus de 8 000 mètres de profondeur (poisson-limace)', 2014, false, NULL, 'Une équipe de scientifiques filme un poisson-limace à une profondeur de 8 145 mètres dans la fosse des Mariannes. C''est la première observation directe d''un poisson vivant à une telle profondeur.', 'L''histoire de l''exploration du fond des océans : Des scaphandriers aux bathyscaphes (1860-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.343937+00', NULL, NULL, NULL, ''),
	(1219, 'Construction du temple d''Aton à Karnak ordonnée par Akhenaton', 1352, false, NULL, 'Akhenaton ordonne la construction d''un temple dédié au dieu Aton à Karnak, marquant une étape importante dans sa réforme religieuse. Ce temple sera plus tard démantelé.', 'Les Dynasties Égyptiennes : Des Pharaons Prédynastiques à Cléopâtre', '', 'PENDING', '', '2026-03-04 07:23:47.343937+00', NULL, NULL, NULL, ''),
	(1220, 'Translation de la capitale à Akhetaton', 1346, false, NULL, 'Akhenaton transfère la capitale de Thèbes à Akhetaton (aujourd''hui Amarna), symbolisant sa rupture avec le clergé d''Amon et l''établissement de son nouveau culte monothéiste.', 'Les Dynasties Égyptiennes : Des Pharaons Prédynastiques à Cléopâtre', '', 'PENDING', '', '2026-03-04 07:23:47.343937+00', NULL, NULL, NULL, ''),
	(1221, 'Début du règne de Toutânkhaton', 1332, false, NULL, 'Toutânkhaton accède au trône après la mort d''Akhenaton. Il restaure rapidement le culte des anciens dieux et change son nom en Toutânkhamon.', 'Les Dynasties Égyptiennes : Des Pharaons Prédynastiques à Cléopâtre', '', 'PENDING', '', '2026-03-04 07:23:47.343937+00', NULL, NULL, NULL, ''),
	(1222, 'Début du règne de Psammétique Ier en Égypte', 664, false, NULL, 'Psammétique Ier fonde la XXVIe dynastie et marque le début de la Basse Époque égyptienne. Il met fin à la domination assyrienne et restaure l''indépendance de l''Égypte.', 'Les Dynasties Égyptiennes : Des Pharaons Prédynastiques à Cléopâtre', '', 'PENDING', '', '2026-03-04 07:23:47.343937+00', NULL, NULL, NULL, ''),
	(1223, 'Alexandre le Grand est couronné pharaon à Memphis', 332, false, NULL, 'Après avoir conquis l''Égypte, Alexandre le Grand est couronné pharaon à Memphis, intégrant l''Égypte à son empire. Il fonde Alexandrie.', 'Les Dynasties Égyptiennes : Des Pharaons Prédynastiques à Cléopâtre', '', 'PENDING', '', '2026-03-04 07:23:47.343937+00', NULL, NULL, NULL, ''),
	(1224, 'Début du règne de Ptolémée Ier Sôter en Égypte', 305, false, NULL, 'Ptolémée Ier Sôter, un des généraux d''Alexandre le Grand, se proclame roi d''Égypte. Il fonde la dynastie ptolémaïque qui gouvernera l''Égypte pendant près de trois siècles.', 'Les Dynasties Égyptiennes : Des Pharaons Prédynastiques à Cléopâtre', '', 'PENDING', '', '2026-03-04 07:23:47.343937+00', NULL, NULL, NULL, ''),
	(1225, 'Suicide de Cléopâtre VII et fin de la dynastie ptolémaïque', 30, false, NULL, 'Après la défaite d''Antoine et Cléopâtre face à Octave (futur Auguste), Cléopâtre se suicide. L''Égypte devient une province romaine, marquant la fin de l''Égypte pharaonique.', 'Les Dynasties Égyptiennes : Des Pharaons Prédynastiques à Cléopâtre', '', 'PENDING', '', '2026-03-04 07:23:47.343937+00', NULL, NULL, NULL, ''),
	(1226, 'Fujiwara no Tokihira devient Sadaijin', 899, false, NULL, 'Fujiwara no Tokihira accède au poste de Sadaijin (Ministre de Gauche), consolidant davantage le pouvoir du clan Fujiwara au sein du gouvernement impérial. Cette nomination marque une étape importante dans la domination politique du clan.', 'L''essor du Japon féodal : Du clan Fujiwara à l''établissement du shogunat Tokugawa (794-1603)', '', 'PENDING', '', '2026-03-04 07:23:47.343937+00', NULL, NULL, NULL, ''),
	(1227, 'Fujiwara no Michinaga devient régent (Sesshō)', 995, false, NULL, 'Fujiwara no Michinaga devient Sesshō (régent) pour l''empereur Ichijō, atteignant le sommet de la puissance Fujiwara. Son règne est considéré comme l''apogée de l''influence du clan.', 'L''essor du Japon féodal : Du clan Fujiwara à l''établissement du shogunat Tokugawa (794-1603)', '', 'PENDING', '', '2026-03-04 07:23:47.343937+00', NULL, NULL, NULL, ''),
	(1228, 'Début du règne de l''empereur Go-Reizei sans ascendance Fujiwara', 1045, false, NULL, 'L''empereur Go-Reizei monte sur le trône sans être né d''une mère issue du clan Fujiwara, ce qui représente un défi à la tradition et un affaiblissement potentiel de l''influence du clan. Cet événement marque un tournant dans la domination des Fujiwara.', 'L''essor du Japon féodal : Du clan Fujiwara à l''établissement du shogunat Tokugawa (794-1603)', '', 'PENDING', '', '2026-03-04 07:23:47.343937+00', NULL, NULL, NULL, ''),
	(1229, 'Retraite de Fujiwara no Yorimichi à Byōdō-in', 1068, false, NULL, 'Fujiwara no Yorimichi se retire à Byōdō-in, un temple qu''il a transformé en un symbole de la splendeur et de la piété du clan Fujiwara. Cet événement coïncide avec la fin de son rôle de Kampaku et le déclin de l''influence directe des Fujiwara.', 'L''essor du Japon féodal : Du clan Fujiwara à l''établissement du shogunat Tokugawa (794-1603)', '', 'PENDING', '', '2026-03-04 07:23:47.343937+00', NULL, NULL, NULL, ''),
	(1230, 'Publication du ''Shin Sarugaku Ki'' de Fujiwara Akihira, décrivant la vie des courtisans et des guerriers', 1076, false, NULL, 'Ce texte est une source précieuse sur les coutumes et les classes sociales de l''époque, offrant un aperçu des interactions entre la noblesse et les premiers samouraïs.', 'L''essor du Japon féodal : Du clan Fujiwara à l''établissement du shogunat Tokugawa (794-1603)', '', 'PENDING', '', '2026-03-04 07:23:47.343937+00', NULL, NULL, NULL, ''),
	(1231, 'Taira no Kiyomori devient le premier guerrier à être nommé Daijo-daijin (Premier Ministre)', 1167, false, NULL, 'Cette nomination symbolise l''ascension du clan Taira et l''influence croissante des guerriers dans la politique impériale, marquant un tournant dans l''équilibre du pouvoir.', 'L''essor du Japon féodal : Du clan Fujiwara à l''établissement du shogunat Tokugawa (794-1603)', '', 'PENDING', '', '2026-03-04 07:23:47.343937+00', NULL, NULL, NULL, ''),
	(1232, 'Minamoto no Yoritomo reçoit le titre de Sei-i Taishōgun', 1192, false, NULL, 'L''empereur Go-Toba nomme Minamoto no Yoritomo Sei-i Taishōgun. Cet événement marque officiellement le début du shogunat de Kamakura.', 'L''essor du Japon féodal : Du clan Fujiwara à l''établissement du shogunat Tokugawa (794-1603)', '', 'PENDING', '', '2026-03-04 07:23:47.343937+00', NULL, NULL, NULL, ''),
	(1233, 'Début officiel du commerce de tribut avec la dynastie Ming', 1404, false, NULL, 'Le shogun Yoshimitsu reprend officiellement le commerce de tribut avec la Chine de la dynastie Ming. Ce commerce apporte prospérité et influence culturelle au Japon.', 'L''essor du Japon féodal : Du clan Fujiwara à l''établissement du shogunat Tokugawa (794-1603)', '', 'PENDING', '', '2026-03-04 07:23:47.343937+00', NULL, NULL, NULL, ''),
	(1234, 'Construction du Kinkaku-ji (Pavillon d''or) achevée', 1397, false, NULL, 'Ashikaga Yoshimitsu achève la construction du Kinkaku-ji (Pavillon d''or) à Kitayama, Kyoto. Il sert initialement de villa de retraite avant d''être transformé en temple zen après sa mort.', 'L''essor du Japon féodal : Du clan Fujiwara à l''établissement du shogunat Tokugawa (794-1603)', '', 'PENDING', '', '2026-03-04 07:23:47.343937+00', NULL, NULL, NULL, ''),
	(1235, 'Démonstration du bateau à vapeur de William Symington sur le lac Dalswinton', 1788, false, NULL, 'William Symington effectue une démonstration réussie de son bateau à vapeur sur le lac Dalswinton en Écosse. C''est l''une des premières démonstrations d''un bateau propulsé par une machine à vapeur.', 'La Révolution Industrielle : De la Machine à Vapeur à l''Électrification Globale (1760-1914)', '', 'PENDING', '', '2026-03-04 07:23:47.343937+00', NULL, NULL, NULL, ''),
	(1236, 'Fondation de la Société des Moteurs Daimler (DMG) à Cannstatt', 1890, false, NULL, 'Gottlieb Daimler fonde la Daimler-Motoren-Gesellschaft (DMG) à Cannstatt, en Allemagne. Cette société jouera un rôle majeur dans le développement et la production d''automobiles.', 'La Révolution Industrielle : De la Machine à Vapeur à l''Électrification Globale (1760-1914)', '', 'PENDING', '', '2026-03-04 07:23:47.343937+00', NULL, NULL, NULL, ''),
	(1237, 'Première démonstration publique de la lampe à arc électrique par Humphry Davy à la Royal Institution de Londres', 1808, false, NULL, 'Humphry Davy présente une lampe à arc électrique devant la Royal Institution de Londres. Cette démonstration marque une étape importante dans le développement de l''éclairage électrique.', 'La Révolution Industrielle : De la Machine à Vapeur à l''Électrification Globale (1760-1914)', '', 'PENDING', '', '2026-03-04 07:23:47.343937+00', NULL, NULL, NULL, ''),
	(1238, 'Première découverte documentée d''or en Caroline du Nord par Conrad Reed sur Little Meadow Creek', 1799, false, NULL, 'Conrad Reed, 12 ans, trouve une pépite d''or de 17 livres sur la propriété de son père, John Reed, marquant le début de la ruée vers l''or en Caroline du Nord. La découverte initiale est restée non identifiée pendant plusieurs années.', 'La ruée vers l''or en Amérique du Nord : De la découverte initiale aux grandes ruées (1799-1899)', '', 'PENDING', '', '2026-03-04 07:23:47.343937+00', NULL, NULL, NULL, ''),
	(1239, 'Découverte d''or à Dukes Creek, Géorgie', 1828, false, NULL, 'La découverte d''or à Dukes Creek marque le début de la ruée vers l''or en Géorgie. Cet événement attire rapidement des milliers de chercheurs d''or dans la région.', 'La ruée vers l''or en Amérique du Nord : De la découverte initiale aux grandes ruées (1799-1899)', '', 'PENDING', '', '2026-03-04 07:23:47.356346+00', NULL, NULL, NULL, ''),
	(1240, 'Découverte d''or à Bonanza Creek par Skookum Jim, Tagish Charlie et George Carmack', 1896, false, NULL, 'Cette découverte marque le début officiel de la ruée vers l''or du Klondike. Elle attire rapidement des milliers de prospecteurs dans la région.', 'La ruée vers l''or en Amérique du Nord : De la découverte initiale aux grandes ruées (1799-1899)', '', 'PENDING', '', '2026-03-04 07:23:47.356346+00', NULL, NULL, NULL, ''),
	(1241, 'Ouverture du saloon "The Palace Grand Theatre" (Dawson City)', 1899, false, NULL, 'Ce saloon devient un lieu de divertissement majeur pour les mineurs et les habitants de Dawson City. Il symbolise l''essor de la ville.', 'La ruée vers l''or en Amérique du Nord : De la découverte initiale aux grandes ruées (1799-1899)', '', 'PENDING', '', '2026-03-04 07:23:47.356346+00', NULL, NULL, NULL, ''),
	(1248, 'Rédaction du commentaire de Buddhaghosa sur le Vinaya Pitaka (Samantapasadika)', 430, false, NULL, 'Buddhaghosa, un érudit bouddhiste, achève son commentaire majeur sur le Vinaya Pitaka. Ce texte devient une référence essentielle pour l''étude de la discipline monastique dans le bouddhisme Theravada.', 'L''expansion du bouddhisme : De la vie de Siddhartha Gautama à sa diffusion mondiale', '', 'PENDING', '', '2026-03-04 07:23:47.356346+00', NULL, NULL, NULL, ''),
	(1249, 'Sixième concile bouddhiste (Chattha Sangayana) à Rangoon', 1954, false, NULL, 'Ce concile a réuni des moines de divers pays Theravada pour réviser et éditer le Tipitaka Pali. Il a marqué une tentative de préserver et de diffuser le canon Pali dans sa forme la plus pure.', 'L''expansion du bouddhisme : De la vie de Siddhartha Gautama à sa diffusion mondiale', '', 'PENDING', '', '2026-03-04 07:23:47.356346+00', NULL, NULL, NULL, ''),
	(1251, 'Traduction du Sutra des Guirlandes (Buddhavatamsaka Sutra) en chinois par Buddhabhadra à Nankin', 420, false, NULL, 'Buddhabhadra, un moine bouddhiste indien, achève la traduction du Buddhavatamsaka Sutra, un texte majeur du bouddhisme Mahayana, en chinois à Nankin. Cette traduction a eu une influence profonde sur le développement du bouddhisme chinois.', 'L''expansion du bouddhisme : De la vie de Siddhartha Gautama à sa diffusion mondiale', '', 'PENDING', '', '2026-03-04 07:23:47.356346+00', NULL, NULL, NULL, ''),
	(1252, 'Construction du Kennin-ji à Kyoto, premier temple Zen officiellement reconnu au Japon', 1202, false, NULL, 'Eisai fonde le Kennin-ji à Kyoto, avec le soutien du shogun Minamoto no Yoriie. Il s''agit du premier temple Zen officiellement reconnu par le gouvernement japonais.', 'L''expansion du bouddhisme : De la vie de Siddhartha Gautama à sa diffusion mondiale', '', 'PENDING', '', '2026-03-04 07:23:47.356346+00', NULL, NULL, NULL, ''),
	(1254, 'Traversée des Blue Mountains par Blaxland, Lawson et Wentworth', 1813, false, NULL, 'Gregory Blaxland, William Lawson et William Charles Wentworth réussissent la première traversée documentée des Blue Mountains à l''ouest de Sydney. Cette expédition ouvre la voie à l''expansion coloniale vers l''intérieur des terres.', 'La Colonisation de l''Australie : De la Première Flotte à la Fédération (1788-1901)', '', 'PENDING', '', '2026-03-04 07:23:47.356346+00', NULL, NULL, NULL, ''),
	(1255, 'Fondation de la colonie de Swan River (Perth)', 1829, false, NULL, 'Le capitaine James Stirling fonde officiellement la colonie de Swan River, qui deviendra plus tard Perth, en Australie-Occidentale. Cet événement marque le début de la colonisation britannique dans cette région.', 'La Colonisation de l''Australie : De la Première Flotte à la Fédération (1788-1901)', '', 'PENDING', '', '2026-03-04 07:23:47.356346+00', NULL, NULL, NULL, ''),
	(1256, 'Adoption du principe de gouvernement responsable en Nouvelle-Écosse', 1848, false, NULL, 'La Nouvelle-Écosse devient la première colonie britannique d''Amérique du Nord à obtenir un gouvernement responsable, marquant une étape importante vers l''autonomie gouvernementale. Cela signifie que le pouvoir exécutif est responsable devant une assemblée élue.', 'La Colonisation de l''Australie : De la Première Flotte à la Fédération (1788-1901)', '', 'PENDING', '', '2026-03-04 07:23:47.356346+00', NULL, NULL, NULL, ''),
	(1257, 'Acquisition de la Terre de Rupert par le Canada', 1869, false, NULL, 'Le Canada acquiert officiellement la Terre de Rupert et le Territoire du Nord-Ouest de la Compagnie de la Baie d''Hudson. Cette acquisition massive augmente considérablement le territoire du Canada et ouvre la voie à l''expansion vers l''ouest.', 'La Colonisation de l''Australie : De la Première Flotte à la Fédération (1788-1901)', '', 'PENDING', '', '2026-03-04 07:23:47.356346+00', NULL, NULL, NULL, ''),
	(1258, 'Première Convention Fédérale Nationale à Sydney', 1891, false, NULL, 'La première Convention Fédérale Nationale se réunit à Sydney pour rédiger une constitution pour le Commonwealth d''Australie. Les délégués de six colonies australiennes et de Nouvelle-Zélande participent.', 'La Colonisation de l''Australie : De la Première Flotte à la Fédération (1788-1901)', '', 'PENDING', '', '2026-03-04 07:23:47.356346+00', NULL, NULL, NULL, ''),
	(1259, 'Publication du livre "High Adventure" d''Edmund Hillary', 1955, false, NULL, 'Edmund Hillary publie son récit de l''ascension de l''Everest. Le livre devient un best-seller international et popularise l''histoire de l''expédition.', 'L''histoire de la conquête du mont Everest : Des premières expéditions aux ascensions modernes', '', 'PENDING', '', '2026-03-04 07:23:47.356346+00', NULL, NULL, NULL, ''),
	(1260, 'Création du parc national de Sagarmatha au Népal, incluant le mont Everest', 1976, false, NULL, 'Le parc national de Sagarmatha est créé pour protéger l''environnement autour du mont Everest. Cette initiative vise à préserver la biodiversité et le patrimoine culturel de la région.', 'L''histoire de la conquête du mont Everest : Des premières expéditions aux ascensions modernes', '', 'PENDING', '', '2026-03-04 07:23:47.356346+00', NULL, NULL, NULL, ''),
	(1261, 'Ouverture du téléphérique de l''Aiguille du Midi', 1955, false, NULL, 'Inauguration du téléphérique permettant un accès facilité à la haute montagne et stimulant le tourisme d''altitude dans le massif du Mont-Blanc. Il a permis de démocratiser l''accès à la haute montagne.', 'L''histoire de la conquête du mont Everest : Des premières expéditions aux ascensions modernes', '', 'PENDING', '', '2026-03-04 07:23:47.356346+00', NULL, NULL, NULL, ''),
	(1262, 'Adoption de la Convention sur la protection des Alpes (Convention Alpine)', 1991, false, NULL, 'Signature d''un traité international entre les pays alpins visant à promouvoir un développement durable et à protéger l''environnement montagnard face aux pressions du tourisme et des activités économiques. Elle a été signée à Salzbourg.', 'L''histoire de la conquête du mont Everest : Des premières expéditions aux ascensions modernes', '', 'PENDING', '', '2026-03-04 07:23:47.356346+00', NULL, NULL, NULL, ''),
	(1263, 'Publication du rapport de l''ONU sur l''impact du tourisme sur les glaciers', 2003, false, NULL, 'Un rapport de l''Organisation Mondiale du Tourisme (OMT) met en évidence l''impact négatif du tourisme de masse sur les glaciers et les écosystèmes de montagne, soulignant la nécessité d''un tourisme plus durable. Il a alerté sur la fonte des glaces.', 'L''histoire de la conquête du mont Everest : Des premières expéditions aux ascensions modernes', '', 'PENDING', '', '2026-03-04 07:23:47.356346+00', NULL, NULL, NULL, ''),
	(1264, 'Admission de la Louisiane comme 18e État des États-Unis', 1812, false, NULL, 'Le territoire de la Louisiane est admis dans l''Union en tant qu''État, marquant une étape importante dans l''intégration du territoire acquis et son développement politique.', 'La Conquête du Far West Américain : Pionniers, Cowboys et Natifs (1803-1912)', '', 'PENDING', '', '2026-03-04 07:23:47.356346+00', NULL, NULL, NULL, ''),
	(1265, 'Proclamation de la République des États-Unis du Brésil', 1889, false, NULL, 'La monarchie brésilienne est renversée par un coup d''État militaire, et la République des États-Unis du Brésil est proclamée. Cet événement met fin au règne de Pierre II et marque le début d''une nouvelle ère politique pour le pays.', 'Les empires coloniaux portugais et espagnol : De la découverte à l''indépendance (1415-1898)', '', 'PENDING', '', '2026-03-04 07:23:47.356346+00', NULL, NULL, NULL, ''),
	(1266, 'Fondation du studio Nestor Film Company (Hollywood)', 1911, false, NULL, 'Le studio Nestor Film Company, fondé par David Horsley, s''installe à Hollywood, marquant l''arrivée du premier studio de cinéma majeur dans la région. Cet événement contribue à l''essor d''Hollywood comme centre de l''industrie cinématographique.', 'L''Âge d''Or d''Hollywood : Des Premiers Studios aux Blockbusters Modernes (1910-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.356346+00', NULL, NULL, NULL, ''),
	(1267, 'Création de la MPPC (Motion Picture Patents Company)', 1908, false, NULL, 'La Motion Picture Patents Company (MPPC), surnommée ''The Trust'', est formée par les principaux détenteurs de brevets cinématographiques. Elle vise à contrôler l''industrie du cinéma aux États-Unis, poussant les cinéastes indépendants à s''installer à Hollywood pour échapper à son emprise.', 'L''Âge d''Or d''Hollywood : Des Premiers Studios aux Blockbusters Modernes (1910-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.356346+00', NULL, NULL, NULL, ''),
	(1268, 'Première diffusion du "Ed Sullivan Show" sur CBS', 1948, false, NULL, 'Lancement du "Ed Sullivan Show" (initialement "Toast of the Town") sur CBS. Cette émission de variétés devient l''une des plus populaires de l''histoire de la télévision américaine, contribuant à populariser de nombreux artistes.', 'L''Âge d''Or d''Hollywood : Des Premiers Studios aux Blockbusters Modernes (1910-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.356346+00', NULL, NULL, NULL, ''),
	(1269, 'Première du film ''Psychose'' d''Alfred Hitchcock à New York', 1960, false, NULL, 'Le film d''horreur psychologique, réalisé avec un budget modeste, choque le public et redéfinit les codes du genre. Il marque un tournant dans la carrière d''Hitchcock et influence durablement le cinéma.', 'L''Âge d''Or d''Hollywood : Des Premiers Studios aux Blockbusters Modernes (1910-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.356346+00', NULL, NULL, NULL, ''),
	(1270, 'Sortie du film "Bonnie and Clyde" (Arthur Penn)', 1967, false, NULL, 'Ce film, considéré comme un des premiers du Nouvel Hollywood, révolutionne le cinéma américain par sa violence et son esthétique. Il contribue à briser les tabous et à attirer un public plus jeune.', 'L''Âge d''Or d''Hollywood : Des Premiers Studios aux Blockbusters Modernes (1910-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.356346+00', NULL, NULL, NULL, ''),
	(1271, 'Sortie du film *Terminator 2 : Le Jugement dernier*', 1991, false, NULL, 'Ce film de James Cameron utilise des effets spéciaux numériques révolutionnaires, notamment pour le personnage du T-1000. Il démontre le potentiel des images de synthèse dans le cinéma d''action.', 'L''Âge d''Or d''Hollywood : Des Premiers Studios aux Blockbusters Modernes (1910-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.356346+00', NULL, NULL, NULL, ''),
	(1272, 'Sortie du film *Avatar*', 2009, false, NULL, 'Le film de James Cameron utilise une technologie 3D immersive et des effets spéciaux avancés pour créer un monde extraterrestre. Il redéfinit l''expérience cinématographique et établit de nouvelles normes pour les effets visuels.', 'L''Âge d''Or d''Hollywood : Des Premiers Studios aux Blockbusters Modernes (1910-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.356346+00', NULL, NULL, NULL, ''),
	(1276, 'Inauguration du Stèle 29 de Tikal, plus ancien monument maya daté avec précision', 292, false, NULL, 'La stèle 29, découverte à Tikal, est le plus ancien monument maya daté avec précision selon le calendrier maya, marquant une étape importante dans le développement de l''écriture et de la chronologie maya. Elle témoigne de la sophistication de leur système de datation.', 'L''essor et la chute des civilisations précolombiennes : des Olmèques à la conquête espagnole (1200 AEC - 1550)', '', 'PENDING', '', '2026-03-04 07:23:47.356346+00', NULL, NULL, NULL, ''),
	(1277, 'Consécration du Temple des Inscriptions à Palenque par K''inich Janaab'' Pakal', 692, false, NULL, 'K''inich Janaab'' Pakal, roi de Palenque, consacre le Temple des Inscriptions, un monument funéraire majeur abritant son sarcophage. Ce temple est renommé pour ses hiéroglyphes détaillés relatant l''histoire de Palenque.', 'L''essor et la chute des civilisations précolombiennes : des Olmèques à la conquête espagnole (1200 AEC - 1550)', '', 'PENDING', '', '2026-03-04 07:23:47.356346+00', NULL, NULL, NULL, ''),
	(1278, 'Achèvement de la Stèle H à Copán, commémorant le 15e K''atun', 731, false, NULL, 'La Stèle H à Copán est achevée, marquant la fin du 15e K''atun (cycle de 20 ans) du calendrier maya. Elle illustre l''importance des cycles temporels et des commémorations dans la société maya.', 'L''essor et la chute des civilisations précolombiennes : des Olmèques à la conquête espagnole (1200 AEC - 1550)', '', 'PENDING', '', '2026-03-04 07:23:47.356346+00', NULL, NULL, NULL, ''),
	(1279, 'Éruption du volcan Xitle qui force la migration et contribue à l''essor de Teotihuacan', 150, false, NULL, 'L''éruption du Xitle dévaste les zones agricoles environnantes, provoquant un afflux de populations vers Teotihuacan et stimulant sa croissance démographique et économique. Cet événement marque un tournant dans l''ascension de la cité.', 'L''essor et la chute des civilisations précolombiennes : des Olmèques à la conquête espagnole (1200 AEC - 1550)', '', 'PENDING', '', '2026-03-04 07:23:47.356346+00', NULL, NULL, NULL, ''),
	(1280, 'Construction de la Pyramide du Soleil à Teotihuacan', 225, false, NULL, 'Achèvement de la construction de la Pyramide du Soleil, le plus grand édifice de Teotihuacan. Elle témoigne de la puissance politique et religieuse de la cité et de sa capacité à mobiliser d''importantes ressources humaines et matérielles.', 'L''essor et la chute des civilisations précolombiennes : des Olmèques à la conquête espagnole (1200 AEC - 1550)', '', 'PENDING', '', '2026-03-04 07:23:47.356346+00', NULL, NULL, NULL, ''),
	(1281, 'Incendie de la Ciudadela et du Temple de Quetzalcoatl à Teotihuacan', 550, false, NULL, 'Destruction par le feu de la Ciudadela et du Temple de Quetzalcoatl, suggérant un bouleversement politique ou social majeur à Teotihuacan. Cet événement marque le début du déclin de la cité.', 'L''essor et la chute des civilisations précolombiennes : des Olmèques à la conquête espagnole (1200 AEC - 1550)', '', 'PENDING', '', '2026-03-04 07:23:47.356346+00', NULL, NULL, NULL, ''),
	(1282, 'Abandon progressif de Teotihuacan', 650, false, NULL, 'Début de l''abandon progressif de Teotihuacan par sa population, marquant la fin de son hégémonie en Mésoamérique. Les causes de ce déclin restent débattues, incluant des facteurs environnementaux, sociaux et politiques.', 'L''essor et la chute des civilisations précolombiennes : des Olmèques à la conquête espagnole (1200 AEC - 1550)', '', 'PENDING', '', '2026-03-04 07:23:47.356346+00', NULL, NULL, NULL, ''),
	(1283, 'Première bataille de Cochin', 1503, false, NULL, 'Le 1er mars 1503, la flotte de Duarte Pacheco Pereira repousse une attaque massive sur Cochin. Cet événement marque une étape importante dans l''établissement de la présence portugaise en Inde.', 'Les Grandes Découvertes Maritimes : De Christophe Colomb à Magellan (1492-1522)', '', 'PENDING', '', '2026-03-04 07:23:47.356346+00', NULL, NULL, NULL, ''),
	(1284, 'Raid français sur Port Royal (Jamaïque)', 1703, false, NULL, 'Une force navale française attaque Port Royal en Jamaïque, causant des dommages et perturbant le commerce. Cet événement souligne la vulnérabilité de la ville.', 'L''Âge d''or des Pirates : De la Flibuste à l''âge d''or (1650 - 1730)', '', 'PENDING', '', '2026-03-04 07:23:47.356346+00', NULL, NULL, NULL, ''),
	(1285, 'Construction du fort de San Miguel à Campeche ordonnée par le gouverneur Juan Caballero y Ocio', 1686, false, NULL, 'Suite au sac de Campeche en 1685, le gouverneur Juan Caballero y Ocio ordonne la construction du fort de San Miguel pour protéger la ville contre de futures attaques de pirates. Les travaux débutent en 1686.', 'L''Âge d''or des Pirates : De la Flibuste à l''âge d''or (1650 - 1730)', '', 'PENDING', '', '2026-03-04 07:23:47.356346+00', NULL, NULL, NULL, ''),
	(1286, 'Naissance d''Edward Teach, dit Barbe Noire', 1680, false, NULL, 'Date de naissance estimée d''Edward Teach, plus connu sous le nom de Barbe Noire, figure emblématique de la piraterie durant l''âge d''or. Sa vie antérieure reste largement méconnue.', 'L''Âge d''or des Pirates : De la Flibuste à l''âge d''or (1650 - 1730)', '', 'PENDING', '', '2026-03-04 07:23:47.356346+00', NULL, NULL, NULL, ''),
	(1287, 'Spirit s''enlise dans du sable (Troy)', 2009, false, NULL, 'Le rover Spirit s''enlise profondément dans du sable meuble dans une zone appelée "Troy". Les tentatives de libération échouent, marquant la fin de sa mobilité.', 'L''exploration de l''espace : De Spoutnik aux missions vers Mars (1957-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.356346+00', NULL, NULL, NULL, ''),
	(1288, 'Publication de la RFC 1009 : exigences pour les passerelles Internet (Requirements for Internet Gateways)', 1987, false, NULL, 'La RFC 1009, co-écrite par David L. Mills, définit les exigences pour les passerelles Internet (routeurs), contribuant à la standardisation et à l''expansion du réseau Internet. Elle formalise les principes de routage et d''adressage.', 'La révolution numérique : De la création d''Internet aux réseaux sociaux (1969-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.356346+00', NULL, NULL, NULL, ''),
	(1289, 'Éli Whitney brevète l''égreneuse à coton', 1793, false, NULL, 'L''égreneuse à coton simplifie et accélère le processus de séparation des fibres de coton des graines. Elle a un impact majeur sur la production de coton et l''économie du Sud des États-Unis.', 'La Révolution Industrielle : Inventions, innovations et bouleversements sociaux (1760-1880)', '', 'PENDING', '', '2026-03-04 07:23:47.356346+00', NULL, NULL, NULL, ''),
	(1290, 'Création de la National Labor Union (États-Unis)', 1866, false, NULL, 'Fondation de la première fédération ouvrière nationale américaine. Elle visait à obtenir la journée de huit heures, l''égalité salariale et la réforme monétaire.', 'La Révolution Industrielle : Inventions, innovations et bouleversements sociaux (1760-1880)', '', 'PENDING', '', '2026-03-04 07:23:47.356346+00', NULL, NULL, NULL, ''),
	(1291, 'Première édition des Jeux olympiques d''hiver en dehors d''Europe et d''Amérique du Nord à Sapporo', 1972, false, NULL, 'Les Jeux olympiques d''hiver se déroulent pour la première fois en Asie, à Sapporo, au Japon. C''est la première fois qu''ils ont lieu en dehors d''Europe et d''Amérique du Nord.', 'Les Jeux Olympiques : De la renaissance à l''ère moderne (1896-2016)', '', 'PENDING', '', '2026-03-04 07:23:47.356346+00', NULL, NULL, NULL, ''),
	(1292, 'Ouverture des premiers Jeux olympiques d''hiver de la jeunesse à Innsbruck, Autriche', 2012, false, NULL, 'Inauguration de la première édition des JOJ d''hiver, marquant une étape dans la promotion du sport chez les jeunes à l''échelle mondiale. L''événement a rassemblé des athlètes âgés de 15 à 18 ans.', 'Les Jeux Olympiques : De la renaissance à l''ère moderne (1896-2016)', '', 'PENDING', '', '2026-03-04 07:23:47.356346+00', NULL, NULL, NULL, ''),
	(1294, 'Achèvement de la construction de la Pagode du Grand Oie Sauvage à Chang''an (Xi''an)', 652, false, NULL, 'La pagode est construite pour abriter les soutras et les reliques rapportés d''Inde par le moine bouddhiste Xuanzang. Elle devient un symbole important de la présence du bouddhisme en Chine.', 'La route de la soie : Des caravanes aux comptoirs (130 AEC - 1453)', '', 'PENDING', '', '2026-03-04 07:23:47.356346+00', NULL, NULL, NULL, ''),
	(1295, 'Fondation du Bureau de la Navigation Maritime à Guangzhou', 714, false, NULL, 'L''établissement de cette institution marque une étape importante dans la facilitation et la régulation du commerce maritime sous la dynastie Tang. Guangzhou devient un port central pour le commerce sur la Route de la Soie maritime.', 'La route de la soie : Des caravanes aux comptoirs (130 AEC - 1453)', '', 'PENDING', '', '2026-03-04 07:23:47.356346+00', NULL, NULL, NULL, ''),
	(1296, 'Établissement du Bureau des Marchandises Étrangères à Yangzhou', 760, false, NULL, 'Yangzhou devient un centre majeur pour le commerce étranger, rivalisant avec Guangzhou. L''établissement de ce bureau témoigne de l''importance croissante du commerce avec l''Asie de l''Est et du Sud-Est.', 'La route de la soie : Des caravanes aux comptoirs (130 AEC - 1453)', '', 'PENDING', '', '2026-03-04 07:23:47.356346+00', NULL, NULL, NULL, ''),
	(1297, 'Interdiction du commerce privé du thé', 835, false, NULL, 'L''empereur Wenzong interdit le commerce privé du thé, le monopolisant pour l''État. Cette mesure vise à augmenter les revenus de l''État mais affecte le commerce privé le long de la Route de la Soie.', 'La route de la soie : Des caravanes aux comptoirs (130 AEC - 1453)', '', 'PENDING', '', '2026-03-04 07:23:47.356346+00', NULL, NULL, NULL, ''),
	(1298, 'Brevet américain pour le rotoscope accordé à Max Fleischer', 1917, false, NULL, 'Max Fleischer reçoit le brevet américain pour son invention, le rotoscope, une technique d''animation qui permet de tracer des images animées à partir de prises de vues réelles. Ce brevet marque une étape importante dans l''histoire de l''animation.', 'L''histoire du cinéma d''animation : Des premiers jouets optiques aux studios Pixar (1877-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.356346+00', NULL, NULL, NULL, ''),
	(1299, 'Sortie du court métrage d''animation "The Clown" (première utilisation de la rotoscopie par Max Fleischer)', 1916, false, NULL, 'Max Fleischer utilise pour la première fois la rotoscopie dans son court métrage d''animation ''The Clown''. Ce film marque les débuts de l''utilisation de cette technique révolutionnaire dans l''industrie de l''animation.', 'L''histoire du cinéma d''animation : Des premiers jouets optiques aux studios Pixar (1877-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.356346+00', NULL, NULL, NULL, ''),
	(1300, 'Fondation des studios d''animation Bray-Hurd Process Company (J.R. Bray et Max Fleischer)', 1914, false, NULL, 'J.R. Bray et Max Fleischer fondent la Bray-Hurd Process Company, un studio d''animation qui jouera un rôle important dans le développement des techniques d''animation. Cette collaboration marque le début de l''ascension de Fleischer dans l''industrie.', 'L''histoire du cinéma d''animation : Des premiers jouets optiques aux studios Pixar (1877-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.368173+00', NULL, NULL, NULL, ''),
	(1301, 'Naissance de Esther Fleischer (sœur de Max Fleischer, collaboratrice sur les films)', 1895, false, NULL, 'Naissance de Esther Fleischer, sœur de Max Fleischer. Elle a collaboré sur plusieurs de ses films d''animation, notamment en tant qu''animatrice et coloriste.', 'L''histoire du cinéma d''animation : Des premiers jouets optiques aux studios Pixar (1877-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.368173+00', NULL, NULL, NULL, ''),
	(1302, 'Sac de la Pierre Noire de La Mecque par les Qarmates', 930, false, NULL, 'Les Qarmates, une secte ismaélienne, pillent La Mecque et emportent la Pierre Noire à Hajar, en Arabie orientale. Elle ne sera restituée qu''en 951.', 'L''Âge d''Or de la Civilisation Islamique : De Bagdad à Cordoue (750-1258)', '', 'PENDING', '', '2026-03-04 07:23:47.368173+00', NULL, NULL, NULL, ''),
	(1303, 'Révolte du faubourg de Cordoue (Al-Ribad)', 818, false, NULL, 'Une importante révolte éclate dans le faubourg (al-Ribad) de Cordoue contre le pouvoir de l''émir Al-Hakam Ier. La répression de cette révolte est sanglante et marque les esprits.', 'L''Âge d''Or de la Civilisation Islamique : De Bagdad à Cordoue (750-1258)', '', 'PENDING', '', '2026-03-04 07:23:47.368173+00', NULL, NULL, NULL, ''),
	(1304, 'Abd al-Rahman II envoie une ambassade viking à la cour de Cordoue', 844, false, NULL, 'Suite à des raids vikings sur les côtes d''Al-Andalus, l''émir Abd al-Rahman II envoie une ambassade auprès des Vikings pour établir des relations diplomatiques et commerciales.', 'L''Âge d''Or de la Civilisation Islamique : De Bagdad à Cordoue (750-1258)', '', 'PENDING', '', '2026-03-04 07:23:47.368173+00', NULL, NULL, NULL, ''),
	(1305, 'Abd al-Rahman III se proclame calife de Cordoue', 929, false, NULL, 'Abd al-Rahman III adopte le titre de calife, rompant ainsi symboliquement avec le califat abbasside de Bagdad. Cet acte marque l''apogée de la puissance omeyyade en Espagne.', 'L''Âge d''Or de la Civilisation Islamique : De Bagdad à Cordoue (750-1258)', '', 'PENDING', '', '2026-03-04 07:23:47.368173+00', NULL, NULL, NULL, ''),
	(1306, 'Publication du Kitāb al-mukhtaṣar fī ḥisāb al-jabr wa-l-muqābala (Abrégé du calcul par la restauration et la comparaison) d''Al-Khwarizmi', 830, false, NULL, 'Cet ouvrage est considéré comme le texte fondateur de l''algèbre. Il introduit des méthodes systématiques pour résoudre des équations linéaires et quadratiques.', 'L''Âge d''Or de la Civilisation Islamique : De Bagdad à Cordoue (750-1258)', '', 'PENDING', '', '2026-03-04 07:23:47.368173+00', NULL, NULL, NULL, ''),
	(1307, 'Traduction en latin du Kitāb al-mukhtaṣar fī ḥisāb al-jabr wa-l-muqābala par Robert de Chester', 1145, false, NULL, 'Cette traduction a permis de diffuser les travaux d''Al-Khwarizmi en Europe. Elle a eu un impact significatif sur le développement des mathématiques occidentales.', 'L''Âge d''Or de la Civilisation Islamique : De Bagdad à Cordoue (750-1258)', '', 'PENDING', '', '2026-03-04 07:23:47.368173+00', NULL, NULL, NULL, ''),
	(1308, 'Traduction du traité ''Éléments'' d''Euclide en arabe', 800, false, NULL, 'Al-Hajjaj ibn Yusuf ibn Matar traduit ''Éléments'' d''Euclide en arabe. Cette traduction est l''une des premières étapes importantes dans l''assimilation des connaissances mathématiques grecques par les savants arabes.', 'L''Âge d''Or de la Civilisation Islamique : De Bagdad à Cordoue (750-1258)', '', 'PENDING', '', '2026-03-04 07:23:47.368173+00', NULL, NULL, NULL, ''),
	(1309, 'Début du règne d''Al-Ghazali comme professeur à l''école Nizamiyya de Bagdad', 1091, false, NULL, 'Al-Ghazali, éminent théologien et philosophe, commence à enseigner à l''école Nizamiyya, contribuant à la synthèse de la philosophie et de la théologie islamique.', 'L''Âge d''Or de la Civilisation Islamique : De Bagdad à Cordoue (750-1258)', '', 'PENDING', '', '2026-03-04 07:23:47.368173+00', NULL, NULL, NULL, ''),
	(1310, 'Transfert du Concile de Bâle à Ferrare par le pape Eugène IV', 1438, false, NULL, 'Le pape Eugène IV transfère le Concile de Bâle à Ferrare, en Italie, pour faciliter la venue de délégations byzantines et poursuivre les discussions sur l''union des Églises.', 'La Renaissance Italienne : De Florence à Rome, l''éclosion des arts et des sciences', '', 'PENDING', '', '2026-03-04 07:23:47.368173+00', NULL, NULL, NULL, ''),
	(1311, 'Nicolas V devient pape', 1447, false, NULL, 'Élection de Nicolas V, pape humaniste qui favorise les arts et les lettres et relance les travaux à Rome. Il est connu pour avoir fondé la Bibliothèque Vaticane.', 'La Renaissance Italienne : De Florence à Rome, l''éclosion des arts et des sciences', '', 'PENDING', '', '2026-03-04 07:23:47.368173+00', NULL, NULL, NULL, ''),
	(1312, 'Installation de la première presse à imprimer à Rome par Conrad Sweynheym et Arnold Pannartz', 1467, false, NULL, 'Introduit l''imprimerie dans la capitale pontificale, permettant la production de textes classiques et religieux. Cet événement marque un tournant dans la diffusion du savoir à Rome.', 'La Renaissance Italienne : De Florence à Rome, l''éclosion des arts et des sciences', '', 'PENDING', '', '2026-03-04 07:23:47.368173+00', NULL, NULL, NULL, ''),
	(1313, 'Impression du "Hypnerotomachia Poliphili" à Venise par Alde Manuce', 1499, false, NULL, 'Publication d''un roman allégorique illustré, célèbre pour sa typographie élégante et ses gravures sur bois. Cet événement est un chef-d''œuvre de l''imprimerie de la Renaissance.', 'La Renaissance Italienne : De Florence à Rome, l''éclosion des arts et des sciences', '', 'PENDING', '', '2026-03-04 07:23:47.368173+00', NULL, NULL, NULL, ''),
	(1314, 'Ouverture du premier magasin IKEA en Chine continentale (Shanghai)', 1998, false, NULL, 'Le premier magasin IKEA en Chine continentale ouvre ses portes à Shanghai, marquant une étape importante dans l''expansion commerciale de l''entreprise en Asie. Cela reflète l''essor du commerce international et l''intérêt croissant des entreprises occidentales pour le marché chinois.', 'La conquête du Mont Everest : Des premières tentatives aux ascensions record (1921-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.368173+00', NULL, NULL, NULL, ''),
	(1315, 'Première ascension féminine de l''Annapurna I par une expédition américaine', 1978, false, NULL, 'Le 15 octobre 1978, Irene Miller et Vera Komarkova, membres d''une expédition américaine, réalisent la première ascension féminine de l''Annapurna I. Alison Chadwick-Onyszkiewicz et Vera Watson meurent lors de cette expédition.', 'La conquête du Mont Everest : Des premières tentatives aux ascensions record (1921-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.368173+00', NULL, NULL, NULL, ''),
	(1316, 'Æthelflæd, Dame des Merciens, reprend Derby aux Vikings', 917, false, NULL, 'Æthelflæd, Dame des Merciens, reprend la ville de Derby aux Vikings. Cette victoire marque une étape importante dans la reconquête des territoires du Danelaw par les Anglo-Saxons.', 'L''Épopée Viking : Raids, explorations et royaumes (793-1066)', '', 'PENDING', '', '2026-03-04 07:23:47.368173+00', NULL, NULL, NULL, ''),
	(1320, 'Inauguration du Stèle 31 à Tikal, commémorant Siyaj Chan K''awiil II', 445, false, NULL, 'La Stèle 31 est un monument important de Tikal, fournissant des informations sur l''histoire et la généalogie de la dynastie. Elle marque un moment clé de la période classique.', 'L''essor et la chute des cités-États Mayas : Des origines à l''abandon (250-1697)', '', 'PENDING', '', '2026-03-04 07:23:47.368173+00', NULL, NULL, NULL, ''),
	(1321, 'Début du règne de Yuknoom Ch''een II, roi de Calakmul', 636, false, NULL, 'Yuknoom Ch''een II, aussi connu sous le nom de Yuknoom le Grand, a mené Calakmul à son apogée en termes de puissance et d''influence. Son règne a marqué une période de prospérité et d''expansion.', 'L''essor et la chute des cités-États Mayas : Des origines à l''abandon (250-1697)', '', 'PENDING', '', '2026-03-04 07:23:47.368173+00', NULL, NULL, NULL, ''),
	(1322, 'Victoire de Calakmul sur Tikal lors d''une bataille majeure', 672, false, NULL, 'Cette victoire a temporairement affaibli Tikal et renforcé la domination de Calakmul dans la région. Elle a eu un impact significatif sur les relations politiques entre les deux cités.', 'L''essor et la chute des cités-États Mayas : Des origines à l''abandon (250-1697)', '', 'PENDING', '', '2026-03-04 07:23:47.368173+00', NULL, NULL, NULL, ''),
	(1323, 'Début du règne de Jasaw Chan K''awiil I à Tikal', 682, false, NULL, 'Jasaw Chan K''awiil I a restauré la puissance de Tikal après une période de déclin. Son règne est marqué par des constructions importantes et des victoires militaires.', 'L''essor et la chute des cités-États Mayas : Des origines à l''abandon (250-1697)', '', 'PENDING', '', '2026-03-04 07:23:47.368173+00', NULL, NULL, NULL, ''),
	(1324, 'Victoire de Tikal sur Calakmul (bataille de 5-Eb)', 695, false, NULL, 'Jasaw Chan K''awiil I de Tikal vainc Yuknoom Yich''aak K''ak'' de Calakmul, marquant un tournant dans la rivalité entre les deux cités et le déclin de Calakmul.', 'L''essor et la chute des cités-États Mayas : Des origines à l''abandon (250-1697)', '', 'PENDING', '', '2026-03-04 07:23:47.368173+00', NULL, NULL, NULL, ''),
	(1325, 'Première utilisation attestée des chiffres arabes dans le manuscrit "Codex Vigilanus"', 976, false, NULL, 'Le Codex Vigilanus, compilé par le moine Vigila, contient la première utilisation documentée des chiffres arabes (y compris un zéro) en Europe occidentale. Il marque une étape importante dans l''adoption de ce système numérique.', 'L''essor et la chute des cités-États Mayas : Des origines à l''abandon (250-1697)', '', 'PENDING', '', '2026-03-04 07:23:47.368173+00', NULL, NULL, NULL, ''),
	(1326, 'Publication du "Livre des étoiles fixes" d''Al-Sufi', 964, false, NULL, 'L''astronome perse Al-Sufi publie son "Livre des étoiles fixes", une révision et un complément du catalogue d''étoiles de Ptolémée. Il inclut des descriptions et des illustrations détaillées des constellations et des étoiles.', 'L''essor et la chute des cités-États Mayas : Des origines à l''abandon (250-1697)', '', 'PENDING', '', '2026-03-04 07:23:47.368173+00', NULL, NULL, NULL, ''),
	(1327, 'Consécration de l''église Saint-Michel de Hildesheim', 1022, false, NULL, 'L''église Saint-Michel, un chef-d''œuvre de l''architecture ottonienne, est consacrée le 29 septembre par l''évêque Bernward de Hildesheim. Elle témoigne de la prospérité relative de certaines régions malgré les défis climatiques et politiques de l''époque.', 'L''essor et la chute des cités-États Mayas : Des origines à l''abandon (250-1697)', '', 'PENDING', '', '2026-03-04 07:23:47.368173+00', NULL, NULL, NULL, ''),
	(1328, 'Destruction de Cholula par les Toltèques', 900, false, NULL, 'La cité de Cholula, important centre religieux et commercial mésoaméricain, est détruite et pillée par les Toltèques. Cet événement marque un tournant dans l''histoire de la région et le déclin de l''influence de Cholula.', 'L''essor et la chute des cités-États Mayas : Des origines à l''abandon (250-1697)', '', 'PENDING', '', '2026-03-04 07:23:47.368173+00', NULL, NULL, NULL, ''),
	(1329, 'Première mention du village de Bernburg (Saale)', 961, false, NULL, 'Le village de Bernburg (Saale) est mentionné pour la première fois dans un document officiel. Cette mention témoigne de l''expansion et de l''organisation administrative du Saint-Empire romain germanique.', 'L''essor et la chute des cités-États Mayas : Des origines à l''abandon (250-1697)', '', 'PENDING', '', '2026-03-04 07:23:47.368173+00', NULL, NULL, NULL, ''),
	(1330, 'Début du règne de Taksony en Hongrie', 955, false, NULL, 'Taksony devient Grand Prince des Magyars (Hongrois). Son règne marque une période de transition et de consolidation du pouvoir magyar après les raids dévastateurs en Europe occidentale.', 'L''essor et la chute des cités-États Mayas : Des origines à l''abandon (250-1697)', '', 'PENDING', '', '2026-03-04 07:23:47.368173+00', NULL, NULL, NULL, ''),
	(1331, 'Révolte Maya du Yucatán menée par Jacinto Canek', 1761, false, NULL, 'Jacinto Canek mène une importante révolte Maya contre la domination espagnole dans le Yucatán. Bien que la rébellion soit écrasée, elle symbolise la résistance continue.', 'L''essor et la chute des cités-États Mayas : Des origines à l''abandon (250-1697)', '', 'PENDING', '', '2026-03-04 07:23:47.368173+00', NULL, NULL, NULL, ''),
	(1332, 'Destruction de la statue de la Vierge de Izamal par les Mayas rebelles', 1562, false, NULL, 'Dans le contexte de la répression menée par Diego de Landa, des Mayas détruisent la statue de la Vierge à Izamal. Cet acte de rébellion marque une escalade de la résistance culturelle et religieuse.', 'L''essor et la chute des cités-États Mayas : Des origines à l''abandon (250-1697)', '', 'PENDING', '', '2026-03-04 07:23:47.368173+00', NULL, NULL, NULL, ''),
	(1333, 'Première session d''enregistrement de "Jackie Brenston and His Delta Cats" avec Ike Turner (Memphis)', 1951, false, NULL, 'Jackie Brenston and His Delta Cats, avec Ike Turner, enregistrent ''Rocket 88'' aux studios Sun de Memphis. Considéré comme un des premiers enregistrements de rock and roll.', 'L''Histoire du Rock''n''Roll : De ses Racines au Phénomène Mondial', '', 'PENDING', '', '2026-03-04 07:23:47.368173+00', NULL, NULL, NULL, ''),
	(1334, 'Première diffusion de l''émission "Yo! MTV Raps"', 1988, false, NULL, 'Le 6 août 1988, MTV diffuse le premier épisode de "Yo! MTV Raps", une émission consacrée au hip-hop. Elle contribue à populariser le genre auprès d''un public plus large et diversifié.', 'L''Histoire du Rock''n''Roll : De ses Racines au Phénomène Mondial', '', 'PENDING', '', '2026-03-04 07:23:47.368173+00', NULL, NULL, NULL, ''),
	(1335, 'Assassinat du gouverneur Le Vasseur à l''île de la Tortue', 1653, false, NULL, 'Le gouverneur Le Vasseur est assassiné par ses propres hommes à la Tortue, plongeant l''île dans une période d''instabilité et de luttes de pouvoir entre les différentes factions de flibustiers.', 'L''Âge d''Or des Pirates Caribéens : Abordages, Trésors et Légendes (1650-1730)', '', 'PENDING', '', '2026-03-04 07:23:47.368173+00', NULL, NULL, NULL, ''),
	(1336, 'Publication du rapport NSC-68 aux États-Unis', 1950, false, NULL, 'Le Conseil national de sécurité américain (NSC) publie le rapport NSC-68, préconisant une augmentation massive des dépenses militaires et une politique de containment agressive contre le communisme. Ce rapport influence fortement la stratégie américaine pendant la Guerre froide.', 'La Guerre Froide : De la Bombe Atomique à la Chute du Mur de Berlin', '', 'PENDING', '', '2026-03-04 07:23:47.368173+00', NULL, NULL, NULL, ''),
	(1337, 'Sortie du film Superman', 1978, false, NULL, 'Le film Superman de Richard Donner sort en salles. Il est l''un des premiers films de super-héros à gros budget et contribue à populariser le genre.', 'L''histoire du Cinéma : Des premiers pas aux blockbusters numériques (1895-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.368173+00', NULL, NULL, NULL, ''),
	(1338, 'Sortie du film Indiana Jones et les Aventuriers de l''arche perdue', 1981, false, NULL, 'Le film Indiana Jones et les Aventuriers de l''arche perdue (Raiders of the Lost Ark) sort en salles. Il consolide le statut de Steven Spielberg et George Lucas comme maîtres du blockbuster.', 'L''histoire du Cinéma : Des premiers pas aux blockbusters numériques (1895-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.368173+00', NULL, NULL, NULL, ''),
	(1339, 'Début des travaux de construction du viaduc de Sankey', 1828, false, NULL, 'Les travaux de construction du viaduc de Sankey, un élément clé du chemin de fer Liverpool-Manchester, débutent en janvier 1828. Ce viaduc permettait de franchir la vallée de Sankey.', 'La Révolution Industrielle : De la Machine à Vapeur à la Production de Masse', '', 'PENDING', '', '2026-03-04 07:23:47.368173+00', NULL, NULL, NULL, ''),
	(1340, 'Établissement du comptoir commercial romain de Muziris (Kerala)', 45, false, NULL, 'Muziris devient un port majeur pour le commerce des épices, des pierres précieuses et des textiles entre l''Inde et l''Empire romain. Le commerce caravanier s''intensifie vers l''Est.', 'La Route de la Soie : Échanges, découvertes et conflits (Ier siècle - XIIIe siècle)', '', 'PENDING', '', '2026-03-04 07:23:47.368173+00', NULL, NULL, NULL, ''),
	(1341, 'Construction du caravansérail de Rabat-e Sharaf au Khorasan', 1114, false, NULL, 'Ce caravansérail, situé sur la route de la soie, offre un abri sécurisé et des services aux marchands et voyageurs. Il symbolise l''infrastructure croissante soutenant le commerce caravanier.', 'La Route de la Soie : Échanges, découvertes et conflits (Ier siècle - XIIIe siècle)', '', 'PENDING', '', '2026-03-04 07:23:47.368173+00', NULL, NULL, NULL, ''),
	(1342, 'Diplomatie entre la Chine des Tang et le royaume du Tibet (Traité de Chang''an)', 821, false, NULL, 'Ce traité établit des relations pacifiques et commerciales entre les deux empires, facilitant le commerce caravanier à travers les régions frontalières. Il marque un apogée des échanges culturels et économiques.', 'La Route de la Soie : Échanges, découvertes et conflits (Ier siècle - XIIIe siècle)', '', 'PENDING', '', '2026-03-04 07:23:47.368173+00', NULL, NULL, NULL, ''),
	(1343, 'Xuanzang arrive à Chang''an avec des écritures bouddhistes', 645, false, NULL, 'Le moine bouddhiste chinois Xuanzang retourne à Chang''an après un long voyage en Inde, rapportant avec lui de nombreux textes bouddhistes. Ces textes ont eu un impact profond sur le bouddhisme chinois.', 'La Route de la Soie : Échanges, découvertes et conflits (Ier siècle - XIIIe siècle)', '', 'PENDING', '', '2026-03-04 07:23:47.368173+00', NULL, NULL, NULL, ''),
	(1344, 'Traduction arabe du Siddhanta (Brahmasphutasiddhanta) de Brahmagupta par Muhammad al-Fazari', 771, false, NULL, 'Introduction des chiffres indiens et des concepts mathématiques indiens, notamment le zéro, dans le monde arabe. Cette traduction a permis la diffusion de ces connaissances en Europe via Al-Andalus.', 'La Route de la Soie : Échanges, découvertes et conflits (Ier siècle - XIIIe siècle)', '', 'PENDING', '', '2026-03-04 07:23:47.368173+00', NULL, NULL, NULL, ''),
	(1345, 'Publication du Kitāb al-Hāwī fī al-ṭibb (grand livre de médecine) par Rhazès', 925, false, NULL, 'Cette encyclopédie médicale monumentale, basée sur l''observation clinique et l''expérimentation, synthétise les connaissances médicales grecques, indiennes et persanes. Elle influence la médecine en Europe pendant des siècles.', 'La Route de la Soie : Échanges, découvertes et conflits (Ier siècle - XIIIe siècle)', '', 'PENDING', '', '2026-03-04 07:23:47.368173+00', NULL, NULL, NULL, ''),
	(1346, 'Traduction latine du Liber pantegni (intégrale de l''Art royal) de Ali ibn Abbas al-Majusi par Constantin l''Africain', 1087, false, NULL, 'Cette traduction introduit en Europe les connaissances médicales du monde islamique, contribuant à la renaissance de la médecine occidentale. Il s''agit d''une des premières traductions importantes de textes médicaux arabes en latin.', 'La Route de la Soie : Échanges, découvertes et conflits (Ier siècle - XIIIe siècle)', '', 'PENDING', '', '2026-03-04 07:23:47.368173+00', NULL, NULL, NULL, ''),
	(1348, 'Promulgation du statut de Kalisz (Statut de Kalisz)', 1264, false, NULL, 'Bolesław the Pious, Duke of Greater Poland, grants the Statute of Kalisz, guaranteeing rights and privileges to the Jewish population. This encouraged Jewish merchants and scholars to settle in Poland, boosting trade and cultural exchange.', 'La Route de la Soie : Échanges, découvertes et conflits (Ier siècle - XIIIe siècle)', '', 'PENDING', '', '2026-03-04 07:23:47.368173+00', NULL, NULL, NULL, ''),
	(1349, 'Publication du rapport de la Commission Fagan sur les émeutes de 1949 à Durban', 1949, false, NULL, 'Le rapport de la Commission Fagan examine les causes et les conséquences des émeutes raciales de 1949 à Durban, en Afrique du Sud. Il met en lumière les tensions sociales et économiques sous-jacentes.', 'La Décolonisation de l''Afrique : Luttes pour l''Indépendance et Nouveaux États (1945-1994)', '', 'PENDING', '', '2026-03-04 07:23:47.368173+00', NULL, NULL, NULL, ''),
	(1350, 'Fondation de la Conférence des organisations nationalistes des colonies portugaises (CONCP) à Casablanca', 1961, false, NULL, 'Les mouvements de libération de l''Angola (MPLA), du Mozambique (FRELIMO), de Guinée-Bissau et du Cap-Vert (PAIGC) s''unissent pour coordonner leurs efforts dans la lutte contre le colonialisme portugais. Cette conférence renforce la coopération entre les mouvements.', 'La Décolonisation de l''Afrique : Luttes pour l''Indépendance et Nouveaux États (1945-1994)', '', 'PENDING', '', '2026-03-04 07:23:47.368173+00', NULL, NULL, NULL, ''),
	(1351, 'Début du règne du roi Godfred de Danemark', 804, false, NULL, 'Godfred monte sur le trône du Danemark. Son règne marque une période d''expansion et de consolidation du pouvoir viking, avec des raids plus organisés et ambitieux.', 'L''Épopée Viking : Raids, Commerce et Royaumes (793-1066)', '', 'PENDING', '', '2026-03-04 07:23:47.368173+00', NULL, NULL, NULL, ''),
	(1352, 'Fondation du comptoir commercial de Hedeby', 804, false, NULL, 'Hedeby (Haithabu), situé au sud du Danemark actuel, devient un important centre commercial viking. Sa position stratégique facilite les échanges entre la mer Baltique et la mer du Nord.', 'L''Épopée Viking : Raids, Commerce et Royaumes (793-1066)', '', 'PENDING', '', '2026-03-04 07:23:47.368173+00', NULL, NULL, NULL, ''),
	(1353, 'Construction du Knarr de Skuldelev', 1030, false, NULL, 'Construction d''un Knarr, navire marchand viking découvert à Skuldelev, Danemark. Ce type de navire était essentiel pour le commerce maritime longue distance et le transport de marchandises.', 'L''Épopée Viking : Raids, Commerce et Royaumes (793-1066)', '', 'PENDING', '', '2026-03-04 07:23:47.368173+00', NULL, NULL, NULL, ''),
	(1354, 'Lancement du premier album commercialisé sur CD par Billy Joel ("52nd Street")', 1982, false, NULL, 'L''album "52nd Street" de Billy Joel est le premier album à être commercialisé sur CD. Il marque un tournant dans l''industrie musicale.', 'La révolution des nouvelles technologies : L''âge d''or de l''innovation (1970-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.394146+00', NULL, NULL, NULL, ''),
	(1355, 'Mention de la Bible de Gutenberg dans la chronique de Mathieu de Coucy', 1470, false, NULL, 'La chronique de Mathieu de Coucy mentionne l''existence de livres imprimés, témoignant de la reconnaissance de cette nouvelle technologie. C''est une des premières mentions de l''impact de l''imprimerie dans les écrits de l''époque.', 'L''Invention et la Diffusion de l''Imprimerie : Une Révolution de la Connaissance (1450-1800)', '', 'PENDING', '', '2026-03-04 07:23:47.394146+00', NULL, NULL, NULL, ''),
	(1356, 'Première impression à Paris par la Gering, Friburger et Crantz (imprimeurs)', 1470, false, NULL, 'L''atelier de Gering, Friburger et Crantz introduit l''imprimerie à Paris, marquant le début de l''essor de l''imprimerie dans la capitale française. Ils publient le *Epistolae Gasparini Pergamensis*.', 'L''Invention et la Diffusion de l''Imprimerie : Une Révolution de la Connaissance (1450-1800)', '', 'PENDING', '', '2026-03-04 07:23:47.394146+00', NULL, NULL, NULL, ''),
	(1357, 'Installation de la première presse à imprimer à Louvain (Belgique)', 1473, false, NULL, 'Jan van Westfalen installe la première presse à imprimer à Louvain, contribuant à la diffusion du savoir et des idées dans les Pays-Bas. Il imprime le *De Civitate Dei* d''Augustin.', 'L''Invention et la Diffusion de l''Imprimerie : Une Révolution de la Connaissance (1450-1800)', '', 'PENDING', '', '2026-03-04 07:23:47.394146+00', NULL, NULL, NULL, ''),
	(1358, 'Adoption du Statut des libraires et imprimeurs de Paris', 1500, false, NULL, 'Ce statut réglemente la profession et soumet les publications à l''approbation de l''Université de Paris. Il marque une étape importante dans le contrôle de l''imprimerie par les autorités.', 'L''Invention et la Diffusion de l''Imprimerie : Une Révolution de la Connaissance (1450-1800)', '', 'PENDING', '', '2026-03-04 07:23:47.394146+00', NULL, NULL, NULL, ''),
	(1359, 'Publication du Statute of Anne (première loi moderne sur le droit d''auteur au Royaume-Uni)', 1710, false, NULL, 'Ce statut accorde aux auteurs le droit exclusif de reproduire leurs œuvres pendant une période limitée. Il marque une étape cruciale dans la reconnaissance légale du droit d''auteur.', 'L''Invention et la Diffusion de l''Imprimerie : Une Révolution de la Connaissance (1450-1800)', '', 'PENDING', '', '2026-03-04 07:23:47.394146+00', NULL, NULL, NULL, ''),
	(1360, 'Première mention de la Route de la Soie par Pline l''Ancien dans son Histoire Naturelle', 77, false, NULL, 'L''auteur romain décrit les marchandises précieuses venant de Seres (Chine) par une route terrestre. C''est une des premières descriptions occidentales de ce commerce lointain.', 'La Route de la Soie : Échanges, Innovations et Empires (Ier - XIVe siècles)', '', 'PENDING', '', '2026-03-04 07:23:47.394146+00', NULL, NULL, NULL, ''),
	(1361, 'Ouverture du col du Karakoram, facilitant le commerce entre l''Inde et la Chine', 60, false, NULL, 'Ce col de haute montagne devient une voie importante pour les caravanes reliant les empires Kushan et Han. Il permet un échange plus direct de biens et d''idées.', 'La Route de la Soie : Échanges, Innovations et Empires (Ier - XIVe siècles)', '', 'PENDING', '', '2026-03-04 07:23:47.394146+00', NULL, NULL, NULL, ''),
	(1362, 'Construction du caravansérail de Rabat-i Malik par les Karakhanides', 1078, false, NULL, 'Ce caravansérail monumental, situé près de Samarcande, offre un refuge sûr et bien équipé pour les marchands voyageant le long de la Route de la Soie. Il témoigne de l''importance du commerce dans la région.', 'La Route de la Soie : Échanges, Innovations et Empires (Ier - XIVe siècles)', '', 'PENDING', '', '2026-03-04 07:23:47.394146+00', NULL, NULL, NULL, ''),
	(1363, 'Envoi de moines bouddhistes de Liang en Corée', 526, false, NULL, 'L''empereur Wu de la dynastie Liang envoie des moines bouddhistes et des textes sacrés en Corée. Cet événement marque une étape importante dans la diffusion du bouddhisme en Corée et l''établissement de liens culturels entre les deux pays.', 'La Route de la Soie : Échanges, Innovations et Empires (Ier - XIVe siècles)', '', 'PENDING', '', '2026-03-04 07:23:47.394146+00', NULL, NULL, NULL, ''),
	(1364, 'Introduction du bouddhisme au Japon par le roi Seong de Baekje', 538, false, NULL, 'Le roi Seong de Baekje, un royaume coréen, envoie une mission diplomatique à la cour impériale du Japon, apportant avec elle des statues de Bouddha et des textes bouddhistes. Cet événement est traditionnellement considéré comme l''introduction officielle du bouddhisme au Japon.', 'La Route de la Soie : Échanges, Innovations et Empires (Ier - XIVe siècles)', '', 'PENDING', '', '2026-03-04 07:23:47.394146+00', NULL, NULL, NULL, ''),
	(1365, 'Première utilisation documentée de la boussole par Alexandre Neckam', 1187, false, NULL, 'Le savant anglais Alexandre Neckam décrit l''utilisation de la boussole pour la navigation dans son traité ''De naturis rerum''. C''est l''une des premières mentions européennes de cet instrument.', 'La Route de la Soie : Échanges, Innovations et Empires (Ier - XIVe siècles)', '', 'PENDING', '', '2026-03-04 07:23:47.394146+00', NULL, NULL, NULL, ''),
	(1366, 'Invention de l''astrolabe universel par Ali ibn Isa', 927, false, NULL, 'Le célèbre astronome musulman Ali ibn Isa invente l''astrolabe universel, un instrument permettant de réaliser des observations astronomiques et de déterminer l''heure à partir de la position des étoiles.', 'La Route de la Soie : Échanges, Innovations et Empires (Ier - XIVe siècles)', '', 'PENDING', '', '2026-03-04 07:23:47.394146+00', NULL, NULL, NULL, ''),
	(1367, 'Construction du premier moulin à marée connu à Killoteran, Irlande', 619, false, NULL, 'Un moulin à marée est construit à Killoteran, près de Waterford, en Irlande. Il s''agit du plus ancien moulin à marée connu, utilisant l''énergie des marées pour moudre le grain.', 'La Route de la Soie : Échanges, Innovations et Empires (Ier - XIVe siècles)', '', 'PENDING', '', '2026-03-04 07:23:47.394146+00', NULL, NULL, NULL, ''),
	(1368, 'Nomination de Francesco Balducci Pegolotti comme agent de la Compagnia dei Bardi à Anvers', 1315, false, NULL, 'Francesco Balducci Pegolotti, an agent of the Florentine Compagnia dei Bardi, is stationed in Antwerp. He later wrote ''La Pratica della Mercatura'', a handbook for merchants that provided detailed information about trade routes, commodities, and customs duties along the Silk Road under Mongol rule.', 'La Route de la Soie : Échanges, Innovations et Empires (Ier - XIVe siècles)', '', 'PENDING', '', '2026-03-04 07:23:47.394146+00', NULL, NULL, NULL, ''),
	(1369, 'Inauguration du studio de cinéma Selig Polyscope à Edendale (Los Angeles)', 1909, false, NULL, 'Selig Polyscope ouvre un studio à Edendale, considéré comme le premier studio de cinéma permanent à Los Angeles. Il marque le début du déplacement de l''industrie cinématographique vers la Californie.', 'L''Histoire du Cinéma : Des Frères Lumière aux Blockbusters Contemporains', '', 'PENDING', '', '2026-03-04 07:23:47.394146+00', NULL, NULL, NULL, ''),
	(1370, 'Lancement du Apple II', 1977, false, NULL, 'Apple Computer lance l''Apple II, un des premiers ordinateurs personnels à succès commercial, contribuant à la démocratisation de l''informatique auprès du grand public.', 'L''Âge d''Or de l''Informatique Personnelle : Des Micro-ordinateurs à Internet (1975-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.394146+00', NULL, NULL, NULL, ''),
	(1371, 'Première version de Microsoft Excel pour Macintosh', 1985, false, NULL, 'Microsoft lance la première version d''Excel pour Macintosh. Il introduit une interface graphique conviviale et des fonctionnalités avancées, marquant le début de la domination de Microsoft dans le domaine des tableurs.', 'L''Âge d''Or de l''Informatique Personnelle : Des Micro-ordinateurs à Internet (1975-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.394146+00', NULL, NULL, NULL, ''),
	(1372, 'Siège de Médine (Bataille du Fossé)', 627, false, NULL, 'Les forces coalisées de La Mecque assiègent Médine. Les musulmans, dirigés par Mahomet, défendent la ville en creusant un fossé.', 'L''Expansion de l''Islam : Conquêtes, Dynasties et Échanges Culturels (622-1258)', '', 'PENDING', '', '2026-03-04 07:23:47.394146+00', NULL, NULL, NULL, ''),
	(1373, 'Début du siège de Damas par les forces du califat Rashidun', 634, false, NULL, 'Les armées musulmanes, sous le commandement de Khalid ibn al-Walid, commencent le siège de Damas, une ville byzantine majeure. Ce siège marque une étape cruciale dans la conquête de la Syrie.', 'L''Expansion de l''Islam : Conquêtes, Dynasties et Échanges Culturels (622-1258)', '', 'PENDING', '', '2026-03-04 07:23:47.394146+00', NULL, NULL, NULL, ''),
	(1374, 'Grande révolte des Zanj', 869, false, NULL, 'Début d''une importante rébellion d''esclaves africains (les Zanj) dans le sud de l''Irak, menaçant la stabilité du califat abbasside. La révolte dure plus de dix ans et affaiblit considérablement le pouvoir central.', 'L''Expansion de l''Islam : Conquêtes, Dynasties et Échanges Culturels (622-1258)', '', 'PENDING', '', '2026-03-04 07:23:47.394146+00', NULL, NULL, NULL, ''),
	(1375, 'Début du règne d''Ibrahim Ier comme premier émir aghlabide d''Ifriqiya', 800, false, NULL, 'Ibrahim Ier est nommé émir par le calife abbasside Harun al-Rashid, marquant le début de la dynastie aghlabide. Cette nomination confère une autonomie de facto à l''Ifriqiya (actuelle Tunisie et parties de l''Algérie et de la Libye).', 'L''Expansion de l''Islam : Conquêtes, Dynasties et Échanges Culturels (622-1258)', '', 'PENDING', '', '2026-03-04 07:23:47.394146+00', NULL, NULL, NULL, ''),
	(1376, 'Nomination de Tahir ibn Husayn comme gouverneur du Khorasan par le calife Al-Ma''mun', 821, false, NULL, 'Tahir ibn Husayn est nommé gouverneur du Khorasan, une région stratégique de l''est du califat abbasside. Cet événement marque le début de la dynastie Tahiride, bien que Tahir ne se soit jamais déclaré indépendant.', 'L''Expansion de l''Islam : Conquêtes, Dynasties et Échanges Culturels (622-1258)', '', 'PENDING', '', '2026-03-04 07:23:47.394146+00', NULL, NULL, NULL, ''),
	(1377, 'Accession de Nasr Ier au pouvoir comme émir samanide de Transoxiane', 864, false, NULL, 'Nasr Ier prend le contrôle de Samarcande et devient l''émir de Transoxiane, consolidant le pouvoir samanide dans la région. Cet événement marque une étape importante dans l''établissement de la dynastie Samanide.', 'L''Expansion de l''Islam : Conquêtes, Dynasties et Échanges Culturels (622-1258)', '', 'PENDING', '', '2026-03-04 07:23:47.394146+00', NULL, NULL, NULL, ''),
	(1387, 'Création du NACA (National Advisory Committee for Aeronautics)', 1915, false, NULL, 'Le NACA est créé aux États-Unis pour superviser et diriger la recherche scientifique en matière d''aéronautique. Il deviendra plus tard la NASA.', 'L''Histoire de l''Aéronautique : Des Premiers Vols aux Avions de Ligne (1903-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.394146+00', NULL, NULL, NULL, ''),
	(1388, 'Lancement du premier service de SMS par Vodafone au Royaume-Uni', 1992, false, NULL, 'Vodafone lance le premier service de Short Message Service (SMS) au Royaume-Uni, permettant l''envoi de courts messages texte entre téléphones mobiles. Le premier SMS est envoyé le 3 décembre par Neil Papworth.', 'La Révolution Numérique : De l''Ordinateur Personnel au Smartphone (1975-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.394146+00', NULL, NULL, NULL, ''),
	(1389, 'Publication de l''article "Personal Dynamic Media" d''Alan Kay dans Computer Magazine', 1977, false, NULL, 'Alan Kay décrit le concept d''un ordinateur personnel portable, le Dynabook, influençant le développement des interfaces graphiques et des tablettes. Cet article marque une étape importante dans la vision de l''informatique personnelle.', 'La Révolution Numérique : De l''Ordinateur Personnel au Smartphone (1975-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.394146+00', NULL, NULL, NULL, ''),
	(1390, 'Lancement du service Viewtron par Knight Ridder', 1980, false, NULL, 'Knight Ridder lance Viewtron, un des premiers services de Vidéotex aux États-Unis, offrant des informations et des services interactifs aux abonnés via leur téléviseur. Il préfigure les services en ligne modernes.', 'La Révolution Numérique : De l''Ordinateur Personnel au Smartphone (1975-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.394146+00', NULL, NULL, NULL, ''),
	(1391, 'Première diffusion de l''émission ''Popi'' à Télé-Québec', 1972, false, NULL, 'Lancement de l''émission jeunesse ''Popi'', qui deviendra un symbole de la télévision éducative québécoise. Elle contribue à la formation d''une identité culturelle chez les jeunes téléspectateurs.', 'L''Histoire des Jeux Olympiques Modernes : De la Renaissance à la Mondialisation (1896-2012)', '', 'PENDING', '', '2026-03-04 07:23:47.394146+00', NULL, NULL, NULL, ''),
	(1392, 'Adhésion de l''Allemagne au Conseil des États de la mer Baltique (CBSS)', 1992, false, NULL, 'L''Allemagne rejoint le CBSS, une organisation intergouvernementale créée pour renforcer la coopération régionale après la fin de la Guerre Froide, reflétant un nouvel engagement dans la région baltique.', 'L''Histoire des Jeux Olympiques Modernes : De la Renaissance à la Mondialisation (1896-2012)', '', 'PENDING', '', '2026-03-04 07:23:47.394146+00', NULL, NULL, NULL, ''),
	(1393, 'Institution de l''Amirauté de Dunkerque', 1662, false, NULL, 'Création de l''Amirauté de Dunkerque, un tribunal maritime chargé de juger les affaires de prises maritimes et de corsaires. Cette institution renforce le contrôle de l''État sur la guerre de course.', 'L''âge d''or de la piraterie dans les Caraïbes : de la flibuste aux grandes figures (1650-1730)', '', 'PENDING', '', '2026-03-04 07:23:47.394146+00', NULL, NULL, NULL, ''),
	(1394, 'Début du mandat de Benjamin Hornigold comme pirate (Nassau)', 1713, false, NULL, 'Benjamin Hornigold, initialement corsaire, commence à opérer comme pirate depuis Nassau, devenant l''un des pirates les plus influents de l''époque. Il jouera un rôle majeur dans l''établissement de la ''République Pirate''.', 'L''âge d''or de la piraterie dans les Caraïbes : de la flibuste aux grandes figures (1650-1730)', '', 'PENDING', '', '2026-03-04 07:23:47.394146+00', NULL, NULL, NULL, ''),
	(1395, 'Naufrage du ''Fiery Dragon'' près de Sainte-Marie', 1695, false, NULL, 'Le navire pirate anglais ''Fiery Dragon'', commandé par le capitaine Edward Coates, fait naufrage près de l''île de Sainte-Marie. L''épave et les survivants contribuent à renforcer la présence pirate sur l''île, qui devient un important repaire.', 'L''âge d''or de la piraterie dans les Caraïbes : de la flibuste aux grandes figures (1650-1730)', '', 'PENDING', '', '2026-03-04 07:23:47.394146+00', NULL, NULL, NULL, ''),
	(1396, 'Construction du caravansérail de Rabbath-Moab', 106, false, NULL, 'Sous l''administration romaine, le caravansérail de Rabbath-Moab (actuelle Jordanie) est construit. Il sert de point de repos et d''échange pour les caravanes empruntant la route commerciale de l''encens et d''autres marchandises précieuses.', 'La Route de la Soie : Échanges, Découvertes et Empires (1er siècle - 14ème siècle)', '', 'PENDING', '', '2026-03-04 07:23:47.394146+00', NULL, NULL, NULL, ''),
	(1397, 'Première mention écrite du poivre dans un document romain', 400, false, NULL, 'Le poivre, épice précieuse importée d''Inde, est mentionné pour la première fois dans un document romain. Cela témoigne de l''intensification des échanges commerciaux avec l''Orient et de la demande croissante pour les produits exotiques.', 'La Route de la Soie : Échanges, Découvertes et Empires (1er siècle - 14ème siècle)', '', 'PENDING', '', '2026-03-04 07:23:47.394146+00', NULL, NULL, NULL, ''),
	(1398, 'Pèlerinage de Knut le Grand à Rome pour assister au couronnement de Conrad II', 1027, false, NULL, 'Knut entreprend un pèlerinage à Rome pour assister au couronnement de Conrad II comme empereur du Saint-Empire romain germanique. Ce voyage renforce son prestige et ses alliances politiques en Europe.', 'L''expansion Viking : raids, explorations et royaumes (793-1066)', '', 'PENDING', '', '2026-03-04 07:23:47.394146+00', NULL, NULL, NULL, ''),
	(1399, 'Frappe de la première monnaie à l''effigie de Knut le Grand à Dublin', 1030, false, NULL, 'Sous l''autorité de Knut, des pièces de monnaie sont frappées à Dublin portant son effigie, témoignant de son influence et de son contrôle sur des parties de l''Irlande. Ces pièces facilitent le commerce et affirment son pouvoir.', 'L''expansion Viking : raids, explorations et royaumes (793-1066)', '', 'PENDING', '', '2026-03-04 07:23:47.394146+00', NULL, NULL, NULL, ''),
	(1400, 'Première ascension du Mont Logan par une équipe canadienne', 1925, false, NULL, 'Le 23 juin 1925, une équipe canadienne dirigée par Albert H. MacCarthy réussit la première ascension documentée du Mont Logan, le plus haut sommet du Canada.', 'La Conquête du Mont Everest : De la Première Tentative à l''Ascension Féminine (1921-1975)', '', 'PENDING', '', '2026-03-04 07:23:47.394146+00', NULL, NULL, NULL, ''),
	(1401, 'Introduction du premier robot industriel (Unimate)', 1961, false, NULL, 'General Motors installe le premier robot industriel, Unimate, sur une chaîne de montage à Trenton, New Jersey. Cette installation marque le début de l''automatisation industrielle et de l''utilisation de robots dans la production de masse.', 'La Conquête du Mont Everest : De la Première Tentative à l''Ascension Féminine (1921-1975)', '', 'PENDING', '', '2026-03-04 07:23:47.394146+00', NULL, NULL, NULL, ''),
	(1402, '22 septembre 1919 : Naissance de Junko Tabei à Miharu, Fukushima, Japon', 1919, false, NULL, 'Junko Tabei, née Junko Ishibashi, est une alpiniste japonaise connue pour être la première femme à avoir atteint le sommet de l''Everest. Elle a également gravi les plus hauts sommets de chaque continent.', 'La Conquête du Mont Everest : De la Première Tentative à l''Ascension Féminine (1921-1975)', '', 'PENDING', '', '2026-03-04 07:23:47.394146+00', NULL, NULL, NULL, ''),
	(1403, 'Début du règne de l''empereur Xuanzong', 712, false, NULL, 'L''empereur Xuanzong monte sur le trône, marquant le début d''une période considérée comme l''âge d''or de la dynastie Tang, caractérisée par la prospérité économique et l''épanouissement culturel.', 'Les Dynasties Chinoises : Un Millénaire de Transformations Impériales (618-1644)', '', 'PENDING', '', '2026-03-04 07:23:47.394146+00', NULL, NULL, NULL, ''),
	(1404, 'Publication du "Yuhai" par Wang Yinglin', 1267, false, NULL, 'Wang Yinglin publie le "Yuhai", une vaste encyclopédie compilant des informations de diverses sources imprimées. Cette publication illustre l''utilisation de l''imprimerie pour la diffusion du savoir encyclopédique.', 'Les Dynasties Chinoises : Un Millénaire de Transformations Impériales (618-1644)', '', 'PENDING', '', '2026-03-04 07:23:47.394146+00', NULL, NULL, NULL, ''),
	(1405, 'Impression du "Zizhi Tongjian" par Sima Guang', 1084, false, NULL, 'Sima Guang supervise l''impression du "Zizhi Tongjian", une chronique historique monumentale. La large diffusion de cet ouvrage renforce l''importance de l''imprimerie dans la préservation et la diffusion de l''histoire.', 'Les Dynasties Chinoises : Un Millénaire de Transformations Impériales (618-1644)', '', 'PENDING', '', '2026-03-04 07:23:47.394146+00', NULL, NULL, NULL, ''),
	(1406, 'Création du Bureau de l''Imprimerie (Shuji Wu) sous le règne de l''empereur Huizong', 1102, false, NULL, 'L''empereur Huizong établit le Bureau de l''Imprimerie (Shuji Wu), une institution gouvernementale dédiée à la production de livres imprimés. Cette initiative étatique témoigne de l''importance accordée à l''imprimerie par le gouvernement Song.', 'Les Dynasties Chinoises : Un Millénaire de Transformations Impériales (618-1644)', '', 'PENDING', '', '2026-03-04 07:23:47.394146+00', NULL, NULL, NULL, ''),
	(1407, 'Début du règne de l''empereur Yongle', 1402, false, NULL, 'Zhu Di usurpe le trône et commence son règne sous le nom d''empereur Yongle, marquant une période d''expansion et de consolidation du pouvoir Ming. Il déplace la capitale à Pékin.', 'Les Dynasties Chinoises : Un Millénaire de Transformations Impériales (618-1644)', '', 'PENDING', '', '2026-03-04 07:23:47.394146+00', NULL, NULL, NULL, ''),
	(1408, 'Établissement du Grand Secrétariat', 1415, false, NULL, 'L''empereur Yongle institutionnalise le Grand Secrétariat (Neige Ge), un organe consultatif composé de hauts fonctionnaires qui assistent l''empereur dans la prise de décisions et la gestion des affaires de l''État.', 'Les Dynasties Chinoises : Un Millénaire de Transformations Impériales (618-1644)', '', 'PENDING', '', '2026-03-04 07:23:47.394146+00', NULL, NULL, NULL, ''),
	(1409, 'Inauguration du Grand Temple (Templo Mayor) dédié à Huitzilopochtli et Tlaloc à Tenochtitlan', 1454, false, NULL, 'Moctezuma I supervise l''agrandissement et la redédicace du Templo Mayor, le principal temple de Tenochtitlan, dédié aux dieux Huitzilopochtli (guerre) et Tlaloc (pluie). Cette inauguration marque l''importance religieuse et politique croissante de Tenochtitlan.', 'L''Empire Aztèque : Fondations, Conquêtes et Chute (1325-1521)', '', 'PENDING', '', '2026-03-04 07:23:47.394146+00', NULL, NULL, NULL, ''),
	(1410, 'Consécration de la quatrième étape du Templo Mayor par Tlacaelel', 1428, false, NULL, 'Tlacaelel, conseiller influent, supervise la consécration d''une phase importante de l''expansion du Templo Mayor. Cette étape reflète la consolidation du pouvoir aztèque et l''importance croissante des sacrifices humains.', 'L''Empire Aztèque : Fondations, Conquêtes et Chute (1325-1521)', '', 'PENDING', '', '2026-03-04 07:23:47.394146+00', NULL, NULL, NULL, ''),
	(1411, 'Grande cérémonie de ré-inauguration du Templo Mayor sous Tizoc', 1487, false, NULL, 'Tizoc organise une cérémonie massive pour ré-inaugurer le Templo Mayor, impliquant des milliers de sacrifices humains. Cet événement marque un apogée de la pratique sacrificielle dans la religion aztèque.', 'L''Empire Aztèque : Fondations, Conquêtes et Chute (1325-1521)', '', 'PENDING', '', '2026-03-04 07:23:47.394146+00', NULL, NULL, NULL, ''),
	(1412, 'Première utilisation du Technicolor bichrome dans le film The Toll of the Sea', 1922, false, NULL, 'Première utilisation commerciale réussie du procédé Technicolor bichrome (couleur à deux bandes) dans le film ''The Toll of the Sea'', réalisé par Chester M. Franklin.', 'L''Âge d''Or d''Hollywood : Naissance du cinéma moderne et de ses stars (1915-1960)', '', 'PENDING', '', '2026-03-04 07:23:47.394146+00', NULL, NULL, NULL, ''),
	(1413, 'Création de la MPPDA (Motion Picture Producers and Distributors of America)', 1922, false, NULL, 'La Motion Picture Producers and Distributors of America (MPPDA), future Motion Picture Association of America (MPAA), est créée pour améliorer l''image de l''industrie cinématographique.', 'L''Âge d''Or d''Hollywood : Naissance du cinéma moderne et de ses stars (1915-1960)', '', 'PENDING', '', '2026-03-04 07:23:47.406143+00', NULL, NULL, NULL, ''),
	(1414, 'Sortie du film "Morocco" avec la première apparition de Gary Cooper et Marlene Dietrich', 1930, false, NULL, 'Ce film marque le début de la collaboration fructueuse entre Marlene Dietrich et le réalisateur Josef von Sternberg. Il lance la carrière de Gary Cooper.', 'L''Âge d''Or d''Hollywood : Naissance du cinéma moderne et de ses stars (1915-1960)', '', 'PENDING', '', '2026-03-04 07:23:47.406143+00', NULL, NULL, NULL, ''),
	(1415, 'Sortie du film "La Chevauchée fantastique"', 1939, false, NULL, 'Première du western américain "Stagecoach", réalisé par John Ford, avec John Wayne. Le film est considéré comme un classique du genre et relance la carrière de John Wayne.', 'L''Âge d''Or d''Hollywood : Naissance du cinéma moderne et de ses stars (1915-1960)', '', 'PENDING', '', '2026-03-04 07:23:47.406143+00', NULL, NULL, NULL, ''),
	(1416, 'Sortie du film "Chantons sous la pluie"', 1952, false, NULL, 'Première du film musical américain "Singin'' in the Rain", réalisé par Stanley Donen et Gene Kelly, avec Gene Kelly, Donald O''Connor et Debbie Reynolds. Le film est une satire de la transition du cinéma muet au cinéma parlant.', 'L''Âge d''Or d''Hollywood : Naissance du cinéma moderne et de ses stars (1915-1960)', '', 'PENDING', '', '2026-03-04 07:23:47.406143+00', NULL, NULL, NULL, ''),
	(1417, 'Sortie du film ''Le Voleur de bicyclette'' de Vittorio De Sica', 1948, false, NULL, 'Le film néoréaliste italien ''Le Voleur de bicyclette'' (Ladri di biciclette) sort en Italie.
Produit indépendamment, il remporte un succès international et influence le cinéma mondial.', 'L''Âge d''Or d''Hollywood : Naissance du cinéma moderne et de ses stars (1915-1960)', '', 'PENDING', '', '2026-03-04 07:23:47.406143+00', NULL, NULL, NULL, ''),
	(1419, 'Nicolas de Cues devient cardinal', 1448, false, NULL, 'Nicolas de Cues, éminent philosophe et théologien humaniste, est élevé au rang de cardinal par le pape Nicolas V. Il jouera un rôle important dans la vie intellectuelle de l''époque.', 'La Renaissance Italienne : Art, Politique et Science (1300-1600)', '', 'PENDING', '', '2026-03-04 07:23:47.406143+00', NULL, NULL, NULL, ''),
	(1420, 'Présentation du polyptyque de Pise par Masaccio', 1426, false, NULL, 'Masaccio livre le polyptyque de Pise, une œuvre majeure qui démontre sa maîtrise de la perspective et de la composition. L''œuvre est ensuite démembrée et dispersée.', 'La Renaissance Italienne : Art, Politique et Science (1300-1600)', '', 'PENDING', '', '2026-03-04 07:23:47.406143+00', NULL, NULL, NULL, ''),
	(1421, 'Achèvement de la Chapelle des Mages au Palais Medici-Riccardi', 1459, false, NULL, 'Benozzo Gozzoli achève les fresques de la Chapelle des Mages, illustrant la splendeur de la cour des Médicis. L''œuvre témoigne du mécénat artistique de la famille et de son rôle central dans la vie florentine.', 'La Renaissance Italienne : Art, Politique et Science (1300-1600)', '', 'PENDING', '', '2026-03-04 07:23:47.406143+00', NULL, NULL, NULL, ''),
	(1422, 'Escarmouche de Jumonville Glen', 1754, false, NULL, 'Une escarmouche entre les troupes de Virginie dirigées par George Washington et un détachement français à Jumonville Glen marque le début de la Guerre de Sept Ans en Amérique du Nord.', 'La Colonisation de l''Amérique du Nord : Exploration, Conflits et Fondations (1492-1776)', '', 'PENDING', '', '2026-03-04 07:23:47.406143+00', NULL, NULL, NULL, ''),
	(1423, 'Inauguration du règne de Yax Nuun Ahiin Ier à Tikal', 379, false, NULL, 'Yax Nuun Ahiin Ier, venu de Teotihuacan, monte sur le trône de Tikal, marquant une influence étrangère significative. Cet événement consolide le pouvoir de Tikal et son rôle central dans les basses terres mayas.', 'L''Effondrement des Civilisations Mésoaméricaines : Mayas, Aztèques et Incas (250-1697)', '', 'PENDING', '', '2026-03-04 07:23:47.406143+00', NULL, NULL, NULL, ''),
	(1424, 'Dédicace du Hieroglyphic Stairway de Copán', 756, false, NULL, 'Le Hieroglyphic Stairway, un monument majeur de Copán, est dédié. Il contient le plus long texte hiéroglyphique maya connu, retraçant l''histoire de la cité et de ses dirigeants.', 'L''Effondrement des Civilisations Mésoaméricaines : Mayas, Aztèques et Incas (250-1697)', '', 'PENDING', '', '2026-03-04 07:23:47.406143+00', NULL, NULL, NULL, ''),
	(1425, 'Début du règne de Ukit Took'' à Copán', 435, false, NULL, 'Ukit Took'' accède au pouvoir à Copán, marquant le début d''une dynastie importante. Son règne contribue à l''essor de Copán en tant que centre politique et culturel majeur.', 'L''Effondrement des Civilisations Mésoaméricaines : Mayas, Aztèques et Incas (250-1697)', '', 'PENDING', '', '2026-03-04 07:23:47.406143+00', NULL, NULL, NULL, ''),
	(1426, 'Mention de la ''guerre stellaire'' sur le monument 6 de Tortuguero', 695, false, NULL, 'Le monument 6 de Tortuguero fait référence à une ''guerre stellaire'', un événement cosmique ou astrologique interprété comme ayant une influence sur les affaires terrestres. Cette date est associée à une défaite de Calakmul face à Tikal.', 'L''Effondrement des Civilisations Mésoaméricaines : Mayas, Aztèques et Incas (250-1697)', '', 'PENDING', '', '2026-03-04 07:23:47.406143+00', NULL, NULL, NULL, ''),
	(1427, 'Fin du règne de Waxaklajun Ub''aah K''awiil à Copán', 738, false, NULL, 'Waxaklajun Ub''aah K''awiil, un puissant roi de Copán, est capturé et exécuté par K''ak'' Tiliw Chan Yopaat de Quirigua. Cet événement marque un tournant dans l''histoire de Copán et de ses relations avec Quirigua.', 'L''Effondrement des Civilisations Mésoaméricaines : Mayas, Aztèques et Incas (250-1697)', '', 'PENDING', '', '2026-03-04 07:23:47.406143+00', NULL, NULL, NULL, ''),
	(1428, 'Début du règne de Ce Acatl Topiltzin Quetzalcoatl à Tula', 923, false, NULL, 'Ce Acatl Topiltzin Quetzalcoatl, figure légendaire, prend le pouvoir à Tula. Son règne est associé à une période de prospérité et d''influence culturelle toltèque.', 'L''Effondrement des Civilisations Mésoaméricaines : Mayas, Aztèques et Incas (250-1697)', '', 'PENDING', '', '2026-03-04 07:23:47.406143+00', NULL, NULL, NULL, ''),
	(1429, 'Destruction partielle de Tula par des incendies', 1150, false, NULL, 'Des incendies ravagent Tula, contribuant au déclin de la ville et de l''empire toltèque. Les causes exactes de ces incendies restent incertaines.', 'L''Effondrement des Civilisations Mésoaméricaines : Mayas, Aztèques et Incas (250-1697)', '', 'PENDING', '', '2026-03-04 07:23:47.406143+00', NULL, NULL, NULL, ''),
	(1430, 'Abandon progressif de Tula', 1175, false, NULL, 'Le déclin de l''influence toltèque entraîne l''abandon progressif de Tula par sa population. Les raisons incluent des conflits internes et des pressions externes.', 'L''Effondrement des Civilisations Mésoaméricaines : Mayas, Aztèques et Incas (250-1697)', '', 'PENDING', '', '2026-03-04 07:23:47.406143+00', NULL, NULL, NULL, ''),
	(1432, 'Création du Bureau de la Musique (Jiaofang) à Chang''an', 714, false, NULL, 'L''empereur Xuanzong fonde le Jiaofang, une académie impériale de musique et de danse. Cette institution centralise et promeut les arts, contribuant à l''effervescence culturelle de la capitale et au rayonnement de la dynastie Tang le long de la Route de la Soie.', 'La Route de la Soie : Échanges Commerciaux, Culturels et Religieux (130 AEC - 1453)', '', 'PENDING', '', '2026-03-04 07:23:47.406143+00', NULL, NULL, NULL, ''),
	(1433, 'Construction de l''observatoire de Maragha', 1259, false, NULL, 'Hulagu Khan ordonne la construction de l''observatoire de Maragha (actuel Iran), sous la direction de Nasir al-Din al-Tusi. Il devient un centre important pour l''astronomie et les mathématiques, attirant des savants de diverses cultures.', 'La Route de la Soie : Échanges Commerciaux, Culturels et Religieux (130 AEC - 1453)', '', 'PENDING', '', '2026-03-04 07:23:47.406143+00', NULL, NULL, NULL, ''),
	(1434, 'Fin des expéditions de Zheng He sous la dynastie Ming', 1433, false, NULL, 'La dynastie Ming met fin aux voyages d''exploration de Zheng He, marquant un tournant dans la politique étrangère chinoise et réduisant l''influence chinoise sur les routes maritimes et terrestres, y compris la Route de la Soie. Cette décision favorise un repli sur soi de la Chine.', 'La Route de la Soie : Échanges Commerciaux, Culturels et Religieux (130 AEC - 1453)', '', 'PENDING', '', '2026-03-04 07:23:47.406143+00', NULL, NULL, NULL, ''),
	(1435, 'Fondation du label Bronze Records par Gerry Bron', 1971, false, NULL, 'Le label Bronze Records, fondé par Gerry Bron, devient un acteur majeur dans la promotion du hard rock et du heavy metal britannique. Il signe des groupes comme Motörhead et Uriah Heep.', 'L''Histoire du Rock ''n'' Roll : Des origines au phénomène mondial (1950-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.406143+00', NULL, NULL, NULL, ''),
	(1437, 'Sortie de l''album "The Joshua Tree" de U2', 1987, false, NULL, 'L''album propulse U2 au rang de groupe de rock mondialement reconnu. Il explore des thèmes américains et consolide la diversification du rock vers des sonorités plus introspectives et engagées.', 'L''Histoire du Rock ''n'' Roll : Des origines au phénomène mondial (1950-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.406143+00', NULL, NULL, NULL, ''),
	(1438, 'Premier festival Lollapalooza à Phoenix, Arizona', 1991, false, NULL, 'Lollapalooza devient un symbole de la culture alternative et grunge. Il contribue à populariser des groupes comme Pearl Jam et Soundgarden, marquant une étape importante dans la diversification du rock.', 'L''Histoire du Rock ''n'' Roll : Des origines au phénomène mondial (1950-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.406143+00', NULL, NULL, NULL, ''),
	(1439, 'Concert gratuit de The Rolling Stones à la plage de Copacabana (Rio de Janeiro)', 2006, false, NULL, 'Le concert attire plus d''un million de personnes et témoigne de la portée mondiale du rock. Il illustre la capacité des groupes de rock établis à attirer des publics massifs à travers le monde.', 'L''Histoire du Rock ''n'' Roll : Des origines au phénomène mondial (1950-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.406143+00', NULL, NULL, NULL, ''),
	(1440, 'Lancement d''Amazon Marketplace', 2000, false, NULL, 'Amazon lance Amazon Marketplace en novembre 2000, permettant à des vendeurs tiers de proposer leurs produits sur la plateforme. Cela élargit considérablement l''offre d''Amazon.', 'L''Ère Numérique : De l''Ordinateur Personnel à Internet et aux Réseaux Sociaux (1975-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.406143+00', NULL, NULL, NULL, ''),
	(1441, 'Inauguration du Musée des Cosmonautes (Moscou)', 1981, false, NULL, 'Le Musée des Cosmonautes est inauguré à Moscou pour commémorer les réalisations de l''exploration spatiale soviétique. Il abrite une vaste collection d''artefacts liés aux vols spatiaux.', 'La Conquête de l''Espace : De Spoutnik à la Station Spatiale Internationale (1957-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.406143+00', NULL, NULL, NULL, ''),
	(1442, 'Création du programme TOP du CIO (The Olympic Partner Programme)', 1985, false, NULL, 'Le CIO lance le programme TOP, un programme de sponsoring mondial exclusif offrant des droits marketing exclusifs aux entreprises partenaires. Ce programme vise à centraliser et à maximiser les revenus de sponsoring.', 'Les Jeux Olympiques Modernes : De la Renaissance à l''Ère Globale (1896-2012)', '', 'PENDING', '', '2026-03-04 07:23:47.406143+00', NULL, NULL, NULL, ''),
	(1443, 'Première représentation de l''opéra ''Almira'' de Haendel à Hambourg', 1705, false, NULL, 'Le premier opéra de Haendel, ''Almira'', est joué pour la première fois au Theater am Gänsemarkt à Hambourg. Cet événement marque le début de sa carrière lyrique.', 'L''Histoire de la Musique Classique : Des Origines à la Révolution Romantique (1600-1850)', '', 'PENDING', '', '2026-03-04 07:23:47.406143+00', NULL, NULL, NULL, ''),
	(1444, 'Publication des ''Variations Goldberg'' de Jean-Sébastien Bach', 1741, false, NULL, 'Les ''Variations Goldberg'', un chef-d''œuvre de la musique pour clavier, sont publiées. Elles sont dédiées au comte Hermann Karl von Keyserlingk.', 'L''Histoire de la Musique Classique : Des Origines à la Révolution Romantique (1600-1850)', '', 'PENDING', '', '2026-03-04 07:23:47.406143+00', NULL, NULL, NULL, ''),
	(1445, 'Première représentation de ''Hippolyte et Aricie'' de Rameau à l''Académie Royale de Musique', 1733, false, NULL, 'L''opéra ''Hippolyte et Aricie'' de Jean-Philippe Rameau est joué pour la première fois à Paris. Il marque une étape importante dans le développement de l''opéra baroque français.', 'L''Histoire de la Musique Classique : Des Origines à la Révolution Romantique (1600-1850)', '', 'PENDING', '', '2026-03-04 07:23:47.406143+00', NULL, NULL, NULL, ''),
	(1446, 'Inauguration du Teatro Regio de Turin avec l''opéra ''Arsace'' de Francesco Feo', 1740, false, NULL, 'Le Teatro Regio de Turin, l''un des plus importants opéras d''Italie, est inauguré. L''événement souligne l''importance de la musique baroque dans la vie culturelle de l''époque.', 'L''Histoire de la Musique Classique : Des Origines à la Révolution Romantique (1600-1850)', '', 'PENDING', '', '2026-03-04 07:23:47.406143+00', NULL, NULL, NULL, ''),
	(1447, 'Découverte du trou dans la couche d''ozone au-dessus de l''Antarctique par l''équipe de Joe Farman', 1985, false, NULL, 'Une équipe de scientifiques britanniques dirigée par Joe Farman publie un article dans Nature révélant un amincissement important de la couche d''ozone au-dessus de l''Antarctique. Cette découverte alerte la communauté internationale sur les dangers des chlorofluorocarbures (CFC).', 'La Conquête de l''Antarctique : De l''exploration à la science (1820-2000)', '', 'PENDING', '', '2026-03-04 07:23:47.406143+00', NULL, NULL, NULL, ''),
	(1448, 'Signature de la Convention de Vienne pour la protection de la couche d''ozone', 1985, false, NULL, 'La Convention de Vienne établit un cadre pour les efforts internationaux de protection de la couche d''ozone. Elle sert de base aux futurs accords plus contraignants.', 'La Conquête de l''Antarctique : De l''exploration à la science (1820-2000)', '', 'PENDING', '', '2026-03-04 07:23:47.406143+00', NULL, NULL, NULL, ''),
	(1449, 'Première révélation à Mahomet dans la grotte de Hira', 610, false, NULL, 'Selon la tradition islamique, l''ange Gabriel apparaît à Mahomet dans la grotte de Hira, marquant le début de sa prophétie. Cet événement est considéré comme le point de départ de l''Islam.', 'L''essor de l''Islam : De la révélation à l''âge d''or (610-1258)', '', 'PENDING', '', '2026-03-04 07:23:47.406143+00', NULL, NULL, NULL, ''),
	(1450, 'Début du prêche public de Mahomet à La Mecque', 613, false, NULL, 'Après une période de révélation privée, Mahomet commence à prêcher publiquement à La Mecque. Il appelle à l''abandon des idoles et à l''adoration d''un seul Dieu, Allah.', 'L''essor de l''Islam : De la révélation à l''âge d''or (610-1258)', '', 'PENDING', '', '2026-03-04 07:23:47.406143+00', NULL, NULL, NULL, ''),
	(1451, 'Entrée triomphale d''Ahmad ibn Buya à Bagdad', 945, false, NULL, 'Le chef Daylamite Ahmad ibn Buya prend le contrôle de Bagdad, marquant le début de l''influence Bouyide sur le califat abbasside. Le calife Al-Mustakfi est contraint de lui accorder le titre de Mu''izz al-Dawla.', 'L''essor de l''Islam : De la révélation à l''âge d''or (610-1258)', '', 'PENDING', '', '2026-03-04 07:23:47.406143+00', NULL, NULL, NULL, ''),
	(1452, 'Conquête de Sijilmasa par les Meknassa', 977, false, NULL, 'La ville de Sijilmasa, plaque tournante du commerce transsaharien, est prise par les Meknassa, une tribu berbère zénète. Cet événement marque un tournant dans le contrôle des routes commerciales de l''or.', 'L''Âge d''Or des Explorations Africaines : Du Commerce Transsaharien aux Empires Oubliés (7e siècle - 16e siècle)', '', 'PENDING', '', '2026-03-04 07:23:47.406143+00', NULL, NULL, NULL, ''),
	(1453, 'Al-Bakri décrit Koumbi Saleh, capitale de l''empire du Ghana', 1068, false, NULL, 'Le géographe Al-Bakri fournit une description détaillée de Koumbi Saleh, la capitale de l''empire du Ghana, dans son ''Livre des Routes et des Royaumes''. Il témoigne de sa richesse et de son rôle central dans le commerce de l''or.', 'L''Âge d''Or des Explorations Africaines : Du Commerce Transsaharien aux Empires Oubliés (7e siècle - 16e siècle)', '', 'PENDING', '', '2026-03-04 07:23:47.406143+00', NULL, NULL, NULL, ''),
	(1454, 'Les Almoravides s''emparent d''Aoudaghost', 1054, false, NULL, 'La ville d''Aoudaghost, un important centre commercial sur la route de l''or, est conquise par les Almoravides. Cette prise de contrôle renforce leur influence sur le commerce transsaharien.', 'L''Âge d''Or des Explorations Africaines : Du Commerce Transsaharien aux Empires Oubliés (7e siècle - 16e siècle)', '', 'PENDING', '', '2026-03-04 07:23:47.406143+00', NULL, NULL, NULL, ''),
	(1525, 'Johan Cruyff reçoit le Ballon d''Or pour la première fois', 1971, false, NULL, 'Cruyff est récompensé pour ses performances exceptionnelles avec l''Ajax Amsterdam. Il incarne le ''football total'' et devient une icône mondiale.', 'L''Histoire du Football : De ses racines anglaises à la Coupe du Monde moderne (1863-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.43055+00', NULL, NULL, NULL, ''),
	(1455, 'Construction de la Grande Mosquée de Djenné (version en banco)', 1240, false, NULL, 'La Grande Mosquée de Djenné, un important centre d''apprentissage islamique et un symbole de la ville, est construite en banco (briques de terre séchées au soleil). Elle témoigne de la prospérité de la région grâce au commerce.', 'L''Âge d''Or des Explorations Africaines : Du Commerce Transsaharien aux Empires Oubliés (7e siècle - 16e siècle)', '', 'PENDING', '', '2026-03-04 07:23:47.406143+00', NULL, NULL, NULL, ''),
	(1456, 'Début du règne de Kaya Maghan Sisse', 1062, false, NULL, 'Kaya Maghan Sisse accède au trône de l''Empire du Ghana. Son règne est marqué par des conflits avec les Almoravides et des pressions internes qui affaiblissent l''empire.', 'L''Âge d''Or des Explorations Africaines : Du Commerce Transsaharien aux Empires Oubliés (7e siècle - 16e siècle)', '', 'PENDING', '', '2026-03-04 07:23:47.406143+00', NULL, NULL, NULL, ''),
	(1457, 'Soulèvement des Sossos contre la domination ghanéenne', 1180, false, NULL, 'Les Sossos, un peuple vassal de l''Empire du Ghana, se révoltent contre la domination ghanéenne. Cette rébellion contribue à la fragmentation politique et à l''affaiblissement de l''empire.', 'L''Âge d''Or des Explorations Africaines : Du Commerce Transsaharien aux Empires Oubliés (7e siècle - 16e siècle)', '', 'PENDING', '', '2026-03-04 07:23:47.406143+00', NULL, NULL, NULL, ''),
	(1458, 'Proclamation de la Charte du Manden à Kouroukan Fouga', 1236, false, NULL, 'Après sa victoire, Soundiata Keita convoque une grande assemblée à Kouroukan Fouga. La Charte du Manden, une constitution orale, est proclamée, établissant les principes de gouvernance et les droits sociaux dans l''Empire du Mali.', 'L''Âge d''Or des Explorations Africaines : Du Commerce Transsaharien aux Empires Oubliés (7e siècle - 16e siècle)', '', 'PENDING', '', '2026-03-04 07:23:47.406143+00', NULL, NULL, NULL, ''),
	(1459, 'Construction de la Grande Mosquée de Djenné (première version)', 1325, false, NULL, 'Mansa Moussa ordonne la construction de la première Grande Mosquée de Djenné, un symbole architectural majeur de l''Empire du Mali et un centre d''apprentissage islamique.', 'L''Âge d''Or des Explorations Africaines : Du Commerce Transsaharien aux Empires Oubliés (7e siècle - 16e siècle)', '', 'PENDING', '', '2026-03-04 07:23:47.406143+00', NULL, NULL, NULL, ''),
	(1460, 'Sac de Gao par les Mossi', 1433, false, NULL, 'Les Mossi, venus du sud, pillent et occupent la ville de Gao, un important centre commercial et administratif de l''Empire du Mali. Cet événement marque le début du déclin de l''influence malienne dans la région.', 'L''Âge d''Or des Explorations Africaines : Du Commerce Transsaharien aux Empires Oubliés (7e siècle - 16e siècle)', '', 'PENDING', '', '2026-03-04 07:23:47.406143+00', NULL, NULL, NULL, ''),
	(1461, 'Visite d''Ibn Battuta à Mogadiscio, en Afrique de l''Est', 1331, false, NULL, 'Ibn Battuta visite Mogadiscio, une ville portuaire prospère sur la côte est-africaine. Il décrit la culture et les coutumes locales, offrant un aperçu précieux de la vie dans cette région à cette époque.', 'L''Âge d''Or des Explorations Africaines : Du Commerce Transsaharien aux Empires Oubliés (7e siècle - 16e siècle)', '', 'PENDING', '', '2026-03-04 07:23:47.406143+00', NULL, NULL, NULL, ''),
	(1462, 'Ibn Battuta atteint le sultanat de Kilwa', 1331, false, NULL, 'Ibn Battuta visite Kilwa, un important centre commercial sur la côte swahilie. Il est impressionné par la richesse et l''architecture de la ville, témoignant de sa puissance commerciale.', 'L''Âge d''Or des Explorations Africaines : Du Commerce Transsaharien aux Empires Oubliés (7e siècle - 16e siècle)', '', 'PENDING', '', '2026-03-04 07:23:47.406143+00', NULL, NULL, NULL, ''),
	(1463, 'Ibn Battuta est nommé juge (qadi) aux Maldives', 1341, false, NULL, 'Après avoir voyagé en Inde, Ibn Battuta est nommé juge (qadi) aux Maldives. Il y passe plusieurs années à appliquer la loi islamique et à observer les coutumes locales.', 'L''Âge d''Or des Explorations Africaines : Du Commerce Transsaharien aux Empires Oubliés (7e siècle - 16e siècle)', '', 'PENDING', '', '2026-03-04 07:23:47.406143+00', NULL, NULL, NULL, ''),
	(1464, 'Victoire de Helsal à la Sydney-Hobart Yacht Race', 1973, false, NULL, 'Helsal remporte la course en un temps record. C''est une victoire surprise.', 'L''Âge d''or de la voile : Courses et records autour du monde (1851-1983)', '', 'PENDING', '', '2026-03-04 07:23:47.406143+00', NULL, NULL, NULL, ''),
	(1465, 'Sayula II remporte la première Whitbread Round the World Race', 1974, false, NULL, 'Le voilier mexicain Sayula II, skippé par Ramón Carlín, entre dans l''histoire en remportant la première édition de la Whitbread. L''équipage amateur surprend le monde de la voile en complétant le tour du monde avec succès.', 'L''Âge d''or de la voile : Courses et records autour du monde (1851-1983)', '', 'PENDING', '', '2026-03-04 07:23:47.417799+00', NULL, NULL, NULL, ''),
	(1466, 'Construction du château d''Osaka par Ishiyama Hongan-ji', 1496, false, NULL, 'Le temple fortifié d''Ishiyama Hongan-ji est érigé à Osaka, devenant un important centre de pouvoir. Il sera plus tard reconstruit par Toyotomi Hideyoshi.', 'L''ascension et la chute des royaumes combattants au Japon : samouraïs, shoguns et unification (1467-1615)', '', 'PENDING', '', '2026-03-04 07:23:47.417799+00', NULL, NULL, NULL, ''),
	(1467, 'Construction du château d''Azuchi ordonnée par Oda Nobunaga', 1576, false, NULL, 'Oda Nobunaga ordonne la construction du château d''Azuchi, un symbole de son pouvoir et de sa richesse. Le château devient un centre politique et culturel majeur, reflétant l''ascension de Nobunaga.', 'L''ascension et la chute des royaumes combattants au Japon : samouraïs, shoguns et unification (1467-1615)', '', 'PENDING', '', '2026-03-04 07:23:47.417799+00', NULL, NULL, NULL, ''),
	(1468, 'Introduction du thé au Japon par des moines bouddhistes (805)', 805, false, NULL, 'Des moines bouddhistes japonais, de retour de Chine, introduisent les premières graines et plants de thé au Japon. Cet événement marque le début de la culture du thé au Japon.', 'L''Histoire du Thé : De la Chine Impériale à la Culture Mondiale (2737 AEC - 1908)', '', 'PENDING', '', '2026-03-04 07:23:47.417799+00', NULL, NULL, NULL, ''),
	(1469, 'Fondation de la société Lipton (1890)', 1890, false, NULL, 'Thomas Lipton fonde la société Lipton, révolutionnant l''industrie du thé en le rendant accessible au grand public. Il est l''un des premiers à vendre le thé pré-emballé.', 'L''Histoire du Thé : De la Chine Impériale à la Culture Mondiale (2737 AEC - 1908)', '', 'PENDING', '', '2026-03-04 07:23:47.417799+00', NULL, NULL, NULL, ''),
	(1470, 'Début du règne de l''empereur Daizong, protecteur de Lu Yu', 762, false, NULL, 'L''empereur Daizong monte sur le trône de la dynastie Tang. Son intérêt pour le thé et son patronage envers Lu Yu contribuent à la diffusion du ''Cha Jing'' et de la culture du thé.', 'L''Histoire du Thé : De la Chine Impériale à la Culture Mondiale (2737 AEC - 1908)', '', 'PENDING', '', '2026-03-04 07:23:47.417799+00', NULL, NULL, NULL, ''),
	(1471, 'Lu Yu s''installe à Huzhou pour se consacrer à l''étude du thé', 764, false, NULL, 'Lu Yu choisit de vivre à Huzhou, région réputée pour son thé de qualité, afin de poursuivre ses recherches et son écriture sur le thé. Il y perfectionne ses connaissances et affine ses pratiques.', 'L''Histoire du Thé : De la Chine Impériale à la Culture Mondiale (2737 AEC - 1908)', '', 'PENDING', '', '2026-03-04 07:23:47.417799+00', NULL, NULL, NULL, ''),
	(1472, 'Recommandation impériale de consommer du thé pour la santé par l''empereur Saga', 815, false, NULL, 'L''empereur Saga encourage la culture et la consommation du thé au Japon après en avoir goûté lors d''un voyage. Il en vante les bienfaits pour la santé.', 'L''Histoire du Thé : De la Chine Impériale à la Culture Mondiale (2737 AEC - 1908)', '', 'PENDING', '', '2026-03-04 07:23:47.417799+00', NULL, NULL, NULL, ''),
	(1597, 'Introduction en bourse de Microsoft (NASDAQ : MSFT)', 1986, false, NULL, 'Microsoft entre en bourse, levant des millions de dollars et transformant Bill Gates et Paul Allen en milliardaires. L''action est cotée au NASDAQ sous le symbole MSFT.', '', '', 'PENDING', '', '2026-03-04 07:23:47.442367+00', NULL, NULL, NULL, ''),
	(1473, 'Publication du ''Kissa Yōjōki'' par le moine Eisai, promouvant les bienfaits du thé', 1211, false, NULL, 'Le moine Eisai écrit le ''Kissa Yōjōki'' (Comment rester en bonne santé en buvant du thé), un traité sur les bienfaits médicinaux du thé. Il popularise la consommation de thé vert.', 'L''Histoire du Thé : De la Chine Impériale à la Culture Mondiale (2737 AEC - 1908)', '', 'PENDING', '', '2026-03-04 07:23:47.417799+00', NULL, NULL, NULL, ''),
	(1474, 'Développement de la culture du thé en Caroline du Sud', 1880, false, NULL, 'La culture du thé en Caroline du Sud, bien que modeste, a contribué à l''intérêt pour le thé en général, y compris le thé glacé. Cette initiative a permis de promouvoir la consommation de thé cultivé localement.', 'L''Histoire du Thé : De la Chine Impériale à la Culture Mondiale (2737 AEC - 1908)', '', 'PENDING', '', '2026-03-04 07:23:47.417799+00', NULL, NULL, NULL, ''),
	(1475, 'Popularisation du thé glacé sucré dans le Sud des États-Unis', 1900, false, NULL, 'Le thé glacé sucré devient une boisson de base dans le Sud des États-Unis, souvent préparé en infusant le thé avec du sucre pendant le processus de brassage. Cette tradition culinaire renforce l''identité régionale du thé glacé.', 'L''Histoire du Thé : De la Chine Impériale à la Culture Mondiale (2737 AEC - 1908)', '', 'PENDING', '', '2026-03-04 07:23:47.417799+00', NULL, NULL, NULL, ''),
	(1476, 'Première description détaillée du Pankration dans les écrits de Philostrate', 220, false, NULL, 'Le sophiste grec Philostrate fournit une description détaillée du Pankration, un art martial combinant boxe et lutte, dans ses écrits. Il met en évidence la brutalité et l''efficacité de cette discipline.', 'L''Histoire des Arts Martiaux : De leurs origines aux compétitions modernes (du Ier siècle à nos jours)', '', 'PENDING', '', '2026-03-04 07:23:47.417799+00', NULL, NULL, NULL, ''),
	(1477, 'Fondation de l''Académie de gladiateurs (Ludus Magnus) par l''empereur Domitien à Rome', 80, false, NULL, 'L''empereur Domitien fonde le Ludus Magnus, la plus grande et la plus importante académie de gladiateurs de Rome. Cette institution jouera un rôle crucial dans la formation et l''entraînement des gladiateurs, dont les combats étaient une forme d''art martial populaire.', 'L''Histoire des Arts Martiaux : De leurs origines aux compétitions modernes (du Ier siècle à nos jours)', '', 'PENDING', '', '2026-03-04 07:23:47.417799+00', NULL, NULL, NULL, ''),
	(1478, 'Fondation du Kodokan par Jigoro Kano', 1882, false, NULL, 'Jigoro Kano fonde le Kodokan à Tokyo, marquant la naissance officielle du judo. Il y développe sa méthode d''éducation physique et morale.', 'L''Histoire des Arts Martiaux : De leurs origines aux compétitions modernes (du Ier siècle à nos jours)', '', 'PENDING', '', '2026-03-04 07:23:47.417799+00', NULL, NULL, NULL, ''),
	(1479, 'Première démonstration publique de karaté par Gichin Funakoshi à Tokyo', 1922, false, NULL, 'Gichin Funakoshi, considéré comme le père du karaté moderne, réalise la première démonstration publique de karaté d''Okinawa au Kodokan de Tokyo. Cet événement marque le début de la diffusion du karaté au Japon.', 'L''Histoire des Arts Martiaux : De leurs origines aux compétitions modernes (du Ier siècle à nos jours)', '', 'PENDING', '', '2026-03-04 07:23:47.417799+00', NULL, NULL, NULL, ''),
	(1480, 'Fondation de la Japan Karate Association (JKA)', 1949, false, NULL, 'La Japan Karate Association (JKA) est fondée pour promouvoir et standardiser le karaté à travers le Japon et le monde. Elle joue un rôle crucial dans le développement du karaté sportif et compétitif.', 'L''Histoire des Arts Martiaux : De leurs origines aux compétitions modernes (du Ier siècle à nos jours)', '', 'PENDING', '', '2026-03-04 07:23:47.417799+00', NULL, NULL, NULL, ''),
	(1481, 'Introduction des "Unified Rules of Mixed Martial Arts" au New Jersey', 2000, false, NULL, 'La Commission Athlétique de l''État du New Jersey adopte un ensemble standardisé de règles pour le MMA, connues sous le nom de "Unified Rules". Ces règles contribuent à la légitimation et à la réglementation du sport.', 'L''Histoire des Arts Martiaux : De leurs origines aux compétitions modernes (du Ier siècle à nos jours)', '', 'PENDING', '', '2026-03-04 07:23:47.417799+00', NULL, NULL, NULL, ''),
	(1482, 'Début du règne de Güyük Khan en tant que Grand Khan de l''Empire Mongol', 1246, false, NULL, 'Güyük, fils d''Ögödei, est intronisé Grand Khan après une période d''instabilité politique. Son règne, bien que bref, est marqué par des tensions internes et des défis à l''autorité centrale.', 'L''Empire Mongol : Conquêtes, Diplomatie et Échanges Culturels (1206-1368)', '', 'PENDING', '', '2026-03-04 07:23:47.417799+00', NULL, NULL, NULL, ''),
	(1483, 'Inauguration du Grand Canal restauré sous la dynastie Yuan', 1293, false, NULL, 'Après des travaux de restauration et d''extension, le Grand Canal est rouvert, facilitant le transport de marchandises et de personnes entre le nord et le sud de la Chine.', 'L''Empire Mongol : Conquêtes, Diplomatie et Échanges Culturels (1206-1368)', '', 'PENDING', '', '2026-03-04 07:23:47.417799+00', NULL, NULL, NULL, ''),
	(1484, 'Publication du "Nong Shu" (Traité d''agriculture) de Wang Zhen', 1313, false, NULL, 'Wang Zhen publie le "Nong Shu", un traité d''agriculture qui compile les connaissances agricoles de l''époque et introduit de nouvelles techniques, notamment l''utilisation de machines agricoles.', 'L''Empire Mongol : Conquêtes, Diplomatie et Échanges Culturels (1206-1368)', '', 'PENDING', '', '2026-03-04 07:23:47.417799+00', NULL, NULL, NULL, ''),
	(1485, 'Début du règne de Toghtoa Bukha, Khan de Mongolie', 1347, false, NULL, 'Toghtoa Bukha accède au trône du Khanat de Mongolie, marquant une période de fragmentation accrue de l''ancien Empire Mongol. Son règne sera marqué par des conflits internes et externes.', 'L''Empire Mongol : Conquêtes, Diplomatie et Échanges Culturels (1206-1368)', '', 'PENDING', '', '2026-03-04 07:23:47.417799+00', NULL, NULL, NULL, ''),
	(1486, 'Publication de l''algorithme de rétropropagation par Paul Werbos', 1974, false, NULL, 'Paul Werbos décrit l''algorithme de rétropropagation dans sa thèse de doctorat. Cet algorithme permet d''entraîner des réseaux de neurones multicouches, surmontant certaines des limitations identifiées par Minsky et Papert.', 'L''Histoire de l''Intelligence Artificielle : Des Origines Théoriques aux Applications Modernes (1943-2011)', '', 'PENDING', '', '2026-03-04 07:23:47.417799+00', NULL, NULL, NULL, ''),
	(1487, 'Publication de l''article "A Logical Calculus of the Ideas Immanent in Nervous Activity" par Warren McCulloch et Walter Pitts', 1943, false, NULL, 'Cet article fondateur propose un modèle mathématique des réseaux neuronaux, influençant fortement le développement de l''IA symbolique. Il pose les bases de la conception de machines capables de simuler des processus cognitifs.', 'L''Histoire de l''Intelligence Artificielle : Des Origines Théoriques aux Applications Modernes (1943-2011)', '', 'PENDING', '', '2026-03-04 07:23:47.417799+00', NULL, NULL, NULL, ''),
	(1488, 'Publication du livre "Perceptrons" par Marvin Minsky et Seymour Papert', 1969, false, NULL, 'Ce livre analyse les limitations des réseaux de neurones simples (perceptrons) et critique leur capacité à résoudre des problèmes complexes. Il a un impact significatif sur le financement de la recherche en IA et conduit à un "hiver de l''IA".', 'L''Histoire de l''Intelligence Artificielle : Des Origines Théoriques aux Applications Modernes (1943-2011)', '', 'PENDING', '', '2026-03-04 07:23:47.417799+00', NULL, NULL, NULL, ''),
	(1489, 'Début du projet Dendral à Stanford', 1965, false, NULL, 'Lancement du projet Dendral, un des premiers systèmes experts, axé sur l''inférence de structures moléculaires à partir de données de spectrométrie de masse. Il marque une étape importante dans le développement de l''intelligence artificielle.', 'L''Histoire de l''Intelligence Artificielle : Des Origines Théoriques aux Applications Modernes (1943-2011)', '', 'PENDING', '', '2026-03-04 07:23:47.417799+00', NULL, NULL, NULL, ''),
	(1490, 'Présentation de l''algorithme de rétropropagation par Rumelhart, Hinton et Williams', 1986, false, NULL, 'David Rumelhart, Geoffrey Hinton et Ronald Williams publient un article démontrant l''efficacité de l''algorithme de rétropropagation pour l''apprentissage dans les réseaux de neurones multicouches. Cet événement marque un tournant majeur dans le domaine.', 'L''Histoire de l''Intelligence Artificielle : Des Origines Théoriques aux Applications Modernes (1943-2011)', '', 'PENDING', '', '2026-03-04 07:23:47.417799+00', NULL, NULL, NULL, ''),
	(1491, 'Publication de ''Learning Internal Representations by Error Propagation'' par Rumelhart, Hinton et Williams dans Nature', 1986, false, NULL, 'L''article de Rumelhart, Hinton et Williams popularise la rétropropagation. Il démontre son potentiel pour résoudre des problèmes complexes et relance l''intérêt pour les réseaux de neurones.', 'L''Histoire de l''Intelligence Artificielle : Des Origines Théoriques aux Applications Modernes (1943-2011)', '', 'PENDING', '', '2026-03-04 07:23:47.417799+00', NULL, NULL, NULL, ''),
	(1492, 'Création du Connectionist Modeling Summer School à Carnegie Mellon University', 1983, false, NULL, 'Ce programme d''été a contribué à former une génération de chercheurs en réseaux de neurones et à diffuser les connaissances sur les modèles connexionnistes.', 'L''Histoire de l''Intelligence Artificielle : Des Origines Théoriques aux Applications Modernes (1943-2011)', '', 'PENDING', '', '2026-03-04 07:23:47.417799+00', NULL, NULL, NULL, ''),
	(1493, 'Développement du réseau Boltzmann par Hinton, Sejnowski et Ackley', 1985, false, NULL, 'Hinton, Sejnowski et Ackley introduisent le réseau de Boltzmann, un type de réseau de neurones stochastique qui utilise un algorithme d''apprentissage basé sur la thermodynamique statistique.', 'L''Histoire de l''Intelligence Artificielle : Des Origines Théoriques aux Applications Modernes (1943-2011)', '', 'PENDING', '', '2026-03-04 07:23:47.417799+00', NULL, NULL, NULL, ''),
	(1494, 'Publication de ''Neural Computation: Foundations of Research'' par Philip D. Wasserman et Robert M. Oetzel', 1990, false, NULL, 'Cet ouvrage a contribué à structurer le domaine du calcul neuronal et à en diffuser les principes. Il a permis de poser les bases pour le développement ultérieur du machine learning.', 'L''Histoire de l''Intelligence Artificielle : Des Origines Théoriques aux Applications Modernes (1943-2011)', '', 'PENDING', '', '2026-03-04 07:23:47.417799+00', NULL, NULL, NULL, ''),
	(1495, 'Création du Consortium for Data Mining (DMC)', 1996, false, NULL, 'Le DMC a été créé pour promouvoir la recherche et le développement dans le domaine du data mining. Il a joué un rôle important dans la diffusion des connaissances et des meilleures pratiques.', 'L''Histoire de l''Intelligence Artificielle : Des Origines Théoriques aux Applications Modernes (1943-2011)', '', 'PENDING', '', '2026-03-04 07:23:47.417799+00', NULL, NULL, NULL, ''),
	(1496, 'Publication de ''The Elements of Statistical Learning'' par Hastie, Tibshirani et Friedman', 2001, false, NULL, 'Cet ouvrage est devenu une référence dans le domaine du machine learning statistique. Il a contribué à formaliser et à diffuser les méthodes statistiques utilisées dans le machine learning.', 'L''Histoire de l''Intelligence Artificielle : Des Origines Théoriques aux Applications Modernes (1943-2011)', '', 'PENDING', '', '2026-03-04 07:23:47.417799+00', NULL, NULL, NULL, ''),
	(1497, 'Début du règne de Songtsen Gampo et introduction du bouddhisme au Tibet', 618, false, NULL, 'Songtsen Gampo, roi du Tibet, épouse la princesse népalaise Bhrikuti et la princesse chinoise Wencheng, toutes deux bouddhistes, ce qui contribue à l''introduction et à la diffusion du bouddhisme au Tibet.', 'L''Odyssée du Bouddhisme : De l''Inde à la Diffusion Mondiale (IVe siècle AEC - 1950)', '', 'PENDING', '', '2026-03-04 07:23:47.417799+00', NULL, NULL, NULL, ''),
	(1498, 'Début du règne de l''empereur Ming de la dynastie Han, qui soutient activement le bouddhisme en Chine', 57, false, NULL, 'L''empereur Ming est connu pour son soutien au bouddhisme, ayant envoyé une mission en Inde pour acquérir des écritures bouddhistes. Son règne marque une période de croissance pour le bouddhisme en Chine.', 'L''Odyssée du Bouddhisme : De l''Inde à la Diffusion Mondiale (IVe siècle AEC - 1950)', '', 'PENDING', '', '2026-03-04 07:23:47.417799+00', NULL, NULL, NULL, ''),
	(1499, 'Construction du Jetavana Vihara à Shravasti achevée', 350, false, NULL, 'La construction du Jetavana Vihara, un important monastère bouddhiste associé à la vie du Bouddha historique, est achevée à Shravasti, en Inde. Ce monastère devient un centre majeur pour l''étude et la pratique du bouddhisme Theravada.', 'L''Odyssée du Bouddhisme : De l''Inde à la Diffusion Mondiale (IVe siècle AEC - 1950)', '', 'PENDING', '', '2026-03-04 07:23:47.417799+00', NULL, NULL, NULL, ''),
	(1500, 'Introduction du bouddhisme au Tibet par le roi Songtsen Gampo', 641, false, NULL, 'Le roi tibétain Songtsen Gampo épouse la princesse népalaise Bhrikuti et la princesse chinoise Wencheng, toutes deux bouddhistes, marquant le début de l''influence bouddhiste au Tibet. Il est considéré comme le premier événement de diffusion du bouddhisme au Tibet.', 'L''Odyssée du Bouddhisme : De l''Inde à la Diffusion Mondiale (IVe siècle AEC - 1950)', '', 'PENDING', '', '2026-03-04 07:23:47.417799+00', NULL, NULL, NULL, ''),
	(1501, 'Construction du monastère de Samye, premier monastère bouddhiste au Tibet', 775, false, NULL, 'Sous le règne du roi Trisong Detsen, le monastère de Samye est achevé, symbolisant l''établissement formel du bouddhisme comme religion d''État au Tibet. Il devient un centre majeur d''apprentissage et de traduction.', 'L''Odyssée du Bouddhisme : De l''Inde à la Diffusion Mondiale (IVe siècle AEC - 1950)', '', 'PENDING', '', '2026-03-04 07:23:47.417799+00', NULL, NULL, NULL, ''),
	(1502, 'Début du règne de Jayavarman VII, roi khmer et fervent bouddhiste', 1181, false, NULL, 'Jayavarman VII monte sur le trône de l''Empire khmer et promeut activement le bouddhisme Mahayana. Son règne voit la construction de nombreux temples bouddhistes, dont le Bayon à Angkor Thom.', 'L''Odyssée du Bouddhisme : De l''Inde à la Diffusion Mondiale (IVe siècle AEC - 1950)', '', 'PENDING', '', '2026-03-04 07:23:47.417799+00', NULL, NULL, NULL, ''),
	(1503, 'Publication du Tripitaka Koreana, collection complète des écritures bouddhistes', 1251, false, NULL, 'La deuxième version du Tripitaka Koreana, une collection complète des écritures bouddhistes gravées sur plus de 80 000 blocs de bois, est achevée en Corée. Elle est conservée au temple Haeinsa.', 'L''Odyssée du Bouddhisme : De l''Inde à la Diffusion Mondiale (IVe siècle AEC - 1950)', '', 'PENDING', '', '2026-03-04 07:23:47.417799+00', NULL, NULL, NULL, ''),
	(1504, 'John Jacob Astor fonde l''American Fur Company', 1808, false, NULL, 'John Jacob Astor fonde l''American Fur Company, qui deviendra l''une des plus grandes entreprises de commerce de la fourrure aux États-Unis. Elle rivalisera avec la Compagnie de la Baie d''Hudson pour le contrôle du marché.', 'La conquête de l''Ouest Américain : Des trappeurs aux cowboys et à la ruée vers l''or (1803-1893)', '', 'PENDING', '', '2026-03-04 07:23:47.417799+00', NULL, NULL, NULL, ''),
	(1505, 'Pic de production de fourrures de castor en Amérique du Nord', 1830, false, NULL, 'L''année 1830 marque le pic de la production de fourrures de castor en Amérique du Nord, alimentant la demande européenne pour les chapeaux de feutre. La sur-exploitation des castors conduit à un déclin de leur population et à une évolution du commerce de la fourrure.', 'La conquête de l''Ouest Américain : Des trappeurs aux cowboys et à la ruée vers l''or (1803-1893)', '', 'PENDING', '', '2026-03-04 07:23:47.417799+00', NULL, NULL, NULL, ''),
	(1506, 'Début du premier convoi organisé vers l''Oregon depuis Independence, Missouri', 1841, false, NULL, 'Le groupe Bartleson-Bidwell part pour la Californie, marquant un tournant dans la migration organisée vers l''Ouest. Ce voyage pionnier ouvre la voie à des milliers de personnes.', 'La conquête de l''Ouest Américain : Des trappeurs aux cowboys et à la ruée vers l''or (1803-1893)', '', 'PENDING', '', '2026-03-04 07:23:47.417799+00', NULL, NULL, NULL, ''),
	(1507, 'Publication du ''Guide de l''Émigrant'' de John Charles Frémont', 1843, false, NULL, 'Le rapport de Frémont sur ses explorations devient un guide essentiel pour les pionniers. Il fournit des informations cruciales sur les itinéraires, les ressources et les défis de la piste de l''Oregon.', 'La conquête de l''Ouest Américain : Des trappeurs aux cowboys et à la ruée vers l''or (1803-1893)', '', 'PENDING', '', '2026-03-04 07:23:47.417799+00', NULL, NULL, NULL, ''),
	(1508, 'Publication du rapport de la Commission de la Paix Indienne', 1868, false, NULL, 'Ce rapport préconise une politique de sédentarisation des Amérindiens dans des réserves. Il marque un tournant dans la politique américaine envers les peuples autochtones.', 'La conquête de l''Ouest Américain : Des trappeurs aux cowboys et à la ruée vers l''or (1803-1893)', '', 'PENDING', '', '2026-03-04 07:23:47.417799+00', NULL, NULL, NULL, ''),
	(1509, 'Couronnement d''Edmond comme roi d''Est-Anglie', 855, false, NULL, 'Edmond devient roi d''Est-Anglie, un royaume anglo-saxon. Son règne sera marqué par des conflits avec les Vikings, culminant avec son martyre en 869.', 'L''Épopée Viking : Pillages, Commerce et Exploration (793-1066)', '', 'PENDING', '', '2026-03-04 07:23:47.417799+00', NULL, NULL, NULL, ''),
	(1510, 'Introduction du café à Aden par des soufis yéménites', 1400, false, NULL, 'Des soufis yéménites introduisent le café à Aden pour rester éveillés pendant leurs prières nocturnes. Cette pratique contribue à la diffusion du café dans le monde islamique.', 'L''histoire du café : De la légende éthiopienne à la mondialisation des Starbucks', '', 'PENDING', '', '2026-03-04 07:23:47.417799+00', NULL, NULL, NULL, ''),
	(1511, 'Ouverture du premier café public à Constantinople (Kiva Han)', 1555, false, NULL, 'Deux marchands, Hakam et Shamsi, ouvrent le premier café public à Constantinople, appelé Kiva Han. Ce lieu devient rapidement un centre de rassemblement social et intellectuel.', 'L''histoire du café : De la légende éthiopienne à la mondialisation des Starbucks', '', 'PENDING', '', '2026-03-04 07:23:47.417799+00', NULL, NULL, NULL, ''),
	(1512, 'Fondation de l''Organisation Internationale du Café (ICO) sous l''égide de l''ONU', 1963, false, NULL, 'L''Organisation Internationale du Café (ICO) est fondée sous l''égide de l''ONU, dans le but de promouvoir la coopération internationale en matière de commerce du café et de stabiliser les marchés.', 'L''histoire du café : De la légende éthiopienne à la mondialisation des Starbucks', '', 'PENDING', '', '2026-03-04 07:23:47.417799+00', NULL, NULL, NULL, ''),
	(1513, 'Première mention documentée du café à Aden, Yémen', 1450, false, NULL, 'Le café est mentionné dans des textes soufis, indiquant son utilisation dans des rituels religieux. Aden devient un centre de commerce du café.', 'L''histoire du café : De la légende éthiopienne à la mondialisation des Starbucks', '', 'PENDING', '', '2026-03-04 07:23:47.417799+00', NULL, NULL, NULL, ''),
	(1514, 'Première exportation significative de café de la Jamaïque vers l''Europe', 1728, false, NULL, 'La Jamaïque commence à exporter du café vers l''Europe, signalant l''établissement de la culture du café dans les colonies britanniques des Caraïbes. Cette exportation marque une étape importante dans l''expansion du commerce du café.', 'L''histoire du café : De la légende éthiopienne à la mondialisation des Starbucks', '', 'PENDING', '', '2026-03-04 07:23:47.417799+00', NULL, NULL, NULL, ''),
	(1515, 'Fondation de la Bourse du Café à New York (New York Coffee Exchange)', 1770, false, NULL, 'La Bourse du Café de New York est fondée, reflétant l''importance croissante du commerce du café dans l''économie américaine. Elle deviendra un centre névralgique pour la fixation des prix et les échanges internationaux.', 'L''histoire du café : De la légende éthiopienne à la mondialisation des Starbucks', '', 'PENDING', '', '2026-03-04 07:23:47.43055+00', NULL, NULL, NULL, ''),
	(1516, 'Ouverture du premier Starbucks à Seattle (Pike Place Market)', 1971, false, NULL, 'Le premier Starbucks ouvre ses portes à Seattle, vendant initialement des grains de café et du matériel de torréfaction. Il marque le début de la chaîne de café la plus importante au monde.', 'L''histoire du café : De la légende éthiopienne à la mondialisation des Starbucks', '', 'PENDING', '', '2026-03-04 07:23:47.43055+00', NULL, NULL, NULL, ''),
	(1517, 'Dunkin'' Donuts lance son premier café expresso', 2003, false, NULL, 'Dunkin'' Donuts, principalement connu pour ses donuts et son café filtre, lance son premier café expresso, entrant en concurrence directe avec Starbucks et d''autres chaînes de café.', 'L''histoire du café : De la légende éthiopienne à la mondialisation des Starbucks', '', 'PENDING', '', '2026-03-04 07:23:47.43055+00', NULL, NULL, NULL, ''),
	(1518, 'McDonald''s lance McCafé aux États-Unis', 2009, false, NULL, 'McDonald''s lance McCafé aux États-Unis, étendant son offre de boissons à base de café et entrant en concurrence avec les chaînes de café établies comme Starbucks et Dunkin'' Donuts.', 'L''histoire du café : De la légende éthiopienne à la mondialisation des Starbucks', '', 'PENDING', '', '2026-03-04 07:23:47.43055+00', NULL, NULL, NULL, ''),
	(1519, 'Inauguration du pont Hell Gate à New York', 1917, false, NULL, 'L''ouverture du pont Hell Gate facilite le transport ferroviaire de marchandises et de personnes à travers New York, renforçant l''infrastructure industrielle et l''attractivité économique de la région.', 'La Grande Migration Africaine-Américaine : De la Ségrégation Rurale au Renouveau Culturel Urbain (1910-1970)', '', 'PENDING', '', '2026-03-04 07:23:47.43055+00', NULL, NULL, NULL, ''),
	(1520, 'Ouverture du premier bureau de la National Urban League à New York', 1910, false, NULL, 'Le 29 septembre 1910, la National Urban League ouvre son premier bureau à New York. Cette organisation jouera un rôle crucial dans l''amélioration des conditions sociales et économiques des Afro-Américains dans les villes.', 'La Grande Migration Africaine-Américaine : De la Ségrégation Rurale au Renouveau Culturel Urbain (1910-1970)', '', 'PENDING', '', '2026-03-04 07:23:47.43055+00', NULL, NULL, NULL, ''),
	(1521, 'Publication du recueil de poèmes "Harlem Shadows" de Claude McKay', 1922, false, NULL, 'Ce recueil marque une étape importante dans la reconnaissance de la poésie afro-américaine et contribue à définir les thèmes de la Renaissance de Harlem. Il aborde des questions de race, d''identité et d''injustice sociale.', 'La Grande Migration Africaine-Américaine : De la Ségrégation Rurale au Renouveau Culturel Urbain (1910-1970)', '', 'PENDING', '', '2026-03-04 07:23:47.43055+00', NULL, NULL, NULL, ''),
	(1522, 'Première représentation de la pièce "The Emperor Jones" d''Eugene O''Neill avec Paul Robeson dans le rôle principal', 1924, false, NULL, 'Cette pièce, bien que controversée, est l''une des premières à présenter un acteur afro-américain dans un rôle dramatique majeur sur une scène de Broadway. Elle contribue à briser les barrières raciales dans le théâtre américain.', 'La Grande Migration Africaine-Américaine : De la Ségrégation Rurale au Renouveau Culturel Urbain (1910-1970)', '', 'PENDING', '', '2026-03-04 07:23:47.43055+00', NULL, NULL, NULL, ''),
	(1523, 'Publication du roman "Quicksand" de Nella Larsen', 1928, false, NULL, 'Ce roman explore les thèmes de l''identité raciale, de la classe sociale et du rôle des femmes dans la société afro-américaine. Il est considéré comme une œuvre majeure de la Renaissance de Harlem.', 'La Grande Migration Africaine-Américaine : De la Ségrégation Rurale au Renouveau Culturel Urbain (1910-1970)', '', 'PENDING', '', '2026-03-04 07:23:47.43055+00', NULL, NULL, NULL, ''),
	(1524, 'Publication du roman "Their Eyes Were Watching God" de Zora Neale Hurston', 1937, false, NULL, 'Ce roman est une œuvre majeure de la littérature afro-américaine qui explore les thèmes de l''identité féminine, de l''amour et de la quête de soi dans le Sud rural. Bien que publié après la période de la Renaissance de Harlem, il est influencé par ce mouvement.', 'La Grande Migration Africaine-Américaine : De la Ségrégation Rurale au Renouveau Culturel Urbain (1910-1970)', '', 'PENDING', '', '2026-03-04 07:23:47.43055+00', NULL, NULL, NULL, ''),
	(1526, 'Présentation du Thaumatrope par John Ayrton Paris à Londres', 1825, false, NULL, 'Le physicien John Ayrton Paris présente le thaumatrope, un jouet optique basé sur la persistance rétinienne. Il est composé d''un disque avec deux images différentes sur chaque face, qui semblent se combiner lorsque le disque est mis en rotation.', 'L''histoire du Cinéma d''Animation : Des jouets optiques aux blockbusters numériques (1828-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.43055+00', NULL, NULL, NULL, ''),
	(1527, 'Invention du Zootrope par William George Horner', 1834, false, NULL, 'Le mathématicien britannique William George Horner invente le zootrope, un appareil d''animation qui améliore le phénakistiscope. Il utilise un cylindre rotatif avec des fentes verticales pour observer une bande de dessins à l''intérieur.', 'L''histoire du Cinéma d''Animation : Des jouets optiques aux blockbusters numériques (1828-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.43055+00', NULL, NULL, NULL, ''),
	(1528, 'Brevet du Folioscope (Flip Book) par John Barnes Linnett', 1868, false, NULL, 'John Barnes Linnett brevète le Kinéographe, plus connu sous le nom de Folioscope ou Flip Book. Il s''agit d''un petit livre contenant une série d''images légèrement différentes qui, feuilletées rapidement, donnent l''illusion du mouvement.', 'L''histoire du Cinéma d''Animation : Des jouets optiques aux blockbusters numériques (1828-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.43055+00', NULL, NULL, NULL, ''),
	(1529, 'Présentation du Praxinoscope d''Émile Reynaud à Paris', 1877, false, NULL, 'Émile Reynaud présente son Praxinoscope, un perfectionnement du zootrope, à Paris. Il utilise un tambour rotatif avec des miroirs au centre pour une vision plus claire et lumineuse des images animées.', 'L''histoire du Cinéma d''Animation : Des jouets optiques aux blockbusters numériques (1828-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.43055+00', NULL, NULL, NULL, ''),
	(1530, 'Walt Disney fonde le Laugh-O-gram Studio à Kansas City', 1922, false, NULL, 'Ce studio marque le début de la carrière de Walt Disney dans l''animation. Il produit des courts métrages et des publicités animées avant de faire faillite.', 'L''histoire du Cinéma d''Animation : Des jouets optiques aux blockbusters numériques (1828-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.43055+00', NULL, NULL, NULL, ''),
	(1531, 'Sortie de *The Black Cauldron* (Taram et le Chaudron magique), film d''animation Disney sombre et coûteux', 1985, false, NULL, 'Le film, basé sur les *Chroniques de Prydain*, est un échec commercial et critique initial. Il marque une période difficile pour Disney avant la Renaissance des années 1990.', 'L''histoire du Cinéma d''Animation : Des jouets optiques aux blockbusters numériques (1828-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.43055+00', NULL, NULL, NULL, ''),
	(1532, 'Commercialisation du logiciel Maya, outil de référence pour l''animation 3D', 1998, false, NULL, 'Développé par Alias Systems Corporation, Maya devient rapidement un standard de l''industrie pour la modélisation, l''animation et le rendu 3D. Il est utilisé dans de nombreux films, jeux vidéo et productions télévisuelles.', 'L''histoire du Cinéma d''Animation : Des jouets optiques aux blockbusters numériques (1828-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.43055+00', NULL, NULL, NULL, ''),
	(1533, 'Institution du Jinshi comme plus haut degré du système d''examen impérial (vers 702)', 702, false, NULL, 'Sous le règne de l''impératrice Wu Zetian, le Jinshi devient le plus haut degré du système d''examen. Ce diplôme prestigieux ouvre les portes aux plus hautes fonctions de l''empire.', 'La Dynastie Tang : Âge d''Or de la Chine Médiévale (618-907)', '', 'PENDING', '', '2026-03-04 07:23:47.43055+00', NULL, NULL, NULL, ''),
	(1534, 'Création de l''Académie Hanlin pour les érudits ayant réussi les examens impériaux (754)', 754, false, NULL, 'L''empereur Xuanzong fonde l''Académie Hanlin, un institut prestigieux pour les érudits ayant réussi les examens impériaux. L''académie devient un centre important de recherche et de conseil politique.', 'La Dynastie Tang : Âge d''Or de la Chine Médiévale (618-907)', '', 'PENDING', '', '2026-03-04 07:23:47.43055+00', NULL, NULL, NULL, ''),
	(1535, 'Réforme du système fiscal sous Xuanzong (Double Tax System)', 730, false, NULL, 'Mise en place d''un nouveau système d''imposition visant à simplifier et à rendre plus équitable la collecte des impôts, stimulant ainsi l''économie et le commerce sur la Route de la Soie.', 'La Dynastie Tang : Âge d''Or de la Chine Médiévale (618-907)', '', 'PENDING', '', '2026-03-04 07:23:47.43055+00', NULL, NULL, NULL, ''),
	(1536, 'Construction du temple de Daming à Yangzhou', 742, false, NULL, 'Ce temple bouddhiste devient un important centre religieux et culturel, attirant des moines et des pèlerins de toute l''Asie, renforçant ainsi les liens culturels et commerciaux le long de la Route de la Soie.', 'La Dynastie Tang : Âge d''Or de la Chine Médiévale (618-907)', '', 'PENDING', '', '2026-03-04 07:23:47.43055+00', NULL, NULL, NULL, ''),
	(1537, 'Première révolte d''esclaves à Saint-Domingue', 1676, false, NULL, 'Une importante révolte d''esclaves éclate dans la région de Petit-Goâve à Saint-Domingue (actuelle Haïti). Bien que réprimée, elle marque le début d''une longue série de résistances à l''esclavage dans la colonie française.', 'L''Âge d''Or de la Piraterie : Des Caraïbes aux Océans du Monde (1650-1730)', '', 'PENDING', '', '2026-03-04 07:23:47.43055+00', NULL, NULL, NULL, ''),
	(1538, 'Diffusion du papier en Corée via des moines bouddhistes', 610, false, NULL, 'Des moines bouddhistes coréens, en voyage en Chine, découvrent le papier et rapportent cette technologie en Corée. Cela marque le début de la diffusion du papier en dehors de la Chine.', 'L''histoire du papier : Des inventions chinoises à l''ère numérique (105-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.43055+00', NULL, NULL, NULL, ''),
	(1539, 'Introduction de la fabrication du papier à Samarcande après la bataille du Talas', 751, false, NULL, 'Des prisonniers de guerre chinois, capturés lors de la bataille du Talas par les armées arabes, révèlent le secret de la fabrication du papier à Samarcande. Cela marque le début de la production de papier dans le monde musulman.', 'L''histoire du papier : Des inventions chinoises à l''ère numérique (105-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.43055+00', NULL, NULL, NULL, ''),
	(1540, 'Établissement d''un atelier de fabrication de papier officiel au Japon (Kami-ya-in)', 724, false, NULL, 'L''établissement du Kami-ya-in officialise la production de papier au Japon, assurant un approvisionnement stable pour les besoins administratifs et religieux. Cet atelier centralise et standardise les techniques de fabrication.', 'L''histoire du papier : Des inventions chinoises à l''ère numérique (105-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.43055+00', NULL, NULL, NULL, ''),
	(1541, 'Publication du Hyakumanto Darani, plus anciens exemples d''impression au Japon', 770, false, NULL, 'L''impératrice Shōtoku commande l''impression de millions de copies du Hyakumanto Darani, des charmes bouddhistes, témoignant de l''utilisation du papier pour la diffusion de textes religieux. Ces impressions sont parmi les plus anciens exemples d''impression connus au Japon.', 'L''histoire du papier : Des inventions chinoises à l''ère numérique (105-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.43055+00', NULL, NULL, NULL, ''),
	(1542, 'Première mention d''un moulin à papier en Espagne (Játiva)', 1056, false, NULL, 'Un document mentionne l''existence d''un moulin à papier à Játiva, en Espagne, témoignant de l''introduction précoce de la fabrication du papier dans la péninsule ibérique. Ce moulin marque une étape importante dans la diffusion du papier en Europe.', 'L''histoire du papier : Des inventions chinoises à l''ère numérique (105-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.43055+00', NULL, NULL, NULL, ''),
	(1543, 'Construction du moulin à papier d''Hérault (France)', 1189, false, NULL, 'Le comte de Toulouse autorise la construction d''un moulin à papier sur l''Hérault, près de Saint-Guilhem-le-Désert. Ce moulin est l''un des premiers exemples connus de production de papier en France.', 'L''histoire du papier : Des inventions chinoises à l''ère numérique (105-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.43055+00', NULL, NULL, NULL, ''),
	(1544, 'Fondation du moulin à papier de Fabriano (Italie)', 1276, false, NULL, 'La ville de Fabriano, en Italie, devient un centre majeur de production de papier grâce à l''établissement de moulins utilisant des techniques innovantes. Fabriano est réputée pour la qualité de son papier.', 'L''histoire du papier : Des inventions chinoises à l''ère numérique (105-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.43055+00', NULL, NULL, NULL, ''),
	(1545, 'Première utilisation de filigranes sur le papier (Bologne)', 1282, false, NULL, 'Les papetiers de Bologne, en Italie, commencent à utiliser des filigranes pour identifier leurs papiers. Cette technique permet de marquer l''origine et la qualité du papier.', 'L''histoire du papier : Des inventions chinoises à l''ère numérique (105-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.43055+00', NULL, NULL, NULL, ''),
	(1546, 'Début de la production de papier à Troyes (France)', 1348, false, NULL, 'La production de papier commence à Troyes, en France, contribuant à l''expansion de l''industrie papetière dans le nord de l''Europe. Troyes devient un centre important pour le commerce du papier.', 'L''histoire du papier : Des inventions chinoises à l''ère numérique (105-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.43055+00', NULL, NULL, NULL, ''),
	(1547, 'Première impression d''un livre avec des illustrations gravées sur bois (Der Edelstein)', 1461, false, NULL, 'Albrecht Pfister imprime "Der Edelstein" (La Pierre Précieuse) d''Ulrich Boner à Bamberg. C''est le premier livre imprimé connu à contenir des illustrations gravées sur bois, marquant une avancée dans l''intégration du texte et de l''image.', 'L''histoire du papier : Des inventions chinoises à l''ère numérique (105-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.43055+00', NULL, NULL, NULL, ''),
	(1548, 'Première machine à papier Fourdrinier opérationnelle à Frogmore Paper Mill', 1803, false, NULL, 'Henry et Sealy Fourdrinier, après avoir acquis le brevet de Robert, mettent en service la première machine à papier Fourdrinier opérationnelle à Frogmore Paper Mill, en Angleterre. Cette machine améliore considérablement la production de papier.', 'L''histoire du papier : Des inventions chinoises à l''ère numérique (105-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.43055+00', NULL, NULL, NULL, ''),
	(1549, 'Le Belgica franchit le cercle antarctique', 1898, false, NULL, 'Le navire Belgica devient le premier navire à franchir le cercle antarctique dans le cadre d''une expédition scientifique. Cet événement marque une étape importante dans l''exploration de l''Antarctique.', 'La Course aux Pôles : Des Explorations Pionnières aux Bases Scientifiques (900-2000)', '', 'PENDING', '', '2026-03-04 07:23:47.43055+00', NULL, NULL, NULL, ''),
	(1550, 'Première utilisation de lampes à arc électrique pour traiter le scorbut à bord du Belgica', 1898, false, NULL, 'Le médecin de l''expédition, Frederick Cook, utilise des lampes à arc électrique pour traiter le scorbut parmi l''équipage du Belgica. C''est l''une des premières tentatives d''utilisation de la lumière artificielle pour traiter cette maladie en milieu extrême.', 'La Course aux Pôles : Des Explorations Pionnières aux Bases Scientifiques (900-2000)', '', 'PENDING', '', '2026-03-04 07:23:47.43055+00', NULL, NULL, NULL, ''),
	(1551, 'Le Belgica est libéré des glaces après 13 mois de captivité', 1899, false, NULL, 'Après 13 mois de captivité dans les glaces, l''équipage du Belgica parvient à libérer le navire. Cet événement marque la fin du premier hivernage en Antarctique et le début du voyage de retour.', 'La Course aux Pôles : Des Explorations Pionnières aux Bases Scientifiques (900-2000)', '', 'PENDING', '', '2026-03-04 07:23:47.43055+00', NULL, NULL, NULL, ''),
	(1552, 'Inauguration du règne de K''inich Yax K''uk'' Mo'' à Copán', 426, false, NULL, 'K''inich Yax K''uk'' Mo'' fonde la dynastie de Copán, marquant un tournant dans l''histoire de la cité-état maya. Cet événement est crucial pour comprendre l''ascension de Copán comme centre politique et culturel majeur.', 'L''essor des civilisations précolombiennes : Des Olmèques aux Incas (1200 AEC - 1533)', '', 'PENDING', '', '2026-03-04 07:23:47.43055+00', NULL, NULL, NULL, ''),
	(1553, 'Consécration du Temple 33 à Tikal', 457, false, NULL, 'Le Temple 33 est consacré à Tikal, un important centre cérémoniel et politique. Cette construction témoigne de la puissance et de l''influence de Tikal à son apogée.', 'L''essor des civilisations précolombiennes : Des Olmèques aux Incas (1200 AEC - 1533)', '', 'PENDING', '', '2026-03-04 07:23:47.43055+00', NULL, NULL, NULL, ''),
	(1554, 'Début du règne de Yax Pasaj Chan Yopaat à Copán', 763, false, NULL, 'Yax Pasaj Chan Yopaat monte sur le trône de Copán, marquant une période de changements et de défis pour la cité-état. Son règne est crucial pour comprendre le déclin éventuel de Copán.', 'L''essor des civilisations précolombiennes : Des Olmèques aux Incas (1200 AEC - 1533)', '', 'PENDING', '', '2026-03-04 07:23:47.43055+00', NULL, NULL, NULL, ''),
	(1555, 'Érection de la stèle 1 à Calakmul', 652, false, NULL, 'La stèle 1 est érigée à Calakmul, une cité rivale de Tikal. Elle commémore un événement important du règne de Yuknoom Ch''een II, soulignant la puissance et l''ambition de Calakmul.', 'L''essor des civilisations précolombiennes : Des Olmèques aux Incas (1200 AEC - 1533)', '', 'PENDING', '', '2026-03-04 07:23:47.43055+00', NULL, NULL, NULL, ''),
	(1556, 'Construction de la Ciudadela et du Temple de Quetzalcoatl à Teotihuacan (achèvement)', 350, false, NULL, 'L''achèvement de la Ciudadela et du Temple de Quetzalcoatl témoigne de la puissance politique et religieuse de Teotihuacan. Le complexe devient le centre administratif et cérémoniel de la cité.', 'L''essor des civilisations précolombiennes : Des Olmèques aux Incas (1200 AEC - 1533)', '', 'PENDING', '', '2026-03-04 07:23:47.43055+00', NULL, NULL, NULL, ''),
	(1557, 'Apogée de l''influence de Teotihuacan sur les cités mayas (Tikal, Kaminaljuyu)', 450, false, NULL, 'Teotihuacan atteint le sommet de son influence culturelle et politique en Mésoamérique. Son style architectural et ses pratiques religieuses se répandent dans les cités mayas, notamment Tikal et Kaminaljuyu.', 'L''essor des civilisations précolombiennes : Des Olmèques aux Incas (1200 AEC - 1533)', '', 'PENDING', '', '2026-03-04 07:23:47.43055+00', NULL, NULL, NULL, ''),
	(1558, 'Présentation du "Nimrod", un des premiers jeux vidéo interactifs, à l''Exposition des Sciences Britanniques', 1951, false, NULL, 'Conçu par John Bennett, le Nimrod est un ordinateur spécialisé dans le jeu de Nim. Il est présenté au public lors de l''Exposition des Sciences Britanniques.', 'L''Histoire des Jeux Vidéo : De Pong aux Réalités Virtuelles', '', 'PENDING', '', '2026-03-04 07:23:47.43055+00', NULL, NULL, NULL, ''),
	(1559, 'Sortie de *Street Fighter II: The World Warrior* sur Arcade', 1991, false, NULL, 'Capcom lance *Street Fighter II: The World Warrior* sur les bornes d''arcade. Il révolutionne le genre du jeu de combat et établit de nouvelles normes en matière de gameplay, de personnages et de compétition.', 'L''Histoire des Jeux Vidéo : De Pong aux Réalités Virtuelles', '', 'PENDING', '', '2026-03-04 07:23:47.43055+00', NULL, NULL, NULL, ''),
	(1560, 'Lancement du premier MMORPG graphique ''Meridian 59''', 1996, false, NULL, 'Archetype Interactive lance ''Meridian 59'', considéré comme le premier MMORPG (Massively Multiplayer Online Role-Playing Game) avec un environnement graphique 3D. Il marque le début d''une nouvelle ère pour les jeux en ligne.', 'L''Histoire des Jeux Vidéo : De Pong aux Réalités Virtuelles', '', 'PENDING', '', '2026-03-04 07:23:47.43055+00', NULL, NULL, NULL, ''),
	(1561, 'Construction du monastère bouddhiste de Hadda sous l''influence Kushan', 200, false, NULL, 'Le monastère de Hadda, près de Jalalabad (Afghanistan), devient un centre majeur de l''art bouddhique gréco-bouddhique sous le patronage Kushan. Il témoigne de l''influence culturelle de l''empire.', 'La Route de la Soie : Des caravanes aux empires et aux échanges culturels (IIe siècle AEC - XIVe siècle)', '', 'PENDING', '', '2026-03-04 07:23:47.43055+00', NULL, NULL, NULL, ''),
	(1562, 'Invention de la boussole : Facilitation de la navigation et du commerce maritime', 850, false, NULL, 'L''invention de la boussole en Chine facilite la navigation maritime et terrestre. Elle contribue à l''essor du commerce sur la Route de la Soie et au-delà.', 'La Route de la Soie : Des caravanes aux empires et aux échanges culturels (IIe siècle AEC - XIVe siècle)', '', 'PENDING', '', '2026-03-04 07:23:47.43055+00', NULL, NULL, NULL, ''),
	(1563, 'Fondation de la Ligue Hanséatique (Hanse)', 1356, false, NULL, 'La Ligue Hanséatique, une alliance commerciale et défensive de villes marchandes d''Europe du Nord, est officiellement fondée. Elle domine le commerce maritime dans la mer Baltique et la mer du Nord, favorisant le développement économique et l''autonomie politique des villes membres.', 'La Route de la Soie : Des caravanes aux empires et aux échanges culturels (IIe siècle AEC - XIVe siècle)', '', 'PENDING', '', '2026-03-04 07:23:47.43055+00', NULL, NULL, NULL, ''),
	(1564, 'Ordonnance somptuaire de Philippe IV le Bel réglementant les vêtements (France)', 1294, false, NULL, 'Cette ordonnance vise à limiter les dépenses excessives en matière de vêtements et à maintenir les distinctions sociales à travers la mode. Elle détaille les types de tissus, les ornements et les coupes autorisés pour chaque classe sociale.', 'L''histoire de la mode : Des costumes traditionnels aux tendances mondialisées (1300-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.43055+00', NULL, NULL, NULL, ''),
	(1565, 'Isabelle de Bavière impose la ''Hennin'' à la cour de France', 1395, false, NULL, 'La hennin, coiffe conique allongée, devient un symbole de statut élevé à la cour de France sous l''influence d''Isabelle de Bavière. Sa hauteur et son ornementation varient selon le rang social.', 'L''histoire de la mode : Des costumes traditionnels aux tendances mondialisées (1300-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.442367+00', NULL, NULL, NULL, ''),
	(1566, 'Publication du décret interdisant les chaussures à poulaines (Angleterre)', 1463, false, NULL, 'Édouard IV interdit le port de chaussures à poulaines, caractérisées par leurs pointes excessivement longues, en raison de leur caractère ostentatoire et des problèmes de mobilité qu''elles causaient.', 'L''histoire de la mode : Des costumes traditionnels aux tendances mondialisées (1300-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.442367+00', NULL, NULL, NULL, ''),
	(1567, 'Publication du "Roman comique" de Scarron', 1651, false, NULL, 'Ce roman est une œuvre majeure de la littérature française du XVIIe siècle, offrant un aperçu de la vie des comédiens et des mœurs de l''époque. Il a influencé le développement du roman réaliste et comique.', 'L''histoire de la mode : Des costumes traditionnels aux tendances mondialisées (1300-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.442367+00', NULL, NULL, NULL, ''),
	(1568, 'Ouverture du premier salon de thé Coco Chanel à Deauville', 1913, false, NULL, 'Coco Chanel ouvre sa première boutique de mode à Deauville, marquant le début de son ascension dans le monde de la mode. Elle y propose des vêtements confortables et pratiques, rompant avec les codes vestimentaires de l''époque.', 'L''histoire de la mode : Des costumes traditionnels aux tendances mondialisées (1300-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.442367+00', NULL, NULL, NULL, ''),
	(1569, 'Commercialisation du premier vernis à ongles par Revlon', 1932, false, NULL, 'Revlon lance le premier vernis à ongles opaque, inspiré par la couleur des automobiles. Ce produit connaît un succès immédiat et contribue à populariser le maquillage auprès des femmes.', 'L''histoire de la mode : Des costumes traditionnels aux tendances mondialisées (1300-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.442367+00', NULL, NULL, NULL, ''),
	(1570, 'Présentation du bikini par Louis Réard', 1946, false, NULL, 'Le couturier français Louis Réard présente le bikini, un maillot de bain deux pièces très court, lors d''un défilé de mode à Paris. Ce vêtement audacieux provoque un scandale, mais il marque une révolution dans l''histoire du costume de bain.', 'L''histoire de la mode : Des costumes traditionnels aux tendances mondialisées (1300-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.442367+00', NULL, NULL, NULL, ''),
	(1571, 'Lancement du premier défilé de prêt-à-porter par Pierre Cardin au Printemps', 1959, false, NULL, 'Pierre Cardin révolutionne la mode en présentant une collection accessible, marquant le début du prêt-à-porter de luxe. Cet événement démocratise la mode et la rend accessible à un public plus large.', 'L''histoire de la mode : Des costumes traditionnels aux tendances mondialisées (1300-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.442367+00', NULL, NULL, NULL, ''),
	(1572, 'Publication du rapport "After the tsunami: rapid environmental assessment" par l''UNEP', 2005, false, NULL, 'Le Programme des Nations Unies pour l''environnement (PNUE) publie un rapport sur l''impact environnemental du tsunami de 2004. Il sensibilise aux conséquences écologiques de la production et de la consommation de masse, y compris dans l''industrie de la mode.', 'L''histoire de la mode : Des costumes traditionnels aux tendances mondialisées (1300-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.442367+00', NULL, NULL, NULL, ''),
	(1573, 'Début du règne de Mansa Musa sur l''Empire du Mali', 1312, false, NULL, 'Mansa Musa accède au trône de l''Empire du Mali, marquant le début d''une période de prospérité et d''expansion culturelle. Son règne est considéré comme l''apogée de l''empire.', 'Les Royaumes Africains : Du Ghana à l''Empire Songhaï (300 - 1591)', '', 'PENDING', '', '2026-03-04 07:23:47.442367+00', NULL, NULL, NULL, ''),
	(1574, 'Fin du règne de Mansa Musa sur l''Empire du Mali', 1337, false, NULL, 'Mansa Musa décède, mettant fin à son règne de 25 ans sur l''Empire du Mali. Son règne est marqué par une expansion territoriale, une prospérité économique et un rayonnement culturel sans précédent.', 'Les Royaumes Africains : Du Ghana à l''Empire Songhaï (300 - 1591)', '', 'PENDING', '', '2026-03-04 07:23:47.442367+00', NULL, NULL, NULL, ''),
	(1575, 'Sonni Ali Ber s''empare de Tombouctou', 1468, false, NULL, 'Sonni Ali Ber, roi de Gao, conquiert Tombouctou, marquant une étape cruciale dans l''expansion de l''empire Songhaï. La ville devient un centre majeur de commerce et d''érudition islamique sous son règne.', 'Les Royaumes Africains : Du Ghana à l''Empire Songhaï (300 - 1591)', '', 'PENDING', '', '2026-03-04 07:23:47.442367+00', NULL, NULL, NULL, ''),
	(1576, 'Pèlerinage d''Askia Mohammad Ier à La Mecque', 1496, false, NULL, 'Askia Mohammad Ier effectue un pèlerinage grandiose à La Mecque, renforçant la légitimité de son pouvoir et les liens de l''empire Songhaï avec le monde musulman. Il reçoit le titre de calife du Soudan occidental.', 'Les Royaumes Africains : Du Ghana à l''Empire Songhaï (300 - 1591)', '', 'PENDING', '', '2026-03-04 07:23:47.442367+00', NULL, NULL, NULL, ''),
	(1577, 'Défaite de l''armée Songhaï à la bataille de Tondibi', 1591, false, NULL, 'Les forces de l''empire Songhaï sont vaincues par une armée marocaine équipée d''armes à feu à Tondibi. Cette défaite marque le début du déclin de l''empire et son morcellement en plusieurs entités.', 'Les Royaumes Africains : Du Ghana à l''Empire Songhaï (300 - 1591)', '', 'PENDING', '', '2026-03-04 07:23:47.442367+00', NULL, NULL, NULL, ''),
	(1578, 'Première preuve de parfum à base d''huile : découverte dans des tombes de l''âge de Nagada II en Égypte', 3500, false, NULL, 'Des archéologues découvrent des résidus de parfum à base d''huile dans des récipients en céramique lors de fouilles de tombes datant de l''âge de Nagada II en Égypte. Cela témoigne d''une utilisation précoce du parfum dans les rituels funéraires et la vie quotidienne.', 'L''histoire du parfum : De l''Égypte antique aux fragrances contemporaines', '', 'PENDING', '', '2026-03-04 07:23:47.442367+00', NULL, NULL, NULL, ''),
	(1598, 'Annonce de l''Apple IIe, une version améliorée et plus abordable de l''Apple II', 1983, false, NULL, 'Apple annonce l''Apple IIe, une version améliorée et plus abordable de l''Apple II. Il devient l''un des ordinateurs les plus populaires des années 1980.', '', '', 'PENDING', '', '2026-03-04 07:23:47.442367+00', NULL, NULL, NULL, ''),
	(1579, 'Première mention écrite de l''utilisation de parfums : sur des tablettes cunéiformes en Mésopotamie', 3000, false, NULL, 'Des tablettes cunéiformes sumériennes mentionnent l''utilisation de parfums et d''encens dans les rituels religieux et les offrandes aux dieux. Ces écrits témoignent de l''importance des fragrances dans la culture mésopotamienne et de leur influence sur les pratiques égyptiennes.', 'L''histoire du parfum : De l''Égypte antique aux fragrances contemporaines', '', 'PENDING', '', '2026-03-04 07:23:47.442367+00', NULL, NULL, NULL, ''),
	(1580, 'Construction du laboratoire de parfum d''Edfou : dédié à la production de fragrances rituelles', 2300, false, NULL, 'Un laboratoire de parfum est construit dans le temple d''Edfou en Égypte, dédié à la production de fragrances utilisées dans les rituels religieux et les offrandes aux dieux. Les inscriptions sur les murs du laboratoire décrivent les recettes et les techniques de fabrication des parfums.', 'L''histoire du parfum : De l''Égypte antique aux fragrances contemporaines', '', 'PENDING', '', '2026-03-04 07:23:47.442367+00', NULL, NULL, NULL, ''),
	(1581, 'Cléopâtre utilise des parfums pour impressionner Marc Antoine : lors de leur rencontre à Tarse', 41, false, NULL, 'Cléopâtre VII utilise des parfums exotiques et coûteux pour impressionner Marc Antoine lors de leur rencontre à Tarse. Elle parfume son navire et son palais, créant une atmosphère de luxe et de séduction qui contribue à son pouvoir politique et personnel.', 'L''histoire du parfum : De l''Égypte antique aux fragrances contemporaines', '', 'PENDING', '', '2026-03-04 07:23:47.442367+00', NULL, NULL, NULL, ''),
	(1582, 'Destruction du temple de Dendérah : fin de la production de parfums rituels à grande échelle', 30, false, NULL, 'Avec la conquête romaine de l''Égypte, le temple de Dendérah, un centre important de production de parfums rituels, est détruit. Cela marque un déclin de la production de parfums à grande échelle selon les méthodes traditionnelles égyptiennes.', 'L''histoire du parfum : De l''Égypte antique aux fragrances contemporaines', '', 'PENDING', '', '2026-03-04 07:23:47.442367+00', NULL, NULL, NULL, ''),
	(1583, 'Première mention écrite de l''alambic par Jabir Ibn Hayyan dans son ''Livre de la Composition de l''Alchimie''', 800, false, NULL, 'Ce traité marque une étape cruciale dans le développement des techniques de distillation, essentielles à la parfumerie. L''alambic permet d''extraire les essences des plantes avec une pureté accrue.', 'L''histoire du parfum : De l''Égypte antique aux fragrances contemporaines', '', 'PENDING', '', '2026-03-04 07:23:47.442367+00', NULL, NULL, NULL, ''),
	(1584, 'Publication du ''Livre des secrets de Maître Alexis le Piémontais'', un recueil de recettes de parfums et cosmétiques', 1555, false, NULL, 'Ce livre, traduit dans plusieurs langues, contribue à la diffusion des connaissances sur la parfumerie et les cosmétiques à travers l''Europe. Il témoigne de l''intérêt croissant pour l''hygiène et la beauté.', 'L''histoire du parfum : De l''Égypte antique aux fragrances contemporaines', '', 'PENDING', '', '2026-03-04 07:23:47.442367+00', NULL, NULL, NULL, ''),
	(1585, 'Établissement de la corporation des gantiers-parfumeurs à Grasse', 1724, false, NULL, 'La reconnaissance officielle de la corporation marque l''importance croissante de l''industrie du parfum à Grasse. Elle réglemente la production et la vente de parfums et de gants parfumés.', 'L''histoire du parfum : De l''Égypte antique aux fragrances contemporaines', '', 'PENDING', '', '2026-03-04 07:23:47.442367+00', NULL, NULL, NULL, ''),
	(1586, 'Acquisition de Givaudan par Roche', 1963, false, NULL, 'Roche acquiert Givaudan, consolidant sa position dans l''industrie des arômes et parfums. Cette acquisition marque une étape importante dans l''histoire de Givaudan.', 'L''histoire du parfum : De l''Égypte antique aux fragrances contemporaines', '', 'PENDING', '', '2026-03-04 07:23:47.442367+00', NULL, NULL, NULL, ''),
	(1587, 'Création du Comité Olympique National (CON) du Japon', 1911, false, NULL, 'Le Japon établit son Comité Olympique National, signalant son engagement croissant envers le mouvement olympique international. Cette création ouvre la voie à la participation du Japon aux Jeux olympiques de Stockholm en 1912.', 'L''histoire des Jeux Olympiques Modernes : Des Jeux d''Athènes au spectacle mondialisé (1896-2012)', '', 'PENDING', '', '2026-03-04 07:23:47.442367+00', NULL, NULL, NULL, ''),
	(1588, 'Commercialisation de la carte VGA, améliorant significativement l''affichage graphique sur PC', 1987, false, NULL, 'IBM introduit la carte VGA (Video Graphics Array), offrant une résolution et une palette de couleurs améliorées par rapport aux normes précédentes. Elle devient rapidement le standard pour l''affichage graphique sur PC.', 'L''histoire des ordinateurs personnels : De l''Altair 8800 à l''iPhone (1975-2007)', '', 'PENDING', '', '2026-03-04 07:23:47.442367+00', NULL, NULL, NULL, ''),
	(1589, 'Sortie de l''album "Highway 61 Revisited" de Bob Dylan', 1965, false, NULL, 'Bob Dylan sort l''album "Highway 61 Revisited", qui marque une étape importante dans l''évolution du rock. L''album inclut la chanson "Like a Rolling Stone", un succès majeur et un titre phare du rock.', 'L''histoire du rock : Des racines blues à l''ère du streaming (1950-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.442367+00', NULL, NULL, NULL, ''),
	(1590, 'Première diffusion de l''opéra rock "Tommy" par The Who au Grand Opera House de Leeds', 1969, false, NULL, 'L''événement marque une étape importante dans l''évolution du rock vers des formes narratives plus ambitieuses. "Tommy" est considéré comme l''un des premiers et des plus influents opéras rock.', 'L''histoire du rock : Des racines blues à l''ère du streaming (1950-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.442367+00', NULL, NULL, NULL, ''),
	(1591, 'Sortie de l''album "Horses" de Patti Smith', 1975, false, NULL, 'Cet album est un mélange de poésie et de rock. Il est considéré comme un jalon du punk rock et du new wave.', 'L''histoire du rock : Des racines blues à l''ère du streaming (1950-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.442367+00', NULL, NULL, NULL, ''),
	(1592, 'Sortie de l''album "Pyromania" de Def Leppard', 1983, false, NULL, 'L''album "Pyromania" propulse Def Leppard au sommet des charts et contribue à populariser le hard rock mélodique auprès d''un large public grâce à des singles diffusés massivement sur MTV. Il marque un tournant dans la carrière du groupe.', 'L''histoire du rock : Des racines blues à l''ère du streaming (1950-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.442367+00', NULL, NULL, NULL, ''),
	(1593, 'Première diffusion du clip "Smells Like Teen Spirit" sur MTV', 1991, false, NULL, 'Le clip de "Smells Like Teen Spirit" de Nirvana est diffusé pour la première fois sur MTV, contribuant à populariser le grunge auprès d''un public plus large. La chanson devient un hymne pour la génération X.', 'L''histoire du rock : Des racines blues à l''ère du streaming (1950-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.442367+00', NULL, NULL, NULL, ''),
	(1594, 'Publication du roman "The Grapes of Wrath" de John Steinbeck', 1939, false, NULL, 'Ce roman emblématique dépeint les difficultés des migrants de l''Oklahoma fuyant la Dust Bowl vers la Californie via la Route 66. Il popularise la route et met en lumière les réalités sociales de l''époque.', 'L''épopée de la Route 66 : De la poussière des pionniers à l''asphalte de la légende (1926-1985)', '', 'PENDING', '', '2026-03-04 07:23:47.442367+00', NULL, NULL, NULL, ''),
	(1595, 'Première apparition du Red''s Giant Hamburg à Springfield, Missouri', 1947, false, NULL, 'Red''s Giant Hamburg, l''un des premiers restaurants drive-in, ouvre ses portes et popularise le hamburger géant. Il incarne la culture de la restauration rapide en bord de route.', 'L''épopée de la Route 66 : De la poussière des pionniers à l''asphalte de la légende (1926-1985)', '', 'PENDING', '', '2026-03-04 07:23:47.442367+00', NULL, NULL, NULL, ''),
	(1596, 'Création du Homebrew Computer Club', 1975, false, NULL, 'Les premiers passionnés de l''Altair 8800 se réunissent pour former le Homebrew Computer Club. Ce club joue un rôle crucial dans le développement de l''informatique personnelle.', '', '', 'PENDING', '', '2026-03-04 07:23:47.442367+00', NULL, NULL, NULL, ''),
	(1599, 'Présentation de la section d''impression de la machine analytique de Babbage par son fils, Henry Babbage, à la British Association', 1888, false, NULL, 'Henry Babbage démontre une partie de la machine analytique, la section d''impression, prouvant ainsi la viabilité des concepts de son père. C''est une démonstration publique du fonctionnement partiel de la machine.', 'L''histoire de l''informatique : Du boulier à l''internet quantique (1623-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.442367+00', NULL, NULL, NULL, ''),
	(1600, 'Introduction du thé au Japon par le moine Eisai (1191)', 1191, false, NULL, 'Le moine bouddhiste Eisai rapporte des graines de thé de Chine au Japon. Il promeut la culture du thé et ses bienfaits pour la santé, contribuant à son adoption par l''élite japonaise.', 'L''histoire du thé : De la légende chinoise au phénomène mondial (2737 AEC - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.442367+00', NULL, NULL, NULL, ''),
	(1601, 'Première vente publique de thé à Londres par Thomas Garway (1657)', 1657, false, NULL, 'Thomas Garway, un cafetier londonien, est le premier à vendre publiquement du thé à Londres. Cet événement marque le début de la popularisation du thé en Angleterre.', 'L''histoire du thé : De la légende chinoise au phénomène mondial (2737 AEC - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.442367+00', NULL, NULL, NULL, ''),
	(1602, 'Construction du temple de la source du thé (Chayuan Si) au mont Tianzhu', 742, false, NULL, 'Le temple de la source du thé (Chayuan Si) est construit au mont Tianzhu. Il devient un centre important pour la culture du thé et la diffusion des connaissances sur ses bienfaits spirituels et médicinaux.', 'L''histoire du thé : De la légende chinoise au phénomène mondial (2737 AEC - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.442367+00', NULL, NULL, NULL, ''),
	(1603, 'Catherine de Bragance popularise la consommation de thé à la cour d''Angleterre', 1662, false, NULL, 'L''épouse portugaise de Charles II, Catherine de Bragance, introduit et popularise la consommation de thé à la cour royale anglaise, contribuant à son adoption par l''aristocratie.', 'L''histoire du thé : De la légende chinoise au phénomène mondial (2737 AEC - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.442367+00', NULL, NULL, NULL, ''),
	(1604, 'Lancement du sachet de thé en mousseline par Teekanne en Allemagne', 1929, false, NULL, 'L''entreprise allemande Teekanne introduit le sachet de thé en mousseline, une alternative plus hygiénique et pratique aux sachets en soie ou en papier utilisés jusqu''alors. Cela contribue à populariser davantage le sachet de thé en Europe.', 'L''histoire du thé : De la légende chinoise au phénomène mondial (2737 AEC - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.442367+00', NULL, NULL, NULL, ''),
	(1605, 'Ouverture du premier salon de thé "Cha Yuan" à Pékin', 1979, false, NULL, 'Le premier salon de thé moderne, "Cha Yuan", ouvre ses portes à Pékin, marquant un renouveau de la culture du thé en Chine après la Révolution culturelle. Il offre une variété de thés et de cérémonies traditionnelles.', 'L''histoire du thé : De la légende chinoise au phénomène mondial (2737 AEC - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.442367+00', NULL, NULL, NULL, ''),
	(1606, 'Publication du ''Bahir'', un des premiers textes majeurs de la Kabbale', 1170, false, NULL, 'Le ''Bahir'' introduit des concepts clés comme les Sephirot et la réincarnation, influençant profondément la pensée mystique juive. Son origine exacte et son auteur restent sujets à débat.', 'L''Histoire des Religions : De la fondation des religions abrahamiques au développement des courants mystiques (1800 AEC - 1500)', '', 'PENDING', '', '2026-03-04 07:23:47.442367+00', NULL, NULL, NULL, ''),
	(1607, 'Traduction du ''Zohar'' en latin par Flavius Mithridates', 1480, false, NULL, 'Flavius Mithridates traduit des extraits du ''Zohar'' en latin pour le compte de Pic de la Mirandole. Cette traduction contribue à introduire les idées kabbalistiques dans la pensée de la Renaissance.', 'L''Histoire des Religions : De la fondation des religions abrahamiques au développement des courants mystiques (1800 AEC - 1500)', '', 'PENDING', '', '2026-03-04 07:23:47.442367+00', NULL, NULL, NULL, ''),
	(1608, 'Publication de l''ouvrage "De l''Esprit des Lois" de Montesquieu', 1748, false, NULL, 'Montesquieu publie "De l''Esprit des Lois", un ouvrage majeur qui influence la pensée politique et juridique. Il aborde notamment la question de l''esclavage et de la séparation des pouvoirs.', 'La Traite Transatlantique : Du commerce triangulaire à l''abolition (1500-1888)', '', 'PENDING', '', '2026-03-04 07:23:47.442367+00', NULL, NULL, NULL, ''),
	(1609, 'Construction de Koumbi Saleh, plaque tournante du commerce de l''or au Ghana', 750, false, NULL, 'Koumbi Saleh devient un centre majeur pour le commerce de l''or, attirant des marchands de toute l''Afrique du Nord et du Moyen-Orient. La ville prospère grâce à son rôle central dans le commerce transsaharien.', 'Les routes caravanières transsahariennes : Du commerce de l''or et du sel aux empires du Sahel (300 - 1600)', '', 'PENDING', '', '2026-03-04 07:23:47.442367+00', NULL, NULL, NULL, ''),
	(1610, 'Ibn Hawqal visite Audaghost et décrit le commerce de l''or avec le Ghana', 977, false, NULL, 'Le géographe arabe Ibn Hawqal visite Audaghost, un important centre commercial, et décrit en détail le commerce de l''or avec le Ghana. Son récit fournit des informations précieuses sur les routes commerciales et les pratiques de l''époque.', 'Les routes caravanières transsahariennes : Du commerce de l''or et du sel aux empires du Sahel (300 - 1600)', '', 'PENDING', '', '2026-03-04 07:23:47.442367+00', NULL, NULL, NULL, ''),
	(1611, 'Mention du dromadaire dans le papyrus P.Vindob.G 29788, témoignant de son utilisation en Égypte', 324, false, NULL, 'Ce papyrus est l''une des premières preuves écrites de l''utilisation du dromadaire pour le transport et le travail en Égypte. Il marque une étape importante dans l''intégration de cet animal dans l''économie locale.', 'Les routes caravanières transsahariennes : Du commerce de l''or et du sel aux empires du Sahel (300 - 1600)', '', 'PENDING', '', '2026-03-04 07:23:47.442367+00', NULL, NULL, NULL, ''),
	(1612, 'Introduction du dromadaire en Mauritanie, facilitant le commerce transsaharien', 400, false, NULL, 'L''arrivée du dromadaire en Mauritanie révolutionne le transport à travers le Sahara. Il permet d''établir des routes commerciales plus régulières et efficaces, stimulant les échanges entre l''Afrique du Nord et l''Afrique subsaharienne.', 'Les routes caravanières transsahariennes : Du commerce de l''or et du sel aux empires du Sahel (300 - 1600)', '', 'PENDING', '', '2026-03-04 07:23:47.442367+00', NULL, NULL, NULL, ''),
	(1613, 'Première description détaillée du dromadaire dans l''encyclopédie ''De Natura Animalium'' d''Isidore de Séville', 636, false, NULL, 'Isidore de Séville inclut une description du dromadaire dans son encyclopédie, contribuant à la diffusion des connaissances sur cet animal en Europe. Il souligne son importance comme bête de somme et moyen de transport.', 'Les routes caravanières transsahariennes : Du commerce de l''or et du sel aux empires du Sahel (300 - 1600)', '', 'PENDING', '', '2026-03-04 07:23:47.442367+00', NULL, NULL, NULL, ''),
	(1614, 'Construction du barrage de Marib au Yémen, nécessitant l''emploi massif de dromadaires pour le transport des matériaux', 750, false, NULL, 'La construction de ce barrage témoigne de l''importance du dromadaire dans les grands projets d''infrastructure. Son endurance et sa capacité à transporter des charges lourdes sont essentielles pour acheminer les matériaux nécessaires.', 'Les routes caravanières transsahariennes : Du commerce de l''or et du sel aux empires du Sahel (300 - 1600)', '', 'PENDING', '', '2026-03-04 07:23:47.442367+00', NULL, NULL, NULL, ''),
	(1615, 'Construction de la Mosquée de Kilwa Kisiwani', 1000, false, NULL, 'Début de la construction de la Mosquée de Kilwa Kisiwani, un important centre commercial sur la côte swahilie, témoignant de la diffusion de l''islam et de l''essor du commerce maritime dans l''océan Indien.', 'Les routes caravanières transsahariennes : Du commerce de l''or et du sel aux empires du Sahel (300 - 1600)', '', 'PENDING', '', '2026-03-04 07:23:47.454234+00', NULL, NULL, NULL, ''),
	(1616, 'Interdiction des armes à Okinawa par le roi Shōshin', 1477, false, NULL, 'Le roi Shōshin d''Okinawa interdit les armes, contribuant au développement des arts martiaux à mains nues. Cette interdiction est un facteur clé dans l''évolution du karaté.', 'L''histoire des Arts Martiaux : Du Shaolin à l''UFC (500-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.454234+00', NULL, NULL, NULL, ''),
	(1617, 'Démonstration de taekwondo devant le président sud-coréen Syngman Rhee', 1954, false, NULL, 'Une démonstration de taekwondo est organisée devant le président Syngman Rhee, impressionné par les techniques. Cet événement contribue à la reconnaissance et au soutien gouvernemental du taekwondo.', 'L''histoire des Arts Martiaux : Du Shaolin à l''UFC (500-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.454234+00', NULL, NULL, NULL, ''),
	(1618, 'Adoption du nom ''Taekwondo'' par l''Association coréenne de taekwondo', 1965, false, NULL, 'Le nom ''Taekwondo'' est officiellement adopté par la KTA, remplaçant les anciens noms et consolidant l''identité de cet art martial coréen. Cela marque une étape importante dans son développement.', 'L''histoire des Arts Martiaux : Du Shaolin à l''UFC (500-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.454234+00', NULL, NULL, NULL, ''),
	(1619, 'Première diffusion de ''The Ultimate Fighter'' (TUF)', 2005, false, NULL, 'La première saison de l''émission de télé-réalité ''The Ultimate Fighter'' est diffusée sur Spike TV. Le succès de l''émission sauve l''UFC de la faillite et attire un nouveau public.', 'L''histoire des Arts Martiaux : Du Shaolin à l''UFC (500-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.454234+00', NULL, NULL, NULL, ''),
	(1620, 'Consécration de l''autel majeur de l''abbatiale de Saint-Martial de Limoges', 1095, false, NULL, 'Cet événement marque une étape importante dans le développement de la musique liturgique et potentiellement de la polyphonie primitive à Saint-Martial. L''abbaye était un centre majeur de composition musicale.', 'L''Histoire de la Musique Classique Occidentale : Du chant grégorien à la musique contemporaine (900 - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.454234+00', NULL, NULL, NULL, ''),
	(1621, 'Première mention connue du compositeur Léonin (Magister Leoninus)', 1169, false, NULL, 'Léonin, chanoine de Notre-Dame de Paris, est l''un des premiers compositeurs de polyphonie dont le nom nous soit parvenu. Il est associé au développement du Magnus Liber Organi.', 'L''Histoire de la Musique Classique Occidentale : Du chant grégorien à la musique contemporaine (900 - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.454234+00', NULL, NULL, NULL, ''),
	(1622, 'Élection de l''évêque Wido à Arezzo', 1023, false, NULL, 'Wido d''Arezzo, plus connu sous le nom de Guido d''Arezzo, est un moine bénédictin italien du Moyen Âge. Il est considéré comme le père de la notation musicale moderne.', 'L''Histoire de la Musique Classique Occidentale : Du chant grégorien à la musique contemporaine (900 - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.454234+00', NULL, NULL, NULL, ''),
	(1623, 'Josquin Des Prez devient maître de chapelle à la cour de Louis XII', 1504, false, NULL, 'Cette nomination prestigieuse confirme la renommée de Josquin Des Prez comme l''un des plus grands compositeurs de son époque. Il compose alors des œuvres pour la cour royale française.', 'L''Histoire de la Musique Classique Occidentale : Du chant grégorien à la musique contemporaine (900 - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.454234+00', NULL, NULL, NULL, ''),
	(1624, 'Publication du "Concerto grosso" Op. 6 d''Arcangelo Corelli', 1714, false, NULL, 'Publication posthume à Amsterdam du recueil de douze concertos grossos d''Arcangelo Corelli. Ces œuvres ont une influence majeure sur le développement du concerto baroque.', 'L''Histoire de la Musique Classique Occidentale : Du chant grégorien à la musique contemporaine (900 - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.454234+00', NULL, NULL, NULL, ''),
	(1625, 'Traduction latine de l''Almageste par Gérard de Crémone', 1175, false, NULL, 'Gérard de Crémone traduit l''Almageste de l''arabe vers le latin à Tolède, en Espagne. Cette traduction rend l''œuvre de Ptolémée accessible aux érudits européens et contribue à la Renaissance du XIIe siècle.', 'L''histoire de l''astronomie : Des observations à l''œil nu aux télescopes spatiaux (300 AEC - 1990)', '', 'PENDING', '', '2026-03-04 07:23:47.454234+00', NULL, NULL, NULL, ''),
	(1626, 'Publication de l''« Epitome de l''Almageste » par Regiomontanus', 1496, false, NULL, 'Johannes Müller von Königsberg, dit Regiomontanus, publie un résumé commenté de l''Almageste. Cet ouvrage contribue à la diffusion et à la compréhension de l''astronomie ptolémaïque avant l''avènement de la révolution copernicienne.', 'L''histoire de l''astronomie : Des observations à l''œil nu aux télescopes spatiaux (300 AEC - 1990)', '', 'PENDING', '', '2026-03-04 07:23:47.454234+00', NULL, NULL, NULL, ''),
	(1627, 'Inauguration du télescope de 72 pouces de Lord Rosse à Birr Castle', 1845, false, NULL, 'Le ''Leviathan de Parsonstown'', le plus grand télescope du monde à l''époque, permet d''observer la structure spirale de certaines nébuleuses. Il marque une étape importante dans l''étude des galaxies.', 'L''histoire de l''astronomie : Des observations à l''œil nu aux télescopes spatiaux (300 AEC - 1990)', '', 'PENDING', '', '2026-03-04 07:23:47.454234+00', NULL, NULL, NULL, ''),
	(1628, 'Première photographie d''un spectre stellaire par William Huggins', 1864, false, NULL, 'Huggins utilise la spectroscopie pour analyser la composition chimique des étoiles, confirmant qu''elles sont composées d''éléments similaires à ceux trouvés sur Terre. Il ouvre la voie à l''astrophysique.', 'L''histoire de l''astronomie : Des observations à l''œil nu aux télescopes spatiaux (300 AEC - 1990)', '', 'PENDING', '', '2026-03-04 07:23:47.454234+00', NULL, NULL, NULL, ''),
	(1629, 'Annonce du procédé du collodion humide par Frederick Scott Archer', 1851, false, NULL, 'Le sculpteur et photographe britannique Frederick Scott Archer publie sa découverte du procédé au collodion humide. Ce procédé, plus rapide et moins coûteux que le daguerréotype, révolutionne la photographie.', 'L''histoire de la photographie : Des premiers daguerréotypes aux selfies numériques (1826-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.454234+00', NULL, NULL, NULL, ''),
	(1630, 'Ouverture du studio de photographie de Nadar à Paris', 1854, false, NULL, 'Gaspard-Félix Tournachon, connu sous le nom de Nadar, ouvre son célèbre studio de photographie à Paris. Il devient rapidement un portraitiste renommé, photographiant de nombreuses personnalités de l''époque.', 'L''histoire de la photographie : Des premiers daguerréotypes aux selfies numériques (1826-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.454234+00', NULL, NULL, NULL, ''),
	(1631, 'Commercialisation du film couleur instantané Polacolor par Polaroid', 1963, false, NULL, 'Polaroid lance le film couleur instantané Polacolor, permettant de réaliser des photos couleur instantanées. Cette innovation majeure élargit considérablement les possibilités créatives de la photographie instantanée.', 'L''histoire de la photographie : Des premiers daguerréotypes aux selfies numériques (1826-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.454234+00', NULL, NULL, NULL, ''),
	(1632, 'Richard Arkwright dépose le brevet du ''water frame'', machine à filer le coton utilisant l''énergie hydraulique', 1769, false, NULL, 'Ce brevet marque une étape cruciale dans la mécanisation de la filature du coton. Le ''water frame'' permet une production plus rapide et de meilleure qualité, contribuant à la révolution industrielle.', 'La Révolution Industrielle : Des machines à vapeur à la production de masse (1760-1914)', '', 'PENDING', '', '2026-03-04 07:23:47.454234+00', NULL, NULL, NULL, ''),
	(1633, 'Présentation du Biograph (caméra) par William Kennedy Laurie Dickson et Elias Koopman à New York', 1896, false, NULL, 'Dickson et Koopman, après avoir quitté Edison, présentent leur propre système de caméra et de projection. Le Biograph devient un concurrent majeur du cinématographe Lumière.', 'L''histoire du cinéma : Des premières projections aux blockbusters hollywoodiens (1895 - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.454234+00', NULL, NULL, NULL, ''),
	(1634, 'Sortie du film "Naissance d''une nation" de D.W. Griffith', 1915, false, NULL, 'Ce film, bien que controversé pour son contenu raciste, est un jalon technique majeur. Il établit de nouvelles normes pour la narration cinématographique et la longueur des films.', 'L''histoire du cinéma : Des premières projections aux blockbusters hollywoodiens (1895 - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.454234+00', NULL, NULL, NULL, ''),
	(1635, 'Première diffusion du film Autant en emporte le vent (Gone with the Wind), fresque historique et mélodrame', 1939, false, NULL, 'Produit par David O. Selznick, le film est une adaptation du roman de Margaret Mitchell. Il remporte un succès colossal et marque l''apogée du cinéma hollywoodien classique.', 'L''histoire du cinéma : Des premières projections aux blockbusters hollywoodiens (1895 - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.454234+00', NULL, NULL, NULL, ''),
	(1636, 'Adam de Brême mentionne le Vinland dans son ''Histoire des archevêques de Hambourg''', 1075, false, NULL, 'Adam de Brême mentionne le Vinland dans son ouvrage, fournissant l''une des premières descriptions écrites de la découverte de l''Amérique du Nord par les Vikings. Son récit contribue à la diffusion de la connaissance des explorations vikings.', 'L''Ascension et la Chute des Vikings : Pillages, Commerce et Exploration (793-1066)', '', 'PENDING', '', '2026-03-04 07:23:47.454234+00', NULL, NULL, NULL, ''),
	(1637, 'Construction du dernier stèle datée à Toniná', 909, false, NULL, 'La dernière stèle datée est érigée à Toniná, marquant la fin de la tradition d''enregistrement calendaire dans cette cité maya. Cela coïncide avec le déclin général de la civilisation maya classique.', 'L''effondrement des civilisations précolombiennes : Des Mayas aux Incas', '', 'PENDING', '', '2026-03-04 07:23:47.454234+00', NULL, NULL, NULL, ''),
	(1638, 'Dernière date inscrite au site de Xultún', 889, false, NULL, 'La dernière date inscrite est relevée à Xultún, indiquant une cessation de l''activité calendaire. Xultún est connu pour ses peintures murales et ses inscriptions.', 'L''effondrement des civilisations précolombiennes : Des Mayas aux Incas', '', 'PENDING', '', '2026-03-04 07:23:47.454234+00', NULL, NULL, NULL, ''),
	(1639, 'Construction du temple de Tlahuizcalpantecuhtli (Étoile du Matin) à Tula', 950, false, NULL, 'Début de la construction du temple dédié à l''Étoile du Matin, une divinité importante du panthéon toltèque. Le temple est orné de statues monumentales d''Atlantes.', 'L''effondrement des civilisations précolombiennes : Des Mayas aux Incas', '', 'PENDING', '', '2026-03-04 07:23:47.454234+00', NULL, NULL, NULL, ''),
	(1640, 'Sortie de "Computer Space", le premier jeu vidéo d''arcade commercialisé à grande échelle', 1971, false, NULL, '"Computer Space", conçu par Nolan Bushnell et Ted Dabney, est distribué par Nutting Associates. Il marque une étape importante dans la commercialisation des jeux vidéo.', 'L''histoire des jeux vidéo : Du Pong aux mondes virtuels immersifs', '', 'PENDING', '', '2026-03-04 07:23:47.454234+00', NULL, NULL, NULL, ''),
	(1641, 'Consécration du nouveau chœur de l''abbatiale de Saint-Denis', 1144, false, NULL, 'Le 11 juin 1144, le nouveau chœur de l''abbatiale de Saint-Denis, symbole de l''émergence du style gothique, est consacré en présence du roi Louis VII.', 'La construction des cathédrales gothiques : De Saint-Denis à Notre-Dame de Chartres (1140-1500)', '', 'PENDING', '', '2026-03-04 07:23:47.454234+00', NULL, NULL, NULL, ''),
	(1642, 'Installation des vitraux dans le déambulatoire de Saint-Denis', 1144, false, NULL, 'Les vitraux colorés, une caractéristique distinctive du style gothique, sont installés dans le déambulatoire de Saint-Denis, illuminant l''espace sacré.', 'La construction des cathédrales gothiques : De Saint-Denis à Notre-Dame de Chartres (1140-1500)', '', 'PENDING', '', '2026-03-04 07:23:47.454234+00', NULL, NULL, NULL, ''),
	(1643, 'Achèvement de la chapelle Sainte-Marie à Saint-Denis', 1140, false, NULL, 'La chapelle Sainte-Marie, intégrée au complexe de Saint-Denis, est achevée, contribuant à l''ensemble architectural novateur de l''époque.', 'La construction des cathédrales gothiques : De Saint-Denis à Notre-Dame de Chartres (1140-1500)', '', 'PENDING', '', '2026-03-04 07:23:47.454234+00', NULL, NULL, NULL, ''),
	(1644, 'Consécration de la cathédrale de Sens, première cathédrale gothique de France', 1164, false, NULL, 'La cathédrale de Sens est consacrée, marquant une étape majeure dans l''évolution de l''architecture gothique. Elle sert de modèle pour les constructions ultérieures.', 'La construction des cathédrales gothiques : De Saint-Denis à Notre-Dame de Chartres (1140-1500)', '', 'PENDING', '', '2026-03-04 07:23:47.454234+00', NULL, NULL, NULL, ''),
	(1645, 'Consécration du chœur de la cathédrale de Reims', 1241, false, NULL, 'Le chœur de la cathédrale de Reims, reconstruit dans le style gothique rayonnant, est consacré. Cet événement marque une étape importante dans la reconstruction de l''édifice.', 'La construction des cathédrales gothiques : De Saint-Denis à Notre-Dame de Chartres (1140-1500)', '', 'PENDING', '', '2026-03-04 07:23:47.454234+00', NULL, NULL, NULL, ''),
	(1646, 'Achèvement de la nef de la cathédrale de Reims', 1275, false, NULL, 'La nef de la cathédrale de Reims est achevée, marquant une étape significative dans la reconstruction de l''édifice après l''incendie de 1210. Elle illustre pleinement le style gothique rayonnant.', 'La construction des cathédrales gothiques : De Saint-Denis à Notre-Dame de Chartres (1140-1500)', '', 'PENDING', '', '2026-03-04 07:23:47.454234+00', NULL, NULL, NULL, ''),
	(1647, 'Consécration de l''autel majeur de la cathédrale de Chartres', 1260, false, NULL, 'L''autel majeur de la cathédrale de Chartres est consacré en présence du roi Louis IX (Saint Louis), marquant une étape importante dans l''achèvement de la cathédrale.', 'La construction des cathédrales gothiques : De Saint-Denis à Notre-Dame de Chartres (1140-1500)', '', 'PENDING', '', '2026-03-04 07:23:47.454234+00', NULL, NULL, NULL, ''),
	(1648, 'Translation des reliques de Saint Lubin à la cathédrale de Chartres', 1196, false, NULL, 'Les reliques de Saint Lubin, évêque de Chartres au VIe siècle, sont solennellement transférées dans la nouvelle cathédrale en construction, renforçant son importance spirituelle.', 'La construction des cathédrales gothiques : De Saint-Denis à Notre-Dame de Chartres (1140-1500)', '', 'PENDING', '', '2026-03-04 07:23:47.454234+00', NULL, NULL, NULL, ''),
	(1649, 'Consécration de la Sainte-Chapelle de Riom', 1396, false, NULL, 'La Sainte-Chapelle de Riom, commandée par Jean de Berry, est un exemple précoce du gothique flamboyant en Auvergne. Elle témoigne du rayonnement artistique de la cour ducale.', 'La construction des cathédrales gothiques : De Saint-Denis à Notre-Dame de Chartres (1140-1500)', '', 'PENDING', '', '2026-03-04 07:23:47.454234+00', NULL, NULL, NULL, ''),
	(1650, 'Sack de Tombouctou par les Mossi', 1333, false, NULL, 'Les Mossi, venant du sud, pillent Tombouctou, marquant une période d''instabilité croissante pour l''Empire du Mali. Cet événement révèle les faiblesses de l''empire face aux raids extérieurs.', 'L''essor des civilisations de l''Afrique de l''Ouest : Du royaume du Ghana à l''empire du Mali (300-1670)', '', 'PENDING', '', '2026-03-04 07:23:47.454234+00', NULL, NULL, NULL, ''),
	(1651, 'Début du règne de Mansa Musa II', 1387, false, NULL, 'Mansa Musa II accède au trône de l''Empire du Mali, succédant à Mansa Mahmud II. Son règne est marqué par une continuation du déclin de l''empire.', 'L''essor des civilisations de l''Afrique de l''Ouest : Du royaume du Ghana à l''empire du Mali (300-1670)', '', 'PENDING', '', '2026-03-04 07:23:47.454234+00', NULL, NULL, NULL, ''),
	(1652, 'Première mention officielle de la Route de la Soie dans les chroniques chinoises (Hanshu)', 94, false, NULL, 'Le Hanshu (Livre des Han), une chronique historique couvrant la dynastie des Han occidentaux, mentionne pour la première fois les routes commerciales vers l''Ouest, consolidant l''existence de la Route de la Soie.', 'L''Histoire de la Route de la Soie : Du commerce des caravanes à l''intégration mondiale (130 AEC - 1453)', '', 'PENDING', '', '2026-03-04 07:23:47.454234+00', NULL, NULL, NULL, ''),
	(1653, 'Construction du temple de Jokhang à Lhassa', 647, false, NULL, 'Le roi Songtsen Gampo du Tibet ordonne la construction du temple de Jokhang à Lhassa pour abriter des statues bouddhistes apportées par ses épouses, la princesse chinoise Wencheng et la princesse népalaise Bhrikuti. Le Jokhang devient le centre spirituel du Tibet.', 'L''Histoire de la Route de la Soie : Du commerce des caravanes à l''intégration mondiale (130 AEC - 1453)', '', 'PENDING', '', '2026-03-04 07:23:47.454234+00', NULL, NULL, NULL, ''),
	(1654, 'Création du Jiaozi, premier papier-monnaie officiel, par le gouvernement Song', 1024, false, NULL, 'Le Jiaozi est émis dans la région du Sichuan pour faciliter les échanges commerciaux et pallier le manque de métaux précieux. Il marque une étape cruciale dans l''histoire monétaire chinoise.', 'L''histoire des monnaies : Du troc à la blockchain (700 AEC - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.454234+00', NULL, NULL, NULL, ''),
	(1655, 'Établissement du Bureau de la Monnaie de Papier (Jiaozichhu) à Chengdu', 1024, false, NULL, 'Ce bureau est créé pour superviser l''émission et la gestion du Jiaozi, assurant ainsi un contrôle centralisé sur la nouvelle monnaie. Il marque une étape importante dans la reconnaissance officielle du papier-monnaie.', 'L''histoire des monnaies : Du troc à la blockchain (700 AEC - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.454234+00', NULL, NULL, NULL, ''),
	(1656, 'Introduction du Qianyin, un nouveau type de papier-monnaie, pour remplacer le Jiaozi', 1160, false, NULL, 'Le Qianyin est introduit en raison de la dépréciation du Jiaozi et des problèmes de contrefaçon. Il est initialement émis dans la région du Huainan et se propage ensuite à d''autres régions.', 'L''histoire des monnaies : Du troc à la blockchain (700 AEC - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.454234+00', NULL, NULL, NULL, ''),
	(1657, 'Boycott des Jeux olympiques de Montréal par 28 pays africains', 1976, false, NULL, 'Vingt-huit nations africaines boycottent les Jeux olympiques de Montréal pour protester contre la participation de la Nouvelle-Zélande, dont l''équipe de rugby avait effectué une tournée en Afrique du Sud, alors soumise à l''apartheid. Cet événement souligne la politisation croissante des Jeux.', 'L''histoire des Jeux Olympiques : Des origines antiques aux JO modernes (776 AEC - 2008)', '', 'PENDING', '', '2026-03-04 07:23:47.454234+00', NULL, NULL, NULL, ''),
	(1658, 'Début du boycott du clan de Mahomet par les Qurayshites', 617, false, NULL, 'Les Qurayshites, opposés à Mahomet, imposent un boycott économique et social au clan de Mahomet, les Hashim, et à ses partisans. Cette mesure vise à affaiblir la communauté musulmane naissante.', 'L''émergence et l''expansion de l''Islam : De la révélation à la construction des empires (610-1258)', '', 'PENDING', '', '2026-03-04 07:23:47.454234+00', NULL, NULL, NULL, ''),
	(1659, 'Achèvement de la traduction des œuvres de Galien par Hunayn ibn Ishaq', 873, false, NULL, 'Hunayn ibn Ishaq, médecin et traducteur, termine la traduction en arabe de l''ensemble des œuvres du médecin grec Galien. Ces traductions ont un impact majeur sur la médecine dans le monde islamique.', 'L''émergence et l''expansion de l''Islam : De la révélation à la construction des empires (610-1258)', '', 'PENDING', '', '2026-03-04 07:23:47.454234+00', NULL, NULL, NULL, ''),
	(1660, 'Construction de l''observatoire de Battani à Raqqa', 880, false, NULL, 'L''astronome et mathématicien Al-Battani établit un observatoire à Raqqa, en Syrie. Il y effectue des observations astronomiques précises qui contribuent significativement à l''avancement de l''astronomie.', 'L''émergence et l''expansion de l''Islam : De la révélation à la construction des empires (610-1258)', '', 'PENDING', '', '2026-03-04 07:23:47.454234+00', NULL, NULL, NULL, ''),
	(1661, 'Fondation du Sultanat de Delhi', 1206, false, NULL, 'Qutb-ud-din Aibak, un général turc, fonde le Sultanat de Delhi en Inde. Ce sultanat marque le début de la domination musulmane en Inde du Nord et l''introduction de la culture et de l''architecture islamiques dans la région.', 'L''émergence et l''expansion de l''Islam : De la révélation à la construction des empires (610-1258)', '', 'PENDING', '', '2026-03-04 07:23:47.454234+00', NULL, NULL, NULL, ''),
	(1662, 'Publication de ''The Influenza Pandemic of 1918'' par William Irwin Thompson, explorant l''impact culturel et spirituel de la grippe', 1981, false, NULL, 'William Irwin Thompson publie son livre analysant les conséquences de la grippe espagnole sur la société et la culture. L''ouvrage met en lumière les dimensions spirituelles et philosophiques de la pandémie.', 'Les grandes pandémies : De la grippe espagnole au SIDA (1918-1981)', '', 'PENDING', '', '2026-03-04 07:23:47.454234+00', NULL, NULL, NULL, ''),
	(1663, 'Publication de ''Voyage au centre de la Terre''', 1864, false, NULL, 'Jules Verne publie son roman ''Voyage au centre de la Terre'', marquant le début de son influence majeure dans la science-fiction et l''aventure. L''œuvre explore des thèmes scientifiques et géologiques imaginaires.', 'L''âge d''or de la science-fiction : De Verne à Asimov (1864-1992)', '', 'PENDING', '', '2026-03-04 07:23:47.454234+00', NULL, NULL, NULL, ''),
	(1664, 'Inauguration du Musée Jules Verne à Nantes', 1978, false, NULL, 'Le Musée Jules Verne ouvre ses portes à Nantes, ville natale de l''écrivain, pour célébrer sa vie et son œuvre. Le musée présente des manuscrits, des illustrations et des objets liés à ses romans.', 'L''âge d''or de la science-fiction : De Verne à Asimov (1864-1992)', '', 'PENDING', '', '2026-03-04 07:23:47.454234+00', NULL, NULL, NULL, ''),
	(1665, 'Lancement du satellite Jules Verne (ATV-1) par l''Agence spatiale européenne', 2008, false, NULL, 'L''Agence spatiale européenne lance le premier véhicule de transfert automatique (ATV), nommé Jules Verne, pour ravitailler la Station spatiale internationale. Ce lancement honore l''influence de Verne sur l''exploration spatiale.', 'L''âge d''or de la science-fiction : De Verne à Asimov (1864-1992)', '', 'PENDING', '', '2026-03-04 07:23:47.465816+00', NULL, NULL, NULL, ''),
	(1666, 'Publication de ''Slan'' d''A.E. van Vogt dans ''Astounding Science Fiction''', 1940, false, NULL, '''Slan'' est un roman de science-fiction qui a eu un impact significatif sur le genre. Il explore des thèmes de persécution et de différence, établissant van Vogt comme une figure majeure.', 'L''âge d''or de la science-fiction : De Verne à Asimov (1864-1992)', '', 'PENDING', '', '2026-03-04 07:23:47.465816+00', NULL, NULL, NULL, ''),
	(1667, 'Publication de ''Foundation'' d''Isaac Asimov dans ''Astounding Science Fiction''', 1942, false, NULL, 'La première histoire du cycle de Fondation, qui deviendra l''une des œuvres les plus célèbres d''Asimov. Elle introduit le concept de psychohistoire et pose les bases d''un empire galactique.', 'L''âge d''or de la science-fiction : De Verne à Asimov (1864-1992)', '', 'PENDING', '', '2026-03-04 07:23:47.465816+00', NULL, NULL, NULL, ''),
	(1668, 'Publication de ''The World of Null-A'' d''A.E. van Vogt', 1948, false, NULL, 'Ce roman complexe et influent explore des thèmes de logique non-aristotélicienne et de perception de la réalité. Il consolide la réputation de van Vogt pour ses intrigues labyrinthiques.', 'L''âge d''or de la science-fiction : De Verne à Asimov (1864-1992)', '', 'PENDING', '', '2026-03-04 07:23:47.465816+00', NULL, NULL, NULL, ''),
	(1669, 'Publication d''« I, Robot » d''Isaac Asimov', 1950, false, NULL, 'Publication du recueil de nouvelles qui établit les Trois Lois de la robotique et propulse Asimov au rang de figure majeure de la science-fiction. Cet ouvrage marque un tournant dans la perception des robots dans la culture populaire.', 'L''âge d''or de la science-fiction : De Verne à Asimov (1864-1992)', '', 'PENDING', '', '2026-03-04 07:23:47.465816+00', NULL, NULL, NULL, ''),
	(1670, 'Publication de « En panne sèche » de J. G. Ballard', 1962, false, NULL, 'Publication du roman dystopique qui explore les thèmes de la catastrophe environnementale et de la psychologie humaine. Il contribue à l''émergence de la New Wave en science-fiction.', 'L''âge d''or de la science-fiction : De Verne à Asimov (1864-1992)', '', 'PENDING', '', '2026-03-04 07:23:47.465816+00', NULL, NULL, NULL, ''),
	(1671, 'Publication de « Dune » de Frank Herbert', 1965, false, NULL, 'Publication du roman de science-fiction épique qui remporte le prix Hugo et le prix Nebula. « Dune » devient un classique du genre, influençant de nombreuses œuvres ultérieures.', 'L''âge d''or de la science-fiction : De Verne à Asimov (1864-1992)', '', 'PENDING', '', '2026-03-04 07:23:47.465816+00', NULL, NULL, NULL, ''),
	(1672, 'Première diffusion de ''Star Trek: The Original Series'' sur NBC', 1966, false, NULL, 'La série télévisée de science-fiction ''Star Trek'', créée par Gene Roddenberry, est diffusée pour la première fois. Elle présente une vision optimiste du futur et explore des questions sociales et philosophiques.', 'L''âge d''or de la science-fiction : De Verne à Asimov (1864-1992)', '', 'PENDING', '', '2026-03-04 07:23:47.465816+00', NULL, NULL, NULL, ''),
	(1673, 'Publication de ''Ubik'' par Philip K. Dick', 1969, false, NULL, 'Le roman de science-fiction ''Ubik'' de Philip K. Dick est publié. Il explore des thèmes de réalité, de perception et de technologie, et est considéré comme l''une de ses œuvres majeures.', 'L''âge d''or de la science-fiction : De Verne à Asimov (1864-1992)', '', 'PENDING', '', '2026-03-04 07:23:47.465816+00', NULL, NULL, NULL, ''),
	(1674, 'Publication de ''La Main gauche de la nuit'' par Ursula K. Le Guin', 1969, false, NULL, 'Le roman de science-fiction ''La Main gauche de la nuit'' d''Ursula K. Le Guin est publié. Il explore des thèmes de genre, de sexualité et de culture sur une planète où les habitants sont ambisexuels.', 'L''âge d''or de la science-fiction : De Verne à Asimov (1864-1992)', '', 'PENDING', '', '2026-03-04 07:23:47.465816+00', NULL, NULL, NULL, ''),
	(1675, 'Couronnement de Robert d''Anjou comme roi de Naples', 1309, false, NULL, 'Robert d''Anjou, un allié clé du pape, est couronné roi de Naples, marquant une étape importante dans l''influence angevine en Italie.', 'La Renaissance Italienne : Des cités-états à l''éclosion artistique et scientifique (1300-1600)', '', 'PENDING', '', '2026-03-04 07:23:47.465816+00', NULL, NULL, NULL, ''),
	(1676, 'Début du règne de Cangrande della Scala à Vérone', 1311, false, NULL, 'Cangrande della Scala devient seigneur de Vérone, inaugurant une période d''expansion et de prospérité pour la ville.', 'La Renaissance Italienne : Des cités-états à l''éclosion artistique et scientifique (1300-1600)', '', 'PENDING', '', '2026-03-04 07:23:47.465816+00', NULL, NULL, NULL, ''),
	(1677, 'Publication de l''édition illustrée de ''De re militari'' de Roberto Valturio à Vérone', 1483, false, NULL, 'Johannes Nicolai de Vérone publie une édition illustrée du traité militaire ''De re militari'' de Roberto Valturio. C''est un exemple précoce de livre technique illustré imprimé en Italie.', 'La Renaissance Italienne : Des cités-états à l''éclosion artistique et scientifique (1300-1600)', '', 'PENDING', '', '2026-03-04 07:23:47.465816+00', NULL, NULL, NULL, ''),
	(1678, 'Galilée commence à enseigner les mathématiques à l''Université de Pise', 1589, false, NULL, 'Galilée est nommé professeur de mathématiques à l''Université de Pise. C''est le début de sa carrière académique et de ses premières recherches sur le mouvement et la mécanique.', 'La Renaissance Italienne : Des cités-états à l''éclosion artistique et scientifique (1300-1600)', '', 'PENDING', '', '2026-03-04 07:23:47.465816+00', NULL, NULL, NULL, ''),
	(1679, 'Galilée accepte un poste de professeur de mathématiques à l''Université de Padoue', 1592, false, NULL, 'Galilée quitte l''Université de Pise pour un poste plus prestigieux à l''Université de Padoue. Il y restera pendant près de 18 ans, menant des recherches importantes en astronomie et en physique.', 'La Renaissance Italienne : Des cités-états à l''éclosion artistique et scientifique (1300-1600)', '', 'PENDING', '', '2026-03-04 07:23:47.465816+00', NULL, NULL, NULL, ''),
	(1680, 'Présentation du microprocesseur Intel 8086', 1978, false, NULL, 'Intel dévoile le 8086, un microprocesseur 16 bits. Il marque le début de l''architecture x86, qui domine encore aujourd''hui le marché des PC.', 'La révolution numérique : Du microprocesseur à l''intelligence artificielle (1971-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.465816+00', NULL, NULL, NULL, ''),
	(1681, 'Création du premier serveur web en Amérique du Nord au SLAC', 1991, false, NULL, 'Le Stanford Linear Accelerator Center (SLAC) met en place le premier serveur web en dehors de l''Europe, étendant ainsi la portée du World Wide Web à un nouveau continent.', 'La révolution numérique : Du microprocesseur à l''intelligence artificielle (1971-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.465816+00', NULL, NULL, NULL, ''),
	(1682, 'Publication du document "Project Xanadu" par Ted Nelson, préfigurant l''hypertexte et les moteurs de recherche', 1973, false, NULL, 'Ted Nelson publie son concept de "Project Xanadu", un système d''hypertexte global et structuré. Cette vision influence le développement futur des moteurs de recherche et du web.', 'La révolution numérique : Du microprocesseur à l''intelligence artificielle (1971-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.465816+00', NULL, NULL, NULL, ''),
	(1683, 'Lancement du service de messagerie Hotmail', 1996, false, NULL, 'Sabeer Bhatia et Jack Smith lancent Hotmail, l''un des premiers services de messagerie web gratuits. Il popularise l''accès à l''e-mail depuis n''importe quel ordinateur connecté.', 'La révolution numérique : Du microprocesseur à l''intelligence artificielle (1971-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.465816+00', NULL, NULL, NULL, ''),
	(1684, 'Découverte du rôle des rats dans la transmission de la peste par la Commission de la peste en Inde', 1907, false, NULL, 'La Commission de la peste en Inde confirme le rôle crucial des rats et de leurs puces dans la transmission de la peste bubonique. Cette découverte conduit à des mesures d''hygiène et de contrôle des populations de rongeurs pour prévenir les épidémies.', 'La construction du canal de Panama : Une aventure humaine, technologique et politique (1880-1914)', '', 'PENDING', '', '2026-03-04 07:23:47.465816+00', NULL, NULL, NULL, ''),
	(1685, 'Mise en service du barrage-écluse de Kachlet, intégrant une centrale hydroélectrique', 1907, false, NULL, 'Le barrage-écluse de Kachlet, sur le Rhin, est mis en service. Il combine une écluse pour la navigation fluviale et une centrale hydroélectrique pour la production d''électricité.', 'La construction du canal de Panama : Une aventure humaine, technologique et politique (1880-1914)', '', 'PENDING', '', '2026-03-04 07:23:47.465816+00', NULL, NULL, NULL, ''),
	(1686, 'Ouverture du canal de Kiel, doté d''écluses à double sas pour gérer le trafic maritime intense', 1895, false, NULL, 'Le canal de Kiel, reliant la mer du Nord à la mer Baltique, est ouvert à la navigation. Ses écluses à double sas permettent de gérer efficacement le trafic maritime important.', 'La construction du canal de Panama : Une aventure humaine, technologique et politique (1880-1914)', '', 'PENDING', '', '2026-03-04 07:23:47.465816+00', NULL, NULL, NULL, ''),
	(1687, 'Début du règne de Samudragupta : Expansion militaire et culturelle de l''Empire Gupta', 335, false, NULL, 'Samudragupta accède au trône et lance une série de campagnes militaires victorieuses, étendant considérablement l''influence de l''empire. Son règne est aussi marqué par un essor des arts et des sciences.', 'Les Dynasties Indiennes : De l''Empire Maurya à l''Empire Moghol (322 AEC - 1707)', '', 'PENDING', '', '2026-03-04 07:23:47.465816+00', NULL, NULL, NULL, ''),
	(1688, 'Construction des grottes d''Ajanta : Art bouddhique sous le patronage Gupta', 462, false, NULL, 'Début de la construction des grottes d''Ajanta, un ensemble de temples bouddhistes taillés dans la roche, sous le règne des Vakatakas, vassaux des Guptas. Elles témoignent de l''influence artistique et religieuse de l''époque.', 'Les Dynasties Indiennes : De l''Empire Maurya à l''Empire Moghol (322 AEC - 1707)', '', 'PENDING', '', '2026-03-04 07:23:47.465816+00', NULL, NULL, NULL, ''),
	(1761, 'Achèvement de la Grande Mosquée de Samarra', 851, false, NULL, 'La construction de la Grande Mosquée de Samarra, commandée par le calife Al-Mutawakkil, est achevée. Son minaret hélicoïdal, l''Al-Malwiya, devient un symbole de l''architecture abbasside.', 'L''essor de l''Islam : De la révélation à l''âge d''or de Bagdad', '', 'PENDING', '', '2026-03-04 07:23:47.477438+00', NULL, NULL, NULL, ''),
	(1689, 'Invasion des Hunas : Début du déclin de l''Empire Gupta', 480, false, NULL, 'Les Hunas (Huns) commencent leurs incursions en Inde, affaiblissant progressivement l''Empire Gupta. Ces invasions marquent le début d''une période de troubles et de fragmentation politique.', 'Les Dynasties Indiennes : De l''Empire Maurya à l''Empire Moghol (322 AEC - 1707)', '', 'PENDING', '', '2026-03-04 07:23:47.465816+00', NULL, NULL, NULL, ''),
	(1690, 'Sack de Kannauj par Mahmud de Ghazni', 1018, false, NULL, 'Mahmud de Ghazni pille et détruit Kannauj, une ville importante gouvernée par les Rajputs. Cet événement démontre la vulnérabilité des royaumes Rajput face aux invasions turco-persanes.', 'Les Dynasties Indiennes : De l''Empire Maurya à l''Empire Moghol (322 AEC - 1707)', '', 'PENDING', '', '2026-03-04 07:23:47.465816+00', NULL, NULL, NULL, ''),
	(1691, 'Construction du temple de Kandariya Mahadeva à Khajuraho', 1030, false, NULL, 'Le roi Vidyadhara de la dynastie Chandela achève le temple de Kandariya Mahadeva. Ce temple est un exemple emblématique de l''architecture et de l''art Rajput.', 'Les Dynasties Indiennes : De l''Empire Maurya à l''Empire Moghol (322 AEC - 1707)', '', 'PENDING', '', '2026-03-04 07:23:47.465816+00', NULL, NULL, NULL, ''),
	(1692, 'Muhammad bin Tughluq transfère la capitale à Daulatabad', 1327, false, NULL, 'Le sultan Muhammad bin Tughluq ordonne le déplacement de la capitale de Delhi à Daulatabad (Devagiri), une décision controversée qui entraîne des difficultés logistiques et un mécontentement généralisé. La capitale sera ramenée à Delhi en 1335.', 'Les Dynasties Indiennes : De l''Empire Maurya à l''Empire Moghol (322 AEC - 1707)', '', 'PENDING', '', '2026-03-04 07:23:47.465816+00', NULL, NULL, NULL, ''),
	(1693, 'Publication du ''Kokin Wakashū'', première anthologie impériale de poésie japonaise', 905, false, NULL, 'Commandée par l''empereur Daigo, cette anthologie marque un tournant dans la littérature japonaise. Elle influence profondément l''esthétique et les valeurs de la cour, éléments qui seront plus tard adoptés par la classe samouraï.', 'L''histoire des samouraïs : De l''ascension du Bushido à la restauration Meiji (794-1868)', '', 'PENDING', '', '2026-03-04 07:23:47.465816+00', NULL, NULL, NULL, ''),
	(1694, 'Révolte de Taira no Masakado : Début d''une rébellion majeure contre le pouvoir central', 939, false, NULL, 'Taira no Masakado se rebelle contre le gouvernement impérial et s''autoproclame empereur, défiant l''autorité de Kyoto. Cet événement révèle la faiblesse du pouvoir central et l''ascension des guerriers provinciaux.', 'L''histoire des samouraïs : De l''ascension du Bushido à la restauration Meiji (794-1868)', '', 'PENDING', '', '2026-03-04 07:23:47.465816+00', NULL, NULL, NULL, ''),
	(1695, 'Institution du ''Kebiiishi'' : Création d''une force de police impériale à Kyoto', 816, false, NULL, 'Afin de maintenir l''ordre dans la capitale, l''empereur Saga crée le ''Kebiiishi'', une force de police. Cette institution renforce le pouvoir central et contribue à la professionnalisation des guerriers.', 'L''histoire des samouraïs : De l''ascension du Bushido à la restauration Meiji (794-1868)', '', 'PENDING', '', '2026-03-04 07:23:47.465816+00', NULL, NULL, NULL, ''),
	(1696, 'Publication du Gukanshō par Jien, moine bouddhiste et historien', 1220, false, NULL, 'Jien, un moine bouddhiste de l''école Tendai, achève le Gukanshō, une œuvre historique qui offre une perspective critique sur l''histoire du Japon et les événements politiques de l''époque de Kamakura.', 'L''histoire des samouraïs : De l''ascension du Bushido à la restauration Meiji (794-1868)', '', 'PENDING', '', '2026-03-04 07:23:47.465816+00', NULL, NULL, NULL, ''),
	(1697, 'Visite d''Hadrien aux Mystères d''Éleusis', 125, false, NULL, 'L''empereur romain Hadrien est initié aux Mystères d''Éleusis. Sa participation impériale témoigne de la popularité et du prestige continu du culte à l''époque romaine.', 'L''histoire des Sociétés Secrètes : Des cultes antiques aux organisations modernes (300 AEC - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.465816+00', NULL, NULL, NULL, ''),
	(1698, 'Première mention écrite de la Guilde des marchands de Londres (Guildhall)', 1067, false, NULL, 'La Guilde des marchands de Londres, ancêtre des guildes médiévales, est mentionnée pour la première fois dans un document écrit. Elle jouera un rôle crucial dans le commerce et la politique de la ville.', 'L''histoire des Sociétés Secrètes : Des cultes antiques aux organisations modernes (300 AEC - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.465816+00', NULL, NULL, NULL, ''),
	(1699, 'Publication des Constitutions d''Anderson', 1723, false, NULL, 'James Anderson publie "Les Constitutions des Francs-Maçons", un document clé définissant les principes, les lois et l''histoire de la franc-maçonnerie. Ce texte a grandement influencé l''organisation et la philosophie maçonnique.', 'L''histoire des Sociétés Secrètes : Des cultes antiques aux organisations modernes (300 AEC - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.465816+00', NULL, NULL, NULL, ''),
	(1700, 'Institution du Rite Écossais Ancien et Accepté à Charleston', 1801, false, NULL, 'Création du premier Suprême Conseil du Rite Écossais Ancien et Accepté à Charleston, Caroline du Sud. Cet événement marque la formalisation d''un nouveau rite maçonnique qui allait se répandre mondialement.', 'L''histoire des Sociétés Secrètes : Des cultes antiques aux organisations modernes (300 AEC - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.465816+00', NULL, NULL, NULL, ''),
	(1701, 'Sortie de l''album "The Dark Side of the Moon" de Pink Floyd', 1973, false, NULL, 'Cet album conceptuel devient un jalon du rock progressif, explorant des thèmes philosophiques et sociaux. Son succès commercial massif contribue à définir le genre.', 'L''histoire du rock ''n'' roll : Des racines blues à l''ère du streaming musical', '', 'PENDING', '', '2026-03-04 07:23:47.465816+00', NULL, NULL, NULL, ''),
	(1702, 'Inauguration du premier festival "Monsters of Rock" à Donington Park', 1980, false, NULL, 'Le premier festival "Monsters of Rock" a lieu à Donington Park, en Angleterre. Il devient un événement annuel majeur pour les fans de hard rock et de heavy metal, présentant des groupes emblématiques du genre.', 'L''histoire du rock ''n'' roll : Des racines blues à l''ère du streaming musical', '', 'PENDING', '', '2026-03-04 07:23:47.465816+00', NULL, NULL, NULL, ''),
	(1703, 'Première diffusion de l''émission "120 Minutes" sur MTV', 1986, false, NULL, 'L''émission "120 Minutes" devient une plateforme essentielle pour la diffusion de la musique alternative et indépendante. Elle contribue à populariser des groupes grunge et britpop auprès d''un large public.', 'L''histoire du rock ''n'' roll : Des racines blues à l''ère du streaming musical', '', 'PENDING', '', '2026-03-04 07:23:47.465816+00', NULL, NULL, NULL, ''),
	(1704, 'Départ de l''expédition Erebus et Terror de Chatham (Angleterre)', 1839, false, NULL, 'Les navires HMS Erebus et HMS Terror, commandés par James Clark Ross, quittent l''Angleterre pour une expédition scientifique et magnétique en Antarctique. L''expédition vise à étudier le magnétisme terrestre et à explorer les régions australes.', 'L''exploration des pôles : De la découverte de l''Antarctique aux expéditions modernes', '', 'PENDING', '', '2026-03-04 07:23:47.465816+00', NULL, NULL, NULL, ''),
	(1705, 'Observation du mont Erebus en Antarctique par l''expédition Ross', 1841, false, NULL, 'L''expédition Erebus et Terror observe et nomme le mont Erebus, un volcan actif en Antarctique. Le nom est donné en l''honneur du navire HMS Erebus.', 'L''exploration des pôles : De la découverte de l''Antarctique aux expéditions modernes', '', 'PENDING', '', '2026-03-04 07:23:47.465816+00', NULL, NULL, NULL, ''),
	(1706, 'Début du forage de la carotte glaciaire de Camp Century au Groenland', 1966, false, NULL, 'Lancement du projet de forage profond de la calotte glaciaire du Groenland par l''armée américaine. Cette initiative a permis d''obtenir des informations précieuses sur le climat passé.', 'L''exploration des pôles : De la découverte de l''Antarctique aux expéditions modernes', '', 'PENDING', '', '2026-03-04 07:23:47.465816+00', NULL, NULL, NULL, ''),
	(1707, 'Début du forage de la carotte glaciaire de Vostok en Antarctique', 1970, false, NULL, 'Commencement du forage de la carotte de glace de Vostok, un projet soviétique puis russo-français. Il a révélé des données climatiques remontant à plus de 400 000 ans.', 'L''exploration des pôles : De la découverte de l''Antarctique aux expéditions modernes', '', 'PENDING', '', '2026-03-04 07:23:47.465816+00', NULL, NULL, NULL, ''),
	(1708, 'Publication des premières données sur les cycles de Milankovitch à partir des carottes glaciaires', 1976, false, NULL, 'Analyse des carottes glaciaires révélant une corrélation entre les variations orbitales de la Terre (cycles de Milankovitch) et les changements climatiques. Confirmation de la théorie astronomique des climats.', 'L''exploration des pôles : De la découverte de l''Antarctique aux expéditions modernes', '', 'PENDING', '', '2026-03-04 07:23:47.465816+00', NULL, NULL, NULL, ''),
	(1709, 'Fin du forage de la carotte glaciaire EPICA Dome C en Antarctique', 2004, false, NULL, 'Achèvement du forage de la carotte de glace EPICA (European Project for Ice Coring in Antarctica) au Dome C. Obtention d''archives climatiques remontant à 800 000 ans.', 'L''exploration des pôles : De la découverte de l''Antarctique aux expéditions modernes', '', 'PENDING', '', '2026-03-04 07:23:47.465816+00', NULL, NULL, NULL, ''),
	(1710, 'Rédaction du Sutra du Lotus (Saddharma Puṇḍarīka Sūtra)', 100, false, NULL, 'L''un des sutras les plus influents du bouddhisme Mahayana, il met en avant le concept de ''véhicule unique'' (Ekayana) et la nature éternelle du Bouddha. Sa rédaction marque une étape clé dans le développement de la pensée Mahayana.', 'La diffusion du bouddhisme : De la fondation du Sangha à l''expansion en Asie (400 AEC - 1300)', '', 'PENDING', '', '2026-03-04 07:23:47.465816+00', NULL, NULL, NULL, ''),
	(1711, 'Premières sculptures bouddhistes connues de Gandhara', 100, false, NULL, 'Apparition des premières sculptures bouddhistes dans la région de Gandhara (actuel Pakistan et Afghanistan), combinant des influences hellénistiques et indiennes. Ces sculptures représentent souvent le Bouddha sous une forme humaine idéalisée.', 'La diffusion du bouddhisme : De la fondation du Sangha à l''expansion en Asie (400 AEC - 1300)', '', 'PENDING', '', '2026-03-04 07:23:47.465816+00', NULL, NULL, NULL, ''),
	(1712, 'Nāgārjuna fonde l''école Madhyamaka', 150, false, NULL, 'Le philosophe bouddhiste indien Nāgārjuna fonde l''école Madhyamaka, une des écoles philosophiques majeures du bouddhisme Mahayana. Il développe le concept de ''vacuité'' (śūnyatā) et l''importance de la ''voie du milieu''.', 'La diffusion du bouddhisme : De la fondation du Sangha à l''expansion en Asie (400 AEC - 1300)', '', 'PENDING', '', '2026-03-04 07:23:47.465816+00', NULL, NULL, NULL, ''),
	(1713, 'Rédaction du Sutra du Cœur (Prajñāpāramitā Hṛdaya Sūtra)', 200, false, NULL, 'Ce sutra concis, mais influent, résume l''enseignement de la Prajñāpāramitā (Perfection de la Sagesse) et met en avant le concept de vacuité (śūnyatā). Il est largement récité dans les traditions bouddhistes Mahayana.', 'La diffusion du bouddhisme : De la fondation du Sangha à l''expansion en Asie (400 AEC - 1300)', '', 'PENDING', '', '2026-03-04 07:23:47.465816+00', NULL, NULL, NULL, ''),
	(1714, 'Fondation du monastère de Samye, premier monastère bouddhiste complet au Tibet', 779, false, NULL, 'Le monastère de Samye est établi sous le patronage du roi Trisong Detsen, intégrant des éléments architecturaux tibétains, indiens et chinois. Il marque un tournant dans l''institutionnalisation du bouddhisme au Tibet.', 'La diffusion du bouddhisme : De la fondation du Sangha à l''expansion en Asie (400 AEC - 1300)', '', 'PENDING', '', '2026-03-04 07:23:47.465816+00', NULL, NULL, NULL, ''),
	(1715, 'Première diffusion de l''émission de radio "King Biscuit Time" avec Sonny Boy Williamson', 1941, false, NULL, 'L''émission "King Biscuit Time" débute sur KFFA à Helena, Arkansas, diffusant du blues et du jazz en direct. Elle contribue à la diffusion de ces genres musicaux dans le Sud des États-Unis.', 'Les Années Folles : L''émergence de la culture de masse et la révolution des mœurs (1919-1939)', '', 'PENDING', '', '2026-03-04 07:23:47.477438+00', NULL, NULL, NULL, ''),
	(1716, 'Ouverture de la première station-service au monde (Gulf Refining Company)', 1913, false, NULL, 'La Gulf Refining Company ouvre la première station-service dédiée à la vente de carburant pour automobiles à Pittsburgh, Pennsylvanie. Cela marque le début d''une nouvelle ère pour la distribution de carburant.', 'Les Années Folles : L''émergence de la culture de masse et la révolution des mœurs (1919-1939)', '', 'PENDING', '', '2026-03-04 07:23:47.477438+00', NULL, NULL, NULL, ''),
	(1717, 'Première édition du Salon des Arts Ménagers à Paris', 1923, false, NULL, 'Ce salon présente les dernières innovations en matière d''équipement domestique, influençant les conditions de travail des femmes au foyer. Il se tient du 11 au 26 février 1923.', 'Les Années Folles : L''émergence de la culture de masse et la révolution des mœurs (1919-1939)', '', 'PENDING', '', '2026-03-04 07:23:47.477438+00', NULL, NULL, NULL, ''),
	(1718, 'Observation de l''éclipse solaire totale à Cumana', 1799, false, NULL, 'Humboldt observe et documente une éclipse solaire totale à Cumana (Venezuela), contribuant à l''astronomie et à la géophysique. Il en profite pour mesurer la longitude.', 'L''âge d''or de l''exploration naturaliste : De Humboldt à Darwin (1799-1859)', '', 'PENDING', '', '2026-03-04 07:23:47.477438+00', NULL, NULL, NULL, ''),
	(1719, 'Publication de ''Voyage d''un naturaliste autour du monde'' par Charles Darwin', 1839, false, NULL, 'Darwin publie son récit de voyage, ''Voyage d''un naturaliste autour du monde'', qui relate ses expériences et observations lors de l''expédition du HMS Beagle. Le livre rencontre un grand succès populaire et scientifique.', 'L''âge d''or de l''exploration naturaliste : De Humboldt à Darwin (1799-1859)', '', 'PENDING', '', '2026-03-04 07:23:47.477438+00', NULL, NULL, NULL, ''),
	(1720, 'Edward Forbes publie ''On the Asteriadae''', 1841, false, NULL, 'Publication de ''On the Asteriadae'', un ouvrage majeur d''Edward Forbes qui contribue à l''étude de la distribution géographique des étoiles de mer. Il y expose sa théorie de la zone azoic.', 'L''âge d''or de l''exploration naturaliste : De Humboldt à Darwin (1799-1859)', '', 'PENDING', '', '2026-03-04 07:23:47.477438+00', NULL, NULL, NULL, ''),
	(1721, 'Joseph Dalton Hooker publie ''Flora Novae-Zelandiae''', 1853, false, NULL, 'Publication du premier volume de ''Flora Novae-Zelandiae'' par Joseph Dalton Hooker, une étude approfondie de la flore de Nouvelle-Zélande. Il met en évidence les liens biogéographiques avec d''autres régions du monde.', 'L''âge d''or de l''exploration naturaliste : De Humboldt à Darwin (1799-1859)', '', 'PENDING', '', '2026-03-04 07:23:47.477438+00', NULL, NULL, NULL, ''),
	(1722, 'Alphonse de Candolle publie ''Géographie botanique raisonnée''', 1855, false, NULL, 'Alphonse de Candolle publie ''Géographie botanique raisonnée'', un ouvrage fondateur de la phytogéographie. Il y analyse les facteurs environnementaux influençant la distribution des plantes.', 'L''âge d''or de l''exploration naturaliste : De Humboldt à Darwin (1799-1859)', '', 'PENDING', '', '2026-03-04 07:23:47.477438+00', NULL, NULL, NULL, ''),
	(1723, 'Présentation de la projection de Mercator au roi Charles II d''Angleterre', 1679, false, NULL, 'Le cartographe Francis Lamb présente une grande carte du monde utilisant la projection de Mercator, soulignant son utilité pour la navigation maritime.', 'L''histoire de la cartographie : Des premières représentations du monde aux cartes numériques (600 AEC - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.477438+00', NULL, NULL, NULL, ''),
	(1724, 'Publication du "Traité de navigation" de Bouguer', 1753, false, NULL, 'Pierre Bouguer publie son "Traité de navigation", un ouvrage fondamental qui contribue à la précision des techniques de navigation et de cartographie maritime.', 'L''histoire de la cartographie : Des premières représentations du monde aux cartes numériques (600 AEC - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.477438+00', NULL, NULL, NULL, ''),
	(1725, 'Début du "Great Trigonometrical Survey" en Inde', 1800, false, NULL, 'Lancement du "Great Trigonometrical Survey" par la Compagnie britannique des Indes orientales, visant à cartographier précisément le sous-continent indien.', 'L''histoire de la cartographie : Des premières représentations du monde aux cartes numériques (600 AEC - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.477438+00', NULL, NULL, NULL, ''),
	(1726, 'Création du format de données géospatiales Shapefile par Esri', 1990, false, NULL, 'Le format Shapefile devient un standard de facto pour l''échange de données géographiques. Il facilite l''interopérabilité entre différents logiciels SIG.', 'L''histoire de la cartographie : Des premières représentations du monde aux cartes numériques (600 AEC - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.477438+00', NULL, NULL, NULL, ''),
	(1727, 'Ouverture de la première usine textile entièrement automatisée (Lowell, Massachusetts)', 1814, false, NULL, 'La première usine textile entièrement automatisée ouvre ses portes à Lowell, Massachusetts. Elle intègre toutes les étapes de la production textile sous un même toit, grâce à l''énergie hydraulique et aux machines à vapeur.', 'La Révolution Industrielle : Des premières machines à vapeur à l''ère de l''électricité (1760-1914)', '', 'PENDING', '', '2026-03-04 07:23:47.477438+00', NULL, NULL, NULL, ''),
	(1728, 'Présentation du rapport de la Commission royale sur le travail des enfants dans les mines au Parlement britannique', 1842, false, NULL, 'Le rapport révèle des conditions de travail épouvantables, notamment l''emploi d''enfants dès l''âge de cinq ans. Il conduit directement à l''adoption de la loi sur les mines.', 'La Révolution Industrielle : Des premières machines à vapeur à l''ère de l''électricité (1760-1914)', '', 'PENDING', '', '2026-03-04 07:23:47.477438+00', NULL, NULL, NULL, ''),
	(1729, 'Adoption des Grágás, premières lois islandaises écrites', 1117, false, NULL, 'L''Althing adopte les Grágás, un ensemble de lois islandaises compilées et écrites pour la première fois. Cela marque une étape importante dans le développement juridique et social de l''Islande.', 'Les Vikings : Des raids côtiers à la colonisation du Groenland', '', 'PENDING', '', '2026-03-04 07:23:47.477438+00', NULL, NULL, NULL, ''),
	(1730, 'Soumission de l''Islande à la Norvège (Gamli sáttmáli)', 1262, false, NULL, 'Signature du ''Vieux Pacte'' (Gamli sáttmáli) par lequel l''Islande se soumet à la domination du roi de Norvège. Cet événement met fin à l''indépendance de l''Islande et la place sous contrôle norvégien.', 'Les Vikings : Des raids côtiers à la colonisation du Groenland', '', 'PENDING', '', '2026-03-04 07:23:47.477438+00', NULL, NULL, NULL, ''),
	(1731, 'Introduction du luthéranisme comme religion d''État en Islande', 1550, false, NULL, 'L''exécution de Jón Arason, dernier évêque catholique d''Islande, marque l''établissement officiel du luthéranisme comme religion d''État. Cet événement consolide la Réforme en Islande et met fin à l''ère catholique.', 'Les Vikings : Des raids côtiers à la colonisation du Groenland', '', 'PENDING', '', '2026-03-04 07:23:47.477438+00', NULL, NULL, NULL, ''),
	(1732, 'Construction de l''église de Thjodhild au Groenland', 1000, false, NULL, 'Thjodhild, la femme d''Erik le Rouge, fait construire une église au Groenland, marquant l''un des premiers édifices chrétiens en Amérique du Nord.', 'Les Vikings : Des raids côtiers à la colonisation du Groenland', '', 'PENDING', '', '2026-03-04 07:23:47.477438+00', NULL, NULL, NULL, ''),
	(1733, 'Visite de l''expédition d''Ivar Bardarson au Groenland : Dernier contact officiel norrois avec la colonie de l''Ouest', 1360, false, NULL, 'Ivar Bardarson, envoyé par le roi de Norvège, inspecte les colonies groenlandaises. Il trouve la colonie de l''Ouest déserte, marquant un tournant dans l''histoire des colonies vikings.', 'Les Vikings : Des raids côtiers à la colonisation du Groenland', '', 'PENDING', '', '2026-03-04 07:23:47.477438+00', NULL, NULL, NULL, ''),
	(1734, 'Assassinat d''Athaulf, roi des Wisigoths, à Barcelone', 415, false, NULL, 'Athaulf, roi des Wisigoths, est assassiné à Barcelone par un serviteur. Cet événement plonge les Wisigoths dans une crise de succession.', 'La chute de Rome et l''ascension des Royaumes barbares : des invasions aux dynasties (376-751)', '', 'PENDING', '', '2026-03-04 07:23:47.477438+00', NULL, NULL, NULL, ''),
	(1735, 'Publication du « Décret Gélase » fixant les livres canoniques et apocryphes', 496, false, NULL, 'Le Décret Gélase, attribué au pape Gélase Ier, est publié. Il établit une liste des livres bibliques considérés comme canoniques et ceux considérés comme apocryphes, influençant la doctrine chrétienne.', 'La chute de Rome et l''ascension des Royaumes barbares : des invasions aux dynasties (376-751)', '', 'PENDING', '', '2026-03-04 07:23:47.477438+00', NULL, NULL, NULL, ''),
	(1736, 'Découverte du corps de George Mallory sur le mont Everest', 1999, false, NULL, 'L''expédition de recherche Mallory et Irvine découvre le corps de George Mallory sur la face nord du mont Everest. La découverte relance le débat sur la possibilité qu''ils aient atteint le sommet en 1924.', 'La conquête de l''Everest : Des premières tentatives aux ascensions modernes (1921-2003)', '', 'PENDING', '', '2026-03-04 07:23:47.477438+00', NULL, NULL, NULL, ''),
	(1737, 'Première ascension du Gasherbrum II par une équipe chinoise et japonaise', 1982, false, NULL, 'Une expédition conjointe sino-japonaise réussit la première ascension du Gasherbrum II (8 035 m), marquant une étape importante dans la coopération internationale en alpinisme. Cet événement contribue à l''essor des expéditions commerciales en haute altitude.', 'La conquête de l''Everest : Des premières tentatives aux ascensions modernes (1921-2003)', '', 'PENDING', '', '2026-03-04 07:23:47.477438+00', NULL, NULL, NULL, ''),
	(1738, 'Ouverture du ''Khumbu Climbing Center'' par Conrad Anker et Jennifer Lowe-Anker', 2003, false, NULL, 'Fondé en mémoire d''Alex Lowe, le Khumbu Climbing Center offre une formation en alpinisme aux Sherpas népalais, améliorant leurs compétences en matière de sécurité et leur permettant de mieux gérer les risques associés à l''ascension de l''Everest et d''autres sommets.', 'La conquête de l''Everest : Des premières tentatives aux ascensions modernes (1921-2003)', '', 'PENDING', '', '2026-03-04 07:23:47.477438+00', NULL, NULL, NULL, ''),
	(1739, 'Construction du Temple Rosalila à Copán', 571, false, NULL, 'K''inich Yax K''uk'' Mo'' reconstruit le temple Rosalila à l''identique par dessus l''ancien temple. Il est dédié au fondateur de la dynastie et témoigne de la puissance de Copán.', 'L''histoire des Empires Précolombiens : Des Olmèques à la conquête du Pérou (1200 AEC - 1572)', '', 'PENDING', '', '2026-03-04 07:23:47.477438+00', NULL, NULL, NULL, ''),
	(1740, 'Introduction du thé comme tribut impérial officiel sous le règne de l''empereur Dezong', 780, false, NULL, 'Le thé devient une ressource importante pour l''État. Cette officialisation stimule la production et le commerce du thé à grande échelle.', 'L''histoire du thé : De la légende de Shen Nong à l''ère du thé glacé (2737 AEC - 1904)', '', 'PENDING', '', '2026-03-04 07:23:47.477438+00', NULL, NULL, NULL, ''),
	(1741, 'Établissement de la première administration officielle du thé (Chaguan) par l''empereur Xianzong', 810, false, NULL, 'Cette administration centralise la gestion de la production, de la distribution et de la taxation du thé. Elle renforce le contrôle de l''État sur cette ressource.', 'L''histoire du thé : De la légende de Shen Nong à l''ère du thé glacé (2737 AEC - 1904)', '', 'PENDING', '', '2026-03-04 07:23:47.477438+00', NULL, NULL, NULL, ''),
	(1742, 'Ouverture du premier salon de thé à Londres par Thomas Twining', 1706, false, NULL, 'Thomas Twining ouvre le premier salon de thé à Londres, appelé "Tom''s Coffee House". Il contribue à populariser la consommation de thé auprès des classes supérieures.', 'L''histoire du thé : De la légende de Shen Nong à l''ère du thé glacé (2737 AEC - 1904)', '', 'PENDING', '', '2026-03-04 07:23:47.477438+00', NULL, NULL, NULL, ''),
	(1743, 'Commercialisation du premier appareil photo Kodak', 1888, false, NULL, 'George Eastman lance le premier appareil photo Kodak, accompagné du slogan ''Vous appuyez sur le bouton, nous faisons le reste''. Cet appareil rend la photographie accessible au grand public et marque le début de l''ère de la photographie amateur.', 'L''histoire de la photographie : Des premières images aux selfies (1826-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.477438+00', NULL, NULL, NULL, ''),
	(1744, 'Fondation de la société Leitz Camera GmbH (Leica)', 1924, false, NULL, 'Ernst Leitz II prend la décision de produire en série l''appareil photo 35mm d''Oskar Barnack. La société est créée pour gérer la production et la commercialisation du Leica.', 'L''histoire de la photographie : Des premières images aux selfies (1826-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.477438+00', NULL, NULL, NULL, ''),
	(1745, 'Bombardement d''Alger par la flotte anglaise', 1672, false, NULL, 'L''amiral anglais Edward Spragge bombarde Alger pour forcer les autorités à libérer les captifs anglais et à cesser les actes de piraterie contre les navires anglais.', 'L''histoire des pirates : Des pirates antiques aux pirates somaliens (300 AEC - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.477438+00', NULL, NULL, NULL, ''),
	(1746, 'Début du siège de Fort Zeelandia par Koxinga', 1661, false, NULL, 'Koxinga, un loyaliste Ming, lance un siège contre Fort Zeelandia, la principale forteresse de la Compagnie néerlandaise des Indes orientales à Taïwan. Le siège aboutit à la prise de contrôle de Taïwan par Koxinga et à l''établissement du royaume de Tungning.', 'L''histoire des pirates : Des pirates antiques aux pirates somaliens (300 AEC - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.477438+00', NULL, NULL, NULL, ''),
	(1747, 'Capture du pétrolier saoudien Sirius Star par des pirates somaliens', 2008, false, NULL, 'Des pirates somaliens capturent le pétrolier saoudien Sirius Star, transportant une cargaison de pétrole brut d''une valeur de 100 millions de dollars. Cet acte audacieux démontre la capacité croissante des pirates et leurs ambitions financières.', 'L''histoire des pirates : Des pirates antiques aux pirates somaliens (300 AEC - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.477438+00', NULL, NULL, NULL, ''),
	(1748, 'Première mention documentée de l''utilisation des neumes pour la notation musicale', 900, false, NULL, 'Les neumes, ancêtres de la notation musicale moderne, apparaissent pour la première fois dans des manuscrits. Ces symboles rudimentaires indiquent la direction mélodique du chant grégorien.', 'L''histoire de la musique classique occidentale : Des chants grégoriens à la musique contemporaine (800-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.477438+00', NULL, NULL, NULL, ''),
	(1749, 'Fondation du "College of Vicars Choral" à Exeter Cathedral', 1388, false, NULL, 'Cette fondation, inspirée par les pratiques de Notre-Dame, vise à former des chanteurs pour la polyphonie. Elle témoigne de l''influence de l''école de Notre-Dame sur la musique anglaise.', 'L''histoire de la musique classique occidentale : Des chants grégoriens à la musique contemporaine (800-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.477438+00', NULL, NULL, NULL, ''),
	(1750, 'Publication du premier livre de madrigaux à cinq voix de Philippe Verdelot', 1534, false, NULL, 'Philippe Verdelot, compositeur franco-flamand actif à Florence, publie son premier livre de madrigaux à cinq voix. Cette publication contribue à populariser le madrigal, une forme musicale profane importante de la Renaissance.', 'L''histoire de la musique classique occidentale : Des chants grégoriens à la musique contemporaine (800-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.477438+00', NULL, NULL, NULL, ''),
	(1751, 'Ouverture du port de Guangzhou au commerce maritime international', 226, false, NULL, 'Le royaume de Wu ouvre le port de Guangzhou au commerce maritime, stimulant les échanges avec l''Asie du Sud-Est et l''Inde via la Route de la Soie maritime.', 'La Route de la Soie : Du commerce caravanier à l''ouverture au monde (130 AEC - 1453)', '', 'PENDING', '', '2026-03-04 07:23:47.477438+00', NULL, NULL, NULL, ''),
	(1752, 'Début du déclin de l''Empire Parthe', 220, false, NULL, 'L''Empire Parthe s''affaiblit considérablement en raison de conflits internes et de pressions extérieures, notamment des Sassanides. Ce déclin affecte la stabilité des routes commerciales sous son contrôle.', 'La Route de la Soie : Du commerce caravanier à l''ouverture au monde (130 AEC - 1453)', '', 'PENDING', '', '2026-03-04 07:23:47.477438+00', NULL, NULL, NULL, ''),
	(1753, 'Première traduction connue d''un texte bouddhiste en chinois par An Shigao à Luoyang', 148, false, NULL, 'An Shigao, un prince parthe devenu moine, arrive à Luoyang et commence à traduire des textes bouddhistes en chinois. Cet événement marque le début de la diffusion du bouddhisme en Chine via la Route de la Soie.', 'La Route de la Soie : Du commerce caravanier à l''ouverture au monde (130 AEC - 1453)', '', 'PENDING', '', '2026-03-04 07:23:47.477438+00', NULL, NULL, NULL, ''),
	(1754, 'Fondation de la Compagnie de la Boussole (Maona di Chio) par Gênes', 1346, false, NULL, 'Cette société commerciale génoise prend le contrôle de l''île de Chios et de ses environs. Elle établit une domination maritime en mer Égée, concurrençant les routes terrestres de la soie.', 'La Route de la Soie : Du commerce caravanier à l''ouverture au monde (130 AEC - 1453)', '', 'PENDING', '', '2026-03-04 07:23:47.477438+00', NULL, NULL, NULL, ''),
	(1755, 'Inauguration du premier studio de cinéma en intérieur (Black Maria)', 1893, false, NULL, 'Thomas Edison ouvre le "Black Maria", le premier studio de cinéma dédié à la production de films. Il est situé à West Orange, New Jersey.', 'L''histoire du cinéma : Des premières projections au cinéma numérique (1895-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.477438+00', NULL, NULL, NULL, ''),
	(1756, 'Inauguration du premier "Nickelodeon" à Pittsburgh, Pennsylvanie', 1905, false, NULL, 'Ce cinéma de quartier, proposant des films pour un nickel, démocratise l''accès au cinéma. Il marque le début de l''expansion rapide des salles de cinéma aux États-Unis.', 'L''histoire du cinéma : Des premières projections au cinéma numérique (1895-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.477438+00', NULL, NULL, NULL, ''),
	(1757, 'Sortie du film "Le Kid" de Charlie Chaplin', 1921, false, NULL, 'Ce long métrage, réalisé, écrit et interprété par Chaplin, est un succès critique et commercial. Il consolide la popularité de Chaplin et marque un tournant dans sa carrière.', 'L''histoire du cinéma : Des premières projections au cinéma numérique (1895-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.477438+00', NULL, NULL, NULL, ''),
	(1758, 'Sortie du film *Cléo de 5 à 7* d''Agnès Varda', 1962, false, NULL, 'Ce film suit une chanteuse pendant deux heures de sa vie, alors qu''elle attend les résultats d''un examen médical. Il explore des thèmes existentiels et la perception de soi.', 'L''histoire du cinéma : Des premières projections au cinéma numérique (1895-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.477438+00', NULL, NULL, NULL, ''),
	(1759, 'Publication du manifeste *Pour un cinéma nouveau* par le groupe Cinéma Vérité', 1963, false, NULL, 'Ce manifeste théorise une approche documentaire directe et immersive, influençant le cinéma direct et le cinéma vérité. Il prône l''utilisation de caméras légères et de sons directs pour capturer la réalité.', 'L''histoire du cinéma : Des premières projections au cinéma numérique (1895-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.477438+00', NULL, NULL, NULL, ''),
	(1760, 'Début du califat omeyyade : Muʿawiya Ier devient calife à Damas', 661, false, NULL, 'Après l''assassinat d''Ali, Muʿawiya Ier s''établit comme calife, marquant le début de la dynastie omeyyade et le transfert du pouvoir de Médine à Damas. Cet événement consolide le pouvoir omeyyade et initie une nouvelle ère politique et administrative.', 'L''essor de l''Islam : De la révélation à l''âge d''or de Bagdad', '', 'PENDING', '', '2026-03-04 07:23:47.477438+00', NULL, NULL, NULL, ''),
	(1762, 'Assassinat du calife Al-Mutawakkil', 861, false, NULL, 'Le calife Al-Mutawakkil est assassiné par des gardes turcs, marquant le début d''une période d''instabilité politique et de déclin de l''autorité centrale abbasside. Cet événement précipite le ''Anarchy at Samarra''.', 'L''essor de l''Islam : De la révélation à l''âge d''or de Bagdad', '', 'PENDING', '', '2026-03-04 07:23:47.477438+00', NULL, NULL, NULL, ''),
	(1763, 'Publication de l''article "The Sources of Soviet Conduct" par "X" (George Kennan)', 1947, false, NULL, 'L''article, publié dans Foreign Affairs, expose la théorie du "containment" de l''Union soviétique. Il influence fortement la politique étrangère américaine pendant la Guerre Froide.', 'La Guerre Froide : De la doctrine Truman à la chute du Mur de Berlin (1947-1991)', '', 'PENDING', '', '2026-03-04 07:23:47.477438+00', NULL, NULL, NULL, ''),
	(1764, 'Première grève au chantier naval Lénine de Gdańsk', 1980, false, NULL, 'Début des grèves menées par Solidarność en Pologne, un mouvement social et politique qui ébranlera le bloc soviétique. Lech Wałęsa en prend la tête.', 'La Guerre Froide : De la doctrine Truman à la chute du Mur de Berlin (1947-1991)', '', 'PENDING', '', '2026-03-04 07:23:47.477438+00', NULL, NULL, NULL, ''),
	(1765, 'Consécration de Grégoire de Tours comme évêque : Témoignage direct des ravages de la peste en Gaule', 573, false, NULL, 'Consécration de Grégoire de Tours comme évêque, dont les écrits offrent un témoignage direct et précieux des ravages de la peste en Gaule. Ses récits documentent l''impact social et religieux de la pandémie.', 'La Peste Noire : De l''épidémie de Justinien aux grandes pandémies médiévales (541-1351)', '', 'PENDING', '', '2026-03-04 07:23:47.489108+00', NULL, NULL, NULL, ''),
	(1766, 'Premières mentions de la peste à Issyk-Kul (actuel Kirghizistan)', 1338, false, NULL, 'Des tombes avec des inscriptions mentionnant une ''peste'' sont découvertes près du lac Issyk-Kul, suggérant le point de départ de la pandémie de peste noire. Ces découvertes archéologiques fournissent des preuves cruciales sur l''origine de la peste.', 'La Peste Noire : De l''épidémie de Justinien aux grandes pandémies médiévales (541-1351)', '', 'PENDING', '', '2026-03-04 07:23:47.489108+00', NULL, NULL, NULL, ''),
	(1767, 'Mise en place du billet de santé à Marseille pour contrôler les déplacements', 1383, false, NULL, 'Les autorités marseillaises instaurent un système de billets de santé pour contrôler les personnes entrant et sortant de la ville. Ce document atteste de l''absence de symptômes de la peste et vise à prévenir l''importation de la maladie.', 'La Peste Noire : De l''épidémie de Justinien aux grandes pandémies médiévales (541-1351)', '', 'PENDING', '', '2026-03-04 07:23:47.489108+00', NULL, NULL, NULL, ''),
	(1768, 'Première diffusion télévisée d''un match de baseball universitaire aux États-Unis', 1939, false, NULL, 'Le 17 mai, un match de baseball universitaire entre Princeton et Columbia est diffusé à la télévision par NBC. C''est la première fois qu''un match de baseball universitaire est diffusé à la télévision.', 'L''histoire de la télévision : Des premières images aux écrans connectés (1926 - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.489108+00', NULL, NULL, NULL, ''),
	(1769, 'Première diffusion de l''émission "Le Palmarès des Chansons" animée par Guy Lux', 1965, false, NULL, 'L''émission devient rapidement un rendez-vous incontournable du paysage audiovisuel français. Elle contribue à populariser de nombreux artistes et chansons.', 'L''histoire de la télévision : Des premières images aux écrans connectés (1926 - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.489108+00', NULL, NULL, NULL, ''),
	(1770, 'Inauguration de la troisième chaîne de l''ORTF (couleur)', 1972, false, NULL, 'La troisième chaîne marque une étape importante dans la diversification de l''offre télévisuelle. Elle est la première chaîne en couleur en France.', 'L''histoire de la télévision : Des premières images aux écrans connectés (1926 - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.489108+00', NULL, NULL, NULL, ''),
	(1771, 'Visite de Zheng He à Malacca, un carrefour commercial stratégique', 1409, false, NULL, 'Zheng He visite Malacca, un port stratégique en Asie du Sud-Est. Cet événement renforce l''influence chinoise dans la région et favorise le commerce.', 'L''histoire des grandes découvertes maritimes chinoises : Des expéditions de Zheng He à la fermeture du pays (1405-1525)', '', 'PENDING', '', '2026-03-04 07:23:47.489108+00', NULL, NULL, NULL, ''),
	(1772, 'Retour de la quatrième expédition de Zheng He à Nankin', 1415, false, NULL, 'La flotte de Zheng He revient à Nankin, rapportant des tributs et des ambassadeurs de divers pays. Ce retour marque le succès de la mission diplomatique et commerciale.', 'L''histoire des grandes découvertes maritimes chinoises : Des expéditions de Zheng He à la fermeture du pays (1405-1525)', '', 'PENDING', '', '2026-03-04 07:23:47.489108+00', NULL, NULL, NULL, ''),
	(1773, 'Visite de Zheng He à Malindi (Kenya)', 1418, false, NULL, 'La flotte de Zheng He arrive à Malindi, sur la côte du Kenya. Cet événement témoigne de la portée des voyages chinois en Afrique de l''Est et de l''établissement de relations diplomatiques.', 'L''histoire des grandes découvertes maritimes chinoises : Des expéditions de Zheng He à la fermeture du pays (1405-1525)', '', 'PENDING', '', '2026-03-04 07:23:47.489108+00', NULL, NULL, NULL, ''),
	(1774, 'Consécration du chœur de la cathédrale de Cologne', 1322, false, NULL, 'Le chœur de la cathédrale de Cologne, une structure gothique impressionnante, est consacré le 27 septembre. Il marque une étape importante dans la construction de l''édifice.', 'La construction des cathédrales gothiques : De Saint-Denis à Cologne (1144-1880)', '', 'PENDING', '', '2026-03-04 07:23:47.489108+00', NULL, NULL, NULL, ''),
	(1775, 'Reprise officielle des travaux de construction de la cathédrale de Cologne', 1842, false, NULL, 'Le roi Frédéric-Guillaume IV de Prusse pose la première pierre pour la reprise des travaux de construction de la cathédrale de Cologne, relançant le projet après des siècles d''interruption.', 'La construction des cathédrales gothiques : De Saint-Denis à Cologne (1144-1880)', '', 'PENDING', '', '2026-03-04 07:23:47.489108+00', NULL, NULL, NULL, ''),
	(1776, 'Fondation de la Broken Hill Proprietary Company (BHP)', 1885, false, NULL, 'La Broken Hill Proprietary Company (BHP) est fondée pour exploiter les riches gisements de minerai de Broken Hill. Elle deviendra l''une des plus grandes entreprises minières au monde.', 'La Ruée vers l''or en Australie : De la découverte des premiers gisements à la fin de l''âge d''or (1851-1900)', '', 'PENDING', '', '2026-03-04 07:23:47.489108+00', NULL, NULL, NULL, ''),
	(1777, 'Adoption de la Loi sur les terres de la Couronne du Victoria (Crown Lands Act)', 1862, false, NULL, 'Le Parlement du Victoria adopte la loi facilitant l''accès aux terres de la Couronne, y compris les zones aurifères. Cette loi visait à encourager la colonisation et le développement économique.', 'La Ruée vers l''or en Australie : De la découverte des premiers gisements à la fin de l''âge d''or (1851-1900)', '', 'PENDING', '', '2026-03-04 07:23:47.489108+00', NULL, NULL, NULL, ''),
	(1778, 'Découverte de la plus grosse pépite d''or du monde à Moliagul, Victoria (Welcome Stranger)', 1869, false, NULL, 'Deux prospecteurs découvrent la pépite d''or ''Welcome Stranger'', pesant plus de 72 kg, près de Moliagul. Cette découverte majeure stimule davantage la ruée vers l''or victorienne.', 'La Ruée vers l''or en Australie : De la découverte des premiers gisements à la fin de l''âge d''or (1851-1900)', '', 'PENDING', '', '2026-03-04 07:23:47.489108+00', NULL, NULL, NULL, ''),
	(1779, 'Ouverture officielle de la Bourse de Melbourne (Melbourne Stock Exchange)', 1861, false, NULL, 'La Bourse de Melbourne ouvre ses portes, reflétant la croissance économique et l''importance croissante des investissements dans la colonie de Victoria, notamment dans le secteur minier.', 'La Ruée vers l''or en Australie : De la découverte des premiers gisements à la fin de l''âge d''or (1851-1900)', '', 'PENDING', '', '2026-03-04 07:23:47.489108+00', NULL, NULL, NULL, ''),
	(1780, 'Première publication du roman "Les Hauts de Hurlevent" d''Emily Brontë', 1847, false, NULL, 'Emily Brontë publie son unique roman, "Les Hauts de Hurlevent", sous le pseudonyme de Ellis Bell. L''œuvre est initialement accueillie avec des critiques mitigées, mais devient par la suite un classique de la littérature anglaise.', 'La Ruée vers l''or en Australie : De la découverte des premiers gisements à la fin de l''âge d''or (1851-1900)', '', 'PENDING', '', '2026-03-04 07:23:47.489108+00', NULL, NULL, NULL, ''),
	(1781, 'Découverte du processus de cyanuration par John Stewart MacArthur, Robert Forrest et William Forrest', 1887, false, NULL, 'Ce procédé révolutionnaire améliore l''extraction de l''or à partir de minerais à faible teneur, marquant une transition vers l''exploitation à grande échelle. Il permet de traiter des volumes importants de minerai auparavant considérés comme non rentables.', 'La Ruée vers l''or en Australie : De la découverte des premiers gisements à la fin de l''âge d''or (1851-1900)', '', 'PENDING', '', '2026-03-04 07:23:47.489108+00', NULL, NULL, NULL, ''),
	(1782, 'Adoption du Stamp Mill à multiples pilons dans les mines d''or du Witwatersrand', 1890, false, NULL, 'L''introduction de ces machines puissantes augmente considérablement la capacité de broyage du minerai. Cela permet de traiter plus rapidement de plus grandes quantités de minerai aurifère, favorisant l''industrialisation de l''extraction.', 'La Ruée vers l''or en Australie : De la découverte des premiers gisements à la fin de l''âge d''or (1851-1900)', '', 'PENDING', '', '2026-03-04 07:23:47.489108+00', NULL, NULL, NULL, ''),
	(1783, 'Interdiction des jeux de hasard par un édit impérial en Chine', 352, false, NULL, 'Un édit impérial est promulgué en Chine en 352, interdisant les jeux de hasard. Cette interdiction reflète les préoccupations morales et sociales liées aux jeux de hasard à cette époque.', 'L''histoire des jouets et des jeux : Des osselets antiques aux jeux vidéo (3000 AEC - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.489108+00', NULL, NULL, NULL, ''),
	(1784, 'Construction de l''oiseau automate mécanique par Al-Jazari', 1206, false, NULL, 'Al-Jazari, un savant et ingénieur musulman, conçoit un oiseau automate mécanique, considéré comme l''un des premiers exemples de jouet mécanique sophistiqué. Il est décrit dans son ouvrage ''Le Livre de la connaissance des dispositifs mécaniques ingénieux''.', 'L''histoire des jouets et des jeux : Des osselets antiques aux jeux vidéo (3000 AEC - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.489108+00', NULL, NULL, NULL, ''),
	(1785, 'Création de la poupée en bois articulée (Holzpuppe) à Nuremberg', 1530, false, NULL, 'Les artisans de Nuremberg, en Allemagne, commencent à produire des poupées en bois articulées, appelées ''Holzpuppen''. Ces poupées, souvent richement vêtues, deviennent des objets de collection prisés par les familles nobles et bourgeoises.', 'L''histoire des jouets et des jeux : Des osselets antiques aux jeux vidéo (3000 AEC - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.489108+00', NULL, NULL, NULL, ''),
	(1786, 'Première inoculation expérimentale contre la fièvre jaune par Daniel Carrión à Lima', 1885, false, NULL, 'L''étudiant en médecine péruvien Daniel Carrión s''inocule volontairement des sécrétions d''une patiente atteinte de la verrue péruvienne, prouvant ainsi le lien entre cette maladie et la fièvre d''Oroya. Il décède des suites de l''expérience.', 'La course aux vaccins : De Jenner à la pandémie de Covid-19 (1796-2020)', '', 'PENDING', '', '2026-03-04 07:23:47.489108+00', NULL, NULL, NULL, ''),
	(1787, 'Production massive du vaccin 17D contre la fièvre jaune par la Fondation Rockefeller', 1939, false, NULL, 'La Fondation Rockefeller lance la production à grande échelle du vaccin 17D, permettant une vaccination massive dans les régions endémiques et contribuant à réduire considérablement l''incidence de la fièvre jaune.', 'La course aux vaccins : De Jenner à la pandémie de Covid-19 (1796-2020)', '', 'PENDING', '', '2026-03-04 07:23:47.489108+00', NULL, NULL, NULL, ''),
	(1788, 'Dioscoride décrit la distillation de la résine de térébinthe dans ''De Materia Medica''', 77, false, NULL, 'Le médecin et botaniste grec Dioscoride détaille le processus de distillation, une avancée majeure dans l''extraction des huiles essentielles. Son ouvrage devient une référence pour la pharmacopée et la parfumerie.', 'L''histoire du parfum : Des fumigations antiques à la parfumerie de luxe (3000 AEC - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.489108+00', NULL, NULL, NULL, ''),
	(1789, 'Taddeo Alderotti commence à enseigner la distillation de l''eau-de-vie à l''Université de Bologne', 1280, false, NULL, 'Alderotti est l''un des premiers à décrire en détail le processus de distillation de l''alcool à partir du vin. Ses travaux contribuent à la diffusion de cette technique en Europe.', 'L''histoire du parfum : Des fumigations antiques à la parfumerie de luxe (3000 AEC - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.489108+00', NULL, NULL, NULL, ''),
	(1790, 'Ouverture de la première usine de production industrielle de vanilline (Haarmann & Reimer)', 1874, false, NULL, 'Haarmann & Reimer (future Symrise) démarre la production à Holzminden, en Allemagne. La vanilline de synthèse devient accessible à grande échelle.', 'L''histoire du parfum : Des fumigations antiques à la parfumerie de luxe (3000 AEC - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.489108+00', NULL, NULL, NULL, ''),
	(1791, 'Présentation du canon géant de Le Creusot à l''Exposition universelle', 1889, false, NULL, 'Le canon géant de Le Creusot, une pièce d''artillerie impressionnante, est exposé, illustrant la puissance industrielle et militaire de la France. Il attire l''attention des visiteurs.', 'Les Grandes Expositions Universelles : Vitrines du progrès et des cultures du monde (1851-1937)', '', 'PENDING', '', '2026-03-04 07:23:47.489108+00', NULL, NULL, NULL, ''),
	(1792, 'Présentation de la "Great Wheel" à l''Exposition de Chicago', 1893, false, NULL, 'La "Great Wheel", une grande roue conçue par George Washington Gale Ferris Jr., est présentée au public à l''Exposition de Chicago. Elle devient une attraction emblématique de l''événement.', 'Les Grandes Expositions Universelles : Vitrines du progrès et des cultures du monde (1851-1937)', '', 'PENDING', '', '2026-03-04 07:23:47.489108+00', NULL, NULL, NULL, ''),
	(1793, 'Présentation du cornet de glace à l''Exposition de Saint-Louis', 1904, false, NULL, 'Le cornet de glace est popularisé lors de l''Exposition de Saint-Louis, suite à une pénurie de coupes à glace. Cette innovation devient rapidement un symbole de la culture américaine.', 'Les Grandes Expositions Universelles : Vitrines du progrès et des cultures du monde (1851-1937)', '', 'PENDING', '', '2026-03-04 07:23:47.489108+00', NULL, NULL, NULL, ''),
	(1794, 'Présentation de l''avion ''Louisiana Purchase'' à l''Exposition de Saint-Louis', 1904, false, NULL, 'L''avion ''Louisiana Purchase'', conçu par John P. Holland, est présenté à l''Exposition de Saint-Louis. Il symbolise les avancées de l''aviation au début du XXe siècle.', 'Les Grandes Expositions Universelles : Vitrines du progrès et des cultures du monde (1851-1937)', '', 'PENDING', '', '2026-03-04 07:23:47.489108+00', NULL, NULL, NULL, ''),
	(1795, 'Revendication formelle de la Terre de la Reine-Maud par la Norvège', 1939, false, NULL, 'La Norvège revendique officiellement la Terre de la Reine-Maud le 14 janvier 1939, une vaste région de l''Antarctique. Cette revendication est motivée par la volonté de sécuriser des intérêts territoriaux avant d''autres nations.', 'La Conquête du Pôle Sud : Des premières explorations aux bases scientifiques permanentes (1820-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.489108+00', NULL, NULL, NULL, ''),
	(1796, 'Première mention documentée d''un marché de Noël à Vienne', 1298, false, NULL, 'Le "Krippenmarkt" de Vienne est mentionné pour la première fois dans un document, marquant le début d''une longue tradition de marchés de Noël en Europe centrale. Il s''agissait d''une forme précoce de foire médiévale saisonnière.', 'L''histoire du cirque : Des saltimbanques médiévaux au Cirque du Soleil (1100-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.489108+00', NULL, NULL, NULL, ''),
	(1797, 'Première représentation documentée d''une pièce de théâtre profane en Angleterre (Le Jeu d''Adam)', 1150, false, NULL, 'Le "Jeu d''Adam", une pièce de théâtre en langue vernaculaire, est joué pour la première fois en Angleterre. Cette représentation marque une étape importante dans le développement du théâtre médiéval profane, distinct des drames liturgiques.', 'L''histoire du cirque : Des saltimbanques médiévaux au Cirque du Soleil (1100-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.489108+00', NULL, NULL, NULL, ''),
	(1798, 'Première représentation du cirque Franconi à Paris', 1807, false, NULL, 'La famille Franconi, d''origine italienne, fonde un cirque équestre qui devient l''un des plus célèbres d''Europe. Le cirque Franconi se distingue par ses spectacles équestres de haute voltige et ses reconstitutions historiques.', 'L''histoire du cirque : Des saltimbanques médiévaux au Cirque du Soleil (1100-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.489108+00', NULL, NULL, NULL, ''),
	(1799, 'Création du Cirque du Soleil par Guy Laliberté et Daniel Gauthier à Baie-Saint-Paul', 1984, false, NULL, 'Fondation de la troupe qui révolutionnera le cirque contemporain en intégrant des éléments de théâtre, de danse et de musique. Le Cirque du Soleil ne présente pas d''animaux.', 'L''histoire du cirque : Des saltimbanques médiévaux au Cirque du Soleil (1100-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.489108+00', NULL, NULL, NULL, ''),
	(1800, 'Fondation du Nouveau Cirque de Moscou sur le Mont des Moineaux', 1971, false, NULL, 'Ce cirque d''état devient un centre majeur d''innovation dans les arts du cirque en URSS. Il met en avant les prouesses techniques et artistiques des artistes.', 'L''histoire du cirque : Des saltimbanques médiévaux au Cirque du Soleil (1100-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.489108+00', NULL, NULL, NULL, ''),
	(1801, 'Première représentation de *Saltimbanco* à Montréal', 1992, false, NULL, '*Saltimbanco* est l''un des spectacles les plus populaires du Cirque du Soleil. Il se distingue par son esthétique urbaine et son énergie débordante.', 'L''histoire du cirque : Des saltimbanques médiévaux au Cirque du Soleil (1100-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.489108+00', NULL, NULL, NULL, ''),
	(1802, 'Départ du HMS Challenger de Portsmouth pour son expédition scientifique', 1872, false, NULL, 'Le HMS Challenger quitte Portsmouth, en Angleterre, le 21 décembre, marquant le début de l''expédition océanographique mondiale. L''expédition a duré près de quatre ans et a permis de recueillir des données précieuses sur les fonds marins, la vie marine et les courants océaniques.', 'L''exploration du fond des océans : De l''expédition du Challenger aux bathyscaphes et aux explorations robotisées (1872-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.489108+00', NULL, NULL, NULL, ''),
	(1803, 'Découverte du point le plus profond de l''océan Pacifique par le HMS Challenger', 1875, false, NULL, 'L''expédition du Challenger sonde et découvre le point le plus profond de l''océan Pacifique, plus tard nommé la fosse des Mariannes. Cette découverte a révolutionné la compréhension des profondeurs océaniques.', 'L''exploration du fond des océans : De l''expédition du Challenger aux bathyscaphes et aux explorations robotisées (1872-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.489108+00', NULL, NULL, NULL, ''),
	(1804, 'Publication du rapport final de l''expédition du Challenger', 1895, false, NULL, 'La publication des 50 volumes du rapport scientifique de l''expédition du Challenger est achevée. Ce rapport monumental a établi les bases de l''océanographie moderne.', 'L''exploration du fond des océans : De l''expédition du Challenger aux bathyscaphes et aux explorations robotisées (1872-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.489108+00', NULL, NULL, NULL, ''),
	(1805, 'Création du premier laboratoire océanographique aux États-Unis (Marine Biological Laboratory)', 1888, false, NULL, 'Fondation du Marine Biological Laboratory à Woods Hole, Massachusetts, inspiré par les découvertes de l''expédition du Challenger. Il devient un centre majeur de recherche en biologie marine et océanographie.', 'L''exploration du fond des océans : De l''expédition du Challenger aux bathyscaphes et aux explorations robotisées (1872-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.489108+00', NULL, NULL, NULL, ''),
	(1806, 'Lancement du programme international Census of Marine Life', 2000, false, NULL, 'Début du Census of Marine Life, un projet international de 10 ans visant à évaluer la diversité, la distribution et l''abondance de la vie marine dans les océans du monde. Il s''inscrit dans la continuité de l''exploration initiée par le Challenger.', 'L''exploration du fond des océans : De l''expédition du Challenger aux bathyscaphes et aux explorations robotisées (1872-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.489108+00', NULL, NULL, NULL, ''),
	(1807, 'Première plongée du submersible Cyana dans le rift des Açores (campagne CYAMAZ)', 1982, false, NULL, 'Le submersible français Cyana effectue sa première plongée dans le rift des Açores dans le cadre de la campagne CYAMAZ. L''objectif est d''étudier l''activité hydrothermale et les communautés biologiques associées.', 'L''exploration du fond des océans : De l''expédition du Challenger aux bathyscaphes et aux explorations robotisées (1872-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.489108+00', NULL, NULL, NULL, ''),
	(1808, 'Première plongée habitée au pôle Nord par le submersible Mir-1', 2007, false, NULL, 'Le submersible russe Mir-1 effectue la première plongée habitée au pôle Nord, atteignant le fond marin à une profondeur de 4 261 mètres. Cette expédition vise à étudier la géologie et la biologie des fonds marins arctiques.', 'L''exploration du fond des océans : De l''expédition du Challenger aux bathyscaphes et aux explorations robotisées (1872-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.489108+00', NULL, NULL, NULL, ''),
	(1809, 'Première cartographie complète du plancher océanique de l''Arctique par un AUV (Theseus)', 2003, false, NULL, 'L''AUV Theseus réalise une cartographie détaillée du plancher océanique sous la calotte glaciaire arctique, démontrant le potentiel des AUV pour l''exploration de zones inaccessibles.', 'L''exploration du fond des océans : De l''expédition du Challenger aux bathyscaphes et aux explorations robotisées (1872-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.489108+00', NULL, NULL, NULL, ''),
	(1810, 'Enregistrement du "Livery Stable Blues" par l''Original Dixieland Jass Band', 1917, false, NULL, 'L''Original Dixieland Jass Band enregistre "Livery Stable Blues" pour Victor Talking Machine Company. Considéré comme l''un des premiers enregistrements de jazz, il marque un tournant dans la diffusion de cette nouvelle musique.', 'L''histoire du jazz : Du ragtime aux courants contemporains (1890-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.489108+00', NULL, NULL, NULL, ''),
	(1811, 'Première représentation de l''opéra "Treemonisha" de Scott Joplin', 1915, false, NULL, 'Scott Joplin présente une version non orchestrée de son opéra "Treemonisha" à Texarkana, Texas. Bien que mal reçu à l''époque, l''œuvre est aujourd''hui reconnue comme une contribution importante à l''opéra américain.', 'L''histoire du jazz : Du ragtime aux courants contemporains (1890-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.489108+00', NULL, NULL, NULL, ''),
	(1812, 'Enregistrement de "Koko" par Charlie Parker, marquant un tournant dans le bebop', 1945, false, NULL, 'Charlie Parker enregistre "Koko" le 26 novembre 1945, un morceau considéré comme un jalon du bebop, caractérisé par son tempo rapide et ses improvisations complexes. Cet enregistrement a radicalement influencé le jazz moderne.', 'L''histoire du jazz : Du ragtime aux courants contemporains (1890-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.489108+00', NULL, NULL, NULL, ''),
	(1813, 'Sortie de l''album "Saxophone Colossus" de Sonny Rollins', 1956, false, NULL, '"Saxophone Colossus", considéré comme l''un des chefs-d''œuvre de Sonny Rollins, est sorti en 1956. L''album met en valeur son style d''improvisation unique et sa maîtrise du saxophone ténor.', 'L''histoire du jazz : Du ragtime aux courants contemporains (1890-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.489108+00', NULL, NULL, NULL, ''),
	(1814, 'Première du film *Shadows* de John Cassavetes, avec une bande originale de jazz improvisée', 1959, false, NULL, '*Shadows*, réalisé par John Cassavetes, sort en salle. La bande originale, improvisée par Charles Mingus et ses musiciens, reflète l''esprit du free jazz.', 'L''histoire du jazz : Du ragtime aux courants contemporains (1890-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.489108+00', NULL, NULL, NULL, ''),
	(1815, 'Ouverture du club de jazz Slug''s Saloon à New York', 1964, false, NULL, 'Slug''s Saloon ouvre ses portes dans l''East Village à New York. Il devient un lieu important pour les musiciens de free jazz comme Sun Ra, Albert Ayler et Cecil Taylor.', 'L''histoire du jazz : Du ragtime aux courants contemporains (1890-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.501463+00', NULL, NULL, NULL, ''),
	(1816, 'Publication de *A Love Supreme* de John Coltrane', 1965, false, NULL, 'John Coltrane publie *A Love Supreme*, un album considéré comme un chef-d''œuvre du jazz modal et spirituel. L''album est une suite en quatre parties exprimant la dévotion de Coltrane à Dieu.', 'L''histoire du jazz : Du ragtime aux courants contemporains (1890-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.501463+00', NULL, NULL, NULL, ''),
	(1817, 'Premier concert du Mahavishnu Orchestra à New York', 1971, false, NULL, 'Le Mahavishnu Orchestra, mené par John McLaughlin, donne son premier concert à New York. Ce groupe devient rapidement un pilier du jazz fusion avec son mélange de virtuosité instrumentale et d''influences rock et indiennes.', 'L''histoire du jazz : Du ragtime aux courants contemporains (1890-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.501463+00', NULL, NULL, NULL, ''),
	(1818, 'Sortie de l''album ''Head Hunters'' de Herbie Hancock', 1973, false, NULL, '''Head Hunters'' d''Herbie Hancock est publié, devenant l''un des albums de jazz fusion les plus vendus de tous les temps. Il incorpore des éléments de funk et de musique électronique, popularisant le genre auprès d''un public plus large.', 'L''histoire du jazz : Du ragtime aux courants contemporains (1890-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.501463+00', NULL, NULL, NULL, ''),
	(1819, 'Sortie de ''Black Radio'' de Robert Glasper Experiment, fusion de jazz, hip-hop et R&B', 2012, false, NULL, 'L''album ''Black Radio'' de Robert Glasper Experiment est publié, remportant un Grammy Award. Il marque une étape importante dans la fusion du jazz avec le hip-hop et le R&B contemporains.', 'L''histoire du jazz : Du ragtime aux courants contemporains (1890-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.501463+00', NULL, NULL, NULL, ''),
	(1820, 'Publication du traité alchimique ''Physica et Mystica'' attribué à Démocrite', 100, false, NULL, 'Ce texte, bien que portant le nom de Démocrite, est daté du Ier siècle et représente l''un des plus anciens écrits alchimiques grecs. Il témoigne de la fusion des connaissances philosophiques et techniques de l''époque.', 'L''histoire de l''Alchimie : Des origines à la recherche de la pierre philosophale (100 - 1789)', '', 'PENDING', '', '2026-03-04 07:23:47.501463+00', NULL, NULL, NULL, ''),
	(1821, 'Traduction du "Tetrabiblos" de Ptolémée en arabe par Mashallah ibn Athari', 762, false, NULL, 'Cette traduction a rendu l''astrologie hellénistique accessible aux érudits arabes, influençant le développement de l''alchimie et de l''astronomie dans le monde islamique. Elle a permis l''intégration des connaissances grecques dans la science arabe.', 'L''histoire de l''Alchimie : Des origines à la recherche de la pierre philosophale (100 - 1789)', '', 'PENDING', '', '2026-03-04 07:23:47.501463+00', NULL, NULL, NULL, ''),
	(1822, 'Publication du "Livre de la composition de l''alchimie" attribué à Jabir Ibn Hayyan', 850, false, NULL, 'Ce texte, l''un des plus importants du corpus jabirien, détaille des techniques de laboratoire et des théories alchimiques, influençant considérablement les pratiques alchimiques ultérieures. Il décrit des procédés chimiques et des équipements de laboratoire.', 'L''histoire de l''Alchimie : Des origines à la recherche de la pierre philosophale (100 - 1789)', '', 'PENDING', '', '2026-03-04 07:23:47.501463+00', NULL, NULL, NULL, ''),
	(1823, 'Construction de l''observatoire de Bagdad sous le règne du calife Al-Mu''tadid', 890, false, NULL, 'Cet observatoire permet des observations astronomiques précises, essentielles pour l''astrologie et l''alchimie, qui étaient étroitement liées à l''époque. Il contribue à l''amélioration des connaissances astronomiques et à la précision des calculs astrologiques.', 'L''histoire de l''Alchimie : Des origines à la recherche de la pierre philosophale (100 - 1789)', '', 'PENDING', '', '2026-03-04 07:23:47.501463+00', NULL, NULL, NULL, ''),
	(1824, 'Publication de ''The Sceptical Chymist'' de Robert Boyle', 1661, false, NULL, 'Robert Boyle publie ''The Sceptical Chymist'', un ouvrage fondateur qui remet en question les théories alchimiques traditionnelles et promeut une approche plus expérimentale et quantitative de la chimie. Il marque une étape importante vers la chimie moderne.', 'L''histoire de l''Alchimie : Des origines à la recherche de la pierre philosophale (100 - 1789)', '', 'PENDING', '', '2026-03-04 07:23:47.501463+00', NULL, NULL, NULL, ''),
	(1825, 'Découverte du phosphore par Hennig Brand', 1669, false, NULL, 'Hennig Brand, un alchimiste de Hambourg, découvre le phosphore en distillant de l''urine. C''est la première découverte d''un élément chimique identifiable, marquant une transition de l''alchimie à la chimie.', 'L''histoire de l''Alchimie : Des origines à la recherche de la pierre philosophale (100 - 1789)', '', 'PENDING', '', '2026-03-04 07:23:47.501463+00', NULL, NULL, NULL, ''),
	(1826, 'Première synthèse de l''urée par Friedrich Wöhler', 1828, false, NULL, 'Friedrich Wöhler synthétise l''urée à partir de composés inorganiques, réfutant la théorie de la force vitale qui postulait que les composés organiques ne pouvaient être créés que par des organismes vivants. Cet événement marque une étape cruciale dans le développement de la chimie organique.', 'L''histoire de l''Alchimie : Des origines à la recherche de la pierre philosophale (100 - 1789)', '', 'PENDING', '', '2026-03-04 07:23:47.501463+00', NULL, NULL, NULL, ''),
	(1827, 'Développement du programme General Problem Solver (GPS) par Allen Newell et Herbert A. Simon', 1957, false, NULL, 'GPS est conçu pour résoudre des problèmes dans divers domaines en utilisant des méthodes de résolution de problèmes générales. Il représente une tentative ambitieuse de créer une IA capable de raisonnement général.', 'L''Histoire de l''Intelligence Artificielle : Des premiers algorithmes aux réseaux neuronaux profonds (1943-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.501463+00', NULL, NULL, NULL, ''),
	(1828, 'Création du programme ELIZA par Joseph Weizenbaum', 1966, false, NULL, 'ELIZA est un programme de traitement du langage naturel capable de simuler une conversation avec un humain. Il illustre les premières tentatives de communication homme-machine et soulève des questions sur la nature de la compréhension.', 'L''Histoire de l''Intelligence Artificielle : Des premiers algorithmes aux réseaux neuronaux profonds (1943-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.501463+00', NULL, NULL, NULL, ''),
	(1829, 'Publication de ''A Heuristic Dendral Program for Explanatory Theory Formation'' par Feigenbaum, Buchanan, et Lederberg', 1971, false, NULL, 'Cet article décrit en détail le programme Dendral et son approche heuristique pour la formation de théories explicatives en chimie. Il marque une étape importante dans le développement des systèmes experts basés sur la connaissance.', 'L''Histoire de l''Intelligence Artificielle : Des premiers algorithmes aux réseaux neuronaux profonds (1943-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.501463+00', NULL, NULL, NULL, ''),
	(1830, 'Conférence inaugurale de l''American Association for Artificial Intelligence (AAAI)', 1980, false, NULL, 'La première conférence de l''AAAI, qui met en évidence les progrès significatifs dans le domaine de l''intelligence artificielle, y compris les systèmes experts, se tient à Stanford.', 'L''Histoire de l''Intelligence Artificielle : Des premiers algorithmes aux réseaux neuronaux profonds (1943-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.501463+00', NULL, NULL, NULL, ''),
	(1831, 'Publication de ''The Fifth Generation: Artificial Intelligence and Japan''s Computer Challenge to the World'' par Edward Feigenbaum et Pamela McCorduck', 1983, false, NULL, 'Cet ouvrage popularise l''idée des systèmes experts et de l''intelligence artificielle, contribuant à l''engouement pour ces technologies et à l''investissement massif dans la recherche et le développement.', 'L''Histoire de l''Intelligence Artificielle : Des premiers algorithmes aux réseaux neuronaux profonds (1943-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.501463+00', NULL, NULL, NULL, ''),
	(1832, 'Publication de l''article de Sepp Hochreiter et Jürgen Schmidhuber introduisant la Long Short-Term Memory (LSTM)', 1997, false, NULL, 'LSTM est une architecture de réseau de neurones récurrents (RNN) conçue pour traiter les dépendances à long terme dans les séquences de données. Elle a permis des avancées significatives dans le traitement du langage naturel et la reconnaissance vocale.', 'L''Histoire de l''Intelligence Artificielle : Des premiers algorithmes aux réseaux neuronaux profonds (1943-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.501463+00', NULL, NULL, NULL, ''),
	(1833, 'Introduction de l''algorithme AdaBoost par Freund et Schapire', 1997, false, NULL, 'AdaBoost (Adaptive Boosting) est un algorithme de boosting qui combine plusieurs classificateurs faibles pour créer un classificateur fort. Il a prouvé son efficacité dans de nombreuses applications de classification et de reconnaissance de motifs.', 'L''Histoire de l''Intelligence Artificielle : Des premiers algorithmes aux réseaux neuronaux profonds (1943-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.501463+00', NULL, NULL, NULL, ''),
	(1834, 'Publication de l''article sur le "Support Vector Machine" (SVM) par Cortes et Vapnik', 1995, false, NULL, 'Cet article présente une nouvelle approche pour la classification et la régression, basée sur la maximisation de la marge entre les classes. Le SVM devient rapidement un outil puissant et populaire en apprentissage automatique.', 'L''Histoire de l''Intelligence Artificielle : Des premiers algorithmes aux réseaux neuronaux profonds (1943-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.501463+00', NULL, NULL, NULL, ''),
	(1835, 'Création d''ImageNet, une base de données massive pour la recherche en vision par ordinateur', 2009, false, NULL, 'ImageNet contient des millions d''images annotées, organisées selon la hiérarchie de WordNet. Elle devient une ressource essentielle pour l''entraînement et l''évaluation des algorithmes de deep learning en vision par ordinateur.', 'L''Histoire de l''Intelligence Artificielle : Des premiers algorithmes aux réseaux neuronaux profonds (1943-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.501463+00', NULL, NULL, NULL, ''),
	(1836, 'Première édition imprimée de la Géographie de Ptolémée (édition de Bologne)', 1477, false, NULL, 'La ''Géographie'' de Ptolémée est imprimée pour la première fois à Bologne. Cette diffusion massive du texte et des cartes de Ptolémée influence profondément la cartographie de la Renaissance.', 'L''histoire de la cartographie : Des premières représentations du monde aux cartes numériques (600 AEC - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.501463+00', NULL, NULL, NULL, ''),
	(1837, 'Début du Grand Projet de triangulation de la France par l''Académie Royale des Sciences', 1733, false, NULL, 'L''Académie Royale des Sciences entreprend une triangulation à grande échelle de la France, marquant une étape cruciale dans le développement de la cartographie précise. Ce projet a permis d''améliorer significativement la précision des cartes et des relevés topographiques.', 'L''histoire de la cartographie : Des premières représentations du monde aux cartes numériques (600 AEC - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.501463+00', NULL, NULL, NULL, ''),
	(1838, 'Déclaration de la disponibilité sélective (SA) du GPS pour un usage civil', 1990, false, NULL, 'Le gouvernement américain active la Disponibilité Sélective (SA) du GPS. Cela dégrade intentionnellement la précision du signal GPS pour les utilisateurs civils.', 'L''histoire de la cartographie : Des premières représentations du monde aux cartes numériques (600 AEC - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.501463+00', NULL, NULL, NULL, ''),
	(1839, 'Adoption du "Troisième Paquet Aérien" par la Communauté Économique Européenne (CEE)', 1992, false, NULL, 'Ce paquet législatif finalise la libéralisation du ciel européen en supprimant les dernières restrictions sur les droits de trafic et les tarifs. Il crée un marché unique du transport aérien pleinement concurrentiel.', 'L''histoire de l''aviation commerciale : Des premiers vols aux compagnies low-cost (1914-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.501463+00', NULL, NULL, NULL, ''),
	(1840, 'Inauguration du Terrain de jeu de balle de Copán', 738, false, NULL, 'Le terrain de jeu de balle de Copán, l''un des plus grands et des plus finement décorés du monde maya, est inauguré. Il témoigne de l''importance du jeu de balle rituel dans la culture maya.', 'L''essor et la chute des cités Mayas : De la période préclassique à la conquête espagnole (200 AEC - 1697)', '', 'PENDING', '', '2026-03-04 07:23:47.501463+00', NULL, NULL, NULL, ''),
	(1841, 'Installation de la Stèle C à Quirigua', 775, false, NULL, 'La Stèle C, un monument colossal représentant le roi K''ak'' Tiliw Chan Yopaat, est érigée à Quirigua. Elle illustre la maîtrise de la sculpture maya et la puissance du souverain.', 'L''essor et la chute des cités Mayas : De la période préclassique à la conquête espagnole (200 AEC - 1697)', '', 'PENDING', '', '2026-03-04 07:23:47.501463+00', NULL, NULL, NULL, ''),
	(1842, 'Début du règne de Yax Nuun Ahiin II à Tikal', 768, false, NULL, 'Yax Nuun Ahiin II accède au trône de Tikal. Son règne est marqué par une période de prospérité et de construction de monuments importants.', 'L''essor et la chute des cités Mayas : De la période préclassique à la conquête espagnole (200 AEC - 1697)', '', 'PENDING', '', '2026-03-04 07:23:47.501463+00', NULL, NULL, NULL, ''),
	(1843, 'Début du règne d''Alphonse VI de León et Castille', 1065, false, NULL, 'Alphonse VI accède au trône et marque une période d''expansion territoriale et de consolidation du pouvoir chrétien dans la péninsule ibérique. Son règne est crucial dans la Reconquista.', 'L''essor et la chute des cités Mayas : De la période préclassique à la conquête espagnole (200 AEC - 1697)', '', 'PENDING', '', '2026-03-04 07:23:47.501463+00', NULL, NULL, NULL, ''),
	(1844, 'Début du règne d''Al-Mustansir Billah au Caire', 1036, false, NULL, 'Al-Mustansir Billah devient calife fatimide à l''âge de sept ans, marquant le début d''une longue période de règne instable et de déclin de l''influence fatimide.', 'L''essor et la chute des cités Mayas : De la période préclassique à la conquête espagnole (200 AEC - 1697)', '', 'PENDING', '', '2026-03-04 07:23:47.501463+00', NULL, NULL, NULL, ''),
	(1845, 'Début du règne de Malcolm III d''Écosse', 1058, false, NULL, 'Malcolm III monte sur le trône écossais après avoir vaincu Macbeth. Son règne marque une transition vers une culture plus anglicisée et une centralisation du pouvoir royal.', 'L''essor et la chute des cités Mayas : De la période préclassique à la conquête espagnole (200 AEC - 1697)', '', 'PENDING', '', '2026-03-04 07:23:47.501463+00', NULL, NULL, NULL, ''),
	(1846, 'Destruction de Mayapan', 1461, false, NULL, 'La ville de Mayapan est saccagée et brûlée, mettant fin à son rôle de capitale et précipitant la désintégration de la ligue de Mayapan. Cet événement marque un tournant majeur dans l''histoire maya du Yucatán.', 'L''essor et la chute des cités Mayas : De la période préclassique à la conquête espagnole (200 AEC - 1697)', '', 'PENDING', '', '2026-03-04 07:23:47.501463+00', NULL, NULL, NULL, ''),
	(1847, 'Publication des Lettres persanes de Montesquieu', 1721, false, NULL, 'Montesquieu publie anonymement une critique satirique de la société française et des institutions politiques à travers le regard de voyageurs persans fictifs. L''œuvre marque un tournant dans la pensée des Lumières.', 'L''histoire des samouraïs : Du guerrier au code d''honneur, du sabre à la modernisation (794-1877)', '', 'PENDING', '', '2026-03-04 07:23:47.501463+00', NULL, NULL, NULL, ''),
	(1848, 'Publication de "The Great Influenza" de John M. Barry', 2004, false, NULL, 'Publication du livre de John M. Barry, "The Great Influenza: The Story of the Deadliest Pandemic in History". Il contribue à raviver l''intérêt pour la pandémie de 1918.', 'L''histoire des pandémies mondiales : De la grippe espagnole au Sida (1918-2003)', '', 'PENDING', '', '2026-03-04 07:23:47.501463+00', NULL, NULL, NULL, ''),
	(1849, 'Production à grande échelle de pénicilline par fermentation submergée', 1943, false, NULL, 'Des scientifiques américains développent une méthode de fermentation submergée pour produire de la pénicilline à grande échelle. Cette avancée permet de répondre à la demande croissante pendant la Seconde Guerre mondiale.', 'L''histoire des pandémies mondiales : De la grippe espagnole au Sida (1918-2003)', '', 'PENDING', '', '2026-03-04 07:23:47.501463+00', NULL, NULL, NULL, ''),
	(1850, 'Publication de l''étude décisive de Chester Keefer sur la pénicilline', 1943, false, NULL, 'Chester Keefer publie un rapport important sur l''efficacité de la pénicilline dans le traitement de diverses infections. Ce rapport contribue à établir la pénicilline comme un médicament essentiel.', 'L''histoire des pandémies mondiales : De la grippe espagnole au Sida (1918-2003)', '', 'PENDING', '', '2026-03-04 07:23:47.501463+00', NULL, NULL, NULL, ''),
	(1851, 'Approbation du vaccin oral contre la polio (OPV) de Sabin aux États-Unis', 1962, false, NULL, 'Le vaccin oral vivant atténué développé par Albert Sabin est approuvé pour utilisation aux États-Unis. Il offre une immunité plus durable et est plus facile à administrer que le vaccin Salk.', 'L''histoire des pandémies mondiales : De la grippe espagnole au Sida (1918-2003)', '', 'PENDING', '', '2026-03-04 07:23:47.501463+00', NULL, NULL, NULL, ''),
	(1852, 'Publication du rapport du CDC décrivant une pneumonie rare chez de jeunes hommes homosexuels à Los Angeles', 1981, false, NULL, 'Ce rapport marque la première reconnaissance officielle de ce qui deviendra plus tard connu sous le nom de SIDA. Il alerte la communauté médicale sur une nouvelle menace pour la santé publique.', 'L''histoire des pandémies mondiales : De la grippe espagnole au Sida (1918-2003)', '', 'PENDING', '', '2026-03-04 07:23:47.501463+00', NULL, NULL, NULL, ''),
	(1853, 'Création du Programme mondial de lutte contre le SIDA (GPA) par l''Organisation Mondiale de la Santé (OMS)', 1987, false, NULL, 'Ce programme vise à coordonner les efforts internationaux pour prévenir la propagation du VIH et améliorer la prise en charge des personnes vivant avec le SIDA. Il marque une étape importante dans la réponse mondiale à la pandémie.', 'L''histoire des pandémies mondiales : De la grippe espagnole au Sida (1918-2003)', '', 'PENDING', '', '2026-03-04 07:23:47.501463+00', NULL, NULL, NULL, ''),
	(1854, 'Ouverture du port de Canton au commerce maritime sous la dynastie Han', 111, false, NULL, 'L''ouverture de Canton stimule le commerce maritime de la soie, créant une route alternative à la Route de la Soie terrestre. Cela diversifie les échanges et renforce l''influence commerciale de la Chine.', 'La route de la soie : Des premières caravanes aux nouvelles routes commerciales (200 AEC - 1453)', '', 'PENDING', '', '2026-03-04 07:23:47.501463+00', NULL, NULL, NULL, ''),
	(1855, 'Achèvement de la construction des Grottes de Yungang (première phase)', 494, false, NULL, 'La première phase de construction des Grottes de Yungang, un site majeur de l''art bouddhique rupestre en Chine, est achevée. Ces grottes témoignent de l''influence du bouddhisme et de l''art gréco-bouddhique sur l''art chinois.', 'La route de la soie : Des premières caravanes aux nouvelles routes commerciales (200 AEC - 1453)', '', 'PENDING', '', '2026-03-04 07:23:47.501463+00', NULL, NULL, NULL, ''),
	(1856, 'Adoption du serment olympique par Victor Boin aux Jeux d''Anvers', 1920, false, NULL, 'Le serment, écrit par Pierre de Coubertin, est prononcé pour la première fois. Il symbolise l''engagement des athlètes envers l''esprit sportif et les règles des Jeux.', 'Les Jeux Olympiques Modernes : De la renaissance à l''ère des super-athlètes (1896-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.501463+00', NULL, NULL, NULL, ''),
	(1857, 'Ouverture des Jeux olympiques d''été de 2000 à Sydney', 2000, false, NULL, 'Cérémonie d''ouverture des XXVIIe olympiades, mettant en avant la culture australienne et l''esprit sportif. Ces jeux ont renforcé la position de l''Australie sur la scène internationale.', 'Les Jeux Olympiques Modernes : De la renaissance à l''ère des super-athlètes (1896-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.501463+00', NULL, NULL, NULL, ''),
	(1858, 'Inauguration du Utah Olympic Park Track (JO de Salt Lake City)', 2002, false, NULL, 'Le Utah Olympic Park Track accueille les épreuves de bobsleigh, luge et skeleton des Jeux olympiques d''hiver. Il devient un lieu emblématique des sports de glisse.', 'Les Jeux Olympiques Modernes : De la renaissance à l''ère des super-athlètes (1896-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.501463+00', NULL, NULL, NULL, ''),
	(1859, 'Début des compétitions de ski cross aux X Games (Aspen)', 2004, false, NULL, 'Le ski cross fait son entrée aux X Games d''Aspen, Colorado. Cet événement marque l''essor de cette discipline spectaculaire et audacieuse.', 'Les Jeux Olympiques Modernes : De la renaissance à l''ère des super-athlètes (1896-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.501463+00', NULL, NULL, NULL, ''),
	(1860, 'Ouverture du pont Eads à St. Louis, Missouri', 1874, false, NULL, 'Ce pont, le premier pont en acier important, permet le passage du trafic ferroviaire et routier au-dessus du Mississippi. Il facilite le commerce et le transport dans la région.', 'La Conquête de l''Ouest américain : De l''expédition de Lewis et Clark à la fin des guerres indiennes', '', 'PENDING', '', '2026-03-04 07:23:47.501463+00', NULL, NULL, NULL, ''),
	(1861, 'Début du règne de Abdallah ben Yasin, fondateur de la dynastie almoravide', 1040, false, NULL, 'Abdallah ben Yasin, un théologien, commence à prêcher un islam rigoriste parmi les tribus berbères Sanhadja, marquant le début de l''expansion almoravide. Il établit un ribat, une forteresse monastique, d''où le nom ''al-Murabitun'' (ceux du ribat).', 'L''essor des Royaumes Africains : Du Royaume de Koumbi Saleh à la chute du Grand Zimbabwe (750-1450)', '', 'PENDING', '', '2026-03-04 07:23:47.501463+00', NULL, NULL, NULL, ''),
	(1862, 'Siège et prise de Ghana par les Almoravides', 1076, false, NULL, 'Les Almoravides assiègent et prennent Koumbi Saleh, la capitale de l''Empire du Ghana. Cet événement marque le déclin de l''influence de Ghana et l''expansion de l''influence almoravide en Afrique de l''Ouest.', 'L''essor des Royaumes Africains : Du Royaume de Koumbi Saleh à la chute du Grand Zimbabwe (750-1450)', '', 'PENDING', '', '2026-03-04 07:23:47.501463+00', NULL, NULL, NULL, ''),
	(1863, 'Début du règne de Soundiata Keïta en tant que Mansa du Mali', 1240, false, NULL, 'Soundiata Keïta est officiellement intronisé Mansa, ou empereur, du Mali, consolidant son autorité sur un vaste territoire. Son règne marque le début d''une période de prospérité et d''expansion pour l''empire.', 'L''essor des Royaumes Africains : Du Royaume de Koumbi Saleh à la chute du Grand Zimbabwe (750-1450)', '', 'PENDING', '', '2026-03-04 07:23:47.501463+00', NULL, NULL, NULL, ''),
	(1864, 'Institution du Gbara, assemblée consultative de l''Empire du Mali', 1240, false, NULL, 'Soundiata Keïta met en place le Gbara, une assemblée de notables représentant les différents clans et régions de l''empire. Le Gbara joue un rôle consultatif auprès du Mansa.', 'L''essor des Royaumes Africains : Du Royaume de Koumbi Saleh à la chute du Grand Zimbabwe (750-1450)', '', 'PENDING', '', '2026-03-04 07:23:47.501463+00', NULL, NULL, NULL, ''),
	(1865, 'Abandon progressif de la capitale du Grand Zimbabwe', 1450, false, NULL, 'La capitale du Grand Zimbabwe est progressivement abandonnée par ses habitants. D''autres centres de pouvoir émergent dans la région, marquant la fin de son hégémonie.', 'L''essor des Royaumes Africains : Du Royaume de Koumbi Saleh à la chute du Grand Zimbabwe (750-1450)', '', 'PENDING', '', '2026-03-04 07:23:47.513308+00', NULL, NULL, NULL, ''),
	(1866, 'Henry Cavendish mesure la constante gravitationnelle (G) avec une balance de torsion', 1798, false, NULL, 'Cette expérience permet de déterminer la densité de la Terre et de calculer la masse des corps célestes. Elle confirme expérimentalement la loi de la gravitation universelle de Newton.', 'Les Grandes Découvertes Scientifiques : De la théorie héliocentrique à la classification des éléments (1543-1869)', '', 'PENDING', '', '2026-03-04 07:23:47.513308+00', NULL, NULL, NULL, ''),
	(1867, 'Publication par Antoine Lavoisier de ''Opuscules physiques et chimiques''', 1774, false, NULL, 'Antoine Lavoisier publie ''Opuscules physiques et chimiques'', un ouvrage où il commence à remettre en question la théorie du phlogistique. Il y décrit ses expériences sur la calcination des métaux et l''importance de l''air dans ce processus.', 'Les Grandes Découvertes Scientifiques : De la théorie héliocentrique à la classification des éléments (1543-1869)', '', 'PENDING', '', '2026-03-04 07:23:47.513308+00', NULL, NULL, NULL, ''),
	(1868, 'Publication du ''Traité élémentaire de chimie'' par Antoine Lavoisier', 1789, false, NULL, 'Antoine Lavoisier publie son ''Traité élémentaire de chimie'', un ouvrage fondateur de la chimie moderne. Il y expose sa nouvelle nomenclature chimique, sa théorie de la combustion basée sur l''oxygène, et sa loi de conservation de la masse.', 'Les Grandes Découvertes Scientifiques : De la théorie héliocentrique à la classification des éléments (1543-1869)', '', 'PENDING', '', '2026-03-04 07:23:47.513308+00', NULL, NULL, NULL, ''),
	(1869, 'Présentation du premier tableau périodique des éléments par Dmitri Mendeleïev', 1869, false, NULL, 'Dmitri Mendeleïev présente son tableau périodique des éléments à la Société chimique russe. Il classe les éléments selon leur masse atomique et prédit l''existence de nouveaux éléments.', 'Les Grandes Découvertes Scientifiques : De la théorie héliocentrique à la classification des éléments (1543-1869)', '', 'PENDING', '', '2026-03-04 07:23:47.513308+00', NULL, NULL, NULL, ''),
	(1870, 'Construction du premier four impérial dédié à la production de thé à Gu Zhu', 771, false, NULL, 'Un four impérial est construit à Gu Zhu (province du Zhejiang) pour produire du thé spécialement pour la cour. Cela témoigne de l''importance croissante du thé dans la culture impériale.', 'L''histoire du thé : De la légende de Shen Nong aux salons de thé modernes (2737 AEC - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.513308+00', NULL, NULL, NULL, ''),
	(1871, 'L''empereur Tang Muzong offre du thé aux ministres lors d''un banquet', 821, false, NULL, 'L''empereur Muzong offre personnellement du thé à ses ministres lors d''un banquet officiel. Cet événement symbolise l''intégration du thé dans les rituels de la cour.', 'L''histoire du thé : De la légende de Shen Nong aux salons de thé modernes (2737 AEC - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.513308+00', NULL, NULL, NULL, ''),
	(1872, 'Développement des ''théâtres de thé'' (chayuan) dans les villes Tang', 840, false, NULL, 'Les ''chayuan'' (théâtres de thé) se développent dans les villes, offrant un lieu de socialisation et de dégustation de thé. Ils contribuent à la diffusion de la culture du thé auprès d''un public plus large.', 'L''histoire du thé : De la légende de Shen Nong aux salons de thé modernes (2737 AEC - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.513308+00', NULL, NULL, NULL, ''),
	(1873, 'Commercialisation des échantillons de thé en sachets de soie par Thomas Sullivan', 1904, false, NULL, 'Thomas Sullivan, un marchand de thé new-yorkais, commence à envoyer des échantillons de thé à ses clients dans de petits sachets de soie. L''invention du sachet de thé est née d''une erreur d''interprétation de ses clients.', 'L''histoire du thé : De la légende de Shen Nong aux salons de thé modernes (2737 AEC - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.513308+00', NULL, NULL, NULL, ''),
	(1874, 'Lancement du "T-Sac" par la société allemande Teekanne', 1949, false, NULL, 'Teekanne lance le "T-Sac", un sachet de thé en papier thermoscellé, améliorant la qualité et la commodité du thé en sachet. Cette innovation renforce la position de Teekanne sur le marché du thé.', 'L''histoire du thé : De la légende de Shen Nong aux salons de thé modernes (2737 AEC - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.513308+00', NULL, NULL, NULL, ''),
	(1875, 'Inauguration du premier salon de thé "TWG Tea" à Singapour', 2007, false, NULL, 'Le premier salon de thé "TWG Tea" ouvre ses portes à Singapour, offrant une vaste sélection de thés du monde entier. Il marque le début de l''expansion internationale de la marque.', 'L''histoire du thé : De la légende de Shen Nong aux salons de thé modernes (2737 AEC - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.513308+00', NULL, NULL, NULL, ''),
	(1876, 'Ouverture du premier salon de thé "Ten Ren Tea" à Taïwan', 1953, false, NULL, 'Ten Ren Tea, une chaîne de salons de thé spécialisée dans le thé taïwanais, ouvre son premier magasin à Taïwan. Elle joue un rôle important dans la popularisation du thé taïwanais à l''échelle mondiale.', 'L''histoire du thé : De la légende de Shen Nong aux salons de thé modernes (2737 AEC - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.513308+00', NULL, NULL, NULL, ''),
	(1877, 'Lancement du "Frappuccino" par Starbucks', 1995, false, NULL, 'Starbucks lance le "Frappuccino", une boisson glacée à base de café, qui devient rapidement un succès mondial. Cette innovation contribue à l''essor de la marque et à la popularisation des boissons glacées au café.', 'L''histoire du thé : De la légende de Shen Nong aux salons de thé modernes (2737 AEC - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.513308+00', NULL, NULL, NULL, ''),
	(1878, 'Introduction du papier au Japon par des moines bouddhistes coréens', 614, false, NULL, 'Des moines bouddhistes coréens introduisent le papier au Japon, où il est rapidement adopté pour l''écriture et l''art. Le papier devient un élément essentiel de la culture japonaise.', 'L''histoire du papier : De l''invention chinoise à l''ère numérique (105 - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.513308+00', NULL, NULL, NULL, ''),
	(1879, 'Établissement du Daegakguksa (atelier de fabrication de papier) en Corée', 1086, false, NULL, 'Le roi Seonjong de Goryeo établit le Daegakguksa, un atelier gouvernemental dédié à la production de papier de haute qualité pour les besoins de la cour et des monastères bouddhistes.', 'L''histoire du papier : De l''invention chinoise à l''ère numérique (105 - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.513308+00', NULL, NULL, NULL, ''),
	(1880, 'Invention du procédé de fabrication de la pâte à papier à partir de bois par Friedrich Gottlob Keller', 1844, false, NULL, 'Friedrich Gottlob Keller brevète un procédé permettant de fabriquer de la pâte à papier à partir de fibres de bois, une alternative moins coûteuse et plus abondante que les chiffons. Cette invention a contribué à réduire le prix du papier et à démocratiser l''accès à l''information.', 'L''histoire du papier : De l''invention chinoise à l''ère numérique (105 - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.513308+00', NULL, NULL, NULL, ''),
	(1881, 'Début des fouilles officielles à Pompéi sous Charles III', 1748, false, NULL, 'Charles III, roi de Naples, lance les premières fouilles archéologiques officielles à Pompéi. Ces excavations révèlent progressivement les bâtiments, les objets et les corps figés dans la cendre.', 'L''histoire des grandes catastrophes naturelles : De l''éruption du Vésuve au tsunami de Fukushima (79 - 2011)', '', 'PENDING', '', '2026-03-04 07:23:47.513308+00', NULL, NULL, NULL, ''),
	(1882, 'Introduction de la règle du « but en or » par l''IFAB', 1993, false, NULL, 'L''International Football Association Board (IFAB) approuve la règle du but en or. Cette règle met fin immédiatement à un match de prolongation si une équipe marque.', 'L''histoire du football : Des premiers matchs aux Coupes du Monde modernes (1863 - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.513308+00', NULL, NULL, NULL, ''),
	(1883, 'Création de la Confédération sud-américaine de football (CONMEBOL)', 1916, false, NULL, 'La Confédération sud-américaine de football (CONMEBOL) est fondée le 9 juillet. Elle vise à organiser et réglementer le football en Amérique du Sud, et à promouvoir le développement du sport dans la région.', 'L''histoire du football : Des premiers matchs aux Coupes du Monde modernes (1863 - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.513308+00', NULL, NULL, NULL, ''),
	(1884, 'Publication de ''Soccernomics'' par Simon Kuper et Stefan Szymanski', 2009, false, NULL, 'Ce livre analyse le football à travers une lentille économique et statistique, révélant des tendances et des stratégies basées sur des données. Il influence la gestion des clubs et les approches tactiques en mettant l''accent sur l''analyse objective.', 'L''histoire du football : Des premiers matchs aux Coupes du Monde modernes (1863 - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.513308+00', NULL, NULL, NULL, ''),
	(1885, 'Début de la construction du Fort Saint-Louis à Léogâne (Saint-Domingue)', 1698, false, NULL, 'Initiée par le gouverneur Jean-Baptiste du Casse, cette construction vise à contrôler les activités maritimes et à réprimer la piraterie croissante dans la région.', 'L''Âge d''or de la flibuste dans les Caraïbes : Des boucaniers aux pirates gentlemen (1620-1730)', '', 'PENDING', '', '2026-03-04 07:23:47.513308+00', NULL, NULL, NULL, ''),
	(1886, 'Première mention du café en Europe par Prospero Alpini', 1592, false, NULL, 'Le botaniste italien Prospero Alpini décrit le café dans son ouvrage ''De Plantis Aegypti'', après l''avoir observé en Égypte. C''est l''une des premières descriptions du café accessible au public européen.', 'L''histoire du café : De la légende de Kaldi aux Starbucks (850 - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.513308+00', NULL, NULL, NULL, ''),
	(1887, 'Première mention du café dans un texte écrit par Abd al-Qadir al-Jaziri', 1587, false, NULL, 'Le manuscrit ''Umdat al-Safwa fi hill al-qahwa'' d''Abd al-Qadir al-Jaziri est le premier texte connu à décrire l''histoire et l''usage du café. Il détaille son introduction à La Mecque et à Médine.', 'L''histoire du café : De la légende de Kaldi aux Starbucks (850 - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.513308+00', NULL, NULL, NULL, ''),
	(1888, 'Autorisation officielle de la consommation de café par le Mufti de La Mecque', 1511, false, NULL, 'Après des débats religieux sur la licéité du café, le Mufti de La Mecque émet une fatwa autorisant sa consommation. Cela marque un tournant dans l''acceptation du café dans le monde musulman.', 'L''histoire du café : De la légende de Kaldi aux Starbucks (850 - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.513308+00', NULL, NULL, NULL, ''),
	(1889, 'Arrivée des premiers grains de café à Venise', 1615, false, NULL, 'Des marchands vénitiens rapportent les premiers grains de café en Europe. Cela marque le début de l''introduction du café en Occident.', 'L''histoire du café : De la légende de Kaldi aux Starbucks (850 - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.513308+00', NULL, NULL, NULL, ''),
	(1890, 'Ouverture du premier café à Londres', 1652, false, NULL, 'Le premier café londonien ouvre ses portes, initiant la culture du café dans la capitale anglaise. Il devient rapidement un lieu de rencontre populaire pour les intellectuels et les hommes d''affaires.', 'L''histoire du café : De la légende de Kaldi aux Starbucks (850 - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.513308+00', NULL, NULL, NULL, ''),
	(1891, 'Inauguration du Café Procope à Paris', 1686, false, NULL, 'Le Café Procope, fondé par l''Italien Francesco Procopio dei Coltelli, ouvre à Paris. Il devient un lieu de rencontre emblématique pour les écrivains, les philosophes et les artistes.', 'L''histoire du café : De la légende de Kaldi aux Starbucks (850 - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.513308+00', NULL, NULL, NULL, ''),
	(1892, 'Introduction du café à New York (Nouvelle-Amsterdam)', 1668, false, NULL, 'Le café est introduit à New York, alors Nouvelle-Amsterdam, par les colons néerlandais. Il marque le début de la consommation de café en Amérique du Nord.', 'L''histoire du café : De la légende de Kaldi aux Starbucks (850 - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.513308+00', NULL, NULL, NULL, ''),
	(1893, 'Introduction du système de culture du café en terrasses au Kenya', 1900, false, NULL, 'Les colons britanniques introduisent la culture du café en terrasses au Kenya. Cette technique améliore le rendement des plantations et contribue au développement de l''industrie caféière kenyane.', 'L''histoire du café : De la légende de Kaldi aux Starbucks (850 - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.513308+00', NULL, NULL, NULL, ''),
	(1894, 'Howard Schultz rejoint Starbucks en tant que directeur du marketing', 1982, false, NULL, 'Howard Schultz rejoint Starbucks et introduit l''idée de servir du café expresso, inspiré par les cafés italiens. Cette vision transformera Starbucks en une chaîne de cafés.', 'L''histoire du café : De la légende de Kaldi aux Starbucks (850 - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.513308+00', NULL, NULL, NULL, ''),
	(1895, 'Sortie du film "À bout de souffle" de Jean-Luc Godard', 1960, false, NULL, 'Sortie en salle du film "À bout de souffle" de Jean-Luc Godard, un film manifeste de la Nouvelle Vague française. Il marque une rupture avec les conventions narratives et esthétiques du cinéma traditionnel.', 'L''histoire du cinéma : Des premières projections aux blockbusters modernes (1895-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.513308+00', NULL, NULL, NULL, ''),
	(1896, 'Circumnavigation de l''Afrique par une expédition phénicienne commandée par Nékao II', 600, false, NULL, 'Selon Hérodote, le pharaon Nékao II envoie une expédition phénicienne explorer les côtes africaines. L''expédition aurait duré trois ans et prouvé que l''Afrique était entourée par la mer.', 'L''histoire des grands explorateurs fluviaux : Des premières expéditions sur le Nil à la découverte de l''Amazone (1700 AEC - 1638)', '', 'PENDING', '', '2026-03-04 07:23:47.513308+00', NULL, NULL, NULL, ''),
	(1897, 'Bataille navale de Cumes : Les Grecs de Cumes défont les Étrusques et les Carthaginois', 474, false, NULL, 'Une coalition de Carthaginois et d''Étrusques est défaite par la flotte grecque de Cumes, mettant fin à l''expansion carthaginoise en Italie.', 'L''histoire des grands explorateurs fluviaux : Des premières expéditions sur le Nil à la découverte de l''Amazone (1700 AEC - 1638)', '', 'PENDING', '', '2026-03-04 07:23:47.513308+00', NULL, NULL, NULL, ''),
	(1898, 'Achèvement du ''Fossé de Corbulo'' reliant les fleuves Rhin et Meuse', 47, false, NULL, 'Le ''Fossé de Corbulo'', un canal reliant le Rhin et la Meuse, est achevé sous la direction du général romain Cnaeus Domitius Corbulo. Il améliore la navigation et le transport de troupes et de marchandises dans la région de Germanie inférieure.', 'L''histoire des grands explorateurs fluviaux : Des premières expéditions sur le Nil à la découverte de l''Amazone (1700 AEC - 1638)', '', 'PENDING', '', '2026-03-04 07:23:47.513308+00', NULL, NULL, NULL, ''),
	(1899, 'Retour de l''expédition de Pedro Teixeira à Belém', 1639, false, NULL, 'L''expédition de Pedro Teixeira arrive à Belém, marquant la fin de son voyage de remontée et de descente de l''Amazone. L''expédition a permis de cartographier la région et de renforcer la présence portugaise.', 'L''histoire des grands explorateurs fluviaux : Des premières expéditions sur le Nil à la découverte de l''Amazone (1700 AEC - 1638)', '', 'PENDING', '', '2026-03-04 07:23:47.513308+00', NULL, NULL, NULL, ''),
	(1900, 'Éruption du volcan Xitle qui force l''abandon de Cuicuilco et favorise l''ascension de Teotihuacan', 100, false, NULL, 'L''éruption du Xitle dévaste Cuicuilco, un centre urbain majeur, permettant à Teotihuacan de devenir la puissance dominante dans le bassin de Mexico. Cet événement marque un tournant dans l''histoire de la région.', 'L''essor et la chute des empires précolombiens : Des Olmèques aux Incas (1500 AEC - 1533)', '', 'PENDING', '', '2026-03-04 07:23:47.513308+00', NULL, NULL, NULL, ''),
	(1901, 'Construction de La Ciudadela et du Temple de Quetzalcoatl à Teotihuacan', 500, false, NULL, 'Achèvement de la construction de La Ciudadela, un vaste complexe cérémoniel et administratif, incluant le Temple de Quetzalcoatl, orné de sculptures complexes. Ce complexe témoigne de la sophistication de la société teotihuacana.', 'L''essor et la chute des empires précolombiens : Des Olmèques aux Incas (1500 AEC - 1533)', '', 'PENDING', '', '2026-03-04 07:23:47.513308+00', NULL, NULL, NULL, ''),
	(1902, 'Consécration de l''autel majeur de la cathédrale Notre-Dame de Paris par le pape Alexandre III', 1182, false, NULL, 'Cet événement marque une étape importante dans la construction de la cathédrale, bien que les travaux se soient poursuivis pendant encore plusieurs décennies. La présence du pape Alexandre III confère une grande importance à cette consécration.', 'La construction des cathédrales gothiques : De Saint-Denis à la cathédrale de Cologne (1144-1880)', '', 'PENDING', '', '2026-03-04 07:23:47.513308+00', NULL, NULL, NULL, ''),
	(1903, 'Première utilisation des orgues de Notre-Dame de Paris', 1334, false, NULL, 'L''installation et la première utilisation des orgues marquent un enrichissement de la liturgie et de la vie musicale à Notre-Dame. Elles deviendront un élément central de la cathédrale.', 'La construction des cathédrales gothiques : De Saint-Denis à la cathédrale de Cologne (1144-1880)', '', 'PENDING', '', '2026-03-04 07:23:47.513308+00', NULL, NULL, NULL, ''),
	(1904, 'Consécration du maître-autel de la cathédrale Notre-Dame d''Amiens', 1269, false, NULL, 'Le maître-autel est consacré, marquant une étape importante dans l''aménagement intérieur de la cathédrale. Cet événement symbolise la dédication du lieu au culte divin.', 'La construction des cathédrales gothiques : De Saint-Denis à la cathédrale de Cologne (1144-1880)', '', 'PENDING', '', '2026-03-04 07:23:47.513308+00', NULL, NULL, NULL, ''),
	(1905, 'Première diffusion de "Hélène et les Garçons" sur TF1', 1992, false, NULL, 'La série "Hélène et les Garçons" est diffusée pour la première fois sur TF1, rencontrant un succès immédiat auprès des jeunes. Elle symbolise l''évolution de la programmation télévisuelle vers des contenus plus axés sur les adolescents.', 'L''histoire de la télévision : Des premières émissions expérimentales à la TNT HD (1926 - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.513308+00', NULL, NULL, NULL, ''),
	(1906, 'Brevet de Frederic Ives pour le Kromskop, un système de photographie couleur additive', 1892, false, NULL, 'Le Kromskop utilise trois filtres de couleur (rouge, vert, bleu) pour capturer et projeter des images en couleur. Il est commercialisé avec succès et contribue à populariser la photographie couleur.', 'L''histoire de la photographie : Des premières expériences aux appareils numériques (1826-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.513308+00', NULL, NULL, NULL, ''),
	(1907, 'Commercialisation du Kodak Autographic Camera permettant d''inscrire des notes sur la pellicule', 1915, false, NULL, 'Cet appareil permet aux photographes d''écrire directement sur la pellicule au moment de la prise de vue, ajoutant une dimension documentaire à leurs photos.', 'L''histoire de la photographie : Des premières expériences aux appareils numériques (1826-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.513308+00', NULL, NULL, NULL, ''),
	(1908, 'Création du format d''image JPEG par le Joint Photographic Experts Group', 1992, false, NULL, 'Le format JPEG devient un standard pour la compression d''images numériques, facilitant le stockage et le partage des photos. Son adoption massive contribue à l''essor de la photographie numérique.', 'L''histoire de la photographie : Des premières expériences aux appareils numériques (1826-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.513308+00', NULL, NULL, NULL, ''),
	(1909, 'Consécration de la Basilique de Sainte-Anne-de-Beaupré', 1676, false, NULL, 'La basilique de Sainte-Anne-de-Beaupré, au Québec, est consacrée, devenant un important lieu de pèlerinage en Amérique du Nord. Elle attire des fidèles en quête de guérison et de grâces spirituelles.', 'L''histoire des Pèlerinages : De l''Antiquité au tourisme religieux moderne (500 AEC - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.513308+00', NULL, NULL, NULL, ''),
	(1910, 'Début du règne d''Obiri Yeboa, fondateur de l''empire Ashanti', 1660, false, NULL, 'Obiri Yeboa commence son règne, jetant les bases de l''empire Ashanti, qui allait dominer le commerce de l''or dans la région. Son règne marque une transition dans le contrôle et l''organisation du commerce de l''or.', 'Les routes du commerce transsaharien : De l''or du Ghana aux manuscrits de Tombouctou (750 - 1600)', '', 'PENDING', '', '2026-03-04 07:23:47.513308+00', NULL, NULL, NULL, ''),
	(1911, 'Première mention écrite de Tombouctou', 1154, false, NULL, 'Le géographe arabe Al-Idrisi mentionne Tombouctou dans sa description du monde connu. Bien que la ville existe probablement depuis un certain temps, cette mention marque sa première apparition dans les sources écrites, témoignant de son importance croissante.', 'Les routes du commerce transsaharien : De l''or du Ghana aux manuscrits de Tombouctou (750 - 1600)', '', 'PENDING', '', '2026-03-04 07:23:47.513308+00', NULL, NULL, NULL, ''),
	(1912, 'Construction de la Grande Mosquée de Tlemcen (Mosquée de Tlemcen)', 1136, false, NULL, 'Yusuf Ibn Tashfin, sultan almoravide, ordonne la construction de la Grande Mosquée de Tlemcen. La mosquée devient un centre religieux et commercial important, stimulant les échanges dans la région.', 'Les routes du commerce transsaharien : De l''or du Ghana aux manuscrits de Tombouctou (750 - 1600)', '', 'PENDING', '', '2026-03-04 07:23:47.513308+00', NULL, NULL, NULL, ''),
	(1913, 'Conquête de Tombouctou par les armées marocaines', 1591, false, NULL, 'Les forces marocaines, dirigées par Djouder Pacha, prennent Tombouctou après la bataille de Tondibi. Cet événement marque le déclin de l''empire Songhaï et une période de troubles pour la ville.', 'Les routes du commerce transsaharien : De l''or du Ghana aux manuscrits de Tombouctou (750 - 1600)', '', 'PENDING', '', '2026-03-04 07:23:47.513308+00', NULL, NULL, NULL, ''),
	(1914, 'Construction de la bibliothèque de l''Université Al Quaraouiyine', 1349, false, NULL, 'Le sultan mérinide Abu Inan Faris ordonne la construction d''une bibliothèque au sein de l''université. Cette bibliothèque abrite une collection précieuse de manuscrits anciens et de textes rares.', 'L''histoire des grandes universités : De l''âge d''or islamique aux campus du XXIe siècle', '', 'PENDING', '', '2026-03-04 07:23:47.513308+00', NULL, NULL, NULL, ''),
	(1915, 'Restauration majeure de la bibliothèque Al Quaraouiyine initiée par le Ministère de la Culture marocain', 2012, false, NULL, 'Le Ministère de la Culture marocain lance un projet de restauration ambitieux pour préserver et moderniser la bibliothèque. La restauration vise à protéger les manuscrits anciens et à améliorer les installations pour les chercheurs.', 'L''histoire des grandes universités : De l''âge d''or islamique aux campus du XXIe siècle', '', 'PENDING', '', '2026-03-04 07:23:47.524937+00', NULL, NULL, NULL, ''),
	(1916, 'Réouverture de la bibliothèque Al Quaraouiyine après restauration', 2016, false, NULL, 'Après plusieurs années de travaux, la bibliothèque de l''Université Al Quaraouiyine rouvre ses portes au public. La réouverture marque une nouvelle ère pour la conservation du patrimoine et la recherche académique.', 'L''histoire des grandes universités : De l''âge d''or islamique aux campus du XXIe siècle', '', 'PENDING', '', '2026-03-04 07:23:47.524937+00', NULL, NULL, NULL, ''),
	(1917, 'Achèvement de la madrasa al-Adiliyya à Alep', 1124, false, NULL, 'La madrasa al-Adiliyya à Alep, commandée par le sultan Nur ad-Din Zangi, est achevée, devenant un centre d''enseignement du droit islamique et un symbole de la renaissance sunnite sous les Zengides.', 'L''histoire des grandes universités : De l''âge d''or islamique aux campus du XXIe siècle', '', 'PENDING', '', '2026-03-04 07:23:47.524937+00', NULL, NULL, NULL, ''),
	(1918, 'Transformation d''Al-Azhar en université par le calife Al-Aziz Billah', 988, false, NULL, 'Al-Aziz Billah transforme la mosquée Al-Azhar en une université à part entière. Des cours structurés et des programmes d''études sont mis en place.', 'L''histoire des grandes universités : De l''âge d''or islamique aux campus du XXIe siècle', '', 'PENDING', '', '2026-03-04 07:23:47.524937+00', NULL, NULL, NULL, ''),
	(1919, 'Création d''une bibliothèque à Al-Azhar', 1005, false, NULL, 'Le calife Al-Hakim bi-Amr Allah fonde une bibliothèque richement dotée à Al-Azhar. Elle contribue à l''essor intellectuel de l''université.', 'L''histoire des grandes universités : De l''âge d''or islamique aux campus du XXIe siècle', '', 'PENDING', '', '2026-03-04 07:23:47.524937+00', NULL, NULL, NULL, ''),
	(1920, 'Construction du Monolithe d''Ezana à Aksoum', 356, false, NULL, 'Le roi Ezana d''Aksoum érige le monolithe, marquant la conversion du royaume au christianisme et commémorant ses victoires militaires. Il symbolise la puissance et la foi du royaume.', 'L''essor et la chute des empires africains : Du royaume d''Aksoum à l''empire Zoulou (100 - 1879)', '', 'PENDING', '', '2026-03-04 07:23:47.524937+00', NULL, NULL, NULL, ''),
	(1921, 'Première mention du port d''Adulis dans le Périple de la mer Érythrée', 40, false, NULL, 'Le Périple de la mer Érythrée décrit Adulis comme un port commercial majeur du royaume d''Aksoum, témoignant de son rôle central dans le commerce maritime avec l''Égypte et l''Inde. Ce document est une source primaire importante sur le commerce aksoumite.', 'L''essor et la chute des empires africains : Du royaume d''Aksoum à l''empire Zoulou (100 - 1879)', '', 'PENDING', '', '2026-03-04 07:23:47.524937+00', NULL, NULL, NULL, ''),
	(1922, 'Début du règne du roi Kaleb d''Aksoum', 520, false, NULL, 'Kaleb monte sur le trône et mène une expédition militaire réussie au Yémen contre le roi juif Dhu Nuwas, renforçant l''influence d''Aksoum en Arabie du Sud. Cette intervention consolide le contrôle aksoumite sur les routes commerciales maritimes.', 'L''essor et la chute des empires africains : Du royaume d''Aksoum à l''empire Zoulou (100 - 1879)', '', 'PENDING', '', '2026-03-04 07:23:47.524937+00', NULL, NULL, NULL, ''),
	(1923, 'Frappe des premières pièces de monnaie en or à Aksoum', 270, false, NULL, 'Le royaume d''Aksoum commence à frapper ses propres pièces d''or, témoignant de sa puissance économique et de son indépendance. Ces pièces facilitent le commerce international et affirment la souveraineté du royaume.', 'L''essor et la chute des empires africains : Du royaume d''Aksoum à l''empire Zoulou (100 - 1879)', '', 'PENDING', '', '2026-03-04 07:23:47.524937+00', NULL, NULL, NULL, ''),
	(1924, 'Destruction de Méroé par le royaume d''Aksoum', 350, false, NULL, 'Le roi Ezana d''Aksoum détruit Méroé, la capitale du royaume de Koush, marquant la fin de ce royaume et l''expansion de l''influence aksoumite dans la région. Cet événement consolide la domination d''Aksoum sur le commerce du Nil.', 'L''essor et la chute des empires africains : Du royaume d''Aksoum à l''empire Zoulou (100 - 1879)', '', 'PENDING', '', '2026-03-04 07:23:47.524937+00', NULL, NULL, NULL, ''),
	(1925, 'Consécration de Frumentius comme premier évêque d''Aksoum', 328, false, NULL, 'Frumentius, un Syrien, est consacré évêque par Athanase d''Alexandrie, marquant un tournant majeur dans la christianisation du royaume d''Aksoum. Cet événement consolide les liens entre Aksoum et le monde chrétien.', 'L''essor et la chute des empires africains : Du royaume d''Aksoum à l''empire Zoulou (100 - 1879)', '', 'PENDING', '', '2026-03-04 07:23:47.524937+00', NULL, NULL, NULL, ''),
	(1926, 'Début du règne d''Ezana, premier roi aksoumite à adopter officiellement le christianisme', 330, false, NULL, 'Ezana, après avoir été éduqué par Frumentius, se convertit et fait du christianisme la religion d''État. Des pièces de monnaie et des inscriptions témoignent de cette conversion.', 'L''essor et la chute des empires africains : Du royaume d''Aksoum à l''empire Zoulou (100 - 1879)', '', 'PENDING', '', '2026-03-04 07:23:47.524937+00', NULL, NULL, NULL, ''),
	(1927, 'Construction de l''église de Dongur Addi Kilte à Aksoum', 350, false, NULL, 'L''église de Dongur Addi Kilte est construite sous le règne d''Ezana, symbolisant l''essor de l''architecture chrétienne à Aksoum. Elle témoigne de l''influence grandissante du christianisme dans le royaume.', 'L''essor et la chute des empires africains : Du royaume d''Aksoum à l''empire Zoulou (100 - 1879)', '', 'PENDING', '', '2026-03-04 07:23:47.524937+00', NULL, NULL, NULL, ''),
	(1928, 'Traduction de la Bible en guèze, langue officielle d''Aksoum', 500, false, NULL, 'La Bible est traduite en guèze, la langue officielle du royaume d''Aksoum, permettant une plus large diffusion du christianisme parmi la population. Cette traduction contribue à l''enracinement de la foi chrétienne.', 'L''essor et la chute des empires africains : Du royaume d''Aksoum à l''empire Zoulou (100 - 1879)', '', 'PENDING', '', '2026-03-04 07:23:47.524937+00', NULL, NULL, NULL, ''),
	(1929, 'Destruction du port d''Adulis par des musulmans', 702, false, NULL, 'Le port d''Adulis, plaque tournante du commerce maritime d''Aksoum, est détruit par des raids musulmans, marquant le début du déclin économique du royaume. Cet événement perturbe les routes commerciales et affaiblit la puissance d''Aksoum.', 'L''essor et la chute des empires africains : Du royaume d''Aksoum à l''empire Zoulou (100 - 1879)', '', 'PENDING', '', '2026-03-04 07:23:47.524937+00', NULL, NULL, NULL, ''),
	(1930, 'Première mention du royaume de Shewa', 896, false, NULL, 'Le royaume de Shewa, situé au sud d''Aksoum, est mentionné pour la première fois dans des sources historiques. Cela témoigne de l''émergence de nouvelles entités politiques dans la région, profitant du déclin d''Aksoum.', 'L''essor et la chute des empires africains : Du royaume d''Aksoum à l''empire Zoulou (100 - 1879)', '', 'PENDING', '', '2026-03-04 07:23:47.524937+00', NULL, NULL, NULL, ''),
	(1931, 'Transfert du siège épiscopal d''Aksoum à Debre Hayq', 920, false, NULL, 'Le siège épiscopal de l''Église éthiopienne orthodoxe est transféré d''Aksoum à Debre Hayq. Ce transfert symbolise le déclin de l''influence d''Aksoum et le déplacement du centre religieux vers le sud.', 'L''essor et la chute des empires africains : Du royaume d''Aksoum à l''empire Zoulou (100 - 1879)', '', 'PENDING', '', '2026-03-04 07:23:47.524937+00', NULL, NULL, NULL, ''),
	(1932, 'Fondation de la dynastie des Banu Najah à Zabid (Yémen)', 819, false, NULL, 'La dynastie des Banu Najah est fondée à Zabid, au Yémen. Cette dynastie prend le contrôle de la route commerciale de la mer Rouge, affectant le commerce d''Aksoum.', 'L''essor et la chute des empires africains : Du royaume d''Aksoum à l''empire Zoulou (100 - 1879)', '', 'PENDING', '', '2026-03-04 07:23:47.524937+00', NULL, NULL, NULL, ''),
	(1933, 'Shaka devient chef du clan zoulou après l''assassinat de son demi-frère Sigujana', 1816, false, NULL, 'Shaka prend le contrôle du clan zoulou, marquant le début de son règne et de ses réformes militaires. Cet événement consolide son pouvoir et lance l''expansion du royaume.', 'L''essor et la chute des empires africains : Du royaume d''Aksoum à l''empire Zoulou (100 - 1879)', '', 'PENDING', '', '2026-03-04 07:23:47.524937+00', NULL, NULL, NULL, ''),
	(1934, 'Assassinat de Shaka par ses demi-frères Dingane et Mhlangana', 1828, false, NULL, 'Shaka est assassiné par ses demi-frères, mettant fin à son règne. Cet événement marque une période de transition et de lutte pour le pouvoir au sein du royaume zoulou.', 'L''essor et la chute des empires africains : Du royaume d''Aksoum à l''empire Zoulou (100 - 1879)', '', 'PENDING', '', '2026-03-04 07:23:47.524937+00', NULL, NULL, NULL, ''),
	(1935, 'Exil du roi Cetshwayo à Londres', 1879, false, NULL, 'Le roi Cetshwayo est exilé à Londres après sa capture. Cet événement marque la fin de son règne et le début d''une nouvelle ère pour le peuple zoulou.', 'L''essor et la chute des empires africains : Du royaume d''Aksoum à l''empire Zoulou (100 - 1879)', '', 'PENDING', '', '2026-03-04 07:23:47.524937+00', NULL, NULL, NULL, ''),
	(1936, 'Inauguration du Canal Sui du Grand Canal de Chine', 609, false, NULL, 'L''empereur Yang Guang des Sui inaugure le Canal Sui, une section majeure du Grand Canal reliant Luoyang et Hangzhou. Cet événement marque une étape cruciale dans l''intégration économique du nord et du sud de la Chine.', 'L''histoire des grands canaux : De la construction du Grand Canal chinois au canal de Panama (486 AEC - 1914)', '', 'PENDING', '', '2026-03-04 07:23:47.524937+00', NULL, NULL, NULL, ''),
	(1937, 'Fondation de la Société Nationale de Protection de la Nature (SNPN) en France', 1905, false, NULL, 'La SNPN, créée le 20 mars 1905, est la plus ancienne association française de protection de la nature. Elle joue un rôle pionnier dans la conservation du patrimoine naturel.', 'L''histoire des mouvements écologistes : De la protection de la nature à la lutte contre le changement climatique (1850 - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.524937+00', NULL, NULL, NULL, ''),
	(1938, 'Publication de ''Printemps silencieux'' de Rachel Carson', 1962, false, NULL, 'Ce livre dénonce les effets néfastes des pesticides sur l''environnement et la santé humaine. Il contribue à lancer le mouvement écologiste moderne.', 'L''histoire des mouvements écologistes : De la protection de la nature à la lutte contre le changement climatique (1850 - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.524937+00', NULL, NULL, NULL, ''),
	(1939, 'Signature de la Convention de Ramsar sur les zones humides', 1971, false, NULL, 'Le 2 février 1971, la Convention de Ramsar est signée en Iran. C''est le premier traité international consacré à la conservation et à l''utilisation rationnelle des zones humides.', 'L''histoire des mouvements écologistes : De la protection de la nature à la lutte contre le changement climatique (1850 - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.524937+00', NULL, NULL, NULL, ''),
	(1940, 'Publication de ''Man and Nature'' de George Perkins Marsh', 1864, false, NULL, 'Ce livre influent met en évidence l''impact destructeur de l''homme sur l''environnement. Il a contribué à sensibiliser le public aux questions écologiques.', 'L''histoire des mouvements écologistes : De la protection de la nature à la lutte contre le changement climatique (1850 - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.524937+00', NULL, NULL, NULL, ''),
	(1941, 'Fondation du Sierra Club par John Muir et d''autres', 1892, false, NULL, 'Le Sierra Club est l''une des premières organisations de conservation environnementale. Il a joué un rôle clé dans la protection des terres sauvages aux États-Unis.', 'L''histoire des mouvements écologistes : De la protection de la nature à la lutte contre le changement climatique (1850 - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.524937+00', NULL, NULL, NULL, ''),
	(1942, 'Ouverture du Studium de Florence', 1321, false, NULL, 'Le Studium de Florence, ou Université de Florence, est officiellement fondé, devenant un centre majeur pour l''étude du droit, des lettres classiques et de la médecine, contribuant à l''essor de l''humanisme.', 'La Renaissance italienne : Des humanistes aux mécènes, de Florence à Rome (1300 - 1600)', '', 'PENDING', '', '2026-03-04 07:23:47.524937+00', NULL, NULL, NULL, ''),
	(1943, 'Leonardo Bruni devient Chancelier de Florence', 1410, false, NULL, 'L''humaniste Leonardo Bruni est nommé Chancelier de Florence. Son érudition et son engagement envers les idéaux républicains contribuent à faire de Florence un centre de l''humanisme civique.', 'La Renaissance italienne : Des humanistes aux mécènes, de Florence à Rome (1300 - 1600)', '', 'PENDING', '', '2026-03-04 07:23:47.524937+00', NULL, NULL, NULL, ''),
	(1944, 'Publication du ''De architectura'' de Vitruve par Giovanni Sulpizio da Veroli à Rome', 1486, false, NULL, 'Première édition imprimée du traité d''architecture de Vitruve, un texte clé de l''Antiquité redécouvert par les humanistes. Il influence profondément l''architecture de la Renaissance.', 'La Renaissance italienne : Des humanistes aux mécènes, de Florence à Rome (1300 - 1600)', '', 'PENDING', '', '2026-03-04 07:23:47.524937+00', NULL, NULL, NULL, ''),
	(1945, 'Antoine le Grand se retire dans le désert', 270, false, NULL, 'Antoine le Grand vend ses biens et se retire dans le désert égyptien, devenant un modèle pour les futurs ermites. Sa vie inspire de nombreux disciples.', 'L''histoire des monastères : Des premiers ermites aux communautés monastiques modernes (300 - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.524937+00', NULL, NULL, NULL, ''),
	(1946, 'Pacôme fonde le premier monastère cénobitique à Tabennèse', 320, false, NULL, 'Pacôme établit une communauté monastique où les moines vivent ensemble sous une règle commune. Cela marque une transition de l''érémitisme vers le cénobitisme.', 'L''histoire des monastères : Des premiers ermites aux communautés monastiques modernes (300 - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.524937+00', NULL, NULL, NULL, ''),
	(1947, 'Athanase d''Alexandrie écrit la ''Vie d''Antoine''', 360, false, NULL, 'Athanase rédige une biographie hagiographique d''Antoine le Grand, popularisant l''idéal érémitique. L''ouvrage contribue à la diffusion de l''érémitisme en Occident.', 'L''histoire des monastères : Des premiers ermites aux communautés monastiques modernes (300 - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.524937+00', NULL, NULL, NULL, ''),
	(1948, 'Jean Cassien fonde l''abbaye Saint-Victor de Marseille', 415, false, NULL, 'Jean Cassien, après avoir vécu parmi les ermites d''Égypte, fonde un monastère en Gaule. Il introduit les pratiques érémitiques orientales en Occident.', 'L''histoire des monastères : Des premiers ermites aux communautés monastiques modernes (300 - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.524937+00', NULL, NULL, NULL, ''),
	(1949, 'Règle de Pachôme : Organisation et discipline de la vie monastique', 325, false, NULL, 'Pachôme rédige la première version de sa Règle, codifiant les principes de vie, de travail et de prière pour les moines. Elle établit une structure communautaire rigoureuse.', 'L''histoire des monastères : Des premiers ermites aux communautés monastiques modernes (300 - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.524937+00', NULL, NULL, NULL, ''),
	(1950, 'Fondation du monastère de Pavou par Pachôme', 336, false, NULL, 'Pachôme fonde le monastère de Pavou, qui devient rapidement un centre important du cénobitisme. Il illustre l''expansion rapide du mouvement monastique en Égypte.', 'L''histoire des monastères : Des premiers ermites aux communautés monastiques modernes (300 - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.524937+00', NULL, NULL, NULL, ''),
	(1951, 'Concile de Vaison : Uniformisation des pratiques liturgiques monastiques', 529, false, NULL, 'Le Concile de Vaison encourage l''adoption de pratiques liturgiques uniformes dans les monastères. Il reflète une volonté d''harmonisation au sein du monachisme occidental.', 'L''histoire des monastères : Des premiers ermites aux communautés monastiques modernes (300 - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.524937+00', NULL, NULL, NULL, ''),
	(1952, 'Concile de Ripon : Wilfrid impose la Règle de Saint-Benoît à l''abbaye de Ripon', 672, false, NULL, 'Wilfrid, évêque d''York, impose la Règle de Saint-Benoît à l''abbaye de Ripon, en Northumbrie. Cet événement marque une étape importante dans l''adoption de la règle bénédictine en Angleterre.', 'L''histoire des monastères : Des premiers ermites aux communautés monastiques modernes (300 - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.524937+00', NULL, NULL, NULL, ''),
	(1953, 'Destruction de l''abbaye du Mont-Cassin par les Lombards', 589, false, NULL, 'L''abbaye du Mont-Cassin, fondée par Benoît de Nursie, est détruite par les Lombards lors de leurs invasions en Italie. La communauté monastique se disperse, mais la Règle de Saint-Benoît survit et continue de se répandre.', 'L''histoire des monastères : Des premiers ermites aux communautés monastiques modernes (300 - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.524937+00', NULL, NULL, NULL, ''),
	(2005, 'Lancement du slogan "Have a Break, Have a Kit Kat"', 1957, false, NULL, 'Rowntree''s lance le slogan publicitaire "Have a Break, Have a Kit Kat", qui contribue à populariser la marque à l''international.', 'L''histoire du chocolat : Des rituels Olmèques aux tablettes industrielles', '', 'PENDING', '', '2026-03-04 07:23:47.53799+00', NULL, NULL, NULL, ''),
	(1954, 'Publication du ''Defensor pacis'' de Marsile de Padoue', 1324, false, NULL, 'Marsile de Padoue, un intellectuel proche des spirituels franciscains, publie le ''Defensor pacis''. Cet ouvrage remet en question le pouvoir temporel de la papauté et prône la souveraineté populaire, suscitant une vive controverse.', 'L''histoire des monastères : Des premiers ermites aux communautés monastiques modernes (300 - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.524937+00', NULL, NULL, NULL, ''),
	(1955, 'Publication de l''encyclique "Pacem in terris" par Jean XXIII', 1963, false, NULL, 'L''encyclique "Pacem in terris" appelle à la paix entre toutes les nations, fondée sur la justice, la liberté et l''amour. Elle marque un tournant dans la doctrine sociale de l''Église catholique.', 'L''histoire des monastères : Des premiers ermites aux communautés monastiques modernes (300 - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.524937+00', NULL, NULL, NULL, ''),
	(1956, 'Introduction du moteur Coventry Climax FPF en Formule 1', 1954, false, NULL, 'Le moteur Coventry Climax FPF, léger et puissant, fait ses débuts et révolutionne la conception des voitures de course. Il permet aux constructeurs britanniques de rivaliser avec les marques italiennes.', 'L''histoire des Grands Prix Automobiles : Des premières courses aux championnats modernes (1894 - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.524937+00', NULL, NULL, NULL, ''),
	(1957, 'Création du British Racing Partnership', 1960, false, NULL, 'Alfred Moss et Ken Gregory fondent le British Racing Partnership (BRP), une écurie privée qui joue un rôle important dans le développement de jeunes pilotes britanniques et de châssis innovants.', 'L''histoire des Grands Prix Automobiles : Des premières courses aux championnats modernes (1894 - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.524937+00', NULL, NULL, NULL, ''),
	(1958, 'Première publication de "Original Jelly Roll Blues" de Jelly Roll Morton', 1915, false, NULL, 'Considéré comme l''une des premières compositions de jazz publiées, ce morceau contribue à diffuser le style de La Nouvelle-Orléans. Il marque une étape importante dans la reconnaissance du jazz comme genre musical.', 'L''histoire du Jazz : Des racines africaines au jazz moderne (1900 - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.524937+00', NULL, NULL, NULL, ''),
	(1959, 'Ouverture du club de jazz Birdland à New York, haut lieu du bebop et du hard bop', 1949, false, NULL, 'Nommé en l''honneur de Charlie "Bird" Parker, le Birdland devient rapidement un club emblématique où se produisent les plus grands noms du jazz moderne. Il contribue à populariser le bebop et le hard bop.', 'L''histoire du Jazz : Des racines africaines au jazz moderne (1900 - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.524937+00', NULL, NULL, NULL, ''),
	(1960, 'Début des sessions d''enregistrement de l''album ''Kind of Blue'' de Miles Davis', 1959, false, NULL, 'Les sessions d''enregistrement de ''Kind of Blue'', un album emblématique du jazz modal, débutent le 2 mars 1959 aux studios Columbia 30th Street à New York. Cet album marque une étape importante dans l''évolution du jazz.', 'L''histoire du Jazz : Des racines africaines au jazz moderne (1900 - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.524937+00', NULL, NULL, NULL, ''),
	(1961, 'Ouverture du club de jazz "Sweet Basil" à Greenwich Village, New York', 1974, false, NULL, 'Inauguration du club de jazz "Sweet Basil", un lieu emblématique de la scène jazz new-yorkaise. Il a accueilli de nombreux artistes de jazz fusion et a contribué à la promotion du genre.', 'L''histoire du Jazz : Des racines africaines au jazz moderne (1900 - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.524937+00', NULL, NULL, NULL, ''),
	(1962, 'Conférence sanitaire internationale de Paris', 1851, false, NULL, 'Première conférence internationale visant à établir des normes sanitaires communes pour lutter contre les épidémies, notamment le choléra. Elle marque une étape importante dans la coopération internationale en matière de santé publique.', 'Les grandes épidémies : De la peste d''Athènes au SIDA (430 AEC - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.524937+00', NULL, NULL, NULL, ''),
	(1963, 'Introduction du bouddhisme zen au Japon par le moine Dōshō', 653, false, NULL, 'Le moine japonais Dōshō, après avoir étudié le bouddhisme en Chine, introduit l''école zen (Chan) au Japon. Cet événement marque le début de l''influence significative du bouddhisme zen sur la culture japonaise.', 'L''histoire des routes de la soie : Des caravanes antiques aux nouvelles routes maritimes (130 AEC - 1453)', '', 'PENDING', '', '2026-03-04 07:23:47.524937+00', NULL, NULL, NULL, ''),
	(1964, 'Massacre de marchands étrangers à Guangzhou', 879, false, NULL, 'Lors de la rébellion de Huang Chao, des milliers de marchands étrangers, principalement musulmans, juifs, chrétiens et persans, sont massacrés à Guangzhou, signalant un déclin du commerce et de la tolérance.', 'L''histoire des routes de la soie : Des caravanes antiques aux nouvelles routes maritimes (130 AEC - 1453)', '', 'PENDING', '', '2026-03-04 07:23:47.524937+00', NULL, NULL, NULL, ''),
	(1965, 'Construction du chantier naval de Vila do Infante au Portugal', 1420, false, NULL, 'Henri le Navigateur fonde un chantier naval et un centre de recherche à Vila do Infante, au Portugal. Ce centre contribue au développement de nouvelles technologies navales et à l''exploration des côtes africaines.', 'L''histoire des routes de la soie : Des caravanes antiques aux nouvelles routes maritimes (130 AEC - 1453)', '', 'PENDING', '', '2026-03-04 07:23:47.53799+00', NULL, NULL, NULL, ''),
	(1966, 'Signature de la Trêve de Calais', 1444, false, NULL, 'L''Angleterre et la France signent la Trêve de Calais, une pause dans la Guerre de Cent Ans. Cette période de paix relative permet aux puissances européennes de se concentrer sur d''autres priorités, y compris l''exploration maritime.', 'L''histoire des routes de la soie : Des caravanes antiques aux nouvelles routes maritimes (130 AEC - 1453)', '', 'PENDING', '', '2026-03-04 07:23:47.53799+00', NULL, NULL, NULL, ''),
	(1967, 'Création du premier BBS francophone, Softinfo', 1983, false, NULL, 'Softinfo, le premier Bulletin Board System (BBS) en langue française, est créé par Francis Benhamou. Il marque le début de l''essor des BBS en France.', 'L''histoire de la cybercriminalité : Des premiers virus informatiques aux attaques de grande ampleur (1970-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.53799+00', NULL, NULL, NULL, ''),
	(1968, 'Publication du code source du virus Elk Cloner dans un magazine', 1982, false, NULL, 'Le code source du virus Elk Cloner, l''un des premiers virus pour Apple II, est publié dans un magazine informatique. Cela contribue à sa diffusion et à l''étude des virus.', 'L''histoire de la cybercriminalité : Des premiers virus informatiques aux attaques de grande ampleur (1970-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.53799+00', NULL, NULL, NULL, ''),
	(1969, 'Publication du rapport McAfee sur l''Opération Aurora', 2010, false, NULL, 'La société de sécurité McAfee publie un rapport détaillé sur l''Opération Aurora, révélant l''ampleur des attaques et les techniques utilisées par les pirates.', 'L''histoire de la cybercriminalité : Des premiers virus informatiques aux attaques de grande ampleur (1970-2010)', '', 'PENDING', '', '2026-03-04 07:23:47.53799+00', NULL, NULL, NULL, ''),
	(1970, 'Concile de Vaishali : Adoption des Dix Points controversés', 383, false, NULL, 'Le Concile de Vaishali se tient, aboutissant à l''adoption des ''Dix Points'' par les moines Vajjiputtaka. Ces points, considérés comme des relâchements de la discipline monastique, mènent à une division au sein du Sangha et contribuent à l''émergence du Mahayana.', 'L''histoire du bouddhisme : De la vie du Bouddha à la diffusion du bouddhisme zen (563 AEC - 1200)', '', 'PENDING', '', '2026-03-04 07:23:47.53799+00', NULL, NULL, NULL, ''),
	(1971, 'Traduction du Sutra du Diamant en chinois par Kumarajiva', 401, false, NULL, 'Kumarajiva, un moine et traducteur bouddhiste, achève sa traduction du Sutra du Diamant (Vajracchedikā Prajñāpāramitā Sūtra) en chinois. Cette traduction devient l''une des versions les plus influentes du sutra.', 'L''histoire du bouddhisme : De la vie du Bouddha à la diffusion du bouddhisme zen (563 AEC - 1200)', '', 'PENDING', '', '2026-03-04 07:23:47.53799+00', NULL, NULL, NULL, ''),
	(1972, 'Publication du ''Sūtra de l''Estrade'' (Liuzu tanjing), texte fondateur du bouddhisme Chan par Huineng', 780, false, NULL, 'Le Sūtra de l''Estrade, attribué à Huineng, sixième patriarche du Chan, est compilé. Il met en avant l''illumination soudaine et l''importance de la pratique directe.', 'L''histoire du bouddhisme : De la vie du Bouddha à la diffusion du bouddhisme zen (563 AEC - 1200)', '', 'PENDING', '', '2026-03-04 07:23:47.53799+00', NULL, NULL, NULL, ''),
	(1973, 'Compilation du ''Recueil de la falaise bleue'' (Biyan Lu), anthologie de koans Chan', 1125, false, NULL, 'Yuanwu Keqin compile le ''Recueil de la falaise bleue'', une collection influente de koans (énigmes paradoxales) utilisés dans la pratique du Chan. Il devient un texte central pour l''étude du Chan.', 'L''histoire du bouddhisme : De la vie du Bouddha à la diffusion du bouddhisme zen (563 AEC - 1200)', '', 'PENDING', '', '2026-03-04 07:23:47.53799+00', NULL, NULL, NULL, ''),
	(1974, 'Attribution du Traité de Marie la Juive à Marie l''Hébraïque (premières descriptions d''appareils alchimiques)', 200, false, NULL, 'Marie l''Hébraïque, alchimiste juive d''Alexandrie, est créditée de la conception d''appareils alchimiques comme le bain-marie et le tribikos. Ses écrits, bien que fragmentaires, influencent le développement des techniques alchimiques.', 'L''histoire de l''alchimie : Des premiers textes hermétiques à la recherche de la pierre philosophale (100 - 1700)', '', 'PENDING', '', '2026-03-04 07:23:47.53799+00', NULL, NULL, NULL, ''),
	(1975, 'Traduction du "Secret des Secrets" (Kitab Sirr al-Asrar) en latin', 1140, false, NULL, 'Le "Secret des Secrets", un texte pseudo-aristotélicien d''origine arabe contenant des éléments d''alchimie et d''hermétisme, est traduit en latin. Cette traduction contribue à la diffusion des idées alchimiques en Europe.', 'L''histoire de l''alchimie : Des premiers textes hermétiques à la recherche de la pierre philosophale (100 - 1700)', '', 'PENDING', '', '2026-03-04 07:23:47.53799+00', NULL, NULL, NULL, ''),
	(1976, 'Traduction du "Secret des Créations" (Kitab Sirr al-Asrar) attribué à Apollonius de Tyane en arabe par Salim Ibn ''Alî', 825, false, NULL, 'Ce texte, bien que pseudo-épigraphique, a exercé une influence considérable sur la pensée alchimique arabe. Il a contribué à la diffusion des concepts hermétiques et à l''intégration de l''alchimie grecque dans le corpus scientifique arabe.', 'L''histoire de l''alchimie : Des premiers textes hermétiques à la recherche de la pierre philosophale (100 - 1700)', '', 'PENDING', '', '2026-03-04 07:23:47.53799+00', NULL, NULL, NULL, ''),
	(1977, 'Publication du ''De mineralibus'' d''Albert le Grand', 1260, false, NULL, 'Albert le Grand publie ''De mineralibus'', un traité de minéralogie et d''alchimie qui décrit les propriétés des minéraux et leur utilisation dans les transformations alchimiques. Il marque une étape importante dans l''étude des substances naturelles.', 'L''histoire de l''alchimie : Des premiers textes hermétiques à la recherche de la pierre philosophale (100 - 1700)', '', 'PENDING', '', '2026-03-04 07:23:47.53799+00', NULL, NULL, NULL, ''),
	(1978, 'Publication du ''De Mineralibus'' d''Albert le Grand, traitant de minéralogie et d''alchimie', 1256, false, NULL, 'Albert le Grand achève son ''De Mineralibus'', un ouvrage important qui compile les connaissances de l''époque sur les minéraux et leur utilisation en alchimie. Il y décrit également des expériences alchimiques.', 'L''histoire de l''alchimie : Des premiers textes hermétiques à la recherche de la pierre philosophale (100 - 1700)', '', 'PENDING', '', '2026-03-04 07:23:47.53799+00', NULL, NULL, NULL, ''),
	(1979, 'Paracelse obtient son doctorat en médecine à l''Université de Ferrare', 1516, false, NULL, 'Ce diplôme marque une étape importante dans sa carrière, lui permettant de pratiquer la médecine et de développer ses théories iatrochimiques. Il commence à voyager et à critiquer la médecine traditionnelle.', 'L''histoire de l''alchimie : Des premiers textes hermétiques à la recherche de la pierre philosophale (100 - 1700)', '', 'PENDING', '', '2026-03-04 07:23:47.53799+00', NULL, NULL, NULL, ''),
	(1980, 'Publication de la Géographie de Ptolémée', 150, false, NULL, 'L''ouvrage compile les connaissances géographiques du monde gréco-romain. Il propose un système de coordonnées et des cartes du monde connu.', 'L''histoire de la cartographie : des premières représentations du monde aux cartes numériques (600 AEC - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.53799+00', NULL, NULL, NULL, ''),
	(1981, 'Traduction en latin de la Géographie de Ptolémée par Jacopo d''Angelo', 1406, false, NULL, 'La traduction latine de l''œuvre de Ptolémée, réalisée par Jacopo d''Angelo, rend le texte accessible à un public européen plus large. Elle influence la cartographie de la Renaissance.', 'L''histoire de la cartographie : des premières représentations du monde aux cartes numériques (600 AEC - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.53799+00', NULL, NULL, NULL, ''),
	(1982, 'Publication de l''édition de la Géographie de Ptolémée annotée par Gérard Mercator', 1578, false, NULL, 'L''édition de la Géographie de Ptolémée annotée par Mercator témoigne de l''importance continue de l''œuvre. Elle intègre les nouvelles découvertes géographiques et les corrige.', 'L''histoire de la cartographie : des premières représentations du monde aux cartes numériques (600 AEC - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.53799+00', NULL, NULL, NULL, ''),
	(1983, 'Copie du mappemonde d''Al-Idrisi conservée à la Bibliothèque Nationale de France', 1456, false, NULL, 'Une copie manuscrite du mappemonde d''Al-Idrisi est réalisée et conservée à la Bibliothèque Nationale de France. Ce document témoigne de l''importance et de la pérennité de l''œuvre d''Al-Idrisi à travers les siècles.', 'L''histoire de la cartographie : des premières représentations du monde aux cartes numériques (600 AEC - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.53799+00', NULL, NULL, NULL, ''),
	(1984, 'Publication de la première édition imprimée du ''Livre de Roger'' d''Al-Idrisi en arabe', 1592, false, NULL, 'La première édition imprimée du ''Livre de Roger'' d''Al-Idrisi est publiée en arabe. Cette publication marque une étape importante dans la diffusion de l''œuvre auprès d''un public plus large dans le monde arabe.', 'L''histoire de la cartographie : des premières représentations du monde aux cartes numériques (600 AEC - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.53799+00', NULL, NULL, NULL, ''),
	(1985, 'Publication d''une édition critique du ''Livre de Roger'' d''Al-Idrisi par Konrad Miller', 1928, false, NULL, 'L''orientaliste allemand Konrad Miller publie une édition critique du ''Livre de Roger'' d''Al-Idrisi, basée sur plusieurs manuscrits. Cette édition constitue une référence pour les chercheurs et contribue à une meilleure compréhension de l''œuvre.', 'L''histoire de la cartographie : des premières représentations du monde aux cartes numériques (600 AEC - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.53799+00', NULL, NULL, NULL, ''),
	(1986, 'Utilisation de la projection de Mercator pour la première carte géologique de l''Angleterre et du Pays de Galles', 1815, false, NULL, 'William Smith publie sa carte géologique de l''Angleterre et du Pays de Galles, utilisant la projection de Mercator pour représenter les formations géologiques. C''est une application novatrice de la projection en dehors de la navigation.', 'L''histoire de la cartographie : des premières représentations du monde aux cartes numériques (600 AEC - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.53799+00', NULL, NULL, NULL, ''),
	(1987, 'Publication de ''Voyage aux régions équinoxiales du Nouveau Continent'' par Alexander von Humboldt', 1807, false, NULL, 'Humboldt commence la publication de son œuvre majeure, relatant son expédition en Amérique du Sud. Cette publication en plusieurs volumes aura une influence considérable sur la science et l''exploration.', 'L''histoire des grandes explorations naturalistes : De Humboldt à Cousteau (1799-1997)', '', 'PENDING', '', '2026-03-04 07:23:47.53799+00', NULL, NULL, NULL, ''),
	(1988, 'Présentation de la carte isobare par Alexander von Humboldt à l''Académie des sciences de Berlin', 1817, false, NULL, 'Humboldt introduit la notion de lignes isobares pour représenter les variations de pression atmosphérique sur une carte. C''est une innovation majeure en météorologie et en cartographie.', 'L''histoire des grandes explorations naturalistes : De Humboldt à Cousteau (1799-1997)', '', 'PENDING', '', '2026-03-04 07:23:47.53799+00', NULL, NULL, NULL, ''),
	(1989, 'Publication de ''La Filiation de l''homme et la sélection liée au sexe'' par Charles Darwin', 1871, false, NULL, 'Darwin publie ''La Filiation de l''homme et la sélection liée au sexe'', appliquant sa théorie de l''évolution à l''espèce humaine. Il y explore les origines animales de l''homme et le rôle de la sélection sexuelle.', 'L''histoire des grandes explorations naturalistes : De Humboldt à Cousteau (1799-1997)', '', 'PENDING', '', '2026-03-04 07:23:47.53799+00', NULL, NULL, NULL, ''),
	(1990, 'Publication du rapport scientifique de l''expédition du Challenger', 1885, false, NULL, 'Le premier volume du rapport scientifique officiel de l''expédition du Challenger est publié. Ce rapport monumental, composé de 50 volumes, a présenté les résultats de l''expédition et a eu un impact profond sur la science océanographique.', 'L''histoire des grandes explorations naturalistes : De Humboldt à Cousteau (1799-1997)', '', 'PENDING', '', '2026-03-04 07:23:47.53799+00', NULL, NULL, NULL, ''),
	(1991, 'Signature de l''acte constitutif de l''Union Internationale pour la Protection de la Nature (UIPN) à Fontainebleau', 1948, false, NULL, 'L''UIPN, future UICN, est fondée lors d''une conférence internationale. Elle vise à promouvoir la conservation de la nature et des ressources naturelles.', 'L''histoire des grandes explorations naturalistes : De Humboldt à Cousteau (1799-1997)', '', 'PENDING', '', '2026-03-04 07:23:47.53799+00', NULL, NULL, NULL, ''),
	(1992, 'Publication du rapport "Global Biodiversity Assessment" par le PNUE, avec la contribution de l''UICN', 1995, false, NULL, 'Cette évaluation exhaustive de la biodiversité mondiale met en évidence les menaces pesant sur les espèces et les écosystèmes. Elle sert de base aux politiques de conservation.', 'L''histoire des grandes explorations naturalistes : De Humboldt à Cousteau (1799-1997)', '', 'PENDING', '', '2026-03-04 07:23:47.53799+00', NULL, NULL, NULL, ''),
	(1993, 'Publication de la ''Description de l''Égypte''', 1809, false, NULL, 'Début de la publication de la ''Description de l''Égypte'', une encyclopédie monumentale compilant les observations scientifiques et artistiques réalisées lors de l''expédition de Napoléon en Égypte. Elle contient de nombreuses reproductions de textes hiéroglyphiques.', 'L''histoire des grandes découvertes archéologiques : De la pierre de Rosette à la tombe de Toutânkhamon (1799 - 1922)', '', 'PENDING', '', '2026-03-04 07:23:47.53799+00', NULL, NULL, NULL, ''),
	(1994, 'Première publication des ''Antiquités d''Herculanum''', 1757, false, NULL, 'Le premier volume des ''Antiquités d''Herculanum'' (Le Antichità di Ercolano Esposte) est publié à Naples. Cet ouvrage monumental, commandé par Charles de Bourbon, présente les découvertes archéologiques d''Herculanum à travers des gravures détaillées, contribuant à la diffusion du style néoclassique.', 'L''histoire des grandes découvertes archéologiques : De la pierre de Rosette à la tombe de Toutânkhamon (1799 - 1922)', '', 'PENDING', '', '2026-03-04 07:23:47.53799+00', NULL, NULL, NULL, ''),
	(1995, 'Giuseppe Fiorelli devient directeur des fouilles de Pompéi', 1860, false, NULL, 'Giuseppe Fiorelli est nommé directeur des fouilles de Pompéi. Il introduit des méthodes de fouilles plus rigoureuses et scientifiques, notamment la technique des moulages en plâtre pour préserver les corps des victimes de l''éruption.', 'L''histoire des grandes découvertes archéologiques : De la pierre de Rosette à la tombe de Toutânkhamon (1799 - 1922)', '', 'PENDING', '', '2026-03-04 07:23:47.53799+00', NULL, NULL, NULL, ''),
	(1996, 'Mort d''Heinrich Schliemann à Naples', 1890, false, NULL, 'Heinrich Schliemann décède des suites d''une opération à l''oreille à Naples, en Italie. Son travail controversé mais influent a transformé la perception de l''archéologie et de l''histoire antique.', 'L''histoire des grandes découvertes archéologiques : De la pierre de Rosette à la tombe de Toutânkhamon (1799 - 1922)', '', 'PENDING', '', '2026-03-04 07:23:47.53799+00', NULL, NULL, NULL, ''),
	(1997, 'Autorisation de fouilles dans la Vallée des Rois accordée à Howard Carter par Lord Carnarvon', 1914, false, NULL, 'Lord Carnarvon finance et autorise Howard Carter à mener des fouilles archéologiques dans la Vallée des Rois, en Égypte. Cette collaboration mènera à la découverte du tombeau de Toutânkhamon.', 'L''histoire des grandes découvertes archéologiques : De la pierre de Rosette à la tombe de Toutânkhamon (1799 - 1922)', '', 'PENDING', '', '2026-03-04 07:23:47.53799+00', NULL, NULL, NULL, ''),
	(1998, 'Construction du premier entrepôt officiel de thé à Yangzhou', 725, false, NULL, 'La dynastie Tang établit un entrepôt officiel à Yangzhou pour gérer et distribuer le thé. Cela facilite le commerce et la distribution du thé à travers l''empire.', 'L''histoire du thé : De la légende de Shen Nong à l''engouement mondial (2737 AEC - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.53799+00', NULL, NULL, NULL, ''),
	(1999, 'Introduction des "thés compressés" (brick tea) pour faciliter le transport et le stockage', 800, false, NULL, 'Les producteurs de thé commencent à compresser les feuilles de thé en briques pour faciliter leur transport et leur stockage. Cette innovation contribue à l''expansion du commerce du thé vers des régions plus éloignées.', 'L''histoire du thé : De la légende de Shen Nong à l''engouement mondial (2737 AEC - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.53799+00', NULL, NULL, NULL, ''),
	(2000, 'Murata Jukō formalise les principes du wabi-cha', 1490, false, NULL, 'Murata Jukō, considéré comme le père de la cérémonie du thé japonaise, formalise les principes du wabi-cha. Il met l''accent sur la simplicité, la rusticité et l''appréciation de l''imperfection.', 'L''histoire du thé : De la légende de Shen Nong à l''engouement mondial (2737 AEC - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.53799+00', NULL, NULL, NULL, ''),
	(2001, 'Début du règne de Parameswara comme premier sultan de Malacca', 1414, false, NULL, 'Parameswara, initialement un prince de Palembang, se convertit à l''islam et prend le titre de sultan Muhammad Shah. Cet événement marque un tournant dans l''histoire de Malacca et de son influence régionale.', 'L''histoire des grandes explorations maritimes chinoises : Des expéditions de Zheng He au déclin de la marine impériale (1405-1525)', '', 'PENDING', '', '2026-03-04 07:23:47.53799+00', NULL, NULL, NULL, ''),
	(2002, 'Début du règne de Dragut à Tripoli', 1551, false, NULL, 'Dragut, amiral ottoman, s''empare de Tripoli et en devient le bey. Il transforme la ville en un important centre de la course en Méditerranée et renforce l''influence ottomane en Afrique du Nord.', 'L''histoire des pirates de Méditerranée : Des raids barbaresques à la fin de la piraterie', '', 'PENDING', '', '2026-03-04 07:23:47.53799+00', NULL, NULL, NULL, ''),
	(2003, 'Brevet du procédé de fabrication du chocolat en poudre par Coenraad Johannes van Houten', 1828, false, NULL, 'Coenraad Johannes van Houten brevète un procédé permettant de séparer le beurre de cacao de la pâte de cacao. Cela rend le chocolat en poudre plus facile à dissoudre et à utiliser.', 'L''histoire du chocolat : Des rituels Olmèques aux tablettes industrielles', '', 'PENDING', '', '2026-03-04 07:23:47.53799+00', NULL, NULL, NULL, ''),
	(2004, 'Commercialisation du Milky Way par la Mars Candy Company', 1923, false, NULL, 'Le Milky Way, une barre chocolatée fourrée au nougat et au caramel, devient un succès immédiat et contribue à populariser le chocolat au lait auprès d''un large public. C''est l''une des premières barres chocolatées produites en masse.', 'L''histoire du chocolat : Des rituels Olmèques aux tablettes industrielles', '', 'PENDING', '', '2026-03-04 07:23:47.53799+00', NULL, NULL, NULL, ''),
	(2006, 'Création du label Max Havelaar pour le commerce équitable du cacao aux Pays-Bas', 1988, false, NULL, 'Le label Max Havelaar est créé aux Pays-Bas pour garantir un prix équitable aux producteurs de cacao. Il marque un tournant dans le commerce du chocolat.', 'L''histoire du chocolat : Des rituels Olmèques aux tablettes industrielles', '', 'PENDING', '', '2026-03-04 07:23:47.53799+00', NULL, NULL, NULL, ''),
	(2007, 'Publication du protocole Harkin-Engel (Cacao)', 2001, false, NULL, 'Signature du protocole Harkin-Engel, un accord international visant à éliminer le travail des enfants dans la production de cacao en Afrique de l''Ouest.', 'L''histoire du chocolat : Des rituels Olmèques aux tablettes industrielles', '', 'PENDING', '', '2026-03-04 07:23:47.53799+00', NULL, NULL, NULL, ''),
	(2008, 'Mars devient la première grande entreprise chocolatière à s''engager à utiliser 100% de cacao certifié durable', 2009, false, NULL, 'Mars Inc. annonce son engagement à utiliser uniquement du cacao certifié durable d''ici 2020, une initiative majeure pour l''industrie.', 'L''histoire du chocolat : Des rituels Olmèques aux tablettes industrielles', '', 'PENDING', '', '2026-03-04 07:23:47.53799+00', NULL, NULL, NULL, ''),
	(2009, 'Barry Callebaut lance le programme ''Cocoa Horizons'' pour améliorer la durabilité de la culture du cacao', 2012, false, NULL, 'Barry Callebaut lance le programme ''Cocoa Horizons'', visant à améliorer les conditions de vie des cultivateurs de cacao et à promouvoir des pratiques agricoles durables.', 'L''histoire du chocolat : Des rituels Olmèques aux tablettes industrielles', '', 'PENDING', '', '2026-03-04 07:23:47.53799+00', NULL, NULL, NULL, ''),
	(2010, 'Installation de la dynastie de Palenque par K''uk'' Bahlam I', 431, false, NULL, 'K''uk'' Bahlam I fonde la dynastie de Palenque, marquant le début d''une période de prospérité et de développement architectural pour la cité-état maya. Il est considéré comme le premier roi de Palenque.', 'L''essor et la chute des cités-états mayas : De la période préclassique à l''effondrement (200 AEC - 900)', '', 'PENDING', '', '2026-03-04 07:23:47.53799+00', NULL, NULL, NULL, ''),
	(2011, 'Consécration de la Stèle 9 à Toniná, témoignant de l''influence de la cité', 514, false, NULL, 'La Stèle 9 de Toniná est érigée, illustrant la puissance militaire et politique de la cité-état maya à cette époque. Elle représente un prisonnier capturé lors d''une bataille.', 'L''essor et la chute des cités-états mayas : De la période préclassique à l''effondrement (200 AEC - 900)', '', 'PENDING', '', '2026-03-04 07:23:47.53799+00', NULL, NULL, NULL, ''),
	(2012, 'Inauguration du Complexe Mundo Perdido à Tikal', 250, false, NULL, 'Achèvement et inauguration du complexe architectural et cérémoniel Mundo Perdido à Tikal, marquant une étape importante dans le développement urbain et religieux de la cité maya. Ce complexe témoigne de la puissance et de l''influence croissantes de Tikal au début de la période classique.', 'L''essor et la chute des cités-états mayas : De la période préclassique à l''effondrement (200 AEC - 900)', '', 'PENDING', '', '2026-03-04 07:23:47.53799+00', NULL, NULL, NULL, ''),
	(2013, 'Installation de B''alam Ajaw comme roi de Calakmul', 330, false, NULL, 'B''alam Ajaw accède au trône de Calakmul, marquant le début d''une période d''expansion et de consolidation du pouvoir pour cette cité. Son règne est caractérisé par des alliances stratégiques et des campagnes militaires visant à rivaliser avec Tikal pour la domination de la région.', 'L''essor et la chute des cités-états mayas : De la période préclassique à l''effondrement (200 AEC - 900)', '', 'PENDING', '', '2026-03-04 07:23:47.53799+00', NULL, NULL, NULL, ''),
	(2014, 'Victoire de Tikal sur Uaxactun', 410, false, NULL, 'Tikal remporte une victoire militaire décisive sur Uaxactun, une cité rivale importante. Cette victoire consolide la position dominante de Tikal dans la région et lui permet d''étendre son influence politique et économique.', 'L''essor et la chute des cités-états mayas : De la période préclassique à l''effondrement (200 AEC - 900)', '', 'PENDING', '', '2026-03-04 07:23:47.53799+00', NULL, NULL, NULL, ''),
	(2015, 'Installation du Stèle 31 à Copán', 652, false, NULL, 'La Stèle 31, un monument sculpté représentant le roi K''ahk'' Uti'' Chan de Copán, est érigée. Elle témoigne de l''influence artistique et politique de Teotihuacan sur la culture maya.', 'L''essor et la chute des cités-états mayas : De la période préclassique à l''effondrement (200 AEC - 900)', '', 'PENDING', '', '2026-03-04 07:23:47.549884+00', NULL, NULL, NULL, ''),
	(2016, 'Début du règne de K''inich Janaab'' Pakal II à Palenque', 702, false, NULL, 'K''inich Janaab'' Pakal II accède au trône de Palenque, marquant une période de prospérité et d''expansion architecturale. Son règne est associé à la construction du Temple des Inscriptions.', 'L''essor et la chute des cités-états mayas : De la période préclassique à l''effondrement (200 AEC - 900)', '', 'PENDING', '', '2026-03-04 07:23:47.549884+00', NULL, NULL, NULL, ''),
	(2017, 'Construction de la structure Rosalila à Copán', 600, false, NULL, 'Début de la construction de la structure Rosalila à Copán, un temple magnifiquement décoré. Il témoigne de l''apogée de l''art et de l''architecture maya dans cette cité.', 'L''essor et la chute des cités-états mayas : De la période préclassique à l''effondrement (200 AEC - 900)', '', 'PENDING', '', '2026-03-04 07:23:47.549884+00', NULL, NULL, NULL, ''),
	(2018, 'Achèvement du jeu de balle de Yaxchilán', 731, false, NULL, 'Le jeu de balle de Yaxchilán, une structure rituelle importante, est achevé. Il reflète l''importance du jeu de balle dans la culture maya et son rôle dans les cérémonies religieuses et politiques.', 'L''essor et la chute des cités-états mayas : De la période préclassique à l''effondrement (200 AEC - 900)', '', 'PENDING', '', '2026-03-04 07:23:47.549884+00', NULL, NULL, NULL, ''),
	(2019, 'Destruction de la ville de Hamadan par les armées abbassides', 810, false, NULL, 'La ville de Hamadan (actuel Iran) est détruite par les armées du califat abbasside lors de conflits internes. Cet événement marque une période d''instabilité et de répression dans la région.', 'L''essor et la chute des cités-états mayas : De la période préclassique à l''effondrement (200 AEC - 900)', '', 'PENDING', '', '2026-03-04 07:23:47.549884+00', NULL, NULL, NULL, ''),
	(2020, 'Dédicace du Stèle 11 à Yaxchilán par Itzamnáj B''alam IV', 768, false, NULL, 'Itzamnáj B''alam IV de Yaxchilán dédie la Stèle 11, un monument important qui témoigne de son pouvoir et de ses victoires militaires. Cette stèle fournit des informations précieuses sur les conflits et les alliances de l''époque.', 'L''essor et la chute des cités-états mayas : De la période préclassique à l''effondrement (200 AEC - 900)', '', 'PENDING', '', '2026-03-04 07:23:47.549884+00', NULL, NULL, NULL, ''),
	(2021, 'Début du règne de K''inich Yo''nal Ahk II à Piedras Negras', 758, false, NULL, 'K''inich Yo''nal Ahk II accède au pouvoir à Piedras Negras, une cité-état maya influente. Son règne est marqué par des constructions importantes et des guerres avec ses voisins, contribuant à l''instabilité régionale.', 'L''essor et la chute des cités-états mayas : De la période préclassique à l''effondrement (200 AEC - 900)', '', 'PENDING', '', '2026-03-04 07:23:47.549884+00', NULL, NULL, NULL, ''),
	(2022, 'Consécration du Terrain de jeu de balle de Seibal', 804, false, NULL, 'Seibal consacre son terrain de jeu de balle, un événement qui souligne l''importance rituelle et politique du jeu dans la société maya. Ce terrain témoigne de la vitalité de la cité à cette époque, malgré les signes de déclin général.', 'L''essor et la chute des cités-états mayas : De la période préclassique à l''effondrement (200 AEC - 900)', '', 'PENDING', '', '2026-03-04 07:23:47.549884+00', NULL, NULL, NULL, ''),
	(2023, 'Datation de la flûte d''Isturitz, l''une des plus anciennes flûtes paléolithiques avérées', 35000, false, NULL, 'Une flûte en os d''oiseau est découverte dans la grotte d''Isturitz, dans les Pyrénées-Atlantiques. Datée d''environ 35 000 ans, elle témoigne d''une culture musicale développée au Paléolithique supérieur.', 'L''histoire des instruments de musique : Des flûtes paléolithiques aux synthétiseurs numériques', '', 'PENDING', '', '2026-03-04 07:23:47.549884+00', NULL, NULL, NULL, ''),
	(2024, 'Découverte des flûtes de Geissenklösterle, parmi les plus anciens instruments de musique confirmés', 42000, false, NULL, 'Des fragments de flûtes en os et en ivoire sont découverts dans la grotte de Geissenklösterle, en Allemagne. Datés d''environ 42 000 ans, ils sont attribués à l''Homo sapiens.', 'L''histoire des instruments de musique : Des flûtes paléolithiques aux synthétiseurs numériques', '', 'PENDING', '', '2026-03-04 07:23:47.549884+00', NULL, NULL, NULL, ''),
	(2025, 'Publication de ''Musica disciplina'' de Boèce, traité majeur sur la théorie musicale médiévale', 500, false, NULL, 'Boèce, philosophe romain, rédige ''Musica disciplina'', un ouvrage qui codifie la musique selon les principes mathématiques et philosophiques grecs. Il influencera la pensée musicale pendant des siècles.', 'L''histoire des instruments de musique : Des flûtes paléolithiques aux synthétiseurs numériques', '', 'PENDING', '', '2026-03-04 07:23:47.549884+00', NULL, NULL, NULL, ''),
	(2026, 'Première utilisation documentée de la flûte traversière en Europe (illustration dans le ''Hortus deliciarum'')', 1180, false, NULL, 'La flûte traversière fait son apparition dans l''iconographie européenne, illustrée dans le ''Hortus deliciarum'' d''Herrade de Landsberg. C''est une des premières preuves visuelles de son existence.', 'L''histoire des instruments de musique : Des flûtes paléolithiques aux synthétiseurs numériques', '', 'PENDING', '', '2026-03-04 07:23:47.549884+00', NULL, NULL, NULL, ''),
	(2027, 'Première mention du oud dans un texte arabe', 950, false, NULL, 'Le oud, ancêtre du luth, est mentionné dans le Kitab al-aghani (Livre des Chansons), une encyclopédie de la musique et de la poésie arabe. Cette mention témoigne de son importance croissante dans la musique du monde islamique médiéval.', 'L''histoire des instruments de musique : Des flûtes paléolithiques aux synthétiseurs numériques', '', 'PENDING', '', '2026-03-04 07:23:47.549884+00', NULL, NULL, NULL, ''),
	(2028, 'Publication du traité ''De Musica'' de Boèce', 1000, false, NULL, 'Ce traité, bien que datant du VIe siècle, est redécouvert et largement diffusé vers l''an 1000. Il influence profondément la théorie musicale médiévale et la conception des instruments, y compris le luth.', 'L''histoire des instruments de musique : Des flûtes paléolithiques aux synthétiseurs numériques', '', 'PENDING', '', '2026-03-04 07:23:47.549884+00', NULL, NULL, NULL, ''),
	(2029, 'Bartolomeo Cristofori présente le premier piano-forte à la cour des Médicis', 1700, false, NULL, 'Bartolomeo Cristofori, facteur d''instruments de musique italien, invente le piano-forte. Il présente son invention à la cour des Médicis à Florence, marquant une étape importante dans l''évolution des instruments à clavier.', 'L''histoire des instruments de musique : Des flûtes paléolithiques aux synthétiseurs numériques', '', 'PENDING', '', '2026-03-04 07:23:47.549884+00', NULL, NULL, NULL, ''),
	(2030, 'Gottfried Silbermann commence à construire des pianos-fortes inspirés de Cristofori', 1730, false, NULL, 'Gottfried Silbermann, facteur d''orgues et de pianos allemand, commence à construire ses propres pianos-fortes. Il s''inspire des modèles de Cristofori, mais apporte des modifications et améliorations.', 'L''histoire des instruments de musique : Des flûtes paléolithiques aux synthétiseurs numériques', '', 'PENDING', '', '2026-03-04 07:23:47.549884+00', NULL, NULL, NULL, ''),
	(2031, 'Johannes Zumpe, facteur de pianos, s''installe à Londres et popularise le piano carré', 1760, false, NULL, 'Johannes Zumpe, un facteur de pianos allemand, s''installe à Londres et commence à produire des pianos carrés. Ces pianos plus petits et moins chers contribuent à populariser l''instrument auprès d''un public plus large.', 'L''histoire des instruments de musique : Des flûtes paléolithiques aux synthétiseurs numériques', '', 'PENDING', '', '2026-03-04 07:23:47.549884+00', NULL, NULL, NULL, ''),
	(2032, 'Ouverture du magasin d''instruments de musique de C.G. Conn à Elkhart, Indiana', 1876, false, NULL, 'Charles Gerard Conn, ancien officier de l''armée américaine, ouvre un magasin de musique à Elkhart, Indiana. L''entreprise C.G. Conn devient rapidement l''un des plus grands fabricants d''instruments à vent au monde.', 'L''histoire des instruments de musique : Des flûtes paléolithiques aux synthétiseurs numériques', '', 'PENDING', '', '2026-03-04 07:23:47.549884+00', NULL, NULL, NULL, ''),
	(2033, 'Sortie de l''album ''Switched-On Bach'' de Wendy Carlos', 1968, false, NULL, 'Wendy Carlos publie ''Switched-On Bach'', un album de musique de Bach interprétée au synthétiseur Moog. Il contribue à la reconnaissance du synthétiseur comme instrument sérieux.', 'L''histoire des instruments de musique : Des flûtes paléolithiques aux synthétiseurs numériques', '', 'PENDING', '', '2026-03-04 07:23:47.549884+00', NULL, NULL, NULL, ''),
	(2034, 'Sortie du logiciel Ableton Live 1.0', 2001, false, NULL, 'Ableton Live 1.0 est lancé, un logiciel de production musicale qui révolutionne la façon dont la musique électronique est créée et jouée en direct. Il introduit une interface non-linéaire.', 'L''histoire des instruments de musique : Des flûtes paléolithiques aux synthétiseurs numériques', '', 'PENDING', '', '2026-03-04 07:23:47.549884+00', NULL, NULL, NULL, ''),
	(2035, 'Introduction de l''ambre gris en parfumerie par les Arabes', 900, false, NULL, 'Les parfumeurs arabes commencent à utiliser l''ambre gris, une substance rare et précieuse provenant des cachalots, comme fixateur et ingrédient de base dans leurs compositions parfumées. Cela enrichit considérablement la palette olfactive disponible.', 'L''histoire de la parfumerie : Des onguents sacrés aux fragrances de stars (3000 AEC - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.549884+00', NULL, NULL, NULL, ''),
	(2036, 'Publication de ''L''Art du Parfumeur'' de Jean-Louis Fargeon', 1772, false, NULL, 'Ce traité détaille les techniques de fabrication des parfums, des cosmétiques et des produits de toilette. Il offre un aperçu précieux des pratiques de la parfumerie au XVIIIe siècle et contribue à la diffusion des connaissances.', 'L''histoire de la parfumerie : Des onguents sacrés aux fragrances de stars (3000 AEC - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.549884+00', NULL, NULL, NULL, ''),
	(2037, 'Première production industrielle d''alizarine synthétique par BASF', 1869, false, NULL, 'Le groupe allemand BASF (Badische Anilin und Soda Fabrik) lance la production industrielle d''alizarine synthétique, un colorant rouge auparavant extrait de la garance. C''est une étape clé dans le développement de l''industrie des colorants synthétiques.', 'L''histoire de la parfumerie : Des onguents sacrés aux fragrances de stars (3000 AEC - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.549884+00', NULL, NULL, NULL, ''),
	(2038, 'Sortie de Angel par Thierry Mugler', 1992, false, NULL, 'Thierry Mugler lance Angel, un parfum gourmand novateur avec des notes de patchouli, chocolat et caramel. Il inaugure une nouvelle ère dans la parfumerie.', 'L''histoire de la parfumerie : Des onguents sacrés aux fragrances de stars (3000 AEC - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.549884+00', NULL, NULL, NULL, ''),
	(2039, 'Publication du livre "De re vestiaria" de Filippo Pigafetta', 1590, false, NULL, 'Ce livre illustre et décrit les costumes de différentes régions du monde, offrant un aperçu précieux de la diversité vestimentaire de l''époque.', 'L''histoire du costume : Des premiers vêtements à la haute couture (3000 AEC - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.549884+00', NULL, NULL, NULL, ''),
	(2040, 'Publication du premier recueil de modèles de dentelle de Federico Vinciolo ''Les singuliers et nouveaux patrons''', 1587, false, NULL, 'Ce recueil marque une étape importante dans la diffusion des motifs de dentelle et influence durablement la mode européenne. Il contribue à l''essor de la dentelle comme élément de luxe et de distinction sociale.', 'L''histoire du costume : Des premiers vêtements à la haute couture (3000 AEC - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.549884+00', NULL, NULL, NULL, ''),
	(2041, 'Présentation de la première poupée de mode (Pandore) à la cour de France', 1663, false, NULL, 'Ces poupées, habillées avec les dernières créations de mode parisienne, sont envoyées aux cours européennes pour diffuser les tendances. Elles jouent un rôle crucial dans l''établissement de Paris comme capitale de la mode.', 'L''histoire du costume : Des premiers vêtements à la haute couture (3000 AEC - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.549884+00', NULL, NULL, NULL, ''),
	(2042, 'Ordonnance royale officialisant la création des manufactures de dentelles d''Alençon et d''Argentan', 1665, false, NULL, 'Cette initiative de Colbert vise à concurrencer les dentelles vénitiennes et flamandes, stimulant ainsi l''industrie textile française. Elle marque une volonté politique de promouvoir le luxe et le savoir-faire français.', 'L''histoire du costume : Des premiers vêtements à la haute couture (3000 AEC - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.549884+00', NULL, NULL, NULL, ''),
	(2043, 'Invention du métier à bas par William Lee', 1589, false, NULL, 'Cette invention mécanise la production de bas, auparavant tricotés à la main. Bien que initialement refusée par la reine Elizabeth I, elle révolutionne l''industrie textile et rend les bas plus accessibles.', 'L''histoire du costume : Des premiers vêtements à la haute couture (3000 AEC - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.549884+00', NULL, NULL, NULL, ''),
	(2044, 'Inauguration du Grand K''uk''ulkan (Chichén Itzá)', 830, false, NULL, 'Achèvement et inauguration de la pyramide de K''uk''ulkan à Chichén Itzá, marquant un sommet de l''architecture maya et de l''influence itzá.', 'Les Empires Précolombiens : Des Olmèques à l''Empire Inca (1200 AEC - 1533)', '', 'PENDING', '', '2026-03-04 07:23:47.549884+00', NULL, NULL, NULL, ''),
	(2045, 'Début du règne de Chan Imix K''awiil (Copán)', 628, false, NULL, 'Accession au pouvoir de Chan Imix K''awiil, un roi important de Copán, marquant une période de développement artistique et architectural dans la cité.', 'Les Empires Précolombiens : Des Olmèques à l''Empire Inca (1200 AEC - 1533)', '', 'PENDING', '', '2026-03-04 07:23:47.549884+00', NULL, NULL, NULL, ''),
	(2046, 'Achèvement du Temple des Inscriptions (Palenque)', 683, false, NULL, 'Fin de la construction du Temple des Inscriptions à Palenque, abritant le sarcophage de Pakal le Grand et des hiéroglyphes détaillant l''histoire de la dynastie.', 'Les Empires Précolombiens : Des Olmèques à l''Empire Inca (1200 AEC - 1533)', '', 'PENDING', '', '2026-03-04 07:23:47.549884+00', NULL, NULL, NULL, ''),
	(2047, 'Présentation du film "Huit et demi" (8½) de Federico Fellini au Festival de Moscou', 1963, false, NULL, 'Ce film autobiographique et onirique est considéré comme un chef-d''œuvre du cinéma italien. Il explore les thèmes de la crise créative et de la subjectivité.', 'L''histoire du cinéma : Des premiers films muets aux blockbusters numériques (1895 - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.549884+00', NULL, NULL, NULL, ''),
	(2048, 'Première mondiale du film Abyss, intégrant des effets spéciaux aquatiques révolutionnaires', 1989, false, NULL, 'Le film Abyss de James Cameron repousse les limites des effets spéciaux avec des scènes sous-marines photoréalistes. Il utilise des techniques de morphing numérique inédites.', 'L''histoire du cinéma : Des premiers films muets aux blockbusters numériques (1895 - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.549884+00', NULL, NULL, NULL, ''),
	(2049, 'Début du règne de Wang Mang et de la dynastie Xin', 9, false, NULL, 'Wang Mang usurpe le trône des Han et fonde la dynastie Xin, mettant fin temporairement à la dynastie Han occidentale. Il met en œuvre des réformes économiques et sociales controversées qui conduisent à des troubles et à une instabilité.', 'Les dynasties impériales chinoises : De Qin Shi Huang à la chute des Qing', '', 'PENDING', '', '2026-03-04 07:23:47.549884+00', NULL, NULL, NULL, ''),
	(2050, 'Invention de l''imprimerie à caractères mobiles par Bi Sheng', 1040, false, NULL, 'Bi Sheng, un roturier, invente l''imprimerie à caractères mobiles en argile, une innovation majeure pour la diffusion du savoir. Cette invention marque une étape cruciale dans l''histoire de l''imprimerie, bien qu''elle n''ait pas été immédiatement adoptée à grande échelle.', 'Les dynasties impériales chinoises : De Qin Shi Huang à la chute des Qing', '', 'PENDING', '', '2026-03-04 07:23:47.549884+00', NULL, NULL, NULL, ''),
	(2051, 'Fondation de l''Académie de la peinture de la dynastie Song (Hanlin Huayuan)', 984, false, NULL, 'L''Académie de la peinture (Hanlin Huayuan) est fondée, devenant un centre important pour le développement et la promotion des arts visuels. Elle joue un rôle clé dans la définition du style artistique de la dynastie Song.', 'Les dynasties impériales chinoises : De Qin Shi Huang à la chute des Qing', '', 'PENDING', '', '2026-03-04 07:23:47.549884+00', NULL, NULL, NULL, ''),
	(2052, 'Établissement du système d''examen impérial triennal standardisé', 1067, false, NULL, 'Le système d''examen impérial est standardisé, se tenant tous les trois ans, permettant une sélection plus rigoureuse des fonctionnaires. Cela renforce la méritocratie et l''efficacité de l''administration Song.', 'Les dynasties impériales chinoises : De Qin Shi Huang à la chute des Qing', '', 'PENDING', '', '2026-03-04 07:23:47.549884+00', NULL, NULL, NULL, ''),
	(2053, 'Introduction du riz de Champa au Fujian', 1011, false, NULL, 'Le riz de Champa, une variété à maturation rapide, est introduit dans la province du Fujian, augmentant la production agricole. Cette innovation contribue à nourrir une population croissante et soutient l''expansion économique.', 'Les dynasties impériales chinoises : De Qin Shi Huang à la chute des Qing', '', 'PENDING', '', '2026-03-04 07:23:47.549884+00', NULL, NULL, NULL, ''),
	(2054, 'Construction du pont de Luoyang (Quanzhou)', 1059, false, NULL, 'Début de la construction du pont de Luoyang (Quanzhou), un pont de pierre massif qui démontre l''ingénierie avancée de l''époque. Il facilite le commerce et les communications dans la région.', 'Les dynasties impériales chinoises : De Qin Shi Huang à la chute des Qing', '', 'PENDING', '', '2026-03-04 07:23:47.549884+00', NULL, NULL, NULL, ''),
	(2055, 'Nationalisation de la British Overseas Airways Corporation (BOAC)', 1939, false, NULL, 'La BOAC est créée par la loi du Parlement britannique du 24 novembre 1939. Elle fusionne British Airways Ltd et Imperial Airways pour assurer les liaisons aériennes pendant la guerre.', 'L''histoire de l''aéronautique civile : Des premiers vols commerciaux aux avions à réaction (1914 - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.549884+00', NULL, NULL, NULL, ''),
	(2056, 'Baptême d''Olaf Haraldsson : Conversion du futur Saint Olaf au christianisme', 1010, false, NULL, 'Olaf Haraldsson, futur roi de Norvège et saint patron, est baptisé en Normandie. Cet événement marque le début de son engagement envers la christianisation de la Norvège, qu''il poursuivra avec détermination.', 'L''histoire des Vikings : Des raids de Lindisfarne à la colonisation du Vinland (793 - 1066)', '', 'PENDING', '', '2026-03-04 07:23:47.549884+00', NULL, NULL, NULL, ''),
	(2057, 'Construction du pont de Capellades, essentiel pour l''industrie papetière catalane', 1164, false, NULL, 'Le pont de Capellades facilite le transport des matières premières et du papier produit dans la région. Il soutient le développement de l''industrie papetière en Catalogne.', 'L''histoire du papier : Des premiers papyrus égyptiens au papier numérique (3000 AEC - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.549884+00', NULL, NULL, NULL, ''),
	(2058, 'Dépôt du brevet du procédé de photographie argentique par Nicéphore Niépce', 1816, false, NULL, 'Nicéphore Niépce dépose un brevet pour son procédé photographique, marquant une étape clé dans l''invention de la photographie. Il nomme son procédé ''héliographie''.', 'L''histoire du papier : Des premiers papyrus égyptiens au papier numérique (3000 AEC - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.549884+00', NULL, NULL, NULL, ''),
	(2059, 'Sortie du Kindle 2', 2009, false, NULL, 'Amazon commercialise la deuxième génération du Kindle, le Kindle 2, avec un design amélioré et une meilleure qualité d''affichage. Il renforce la position d''Amazon sur le marché des lecteurs électroniques.', 'L''histoire du papier : Des premiers papyrus égyptiens au papier numérique (3000 AEC - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.549884+00', NULL, NULL, NULL, ''),
	(2060, 'Lancement du Kindle DX', 2009, false, NULL, 'Amazon présente le Kindle DX, une version plus grande du Kindle, ciblant les étudiants et les professionnels ayant besoin de lire des documents de grande taille. Il vise à étendre l''utilisation du Kindle au-delà de la lecture de romans.', 'L''histoire du papier : Des premiers papyrus égyptiens au papier numérique (3000 AEC - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.549884+00', NULL, NULL, NULL, ''),
	(2061, 'Disponibilité du Kindle pour iPhone et iPod Touch', 2009, false, NULL, 'Amazon lance une application Kindle pour iPhone et iPod Touch, permettant aux utilisateurs de lire des livres Kindle sur leurs appareils Apple. Cela étend l''accès au contenu Kindle à un public plus large.', 'L''histoire du papier : Des premiers papyrus égyptiens au papier numérique (3000 AEC - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.549884+00', NULL, NULL, NULL, ''),
	(2062, 'Brevet du procédé de photographie couleur soustractive par Louis Ducos du Hauron', 1868, false, NULL, 'Louis Ducos du Hauron dépose un brevet pour un procédé de photographie couleur soustractive. Son procédé utilise trois plaques de verre recouvertes d''émulsions sensibles aux couleurs primaires (cyan, magenta et jaune).', 'L''histoire de la photographie : Des premiers daguerréotypes aux réseaux sociaux', '', 'PENDING', '', '2026-03-04 07:23:47.549884+00', NULL, NULL, NULL, ''),
	(2063, 'Agfa commercialise le film couleur Agfacolor Neu', 1936, false, NULL, 'Agfa commercialise le film couleur Agfacolor Neu, un film couleur révolutionnaire basé sur un procédé de développement chromogène. Ce procédé permet d''obtenir des couleurs plus vives et une meilleure stabilité des images.', 'L''histoire de la photographie : Des premiers daguerréotypes aux réseaux sociaux', '', 'PENDING', '', '2026-03-04 07:23:47.549884+00', NULL, NULL, NULL, ''),
	(2064, 'Publication du roman ''Show Boat'' d''Edna Ferber', 1926, false, NULL, 'Le roman d''Edna Ferber, qui a inspiré la comédie musicale du même nom, est publié. L''œuvre explore la vie sur un bateau de spectacle itinérant sur le fleuve Mississippi.', 'L''histoire du théatre : Des drames grecs aux comédies musicales contemporaines', '', 'PENDING', '', '2026-03-04 07:23:47.549884+00', NULL, NULL, NULL, ''),
	(2065, 'Début de la construction du Colisée (Amphithéâtre Flavien)', 72, false, NULL, 'L''empereur Vespasien initie la construction de l''amphithéâtre Flavien, plus tard connu sous le nom de Colisée, sur le site de l''ancien palais de Néron.', 'Les grandes constructions : Des pyramides d''Égypte aux gratte-ciels contemporains', '', 'PENDING', '', '2026-03-04 07:23:47.561428+00', NULL, NULL, NULL, ''),
	(2066, 'Achèvement des travaux d''agrandissement du Colisée sous Domitien', 90, false, NULL, 'L''empereur Domitien termine les travaux d''agrandissement du Colisée, ajoutant des galeries supérieures et des espaces supplémentaires pour les spectateurs.', 'Les grandes constructions : Des pyramides d''Égypte aux gratte-ciels contemporains', '', 'PENDING', '', '2026-03-04 07:23:47.561428+00', NULL, NULL, NULL, ''),
	(2067, 'Derniers combats de gladiateurs documentés au Colisée', 438, false, NULL, 'L''empereur Valentinien III abolit officiellement les combats de gladiateurs au Colisée, mettant fin à une tradition de plusieurs siècles.', 'Les grandes constructions : Des pyramides d''Égypte aux gratte-ciels contemporains', '', 'PENDING', '', '2026-03-04 07:23:47.561428+00', NULL, NULL, NULL, ''),
	(2068, 'Construction de la colonne de Marc Aurèle commencée à Rome', 176, false, NULL, 'La construction de la colonne commémorative de Marc Aurèle débute à Rome. Elle représente les campagnes militaires de l''empereur contre les Marcomans et les Sarmates, menées pendant la peste antonine.', 'L''histoire des grandes pandémies : De la peste d''Athènes au COVID-19', '', 'PENDING', '', '2026-03-04 07:23:47.561428+00', NULL, NULL, NULL, ''),
	(2069, 'Recrudescence de la peste de Justinien à Constantinople', 549, false, NULL, 'Une nouvelle vague de la peste de Justinien frappe Constantinople, ravivant la crise démographique et économique. Les efforts de reconstruction de Justinien sont à nouveau entravés.', 'L''histoire des grandes pandémies : De la peste d''Athènes au COVID-19', '', 'PENDING', '', '2026-03-04 07:23:47.561428+00', NULL, NULL, NULL, ''),
	(2070, 'Premières observations de la grippe russe à Saint-Pétersbourg', 1889, false, NULL, 'Les premiers cas de la pandémie de grippe russe sont signalés à Saint-Pétersbourg, marquant le début de sa propagation mondiale. La maladie se propage rapidement à travers l''Europe.', 'L''histoire des grandes pandémies : De la peste d''Athènes au COVID-19', '', 'PENDING', '', '2026-03-04 07:23:47.561428+00', NULL, NULL, NULL, ''),
	(2071, 'Apogée du royaume nabatéen de Pétra, plaque tournante du commerce caravanier et de l''encens', 50, false, NULL, 'Pétra, capitale des Nabatéens, atteint son apogée en tant que centre commercial majeur sur la route de l''encens. La ville contrôle les caravanes transportant l''encens, la myrrhe et d''autres produits de luxe entre l''Arabie du Sud et la Méditerranée.', 'L''histoire des routes commerciales : De la route de l''encens à la nouvelle route de la soie (300 AEC - 2010)', '', 'PENDING', '', '2026-03-04 07:23:47.561428+00', NULL, NULL, NULL, ''),
	(2072, 'Fondation du shogunat de Kamakura', 1185, false, NULL, 'Minamoto no Yoritomo établit le shogunat de Kamakura, marquant le début du gouvernement militaire féodal au Japon. Il reçoit le titre de shogun en 1192.', 'L''histoire des samouraïs : De l''émergence des guerriers à la restauration de Meiji', '', 'PENDING', '', '2026-03-04 07:23:47.561428+00', NULL, NULL, NULL, '');


